}

/* ==========================================
   微调补丁：电池图标左移，统一三者间距
   放在 CSS 最末尾
   ========================================== */

/* 桌面 / 默认尺寸：电池整体左移 */
.relink-scope .rs-iphone-mock::before {
  right: 74px !important;
}

.relink-scope .rs-iphone-mock::after {
  right: 71px !important;
}

/* 平板端：同步左移 */
@media (max-width: 768px) {
  .relink-scope .rs-iphone-mock::before {
    right: 68px !important;
  }

  .relink-scope .rs-iphone-mock::after {
    right: 65px !important;
  }
}

/* 手机端：同步左移 */
@media (max-width: 480px) {
  .relink-scope .rs-iphone-mock::before {
    right: 62px !important;
  }

  .relink-scope .rs-iphone-mock::after {
    right: 59px !important;
  }
}

/* 手机屏幕内部可上下滑动：隐藏滚动条 + 移动端惯性滚动 */
.rs-iphone-screen {
  overflow-y: auto !important;
  overflow-x: hidden !important;
  scrollbar-width: none !important;
  -ms-overflow-style: none !important;
  -webkit-overflow-scrolling: touch !important;
  scrollbar-gutter: stable !important;
}

.rs-iphone-screen::-webkit-scrollbar {
  width: 0 !important;
  height: 0 !important;
  display: none !important;
}

/* 避免最后一条通知被底部提示挡住 */
.rs-notifications {
  padding-bottom: 56px !important;
}

/* 成人论坛图片附件：灰色独立外框 */
.rs-forum-attachment {
  width: 100% !important;
  max-width: 100% !important;
  box-sizing: border-box !important;
  margin-top: 8px !important;
  border-radius: 12px !important;
  overflow: hidden !important;
  background: rgba(255, 255, 255, 0.42) !important;
  border: 1px solid rgba(255, 255, 255, 0.42) !important;
}

/* 附件折叠标题：永远在图片上方，不被覆盖 */
.rs-attach-summary {
  position: relative !important;
  z-index: 2 !important;
  list-style: none !important;
  cursor: pointer !important;
  padding: 7px 9px !important;
  display: flex !important;
  align-items: center !important;
  justify-content: space-between !important;
  gap: 8px !important;
  font-size: 12px !important;
  line-height: 1.4 !important;
  color: rgba(45, 45, 50, 0.82) !important;
  background: rgba(255, 255, 255, 0.24) !important;
}

.rs-attach-summary::-webkit-details-marker {
  display: none !important;
}

.rs-attach-summary em {
  flex: 0 0 auto !important;
  font-style: normal !important;
  font-size: 11px !important;
  color: rgba(80, 80, 88, 0.58) !important;
}

/* 展开后的附件区域：负责给图片留边距 */
.rs-attach-body {
  width: 100% !important;
  box-sizing: border-box !important;
  padding: 8px 9px 9px !important;
  display: flex !important;
  flex-direction: column !important;
  align-items: stretch !important;
  gap: 5px !important;
}

/* 兼容旧的 .rs-attach-image 写法 */
.rs-attach-image {
  width: 100% !important;
  max-width: 100% !important;
  box-sizing: border-box !important;
  aspect-ratio: 3 / 4 !important;
  border-radius: 10px !important;
  background:
    linear-gradient(rgba(0, 0, 0, 0.08), rgba(0, 0, 0, 0.18)),
    url("your-image.jpg") center / cover no-repeat;
  box-shadow: 0 6px 14px rgba(0, 0, 0, 0.16) !important;
}

/* 附件图片：适配 <div class="rs-avatar story-image img-FJ-{{编号}}"></div> */
.rs-forum-attachment .rs-avatar.story-image {
  position: relative !important;
  z-index: 1 !important;
  width: 100% !important;
  max-width: 100% !important;
  height: auto !important;
  min-height: 0 !important;
  aspect-ratio: 3 / 4 !important;
  box-sizing: border-box !important;
  display: block !important;
  flex: none !important;
  margin: 0 !important;
  border: none !important;
  border-radius: 10px !important;
  overflow: hidden !important;
  transform: none !important;
  background-size: cover !important;
  background-position: center !important;
  background-repeat: no-repeat !important;
  box-shadow: 0 6px 14px rgba(0, 0, 0, 0.16) !important;
}

/* 覆盖头像原始样式，防止绝对定位、圆形头像、固定尺寸污染附件 */
.rs-forum-attachment .rs-avatar,
.rs-forum-attachment .story-image {
  position: relative !important;
  max-width: 100% !important;
  max-height: none !important;
  border-radius: 10px !important;
}

/* 附件说明文字：始终在图片下方 */
.rs-attach-meta {
  position: relative !important;
  z-index: 2 !important;
  margin-top: 0 !important;
  font-size: 11px !important;
  line-height: 1.4 !important;
  color: rgba(70, 70, 78, 0.56) !important;
}

/* 隐藏页面级滚动条 */
html,
body {
  scrollbar-width: none !important;
  -ms-overflow-style: none !important;
}

html::-webkit-scrollbar,
body::-webkit-scrollbar {
  width: 0 !important;
  height: 0 !important;
  display: none !important;
}

/* 隐藏指定滚动容器滚动条 */
.rs-iphone-screen {
  overflow-y: auto !important;
  overflow-x: hidden !important;
  scrollbar-width: none !important;
  -ms-overflow-style: none !important;
  -webkit-overflow-scrolling: touch !important;
}

.rs-iphone-screen::-webkit-scrollbar {
  width: 0 !important;
  height: 0 !important;
  display: none !important;
}

/* ==========================================
   最终补丁：iPhone 通知区隐藏滚动条 + 边缘渐隐
   放在整份 CSS 最末尾
   ========================================== */

/* 手机屏幕本体：允许滑动，但不显示滚动条、不预留滚动条槽位 */
.relink-scope .rs-iphone-screen {
  overflow-y: auto !important;
  overflow-x: hidden !important;
  scrollbar-width: none !important;
  -ms-overflow-style: none !important;
  -webkit-overflow-scrolling: touch !important;
  scrollbar-gutter: auto !important;
}

/* Chrome / Edge / Safari 隐藏屏幕滚动条 */
.relink-scope .rs-iphone-screen::-webkit-scrollbar {
  width: 0 !important;
  height: 0 !important;
  display: none !important;
  background: transparent !important;
}

/* 真正滚动的是通知列表：这里必须一起隐藏 */
.relink-scope .rs-notifications {
  flex: 1 !important;
  padding-top: 18px !important;
  padding-bottom: 74px !important;

  display: flex !important;
  flex-direction: column !important;
  gap: 12px !important;

  overflow-y: auto !important;
  overflow-x: hidden !important;

  scrollbar-width: none !important;
  -ms-overflow-style: none !important;
  -webkit-overflow-scrolling: touch !important;

  /*
    核心：上下渐隐。
    18px 开始完全显示，底部 52px 前开始渐隐，
    这样通知卡片会更靠近屏幕边缘才消失。
  */
  mask-image: linear-gradient(
    to bottom,
    transparent 0px,
    rgba(0, 0, 0, 0.25) 8px,
    #000 18px,
    #000 calc(100% - 52px),
    rgba(0, 0, 0, 0.25) calc(100% - 24px),
    transparent 100%
  ) !important;

  -webkit-mask-image: linear-gradient(
    to bottom,
    transparent 0px,
    rgba(0, 0, 0, 0.25) 8px,
    #000 18px,
    #000 calc(100% - 52px),
    rgba(0, 0, 0, 0.25) calc(100% - 24px),
    transparent 100%
  ) !important;
}

/* 强制干掉你前面写过的 4px 滚动条 */
.relink-scope .rs-notifications::-webkit-scrollbar {
  width: 0 !important;
  height: 0 !important;
  display: none !important;
  background: transparent !important;
}

.relink-scope .rs-notifications::-webkit-scrollbar-track {
  display: none !important;
  background: transparent !important;
}

.relink-scope .rs-notifications::-webkit-scrollbar-thumb {
  display: none !important;
  background: transparent !important;
}

/* 通知卡片靠近边缘时更自然：不再被硬切 */
.relink-scope .rs-notification-card {
  flex-shrink: 0 !important;
  will-change: transform, opacity !important;
}

/* 底部提示稍微贴底，让通知能滑到更外侧 */
.relink-scope .rs-lockscreen-hint {
  padding: 10px 0 4px !important;
  margin-top: 0 !important;
}

/* 小屏幕：渐隐范围稍微缩小，避免内容被吃太多 */
@media (max-width: 480px) {
  .relink-scope .rs-notifications {
    padding-top: 14px !important;
    padding-bottom: 64px !important;

    mask-image: linear-gradient(
      to bottom,
      transparent 0px,
      rgba(0, 0, 0, 0.3) 6px,
      #000 14px,
      #000 calc(100% - 44px),
      rgba(0, 0, 0, 0.3) calc(100% - 20px),
      transparent 100%
    ) !important;

    -webkit-mask-image: linear-gradient(
      to bottom,
      transparent 0px,
      rgba(0, 0, 0, 0.3) 6px,
      #000 14px,
      #000 calc(100% - 44px),
      rgba(0, 0, 0, 0.3) calc(100% - 20px),
      transparent 100%
    ) !important;
  }
}

/* ==========================================
   最终补丁：移动端 iPhone 拉满宽度 + 通知内容扩展
   放在整份 CSS 最末尾
   ========================================== */

/* 默认：让手机更接近聊天气泡宽度 */
.relink-scope .rs-iphone-mock {
  width: min(100%, 560px) !important;
  max-width: 560px !important;
  aspect-ratio: 9 / 19.5 !important;
  height: auto !important;
  margin: 0 auto 20px !important;
  box-sizing: border-box !important;
}

/* 屏幕内部减少左右浪费，让通知区更宽 */
.relink-scope .rs-iphone-screen {
  padding-left: 16px !important;
  padding-right: 16px !important;
  box-sizing: border-box !important;
}

/* 通知列表尽量吃满屏幕内部宽度 */
.relink-scope .rs-notifications {
  width: 100% !important;
  box-sizing: border-box !important;
  gap: 10px !important;
}

/* 通知卡片拉宽，减少无效留白 */
.relink-scope .rs-notification-card {
