/* ========== 最终修复：移动端电池归位 ========== */
.relink-scope .rs-iphone-mock,
.relink-scope .rs-iphone-screen {
  position: relative !important;
}

.relink-scope .rs-iphone-screen::before {
  top: clamp(14px, 2.8vw, 18px) !important;
  right: clamp(72px, 15vw, 92px) !important;
}

.relink-scope .rs-iphone-screen::after {
  top: clamp(14px, 2.8vw, 18px) !important;
  right: clamp(16px, 3.5vw, 24px) !important;
}

.relink-scope .rs-iphone-mock::before {
  top: clamp(27px, 5.4vw, 35px) !important;
  right: clamp(60px, 12.5vw, 78px) !important;
}

.relink-scope .rs-iphone-mock::after {
  top: clamp(29px, 5.8vw, 37px) !important;
  right: clamp(57px, 12vw, 75px) !important;
}

@media (max-width: 480px) {
  .relink-scope .rs-iphone-screen::before {
    top: 13px !important;
    right: 66px !important;
  }

  .relink-scope .rs-iphone-screen::after {
    top: 13px !important;
    right: 14px !important;
  }

  .relink-scope .rs-iphone-mock::before {
    top: 26px !important;
    right: 52px !important;
  }

  .relink-scope .rs-iphone-mock::after {
    top: 28px !important;
    right: 49px !important;
  }
}

/* ========== 仅移动端修复：电池微调，PC端不改 ========== */
@media (max-width: 768px) {
  .rs-iphone-screen,
  .relink-scope .rs-iphone-screen,
  .rs-iphone-mock,
  .relink-scope .rs-iphone-mock {
    position: relative !important;
  }

  /* 信号：保持移动端原位置 */
  .rs-iphone-screen::before,
  .relink-scope .rs-iphone-screen::before {
    top: 13px !important;
    right: 68px !important;
  }

  /* 80%文字：保持移动端原位置 */
  .rs-iphone-screen::after,
  .relink-scope .rs-iphone-screen::after {
    top: 13px !important;
    right: 14px !important;
  }

  /* 电池主体：只在移动端往左一点 */
  .rs-iphone-mock::before,
  .relink-scope .rs-iphone-mock::before {
    top: 22px !important;
    right: 50px !important;
  }

  /* 电池凸起：跟着主体左移 */
  .rs-iphone-mock::after,
  .relink-scope .rs-iphone-mock::after {
    top: 24px !important;
    right: 47px !important;
  }
}

@media (max-width: 480px) {
  /* 小屏手机再单独微调 */
  .rs-iphone-screen::before,
  .relink-scope .rs-iphone-screen::before {
    top: 12px !important;
    right: 64px !important;
  }

  .rs-iphone-screen::after,
  .relink-scope .rs-iphone-screen::after {
    top: 12px !important;
    right: 13px !important;
  }

  .rs-iphone-mock::before,
  .relink-scope .rs-iphone-mock::before {
    top: 20px !important;
    right: 45px !important;
  }

  .rs-iphone-mock::after,
  .relink-scope .rs-iphone-mock::after {
    top: 22px !important;
    right: 42px !important;
  }
}

/* ========== 移动端微调：80% 电量文字右移一点 ========== */
@media (max-width: 768px) {
  .rs-iphone-screen::after,
  .relink-scope .rs-iphone-screen::after {
    right: 8px !important;
  }
}

@media (max-width: 480px) {
  .rs-iphone-screen::after,
  .relink-scope .rs-iphone-screen::after {
    right: 7px !important;
  }
}

/* =========================================================
   Relink A→B 兼容补丁：短类名模板完整继承原美化
   放在整份 CSS 最末尾
   ========================================================= */

/* ---------- 0. B模板根变量 ---------- */
.rls,
.rls *,
.pif,
.pif *,
.wbt,
.wbt *,
.ipm,
.ipm *,
.chb,
.chb * {
  --rs-primary:#ff7a9c;
  --rs-accent:#c8a2c8;
  --rs-sakura:#ffb7c5;
  --rs-text:#4a2c3d;
  --rs-text-sub:#8a6478;
  --rs-text-light:#a88497;
  --rs-bg-card:rgba(255,250,252,0.96);
  --rs-bg-soft:rgba(255,240,245,0.85);
  --rs-bg-inner:rgba(255,255,255,0.7);
  --rs-border:rgba(255,154,178,0.32);
  --rs-border-soft:rgba(200,162,200,0.22);
  --rs-shadow:0 10px 36px rgba(255,122,156,0.18),0 0 24px rgba(255,183,197,0.15);
  --rs-glow:0 0 16px rgba(255,183,197,0.45);
  --rs-radius:18px;
  --rs-radius-sm:10px;
  --rs-lv1:#a8d8b9;
  --rs-lv2:#ffd97d;
  --rs-lv3:#ffa07a;
  --rs-lv4:#ff6b8a;
  --rs-lv5:#c44569;
  box-sizing:border-box!important;
  font-family:"Noto Serif JP","PingFang SC","Microsoft YaHei",system-ui,-apple-system,sans-serif!important;
}

/* ---------- 1. B模板外壳继承 relink-scope ---------- */
.rls {
  color:var(--rs-text)!important;
  max-width:880px!important;
  margin:18px auto!important;
  padding:22px!important;
  background:
    linear-gradient(135deg,rgba(255,245,247,0.92),rgba(245,232,245,0.88)),
    radial-gradient(ellipse at top right,rgba(255,183,197,0.18),transparent 60%)!important;
  backdrop-filter:blur(14px)!important;
  -webkit-backdrop-filter:blur(14px)!important;
  border:1px solid var(--rs-border)!important;
  border-radius:24px!important;
  box-shadow:var(--rs-shadow)!important;
  position:relative!important;
  overflow:hidden!important;
  animation:rs-fade-in 0.8s ease both!important;
}

.rls::before {
  content:""!important;
  position:absolute!important;
  top:0!important;
  left:0!important;
  right:0!important;
  height:3px!important;
  background:linear-gradient(90deg,var(--rs-primary),var(--rs-sakura),var(--rs-accent),var(--rs-primary))!important;
  background-size:200% 100%!important;
  animation:rs-flow 4s linear infinite!important;
}

/* ---------- 2. 场景头部 ---------- */
.rls .tgs {
  display:grid!important;
  grid-template-columns:repeat(4,1fr)!important;
  gap:10px!important;
  margin-bottom:10px!important;
}

.rls .tag {
  display:flex!important;
  align-items:center!important;
  gap:6px!important;
  padding:8px 12px!important;
  background:linear-gradient(135deg,rgba(255,255,255,0.85),rgba(255,232,238,0.7))!important;
  border:1px solid var(--rs-border)!important;
  border-radius:12px!important;
  font-size:13px!important;
  color:var(--rs-text)!important;
  box-shadow:0 2px 6px rgba(255,122,156,0.08)!important;
  transition:transform 0.25s ease,box-shadow 0.25s ease!important;
}

.rls .tag:hover {
  transform:translateY(-2px)!important;
  box-shadow:0 4px 12px rgba(255,122,156,0.2)!important;
}

.rls .tag b {
  color:var(--rs-primary)!important;
  font-weight:700!important;
}

.rls .ico {
  font-size:14px!important;
  filter:drop-shadow(0 0 4px rgba(255,183,197,0.6))!important;
}

.rls .scd {
  padding:10px 14px!important;
  background:rgba(255,183,197,0.12)!important;
  border-left:3px solid var(--rs-primary)!important;
  border-radius:0 10px 10px 0!important;
  font-size:14px!important;
  color:var(--rs-text)!important;
}

.rls .scd b {
  color:var(--rs-primary)!important;
  font-weight:700!important;
}

/* ---------- 3. 状态面板 ---------- */
.rls .stp {
  display:grid!important;
  grid-template-columns:260px 1fr!important;
  grid-template-areas:"left right" "bottom bottom"!important;
  gap:18px!important;
  margin-bottom:18px!important;
}

.rls .pnl {
  grid-area:left!important;
  padding:16px!important;
  display:flex!important;
  flex-direction:column!important;
  align-items:stretch!important;
  background:linear-gradient(160deg,rgba(255,250,252,0.95),rgba(255,232,238,0.85))!important;
  border:1px solid var(--rs-border)!important;
  border-radius:var(--rs-radius)!important;
  box-shadow:var(--rs-shadow)!important;
  text-align:center!important;
}

.rls .pnr {
  grid-area:right!important;
  padding:18px!important;
  background:var(--rs-bg-card)!important;
  border:1px solid var(--rs-border)!important;
  border-radius:var(--rs-radius)!important;
  box-shadow:var(--rs-shadow)!important;
}

/* ---------- 4. 立绘 ---------- */
.rls .avb {
  position:relative!important;
  width:100%!important;
  height:auto!important;
  aspect-ratio:2/3!important;
  max-width:none!important;
  margin:0 0 14px 0!important;
  border-radius:12px!important;
  overflow:hidden!important;
  display:block!important;
  font-size:0!important;
  line-height:0!important;
  box-shadow:0 12px 28px rgba(255,122,156,0.3),0 0 24px rgba(255,183,197,0.4)!important;
  animation:rs-glow-pulse 3.5s ease infinite!important;
}

.rls .avb::after {
  content:""!important;
  position:absolute!important;
  inset:0!important;
  background:linear-gradient(180deg,transparent 65%,rgba(74,44,61,0.35))!important;
  pointer-events:none!important;
}

.rls .avb .ava,
.rls .avb .si,
.rls .pnl > .ava,
.rls .pnl > .si[class*="img-FZ-"] {
  position:absolute!important;
  inset:0!important;
  width:100%!important;
  height:100%!important;
  margin:0!important;
  padding:0!important;
  display:block!important;
  background-size:cover!important;
  background-position:center center!important;
  background-repeat:no-repeat!important;
  border-radius:0!important;
  box-shadow:none!important;
  vertical-align:top!important;
}

/* ---------- 5. 左栏文字 ---------- */
.rls .nam {
  font-size:18px!important;
  font-weight:700!important;
  color:var(--rs-text)!important;
  margin-bottom:6px!important;
  letter-spacing:1px!important;
  text-shadow:0 1px 2px rgba(255,255,255,0.6)!important;
}

.rls .age {
  font-size:13px!important;
  color:var(--rs-primary)!important;
  font-weight:600!important;
  margin-left:4px!important;
}

.rls .idn {
  display:inline-block!important;
  padding:4px 12px!important;
  margin-bottom:10px!important;
  background:linear-gradient(135deg,var(--rs-primary),var(--rs-accent))!important;
  color:#fff!important;
  font-size:12px!important;
  border-radius:14px!important;
  font-weight:600!important;
  letter-spacing:0.5px!important;
  box-shadow:0 3px 10px rgba(255,122,156,0.35)!important;
}

.rls .mod,
.rls .pos {
  font-size:12.5px!important;
  color:var(--rs-text-sub)!important;
  padding:6px 10px!important;
  margin-top:8px!important;
  background:rgba(255,255,255,0.6)!important;
  border-radius:10px!important;
  border:1px solid var(--rs-border-soft)!important;
  text-align:left!important;
  line-height:1.6!important;
}

.rls .mod span,
.rls .pos span {
  color:var(--rs-text)!important;
  font-weight:600!important;
}

/* ---------- 6. 引用框 ---------- */
.rls .qtb {
  margin-top:14px!important;
  padding:14px 16px 14px 40px!important;
  position:relative!important;
  background:linear-gradient(135deg,rgba(255,245,247,0.9),rgba(245,232,245,0.85))!important;
  border:1px solid var(--rs-border)!important;
  border-radius:12px!important;
  border-left:3px solid var(--rs-primary)!important;
  box-shadow:0 4px 14px rgba(255,122,156,0.12)!important;
  animation:rs-fade-in 1s ease 0.3s both!important;
}

.rls .qti {
  position:absolute!important;
  left:10px!important;
  top:6px!important;
  font-size:36px!important;
  line-height:1!important;
  color:var(--rs-primary)!important;
  font-family:Georgia,serif!important;
  opacity:0.45!important;
}

.rls .qtt {
  font-size:13.5px!important;
  color:var(--rs-text)!important;
  line-height:1.85!important;
  font-style:italic!important;
  letter-spacing:0.3px!important;
}

/* ---------- 7. 进度条 ---------- */
.rls .brg {
  margin-bottom:16px!important;
}

.rls .pgc {
  margin-bottom:12px!important;
}

.rls .pgc:last-child {
  margin-bottom:0!important;
}

.rls .pgl {
  display:flex!important;
  justify-content:space-between!important;
  align-items:center!important;
  font-size:13px!important;
  margin-bottom:6px!important;
}

.rls .lbt {
  color:var(--rs-text)!important;
  font-weight:600!important;
}

.rls .hlt {
  color:var(--rs-primary)!important;
  font-weight:700!important;
  font-size:12px!important;
  padding:1px 8px!important;
  background:rgba(255,122,156,0.12)!important;
  border-radius:8px!important;
  margin-left:4px!important;
}

.rls .lbv {
  color:var(--rs-text-sub)!important;
  font-weight:700!important;
  font-size:12.5px!important;
  font-variant-numeric:tabular-nums!important;
}

.rls .pgt {
  height:12px!important;
  border-radius:8px!important;
  background:rgba(255,183,197,0.18)!important;
  overflow:hidden!important;
  box-shadow:inset 0 2px 4px rgba(196,69,105,0.12)!important;
  position:relative!important;
}

.rls .pgf,
.rls .pgfd,
.rls .pgfl,
.rls .pgfp {
  height:100%!important;
  border-radius:8px!important;
  position:relative!important;
  background-image:none!important;
  background-size:auto!important;
  background-blend-mode:normal!important;
  animation:rs-fill-grow 1.4s cubic-bezier(0.34,1.2,0.64,1) both!important;
}

.rls .pgf {
  background:linear-gradient(135deg,var(--rs-primary),var(--rs-accent))!important;
  box-shadow:0 0 12px rgba(255,122,156,0.5)!important;
}

.rls .pgfd {
  background:linear-gradient(135deg,#c44569,#ff6b8a)!important;
  box-shadow:0 0 14px rgba(196,69,105,0.55)!important;
}

.rls .pgfl {
  background:linear-gradient(135deg,#ff5582,#ffb7c5)!important;
  box-shadow:0 0 14px rgba(255,107,138,0.6)!important;
}

.rls .pgfp {
  background:linear-gradient(135deg,#e85a7a,#c8a2c8)!important;
  box-shadow:0 0 14px rgba(232,90,122,0.5)!important;
}

/* ---------- 8. 开发度网格 ---------- */
.rls .dvg {
  display:grid!important;
  grid-template-columns:repeat(2,1fr)!important;
  gap:10px!important;
  margin-bottom:14px!important;
}

.rls .dvi {
  padding:10px 12px!important;
  background:linear-gradient(135deg,rgba(255,255,255,0.85),rgba(255,240,245,0.7))!important;
  border:1px solid var(--rs-border-soft)!important;
  border-radius:12px!important;
  transition:transform 0.25s ease,box-shadow 0.25s ease,border-color 0.25s ease!important;
}

.rls .dvi:hover {
  transform:translateY(-2px)!important;
  box-shadow:0 6px 16px rgba(255,122,156,0.18)!important;
  border-color:var(--rs-primary)!important;
}

.rls .dvt {
  font-size:13px!important;
  font-weight:700!important;
  color:var(--rs-primary)!important;
  margin-bottom:4px!important;
}

.rls .dvv {
  font-size:11.5px!important;
  color:var(--rs-text-sub)!important;
  font-weight:600!important;
  margin-bottom:4px!important;
  font-variant-numeric:tabular-nums!important;
}

.rls .dvd {
  font-size:11.5px!important;
  color:var(--rs-text)!important;
  line-height:1.55!important;
  padding-top:4px!important;
  border-top:1px dashed var(--rs-border-soft)!important;
}

/* ---------- 9. 腔内情况 ---------- */
.rls .bqb {
  margin-bottom:12px!important;
  padding:12px!important;
  background:linear-gradient(135deg,rgba(255,232,238,0.6),rgba(245,220,235,0.5))!important;
  border:1px solid var(--rs-border)!important;
  border-radius:12px!important;
}

.rls .bqt {
  font-size:13px!important;
  font-weight:700!important;
  color:var(--rs-primary)!important;
  margin-bottom:8px!important;
  display:flex!important;
  align-items:center!important;
  gap:4px!important;
}

.rls .bqb .si {
  display:block!important;
  margin:8px auto!important;
  border-radius:10px!important;
  max-width:100%!important;
  box-shadow:0 4px 14px rgba(255,122,156,0.2)!important;
}

.rls .bqd {
  font-size:12.5px!important;
  color:var(--rs-text)!important;
  line-height:1.7!important;
  margin-bottom:6px!important;
}

.rls .bqm {
  font-size:12px!important;
  color:var(--rs-text-sub)!important;
  padding-top:6px!important;
  border-top:1px dashed var(--rs-border-soft)!important;
}

/* ---------- 10. 男主信息 ---------- */
.pif {
  width:min(100%,960px)!important;
  max-width:960px!important;
  margin:18px auto!important;
  padding:16px 20px!important;
  background:linear-gradient(135deg,rgba(240,248,255,0.96),rgba(230,240,250,0.92))!important;
  border:1px solid rgba(100,149,237,0.32)!important;
  border-radius:var(--rs-radius)!important;
  box-shadow:0 8px 24px rgba(100,149,237,0.16),inset 0 1px 0 rgba(255,255,255,0.55)!important;
  overflow:hidden!important;
  position:relative!important;
  color:var(--rs-text)!important;
}

.pif::before {
  content:""!important;
  position:absolute!important;
  top:0!important;
  left:18px!important;
  right:18px!important;
  height:2px!important;
  background:linear-gradient(90deg,transparent,rgba(100,149,237,0.85),rgba(173,216,230,0.9),transparent)!important;
}

.plh {
  display:block!important;
  font-size:15px!important;
  font-weight:700!important;
  color:#4169e1!important;
  margin-bottom:12px!important;
  padding-bottom:8px!important;
  border-bottom:2px solid rgba(100,149,237,0.28)!important;
  letter-spacing:1px!important;
  cursor:pointer!important;
  list-style:none!important;
}

.plh::-webkit-details-marker {
  display:none!important;
}

.plg {
  display:grid!important;
