}

.inv {
  font-size:13px!important;
  color:var(--rs-text)!important;
  line-height:1.65!important;
}

.inv b {
  color:#4169e1!important;
}

/* ---------- 11. 功能记录区 ---------- */
.wbt {
  width:min(100%,960px)!important;
  max-width:960px!important;
  margin:18px auto!important;
  padding:16px 20px!important;
  background:linear-gradient(135deg,rgba(255,250,240,0.96),rgba(255,243,224,0.92))!important;
  border:1px solid rgba(218,165,32,0.32)!important;
  border-radius:var(--rs-radius)!important;
  box-shadow:0 8px 24px rgba(218,165,32,0.16),inset 0 1px 0 rgba(255,255,255,0.55)!important;
  overflow:hidden!important;
  position:relative!important;
}

.wbt::before {
  content:""!important;
  position:absolute!important;
  top:0!important;
  left:18px!important;
  right:18px!important;
  height:2px!important;
  background:linear-gradient(90deg,transparent,rgba(218,165,32,0.85),rgba(255,215,128,0.9),transparent)!important;
}

.wbh {
  display:block!important;
  font-size:15px!important;
  font-weight:700!important;
  color:#daa520!important;
  margin-bottom:12px!important;
  padding-bottom:8px!important;
  border-bottom:2px solid rgba(218,165,32,0.28)!important;
  letter-spacing:1px!important;
  cursor:pointer!important;
  list-style:none!important;
}

.wbh::-webkit-details-marker {
  display:none!important;
}

.wbl {
  display:flex!important;
