.disc-cover { width: 100%; height: 100%; border-radius: 50%; object-fit: cover; display: block; }
.disc-hole { position: absolute; top: 50%; left: 50%; width: 14px; height: 14px; transform: translate(-50%,-50%); border-radius: 50%; background: radial-gradient(circle,#1a1a2e 40%,#2a1a2e 70%,rgba(255,107,157,0.15) 100%); border: 1.5px solid rgba(255,255,255,0.15); box-shadow: inset 0 0 4px rgba(0,0,0,0.6); z-index: 2; }
.disc-groove { position: absolute; top: 50%; left: 50%; border-radius: 50%; border: 0.5px solid rgba(255,255,255,0.06); transform: translate(-50%,-50%); pointer-events: none; }
.disc-groove.g1{width:70%;height:70%} .disc-groove.g2{width:50%;height:50%} .disc-groove.g3{width:85%;height:85%}
.disc-pause-overlay { position: absolute; top: 50%; left: 50%; transform: translate(-50%,-50%); width: 100%; height: 100%; border-radius: 50%; background: rgba(0,0,0,0.45); display: flex; align-items: center; justify-content: center; opacity: 0; transition: opacity 0.3s ease; z-index: 3; }
#bgmToggle:not(.playing) .disc-pause-overlay { opacity: 1; }
#bgmToggle.playing .disc-pause-overlay { opacity: 0; }
.pause-icon { display: flex; gap: 4px; }
.pause-icon span { display: block; width: 4px; height: 16px; background: rgba(255,255,255,0.85); border-radius: 2px; }

/* ========== GAL顶部功能按钮 ========== */
.top-btn { position: absolute; top: 20px; width: 110px; padding: 8px 0; background: rgba(26, 21, 32, 0.8); border: 1px solid rgba(255,107,157,0.4); color: #f0f0f0; font-size: 0.9rem; border-radius: 4px; box-shadow: 0 2px 5px rgba(0,0,0,0.5); transition: all 0.2s ease; cursor: pointer; text-align: center; pointer-events: auto; touch-action: manipulation; z-index: 200; font-weight: bold; }
.top-btn:hover { background: rgba(255,107,157,0.3); transform: translateY(-2px); }
#mute-btn { left: 20px; }
#history-btn { left: 140px; }
#skip-opening-btn, #restart-btn { left: 260px; }
#view-cg-btn { right: 20px; }

/* ========== GAL 对话框 ========== */
.gal-dialog-box { position: fixed; bottom: 40px; left: 50%; transform: translateX(-50%); width: min(1000px,94vw); z-index: 40; opacity: 0; transition: opacity 0.6s ease; pointer-events: none; }
.gal-dialog-box.show { opacity: 1; }
.gal-dialog-inner { background: linear-gradient(180deg,rgba(10,5,20,0.65) 0%,rgba(20,10,35,0.75) 100%); border: 1.5px solid rgba(255,107,157,0.35); border-radius: 8px; padding: 0; box-shadow: 0 8px 50px rgba(0,0,0,0.7),inset 0 1px 0 rgba(255,255,255,0.05); position: relative; overflow: visible; }
.gal-dialog-inner::before { content: ''''; position: absolute; top: 0; left: 0; right: 0; height: 1px; background: linear-gradient(90deg,transparent,rgba(255,107,157,0.5),transparent); }
.gal-dialog-name { position: absolute; top: -20px; left: 32px; background: linear-gradient(135deg,var(--color-primary),#e84393); color: #fff; padding: 6px 28px; font-size: 16px; font-weight: bold; border-radius: 6px 6px 0 0; letter-spacing: 2px; box-shadow: 0 -2px 15px rgba(255,107,157,0.4); white-space: nowrap; }
.gal-dialog-text { padding: 36px 36px 28px 36px; font-size: 19px; line-height: 1.8; color: #f0e6f6; letter-spacing: 1px; min-height: 160px; word-break: break-all; overflow-wrap: break-word; }
.gal-dialog-text .char { opacity: 0; display: inline; transition: opacity 0.05s ease; }
.gal-dialog-indicator { position: absolute; bottom: 12px; right: 24px; width: 0; height: 0; border-left: 8px solid transparent; border-right: 8px solid transparent; border-top: 10px solid rgba(255,107,157,0.8); animation: indicatorBounce 1s ease-in-out infinite; display: none; }
@keyframes indicatorBounce { 0%,100%{transform:translateY(0)} 50%{transform:translateY(5px)} }

/* ========== GAL 选项容器 ========== */
.gal-options-container { position: absolute; top: 45%; left: 50%; transform: translate(-50%, -50%); z-index: 50; display: flex; flex-direction: column; gap: 16px; width: min(600px, 85vw); opacity: 0; pointer-events: none; transition: opacity 0.4s ease; }
.gal-options-container.show { opacity: 1; pointer-events: auto; }
.gal-option-btn { background: rgba(20, 10, 35, 0.92); border: 1.5px solid rgba(255,107,157,0.5); color: #fff; padding: 18px 24px; font-size: 18px; border-radius: 8px; cursor: pointer; transition: all 0.2s ease; box-shadow: 0 4px 20px rgba(0,0,0,0.6); text-align: center; letter-spacing: 1px; font-family: inherit; }
.gal-option-btn:hover { background: rgba(50, 25, 70, 0.95); border-color: var(--color-primary); transform: translateY(-2px); box-shadow: 0 6px 25px rgba(255,107,157,0.4); }
.gal-option-btn:active { background: rgba(70, 35, 90, 0.98); transform: translateY(0); box-shadow: 0 2px 10px rgba(255,107,157,0.4); }

/* ========== 历史记录弹窗 ========== */
.history-overlay { position: fixed; top: 0; left: 0; width: 100%; height: 100%; background: rgba(0,0,0,0.85); z-index: 300; display: flex; align-items: center; justify-content: center; opacity: 0; visibility: hidden; transition: opacity 0.3s; backdrop-filter: blur(4px); }
.history-overlay.show { opacity: 1; visibility: visible; }
.history-panel { width: min(800px, 92vw); height: 75vh; background: linear-gradient(180deg,rgba(18,10,28,0.97) 0%,rgba(28,16,40,0.98) 100%); border: 1.5px solid rgba(255,107,157,0.3); border-radius: 12px; display: flex; flex-direction: column; overflow: hidden; box-shadow: 0 10px 50px rgba(0,0,0,0.8); }
.history-header { display: flex; justify-content: space-between; align-items: center; padding: 16px 24px; border-bottom: 1px solid rgba(255,107,157,0.2); font-size: 18px; color: var(--color-accent); font-weight: bold; letter-spacing: 2px; }
.history-close-btn { background: none; border: none; color: #fff; font-size: 24px; cursor: pointer; line-height: 1; transition: color 0.2s; }
.history-close-btn:hover { color: var(--color-primary); }
.history-body { flex: 1; overflow-y: auto; padding: 20px 24px; display: flex; flex-direction: column; gap: 16px; scrollbar-width: thin; scrollbar-color: rgba(255,107,157,0.3) transparent; -webkit-overflow-scrolling: touch; overscroll-behavior: contain; }
.history-body::-webkit-scrollbar { width: 6px; }
.history-body::-webkit-scrollbar-track { background: transparent; }
.history-body::-webkit-scrollbar-thumb { background: rgba(255,107,157,0.3); border-radius: 3px; }
.history-item { border-bottom: 1px solid rgba(255,255,255,0.05); padding-bottom: 12px; }
.history-name { color: var(--color-primary); font-weight: bold; font-size: 14px; margin-bottom: 6px; letter-spacing: 1px; }
.history-text { color: #f0e6f6; font-size: 15px; line-height: 1.7; }

/* ========== 结束复制弹窗 ========== */
.end-copy-overlay { position: fixed; top: 0; left: 0; width: 100%; height: 100%; background: rgba(0,0,0,0.8); z-index: 400; display: flex; align-items: center; justify-content: center; opacity: 0; visibility: hidden; transition: opacity 0.3s; backdrop-filter: blur(6px); }
.end-copy-overlay.show { opacity: 1; visibility: visible; }
.end-copy-box { background: linear-gradient(180deg, rgba(28,16,40,0.98), rgba(18,10,28,0.99)); border: 1.5px solid rgba(255,107,157,0.35); border-radius: 12px; padding: 36px; text-align: center; width: min(420px, 88vw); box-shadow: 0 10px 50px rgba(0,0,0,0.8); }
.end-copy-title { font-size: 22px; color: var(--color-accent); font-weight: bold; margin-bottom: 12px; letter-spacing: 2px; }
.end-copy-desc { font-size: 15px; color: rgba(255,255,255,0.6); margin-bottom: 28px; line-height: 1.6; }


/* 图鉴 */
.gallery-overlay {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: rgba(0,0,0,0.85);
  z-index: 200;
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0;
  visibility: hidden;

  /* 关键：关闭状态和淡出期间不再接收点击 */
  pointer-events: none;

  transition: opacity 0.4s ease, visibility 0s 0.4s;
  backdrop-filter: blur(6px);
}

.gallery-overlay.show {
  opacity: 1;
  visibility: visible;

  /* 只有真正显示时才允许点击 */
  pointer-events: auto;

  transition: opacity 0.4s ease, visibility 0s 0s;
}
.gallery-panel { position: relative; width: min(960px,92vw); height: min(85vh,800px); background: linear-gradient(180deg,rgba(18,10,28,0.97) 0%,rgba(28,16,40,0.98) 100%); border: 1.5px solid rgba(255,107,157,0.3); border-radius: 12px; box-shadow: 0 8px 60px rgba(0,0,0,0.7),0 0 40px rgba(255,107,157,0.1); display: flex; flex-direction: column; overflow: hidden; }
.gallery-header { display: flex; align-items: center; justify-content: space-between; padding: 16px 24px; border-bottom: 1px solid rgba(255,107,157,0.2); flex-shrink: 0; }
.gallery-header-title { font-size: 20px; font-weight: bold; color: var(--color-accent); letter-spacing: 2px; }
.gallery-close-btn { width: 36px; height: 36px; border: 1.5px solid rgba(255,255,255,0.25); border-radius: 50%; background: rgba(255,255,255,0.05); color: #fff; font-size: 18px; cursor: pointer; display: flex; align-items: center; justify-content: center; transition: all 0.25s ease; line-height: 1; }
.gallery-close-btn:hover { background: rgba(255,107,157,0.3); border-color: var(--color-primary); transform: rotate(90deg); }
.gallery-body { flex: 1; overflow-y: auto; overflow-x: hidden; padding: 20px 24px 24px 24px; scrollbar-width: thin; scrollbar-color: rgba(255,107,157,0.3) transparent; -webkit-overflow-scrolling: touch; overscroll-behavior: contain; }
.gallery-body::-webkit-scrollbar{width:6px} .gallery-body::-webkit-scrollbar-track{background:transparent} .gallery-body::-webkit-scrollbar-thumb{background:rgba(255,107,157,0.3);border-radius:3px}
.gallery-category{margin-bottom:28px} .gallery-category:last-child{margin-bottom:0}
.gallery-category-title { font-size: 15px; font-weight: bold; color: var(--color-primary); letter-spacing: 2px; margin-bottom: 14px; padding-bottom: 8px; border-bottom: 1px solid rgba(255,107,157,0.15); display: flex; align-items: center; gap: 8px; }
.gallery-category-title::before { content: ''''; display: inline-block; width: 3px; height: 16px; background: var(--color-primary); border-radius: 2px; }
.gallery-grid { display: grid; grid-template-columns: repeat(2,1fr); gap: 12px; }
.gallery-item { position: relative; border-radius: 8px; overflow: hidden; cursor: pointer; aspect-ratio: 3/4; background: rgba(255,255,255,0.03); border: 1px solid rgba(255,255,255,0.08); transition: all 0.3s ease; }
.gallery-item:hover { border-color: rgba(255,107,157,0.4); transform: translateY(-2px); box-shadow: 0 6px 24px rgba(255,107,157,0.15); }
.gallery-item img { width: 100%; height: 100%; object-fit: cover; display: block; transition: transform 0.4s ease; }
.gallery-item:hover img { transform: scale(1.05); }
.gallery-item-placeholder { position: relative; border-radius: 8px; overflow: hidden; aspect-ratio: 3/4; background: linear-gradient(135deg,rgba(255,107,157,0.08) 0%,rgba(255,194,209,0.05) 100%); border: 1.5px dashed rgba(255,107,157,0.35); display: flex; align-items: center; justify-content: center; text-align: center; padding: 16px; }
.placeholder-text { color: var(--color-accent); font-size: 14px; line-height: 1.7; letter-spacing: 1px; }
.placeholder-text .highlight { color: var(--color-primary); font-weight: bold; font-size: 22px; display: block; margin-bottom: 6px; }
.gallery-lightbox { position: fixed; top: 0; left: 0; width: 100%; height: 100%; background: rgba(0,0,0,0.92); z-index: 600; display: flex; align-items: center; justify-content: center; opacity: 0; visibility: hidden; transition: opacity 0.35s ease, visibility 0s 0.35s; cursor: pointer; }
.gallery-lightbox.show { opacity: 1; visibility: visible; transition: opacity 0.35s ease, visibility 0s 0s; }
.gallery-lightbox img { max-width: 92vw; max-height: 90vh; object-fit: contain; border-radius: 6px; box-shadow: 0 8px 40px rgba(0,0,0,0.6); transform: scale(0.9); transition: transform 0.35s ease; }
.gallery-lightbox.show img { transform: scale(1); }
.lightbox-hint { position: absolute; bottom: 24px; left: 50%; transform: translateX(-50%); color: rgba(255,255,255,0.5); font-size: 13px; letter-spacing: 1px; pointer-events: none; }
.lightbox-close-btn { position: absolute; top: 20px; right: 20px; width: 40px; height: 40px; background: rgba(0,0,0,0.5); border: 1px solid rgba(255,255,255,0.3); color: #fff; font-size: 24px; border-radius: 50%; cursor: pointer; z-index: 601; display: flex; align-items: center; justify-content: center; transition: background 0.3s; }
.lightbox-close-btn:hover { background: rgba(255,107,157,0.5); }

/* ========== 设置弹窗 ========== */
.setup-overlay { position: fixed; top: 0; left: 0; width: 100%; height: 100%; background: rgba(0,0,0,0.85); z-index: 200; display: flex; align-items: center; justify-content: center; opacity: 0; visibility: hidden; transition: opacity 0.4s ease, visibility 0s 0.4s; backdrop-filter: blur(6px); }
.setup-overlay.show { opacity: 1; visibility: visible; transition: opacity 0.4s ease, visibility 0s 0s; }
.setup-panel { position: relative; width: min(720px,92vw); max-height: min(88vh,800px); background: linear-gradient(180deg,rgba(18,10,28,0.97) 0%,rgba(28,16,40,0.98) 100%); border: 1.5px solid rgba(255,107,157,0.3); border-radius: 12px; box-shadow: 0 8px 60px rgba(0,0,0,0.7),0 0 40px rgba(255,107,157,0.1); display: flex; flex-direction: column; overflow: hidden; }
.setup-header { display: flex; align-items: center; justify-content: space-between; padding: 16px 24px; border-bottom: 1px solid rgba(255,107,157,0.2); flex-shrink: 0; }
.setup-header-title { font-size: 20px; font-weight: bold; color: var(--color-accent); letter-spacing: 2px; }
.setup-header-step { font-size: 13px; color: rgba(255,255,255,0.4); letter-spacing: 1px; }
.setup-body { flex: 1; overflow-y: auto; overflow-x: hidden; padding: 28px 32px 24px 32px; scrollbar-width: thin; scrollbar-color: rgba(255,107,157,0.3) transparent; }
.setup-body::-webkit-scrollbar{width:6px} .setup-body::-webkit-scrollbar-track{background:transparent} .setup-body::-webkit-scrollbar-thumb{background:rgba(255,107,157,0.3);border-radius:3px}
.setup-footer { display: flex; align-items: center; justify-content: flex-end; gap: 12px; padding: 16px 24px; border-top: 1px solid rgba(255,107,157,0.15); flex-shrink: 0; }

.setup-step { display: none; }
.setup-step.active { display: block; animation: setupFadeIn 0.4s ease; }
@keyframes setupFadeIn { from{opacity:0;transform:translateY(10px)} to{opacity:1;transform:translateY(0)} }

.setup-name-label { font-size: 16px; color: var(--text-secondary); margin-bottom: 16px; letter-spacing: 1px; }
.setup-name-input { width: 100%; padding: 14px 18px; font-size: 18px; background: rgba(255,255,255,0.06); border: 1.5px solid rgba(255,107,157,0.3); border-radius: 8px; color: #fff; font-family: inherit; transition: all 0.3s ease; letter-spacing: 1px; }
.setup-name-input::placeholder { color: rgba(255,255,255,0.25); font-style: italic; }
.setup-name-input:focus { border-color: var(--color-primary); background: rgba(255,255,255,0.1); box-shadow: 0 0 20px rgba(255,107,157,0.15); }

.mode-select-title { font-size: 16px; color: var(--text-secondary); margin-bottom: 20px; letter-spacing: 1px; text-align: center; }
.mode-cards { display: grid; grid-template-columns: 1fr 1fr; gap: 20px; }
.mode-card { display: flex; flex-direction: column; align-items: center; cursor: pointer; transition: transform 0.3s ease; }
.mode-card:hover { transform: translateY(-4px); }
.mode-card-flip { width: 100%; aspect-ratio: 3/4.3; perspective: 800px; position: relative; border-radius: 10px; overflow: visible; }
.mode-card-inner { width: 100%; height: 100%; position: relative; transition: transform 0.7s ease; transform-style: preserve-3d; border-radius: 10px; }
.mode-card.flipped .mode-card-inner { transform: rotateY(180deg); }
.mode-card-front, .mode-card-back { position: absolute; top: 0; left: 0; width: 100%; height: 100%; backface-visibility: hidden; border-radius: 10px; overflow: hidden; border: 2px solid rgba(255,255,255,0.1); transition: border-color 0.3s ease; }
.mode-card-back { transform: rotateY(180deg); }
.mode-card-front img, .mode-card-back img { width: 100%; height: 100%; object-fit: cover; display: block; filter: brightness(0.6); transition: filter 0.3s ease; }
.mode-card:hover .mode-card-front img, .mode-card:hover .mode-card-back img { filter: brightness(1); }
.mode-card.flipped .mode-card-front img, .mode-card.flipped .mode-card-back img { filter: brightness(1); }
.mode-card.selected .mode-card-front, .mode-card.selected .mode-card-back { border-color: var(--color-primary); box-shadow: 0 0 24px rgba(255,107,157,0.35); }
.mode-card-label { margin-top: 12px; font-size: 16px; font-weight: bold; color: var(--color-accent); letter-spacing: 2px; text-align: center; transition: color 0.3s ease; }
.mode-card.selected .mode-card-label { color: var(--color-primary); }
.mode-card-desc { margin-top: 8px; font-size: 12px; color: rgba(255,255,255,0.4); line-height: 1.6; text-align: center; max-height: 0; overflow: hidden; opacity: 0; transition: all 0.4s ease; padding: 0 4px; }
.mode-card.flipped .mode-card-desc { max-height: 120px; opacity: 1; margin-top: 10px; }

.setup-info-group { margin-bottom: 18px; }
.setup-info-group:last-child { margin-bottom: 0; }
.setup-info-label { font-size: 13px; color: rgba(255,255,255,0.45); margin-bottom: 6px; letter-spacing: 1px; }
.setup-info-input { width: 100%; padding: 12px 16px; font-size: 15px; background: rgba(255,255,255,0.06); border: 1.5px solid rgba(255,107,157,0.2); border-radius: 8px; color: #fff; font-family: inherit; transition: all 0.3s ease; letter-spacing: 1px; }
.setup-info-input::placeholder { color: rgba(255,255,255,0.2); font-style: italic; }
.setup-info-input:focus { border-color: var(--color-primary); background: rgba(255,255,255,0.1); box-shadow: 0 0 16px rgba(255,107,157,0.12); }
.setup-info-select-wrapper { position: relative; width: 100%; }
.setup-info-select { width: 100%; padding: 12px 40px 12px 16px; font-size: 15px; background: rgba(255,255,255,0.06); border: 1.5px solid rgba(255,107,157,0.2); border-radius: 8px; color: #fff; font-family: inherit; transition: all 0.3s ease; letter-spacing: 1px; cursor: pointer; appearance: none; -webkit-appearance: none; }
.setup-info-select:focus { border-color: var(--color-primary); background: rgba(255,255,255,0.1); box-shadow: 0 0 16px rgba(255,107,157,0.12); }
.setup-info-select option { background: #2a1a2e; color: #fff; padding: 8px; }
.setup-info-select-wrapper::after { content: ''▾''; position: absolute; right: 16px; top: 50%; transform: translateY(-50%); color: rgba(255,107,157,0.6); font-size: 14px; pointer-events: none; }

.setup-option-group { margin-bottom: 22px; }
.setup-option-group:last-child { margin-bottom: 0; }
.setup-option-header { display: flex; align-items: center; justify-content: space-between; margin-bottom: 6px; gap: 16px; }
.setup-option-title { font-size: 14px; font-weight: bold; color: var(--color-accent); letter-spacing: 1px; }
.setup-option-desc { font-size: 12px; color: rgba(255,255,255,0.35); line-height: 1.6; margin-top: 2px; }

.setup-radio-group { display: flex; gap: 8px; margin-top: 10px; flex-wrap: wrap; }
.setup-radio-item { position: relative; flex: 1; min-width: 0; }
.setup-radio-item input[type="radio"] { position: absolute; opacity: 0; width: 0; height: 0; pointer-events: none; }
.setup-radio-label { display: flex; flex-direction: column; align-items: center; padding: 10px 8px; background: rgba(255,255,255,0.04); border: 1.5px solid rgba(255,255,255,0.1); border-radius: 8px; cursor: pointer; transition: all 0.3s ease; text-align: center; }
.setup-radio-label:hover { border-color: rgba(255,107,157,0.4); background: rgba(255,107,157,0.06); }
.setup-radio-item input[type="radio"]:checked + .setup-radio-label { border-color: var(--color-primary); background: rgba(255,107,157,0.12); box-shadow: 0 0 16px rgba(255,107,157,0.15); }
.setup-radio-value { font-size: 16px; font-weight: bold; color: var(--color-accent); margin-bottom: 4px; }
.setup-radio-item input[type="radio"]:checked + .setup-radio-label .setup-radio-value { color: var(--color-primary); }
.setup-radio-hint { font-size: 10px; color: rgba(255,255,255,0.3); line-height: 1.4; }
.setup-radio-item input[type="radio"]:checked + .setup-radio-label .setup-radio-hint { color: rgba(255,255,255,0.5); }

.setup-toggle { position: relative; width: 48px; height: 26px; flex-shrink: 0; }
.setup-toggle input { opacity: 0; width: 0; height: 0; position: absolute; }
.setup-toggle-slider { position: absolute; cursor: pointer; top: 0; left: 0; right: 0; bottom: 0; background: rgba(255,255,255,0.12); border-radius: 26px; transition: all 0.3s ease; border: 1.5px solid rgba(255,255,255,0.15); }
.setup-toggle-slider::before { content: ''''; position: absolute; height: 18px; width: 18px; left: 3px; bottom: 2.5px; background: rgba(255,255,255,0.6); border-radius: 50%; transition: all 0.3s ease; }
.setup-toggle input:checked + .setup-toggle-slider { background: rgba(255,107,157,0.4); border-color: var(--color-primary); }
.setup-toggle input:checked + .setup-toggle-slider::before { transform: translateX(22px); background: var(--color-primary); box-shadow: 0 0 8px rgba(255,107,157,0.4); }

.setup-divider { height: 1px; background: rgba(255,107,157,0.1); margin: 24px 0; }

/* 滚动提示条 */
.scroll-hint-bar { text-align: center; padding: 12px 0 4px 0; color: rgba(255,107,157,0.5); font-size: 12px; letter-spacing: 1px; animation: scrollHintPulse 2s ease-in-out infinite; user-select: none; }
.scroll-hint-bar.hidden { display: none; }
@keyframes scrollHintPulse { 0%,100%{opacity:0.4} 50%{opacity:1} }

.setup-footer-left { display: flex; align-items: center; gap: 10px; }
.setup-footer-spread { display: flex; align-items: center; justify-content: space-between; width: 100%; }

.btn-copy { background: rgba(255,255,255,0.08); color: var(--color-accent); border: 1.5px solid rgba(255,107,157,0.3); padding: 10px 22px; font-size: 14px; border-radius: var(--radius-md); cursor: pointer; transition: all var(--transition-normal); font-weight: bold; letter-spacing: 1px; }
.btn-copy:hover { background: rgba(255,107,157,0.2); border-color: var(--color-primary); }
.btn-copy.copied { background: rgba(78,205,196,0.2); border-color: var(--color-success); color: var(--color-success); }
.btn-sm { padding: 10px 24px; font-size: 14px; }

/* ========== 确认弹窗 ========== */
.confirm-overlay { position: fixed; top: 0; left: 0; width: 100%; height: 100%; background: rgba(0,0,0,0.7); z-index: 500; display: flex; align-items: center; justify-content: center; opacity: 0; visibility: hidden; transition: opacity 0.3s ease, visibility 0s 0.3s; backdrop-filter: blur(4px); }
.confirm-overlay.show { opacity: 1; visibility: visible; transition: opacity 0.3s ease, visibility 0s 0s; }
.confirm-box { background: linear-gradient(180deg, rgba(28,16,40,0.98) 0%, rgba(18,10,28,0.99) 100%); border: 1.5px solid rgba(255,107,157,0.35); border-radius: 12px; padding: 32px 36px 28px; max-width: min(420px, 88vw); width: 100%; box-shadow: 0 8px 48px rgba(0,0,0,0.6), 0 0 30px rgba(255,107,157,0.1); text-align: center; transform: scale(0.9); transition: transform 0.3s ease; }
.confirm-overlay.show .confirm-box { transform: scale(1); }
.confirm-icon { font-size: 36px; margin-bottom: 16px; display: block; }
.confirm-title { font-size: 17px; font-weight: bold; color: var(--color-accent); margin-bottom: 10px; letter-spacing: 1px; }
.confirm-desc { font-size: 13px; color: rgba(255,255,255,0.45); line-height: 1.7; margin-bottom: 24px; }
.confirm-actions { display: flex; gap: 12px; justify-content: center; }
.confirm-actions .btn { min-width: 100px; }

/* ========== 角色介绍/玩法介绍面板 ========== */
.info-overlay { position: fixed; top: 0; left: 0; width: 100%; height: 100%; background: rgba(0,0,0,0.85); z-index: 200; display: flex; align-items: center; justify-content: center; opacity: 0; visibility: hidden; transition: opacity 0.4s ease, visibility 0s 0.4s; backdrop-filter: blur(6px); }
.info-overlay.show { opacity: 1; visibility: visible; transition: opacity 0.4s ease, visibility 0s 0s; }
.info-panel { position: relative; width: min(960px, 92vw); height: min(88vh, 900px); background: linear-gradient(180deg, rgba(18,10,28,0.97) 0%, rgba(28,16,40,0.98) 100%); border: 1.5px solid rgba(255,107,157,0.3); border-radius: 12px; box-shadow: 0 8px 60px rgba(0,0,0,0.7), 0 0 40px rgba(255,107,157,0.1); display: flex; flex-direction: column; overflow: hidden; }
.info-header { display: flex; align-items: center; justify-content: space-between; padding: 16px 24px; border-bottom: 1px solid rgba(255,107,157,0.2); flex-shrink: 0; }
.info-header-title { font-size: 20px; font-weight: bold; color: var(--color-accent); letter-spacing: 2px; }
.info-close-btn { width: 36px; height: 36px; border: 1.5px solid rgba(255,255,255,0.25); border-radius: 50%; background: rgba(255,255,255,0.05); color: #fff; font-size: 18px; cursor: pointer; display: flex; align-items: center; justify-content: center; transition: all 0.25s ease; line-height: 1; }
.info-close-btn:hover { background: rgba(255,107,157,0.3); border-color: var(--color-primary); transform: rotate(90deg); }
.info-body { flex: 1; overflow-y: auto; overflow-x: hidden; padding: 24px 28px 32px 28px; scrollbar-width: thin; scrollbar-color: rgba(255,107,157,0.3) transparent; -webkit-overflow-scrolling: touch; overscroll-behavior: contain; }
.info-body::-webkit-scrollbar { width: 6px; }
.info-body::-webkit-scrollbar-track { background: transparent; }
.info-body::-webkit-scrollbar-thumb { background: rgba(255,107,157,0.3); border-radius: 3px; }

.info-section-title { font-size: 18px; font-weight: bold; color: var(--color-accent); letter-spacing: 3px; margin: 0 0 20px 0; padding-bottom: 10px; border-bottom: 1px solid rgba(255,107,157,0.15); display: flex; align-items: center; gap: 8px; }
.info-section-title::before { content: ''''; display: inline-block; width: 3px; height: 18px; background: var(--color-primary); border-radius: 2px; }

.story-block { padding: 20px 24px; background: rgba(255,107,157,0.04); border-left: 2px solid rgba(255,107,157,0.3); border-radius: 0 8px 8px 0; margin-bottom: 16px; line-height: 1.9; }
.story-block p { margin: 0 0 12px 0; font-size: 15px; color: var(--text-secondary); }
.story-block p:last-child { margin-bottom: 0; }
.story-block .story-highlight { color: var(--color-primary); font-weight: bold; }
.story-block .story-quote { color: var(--color-accent); font-style: italic; text-align: center; display: block; margin-top: 8px; }
.story-danger { border-left-color: rgba(255,107,107,0.4); background: rgba(255,107,107,0.04); }
.story-danger p { color: rgba(232,213,232,0.75); }
.story-danger .danger-text { color: rgba(255,107,107,0.8); }

.chara-card { display: flex; gap: 20px; padding: 20px; margin-bottom: 16px; border-radius: 8px; border: 1px solid rgba(255,255,255,0.06); transition: border-color 0.3s ease; }
.chara-card:hover { border-color: rgba(255,107,157,0.25); }
.chara-card-featured { border-color: rgba(255,107,157,0.2); background: rgba(255,107,157,0.03); }
.chara-avatar { min-width: 70px; text-align: center; flex-shrink: 0; }
.chara-avatar-circle { width: 56px; height: 56px; border-radius: 50%; display: flex; align-items: center; justify-content: center; margin: 0 auto 6px; font-size: 20px; border: 1.5px solid rgba(255,255,255,0.15); background: rgba(255,255,255,0.04); }
.chara-avatar-label { font-size: 11px; color: rgba(255,107,157,0.6); letter-spacing: 1px; }
.chara-avatar-img { width: 140px; border-radius: 6px; border: 1px solid rgba(255,107,157,0.3); display: block; margin-bottom: 6px; cursor: pointer; transition: all 0.3s ease; }
.chara-avatar-img:hover { border-color: var(--color-primary); transform: translateY(-2px); box-shadow: 0 4px 15px rgba(255,107,157,0.2); }
.chara-name { font-size: 16px; font-weight: bold; color: var(--color-accent); margin-bottom: 3px; }
.chara-meta { font-size: 12px; color: rgba(255,255,255,0.35); margin-bottom: 10px; letter-spacing: 1px; }
.chara-desc { font-size: 14px; color: rgba(232,213,232,0.7); line-height: 1.8; margin: 0; }
.chara-desc-sub { font-size: 14px; color: rgba(232,213,232,0.55); font-style: italic; line-height: 1.8; margin: 8px 0 0 0; }

.npc-group-label { font-size: 13px; letter-spacing: 3px; margin: 28px 0 14px 0; display: flex; align-items: center; gap: 6px; }
.npc-group-label.friendly { color: rgba(78,205,196,0.8); }
.npc-group-label.danger { color: rgba(255,107,107,0.8); }
.npc-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; margin-bottom: 8px; }
.npc-card { padding: 14px 16px; border-radius: 6px; border: 1px solid rgba(255,255,255,0.06); transition: border-color 0.3s ease; }
.npc-card:hover { border-color: rgba(255,107,157,0.25); }
.npc-name { font-size: 14px; margin-bottom: 2px; font-weight: bold; }
.npc-name.friendly { color: rgba(78,205,196,0.85); }
.npc-name.danger { color: rgba(255,107,107,0.85); }
.npc-meta { font-size: 11px; color: rgba(255,255,255,0.3); margin-bottom: 8px; }
.npc-desc { font-size: 13px; color: rgba(232,213,232,0.6); line-height: 1.7; margin: 0; }

.info-divider { height: 1px; background: rgba(255,107,157,0.1); margin: 32px 0; }

.gameplay-subtitle { font-size: 15px; font-weight: bold; color: var(--color-accent); margin: 0 0 10px 0; padding-left: 12px; border-left: 2px solid var(--color-primary); letter-spacing: 1px; }
.gameplay-text { font-size: 14px; color: rgba(232,213,232,0.7); line-height: 1.9; margin: 0 0 8px 0; }
.gameplay-text:last-child { margin-bottom: 0; }
.gameplay-text b { color: var(--color-accent); font-weight: bold; }
.gameplay-text .hl { color: var(--color-primary); }
.gameplay-muted { font-size: 14px; color: rgba(232,213,232,0.45); line-height: 1.9; margin: 0 0 24px 0; }
.gameplay-block { margin-bottom: 28px; }
.gameplay-block:last-child { margin-bottom: 0; }

.info-footer-quote { text-align: center; padding: 28px 0 8px 0; border-top: 1px solid rgba(255,107,157,0.1); margin-top: 20px; }
.info-footer-quote p { font-size: 13px; color: rgba(255,107,157,0.4); letter-spacing: 2px; margin: 0; font-style: italic; }

