@media (max-width: 480px) {
.top-btn { width: 88px; padding: 6px 0; font-size: 0.78rem; }
#mute-btn { left: 8px; }
#history-btn { left: 102px; }
#skip-opening-btn, #restart-btn { left: 196px; }
