<script>
var DEFAULT_NAME=''藤场 悠真'';
var GIF_URL=''https://miha.wiki/WIcZz0.gif'';
var HOVER_SFX_URL=''https://miha.wiki/O6E5ds.ogg'';
var CLICK_SFX_URL=''https://miha.wiki/QEslwS.ogg'';
// 菜单BGM池：开场随机选一首，播完自动切换到另一首
var MENU_BGM_URLS = [
  ''https://miha.wiki/NdS72v.mp3'',
  ''https://miha.wiki/MyNkCp.mp3''
];
var BGM_URL = MENU_BGM_URLS[0]; // 兼容旧引用
var BGM2_URL=''https://miha.wiki/lwFnnQ.ogg'';

var currentMenuBgmIndex = Math.floor(Math.random() * MENU_BGM_URLS.length);

var hoverSfx=new Audio(HOVER_SFX_URL),clickSfx=new Audio(CLICK_SFX_URL);
// ========== 新增：PC端专属·全局悬停音效 ==========
var NEW_HOVER_SFX_URL = ''https://miha.wiki/nLOJhX.ogg'';
var newHoverSfx = new Audio(NEW_HOVER_SFX_URL);
newHoverSfx.volume = 0.4;
newHoverSfx.preload = ''auto'';

// 严格识别"真PC鼠标"环境，触屏笔记本/平板不触发
var isDesktopPointer = window.matchMedia &&
                       window.matchMedia(''(hover: hover) and (pointer: fine)'').matches;

function playNewHoverSfx() {
    if (!isDesktopPointer || isMuted) return;
    var snd = newHoverSfx.cloneNode();
    snd.volume = 0.4;
    snd.play().catch(function(){});
}
var bgmAudio=new Audio(MENU_BGM_URLS[currentMenuBgmIndex]);
var bgm2Audio=new Audio(BGM2_URL);
bgmAudio.volume=0.4;bgmAudio.loop=false;bgmAudio.preload=''auto''; // loop关掉，由ended事件接管
bgm2Audio.volume=0.15;bgm2Audio.loop=true;bgm2Audio.preload=''auto'';

// 一首放完自动切到另一首，实现多样性
bgmAudio.addEventListener(''ended'', function() {
  currentMenuBgmIndex = (currentMenuBgmIndex + 1) % MENU_BGM_URLS.length;
  bgmAudio.src = MENU_BGM_URLS[currentMenuBgmIndex];
  bgmAudio.volume = 0.4;
  var p = bgmAudio.play();
  if (p && p.catch) p.catch(function(){});
});

var bjNormalSfx = new Audio(''https://miha.wiki/ARl5Jd.ogg'');
var bjFastSfx = new Audio(''https://miha.wiki/CZxoYD.ogg'');
var bjCumSfx = new Audio(''https://miha.wiki/lLwIrx.mp3'');
bjNormalSfx.loop = true;
bjFastSfx.loop = true;
bjCumSfx.loop = false;
bjNormalSfx.preload = ''auto'';
bjFastSfx.preload = ''auto'';
bjCumSfx.preload = ''auto'';
bjNormalSfx.volume = 0.8;
bjFastSfx.volume = 0.8;
bjCumSfx.volume = 0.9;
var currentBjSfx = null;
var bjSfxUnlocked = false;

var isMuted = false;

function unlockOneBjSfx(audio) {
    if (!audio) return;
    try {
        audio.preload = ''auto'';
        audio.load();
    } catch (e) {}
}

function unlockBjSfx() {
    if (bjSfxUnlocked) return;
    bjSfxUnlocked = true;

    // 移动端修复：不再通过 audio.play() 解锁真实 R18 音效
    // 部分 iOS / 安卓浏览器即使 muted + volume=0，仍可能误播
    // 这里只预加载，不播放，避免 R18 确认后提前响一次
    unlockOneBjSfx(bjNormalSfx);
    unlockOneBjSfx(bjFastSfx);
    unlockOneBjSfx(bjCumSfx);
}

function stopCurrentBjSfx() {
    if (!currentBjSfx) return;

    try {
        currentBjSfx.pause();
        currentBjSfx.currentTime = 0;
    } catch (e) {}

    currentBjSfx = null;
}

function playBjSfx(type) {
    if (type === ''stop'') {
        stopCurrentBjSfx();
        return;
    }
    stopCurrentBjSfx();

    if (type === ''normal'') {
        currentBjSfx = bjNormalSfx;
    } else if (type === ''fast'') {
        currentBjSfx = bjFastSfx;
    } else if (type === ''cum'') {
        currentBjSfx = bjCumSfx;
    } else {
        currentBjSfx = null;
        return;
    }

    if (!currentBjSfx || isMuted) return;

    try {
        currentBjSfx.pause();
        currentBjSfx.currentTime = 0;
        currentBjSfx.muted = false;
    } catch (e) {}

    var playPromise;
    try {
        playPromise = currentBjSfx.play();
    } catch (e) {
        console.log(''BJ SFX play error:'', e);
        return;
    }

    if (playPromise && playPromise.catch) {
        playPromise.catch(function(err) {
            console.log(''BJ SFX blocked or not ready:'', err);
        });
    }
}

function playHoverSfx(){
    if(isMobile||isMuted)return;
    var snd = hoverSfx.cloneNode();
    snd.volume = 0.5;
    snd.play().catch(function(){});
}
var lastClickTime = 0;
function playClickSfx(){
    if(isMuted)return;
    var now = Date.now();
    if(now - lastClickTime < 50) return;
    lastClickTime = now;
    var snd = clickSfx.cloneNode();
    snd.volume = 0.6;
    snd.play().catch(function(){});
}

var BGM_NORMAL_VOL=0.4;
var bgmPlaying=false,bgmToggle=document.getElementById(''bgmToggle'');
var isMobile=(''ontouchstart'' in window)||(navigator.maxTouchPoints>0);

var bgmFadeInterval=null;
var bgmFadeActive=false;

function startBgmFadeOut(){
    if(bgmFadeActive) return;
    bgmFadeActive=true;
    var FADE_MS=4500;
    var startVol=bgmAudio.volume;
    var startTime=0;
    function fadeStep(timestamp){
        if(!startTime) startTime=timestamp;
        var elapsed=timestamp-startTime;
        var t=Math.min(elapsed/FADE_MS,1);
        var ease=t*t*t;
        var newVol=startVol*(1-ease);
        try{ bgmAudio.volume=Math.max(0,newVol); }catch(e){}
        if(t<1){
            bgmFadeInterval=requestAnimationFrame(fadeStep);
        }else{
            bgmFadeInterval=null;
        }
    }
    bgmFadeInterval=requestAnimationFrame(fadeStep);
}

function stopBgmCompletely(){
    if(bgmFadeInterval){cancelAnimationFrame(bgmFadeInterval);bgmFadeInterval=null;}
    bgmFadeActive=false;
    bgmAudio.pause();
    bgmAudio.currentTime=0;
    bgmAudio.volume=BGM_NORMAL_VOL;
    bgmPlaying=false;
    bgmToggle.classList.remove(''playing'');
}

var currentBgm=''bgm1'';

function startBGM(){
    bgmAudio.volume=BGM_NORMAL_VOL;
    bgmAudio.play().then(function(){
        bgmPlaying=true;currentBgm=''bgm1'';
        bgmToggle.classList.add(''playing'',''visible'');
    }).catch(function(){
        bgmPlaying=false;
        bgmToggle.classList.remove(''playing'');
        bgmToggle.classList.add(''visible'');
    });
}

function startBGM2(){
    bgm2Audio.currentTime=0;
    bgm2Audio.volume=0;
    bgm2Audio.play().then(function(){
        bgmPlaying=true;currentBgm=''bgm2'';
        bgmToggle.classList.add(''playing'',''visible'');
        var fadeStep=0,fadeSteps=30;
        var fi=setInterval(function(){
            fadeStep++;
            var t=Math.min(fadeStep/fadeSteps,1);
            bgm2Audio.volume=0.15*t;
            if(fadeStep>=fadeSteps)clearInterval(fi);
        },50);
    }).catch(function(){
        bgmPlaying=false;
        bgmToggle.classList.remove(''playing'');
        bgmToggle.classList.add(''visible'');
    });
}

function toggleBGM(){
    if(currentBgm===''bgm2''){
        if(bgmPlaying){bgm2Audio.pause();bgmPlaying=false;bgmToggle.classList.remove(''playing'');}
        else{bgm2Audio.play().then(function(){bgmPlaying=true;bgmToggle.classList.add(''playing'');}).catch(function(){});}
    }else{
        if(bgmPlaying){bgmAudio.pause();bgmPlaying=false;bgmToggle.classList.remove(''playing'');}
        else{bgmAudio.play().then(function(){bgmPlaying=true;bgmToggle.classList.add(''playing'');}).catch(function(){});}
    }
}

bgmToggle.addEventListener(''click'',function(){playClickSfx();toggleBGM();});
