function checkAllLoaded(){if(resourcesLoaded.bg&&resourcesLoaded.eyeBg&&resourcesLoaded.video&&resourcesLoaded.creditGif&&resourcesLoaded.bgm&&resourcesLoaded.setupImgs&&resourcesLoaded.bgm2){updateProgress(100);loadingComplete=true;clearTimeout(loadingTimeout);loadingText.textContent=''加载完成'';isSlowLoading=false;updateLoadingDetail(''所有资源加载完毕,准备就绪'');var slh = document.getElementById(''slowLoadHint'');if(slh) slh.style.display=''none'';enterBtn.style.display=''block'';skipLoadBtn.style.display=''none'';}}
var preloadedImageCache = [];

function preloadImageStrict(url) {
    return new Promise(function(resolve) {
        var img = new Image();

        img.decoding = ''async'';
        img.loading = ''eager'';
        img.src = url;

        img.onload = function() {
            if (img.decode) {
                img.decode()
                    .then(function() {
                        preloadedImageCache.push(img);
                        resolve({ url: url, ok: true });
                    })
                    .catch(function() {
                        preloadedImageCache.push(img);
                        resolve({ url: url, ok: true });
                    });
            } else {
                preloadedImageCache.push(img);
                resolve({ url: url, ok: true });
            }
        };

        img.onerror = function() {
            console.warn(''图片预加载失败:'', url);
            resolve({ url: url, ok: false });
        };
    });
}

function preloadSetupImages(cb) {
    var urls = Array.from(new Set(ALL_PRELOAD_IMGS.filter(Boolean)));
    var total = urls.length;
    var loaded = 0;

    if (!total) {
        cb();
        return;
    }

    Promise.all(urls.map(function(url) {
        return preloadImageStrict(url).then(function(result) {
            loaded++;

            var percent = 32 + Math.floor((loaded / total) * 16);
            updateProgress(percent);

            updateLoadingDetail(
                ''正在预加载图片素材...<br>'' +
                loaded + '' / '' + total
            );

            return result;
        });
    })).then(function() {
        cb();
    });
}

