function loadBGM(){
    var dn=false;
    var loadedCount=0;
    var totalCount=MENU_BGM_URLS.length; // 池里有多少首就等多少首
    
    function fin(){
        if(dn)return;
        dn=true;
        resourcesLoaded.bgm=true;
        updateProgress(82);
        updateLoadingDetail(''正在加载游戏内BGM与音效...'');
        loadBGM2();
    }
    
    function onOneDone(){
        loadedCount++;
        if(loadedCount>=totalCount) fin();
    }
    
    // 1. 当前已选中的BGM（bgmAudio实例）
    if(bgmAudio.readyState>=4){
        onOneDone();
    } else {
        bgmAudio.addEventListener(''canplaythrough'',onOneDone,{once:true});
        bgmAudio.addEventListener(''error'',onOneDone,{once:true});
        bgmAudio.load();
    }
    
    // 2. 池中其余BGM：用临时Audio对象触发浏览器缓存，
    //    之后切歌时 bgmAudio.src=新URL 会命中HTTP缓存，无需重新下载
    MENU_BGM_URLS.forEach(function(url,idx){
        if(idx===currentMenuBgmIndex) return; // 跳过已加载的那首
        var alt=new Audio();
        alt.preload=''auto'';
        alt.addEventListener(''canplaythrough'',onOneDone,{once:true});
        alt.addEventListener(''error'',onOneDone,{once:true});
        alt.src=url;
        alt.load();
    });
    
    // 总体超时兜底（按池子大小放宽）
    setTimeout(fin,10000+totalCount*2000);
}

function loadBGM2(){
    var dn=false;
    function fin(){
        if(dn)return;dn=true;resourcesLoaded.bgm2=true;updateProgress(90);
        bjNormalSfx.load(); bjFastSfx.load(); bjCumSfx.load();
        checkAllLoaded();
    }
    if(bgm2Audio.readyState>=4){fin();return;}
    bgm2Audio.addEventListener(''canplaythrough'',fin,{once:true});
    bgm2Audio.addEventListener(''error'',fin,{once:true});
    setTimeout(fin,10000);bgm2Audio.load();
}

