setupStepIndicator.textContent=step+'' / ''+TOTAL_STEPS;
stepEls[step-1].classList.add(''active'');
setupBody.scrollTop=0;
if(step===1){renderNavFooter(null,2,function(){setupState.playerName=playerNameInput.value.trim();});setTimeout(function(){playerNameInput.focus();},100);}
else if(step===2){renderCardFooter(1,3,function(){return!!setupState.selectedMode;});}
else if(step===3){renderCardFooter(2,4,function(){return!!setupState.selectedDebt;});}
else if(step===4){renderCardFooter(3,5,function(){return!!setupState.selectedFavor;});}
else if(step===5){
var name=setupState.playerName||DEFAULT_NAME;
document.getElementById(''infoName'').value=name;
document.getElementById(''infoModeSelect'').value=setupState.selectedMode||''pure'';
document.getElementById(''infoDebtSelect'').value=setupState.selectedDebt||''easy'';
document.getElementById(''infoFavorSelect'').value=setupState.selectedFavor||''50'';
step5ScrolledBottom=false;
document.getElementById(''scrollHintBar'').classList.remove(''hidden'');
renderFinalFooter();
setTimeout(checkStep5Scroll,100);
}
}

function checkStep5Scroll(){
if(setupState.currentStep!==5)return;
var sb=setupBody;
if((sb.scrollHeight-sb.scrollTop-sb.clientHeight)<30){step5ScrolledBottom=true;document.getElementById(''scrollHintBar'').classList.add(''hidden'');renderFinalFooter();}
}
setupBody.addEventListener(''scroll'',function(){if(setupState.currentStep===5&&!step5ScrolledBottom)checkStep5Scroll();});

function renderNavFooter(prev,next,beforeNext){
setupFooter.innerHTML='''';var w=document.createElement(''div'');w.className=''setup-footer-spread'';
if(prev!==null)w.appendChild(makeBtn(''上一步'',''btn btn-secondary btn-sm'',function(){fadeToStep(prev);}));
else w.appendChild(document.createElement(''div''));
w.appendChild(makeBtn(''下一步'',''btn btn-sm'',function(){if(beforeNext)beforeNext();fadeToStep(next);}));
setupFooter.appendChild(w);
}
function renderCardFooter(prev,next,canNext){
setupFooter.innerHTML='''';var w=document.createElement(''div'');w.className=''setup-footer-spread'';
w.appendChild(makeBtn(''上一步'',''btn btn-secondary btn-sm'',function(){fadeToStep(prev);}));
if(canNext())w.appendChild(makeBtn(''下一步'',''btn btn-sm'',function(){fadeToStep(next);}));
setupFooter.appendChild(w);
}
function renderFinalFooter(){
setupFooter.innerHTML='''';var w=document.createElement(''div'');w.className=''setup-footer-spread'';
var left=document.createElement(''div'');left.className=''setup-footer-left'';
left.appendChild(makeBtn(''上一步'',''btn btn-secondary btn-sm'',function(){syncStep5ToState();fadeToStep(4);}));
var copyBtn=document.createElement(''button'');copyBtn.className=''btn-copy'';copyBtn.textContent=''复制信息'';
copyBtn.addEventListener(''mouseenter'',playHoverSfx);
copyBtn.addEventListener(''click'',function(){playClickSfx();syncStep5ToState();doCopy(buildCopyText(),copyBtn);});
left.appendChild(copyBtn);
w.appendChild(left);
var startBtn=document.createElement(''button'');startBtn.className=''btn btn-sm'';startBtn.textContent=''开始游戏'';
if(!step5ScrolledBottom){startBtn.classList.add(''disabled'');startBtn.title=''请先滑动到底部查看所有设置'';}
else{startBtn.addEventListener(''mouseenter'',playHoverSfx);startBtn.addEventListener(''click'',function(){playClickSfx();syncStep5ToState();showConfirm();});}
w.appendChild(startBtn);setupFooter.appendChild(w);
}
function makeBtn(text,cls,onClick){var b=document.createElement(''button'');b.className=cls;b.textContent=text;b.addEventListener(''mouseenter'',playHoverSfx);b.addEventListener(''click'',function(){playClickSfx();onClick();});return b;}
function syncStep5ToState(){
var nameVal=document.getElementById(''infoName'').value.trim();
setupState.playerName=nameVal||DEFAULT_NAME;
setupState.selectedMode=document.getElementById(''infoModeSelect'').value;
setupState.selectedDebt=document.getElementById(''infoDebtSelect'').value;
setupState.selectedFavor=document.getElementById(''infoFavorSelect'').value;
}
function buildCopyText(){
var ms=document.getElementById(''infoModeSelect''),ds=document.getElementById(''infoDebtSelect''),fs=document.getElementById(''infoFavorSelect'');
var words=document.querySelector(''input[name="replyWords"]:checked'').value;
var tc=document.getElementById(''toggleThinkChain'').checked;var am=document.getElementById(''toggleAntiMyth'').checked;var at=document.getElementById(''toggleAntiTalk'').checked;var mem=document.getElementById(''toggleMemory'').checked;
var nameVal=document.getElementById(''infoName'').value.trim()||DEFAULT_NAME;
var lines=[];
lines.push(''玩家姓名: ''+nameVal);
lines.push(''游玩模式: 【''+ms.options[ms.selectedIndex].text+''】'');
lines.push(''债务难度: ''+ds.options[ds.selectedIndex].text);
lines.push(''初始好感度: ''+fs.options[fs.selectedIndex].text);
lines.push(''最少回复''+words+''字'');
lines.push(''思维链【''+(tc?''开启'':''关闭'')+''】'');
lines.push(''防神化防绝望【''+(am?''开启'':''关闭'')+''】'');
lines.push(''防抢话【''+(at?''开启'':''关闭'')+''】'');
lines.push(''记忆区【''+(mem?''开启'':''关闭'')+''】'');
lines.push('''');
lines.push(''【开场剧情已结束】'');
return lines.join(''\n'');
}
function doCopy(text,btn){function ok(){btn.textContent=''已复制 ✓'';btn.classList.add(''copied'');setTimeout(function(){btn.textContent=''复制信息'';btn.classList.remove(''copied'');},2000);}function fail(){btn.textContent=''复制失败'';setTimeout(function(){btn.textContent=''复制信息'';},2000);}if(navigator.clipboard&&navigator.clipboard.writeText){navigator.clipboard.writeText(text).then(ok).catch(function(){fbCopy(text)?ok():fail();});}else{fbCopy(text)?ok():fail();}}
function fbCopy(text){var ta=document.createElement(''textarea'');ta.value=text;ta.style.cssText=''position:fixed;left:-9999px'';document.body.appendChild(ta);ta.select();var r=false;try{r=document.execCommand(''copy'');}catch(e){}document.body.removeChild(ta);return r;}
function fadeToStep(target){if(setupState.currentStep===2&&target===3&&setupState.selectedMode===''ntr''){document.getElementById(''ntrWarningOverlay'').classList.add(''show'');return;}var cur=document.querySelector(''.setup-step.active'');if(cur){cur.style.transition=''opacity 0.3s ease'';cur.style.opacity=''0'';setTimeout(function(){cur.style.transition='''';cur.style.opacity='''';showSetupStep(target);},300);}else{showSetupStep(target);}}

function bindCardPair(a,b,key,va,vb,rerender){
a.addEventListener(''click'',function(){playClickSfx();setupState[key]=va;a.classList.add(''flipped'',''selected'');b.classList.remove(''flipped'',''selected'');rerender();});
b.addEventListener(''click'',function(){playClickSfx();setupState[key]=vb;b.classList.add(''flipped'',''selected'');a.classList.remove(''flipped'',''selected'');rerender();});
a.addEventListener(''mouseenter'',playHoverSfx);b.addEventListener(''mouseenter'',playHoverSfx);
}
bindCardPair(document.getElementById(''modePure''),document.getElementById(''modeNTR''),''selectedMode'',''pure'',''ntr'',function(){renderCardFooter(1,3,function(){return!!setupState.selectedMode;});});
bindCardPair(document.getElementById(''debtEasy''),document.getElementById(''debtHard''),''selectedDebt'',''easy'',''hard'',function(){renderCardFooter(2,4,function(){return!!setupState.selectedDebt;});});
bindCardPair(document.getElementById(''favor50''),document.getElementById(''favor300''),''selectedFavor'',''50'',''300'',function(){renderCardFooter(3,5,function(){return!!setupState.selectedFavor;});});

setupOverlay.addEventListener(''click'',function(e){if(e.target===setupOverlay){playClickSfx();closeSetup();}});
document.getElementById(''startGameBtn'').addEventListener(''click'',function(){playClickSfx();openSetup();});
document.querySelectorAll(''.setup-radio-label'').forEach(function(l){l.addEventListener(''mouseenter'',playHoverSfx);l.addEventListener(''click'',playClickSfx);});
document.querySelectorAll(''.setup-toggle'').forEach(function(t){t.addEventListener(''mouseenter'',playHoverSfx);t.addEventListener(''click'',playClickSfx);});

/* ========== 确认弹窗 ========== */
var confirmOverlay=document.getElementById(''confirmOverlay'');
var confirmCancel=document.getElementById(''confirmCancel'');
var confirmStart=document.getElementById(''confirmStart'');
function showConfirm(){confirmOverlay.classList.add(''show'');}
function hideConfirm(){confirmOverlay.classList.remove(''show'');}
confirmCancel.addEventListener(''mouseenter'',playHoverSfx);
confirmCancel.addEventListener(''click'',function(){playClickSfx();hideConfirm();});
confirmStart.addEventListener(''mouseenter'',playHoverSfx);
confirmStart.addEventListener(''click'',function(){
    playClickSfx();
    hideConfirm();
    closeSetup();
    showR18Warning();
});
confirmOverlay.addEventListener(''click'',function(e){if(e.target===confirmOverlay){playClickSfx();hideConfirm();}});

/* ========== R18 警告弹窗 ========== */
var r18WarningOverlay = document.getElementById(''r18WarningOverlay'');
var r18StartBtn = document.getElementById(''r18StartBtn'');
var r18Timer = null;

function showR18Warning() {
    r18WarningOverlay.classList.add(''show'');
    var timeLeft = 5;
    r18StartBtn.classList.add(''disabled'');
    r18StartBtn.textContent = ''开始游戏 ('' + timeLeft + ''s)'';
    r18Timer = setInterval(function() {
        timeLeft--;
        if (timeLeft <= 0) {
            clearInterval(r18Timer);
            r18StartBtn.classList.remove(''disabled'');
            r18StartBtn.textContent = ''开始游戏'';
        } else {
            r18StartBtn.textContent = ''开始游戏 ('' + timeLeft + ''s)'';
        }
    }, 1000);
}

function hideR18Warning() {
    r18WarningOverlay.classList.remove(''show'');
    if (r18Timer) clearInterval(r18Timer);
}

r18StartBtn.addEventListener(''mouseenter'', function() {
    if (!this.classList.contains(''disabled'')) playHoverSfx();
});

r18StartBtn.addEventListener(''click'', function() {
    if (this.classList.contains(''disabled'')) return;

    playClickSfx();
    unlockBjSfx();

    /*
      移动端修复点：
      iOS / 安卓部分浏览器要求 video.play() 必须发生在用户点击手势内。
      所以这里先在 R18 按钮点击事件里对 video 做一次播放授权解锁，
      然后再进入原本的 launchGame 动画流程。
    */
    if (isMobile && video) {
        video.muted = true;
        video.setAttribute(''muted'', '''');
        video.setAttribute(''playsinline'', '''');
        video.setAttribute(''webkit-playsinline'', '''');
        video.setAttribute(''x5-playsinline'', '''');
        video.setAttribute(''x5-video-player-type'', ''h5'');
        video.setAttribute(''x5-video-player-fullscreen'', ''false'');

        try {
            video.pause();
            video.currentTime = 0;
        } catch(e) {}

        var unlockPromise = video.play();

        if (unlockPromise && unlockPromise.then) {
            unlockPromise.then(function() {
                video.pause();
                try { video.currentTime = 0; } catch(e) {}

                hideR18Warning();
                launchGame();
            }).catch(function() {
                hideR18Warning();
                launchGame();
            });
        } else {
            try {
                video.pause();
                video.currentTime = 0;
            } catch(e) {}

            hideR18Warning();
            launchGame();
        }
    } else {
        hideR18Warning();
        launchGame();
    }
});

/* ========== 开始游戏 ========== */
var bgmDreamStarted=false;
var videoPollInterval=null;

function launchGame(){
    if(!video.src){
        video.src=''https://videotourl.com/videos/1790521581279-85346919-5ff1-4d47-882b-9f54f573beca.mp4'';
        video.preload=''auto'';
        video.load();
    }

    video.muted = true;
    video.setAttribute(''muted'', '''');
    video.setAttribute(''playsinline'', '''');
    video.setAttribute(''webkit-playsinline'', '''');
    video.setAttribute(''x5-playsinline'', '''');
    video.setAttribute(''x5-video-player-type'', ''h5'');
    video.setAttribute(''x5-video-player-fullscreen'', ''false'');

    try {
        video.pause();
        video.currentTime = 0;
    } catch(e) {}

    blurTriggered=false;
    bgmDreamStarted=false;
    bgmAudio.volume=BGM_NORMAL_VOL;

    menuContainer.classList.add(''fade-out'');
    skipVideoBtn.style.display = ''block'';

    setTimeout(function(){
        scenes.menu.classList.add(''show-bg'');

        setTimeout(function(){
            scenes.video.style.opacity=''0'';
            scenes.video.classList.add(''active'');

            requestAnimationFrame(function(){
                requestAnimationFrame(function(){
                    scenes.video.style.transition=''opacity 0.8s ease'';
                    scenes.video.style.opacity=''1'';

                    setTimeout(function(){
                        scenes.menu.classList.remove(''active'');

                        setTimeout(function(){
                            var playPromise = video.play();

                            if(playPromise && playPromise.then){
                                playPromise.then(function(){
                                    startVideoPoll();
                                }).catch(function(){
                                    /*
                                      移动端兜底：
                                      如果浏览器仍然拦截播放，不弹 alert，不回菜单。
                                      保持视频场景，然后重新 load 再试一次。
                                    */
                                    try {
                                        video.load();
                                        video.currentTime = 0;
                                    } catch(e) {}

                                    var retryPromise = video.play();

                                    if(retryPromise && retryPromise.then){
                                        retryPromise.then(function(){
                                            startVideoPoll();
                                        }).catch(function(){
                                            /*
                                              最终兜底：
                                              保持在视频场景，避免移动端出现“点开始游戏后回主菜单”的问题。
                                            */
                                            scenes.menu.classList.remove(''active'');
                                            scenes.video.classList.add(''active'');
                                            scenes.video.style.opacity=''1'';
                                        });
                                    } else {
                                        startVideoPoll();
                                    }
                                });
                            } else {
                                startVideoPoll();
                            }
                        },100);
                    },800);
                });
            });
        },400);
    },900);
}

function startVideoPoll(){
    if(videoPollInterval)clearInterval(videoPollInterval);
    videoPollInterval=setInterval(function(){
        if(!video.duration||video.paused) return;
        if(video.ended){clearInterval(videoPollInterval);videoPollInterval=null;return;}
        var remaining=video.duration-video.currentTime;
        if(!bgmDreamStarted&&remaining<=6){
            bgmDreamStarted=true;
            startBgmFadeOut();
        }
        if(!blurTriggered&&remaining<=1.5){
            blurTriggered=true;
            video.classList.add(''blurred'');
            document.getElementById(''galDialog'').classList.add(''show'');
            var el = document.getElementById(''galDialogText'');
            el.innerHTML = '''';
            "哥哥...醒醒...".split('''').forEach(function(c,i){
                var s=document.createElement(''span'');
                s.className=''char'';
                s.textContent=c;
                s.style.opacity = ''1'';
                s.style.transitionDelay=(i*150)+''ms'';
                el.appendChild(s);
            });
        }
    },100);
}

function skipVideoAnimation() {
    skipVideoBtn.style.display = ''none'';
    if(videoPollInterval){clearInterval(videoPollInterval);videoPollInterval=null;}
    stopBgmCompletely();
    if(bgmFadeInterval){cancelAnimationFrame(bgmFadeInterval);bgmFadeInterval=null;}
    video.pause();
    video.classList.remove(''blurred'');
    var ov=document.getElementById(''eyeCloseOverlay''),ct=ov.querySelector(''.eyelid-close-top''),cb=ov.querySelector(''.eyelid-close-bottom'');
    ov.style.display=''block'';ct.style.transition=''none'';cb.style.transition=''none'';ct.style.height=''0%'';cb.style.height=''0%'';
    requestAnimationFrame(function(){requestAnimationFrame(function(){
        ct.style.transition=''height 0.4s ease-in'';cb.style.transition=''height 0.4s ease-in'';
        ct.style.height=''50%'';cb.style.height=''50%'';
    });});
    setTimeout(function(){
        scenes.video.classList.remove(''active'');scenes.video.style.opacity='''';scenes.video.style.transition='''';video.classList.remove(''blurred'');
        var es=scenes.eyeOpen,et=es.querySelector(''.eyelid-top''),eb=es.querySelector(''.eyelid-bottom''),bg=es.querySelector(''.eye-bg'');
        et.style.transition=''none'';eb.style.transition=''none'';et.style.height=''50%'';eb.style.height=''50%'';et.style.display='''';eb.style.display='''';
        bg.style.filter=''blur(18px)'';bg.style.transition=''filter 0.6s ease'';
        es.style.transition=''none'';es.classList.add(''active'');es.offsetHeight;
        setTimeout(function(){
            ov.style.display=''none'';ct.style.height=''0%'';cb.style.height=''0%'';
            es.style.transition='''';et.style.transition=''height 0.8s ease'';eb.style.transition=''height 0.8s ease'';
            startEyeOpenSequence();
        },50);
    },500);
}

video.addEventListener(''ended'',function(){
    if(videoPollInterval){clearInterval(videoPollInterval);videoPollInterval=null;}
    skipVideoBtn.style.display = ''none'';
    stopBgmCompletely();

    var ov=document.getElementById(''eyeCloseOverlay''),ct=ov.querySelector(''.eyelid-close-top''),cb=ov.querySelector(''.eyelid-close-bottom'');
    ov.style.display=''block'';ct.style.transition=''none'';cb.style.transition=''none'';ct.style.height=''0%'';cb.style.height=''0%'';
    requestAnimationFrame(function(){requestAnimationFrame(function(){
        ct.style.transition=''height 0.4s ease-in'';cb.style.transition=''height 0.4s ease-in'';
        ct.style.height=''50%'';cb.style.height=''50%'';
    });});
    setTimeout(function(){
        scenes.video.classList.remove(''active'');scenes.video.style.opacity='''';scenes.video.style.transition='''';video.classList.remove(''blurred'');
        var es=scenes.eyeOpen,et=es.querySelector(''.eyelid-top''),eb=es.querySelector(''.eyelid-bottom''),bg=es.querySelector(''.eye-bg'');
        et.style.transition=''none'';eb.style.transition=''none'';et.style.height=''50%'';eb.style.height=''50%'';et.style.display='''';eb.style.display='''';
        bg.style.filter=''blur(18px)'';bg.style.transition=''filter 0.6s ease'';
        es.style.transition=''none'';es.classList.add(''active'');es.offsetHeight;
        setTimeout(function(){
            ov.style.display=''none'';ct.style.height=''0%'';cb.style.height=''0%'';
            es.style.transition='''';et.style.transition=''height 0.8s ease'';eb.style.transition=''height 0.8s ease'';
            startEyeOpenSequence();
        },50);
    },500);
});

bgImage.src=''https://miha.wiki/RZxq2f.png'';updateProgress(5);

function startEyeOpenSequence(){
    var es=scenes.eyeOpen,et=es.querySelector(''.eyelid-top''),eb=es.querySelector(''.eyelid-bottom''),bg=es.querySelector(''.eye-bg'');
    var tl=[
        {d:1200,a:function(){se(et,eb,38);}},{d:1200,a:function(){se(et,eb,50);}},
        {d:800,a:function(){se(et,eb,32);bg.style.filter=''blur(14px)'';}},{d:1000,a:function(){se(et,eb,50);}},
        {d:700,a:function(){se(et,eb,22);bg.style.filter=''blur(10px)'';}},{d:1200,a:function(){se(et,eb,50);}},
        {d:600,a:function(){se(et,eb,12);bg.style.filter=''blur(6px)'';}},{d:900,a:function(){se(et,eb,48);}},
        {d:300,a:function(){se(et,eb,8);bg.style.filter=''blur(3px)'';}},
        {d:1000,a:function(){et.style.transition=''height 0.15s ease'';eb.style.transition=''height 0.15s ease'';se(et,eb,50);}},
        {d:250,a:function(){et.style.transition=''height 0.6s ease'';eb.style.transition=''height 0.6s ease'';se(et,eb,0);bg.style.transition=''filter 0.8s ease'';bg.style.filter=''blur(0px)'';}},
        {d:1000,a:function(){
            et.style.display=''none'';
            eb.style.display=''none'';
            startBGM2();
            document.getElementById(''bgmToggle'').style.display=''none'';
            document.getElementById(''galTopBtns'').style.display=''block'';
            startGalEngine();
        }}
    ];
    var td=0;tl.forEach(function(s){td+=s.d;setTimeout(s.a,td);});
}

