var currentNodeId = ''s1_1'';
var isTyping = false;
var typeInterval = null;
var currentText = '''';
var historyLog = [];

var activeBgLayer = 1;
var currentBgSrc = '''';
var activeSpriteLayer = 1;
var currentSpriteKey = ''none'';

function setGalBg(src) {
    if (currentBgSrc === src) return;
    currentBgSrc = src;
    var nextLayer = activeBgLayer === 1 ? 2 : 1;
    var nextEl = document.getElementById(''galBg'' + nextLayer);
    var currEl = document.getElementById(''galBg'' + activeBgLayer);
    
    currEl.style.zIndex = ''3'';
    nextEl.style.zIndex = ''1'';
    
    nextEl.style.backgroundImage = ''url('' + src + '')'';
    nextEl.style.opacity = ''1'';
    currEl.style.opacity = ''0'';
    
    activeBgLayer = nextLayer;
}

function startGalEngine() {
    document.getElementById(''galDialog'').classList.add(''show'');
    document.getElementById(''galClickArea'').style.display = ''block'';
    document.getElementById(''skip-opening-btn'').style.display = ''block'';
    document.getElementById(''restart-btn'').style.display = ''none'';
    skipVideoBtn.style.display = ''none'';
    
    currentNodeId = ''s1_1'';
    historyLog = [];
    document.getElementById(''historyBody'').innerHTML = '''';
    
    document.getElementById(''galBg1'').style.opacity = ''0'';
    document.getElementById(''galBg2'').style.opacity = ''0'';
    currentBgSrc = '''';
    activeBgLayer = 1;
    
    document.getElementById(''galSprite1'').style.opacity = ''0'';
    document.getElementById(''galSprite2'').style.opacity = ''0'';
    currentSpriteKey = ''none'';
    activeSpriteLayer = 1;
    
    playStoryNode(currentNodeId);
}

function playStoryNode(id) {
    if (id === ''end'') {
        showEndCopy();
        return;
    }
    
    var node = storyData.find(function(n) { return n.id === id; });
    if (!node) return;
    
    currentNodeId = id;
    
    var nameEl = document.querySelector(''.gal-dialog-name'');
    if (node.name === ''旁白'') {
        nameEl.style.display = ''none'';
    } else {
        nameEl.style.display = ''block'';
        nameEl.textContent = node.name;
    }
    
    var textEl = document.getElementById(''galDialogText'');
    textEl.innerHTML = '''';
    
    if (node.bg) {
        var targetSrc = bgs[node.bg];
        if (targetSrc) {
            setGalBg(targetSrc);
        }
    }
    
    if (node.sprite) {
        if (node.sprite === ''none'') {
            document.getElementById(''galSprite1'').style.opacity = ''0'';
            document.getElementById(''galSprite2'').style.opacity = ''0'';
            currentSpriteKey = ''none'';
        } else {
            if (currentSpriteKey !== node.sprite) {
                var nextLayer = activeSpriteLayer === 1 ? 2 : 1;
                var nextEl = document.getElementById(''galSprite'' + nextLayer);
                var currEl = document.getElementById(''galSprite'' + activeSpriteLayer);
                
                nextEl.src = sprites[node.sprite];
                nextEl.style.opacity = ''1'';
                currEl.style.opacity = ''0'';
                
                activeSpriteLayer = nextLayer;
                currentSpriteKey = node.sprite;
            }
        }
    }

    var viewCgBtn = document.getElementById(''view-cg-btn'');
    var currentFocusImgSrc = '''';
    
    var isCgBg = false;
    for (var key in bgs) {
        if (key.startsWith(''cg'') && key !== ''cg'' && bgs[key] === currentBgSrc) {
            isCgBg = true;
            currentFocusImgSrc = currentBgSrc;
            break;
        }
    }

    if (!isCgBg && currentSpriteKey !== ''none'') {
        currentFocusImgSrc = sprites[currentSpriteKey];
    }

    if (currentFocusImgSrc) {
        viewCgBtn.style.display = ''block'';
        viewCgBtn.dataset.src = currentFocusImgSrc;
    } else {
        viewCgBtn.style.display = ''none'';
    }

    if (id === ''s9_1'') playBjSfx(''normal'');
    if (id === ''s9_10'') playBjSfx(''fast'');
    if (id === ''s11_1'') playBjSfx(''cum'');
    if (id === ''s11_5'') playBjSfx(''stop'');
    
    addHistory(node.name, node.text);
    
    isTyping = true;
    currentText = node.text;
    var chars = currentText.split('''');
    var charSpans = [];
    chars.forEach(function(c) {
        if (c === ''\n'') {
            textEl.appendChild(document.createElement(''br''));
        } else {
            var s = document.createElement(''span'');
            s.className = ''char'';
            s.textContent = c;
            textEl.appendChild(s);
            charSpans.push(s);
        }
    });
    
    var i = 0;
    document.querySelector(''.gal-dialog-indicator'').style.display = ''none'';
    
    if(typeInterval) clearInterval(typeInterval);
    
    typeInterval = setInterval(function() {
        if (i < charSpans.length) {
            charSpans[i].style.opacity = ''1'';
            i++;
        } else {
            finishTyping(node);
        }
    }, 35);
}

function finishTyping(node) {
    if(typeInterval) clearInterval(typeInterval);
    isTyping = false;
    var spans = document.getElementById(''galDialogText'').querySelectorAll(''span.char'');
    spans.forEach(function(s) {
        s.style.opacity = ''1'';
    });
    
    if (node.options && node.options.length > 0) {
        showOptions(node.options);
        document.querySelector(''.gal-dialog-indicator'').style.display = ''none'';
    } else {
        document.querySelector(''.gal-dialog-indicator'').style.display = ''block'';
    }
}

function handleGalClick() {
    if (isTyping) {
        var node = storyData.find(function(n) { return n.id === currentNodeId; });
        finishTyping(node);
    } else {
        var node = storyData.find(function(n) { return n.id === currentNodeId; });
        if (node && (!node.options || node.options.length === 0)) {
            playClickSfx();
            playStoryNode(node.next);
        }
    }
}

document.getElementById(''galClickArea'').addEventListener(''click'', handleGalClick);

function showOptions(options) {
    var container = document.getElementById(''galOptionsContainer'');
    container.innerHTML = '''';
    options.forEach(function(opt) {
        var btn = document.createElement(''button'');
        btn.className = ''gal-option-btn'';
        btn.textContent = opt.text;
        btn.addEventListener(''mouseenter'', playHoverSfx);
        btn.addEventListener(''click'', function(e) {
            e.stopPropagation();
            playClickSfx();
            container.classList.remove(''show'');
            playStoryNode(opt.target);
        });
        container.appendChild(btn);
    });
    container.classList.add(''show'');
}

function addHistory(name, text) {
    var hb = document.getElementById(''historyBody'');
    var item = document.createElement(''div'');
    item.className = ''history-item'';
    item.innerHTML = ''<div class="history-name">'' + name + ''</div><div class="history-text">'' + text.replace(/\n/g, ''<br>'') + ''</div>'';
    hb.appendChild(item);
    hb.scrollTop = hb.scrollHeight;
}

function showEndCopy() {
    document.getElementById(''galClickArea'').style.display = ''none'';
    document.getElementById(''galOptionsContainer'').classList.remove(''show'');
    document.getElementById(''skip-opening-btn'').style.display = ''none'';
    document.getElementById(''restart-btn'').style.display = ''block'';
    document.getElementById(''endCopyOverlay'').classList.add(''show'');
}

