// ========== 全局可点击区域 hover 委托（仅PC生效）==========
var INTERACTIVE_SELECTOR = [
    ''button'',
    ''.btn'',
    ''.menu-btn'',
    ''.top-btn'',
    ''.btn-copy'',
    ''.gal-option-btn'',
    ''.history-close-btn'',
    ''.gallery-close-btn'',
    ''.info-close-btn'',
    ''.lightbox-close-btn'',
    ''#bgmToggle'',
    ''#galClickArea'',
    ''.float-duck'',
    ''.menu-title-img''
].join('', '');

document.addEventListener(''mouseover'', function(e) {
    if (!isDesktopPointer || isMuted) return;
    var target = e.target.closest(INTERACTIVE_SELECTOR);
    if (!target) return;
    // 关键：防止从子元素移到父元素时重复触发
    var related = e.relatedTarget;
    if (related && target.contains(related)) return;
    playNewHoverSfx();
}, true);
bindButtonSounds();
/* ========== BGM 信息卡片悬浮逻辑 ========== */
(function() {
  var bgmCard = document.getElementById(''bgmInfoCard'');
  var bgmBtn = document.getElementById(''bgmToggle'');
  if (!bgmCard || !bgmBtn) return;

  // 用 hover+pointer 判定真正的PC鼠标环境，避免触屏笔记本被误判
  var isDesktop = window.matchMedia &&
                  window.matchMedia(''(hover: hover) and (pointer: fine)'').matches;

  if (isDesktop) {
    // ========== PC端：仅鼠标悬停才显示 ==========
    var hideTimer = null;
    function showCard() {
      if (hideTimer) { clearTimeout(hideTimer); hideTimer = null; }
      bgmCard.classList.add(''show'');
    }
    function hideCard() {
      if (hideTimer) clearTimeout(hideTimer);
      hideTimer = setTimeout(function() {
        bgmCard.classList.remove(''show'');
      }, 150);
    }
    bgmBtn.addEventListener(''mouseenter'', showCard);
    bgmBtn.addEventListener(''mouseleave'', hideCard);
    bgmCard.addEventListener(''mouseenter'', showCard);
    bgmCard.addEventListener(''mouseleave'', hideCard);
    return; // PC逻辑结束，绝不执行下面的自动弹出
  }

  // ========== 移动端专属：进入主菜单1秒后弹出，停留5秒，慢速渐入渐出 ==========
  bgmCard.style.left = ''80px''; // 往右挪，避开左上角唱片按钮
  bgmCard.style.transition =
    ''opacity 1s ease, transform 1s cubic-bezier(0.16, 1, 0.3, 1)'';

  var showDelayTimer = null;
  var hideDelayTimer = null;

  function clearMobileTimers() {
    if (showDelayTimer) { clearTimeout(showDelayTimer); showDelayTimer = null; }
    if (hideDelayTimer) { clearTimeout(hideDelayTimer); hideDelayTimer = null; }
  }

  function triggerMobilePopup() {
    clearMobileTimers();
    showDelayTimer = setTimeout(function() {
      bgmCard.classList.add(''show'');
      hideDelayTimer = setTimeout(function() {
        bgmCard.classList.remove(''show'');
      }, 5000);
    }, 1000);
  }

  var menuScene = document.getElementById(''menuScene'');
  if (!menuScene) return;

  var menuObs = new MutationObserver(function() {
    if (menuScene.classList.contains(''active'')) {
      triggerMobilePopup();
    } else {
      clearMobileTimers();
      bgmCard.classList.remove(''show'');
    }
  });
  menuObs.observe(menuScene, { attributes: true, attributeFilter: [''class''] });

  if (menuScene.classList.contains(''active'')) {
    triggerMobilePopup();
  }
})();

/* ========== 主菜单漂浮物生成器 ========== */
(function() {
  var floatLayer = document.getElementById(''menuFloatLayer'');
  var menuScene = document.getElementById(''menuScene'');
  if (!floatLayer || !menuScene) return;

  var spawnTimers = [];
  var isRunning = false;
  var PETAL_FALL_NAMES = [''petalFallA'', ''petalFallB'', ''petalFallC''];
  var PETAL_VARIANTS = ['''', ''s-small'', ''s-big'', ''s-deep''];
  var ORB_RISE_NAMES = [''orbRiseA'', ''orbRiseB''];
  var ORB_SIZES = ['''', ''o-sm'', ''o-lg''];

  function rand(min, max) { return Math.random() * (max - min) + min; }
  function pick(arr) { return arr[Math.floor(Math.random() * arr.length)]; }

  function spawnPetal() {
    if (!isRunning) return;
    var petal = document.createElement(''div'');
    petal.className = ''sakura-petal '' + pick(PETAL_VARIANTS);
    petal.style.left = rand(-5, 100) + ''%'';
    var duration = rand(11, 18);
    petal.style.animation = pick(PETAL_FALL_NAMES) + '' '' + duration.toFixed(2) + ''s linear forwards'';
    petal.style.opacity = rand(0.55, 0.95);
    floatLayer.appendChild(petal);
    setTimeout(function() {
      if (petal.parentNode) petal.parentNode.removeChild(petal);
    }, duration * 1000 + 200);
  }

  function spawnOrb() {
    if (!isRunning) return;
    var orb = document.createElement(''div'');
    orb.className = ''glow-orb '' + pick(ORB_SIZES);
    orb.style.left = rand(0, 100) + ''%'';
    var duration = rand(8, 14);
    var riseAnim = pick(ORB_RISE_NAMES) + '' '' + duration.toFixed(2) + ''s ease-in forwards'';
    var twinkleAnim = ''orbTwinkle '' + rand(1.2, 2.4).toFixed(2) + ''s ease-in-out infinite'';
    orb.style.animation = riseAnim + '', '' + twinkleAnim;
    floatLayer.appendChild(orb);
    setTimeout(function() {
      if (orb.parentNode) orb.parentNode.removeChild(orb);
    }, duration * 1000 + 200);
  }

  var duckOnScreen = false;
  var DUCK_FALL_NAMES = [''duckFallA'', ''duckFallB''];

  function spawnDuck() {
    if (!isRunning || duckOnScreen) return;
    duckOnScreen = true;

    var duck = document.createElement(''div'');
    duck.className = ''float-duck'';
    duck.style.left = rand(8, 88) + ''%'';
    var duration = rand(14, 20); // 比花瓣稍慢，更容易点到
    duck.style.animation = pick(DUCK_FALL_NAMES) + '' '' + duration.toFixed(2) + ''s linear forwards'';

    // 点击事件：吐槽 + 不影响飘动
    duck.addEventListener(''click'', function(e) {
      e.stopPropagation();
      // 移除已有气泡，避免连点叠加
      var oldBubble = duck.querySelector(''.duck-bubble'');
      if (oldBubble) oldBubble.remove();

      var bubble = document.createElement(''div'');
      bubble.className = ''duck-bubble'';
      bubble.textContent = ''尼玛~'';
      duck.appendChild(bubble);

      // 触发一下抖动反馈（包一层 inner 以免覆盖外层飘动动画）
      // 由于直接给 duck 加抖动会冲突，这里只通过气泡视觉效果体现
      setTimeout(function() {
        if (bubble.parentNode) bubble.remove();
      }, 1500);

      // 顺便播个点击音效
      if (typeof playClickSfx === ''function'') playClickSfx();
    });

    floatLayer.appendChild(duck);

    setTimeout(function() {
      if (duck.parentNode) duck.parentNode.removeChild(duck);
      duckOnScreen = false;
    }, duration * 1000 + 200);
  }

  function tryDuckSpawn() {
    if (!isRunning) return;
    // 大约 8% 概率出鸭，且屏幕没鸭时才出
    if (!duckOnScreen && Math.random() < 0.08) {
      spawnDuck();
    }
  }

  function startFloating() {
    if (isRunning) return;
    isRunning = true;

    // 预先撒一批，避免初次进入时空荡
    for (var i = 0; i < 6; i++) {
      setTimeout(spawnPetal, i * 350);
    }

    // 进入菜单必定掉一只鸭，营造惊喜首遇
    setTimeout(spawnDuck, 2500);

    // 持续生成
    spawnTimers.push(setInterval(spawnPetal, 900));
    spawnTimers.push(setInterval(tryDuckSpawn, 4000)); // 每4秒掷一次骰子，约8%概率掉鸭
  }

  function stopFloating() {
    isRunning = false;
    spawnTimers.forEach(function(t) { clearInterval(t); });
    spawnTimers = [];
    // 已经在飞的让它自然消失即可，不强制清理
  }

  // 监听菜单显隐
  var observer = new MutationObserver(function() {
    if (menuScene.classList.contains(''active'')) {
      startFloating();
    } else {
      stopFloating();
    }
  });
  observer.observe(menuScene, { attributes: true, attributeFilter: [''class''] });

  // 首次如果菜单已经active，直接启动
  if (menuScene.classList.contains(''active'')) startFloating();
})();
</script>
</body>
</html>', '都市日常', '2026-09-30 21:41:07', '2026-09-30 21:41:07', '', '', '[]', '') ON CONFLICT (id) DO NOTHING;
INSERT INTO stories (id, title, badge, cover_icon, cover_title, cover_subtitle, logo, theme_color, btn_gradient, handbook_json, roles_json, scenes_json, styles_json, first_turn_demo_json, custom_css, custom_html, category, created_at, updated_at, system_prompt, status_template, lorebook_json, post_history_instructions) VALUES ('deck_gentle_mother_contrast', '我的温柔妈妈居然是个丝袜癖反差痴女（可M可S）', '都市 · 丝袜反差', '🖤', '我的温柔妈妈居然是个', '我的温柔妈妈居然是个丝袜癖反差痴女（可M可S）', '🖤', '#ec4899', 'linear-gradient(135deg, #db2777 0%, #f472b6 100%)', '{"title": "我的温柔妈妈居然是个丝袜癖反差痴女（可M可S）", "desc": "【更新】\n增加开放性结局，特别增加NTR结局，NTR玩家狂喜。\n第一次做卡，有不足的地方关心大家踊跃批评，希望大家能在评论留下建议。\n\n拥有E罩杯雪乳与蜜桃臀且喜欢穿连裤袜的妈妈居然是个反差女S。\n\n为了死守温柔伪装，每天晚上背着懦弱无能的丈夫在卫生间频频自慰，欲求不满的她有了“出轨”的想法，难道你只能眼睁睁看着妈妈被大肉棒干得淫水四溢、浪叫连连，你还要强忍屈辱，装作不知道吗？\n\n你必须让妈妈心甘情愿地敞开流水的肉穴，在日常家务中沦为你胯下疯狂吞咽精液的淫荡玩物。 （或者成为妈妈的专属M玩物）", "bg_image": "https://catai.wiki/a14cf11b-69f6-4467-8ee1-dd7e5ed6aa00/bg", "opening_options": ["【深入互动】：依循情境展开深入探索与对话", "【试探心理】：保持警觉，观察对方隐秘情绪与微妙反应", "【掌控局势】：以坚定主动态度引导场景走向"]}', '[{"name": "主角 (玩家)", "role": "核心视角", "desc": "故事的决策者与见证者，每一次对话抉择都将决定剧情与好感走向。"}, {"name": "苏沐晴", "role": "温柔优雅全职人妻", "desc": "34岁全职太太，165cm/56kg，96E丰腴雪乳与蜜桃臀。戴细黑框眼镜，举手投足温婉贤淑挑不出瑕疵，暗地里却对薄透连裤袜与支配快感怀有极度狂热的痴迷。"}]', '[{"title": "深夜幽暗的走廊与浴室", "desc": "夜深人静，走廊壁灯昏黄，你端着空水杯走出卧室，迎面走来的苏沐晴裙摆下尼龙丝袜摩擦的沙沙细响在寂静中格外清晰。"}]', '{"dialogue_style": "细腻深邃的情感描写，极具沉浸感的人物神态心理博弈与生动对话", "format": "幻诺剧场标准交互规范及.custom-ui手账联动"}', '[{"index": 1, "isUser": false, "scene": "深夜幽暗的走廊与浴室", "story": "<tl>📅时间：关键时刻 | 🌏地点：深夜幽暗的走廊与浴室</tl>\n\n<article>\n<p>凌晨一点，整座温馨的复式公寓陷入沉睡。\n\n你感到口渴走出房门，正撞见刚从浴室走出的苏沐晴。她那头乌黑的长发慵懒地低挽在脑后，细黑框眼镜后是一双永远带着温和笑意的眸子。身上虽穿着居家的过膝长裙与针织开衫，但随着她莲步轻移，裙摆翻飞间，隐隐露出包裹在轻薄灰黑丝袜里的饱满长腿与圆润线条，空气中幽幽散发着沐浴后的清甜水汽与丝袜尼龙特有的微妙气息。\n\n“这么晚还不睡吗？小心明天精神不好哦。”她轻柔一笑，递过手中的温水杯，眼神中却闪过一丝不易察觉的审视与玩味。</p>\n</article>", "branches": [{"tag": "A", "title": "接过水杯并道谢", "desc": "自然接过水杯，目光克制而礼貌地落在她温柔的微笑上"}, {"tag": "B", "title": "目光流连于丝袜长腿", "desc": "直勾勾注视着她裙摆下轻薄透肉的丝袜，试探她的态度与底线"}, {"tag": "C", "title": "低声指出方才的动静", "desc": "若无其事地提起方才浴室里的异样声响，观察她神色间微妙的变化"}]}]', '/* === 半透明毛玻璃效果 - 消息气泡区 === */
/* 用户消息气泡 - 冷调浅蓝毛玻璃 */
#customized-question-content .bg-gray-100\/90 {
  background: rgba(225,138,250, 0.65) !important; /* 浅蓝玻璃底色 */
  backdrop-filter: blur(12px) saturate(180%) !importan; /* 毛玻璃模糊与饱和度增强 */
  -webkit-backdrop-filter: blur(12px) saturate(180%) !important; /* Safari 支持 */
  border-radius: 0.75rem !important; /* 保持圆角 */
  box-shadow:
    inset 0 0 0 1px rgba(255, 255, 255, 0.4), /* 细微白色内边框，模拟玻璃边缘 */
    inset 0 1px 12px rgba(255, 255, 255, 0.3), /* 顶部内发光，增强玻璃厚度感 */
    0 4px给小班20px rgba(160, 195, 220, 0.15) !important; /* 柔和外阴影，提升层次 */
  isolation: isolate !important; /* 为背景动画层准备 */
}

/* AI消息气泡 - 暖调浅粉毛玻璃 */
#customized-answer-content .bg-gray-100\/90 {
  background: rgba(255, 240, 245, 0.65) !important; /* 浅粉玻璃底色 */
  backdrop-filter: blur(12px) saturate(180%) !important;
  -webkit-backdrop-filter: blur(12px) saturate(180%) !important;
  border-radius: 0.75rem !important;
  box-shadow:
    inset 0 0 0 1px rgba(255, 255, 255, 0.4),
    inset 0 1px 12px rgba(255, 255, 255, 0.3),
    0 4px 20px rgba(230, 180, 190, 0.15) !important;
  isolation: isolate !important;
}

/* 确保文本层在毛玻璃背景上清晰可读 */
#customized-question-content .markdown-body,
#customized-answer-content .markdown-body {
  position: relative !important;
  z-index: 1 !important;
  background: transparent !important;
  color: #111827 !important; /* 深灰色文本，对比度已达标 */
}

/* 顶部装饰条融入毛玻璃效果（可选微调） */
#customized-question-content .bg-\[\#c9e1e9\] {
  background: rgba(180, 220, 235, 0.7) !important; /* 调整为半透明 */
  backdrop-filter: blur(4px) !important;
  -webkit-backdrop-filter: blur(4px) !important;
}
#customized-answer-content .bg-\[\#F1CBCB\] {
  background: rgba(240, 200, \"200\", 0.7) !important;
  backdrop-filter: blur(4px) !important;
  -webkit-backdrop-filter: blur(4px) !important;
}

/* 头像容器添加匹配的毛玻璃边框（增强一体性） */
#customized-question-avatar {
  box-shadow:
    0 0 0 2px rgba(255, 255, 255, 0.9),
    inset 0 0 0 2px rgba(225, 240, 250, 0.5) !important;
}
#customized-answer-avatar {
  box-shadow:
    0 0 0 2px rgba(255, 255, 255, 0.9),
    inset 0 0 0 2px rgba(255, 240, 245, 0.5) !important;
}

/* === 响应式与降级处理 === */
/* 移动端适配 */
@media (max-width: 768px) {
  #customized-question-content .bg-gray-100\/90,
  #customized-answer-content .bg-gray-100\/90 {
    backdrop-filter: blur(10px) saturate(160%) !important; /* 略微降低模糊度以保性能 */
    -webkit-backdrop-filter: blur(10px) saturate(160%) !important;
  }
}

/* 动效降级：当用户偏好减少动画时，移除模糊效果，保留半透明背景 */
@media (prefers-reduced-motion: reduce) {
  #customized-question-content .bg-gray-100\/90,
  #customized-answer-content .bg-gray-100\/90,
  #customized-question-content .bg-\[\#c9e1e9\],
  #customized-answer-content .bg-\[\#F1CBCB\] {
    backdrop-filter: none !important;
    -webkit-backdrop-filter: none !important;
  }
}

/* 滚动条美化（与毛玻璃风格协调） */
#customized-question-content::-webkit-scrollbar,
