.card{background-color:var(--color-surface);border:1px solid var(--color-border);border-radius:var(--radius-lg);padding:var(--space-lg);margin-bottom:var(--space-md);box-shadow:var(--shadow-md);transition:transform var(--transition-base) var(--ease-out),box-shadow var(--transition-base) var(--ease-out);}
.card:hover{transform:translateY(-2px);box-shadow:var(--shadow-lg);border-color:var(--color-primary);}
