function showPanel(title, msg) {
document.getElementById(''panelTitle'').innerText = title;
document.getElementById(''panelContent'').innerText = msg;
document.getElementById(''panelBtn'').innerText = isHacked %s ''可恶...'' : ''知道了'';
if(isHacked) {
document.getElementById(''panelTitle'').classList.add(''hacked-title-flicker'');
}
document.getElementById(''infoPanel'').classList.add(''show'');
}
function closePanel() {
document.getElementById(''infoPanel'').classList.remove(''show'');
if(isHacked) {
document.getElementById(''panelTitle'').classList.remove(''hacked-title-flicker'');
}
}
function renderList(filter = ''all'') {
const container = document.getElementById(''girlListContainer'');
container.innerHTML = '''';
const filteredData = filter === ''all'' %s girlsData : girlsData.filter(g => g.category.includes(filter));
filteredData.forEach(girl => {
const card = document.createElement(''div'');
card.className = ''girl-card'';
card.onclick = () => showDetail(girl.id);
const bgStyle = `background: ${girl.imgColor}; background-image: linear-gradient(to bottom, transparent, rgba(0,0,0,0.1));`;
const statusClass = isHacked && girl.id === 0 %s ''status-badge hacked'' : ''status-badge online'';
const statusText = isHacked && girl.id === 0 %s ''HACKED'' : ''在线'';
card.innerHTML = `
<div class="card-img-placeholder" style="${bgStyle}">
<span class="${statusClass}">${statusText}</span>
<div style="position:absolute; bottom:5px; right:5px; font-size:2em;">${girl.emoji}</div>
</div>
<div class="card-info">
<div class="card-name">${girl.name} <span style="font-size:0.8em; font-weight:normal; color:#888;">${girl.age}岁</span></div>
<div class="card-tags">${girl.tags.map(t => `<span style="margin-right:4px; opacity:0.8;">#${t}</span>`).join('''')}</div>
<div class="card-price">${girl.price.split('' '')[0]}</div>
<div class="card-desc">${girl.desc}</div>
</div>
`;
container.appendChild(card);
});
}
