.k-sum:hover{background:linear-gradient(145deg,#909090,#757575);transform:scale(1.02);box-shadow:3px 3px 8px rgba(0,0,0,0.15)}
.k-box{background:#dcdcdc;border-radius:6px;padding:10px;margin-top:8px;font-size:14px;text-align:left;white-space:pre-wrap;line-height:1.6;box-shadow:inset 0 0 10px rgba(0,0,0,0.05);border:1px solid rgba(255,255,255,0.3)}
details[open] .k-box{animation:k-fade 0.4s cubic-bezier(0.4,0,0.2,1)}
.k-img{margin:8px 0;text-align:left;white-space:normal;position:relative}
