<script>
const BG_IMAGE_URL = ''https://catai.wiki/45f46239-62f8-49b2-c71f-7ea2751c6500/w=3000'';
const BGM_URL = ''https://raw.githubusercontent.com/wszqwe/-/49e686bff50762d0792675ed465bd87991fb163a/%E9%8E%96%E9%82%A3%20-%20%E5%BD%BC%E5%A5%B3%E3%81%AF%E6%97%85%E3%81%AB%E5%87%BA%E3%82%8B(1).mp3'';
const TICK_MS = 2000;
const DECAY = { hunger:[1,3], thirst:[1,3], pee:[1,2], poo:[0,2], sleepy:[1,2], dirt:[1,2] };

const $=id=>document.getElementById(id);
const v=id=>{const el=$(id);return el?el.value.trim():''''};

const SFX=(()=>{
  let ctx=null,lastTick=0;
  const ac=()=>{ if(!ctx) ctx=new (window.AudioContext||window.webkitAudioContext)(); if(ctx.state===''suspended'')ctx.resume(); return ctx; };
  function tone(f,o={}){
    const {type=''sine'',dur=.09,vol=.12,delay=0,slide=0}=o;
    try{
      const c=ac(),t=c.currentTime+delay,osc=c.createOscillator(),g=c.createGain();
      osc.type=type;osc.frequency.setValueAtTime(f,t);
      if(slide)osc.frequency.exponentialRampToValueAtTime(slide,t+dur);
      g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(vol,t+.008);
      g.gain.exponentialRampToValueAtTime(.0001,t+dur);
      osc.connect(g).connect(c.destination);osc.start(t);osc.stop(t+dur+.03);
    }catch(e){}
  }
  return{
    pop(){tone(520,{dur:.09,vol:.15,slide:920})},
    click(){tone(340,{type:''triangle'',dur:.06,vol:.1})},
    open(){tone(440,{dur:.1});tone(660,{dur:.13,delay:.07})},
    close(){tone(560,{dur:.09});tone(360,{dur:.12,delay:.07})},
    on(){tone(660,{dur:.08,vol:.13});tone(990,{dur:.13,vol:.13,delay:.06})},
    off(){tone(500,{dur:.08,vol:.11});tone(330,{dur:.11,vol:.1,delay:.06})},
    type(){const n=performance.now();if(n-lastTick<95)return;lastTick=n;tone(1250,{type:''triangle'',dur:.03,vol:.03})},
    good(){[523,659,784,1047].forEach((f,i)=>tone(f,{dur:.13,vol:.12,delay:i*.07}))},
    giggle(){[880,1175,990,1400].forEach((f,i)=>tone(f,{dur:.09,vol:.1,delay:i*.055}))},
    slurp(){tone(300,{dur:.12,vol:.12,slide:520});tone(420,{dur:.1,vol:.1,delay:.1,slide:640})},
    splash(){[700,900,760,980].forEach((f,i)=>tone(f,{type:''triangle'',dur:.07,vol:.08,delay:i*.05}))},
    alarm(){tone(880,{type:''square'',dur:.12,vol:.08});tone(880,{type:''square'',dur:.12,vol:.08,delay:.18})},
    spank(){tone(180,{type:''square'',dur:.08,vol:.14});tone(120,{type:''square'',dur:.12,vol:.1,delay:.12})},
    sad(){[440,392,349,330].forEach((f,i)=>tone(f,{dur:.14,vol:.11,delay:i*.09}))}
  };
})();

let toastTimer=null;
function toast(msg){const t=$(''toast'');t.textContent=msg;t.classList.add(''show'');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove(''show''),2400);}

/* ===== 浮动对话气泡开关与系统 ===== */
let speechEnabled = true;
let speechTimer=null, lastSpeechTime=0, speechQueue=[];

const msgToggleBtn = $(''msgToggleBtn'');
msgToggleBtn.addEventListener(''click'', ()=>{
  speechEnabled = !speechEnabled;
  msgToggleBtn.textContent = speechEnabled ? ''💬'' : ''🔕'';
  if(speechEnabled){
    toast(''💬 崽崽提示已开启'');
    SFX.open();
  } else {
    $(''speechBubble'').classList.remove(''show'');
    speechQueue = [];
    toast(''🔕 崽崽提示已关闭'');
    SFX.close();
  }
});

function showSpeech(text, type=''normal'', emoji=''💬'', duration=3200){
  if(!speechEnabled) return;
  const now=Date.now();
  // 如果距离上次显示太近，加入队列
  if(now-lastSpeechTime<1200){
    speechQueue.push({text,type,emoji,duration});
    return;
  }
  lastSpeechTime=now;
  const bub=$(''speechBubble'');
  bub.classList.remove(''show'',''warn'',''crit'');
  bub.innerHTML=`<span class="emo">${emoji}</span>${text}`;
  if(type===''warn'')bub.classList.add(''warn'');
  if(type===''crit'')bub.classList.add(''crit'');
  requestAnimationFrame(()=>bub.classList.add(''show''));
  clearTimeout(speechTimer);
  speechTimer=setTimeout(()=>{
    bub.classList.remove(''show'');
    // 处理队列
    setTimeout(()=>{
      if(speechQueue.length>0 && speechEnabled){
        const next=speechQueue.shift();
        showSpeech(next.text,next.type,next.emoji,next.duration);
      }
    },400);
  },duration);
}

const BGM=(()=>{
  const btn=$(''bgmBtn'');
  let audio=null,on=true,pending=true;
  if(BGM_URL){
    audio=new Audio(BGM_URL);audio.loop=true;audio.volume=.55;audio.preload=''auto'';
    audio.addEventListener(''play'',()=>{btn.classList.add(''playing'');});
    audio.addEventListener(''pause'',()=>btn.classList.remove(''playing''));
    audio.addEventListener(''error'',()=>{toast(''❌ 音乐加载失败，请检查链接'');});
  }
  function paint(){btn.textContent=on?''🎶'':''🔇'';}
  function play(){if(!audio||!on)return;const p=audio.play();if(p&&p.catch){p.catch(()=>{pending=true;});}}
  function tryStart(){if(!on||!audio)return;pending=false;play();}
  const kick=()=>{if(pending&&on){tryStart();}document.removeEventListener(''pointerdown'',kick);document.removeEventListener(''keydown'',kick);document.removeEventListener(''touchstart'',kick);};
  document.addEventListener(''pointerdown'',kick);document.addEventListener(''keydown'',kick);document.addEventListener(''touchstart'',kick);
  if(audio){play();}
  paint();
  btn.addEventListener(''click'',()=>{
    if(!audio){toast(''❌ 没有配置音乐'');return;}
    on=!on;paint();
    if(on){play();toast(''🎵 音乐已开启'');SFX.open();}
    else{audio.pause();btn.classList.remove(''playing'');toast(''🔇 音乐已暂停'');SFX.close();}
  });
  return{};
})();

