let curView=''view-home'';
function show(id){
  if(curView===id)return;
  curView=id;
  document.querySelectorAll(''.view'').forEach(v=>v.classList.remove(''on''));
  $(id).classList.add(''on'');
  document.querySelectorAll(''.sbtn'').forEach(b=>b.classList.toggle(''on'',b.dataset.v===id));
  window.scrollTo({top:0,behavior:''smooth''});
  SFX.pop();
  if(id===''view-baby'')renderBaby();
  if(id===''view-report'')update();
}
document.querySelectorAll(''.sbtn[data-v]'').forEach(b=>{
  b.addEventListener(''click'',()=>show(b.dataset.v));
});

