function worstNeed(){
  let w=null,score=-1;
  NEEDS.forEach(s=>{
    if(s.v>score){score=s.v;w=s;}
  });
  return{need:w,score};
}
function nowStr(){const d=new Date(),p=n=>String(n).padStart(2,''0'');return `${p(d.getHours())}:${p(d.getMinutes())}`;}
function log(msg){
  const li=document.createElement(''li'');
  li.innerHTML=`<span class="lt">[${nowStr()}]</span>${msg}`;
  const list=$(''logList'');list.prepend(li);
  while(list.children.length>6)list.lastChild.remove();
}

// 检查阈值并发出语音提醒（只在跨越阈值时触发，避免刷屏）
function checkThresholds(){
  NEEDS.forEach(s=>{
    const v=s.v;
    let level=0;
    if(v>=90) level=3;
    else if(v>=70) level=2;
    else if(v>=50) level=1;
    
    if(level>warnLevel[s.k]){
      // 等级上升，触发语音
      const speeches=SPEECH[s.k];
      let pool, type, emoji;
      if(level===3){
        pool=speeches.crit; type=''crit''; emoji=''🚨'';
      } else if(level===2){
        pool=speeches.warn; type=''warn''; emoji=''⚠️'';
      } else {
        pool=speeches.mild; type=''normal''; emoji=s.label.slice(0,2);
      }
      const msg=pool[Math.floor(Math.random()*pool.length)];
      showSpeech(msg, type, emoji, level===3?4500:3500);
    }
    warnLevel[s.k]=level;
  });
}

function renderBaby(){
  let critAny=false,warnAny=false;
  NEEDS.forEach(s=>{
    s.fill.style.width=s.v+''%'';s.valEl.textContent=Math.round(s.v);
    const warn=s.v>=70,crit=s.v>=90;
    s.row.classList.toggle(''warn'',crit);
    if(crit)critAny=true;else if(warn)warnAny=true;
  });
  $(''favFill'').style.width=fav+''%'';$(''favVal'').textContent=fav;
  const k=$(''kiddo'');
  if(!k.classList.contains(''happy'')&&!k.classList.contains(''spanked'')){
    k.classList.toggle(''crying'',critAny);
    k.classList.toggle(''worried'',!critAny&&warnAny);
  }
  checkThresholds();
  $(''babyBadge'').classList.toggle(''show'',critAny);
}
function babyTick(){
  NEEDS.forEach(s=>{
    const [a,b]=DECAY[s.k];
    const d=a+Math.floor(Math.random()*(b-a+1));
    const before=s.v;
    s.v=Math.max(0,Math.min(100,s.v+d));
    if((s.k===''pee''||s.k===''poo'')&&before<100&&s.v>=100){
      s.v=15;
      const dirt=NEEDS.find(x=>x.k===''dirt'');
      dirt.v=Math.min(100,dirt.v+50);
      fav=Math.max(0,fav-2);
      const evtMsg=s.k===''pee''?''💦 糟糕！崽崽没忍住尿湿了裤兜，身上脏污度大增！快带去洗香香！'':''💩 糟糕！崽崽拉在裤兜里了，小脸通红，快去洗香香！'';
      log(evtMsg);
      toast(s.k===''pee''?''💦 尿裤兜了！快去照顾崽崽！'':''💩 拉裤兜了！快去照顾崽崽！'');
      showSpeech(s.k===''pee''?''呜呜呜……没憋住……尿尿了……小裤裤湿湿的好难受……'':''呜呜呜……臭臭拉在裤裤里了……好丢脸……'', ''crit'',''😭'',4000);
      SFX.alarm();if(navigator.vibrate)navigator.vibrate(180);
    }
  });
  if(curView===''view-baby'')renderBaby();
  else $(''babyBadge'').classList.toggle(''show'',worstNeed().score>=90);
}
