    <footer><a href="https://aitrader.wiki/zh/explore/installed/813e225e-2a1a-45bd-b441-f4741dff5418" target="_blank"></a></footer>
    <div id="toast" class="toast">信息已成功复制！</div>

    <script>
        // ============================================================
        // 1. Tab 切换
        // ============================================================
        function switchTab(tabId) {
            document.querySelectorAll(''.tab-content'').forEach(t => t.classList.remove(''active''));
            document.querySelectorAll(''.tab-btn'').forEach(b => b.classList.remove(''active''));
            document.getElementById(tabId).classList.add(''active'');
            // 通过 event 获取当前按钮
            const btns = document.querySelectorAll(''.tab-btn'');
            for (const btn of btns) {
                if (btn.textContent.includes(tabId.replace(''tab-'', '''').replace(''-'', '' '')) ||
                    (tabId === ''tab-world'' && btn.textContent.includes(''世界观'')) ||
                    (tabId === ''tab-chars'' && btn.textContent.includes(''核心人物'')) ||
                    (tabId === ''tab-form'' && btn.textContent.includes(''入学档案''))) {
                    btn.classList.add(''active'');
                    break;
                }
            }
            // 如果上述匹配失败，用备用方法
            if (!document.querySelector(''.tab-btn.active'')) {
                const map = { ''tab-world'': 0, ''tab-chars'': 1, ''tab-form'': 2 };
                const idx = map[tabId] || 0;
                const allBtns = document.querySelectorAll(''.tab-btn'');
                if (allBtns[idx]) allBtns[idx].classList.add(''active'');
            }
            // 关闭所有自定义下拉
            closeAllDropdowns();
        }

        // ============================================================
        // 2. 自定义下拉组件
        // ============================================================
        (function initCustomSelects() {
            const selects = document.querySelectorAll(''.custom-select'');

            // 点击外部关闭所有下拉
            document.addEventListener(''click'', function(e) {
                const target = e.target.closest(''.custom-select'');
                if (!target) {
                    closeAllDropdowns();
                }
            });

            // 触摸滚动时关闭下拉（提升移动端体验）
            document.addEventListener(''touchmove'', function(e) {
                const target = e.target.closest(''.custom-select-dropdown'');
                if (!target) {
                    closeAllDropdowns();
                }
            }, { passive: true });

            selects.forEach(function(container) {
                const trigger = container.querySelector(''.custom-select-trigger'');
                const dropdown = container.querySelector(''.custom-select-dropdown'');
                const options = dropdown.querySelectorAll(''.option'');
                const customInputId = container.dataset.customInput;
                const customWrapper = document.getElementById(customInputId + ''_wrapper'');

                // 点击触发器
                trigger.addEventListener(''click'', function(e) {
                    e.stopPropagation();
                    const isOpen = dropdown.classList.contains(''open'');
                    closeAllDropdowns();
                    if (!isOpen) {
                        dropdown.classList.add(''open'');
                        trigger.querySelector(''.arrow'').classList.add(''open'');
                    }
                });

                // 键盘支持（Enter / Space）
                trigger.addEventListener(''keydown'', function(e) {
                    if (e.key === ''Enter'' || e.key === '' '') {
                        e.preventDefault();
                        trigger.click();
                    }
                });

                // 选项点击
                options.forEach(function(opt) {
                    opt.addEventListener(''click'', function(e) {
                        e.stopPropagation();
                        const value = opt.dataset.value;
                        const label = opt.textContent.trim();

                        // 更新触发器
                        const valueSpan = trigger.querySelector(''.value'');
                        valueSpan.textContent = label;
                        trigger.classList.remove(''placeholder'');

                        // 标记选中
                        options.forEach(o => o.classList.remove(''selected''));
                        opt.classList.add(''selected'');

                        // 关闭下拉
                        dropdown.classList.remove(''open'');
                        trigger.querySelector(''.arrow'').classList.remove(''open'');

                        // 处理自定义输入
                        if (value === ''custom'') {
                            if (customWrapper) {
                                customWrapper.classList.add(''show'');
                                // 聚焦输入框
                                const inp = customWrapper.querySelector(''input'');
                                if (inp) setTimeout(function() { inp.focus(); }, 100);
                            }
                            // 存储特殊标记
                            container.dataset.customMode = ''true'';
                        } else {
                            if (customWrapper) {
                                customWrapper.classList.remove(''show'');
                            }
                            container.dataset.customMode = ''false'';
                            // 存储选中值
                            container.dataset.selectedValue = value;
                        }

                        // 触发 change 事件（兼容旧逻辑）
                        const evt = new Event(''change'', { bubbles: true });
                        container.dispatchEvent(evt);
                    });
                });

                // 如果已经选中了某个值（恢复状态）
                const selectedOpt = dropdown.querySelector(''.option.selected'');
                if (selectedOpt) {
                    const val = selectedOpt.dataset.value;
                    if (val === ''custom'') {
                        if (customWrapper) customWrapper.classList.add(''show'');
                        container.dataset.customMode = ''true'';
                    } else {
                        container.dataset.selectedValue = val;
                    }
                    trigger.querySelector(''.value'').textContent = selectedOpt.textContent.trim();
                    trigger.classList.remove(''placeholder'');
                }

                // 自定义输入框内容变化时，同步更新显示
                if (customWrapper) {
                    const inp = customWrapper.querySelector(''input'');
                    if (inp) {
                        inp.addEventListener(''input'', function() {
                            if (container.dataset.customMode === ''true'') {
                                const val = this.value.trim() || ''✎ 自定义...'';
                                trigger.querySelector(''.value'').textContent = val;
                            }
                        });
                        // 失焦时如果为空，恢复显示
                        inp.addEventListener(''blur'', function() {
                            if (container.dataset.customMode === ''true'' && !this.value.trim()) {
                                trigger.querySelector(''.value'').textContent = ''✎ 自定义...'';
                            }
                        });
                    }
                }
            });

            // 辅助：关闭所有下拉
            window.closeAllDropdowns = function() {
                document.querySelectorAll(''.custom-select-dropdown'').forEach(d => {
                    d.classList.remove(''open'');
                });
                document.querySelectorAll(''.custom-select-trigger .arrow'').forEach(a => {
                    a.classList.remove(''open'');
                });
            };

            // 辅助：获取自定义下拉的值
            window.getCustomSelectValue = function(container) {
                const isCustom = container.dataset.customMode === ''true'';
                if (isCustom) {
                    const customInputId = container.dataset.customInput;
                    const wrapper = document.getElementById(customInputId + ''_wrapper'');
                    if (wrapper) {
                        const inp = wrapper.querySelector(''input'');
                        if (inp && inp.value.trim()) {
                            return inp.value.trim();
                        }
                    }
                    // 如果自定义输入为空，返回 "自定义"
                    return ''自定义'';
                }
                return container.dataset.selectedValue || '''';
            };

            // 辅助：获取下拉显示文本
            window.getCustomSelectDisplay = function(container) {
                const trigger = container.querySelector(''.custom-select-trigger'');
                const span = trigger.querySelector(''.value'');
                return span %s span.textContent : '''';
            };
        })();

        // ============================================================
        // 3. 生成档案 (适配自定义下拉)
        // ============================================================
        function generateProfile() {
            const name = document.getElementById(''p_name'').value.trim() || ''无名氏'';
            const age = document.getElementById(''p_age'').value.trim() || ''未填写'';
            const extra = document.getElementById(''p_extra'').value.trim() || ''无'';

            // 从自定义下拉获取值
            const genderContainer = document.querySelector(''.custom-select[data-field="gender"]'');
            const persContainer = document.querySelector(''.custom-select[data-field="pers"]'');
            const appContainer = document.querySelector(''.custom-select[data-field="app"]'');
            const lowerContainer = document.querySelector(''.custom-select[data-field="lower"]'');

            const gender = getCustomSelectValue(genderContainer) || ''未选择'';
            const pers = getCustomSelectValue(persContainer) || ''未选择'';
            const app = getCustomSelectValue(appContainer) || ''未选择'';
            const lower = getCustomSelectValue(lowerContainer) || ''未选择'';

            // 如果值为空，用显示文本
            const genderDisplay = gender || getCustomSelectDisplay(genderContainer) || ''未选择'';
            const persDisplay = pers || getCustomSelectDisplay(persContainer) || ''未选择'';
            const appDisplay = app || getCustomSelectDisplay(appContainer) || ''未选择'';
            const lowerDisplay = lower || getCustomSelectDisplay(lowerContainer) || ''未选择'';

            const opening = `【开场剧情】
        你穿过校门更衣室，走过满是异样目光的校园道路，全身赤裸地踏入教室，面对讲台下三十具青春靓丽的全裸女体。`;

            const output = `【圣伊甸贵族女子学园 - 唯一男性档案】
        ============================
        [基本信息]
        姓名：${name}
        年龄：${age}
        性别认知：${genderDisplay}

        [特质面板]
        性格特征：${persDisplay}
        外貌特征：${appDisplay}
        下身描述：${lowerDisplay}

        [附加设定]
        ${extra}
        ============================
        ※ 注：该生已了解并同意遵守本校"入校即脱衣"及"共用女卫/浴室"之绝对校规。

        ${opening}`;

            document.getElementById(''preview_output'').value = output;
        }

        // ============================================================
        // 4. 复制档案
        // ============================================================
        function copyProfile() {
            const preview = document.getElementById(''preview_output'');
            if (!preview.value.trim()) {
                alert(''请先生成档案！'');
                return;
            }
            // 使用 modern API
            if (navigator.clipboard && navigator.clipboard.writeText) {
                navigator.clipboard.writeText(preview.value).then(function() {
                    showToast(''信息已成功复制！'');
                }).catch(function() {
                    fallbackCopy(preview);
                });
            } else {
                fallbackCopy(preview);
            }
        }

        function fallbackCopy(textarea) {
            textarea.select();
            textarea.setSelectionRange(0, 99999);
            try {
                document.execCommand(''copy'');
                showToast(''信息已成功复制！'');
            } catch (e) {
                alert(''复制失败，请手动复制。'');
            }
        }

        function showToast(msg) {
            const toast = document.getElementById(''toast'');
            toast.textContent = msg || ''信息已成功复制！'';
            toast.style.display = ''block'';
            clearTimeout(toast._timer);
            toast._timer = setTimeout(function() {
                toast.style.display = ''none'';
            }, 2000);
        }

        // ============================================================
        // 5. 兼容旧版的 toggleCustom (保留，但不再使用)
        // ============================================================
        // 旧版函数保留，但自定义下拉已经内置了逻辑
        function toggleCustom(selectObj, inputId) {
            // 不再使用，保留空函数避免报错
        }

        // ============================================================
        // 6. 初始化：如果有默认选中状态，恢复
        // ============================================================
        document.addEventListener(''DOMContentLoaded'', function() {
            // 检查是否有预选值
            document.querySelectorAll(''.custom-select'').forEach(function(container) {
                const selected = container.querySelector(''.option.selected'');
                if (selected) {
                    const trigger = container.querySelector(''.custom-select-trigger'');
                    trigger.querySelector(''.value'').textContent = selected.textContent.trim();
                    trigger.classList.remove(''placeholder'');
                    if (selected.dataset.value === ''custom'') {
                        const customId = container.dataset.customInput;
                        const wrapper = document.getElementById(customId + ''_wrapper'');
                        if (wrapper) wrapper.classList.add(''show'');
                        container.dataset.customMode = ''true'';
                    } else {
                        container.dataset.selectedValue = selected.dataset.value;
                        container.dataset.customMode = ''false'';
                    }
                }
            });
        });

        // 解决切换tab时dropdown残留
        document.addEventListener(''click'', function(e) {
            if (!e.target.closest(''.custom-select'')) {
                closeAllDropdowns();
            }
        });

        console.log(''✅ 圣伊甸入学系统已加载 (自定义下拉组件 v2.0)'');
    </script>

</body>
</html>', '校园', '2026-09-15 15:03:14', '2026-09-15 15:03:14', '', '', '[]', '') ON CONFLICT (id) DO NOTHING;
INSERT INTO stories (id, title, badge, cover_icon, cover_title, cover_subtitle, logo, theme_color, btn_gradient, handbook_json, roles_json, scenes_json, styles_json, first_turn_demo_json, custom_css, custom_html, category, created_at, updated_at, system_prompt, status_template, lorebook_json, post_history_instructions) VALUES ('deck_pure_love_childhood_friend', '与傲娇青梅的纯爱日常💗', '青梅竹马 · 甜宠纯爱', '🌸', '青梅竹马', '与傲娇青梅苏晚晴从小到大的纯爱物语', '🌸', '#ec4899', 'linear-gradient(135deg, #ec4899 0%, #f472b6 100%)', '{"title": "与傲娇青梅的纯爱日常💗", "desc": "与笨蛋傲娇青梅苏晚晴从小到大的日常生活：从幼儿园小学对我有极强占有欲的孩子王，到初中意识到感情的温柔文静，再到高中傲娇毒舌却一心一意的校花，大学患得患失占有欲爆棚的知性少女。这是一段纯粹的纯爱故事，没有背叛与出轨，步步走向专属幸福。", "bg_image": "https://catai.wiki/639e4482-7a6e-4fa7-1647-807a51344000/bg", "opening_options": ["【高中校花·放学等候】：“背着单肩书包在校门口梧桐树下等你，气鼓鼓地塞给你一盒温热的红豆派：‘笨蛋，才不是特意买给你的呢！买一送一多出来的而已！’”", "【大学租房·同居患得患失】：“坐在出租屋地毯上整理合照相册，抬头咬着下唇望向你：‘喂……今天联谊会上的那个学妹，你加她微信了没有？’”", "【初中雨天·同撑一把伞】：“细雨蒙蒙中小心翼翼地把雨伞往你那边倾斜，自己半边肩膀被雨淋湿，耳垂通红低着头不敢看你。”", "【小学霸道·孩子王保护】：“双手叉腰挡在你身前，凶巴巴地把抢你橡皮擦的男同学推开：‘你敢欺负他？他可是我罩着的！’”"]}', '[{"name": "苏晚晴", "role": "邻居青梅竹马 (傲娇/深情/专属独占)", "desc": "从小住在你家对门的邻居青梅。容貌清丽绝伦，高中时及腰长发、身材高挑窈窕，是公认的校花级女神。外表嘴硬要强，经常用毒舌掩饰害羞，实际上日记本里密密麻麻全写满了你，家里藏着装满从小到大回忆物件的宝盒。"}, {"name": "男主 (玩家)", "role": "青梅竹马的命定唯一", "desc": "与苏晚晴一起长大的邻家竹马，深知晚晴所有逞强与脆弱的小习惯，在温柔包容与坏心眼挑逗中逐步攻破傲娇心防。"}]', '[{"title": "🏫 高中校门外 · 梧桐树下的红豆派", "desc": "高二秋季放学时分，夕阳如金。苏晚晴站在校门侧的梧桐树阴影里，踩着落叶不耐烦地等待，手心紧紧捂着还冒着热气的红豆派。"}, {"title": "🏠 大学温馨合租公寓 · 深夜沙发", "desc": "温馨的双人小公寓，地暖散发着融融暖意。晚晴盘腿坐在地毯上，抱着毛绒熊抱枕，偷偷斜眼打量你的手机屏幕。"}]', '{"dialogue_style": "轻快细腻的青春恋爱小说风，充满生动的傲娇小动作与心理反差推拉", "format": "AI风月标准双栏规范及.custom-ui样式"}', '[{"index": 1, "isUser": false, "scene": "🏫 高中校门外 · 梧桐树下的红豆派", "story": "<tl>📅时间：高二秋季 17:35 | 🌏地点：圣华中学东门梧桐道 | 🍁天气：晴朗秋风</tl>\n\n<article>\n<p>放学的钟声回荡在校园上空，漫天梧桐黄叶在金色斜阳下打着旋儿飘落。你在校门口张望，一眼便望见了树荫下的那一抹熟悉高挑的身影。</p>\n\n<p>苏晚晴正单脚轻踢着路牙石，海风吹拂着她乌黑柔顺的及腰长发，清冷精致的侧脸在落日余晖中仿佛发着光。那是整座高中公认不可侵犯的高岭校花，但此刻，当她的视线捕捉到你走过来的身影时，那双清亮的杏眼骤然亮了一瞬，随即又极其刻意地板起了俏脸。</p>\n\n<p><w>“……大笨蛋！你到底在教室里磨蹭什么啊？！害本姑娘在冷风里足足吹了十五分钟！”</w></p>\n\n<p>她踩着小皮鞋快步走上前，一把将怀里紧紧捂着的小纸袋用力塞进你的怀中。隔着薄薄的油纸，依然能感受到滚烫香甜的红豆派温度。她飞快地别过通红发烫的耳垂，假装漫不经心地哼了一声：</p>\n\n<p><w>“别、别误会了！校门口甜品店刚好第二份半价而已，我只是不想浪费粮食才顺手买的！你要是不喜欢吃就直接扔垃圾桶好了……不准笑！再笑今天我就不让你抄数学作业了！”</w></p>\n</article>\n\n<opt>\n<suggested_questions>\n<d>A. 【轻捏耳垂·坏笑调侃】：伸手接过红豆派咬了一大口，顺势凑近轻捏她发烫的耳尖：“哇，好甜！晚晴特意排队买的爱心甜点，我怎么舍得扔呢？”【策略评估：直接戳破她的傲娇掩饰，极易引发少女羞愤小粉拳与心跳狂飙】</d>\n<d>B. 【温柔体贴·分她一半】：微笑着将红豆派掰成两半，将还冒着热气的那一半递到她唇边：“正好肚子饿了。天气这么凉，晚晴也咬一口暖暖身子吧。”【策略评估：以宠溺温柔打破防备，直击少女内心最柔软的被爱渴望】</d>\n<d>C. 【故作嫌弃·反向拉扯】：挑了挑眉把纸袋还给她：“真可惜，我今天答应了后桌女同学去吃奶茶，红豆派恐怕吃不下了呢。”【策略评估：剧烈激起占有欲与酸涩醋意，让她瞬间从傲娇破防为焦急质问】</d>\n<d>D. 【牵起小手·并肩回家】：顺势一把牵住她被风吹凉的纤细小手揣进自己的暖和外套口袋里，迈步往前走：“走啦，今晚叔叔阿姨不在家，想吃我煮的西红柿鸡蛋面吗？”【策略评估：跨越社交距离的高甜肢体接触，大幅拉满依赖感与纯爱甜蜜度】</d>\n</suggested_questions>\n</opt>", "branches": [{"tag": "A", "title": "轻捏耳垂坏笑调侃", "desc": "直接戳破她的傲娇掩饰，引发羞愤娇嗔与心跳飙升"}, {"tag": "B", "title": "温柔体贴分她一半", "desc": "以宠溺温柔打破防备，直击少女柔软内心"}, {"tag": "C", "title": "故作嫌弃反向拉扯", "desc": "激发独占欲与醋意，打破高傲防线"}, {"tag": "D", "title": "牵起小手并肩回家", "desc": "跨越社交距离的亲密牵手，甜蜜值拉满"}]}]', '', '', '💎 甜宠恋爱', '2026-09-22 11:47:43', '2026-09-22 11:47:43', '', '', '[]', '') ON CONFLICT (id) DO NOTHING;
INSERT INTO stories (id, title, badge, cover_icon, cover_title, cover_subtitle, logo, theme_color, btn_gradient, handbook_json, roles_json, scenes_json, styles_json, first_turn_demo_json, custom_css, custom_html, category, created_at, updated_at, system_prompt, status_template, lorebook_json, post_history_instructions) VALUES ('deck_rin_raw', '【原貌白模】雨夜便利店的离家少女 · 原始未美化版', '⚪ 原始白模 · 未加正则/CSS', '🌧️', '雨夜便利店的离家少女', '原始输出样式 · 纯文本状态栏与原生标签体验', '🌧️', 'slate', 'from-gray-700 to-slate-800', '{"audience": ["想观察大模型原生输出格式、未加正则替换与内置CSS的创作者与玩家"], "tips": ["【对比测试】：本卡刻意去除了任何正则替换与自定义CSS皮肤，呈现平台最朴素的默认渲染效果。", "【排版特点】：状态栏为原生灰扑扑的details标签，多行选项在未加CSS时容易出现排版紧缩。"], "quote": "“别看了……我没有偷东西，只是在避雨而已。买得起关东煮的钱我还是有的。”"}', '[{"name": "星野凛 (Hoshino Rin)", "role": "女主角 · 离家出走的高二少女", "desc": "17岁，原本是私立名校的优等生，因无法承受母亲窒息的高压掌控，在暴雨夜砸碎了存钱罐离家出走。全身湿透，穿着打湿的水手服，神情像一只受惊却呲牙防备的野猫。", "avatar": "https://api.dicebear.com/7.x/bottts/svg%sseed=rin_raw"}, {"name": "值班店员 / 避难者", "role": "玩家视角", "desc": "深夜两点在全家便利店值班的年轻店员，面对这个缩在垃圾桶旁和关东煮货架夹缝中发抖的陌生少女。", "avatar": "https://api.dicebear.com/7.x/bottts/svg%sseed=clerk"}]', '[{"name": "深夜2:15 全家便利店靠窗散座", "desc": "外侧暴雨如注，霓虹灯被雨水晕染成模糊的光晕。便利店冷气很足，关东煮冒着微弱的热气。"}]', '["自然现实主义", "疏离与防备", "原生未美化排版"]', '{"status": "【状态：凌晨02:15 暴雨夜 | 凛的体温：失温颤抖 | 警惕度：90%（随时准备逃跑） | 食物：一碗快凉掉的白萝卜和魔芋丝】", "story": "凌晨两点十五分，暴雨疯狂砸在便利店巨大的落地玻璃窗上，将街对面的霓虹招牌冲刷成一片斑驳扭曲的色块。\n\n门上的电子迎宾铃「叮咚——欢迎光临」已经三个小时没有响过了。店内老旧的空调送风口正呼呼地吐着冷气，空气里弥漫着关东煮高汤和廉价关东煮蒸发出来的甜咸气味。\n\n在靠窗最狭窄的垃圾分类桶旁边，那个一个小时前冲进来的少女依旧缩在塑料圆凳上。\n\n她浑身都湿透了。藏青色的水手服短裙黏在白皙却冻得发青的大腿上，额前被雨水打湿的齐刘海下一双杏眼死死盯着面前那碗早已不再冒热气的关东煮。在她脚边，一个掉漆的帆布双肩包正不断往地板砖上滴着水，洇开了一大片水渍。\n\n当你端着热茶走近时，她像被踩到尾巴的野猫一样猛地瑟缩了一下身子，纤细的手指一把抓紧了双肩包的肩带，苍白的嘴唇抿成一条紧绷的直线：\n\n「别过来……！\n我、我买了关东煮的，小票还在桌子上！我没有霸占你们的座位，等雨停了……雨停了我马上就走！」\n\n她说话时牙齿在轻微打颤，湿漉漉的黑色水手服领口下，那根褪色的红领巾随着她急促的呼吸微微起伏。她显然在竭力维持着凶狠冷淡的防备姿态，可冻得发红的鼻尖和眼眶里的湿气却出卖了她此刻的无助。", "rawOutputSnippet": "<details>\n<summary>📊 实时物理与心理状态</summary>\n- 当前位置：便利店靠窗角落塑料凳\n- 衣着状态：水手服全湿（黏在皮肤上）\n- 体能状态：轻度失温，双肩微颤\n- 心理防备：90%（将店员视作潜在驱赶者或警察同伙）\n- 随身物品：湿透的双肩包（含学生证、存钱罐碎银与未关机的手机）\n</details>\n\n<suggested_questions>\n【递毛巾】：“擦擦吧，制服全湿了会着凉的。我不会赶你走。”\n【送热关东煮】：“这碗已经凉了，我帮你换一份刚煮好的热高汤吧。”\n【试探询问】：“现在已经凌晨两点了，给家里人报个平安比较好哦。”\n【保持距离】：“我就在前台，有需要的话随时喊我。”\n</suggested_questions>", "userAction": "我从柜台拿了一条干净的员工毛巾和一杯热大麦茶，没有直接走近，而是隔着一个座位的距离轻轻放下：“毛巾是干净的，大麦茶免费，你先擦擦头发吧。”", "actionChoices": ["【递毛巾】：“擦擦吧，制服全湿了会着凉的。我不会赶你走。”", "【送热关东煮】：“这碗已经凉了，我帮你换一份刚煮好的热高汤吧。”", "【试探询问】：“现在已经凌晨两点了，给家里人报个平安比较好哦。”", "【保持距离】：“我就在前台，有需要的话随时喊我。”"]}', NULL, '<!DOCTYPE html>
<html lang="zh-CN">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>【原貌白模】雨夜便利店的离家少女 · 原始未美化版</title>
<link href="https://fonts.googleapis.com/css2%sfamily=Noto+Serif+SC:wght@400;600;700&display=swap" rel="stylesheet">
<style>
    :root{
        --soft-white:#ffffff;
        --cream-bg:#fdfcf8;
        --accent-gold:#d4a373;
        --accent-purple:#9d8ec7;
        --text-dark:#2d2d2d;
        --text-gray:#6d6d6d;
        --border-color:#efe6ff;
        --shadow:0 12px 42px rgba(120,90,160,0.10);
        --shadow-soft:0 6px 20px rgba(120,90,160,0.07);
    }
    *{box-sizing:border-box;}
    html,body{margin:0;padding:0;}
    body{
        font-family:''Noto Serif SC'',"PingFang SC","Microsoft YaHei",serif;
        background:linear-gradient(180deg,#fdfcf8 0%,#f7f2ff 45%,#fdfcf8 100%);
        color:var(--text-dark);
        line-height:1.85;
        padding:18px 14px 60px;
        -webkit-font-smoothing:antialiased;
    }
    .page{max-width:880px;margin:0 auto;}
    .hero{
        position:relative;
        text-align:center;
        padding:46px 24px 40px;
        background:linear-gradient(135deg,#fff7f0 0%,#f6ecff 55%,#fdfcf8 100%);
        border-radius:30px;
        border:1px solid var(--border-color);
        box-shadow:var(--shadow);
        margin-bottom:24px;
        overflow:hidden;
    }
    .hero-tag{
        position:relative;
        display:inline-block;
        background:linear-gradient(135deg,#f3e8ff,#faedcd);
        color:#7c6bb0;
        padding:7px 20px;
        border-radius:999px;
        font-size:12.5px;
        letter-spacing:3px;
        font-weight:600;
        border:1px solid #ead9ff;
    }
    .hero h1{
        position:relative;
        font-size:28px;
        letter-spacing:1.5px;
        margin:20px 0 10px;
        color:#332b4d;
    }
    .hero .hero-sub{
        position:relative;
        color:var(--accent-purple);
        font-size:14px;
        letter-spacing:3px;
        margin:0;
    }
    .hero .hero-line{
        position:relative;
        width:60px;height:2px;
        background:linear-gradient(90deg,transparent,var(--accent-gold),transparent);
        margin:18px auto 0;
    }
    .card{
        background:var(--soft-white);
        border-radius:24px;
        padding:28px 26px;
        margin-bottom:22px;
        box-shadow:var(--shadow-soft);
        border:1px solid #f2edfb;
    }
    .section-title{
        display:flex;
        align-items:center;
        gap:12px;
        font-size:18.5px;
        font-weight:700;
        color:#3a3350;
        margin:0 0 18px;
        letter-spacing:1px;
    }
    .section-title::before{
        content:"";
        width:6px;height:22px;
        border-radius:4px;
        background:linear-gradient(180deg,var(--accent-purple),var(--accent-gold));
        display:inline-block;
    }
    .section-sub{
        color:var(--text-gray);
        font-size:13px;
        margin:-10px 0 16px;
    }
    p{margin:0 0 14px;}
    .story-text{color:#4a4458;font-size:15px;line-height:1.9;white-space:pre-line;}
    .profile-grid{
        display:grid;
        grid-template-columns:repeat(auto-fit,minmax(240px,1fr));
        gap:16px;
    }
    .p-item{
        background:linear-gradient(160deg,#fdfbff,#fff9f2);
        border:1px solid #f0eafc;
        border-radius:18px;
        padding:18px 20px;
        transition:.25s;
    }
    .p-item:hover{transform:translateY(-3px);box-shadow:var(--shadow-soft);}
    .p-item h4{
        margin:0 0 10px;
        font-size:15px;
        color:var(--accent-purple);
        display:flex;align-items:center;gap:8px;
    }
    .p-item h4 .dot{
        width:8px;height:8px;border-radius:50%;
        background:var(--accent-gold);
        display:inline-block;
    }
    .p-item p{margin:0;font-size:13.5px;color:#5a5468;line-height:1.75;}
    .mech-list{list-style:none;padding:0;margin:0;}
    .mech-list li{
        display:flex;gap:14px;
        padding:14px 16px;
        border-radius:16px;
        background:#fbf9ff;
        border:1px solid #f1ebfc;
        margin-bottom:12px;
        font-size:13.5px;color:#544e64;
        align-items:flex-start;
    }
    .mech-list li .badge{
        flex:0 0 auto;
        font-size:11.5px;
        font-weight:700;
        padding:4px 10px;
        border-radius:999px;
        background:linear-gradient(135deg,#f3e8ff,#faedcd);
        color:var(--accent-purple);
        letter-spacing:1px;
    }
    .form-grid{
        display:grid;
        grid-template-columns:repeat(auto-fit,minmax(220px,1fr));
        gap:16px;
    }
    .field{display:flex;flex-direction:column;gap:7px;}
    .field label{font-size:13.5px;font-weight:600;color:#5f5873;}
    .field input,.field textarea{
        font-family:inherit;font-size:14px;color:#3d374d;
        background:#fdfcff;border:1.5px solid #ece5fa;border-radius:14px;
        padding:12px 14px;outline:none;transition:.2s;
    }
    .field input:focus,.field textarea:focus{
        border-color:#c9b6ec;background:#fff;
        box-shadow:0 0 0 4px rgba(157,142,199,0.12);
    }
    .full{grid-column:1/-1;}
    .opening-list{display:flex;flex-direction:column;gap:14px;margin-bottom:20px;}
    .opening-card{
        position:relative;border:1.5px solid #efe9fb;border-radius:18px;
        padding:16px 18px 16px 54px;background:#fdfcff;cursor:pointer;
        transition:.22s;font-size:13.5px;color:#4f4960;line-height:1.78;
    }
    .opening-card:hover{border-color:#d6c6f2;background:#fbf8ff;}
    .opening-card .idx{
        position:absolute;left:16px;top:16px;width:26px;height:26px;
        border-radius:9px;background:linear-gradient(135deg,#f3e8ff,#faedcd);
        color:var(--accent-purple);font-size:12px;font-weight:700;
        display:flex;align-items:center;justify-content:center;
    }
    .opening-card .tag{
        display:inline-block;font-size:11px;font-weight:700;letter-spacing:1px;
        color:#b07a86;background:#fdeef1;border-radius:6px;padding:2px 9px;margin-bottom:7px;
    }
    .opening-card.selected{
        border-color:var(--accent-purple);
        background:linear-gradient(160deg,#faf6ff,#fff9f3);
        box-shadow:0 8px 24px rgba(157,142,199,0.16);
    }
    .opening-card.selected .idx{
        background:linear-gradient(135deg,var(--accent-purple),var(--accent-gold));
        color:#fff;
    }
    .custom-box{display:flex;flex-direction:column;gap:8px;margin-bottom:22px;}
    .custom-box label{font-size:13.5px;font-weight:600;color:#5f5873;}
    .custom-box textarea{
        font-family:inherit;font-size:14px;color:#3d374d;background:#fdfcff;
        border:1.5px solid #ece5fa;border-radius:14px;padding:12px 14px;
        outline:none;resize:vertical;min-height:88px;line-height:1.7;
    }
    .gen-wrap{text-align:center;margin-top:6px;}
    .gen-btn{
        font-family:inherit;cursor:pointer;border:none;padding:15px 56px;
        border-radius:999px;font-size:15px;font-weight:700;letter-spacing:3px;
        color:#fff;background:linear-gradient(135deg,var(--accent-purple),var(--accent-gold));
        box-shadow:0 12px 28px rgba(157,142,199,0.35);transition:.25s;
    }
    .gen-btn:hover{transform:translateY(-2px);box-shadow:0 16px 34px rgba(157,142,199,0.45);}
    .summary-card{background:linear-gradient(160deg,#fffcfa,#f8f3ff);border:1px solid #f0e8fd;}
    .summary-inner{
        background:#fffdfb;border:1px dashed #e3d9f5;border-radius:18px;
        padding:20px;min-height:110px;font-size:13.8px;color:#514b62;line-height:1.9;
        white-space:pre-wrap;word-break:break-word;
    }
    .copy-wrap{text-align:center;margin-top:-6px;margin-bottom:20px;}
    .copy-btn{
        font-family:inherit;cursor:pointer;width:100%;max-width:880px;border:none;
        padding:16px 20px;border-radius:18px;font-size:15.5px;font-weight:700;
        letter-spacing:3px;color:#fff;background:linear-gradient(135deg,var(--accent-purple),var(--accent-gold));
        box-shadow:0 14px 34px rgba(143,126,201,0.38);transition:.25s;
    }
    .copy-btn:hover{transform:translateY(-2px);box-shadow:0 18px 40px rgba(143,126,201,0.48);}
    @media (max-width:600px){
        body{padding:12px 10px 46px;}
        .hero{padding:34px 18px 30px;border-radius:24px;}
        .hero h1{font-size:22px;}
        .card{padding:20px 16px;}
        .profile-grid,.form-grid{grid-template-columns:1fr;}
        .opening-card{padding:14px 15px 14px 48px;font-size:13px;}
        .gen-btn{width:100%;padding:14px;}
