        const v = document.getElementById(id).value.trim();
        return v %s v : ''（未填写）'';
    }

    document.getElementById(''genBtn'').addEventListener(''click'', function () {
        const name = val(''p-name'');
        const age = val(''p-age'');
        const look = val(''p-look'');
        const cock = val(''p-cock'');
        const other = val(''p-other'');

        const custom = document.getElementById(''customOpening'').value.trim();
        const chosen = custom %s custom : OPENINGS[selectedIndex].text;
        const chosenTag = custom %s ''自定义开场白'' : OPENINGS[selectedIndex].tag;

        let out = '''';
        out += ''【玩家设定】\n'';
        out += ''姓名：'' + name + ''\n'';
        out += ''年龄：'' + age + ''\n'';
        out += ''外貌：'' + look + ''\n'';
        out += ''特质设定：'' + cock + ''\n'';
        out += ''其他设定：'' + other + ''\n\n'';
        out += ''【开场白 · '' + chosenTag + ''】\n'';
        out += chosen;

        lastSummaryText = out;
        summaryBox.textContent = out;
        summaryBox.scrollIntoView({behavior: ''smooth'', block: ''start''});
    });

    copyBtn.addEventListener(''click'', function () {
        if (!lastSummaryText) { lastSummaryText = summaryBox.textContent; }
        if (navigator.clipboard && navigator.clipboard.writeText) {
            navigator.clipboard.writeText(lastSummaryText).then(function() {
                copyBtn.textContent = ''已 复 制 ✓'';
                setTimeout(function() { copyBtn.textContent = ''一 键 复 制''; }, 1800);
            });
        }
    });
</script>
</body>
</html>', '都市', '2026-09-13 14:34:01', '2026-09-13 14:34:01', '', '', '[]', '') ON CONFLICT (id) DO NOTHING;
INSERT INTO stories (id, title, badge, cover_icon, cover_title, cover_subtitle, logo, theme_color, btn_gradient, handbook_json, roles_json, scenes_json, styles_json, first_turn_demo_json, custom_css, custom_html, category, created_at, updated_at, system_prompt, status_template, lorebook_json, post_history_instructions) VALUES ('deck_jiuxiao_xiuxian', '九霄修仙传：设定超全的修仙卡（开局roll天赋）', '修真长生 · 开局roll天赋', '🗡️', '九霄仙途', '从练气蝼蚁到九霄至尊的逆天长生录', '🗡️', '#10b981', 'linear-gradient(135deg, #10b981 0%, #059669 100%)', '{"title": "九霄修仙传：设定超全的修仙卡（开局roll天赋）", "desc": "【设定超全的硬核修仙巨制】完整构建九霄大陆九大境界（练气/筑基/金丹/元婴/化神/炼虚/合体/大乘/渡劫）、宗门林立、灵根资质、天材地宝、妖兽品阶与天地异火系统。开局自选或roll神级命格天赋，真实还原仙途之残酷与长生之逆天，绝不言出法随！", "bg_image": "https://catai.wiki/6fa0ffc0-2a67-4647-06d2-d793428ffe00/cover", "opening_options": ["【宗门杂役·逆天改命】：“青云宗灵田边，身为五系杂灵根杂役弟子的你，在后山溪水里意外捡到一枚沾满青苔的古朴黑戒……”", "【落魄修仙世家·家族重振】：“破败的林氏祖祠内，长明灯忽明忽暗，身为少主的你接过父亲留下的残缺天阶心法秘籍。”", "【散修破局·险地寻药】：“万毒瘴气弥漫的断魂谷外，你握着手中的淬毒匕首，正死死盯着悬崖边盛开的一株百年洗髓草。”", "【魔宗卧底·双修博弈】：“幽冥魔宗合欢峰顶，冷艳狠辣的魔宗圣女冷冷俯视着跪在玉阶下的你，命你奉上一缕本命精血。”"]}', '[{"name": "修仙者 (玩家)", "role": "逆天求道者 / 天赋宿主", "desc": "踏入九霄修真大世界的求道之人。身怀神级天赋词条，在吞吐天地灵气、炼制灵丹妙药、历经天劫雷罚中争夺一线长生机缘。"}, {"name": "云清璃 (青云剑宗小师妹)", "role": "天灵根剑修天才 (傲娇/正义/剑心通明)", "desc": "16岁，青云宗宗主之幼女，罕见纯阳天火灵根。平日里白衣胜雪、仗剑行侠，对凡俗琐事一窍不通，表面嫌弃主角杂役身份，暗地里多次在宗门执法堂护你周全。"}]', '[{"title": "⛰️ 青云剑宗后山 · 灵雾缭绕的断崖", "desc": "云海翻滚，古松如虬。远处的仙禽鹤鸣隐隐约约，瀑布垂落千尺化为弥漫灵雾，是吐纳筑基的绝佳宝地。"}, {"title": "🏯 九霄天元黑市 · 宝光四溢的修仙坊市", "desc": "各派修士掩盖面容交换禁忌灵草法宝，暗流涌动，杀人夺宝与一夜暴富在一念之间。"}]', '{"dialogue_style": "原汁原味的古典东方修真玄幻网文风，讲究因果机缘、境界威压与天地法则", "format": "AI风月标准双栏规范及.custom-ui样式"}', '[{"index": 1, "isUser": false, "scene": "⛰️ 青云剑宗后山 · 灵雾缭绕的断崖", "story": "<tl>📅大乾历 728年 · 谷雨 | 🌏地点：青云剑宗外门后山断崖 | 🧘‍♂️境界：练气期一层 (灵气值: 12/100)</tl>\n\n<article>\n<p>山风浩荡，将后山断崖上的千顷云海撕扯出万千波澜。暮色四合，九霄主峰上的护宗护山大阵正泛着淡淡的青蒙蒙微光。</p>\n\n<p>你盘膝坐在一块被风雨侵蚀出青苔的磐石上，浑身骨骼在刚才运转吐纳决时发出细微的酸胀声。作为青云宗最不起眼的杂役弟子，你身负驳杂的下品五行灵根，三年苦修不过堪堪叩开练气期一层的门槛，下个月的宗门外门考核若是不过，便要被贬下山为凡尘矿奴。</p>\n\n<p>然而此刻，你紧握在掌心里的一枚乌黑石戒，却正散发着异样温热的脉动。这是你方才在后山灵溪挑水时无意捞起的异物，上面隐约篆刻着古老的九霄铭文。</p>\n\n<p><w>“喂！那个偷懒的杂役，你还赖在断崖上干什么呢？！”</w></p>\n\n<p>一道清脆中带着几分娇蛮的少女娇喝自上方悬崖栈道上传来。伴随着环佩叮当与破空剑气，一袭雪白流仙裙、腰悬青玉剑鞘的少女宛如惊鸿仙子般飘然落下。那是青云宗掌教之女、天生纯阳剑体的绝世天才云清璃。</p>\n\n<p>她微微蹙着秀眉，杏眸带着居高临下的审视上下打量你，手中挽着一株刚采摘下来的散发着浓郁药香的二阶【紫玉芝】：</p>\n\n<p><w>“后山今夜有二阶妖兽赤鳞蟒出没的痕迹，不想沦为妖兽腹中肉的话，就赶紧收拾柴担回杂役院去！……诺，本小姐刚才采药顺手采多了，这片紫芝叶子便宜你这个呆子拿去熬药擦伤吧，省得考核不过给本宗丢人！”</w></p>\n</article>\n\n<opt>\n<suggested_questions>\n<d>A. 【双手接过灵芝·不卑不亢】：从容躬身接过药草，神色平静注视她的眼眸：“多谢云师姐关照。不过今夜这断崖上的赤鳞蟒，我倒很想去见识见识它的蛇胆。【行动目标：试炼初阶雷火法诀，尝试越级挑战残血妖兽】”</d>\n<d>B. 【暗中激活黑戒·神识探查】：一只手悄然将灵力注入掌心的古朴石戒，尝试唤醒其中沉睡的古老残魂【行动目标：触发金手指老爷爷/神尊指点，辨认神秘石戒来历与修真秘辛】</d>\n<d>C. 【调侃试探·借势拉近】：收起药草狡黠一笑：“云师姐嘴上说顺手，可紫玉芝生长在千仞绝壁，师姐冒着危险采来，不会是特意给师弟我准备的吧？”【行动目标：直击傲娇小师妹羞涩心防，打破身份阶级壁垒】</d>\n<d>D. 【虚心求教·请教剑法破绽】：拔出腰间锈迹斑斑的杂役铁剑当场演示一招青云剑式，向剑道天才云清璃求教气机运转之道【行动目标：以坚毅求道之心打动高岭小师妹，争取得到高阶剑诀指点】</d>\n</suggested_questions>\n</opt>", "branches": [{"tag": "A", "title": "接过灵芝不卑不亢", "desc": "从容致谢并表明越级挑战妖兽之志向，展现道心"}, {"tag": "B", "title": "暗中激活乌黑石戒", "desc": "灵力注入唤醒神秘古戒残魂，开启逆天金手指"}, {"tag": "C", "title": "调侃试探傲娇师姐", "desc": "笑戳送药破绽，击溃小师妹傲娇心理防线"}, {"tag": "D", "title": "拔剑演示虚心求教", "desc": "以不灭求道之坚毅打动剑道天才，争取指点"}]}]', '', '', '⚔️ 奇幻冒险', '2026-09-22 11:47:43', '2026-09-22 11:47:43', '', '', '[]', '') ON CONFLICT (id) DO NOTHING;
INSERT INTO stories (id, title, badge, cover_icon, cover_title, cover_subtitle, logo, theme_color, btn_gradient, handbook_json, roles_json, scenes_json, styles_json, first_turn_demo_json, custom_css, custom_html, category, created_at, updated_at, system_prompt, status_template, lorebook_json, post_history_instructions) VALUES ('deck_sister_roommate_belong', '妹妹的骚穴再不插入就要属于别人了！', '禁断 · 兄妹同居', '🎀', '妹妹的骚穴再不插入就', '妹妹的骚穴再不插入就要属于别人了！', '🎀', '#ec4899', 'linear-gradient(135deg, #ec4899 0%, #f43f5e 100%)', '{"title": "妹妹的骚穴再不插入就要属于别人了！", "desc": "林溪月，你的亲生妹妹。\n十八岁，高三，身高168，H罩杯，腰细臀翘，一双雪白的大长腿让全校男生流尽口水。黑长直发，冷白皮，五官精致得像瓷娃娃，笑起来有浅浅的梨涡。\n但在你面前，她从来不把自己当外人。\n\n夏天穿着你的大T恤在家里晃悠，里面什么都不穿，弯腰拿东西时饱满的乳房几乎要从领口掉出来。洗完澡裹着浴巾出来，当着你的面解开，用毛巾慢慢擦干身上每一寸湿漉漉的肌肤。甚至有时候来例假，她也会懒洋洋地躺在沙发上，双腿大张着抱怨卫生巾不舒服，裙底那条粉色的小内裤和若隐若现的白虎缝隙，全都被你一览无余。\n\n她不是不知道你在看。\n她是故意的。\n\n从十五岁那年，她发现你偷看她换衣服没有揭穿，反而在第二天穿了一件更透的吊带开始，你们之间就形成了一种心照不宣的默契——林溪月，是你一个人的专属展览品。\n\n她允许你看，允许你在她“睡着”的时候偷偷触碰，甚至允许你在她半推半就之下，用嘴唇品尝过她粉色嫩穴里流出的蜜汁", "bg_image": "https://catai.wiki/0ca69137-b854-45e1-b3bc-259da82fb900/bg", "opening_options": ["【霸道审问】：直接抓住妹妹的手腕，逼问今天向她告白的男生到底是谁", "【假装冷淡】：故意装作不在意，看她气急败坏下如何主动跨坐上来撩拨", "【打破禁忌】：反锁房门，将浑身泛红娇软的妹妹逼入书桌死角打破最后防线"]}', '[{"name": "主角 (玩家)", "role": "核心视角", "desc": "故事的决策者与推进者"}, {"name": "故事角色", "role": "互动对象", "desc": "性格与背景随着剧情发展逐步揭示"}]', '[{"title": "场景开局", "desc": "故事拉开帷幕的初始场景，交织着微妙的气氛与情感抉择。"}]', '{"dialogue_style": "细腻深邃的情感物语，富有张力的人物神态与心理博弈", "format": "AI风月标准双栏规范及.custom-ui样式"}', '[{"index": 1, "isUser": false, "scene": "初始情境", "story": "<tl>📅时间：夜晚 | 🌏地点：故事开端</tl>\n\n<article>\n<p>林溪月，你的亲生妹妹。\n十八岁，高三，身高168，H罩杯，腰细臀翘，一双雪白的大长腿让全校男生流尽口水。黑长直发，冷白皮，五官精致得像瓷娃娃，笑起来有浅浅的梨涡。\n但在你面前，她从来不把自己当外人。\n\n夏天穿着你的大T恤在家里晃悠，里面什么都不穿，弯腰拿东西时饱满的乳房几乎要从领口掉出来。洗完澡裹着浴巾出来，当着你的面解开，用毛巾慢慢擦干身上每一寸湿漉漉的肌肤。甚至有时候来例假，她也会懒洋洋地躺在沙发上，双腿大张着抱怨卫生巾不舒服，裙底那条粉色的小内裤和若隐若现的白虎缝隙，全都被你一览无余。\n\n她不是不知道你在看。\n她是故意的。\n\n从十五岁那年，她发现你偷看她换衣服没有揭穿，反而在第二天穿了一件更透的吊带开始，你们之间就形成了一种心照不宣的默契——林溪月，是你一个人的专属展览品。\n\n她允许你</p>\n</article>", "branches": [{"tag": "A", "title": "深入互动", "desc": "顺应当前情境展开下一步剧情"}, {"tag": "B", "title": "试探心理", "desc": "观察对方细微的反应与意图"}, {"tag": "C", "title": "掌握主动", "desc": "以坚定的态度引导局势发展"}]}]', '/* --- 核心修复：强制亮色模式 & 移动端重置 --- */
:root {
    color-scheme: light !important;
}
* {
    -webkit-tap-highlight-color: transparent !important;
    -webkit-touch-callout: none !important;
}
*:focus, *:active {
    outline: none !important;
    box-shadow: none !important;
}

/* --- 整体风格：云朵蓝莓 (Cloudy Blueberry) --- */

/* 1. 主容器：清新的蓝白渐变 */
.bg-gray-100\/90.relative.inline-block {
    background: linear-gradient(180deg, #E0F7FA 0%, #E6E6FA 100%) !important;
    border: 3px solid #B0E0E6 !important;
    border-radius: 20px !important;
    padding: 20px !important;
    margin: 10px auto !important;
    box-shadow: 0 8px 20px rgba(176, 224, 230, 0.5) !important;
}

/* 2. 文本区域：纯净白色 */
.markdown-body {
    background-color: #FFFFFF !important;
    color: #5F6368 !important;
    border-radius: 15px !important;
    padding: 15px !important;
    font-family: ''Nunito'', ''Segoe UI'', sans-serif !important;
    line-height: 1.7 !important;
    border: 1px solid #F0F8FF !important;
}

/* 3. 标题：天空蓝 */
.markdown-body h1, .markdown-body h2, .markdown-body h3 {
    color: #6495ED !important;
    border-bottom: 2px dashed #B0E0E6 !important;
    padding-bottom: 5px !important;
    margin-top: 1.2em !important;
}

/* --- 核心优化：状态栏 (Details) - 晨曦微光风格 --- */
details {
    /* 背景：极淡的云雾渐变，通透感 */
    background: linear-gradient(135deg, #F0F8FF 0%, #FFFFFF 100%) !important;
    /* 边框：天空蓝虚线，精致且不沉重 */
    border: 2px dashed #87CEEB !important;
    color: #5F6368 !important; /* 深灰字，保证阅读舒适 */
    border-radius: 16px !important; /* 更圆润的胶囊角 */
    margin: 15px 0 !important;
    padding: 12px 18px !important;
    box-shadow: 0 4px 12px rgba(135, 206, 235, 0.2) !important; /* 淡淡的蓝色光晕 */
    transition: all 0.3s ease !important;
}

/* 展开时的交互微调 */
details[open] {
    border-color: #6495ED !important; /* 展开后边框变深一点 */
    background: #F0F8FF !important;
}

/* 状态栏标题 (Summary) */
summary {
    color: #4682B4 !important; /* 钢蓝标题，优雅清晰 */
    font-weight: 700 !important;
    font-size: 1.05em !important;
    cursor: pointer !important;
    outline: none !important;
    list-style: none !important;
    padding: 5px 0 !important;
    letter-spacing: 0.5px !important;
}

summary::-webkit-details-marker {
    display: none !important;
}

/* 自定义图标：闪烁的星星 */
summary::before {
    content: ''✨ '' !important;
    margin-right: 8px !important;
    filter: drop-shadow(0 0 2px gold) !important;
}
details[open] summary::before {
    content: ''💫 '' !important;
}

/* 状态栏内的链接颜色适配（背景变亮，链接要深色） */
details a {
    color: #1E90FF !important; /* 闪避蓝 */
    text-decoration: none !important;
    border-bottom: 1px dotted #1E90FF !important;
}

/* 状态栏内的代码块适配 */
details code, details pre {
    background-color: #E6F2FF !important; /* 极淡蓝底 */
    color: #4682B4 !important; /* 钢蓝字 */
    border: 1px solid #D1E9FF !important;
}

/* --- 普通代码块 (非状态栏内) --- */
.markdown-body pre, .markdown-body code {
    background-color: #F0F8FF !important;
    color: #4682B4 !important;
    border-radius: 8px !important;
    font-family: Consolas, monospace !important;
    padding: 5px !important;
    border: 1px solid #B0C4DE !important;
    
    /* 手机端防黑边 */
    outline: none !important;
    box-shadow: none !important;
    white-space: pre-wrap !important;
    word-break: break-all !important;
}

/* --- 其他元素美化 --- */

/* 链接 */
.markdown-body a {
    color: #1E90FF !important;
    text-decoration: none !important;
    font-weight: 600 !important;
}

/* 列表 */
.markdown-body ul li::before {
    content: ''☁️ '' !important;
    margin-right: 5px !important;
}
.markdown-body ul {
    list-style: none !important;
    padding-left: 10px !important;
}

/* 按钮 */
.MuiButtonBase-root.MuiButton-root {
    background-color: #87CEEB !important;
    color: #FFFFFF !important;
    border-radius: 20px !important;
    font-weight: bold !important;
    box-shadow: 0 4px 6px rgba(135, 206, 235, 0.3) !important; /* 增加一点立体感 */
    border: none !important;
}
.MuiButtonBase-root.MuiButton-root:hover {
    background-color: #00BFFF !important;
    transform: translateY(-1px) !important; /* 悬停微动 */
}

/* 输入框 */
textarea, input[type="text"] {
    background: #FFFFFF !important; /* 纯白背景更干净 */
    border: 2px solid #E6E6FA !important;
    border-radius: 12px !important;
    color: #483D8B !important;
    padding: 12px !important;
    box-shadow: inset 0 2px 4px rgba(0,0,0,0.02) !important;
    -webkit-appearance: none !important;
}
textarea:focus, input[type="text"]:focus {
    border-color: #87CEEB !important;
    box-shadow: 0 0 0 3px rgba(135, 206, 235, 0.2) !important;
}

/* 隐藏顶部颜色条 */
[class*="bg-[#F1CBCB]"], [class*="bg-[#c9e1e9]"] {
    display: none !important;
}

/* === 强制清除移动端所有默认黑边/黑底 === */

input, textarea, select, button, pre, code {
    -webkit-appearance: none !important;
    -moz-appearance: none !important;
    appearance: none !important;
}

input, textarea, button, pre, code {
    background-color: #FFFFFF !important;
    background: #FFFFFF !important;
}

pre, code {
    color: #4682B4 !important;
    background-color: #F0F8FF !important;
    -webkit-text-fill-color: #4682B4 !important;
    -webkit-background-clip: padding-box !important;
}

:root {
    color-scheme: light !important;
}

button, [role="button"] {
    -webkit-tap-highlight-color: transparent !important;
    background-color: #87CEEB !important;
}

/* === 强制清除移动端代码块黑底 === */
pre,
code,
pre[class*="language-"],
code[class*="language-"],
.language-python,
.language-time,
.hljs {
    -webkit-appearance: none !important;
    -moz-appearance: none !important;
    appearance: none !important;
    background-color: #F0F8FF !important;
    color: #4682B4 !important;
    -webkit-text-fill-color: #4682B4 !important;
    -webkit-background-clip: padding-box !important;
    background-clip: padding-box !important;
    background: #F0F8FF !important;
    border: 1px solid #B0C4DE !important;
    outline: none !important;
    box-shadow: none !important;
}

div > pre,
.markdown-body > pre,
.markdown-body pre {
    background-color: #F0F8FF !important;
    background: #F0F8FF !important;
}', '<!DOCTYPE html>
<html lang="zh-CN">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>妹妹的第一次，只能是我的</title>
<style>
@import url(''https://fonts.googleapis.com/css2%sfamily=Noto+Serif+SC:wght@400;600;700&family=ZCOOL+KuaiLe&display=swap'');

*{margin:0;padding:0;box-sizing:border-box;-webkit-tap-highlight-color:transparent;}

body{
  font-family:''Noto Serif SC'',serif;
  background:linear-gradient(150deg,#1a0f18 0%,#2b1523 35%,#1f1219 70%,#150a12 100%);
  color:#f0dce6;
  min-height:100vh;
  padding:16px 12px 80px;
  line-height:1.85;
  font-size:15px;
  -webkit-text-size-adjust:100%;
}

:root{
  --pink:#ff8fb8;
  --pink-deep:#ff5f96;
  --pink-glow:rgba(255,110,160,0.45);
  --rose:#e25a8c;
  --gold:#f5c97a;
  --gold-deep:#d9a84e;
  --cream:#fbe9f0;
  --card:rgba(48,26,38,0.82);
  --card-solid:#321a26;
  --line:rgba(255,143,184,0.28);
  --line-soft:rgba(255,143,184,0.14);
  --text:#f0dce6;
  --text-soft:#c4a0b0;
  --grad-pink:linear-gradient(135deg,#ff8fb8,#ff5f96);
  --grad-pink-hover:linear-gradient(135deg,#ff5f96,#e25a8c);
  --grad-gold:linear-gradient(135deg,#f5c97a,#d9a84e);
  --shadow:0 10px 32px rgba(255,80,140,0.18);
  --shadow-soft:0 6px 18px rgba(255,80,140,0.10);
  --radius:20px;
  --radius-sm:14px;
}

.wrap{
  max-width:760px;
  margin:0 auto;
  position:relative;
}

/* 顶部标题 */
.hero{
  text-align:center;
  padding:28px 16px 22px;
  position:relative;
  overflow:hidden;
  border-radius:var(--radius);
  background:
    radial-gradient(circle at 20% 10%,rgba(255,110,160,0.22),transparent 55%),
    radial-gradient(circle at 85% 90%,rgba(245,201,122,0.16),transparent 55%),
    linear-gradient(160deg,rgba(56,28,42,0.92),rgba(34,18,26,0.96));
  border:1px solid var(--line);
  box-shadow:var(--shadow);
  margin-bottom:20px;
}
.hero::before{
  content:"";
  position:absolute;
  top:-40px;right:-40px;
  width:140px;height:140px;
  border-radius:50%;
  background:radial-gradient(circle,rgba(255,110,160,0.22),transparent 70%);
  filter:blur(6px);
}
.hero::after{
  content:"";
  position:absolute;
  bottom:-50px;left:-30px;
  width:130px;height:130px;
  border-radius:50%;
  background:radial-gradient(circle,rgba(245,201,122,0.16),transparent 70%);
  filter:blur(6px);
}
.hero h1{
  font-family:''ZCOOL KuaiLe'',cursive;
  font-size:clamp(22px,5.6vw,34px);
  letter-spacing:2px;
  background:linear-gradient(90deg,#ffb3cd,#ff5f96,#f5c97a);
  -webkit-background-clip:text;
  background-clip:text;
  -webkit-text-fill-color:transparent;
  position:relative;
  z-index:2;
  margin-bottom:8px;
  text-shadow:0 0 24px rgba(255,95,150,0.35);
}
.hero .sub{
  color:var(--text-soft);
  font-size:12.5px;
  letter-spacing:3px;
  position:relative;
  z-index:2;
}
.hero .heart{
  position:relative;
  z-index:2;
  margin-top:10px;
  font-size:14px;
  color:var(--pink);
  letter-spacing:6px;
  opacity:.8;
}

/* 通用卡片 */
.card{
  background:var(--card);
  border:1px solid var(--line);
  border-radius:var(--radius);
  box-shadow:var(--shadow-soft);
  padding:20px 18px;
  margin-bottom:18px;
  backdrop-filter:blur(6px);
  position:relative;
  overflow:hidden;
}
.card-title{
  display:flex;
  align-items:center;
  gap:9px;
  font-size:16px;
  font-weight:700;
  color:var(--pink);
  margin-bottom:14px;
  letter-spacing:1px;
}
.card-title::before{
  content:"";
  width:5px;height:18px;
  border-radius:3px;
  background:var(--grad-pink);
  box-shadow:0 0 10px var(--pink-glow);
}
.card-title .ico{font-size:17px;}

/* 人物介绍美化 */
.intro-grid{
  display:grid;
  gap:12px;
}
.intro-item{
  background:linear-gradient(145deg,rgba(255,143,184,0.08),rgba(255,143,184,0.02));
  border:1px solid var(--line-soft);
  border-radius:var(--radius-sm);
  padding:13px 15px;
  position:relative;
}
.intro-item .lab{
  display:inline-block;
  font-size:12px;
  color:var(--gold);
  letter-spacing:2px;
  margin-bottom:6px;
  font-weight:600;
}
.intro-item .txt{color:var(--text);font-size:14px;}
.intro-item .txt em{color:var(--pink);font-style:normal;font-weight:600;}

.name-block{
  text-align:center;
  padding:16px 10px 14px;
  margin-bottom:14px;
  border-radius:var(--radius-sm);
  background:linear-gradient(150deg,rgba(255,110,160,0.14),rgba(255,110,160,0.03));
  border:1px solid var(--line-soft);
}
.name-block .big{
  font-family:''ZCOOL KuaiLe'',cursive;
  font-size:clamp(24px,6.5vw,32px);
  color:#fff;
  letter-spacing:4px;
  text-shadow:0 0 22px var(--pink-glow);
}
.name-block .tag{
  margin-top:8px;
  display:flex;
  justify-content:center;
  flex-wrap:wrap;
  gap:6px;
}
.name-block .tag span{
  font-size:11.5px;
  padding:3px 11px;
  border-radius:20px;
  background:rgba(255,143,184,0.14);
  border:1px solid var(--line);
  color:var(--pink);
}

.story-text{
  font-size:14px;
  color:var(--text-soft);
  line-height:2;
  text-indent:2em;
}
.story-text em{color:var(--pink);font-style:normal;font-weight:600;}
.story-text .hl{color:var(--gold);}

/* 玩法列表 */
.rules{display:grid;gap:10px;}
.rule-row{
  display:flex;
  gap:10px;
  align-items:flex-start;
  background:linear-gradient(145deg,rgba(255,143,184,0.06),transparent);
  border:1px solid var(--line-soft);
  border-radius:var(--radius-sm);
  padding:11px 13px;
}
.rule-row .dot{
  flex:0 0 auto;
  width:22px;height:22px;
  border-radius:50%;
  background:var(--grad-pink);
  color:#fff;
  font-size:12px;
  font-weight:700;
  display:flex;align-items:center;justify-content:center;
  box-shadow:0 0 10px var(--pink-glow);
  margin-top:1px;
}
.rule-row .rt{font-size:13.5px;color:var(--text);line-height:1.75;}
.rule-row .rt b{color:var(--pink);}

/* 表单 */
.field{margin-bottom:14px;}
.field label{
  display:block;
  font-size:13px;
  color:var(--gold);
  letter-spacing:1px;
  margin-bottom:7px;
  font-weight:600;
}
.field input,
.field textarea,
.field select{
  width:100%;
  background:rgba(20,10,16,0.6);
  border:1px solid var(--line);
  border-radius:var(--radius-sm);
  color:var(--cream);
  font-family:''Noto Serif SC'',serif;
  font-size:14px;
  padding:11px 13px;
  outline:none;
  transition:border-color .25s,box-shadow .25s;
  line-height:1.7;
}
.field textarea{resize:vertical;min-height:78px;}
.field input:focus,
.field textarea:focus,
.field select:focus{
  border-color:var(--pink);
  box-shadow:0 0 0 3px rgba(255,95,150,0.14);
}
.field input::placeholder,
.field textarea::placeholder{color:rgba(196,160,176,0.5);}
.two-col{display:grid;grid-template-columns:1fr 1fr;gap:12px;}

/* 开场白选择 */
.opening-list{display:grid;gap:11px;}
.opening-item{
  position:relative;
  border:1px solid var(--line-soft);
  border-radius:var(--radius-sm);
  padding:13px 14px 13px 44px;
  cursor:pointer;
  transition:all .25s;
  background:linear-gradient(145deg,rgba(255,143,184,0.05),transparent);
  font-size:13.5px;
  color:var(--text-soft);
  line-height:1.8;
}
.opening-item:active{transform:scale(0.99);}
.opening-item.sel{
  border-color:var(--pink);
  background:linear-gradient(145deg,rgba(255,95,150,0.16),rgba(255,95,150,0.04));
  box-shadow:0 0 18px rgba(255,95,150,0.18);
  color:var(--cream);
}
.opening-item .chk{
  position:absolute;
  left:14px;top:14px;
  width:19px;height:19px;
  border-radius:50%;
  border:2px solid var(--line);
  display:flex;align-items:center;justify-content:center;
  transition:all .25s;
}
.opening-item.sel .chk{
  border-color:var(--pink);
  background:var(--grad-pink);
}
.opening-item .chk::after{
  content:"✓";
  font-size:12px;
  color:#fff;
  opacity:0;
  transition:opacity .25s;
}
.opening-item.sel .chk::after{opacity:1;}
.opening-item .op-label{
  display:block;
  font-size:12px;
  color:var(--gold);
  margin-bottom:3px;
  letter-spacing:1px;
  font-weight:600;
}

/* 主按钮 */
.btn-main{
  display:block;
  width:100%;
  padding:15px;
  border:none;
  border-radius:var(--radius-sm);
  background:var(--grad-pink);
  color:#fff;
  font-family:''ZCOOL KuaiLe'',cursive;
  font-size:17px;
  letter-spacing:3px;
  cursor:pointer;
  box-shadow:0 8px 24px rgba(255,95,150,0.35);
  transition:all .25s;
  margin-top:6px;
}
.btn-main:active{transform:translateY(2px);box-shadow:0 4px 14px rgba(255,95,150,0.28);}
.btn-main:hover{background:var(--grad-pink-hover);}

/* 总结区 */
.summary{
  border:1px dashed var(--pink);
  border-radius:var(--radius);
  padding:18px 16px;
  background:
    radial-gradient(circle at 90% 10%,rgba(245,201,122,0.10),transparent 50%),
    linear-gradient(160deg,rgba(56,28,42,0.7),rgba(34,18,26,0.8));
  margin-bottom:16px;
}
.summary-empty{
  text-align:center;
  color:rgba(196,160,176,0.55);
  font-size:13px;
  padding:22px 10px;
  letter-spacing:1px;
}
.summary-block{margin-bottom:14px;}
.summary-block:last-child{margin-bottom:0;}
.summary-block .s-title{
  font-size:13px;
  color:var(--gold);
  letter-spacing:2px;
  font-weight:700;
  margin-bottom:8px;
  display:flex;align-items:center;gap:7px;
}
.summary-block .s-title::before{
  content:"";
  width:4px;height:14px;
  border-radius:2px;
  background:var(--grad-gold);
}
.summary-block .s-body{
  font-size:13.5px;
  color:var(--cream);
  line-height:1.9;
  white-space:pre-wrap;
  word-break:break-word;
  background:rgba(20,10,16,0.4);
  border:1px solid var(--line-soft);
  border-radius:var(--radius-sm);
  padding:12px 13px;
}
.summary-block .s-body .k{color:var(--pink);font-weight:600;}

/* 复制按钮 */
.btn-copy{
  display:flex;
  align-items:center;
  justify-content:center;
  gap:8px;
  width:100%;
  padding:14px;
  border:1px solid var(--gold);
  border-radius:var(--radius-sm);
  background:linear-gradient(135deg,rgba(245,201,122,0.22),rgba(217,168,78,0.12));
  color:var(--gold);
  font-family:''Noto Serif SC'',serif;
  font-size:15px;
  font-weight:700;
  letter-spacing:2px;
  cursor:pointer;
  transition:all .25s;
}
.btn-copy:active{transform:translateY(2px);}
.btn-copy:hover{
  background:linear-gradient(135deg,rgba(245,201,122,0.34),rgba(217,168,78,0.2));
  box-shadow:0 0 20px rgba(245,201,122,0.22);
}
.btn-copy .ci{font-size:16px;}

/* 提示 */
.tip{
  font-size:11.5px;
  color:rgba(196,160,176,0.65);
  text-align:center;
  margin-top:8px;
  letter-spacing:.5px;
}

/* 底部 */
.footer{
  text-align:center;
  font-size:11.5px;
  color:rgba(196,160,176,0.5);
  letter-spacing:2px;
  padding:18px 0 6px;
}
.footer .l{color:var(--pink);letter-spacing:8px;display:block;margin-bottom:6px;}

/* 响应式 */
@media (max-width:400px){
  body{padding:12px 9px 70px;font-size:14.5px;}
  .card{padding:17px 14px;}
  .two-col{grid-template-columns:1fr;}
  .hero{padding:22px 12px 18px;}
}
@media (min-width:760px){
  body{padding:26px 20px 80px;}
  .card{padding:24px 24px;}
  .hero{padding:36px 20px 28px;}
}

/* 滚动条 */
::-webkit-scrollbar{width:7px;height:7px;}
::-webkit-scrollbar-track{background:transparent;}
::-webkit-scrollbar-thumb{background:rgba(255,143,184,0.3);border-radius:4px;}
::-webkit-scrollbar-thumb:hover{background:rgba(255,143,184,0.5);}

/* 进场动画 */
@keyframes fadeUp{
  from{opacity:0;transform:translateY(16px);}
  to{opacity:1;transform:translateY(0);}
}
.anim{animation:fadeUp .55s cubic-bezier(0.22,1,0.36,1) both;}
.d1{animation-delay:.05s;}
.d2{animation-delay:.12s;}
.d3{animation-delay:.19s;}
.d4{animation-delay:.26s;}
.d5{animation-delay:.33s;}
</style>
