// 绑定角色卡点击交互 (直接通知宿主 React 视口中央呼出高保真弹窗，与 AI 风月 100% 一致)
document.querySelectorAll(''.character-card'').forEach(card => {
    card.addEventListener(''click'', function(e) {
        playSound(''click'');
        const characterId = this.getAttribute(''data-character'');
        const data = characterData[characterId];
        if (!data) return;

        try {
            window.parent.postMessage({
                type: ''NOVAL_SHOW_CHARACTER_MODAL'',
                character: {
                    id: characterId,
                    name: data.name,
                    tag: data.tag,
                    avatar: data.avatar,
                    description: data.description,
                    reaction: data.reaction
                }
            }, ''*'');
        } catch(err) {}
    });
});

charModalClose.addEventListener(''click'', function() {
    playSound(''close'');
    characterModal.classList.remove(''active'');
});

characterModal.addEventListener(''click'', function(e) {
    if (e.target === characterModal) {
        playSound(''close'');
        characterModal.classList.remove(''active'');
    }
});

