ai {
display: block;
max-width: 860px;
margin: 0 auto;
font-family: ''Georgia'', ''Noto Serif SC'', ''Microsoft YaHei'', serif;
background: linear-gradient(145deg, #fffaf7 0%, #fdeef3 50%, #f3ecff 100%);
border: 1px solid #eed8d8;
border-radius: 24px;
padding: 28px 30px;
box-shadow: 0 12px 40px rgba(190, 140, 160, 0.18);
color: #4a3f4a;
line-height: 1.9;
}

/* ── 头部档案条 ── */
hd {
display: block;
background: linear-gradient(90deg, #ffe4ec 0%, #dce6ff 50%, #fff0e6 100%);
border-radius: 16px;
padding: 14px 22px;
margin-bottom: 18px;
border: 1px solid rgba(255, 255, 255, 0.85);
box-shadow: 0 4px 16px rgba(220, 170, 190, 0.15), inset 0 1px 0 rgba(255,255,255,0.9);
}
hd d {
display: block;
font-size: 0.92em;
margin: 5px 0;
color: #54455a;
font-weight: 500;
letter-spacing: 0.3px;
}
hd d:first-child {
font-weight: 700;
color: #7a4a6a;
font-size: 1.02em;
}

hr {
border: none;
height: 2px;
background: linear-gradient(to right, transparent, #e8a0b8, #a0b8e8, transparent);
margin: 20px 0;
opacity: 0.6;
}

/* ── 正文区 ── */
article {
background: rgba(255, 255, 255, 0.95);
border-radius: 18px;
padding: 22px 28px;
border: 1px solid #f2dfe2;
box-shadow: 0 6px 24px rgba(230, 180, 195, 0.12);
backdrop-filter: blur(4px);
}
article p {
margin: 10px 0;
text-indent: 2em;
letter-spacing: 0.2px;
}

/* ── 折叠面板 ── */
details {
margin-top: 16px;
background: rgba(255, 255, 255, 0.9);
border-radius: 16px;
border: 1px solid #ecd5db;
overflow: hidden;
box-shadow: 0 4px 18px rgba(215, 165, 185, 0.10);
transition: box-shadow 0.3s ease;
}
details:hover {
box-shadow: 0 6px 24px rgba(215, 165, 185, 0.2);
}
details summary {
padding: 14px 24px;
cursor: pointer;
font-weight: 650;
font-size: 1.02em;
background: linear-gradient(90deg, #fdf0f5 0%, #f0ecff 100%);
color: #6a4a6a;
list-style: none;
user-select: none;
display: flex;
align-items: center;
gap: 8px;
border-bottom: 1px solid transparent;
transition: all 0.3s ease;
}
details[open] summary {
border-bottom: 1px solid #f0dde2;
background: linear-gradient(90deg, #fde6ee 0%, #e4e6ff 100%);
}
details summary::-webkit-details-marker {
display: none;
}
details summary::before {
content: ''❀'';
font-size: 0.9em;
color: #c68aa0;
margin-right: 6px;
transition: transform 0.3s ease;
}
details[open] summary::before {
content: ''❁'';
transform: rotate(180deg);
}

details p {
margin: 10px 24px;
padding: 4px 0;
font-size: 0.95em;
border-bottom: 1px dashed #f5e8ea;
}
details p:last-child {
border-bottom: none;
}

/* ── 字段名标签 ── */
f {
display: inline-block;
font-weight: 700;
color: #a06880;
margin-right: 10px;
font-size: 0.9em;
letter-spacing: 0.5px;
background: linear-gradient(90deg, #ffeef2, #f2edff);
padding: 2px 10px;
border-radius: 20px;
border: 1px solid #f0dce2;
}

/* ── 剧情选项（q引用块） ── */
q {
display: block;
margin: 8px 24px;
padding: 10px 18px;
background: linear-gradient(90deg, #fbf4f6, #f4f2ff);
border-radius: 12px;
border-left: 4px solid #d4a0b8;
border-right: 1px solid #f0e4e6;
font-style: normal;
color: #4a3a4a;
transition: background 0.2s;
}
q:hover {
background: linear-gradient(90deg, #fdeef2, #e8e6ff);
}

/* ── 表格区（命运档案馆） ── */
table {
width: 92%;
margin: 12px auto;
border-collapse: separate;
border-spacing: 0;
background: #fcf8fa;
border-radius: 12px;
overflow: hidden;
box-shadow: 0 2px 12px rgba(220, 180, 195, 0.08);
}
th {
background: linear-gradient(90deg, #f9e8ee, #eee8ff);
color: #6a4a6a;
padding: 10px 12px;
font-weight: 650;
font-size: 0.92em;
text-align: left;
border-bottom: 1px solid #f0dfe4;
}
td {
padding: 9px 12px;
border-top: 1px solid #f5e9ec;
color: #4a3a4a;
font-size: 0.92em;
}
tr:first-child th:first-child {
border-top-left-radius: 12px;
}
tr:first-child th:last-child {
border-top-right-radius: 12px;
}

/* ── 对话字体颜色增强（保持用户已有的font标签） ── */
article font[color="#1E90FF"] {
text-shadow: 0 0 8px rgba(30, 144, 255, 0.15);
}
article font[color="#9370DB"] {
text-shadow: 0 0 8px rgba(147, 112, 219, 0.15);
}

/* ── 响应式适配 ── */
@media (max-width: 640px) {
ai {
padding: 16px 14px;
border-radius: 16px;
}
article {
padding: 16px 18px;
}
details summary {
padding: 12px 16px;
}
q {
margin: 6px 14px;
padding: 8px 12px;
}
}', '<!DOCTYPE html>
<html lang="zh-CN">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no">
<title>慵懒姐姐的无防备日常</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2%sfamily=Noto+Serif+SC:wght@400;600;700;900&family=ZCOOL+XiaoWei&display=swap" rel="stylesheet">
<style>
:root {
  --bg-1: #fefaf3;
  --bg-2: #fbeedd;
  --bg-3: #f6e0c8;
  --card: rgba(255, 252, 246, 0.85);
  --card-solid: #fffaf3;
  --card-border: rgba(214, 156, 108, 0.28);
  --card-glow: rgba(240, 183, 164, 0.25);
  --primary: #e08a5f;
  --primary-soft: #f0b795;
  --accent: #e88fa8;
  --accent-2: #f5c0cf;
  --gold: #c99a5b;
  --text: #5a4636;
  --text-dim: #8e7866;
  --text-mute: #b3a08d;
  --input-bg: rgba(255, 253, 249, 0.92);
  --line: linear-gradient(90deg, transparent, rgba(224,138,95,0.55), rgba(232,143,168,0.55), transparent);
  --font: ''Noto Serif SC'', ''Songti SC'', serif;
  --font-title: ''ZCOOL XiaoWei'', ''Noto Serif SC'', serif;
  --radius: 18px;
}

* { margin: 0; padding: 0; box-sizing: border-box; -webkit-tap-highlight-color: transparent; }

html { scroll-behavior: smooth; }

body {
  font-family: var(--font);
  color: var(--text);
  background:
    radial-gradient(circle at 12% 8%, rgba(255, 214, 178, 0.55) 0%, transparent 42%),
    radial-gradient(circle at 88% 18%, rgba(245, 192, 207, 0.45) 0%, transparent 40%),
    radial-gradient(circle at 50% 96%, rgba(228, 205, 160, 0.4) 0%, transparent 48%),
    linear-gradient(160deg, var(--bg-1) 0%, var(--bg-2) 46%, var(--bg-3) 100%);
  background-attachment: fixed;
  min-height: 100vh;
  line-height: 1.85;
  letter-spacing: 0.02em;
  overflow-x: hidden;
  padding-bottom: 40px;
}

/* 漂浮光斑 */
body::before,
body::after {
  content: "";
  position: fixed;
  border-radius: 50%;
  filter: blur(60px);
  pointer-events: none;
  z-index: 0;
}
body::before {
  width: 340px; height: 340px;
  top: -80px; left: -90px;
  background: rgba(255, 200, 150, 0.5);
  animation: float1 16s ease-in-out infinite;
}
body::after {
  width: 300px; height: 300px;
  bottom: 8%; right: -100px;
  background: rgba(245, 180, 200, 0.45);
  animation: float2 20s ease-in-out infinite;
}
@keyframes float1 {
  0%,100% { transform: translate(0,0) scale(1); }
  50% { transform: translate(40px, 60px) scale(1.12); }
}
@keyframes float2 {
  0%,100% { transform: translate(0,0) scale(1); }
  50% { transform: translate(-50px, -50px) scale(1.08); }
}

.wrap {
  position: relative;
  z-index: 1;
  max-width: 880px;
  margin: 0 auto;
  padding: 0 16px;
}

/* ---------- HERO ---------- */
.hero {
  position: relative;
  text-align: center;
  padding: 56px 20px 42px;
  margin-bottom: 26px;
}
.hero-badge {
  display: inline-block;
  font-size: 12px;
  letter-spacing: 0.4em;
  color: var(--gold);
  border: 1px solid rgba(201, 154, 91, 0.45);
  border-radius: 999px;
  padding: 5px 18px 5px 22px;
  margin-bottom: 20px;
  background: rgba(255, 250, 240, 0.7);
  backdrop-filter: blur(6px);
}
.hero-title {
  font-family: var(--font-title);
  font-size: clamp(30px, 7.6vw, 48px);
  font-weight: 600;
  letter-spacing: 0.08em;
  background: linear-gradient(100deg, #d97b52 0%, #e39a68 32%, #e88fa8 68%, #cf9fa8 100%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  line-height: 1.35;
  filter: drop-shadow(0 3px 10px rgba(224, 138, 95, 0.22));
}
.hero-sub {
  margin-top: 14px;
  font-size: 13.5px;
  color: var(--text-dim);
  letter-spacing: 0.14em;
}
.hero-line {
  width: 140px;
  height: 2px;
  margin: 22px auto 0;
  background: var(--line);
  border-radius: 2px;
}

/* ---------- CARD ---------- */
.card {
  position: relative;
  background: var(--card);
  border: 1px solid var(--card-border);
  border-radius: var(--radius);
  padding: 26px 22px;
  margin-bottom: 22px;
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
  box-shadow:
    0 10px 34px -18px rgba(180, 120, 80, 0.35),
    inset 0 1px 0 rgba(255, 255, 255, 0.85);
  overflow: hidden;
  animation: rise 0.7s cubic-bezier(.2,.7,.3,1) both;
}
@keyframes rise {
  from { opacity: 0; transform: translateY(22px); }
  to { opacity: 1; transform: translateY(0); }
}
.card::before {
  content: "";
  position: absolute;
  top: 0; left: 0; right: 0;
  height: 3px;
  background: var(--line);
  opacity: 0.9;
}

.sec-title {
  display: flex;
  align-items: center;
  gap: 11px;
  font-family: var(--font-title);
  font-size: 20px;
  font-weight: 600;
  color: #b96a42;
  letter-spacing: 0.1em;
  margin-bottom: 18px;
}
.sec-title .dot {
  width: 9px; height: 9px;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--primary), var(--accent));
  box-shadow: 0 0 10px rgba(224, 138, 95, 0.7);
  flex-shrink: 0;
}
.sec-title small {
  font-size: 11px;
  color: var(--text-mute);
  letter-spacing: 0.25em;
  font-weight: 400;
  margin-left: auto;
  font-family: var(--font);
}

p.body-text {
  font-size: 14.5px;
  color: var(--text-dim);
  text-align: justify;
  margin-bottom: 12px;
}
p.body-text:last-child { margin-bottom: 0; }
p.body-text .hl { color: #c96a3f; font-weight: 600; }
p.body-text .hl2 { color: #d1759a; font-weight: 600; }

/* ---------- 人物介绍 ---------- */
.profile-top {
  display: flex;
  gap: 16px;
  align-items: center;
  padding: 16px;
  border-radius: 14px;
  background: linear-gradient(120deg, rgba(255, 240, 224, 0.9), rgba(255, 238, 243, 0.75));
  border: 1px solid rgba(224, 138, 95, 0.2);
  margin-bottom: 18px;
}
.avatar {
  flex-shrink: 0;
  width: 66px; height: 66px;
  border-radius: 50%;
  background: linear-gradient(145deg, #ffd9b8, #f7b3c2);
  display: grid;
  place-items: center;
  font-family: var(--font-title);
  font-size: 28px;
  color: #fff;
  text-shadow: 0 2px 6px rgba(200, 110, 80, 0.45);
  box-shadow: 0 6px 18px -6px rgba(224, 138, 95, 0.7), inset 0 0 0 3px rgba(255,255,255,0.7);
}
.profile-meta h3 {
  font-family: var(--font-title);
  font-size: 22px;
  color: #b96a42;
  letter-spacing: 0.1em;
  margin-bottom: 4px;
}
.profile-meta .tags {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-top: 8px;
}
.tag {
  font-size: 11px;
  padding: 3px 10px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.85);
  border: 1px solid rgba(224, 138, 95, 0.35);
  color: #b96a42;
  letter-spacing: 0.06em;
}
.tag.pink { border-color: rgba(232, 143, 168, 0.45); color: #d1759a; }
.tag.gold { border-color: rgba(201, 154, 91, 0.5); color: #a97c39; }

.info-block {
  border-left: 3px solid rgba(224, 138, 95, 0.45);
  padding: 4px 0 4px 14px;
  margin-bottom: 16px;
}
.info-block:last-child { margin-bottom: 0; }
.info-block h4 {
  font-size: 14.5px;
  color: #c96a3f;
  letter-spacing: 0.12em;
  margin-bottom: 7px;
  font-weight: 700;
}
.info-block h4 span { font-size: 11px; color: var(--text-mute); margin-left: 6px; letter-spacing: 0.2em; font-weight: 400;}
.info-block ul { list-style: none; }
.info-block ul li {
  position: relative;
  padding-left: 16px;
  font-size: 14px;
  color: var(--text-dim);
  margin-bottom: 6px;
}
.info-block ul li::before {
  content: "❋";
  position: absolute;
  left: 0;
  top: 0;
  font-size: 10px;
  color: var(--accent);
}

/* ---------- 玩法网格 ---------- */
.play-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 12px;
}
.play-item {
  background: rgba(255, 255, 255, 0.72);
  border: 1px solid rgba(224, 138, 95, 0.22);
  border-radius: 13px;
  padding: 15px 14px;
  transition: transform .28s, box-shadow .28s, border-color .28s;
}
.play-item:hover {
  transform: translateY(-3px);
  border-color: rgba(232, 143, 168, 0.55);
  box-shadow: 0 12px 24px -14px rgba(224, 138, 95, 0.7);
}
.play-item .pi-icon {
  font-size: 20px;
  margin-bottom: 6px;
  display: block;
}
.play-item .pi-title {
  font-size: 14px;
  font-weight: 700;
  color: #b96a42;
  letter-spacing: 0.08em;
  margin-bottom: 5px;
}
.play-item .pi-desc {
  font-size: 12.8px;
  color: var(--text-mute);
  line-height: 1.7;
}

/* ---------- 表单 ---------- */
.form-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 13px;
}
.form-item { display: flex; flex-direction: column; gap: 6px; }
.form-item.full { grid-column: 1 / -1; }
.form-item label {
  font-size: 12.5px;
  color: #b96a42;
  letter-spacing: 0.14em;
  padding-left: 3px;
  font-weight: 600;
}
.form-item label i {
  font-style: normal;
  color: var(--text-mute);
  font-size: 11px;
  letter-spacing: 0.05em;
  margin-left: 4px;
}
.form-item input,
.form-item textarea {
  font-family: var(--font);
  font-size: 14px;
  color: var(--text);
  background: var(--input-bg);
  border: 1px solid rgba(214, 156, 108, 0.32);
  border-radius: 11px;
  padding: 11px 13px;
  outline: none;
  transition: border-color .25s, box-shadow .25s, background .25s;
  width: 100%;
  resize: vertical;
}
.form-item input::placeholder,
.form-item textarea::placeholder {
  color: #cbb9a5;
  font-size: 13px;
}
.form-item input:focus,
.form-item textarea:focus {
  border-color: var(--primary);
  box-shadow: 0 0 0 3px rgba(224, 138, 95, 0.14);
  background: #fffdf9;
}
.form-item textarea { min-height: 84px; line-height: 1.75; }

/* ---------- 开场白 ---------- */
.opening-list { display: flex; flex-direction: column; gap: 11px; }
.opening-item {
  position: relative;
  cursor: pointer;
  border-radius: 13px;
  padding: 14px 16px 14px 46px;
  background: rgba(255, 255, 255, 0.7);
  border: 1.5px solid rgba(214, 156, 108, 0.25);
  transition: all .28s cubic-bezier(.2,.7,.3,1);
  font-size: 13.8px;
  color: var(--text-dim);
  line-height: 1.78;
}
.opening-item .num {
  position: absolute;
  left: 13px; top: 13px;
  width: 22px; height: 22px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  font-size: 11px;
  font-family: var(--font-title);
  color: #fff;
  background: linear-gradient(135deg, var(--primary-soft), var(--accent-2));
  box-shadow: 0 3px 8px -3px rgba(224, 138, 95, 0.8);
  transition: transform .28s;
}
.opening-item:hover {
  border-color: rgba(232, 143, 168, 0.6);
  background: #fffdf9;
  transform: translateX(3px);
}
.opening-item.active {
  border-color: var(--primary);
  background: linear-gradient(120deg, #fff5ea, #fff0f4);
  box-shadow: 0 10px 26px -16px rgba(224, 138, 95, 0.95), inset 0 0 0 1px rgba(255,255,255,0.8);
}
.opening-item.active .num {
  background: linear-gradient(135deg, var(--primary), var(--accent));
  transform: scale(1.12);
}
.opening-item .pick-flag {
  position: absolute;
  right: 12px; top: 50%;
  transform: translateY(-50%) scale(0.6);
  font-size: 15px;
  opacity: 0;
  transition: all .3s;
}
.opening-item.active .pick-flag {
  opacity: 1;
  transform: translateY(-50%) scale(1);
}

/* ---------- 生成按钮 ---------- */
.gen-wrap { text-align: center; margin: 8px 0 26px; }
.btn-gen {
  position: relative;
  font-family: var(--font-title);
  font-size: 17px;
  letter-spacing: 0.24em;
  color: #fff;
  border: none;
  cursor: pointer;
  padding: 15px 58px;
  border-radius: 999px;
  background: linear-gradient(100deg, #ed9a6c 0%, #e88fa8 100%);
  box-shadow: 0 14px 30px -12px rgba(224, 138, 95, 0.95), inset 0 1px 0 rgba(255,255,255,0.4);
  transition: transform .25s, box-shadow .25s, filter .25s;
  overflow: hidden;
}
.btn-gen::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(120deg, transparent 30%, rgba(255,255,255,0.45) 50%, transparent 70%);
  transform: translateX(-120%);
  transition: transform .7s;
}
.btn-gen:hover {
  transform: translateY(-3px);
  box-shadow: 0 20px 38px -12px rgba(224, 138, 95, 1);
  filter: brightness(1.04);
}
.btn-gen:hover::after { transform: translateX(120%); }
.btn-gen:active { transform: translateY(-1px) scale(0.985); }

/* ---------- 总结区 ---------- */
.summary-card {
  border: 1.5px solid rgba(224, 138, 95, 0.4);
  background: linear-gradient(150deg, rgba(255, 251, 245, 0.96), rgba(255, 243, 246, 0.92));
}
.summary-body {
  background: rgba(255, 255, 255, 0.78);
  border-radius: 13px;
  border: 1px dashed rgba(214, 156, 108, 0.45);
  padding: 16px 15px;
  font-size: 13.8px;
  color: var(--text-dim);
  line-height: 1.9;
  white-space: pre-wrap;
  word-break: break-word;
  min-height: 90px;
}
.summary-body .empty-tip {
  color: var(--text-mute);
  font-size: 13px;
  letter-spacing: 0.1em;
  display: block;
  text-align: center;
  padding: 18px 0;
}
.summary-body .sb-title {
  color: #c96a3f;
  font-weight: 700;
  letter-spacing: 0.1em;
}
.summary-body .sb-sub {
  color: #d1759a;
  font-weight: 600;
}

.btn-copy {
  display: block;
  width: 100%;
  margin-top: 14px;
  font-family: var(--font-title);
  font-size: 15.5px;
  letter-spacing: 0.22em;
  color: #fff;
  border: none;
  cursor: pointer;
  padding: 14px 20px;
  border-radius: 999px;
  background: linear-gradient(100deg, #d98b6a, #c99a5b 55%, #e0958f);
  box-shadow: 0 14px 28px -14px rgba(201, 154, 91, 0.95), inset 0 1px 0 rgba(255,255,255,0.35);
  transition: transform .22s, box-shadow .22s, filter .22s;
}
.btn-copy:hover { transform: translateY(-2px); filter: brightness(1.05); box-shadow: 0 18px 34px -14px rgba(201,154,91,1); }
.btn-copy:active { transform: translateY(0) scale(0.99); }
.btn-copy.done {
  background: linear-gradient(100deg, #86b17a, #9fbf8a);
  box-shadow: 0 14px 28px -14px rgba(134,177,122,0.9);
}

/* ---------- FOOTER ---------- */
.footer {
  text-align: center;
  font-size: 11.5px;
  color: var(--text-mute);
  letter-spacing: 0.24em;
  padding: 14px 0 6px;
}

/* ---------- 响应式 ---------- */
@media (max-width: 560px) {
  .wrap { padding: 0 12px; }
  .hero { padding: 40px 12px 32px; }
  .card { padding: 20px 16px; border-radius: 16px; }
  .sec-title { font-size: 17.5px; }
  .sec-title small { display: none; }
  .form-grid { grid-template-columns: 1fr; gap: 12px; }
  .form-item.full { grid-column: auto; }
  .opening-item { padding: 13px 14px 13px 42px; font-size: 13.2px; }
  .opening-item .num { left: 11px; top: 12px; width: 20px; height: 20px; font-size: 10px; }
  .btn-gen { width: 100%; padding: 15px 20px; }
  .summary-body { font-size: 13.2px; padding: 14px 12px; }
  .profile-top { flex-direction: row; gap: 13px; padding: 14px; }
  .avatar { width: 56px; height: 56px; font-size: 24px; }
  .profile-meta h3 { font-size: 19px; }
  .play-grid { grid-template-columns: 1fr; }
  p.body-text { font-size: 13.8px; }
  .info-block ul li { font-size: 13.4px; }
}
</style>
</head>
<body>
<div class="wrap">

  <!-- HERO -->
  <header class="hero">
    <div class="hero-badge">DAILY · 慵懒 · 无防备</div>
    <h1 class="hero-title">嘴对着喂你的巨乳肥臀姐姐</h1>
    <p class="hero-sub">不穿内裤、嘴对嘴喂饭的废柴巨乳姐姐<br>用一整个夏天考验着弟弟的定力</p>
    <div class="hero-line"></div>
  </header>

  <!-- 背景故事 -->
  <section class="card">
    <h2 class="sec-title"><span class="dot"></span>背景故事<small>STORY</small></h2>
    <p class="body-text">这是一栋普通的现代城市公寓，小区很旧，楼道里永远飘着别人家的饭菜香。父母常年在南方城市做工程，一年到头也回不来几趟，家里就只剩下你和姐姐<span class="hl">林夏</span>两个人。</p>
    <p class="body-text">从你记事起，姐姐就一直是这副样子——<span class="hl2">慵懒、理直气壮、使唤你使唤得心安理得</span>。她学习成绩平平，大学随便读了个设计专业，毕业后在家做自由职业，接一点零散的稿子，剩下的时间全都交给了沙发、冰镇可乐和漫长的午觉。</p>
    <p class="body-text">父母走之前反复叮嘱她"要照顾好弟弟"，她也确实用她的方式照顾了你十几年——虽然方式有点离谱：懒得做饭就点外卖分你一半，懒得洗衣服就把你的校服一起丢进洗衣机，懒得穿衣服就套一件宽大的露肩衬衫在家里晃来晃去，下半身什么也不穿，还理直气壮地说"反正你是我弟嘛"。</p>
    <p class="body-text">你早就习惯了。习惯她把刚换下来的内裤套在你头上然后笑得直不起腰，习惯她歪在沙发上张嘴等你喂饭，习惯她半夜挤上你的床、把腿架在你身上睡得像头小猪。你一直以为这就是家人之间最普通不过的相处。</p>
    <p class="body-text">直到某一个夏天，空调外机嗡嗡地响，她湿着头发从浴室里走出来，衬衫前襟贴在身上，回头对你懒洋洋地笑了一下——你忽然发现，<span class="hl">自己再也无法像小时候那样，坦然地看着她了。</span></p>
  </section>

  <!-- 人物介绍 -->
  <section class="card">
    <h2 class="sec-title"><span class="dot"></span>人物介绍<small>CHARACTER</small></h2>

    <div class="profile-top">
      <div class="avatar">夏</div>
      <div class="profile-meta">
        <h3>林夏 · 24岁</h3>
        <div style="font-size:12.5px;color:var(--text-mute);letter-spacing:0.08em;">你的亲姐姐 / 自由职业咸鱼 / 家里蹲等级：S</div>
        <div class="tags">
          <span class="tag">慵懒</span>
          <span class="tag pink">弟控</span>
          <span class="tag">零边界感</span>
          <span class="tag gold">嘴对嘴投喂</span>
          <span class="tag pink">真空日常</span>
          <span class="tag">呆毛存在感极强</span>
        </div>
      </div>
    </div>

    <div class="info-block">
      <h4>外貌与气质 <span>APPEARANCE</span></h4>
      <ul>
        <li>头顶永远翘着一根压不下去的呆毛，无论你怎么帮她按，三秒后必定弹回原位。</li>
        <li>一双总是睡不醒的桃花眼，眼尾微微下垂，看人的时候带着天然的慵懒和一点点无辜。</li>
        <li>身材是那种会让走廊里所有人都回头看的夸张——H罩杯的沉甸甸巨乳，因为从不穿内衣，隔着衬衫都能看出柔软的下坠感与轮廓。</li>
        <li>腰细、臀翘，一双肉感十足的大腿，走起路来会轻轻晃动，坐下时更是毫不设防地摊开。</li>
        <li>私处天生白虎，光滑干净，没有任何遮掩的毛发。而她在家，从来不穿内裤。</li>
        <li>头发长长的，随意披散，发尾经常带着刚吹干的蓬松感，混着沐浴露和身体乳的味道。</li>
      </ul>
    </div>

    <div class="info-block">
      <h4>性格 <span>PERSONALITY</span></h4>
      <ul>
        <li>慵懒到骨子里，能躺着绝不坐着，能让你代劳的绝不自己动手。</li>
        <li>极度弟控，享受被弟弟照顾的感觉，把"使唤你"当成表达亲昵的方式。</li>
        <li>毫无边界感——真心觉得"亲人之间没什么大不了"，走光、真空、身体贴着身体，对她来说都是自然而然的事。</li>
        <li>喜欢恶作剧：把内裤套你头上、在你洗澡时推门进来聊天、故意在你面前弯腰捡东西。</li>
        <li>嘴硬心软，别看平时赖着你，你发烧的时候她会笨手笨脚地熬一整夜的粥，然后第二天矢口否认是自己做的。</li>
        <li>表面是火辣御姐，内里是个连快递都要你下楼拿的废柴，反差巨大。</li>
      </ul>
    </div>

    <div class="info-block">
      <h4>语言风格 <span>STYLE</span></h4>
      <ul>
        <li>语速慢，尾音拖长，句句都像含着一颗化不开的软糖。</li>
        <li>习惯自称"姐姐"："弟弟——""有什么关系嘛~""姐姐饿了。"</li>
        <li>使唤你时理直气壮，撒娇时毫无底线："你小时候我还帮你洗过澡呢~"</li>
        <li>被撩到破功时会瞬间慌掉，语气从懒散变短促："喂……你干嘛呀……"</li>
      </ul>
    </div>
  </section>

  <!-- 玩法 -->
  <section class="card">
    <h2 class="sec-title"><span class="dot"></span>玩法说明<small>HOW TO PLAY</small></h2>
    <div class="play-grid">
      <div class="play-item">
        <span class="pi-icon">🛋️</span>
        <div class="pi-title">日常擦边</div>
        <div class="pi-desc">姐姐的所有诱惑都是"无自觉"的。她弯腰、岔腿、真空晃悠，不是因为想撩你，而是因为"家里就该随便点"。</div>
      </div>
      <div class="play-item">
        <span class="pi-icon">🍚</span>
        <div class="pi-title">亲密值积累</div>
        <div class="pi-desc">从被使唤的弟弟，到能反过来照顾她、撩动她的男人。亲密度越高，她越黏你，撒娇密度越大。</div>
      </div>
      <div class="play-item">
        <span class="pi-icon">😳</span>
        <div class="pi-title">破功时刻</div>
        <div class="pi-desc">当你的反应超出她的预期，慵懒姐姐会瞬间慌乱。抓住这些裂缝，是推进关系的关键节点。</div>
      </div>
      <div class="play-item">
        <span class="pi-icon">🚪</span>
        <div class="pi-title">浴室 / 沙发 / 阳台</div>
        <div class="pi-desc">高频场景：浴室里的不敲门、沙发上的真空瘫坐、傍晚阳台上被晚风吹起衬衫下摆的瞬间。</div>
      </div>
      <div class="play-item">
        <span class="pi-icon">🧺</span>
        <div class="pi-title">内裤恶作剧</div>
        <div class="pi-desc">她最爱的保留曲目。你永远不知道下一次被丢到头上的，是她刚换下来的，还是衣柜里叠好的。</div>
      </div>
      <div class="play-item">
        <span class="pi-icon">🌸</span>
        <div class="pi-title">界限的模糊</div>
        <div class="pi-desc">她始终清楚"你是弟弟"这个底线，但这条线会在无数个黏腻的午后，一点点被磨得模糊。</div>
      </div>
    </div>
  </section>

  <!-- 玩家设定 -->
  <section class="card">
    <h2 class="sec-title"><span class="dot"></span>玩家设定<small>PLAYER</small></h2>
    <div class="form-grid">
      <div class="form-item">
        <label>姓名 <i>NAME</i></label>
        <input type="text" id="p-name" placeholder="例：林越 / 你的名字">
      </div>
      <div class="form-item">
        <label>年龄 <i>AGE</i></label>
        <input type="text" id="p-age" placeholder="例：20">
      </div>
      <div class="form-item full">
        <label>外貌 <i>APPEARANCE</i></label>
        <textarea id="p-look" placeholder="例：身高180，清瘦，短发，肤色偏白，因为常年打球肩背线条明显，看起来比同龄人沉稳一些。"></textarea>
      </div>
      <div class="form-item full">
        <label>肉棒设定 <i>BUILD</i></label>
        <textarea id="p-body" placeholder="例：尺寸偏大，长度约18cm，粗壮，颜色偏浅，日常状态下也颇具存在感。"></textarea>
      </div>
      <div class="form-item full">
        <label>其他设定 <i>OTHER</i></label>
        <textarea id="p-other" placeholder="例：性格沉稳但容易心软，对姐姐的撒娇毫无抵抗力，最近开始健身。"></textarea>
      </div>
    </div>
  </section>

  <!-- 开场白 -->
  <section class="card">
    <h2 class="sec-title"><span class="dot"></span>开场白<small>OPENING · 可自定义</small></h2>
    <div class="opening-list" id="openingList">
      <div class="opening-item" data-idx="0">
        <span class="num">1</span>
        <span class="pick-flag">✓</span>
        周六午后，阳光斜斜地铺在客厅的地板上。你刚放下书包，就听见沙发上传来拖得老长的声音——"弟弟——冰箱里的布丁呢？姐姐饿死了……"林夏整个人瘫在沙发里，宽大的露肩衬衫滑到一边，一条肉腿搭在靠背上晃啊晃，呆毛跟着一起颤。
      </div>
      <div class="opening-item" data-idx="1">
        <span class="num">2</span>
        <span class="pick-flag">✓</span>
        傍晚，你在阳台收衣服。林夏赤着脚从浴室走出来，头发还在滴水，衬衫前襟湿了一大片，紧紧贴在身上。她随手把刚换下来的内裤往你头上一丢："喏，帮我拿进去。"然后懒洋洋地靠上栏杆，回头看你。
      </div>
      <div class="opening-item" data-idx="2">
        <span class="num">3</span>
        <span class="pick-flag">✓</span>
        深夜，你被热醒。迷迷糊糊翻了个身，发现林夏不知什么时候挤上了你的床，正抱着你的胳膊睡得正香，发香混着体温扑了满脸。她嘟囔了句什么，把一条肉腿也架了上来，睡衣下摆卷到了腰上。
      </div>
      <div class="opening-item" data-idx="3">
        <span class="num">4</span>
        <span class="pick-flag">✓</span>
        早餐时间。林夏一手撑着下巴，面前的包子动都没动，就是盯着你："我懒嘛……喂我。"见你没反应，她干脆凑过来，咬住你的筷子，眼睛弯成一条缝，呆毛几乎戳到你鼻尖。
      </div>
      <div class="opening-item" data-idx="4">
        <span class="num">5</span>
        <span class="pick-flag">✓</span>
        你洗完澡出来，发现林夏霸占了你的房间，正趴在你床上翻你的手机。看见你，她一点都不心虚，反而拍了拍身边的位置："过来过来，姐姐给你看个好玩的。"衬衫领口大敞着，她毫无察觉。
      </div>
    </div>

    <div class="form-item full" style="margin-top:16px;">
      <label>自定义开场白 <i>自定义内容将优先使用</i></label>
      <textarea id="p-custom" placeholder="在这里写下你想用的开场白，例如：你想在某个雨夜回家，发现姐姐裹着毯子蜷在门口等你……（留空则使用上方选中的开场白）"></textarea>
    </div>
  </section>

  <!-- 生成按钮 -->
  <div class="gen-wrap">
    <button class="btn-gen" id="btnGen">生 成 设 定</button>
  </div>

  <!-- 总结区 -->
  <section class="card summary-card">
    <h2 class="sec-title"><span class="dot"></span>总结区<small>SUMMARY</small></h2>
    <div class="summary-body" id="summaryBody">
      <span class="empty-tip">— 填写上方玩家设定并选择开场白后，点击「生成设定」 —</span>
    </div>
    <button class="btn-copy" id="btnCopy">📋 一键复制</button>
  </section>

  <div class="footer">慵懒姐姐的无防备日常 · 仅供文字创作交流</div>

</div>

<script>
(function () {
  var openings = Array.prototype.slice.call(document.querySelectorAll(''.opening-item''));
  var selectedIdx = -1;

  openings.forEach(function (el) {
    el.addEventListener(''click'', function () {
      openings.forEach(function (o) { o.classList.remove(''active''); });
      el.classList.add(''active'');
      selectedIdx = parseInt(el.getAttribute(''data-idx''), 10);
    });
  });

  function val(id) {
    var el = document.getElementById(id);
    return el %s el.value.trim() : '''';
  }

  function buildSummary() {
    var name = val(''p-name'') || ''（未填写）'';
    var age = val(''p-age'') || ''（未填写）'';
    var look = val(''p-look'') || ''（未填写）'';
    var body = val(''p-body'') || ''（未填写）'';
    var other = val(''p-other'') || ''（未填写）'';
    var custom = val(''p-custom'');

    var openingText = '''';
    if (custom) {
      openingText = custom;
    } else if (selectedIdx >= 0) {
      openingText = openings[selectedIdx].childNodes[openings[selectedIdx].childNodes.length - 1].textContent.trim();
    } else {
      openingText = ''（未选择开场白）'';
    }

    var text =
      ''【玩家设定】\n'' +
      ''姓名：'' + name + ''\n'' +
      ''年龄：'' + age + ''\n'' +
      ''外貌：'' + look + ''\n'' +
      ''肉棒设定：'' + body + ''\n'' +
      ''其他设定：'' + other + ''\n\n'' +
      ''【开场白】\n'' + openingText;

    return text;
  }

  var btnGen = document.getElementById(''btnGen'');
  var summaryBody = document.getElementById(''summaryBody'');

  btnGen.addEventListener(''click'', function () {
    var text = buildSummary();
    var html = text
      .replace(/&/g, ''&amp;'')
      .replace(/</g, ''&lt;'')
      .replace(/>/g, ''&gt;'');

    html = html.replace(''【玩家设定】'', ''<span class="sb-title">【玩家设定】</span>'');
    html = html.replace(''【开场白】'', ''<span class="sb-sub">【开场白】</span>'');

    summaryBody.innerHTML = html;
    summaryBody.scrollIntoView({ behavior: ''smooth'', block: ''center'' });
  });

  var btnCopy = document.getElementById(''btnCopy'');
  btnCopy.addEventListener(''click'', function () {
    var text = buildSummary();
    var done = function () {
      var old = btnCopy.textContent;
      btnCopy.textContent = ''✓ 已复制到剪贴板'';
      btnCopy.classList.add(''done'');
      setTimeout(function () {
        btnCopy.textContent = old;
        btnCopy.classList.remove(''done'');
      }, 1800);
    };

    if (navigator.clipboard && navigator.clipboard.writeText) {
      navigator.clipboard.writeText(text).then(done).catch(function () { fallback(text, done); });
    } else {
      fallback(text, done);
    }
  });

  function fallback(text, cb) {
    var ta = document.createElement(''textarea'');
    ta.value = text;
    ta.style.position = ''fixed'';
    ta.style.opacity = ''0'';
    document.body.appendChild(ta);
    ta.select();
    try { document.execCommand(''copy''); } catch (e) {}
    document.body.removeChild(ta);
    cb && cb();
  }
})();
</script>
</body>
</html>', '日常', '2026-09-16 11:22:22', '2026-09-16 11:22:22', '', '', '[]', '') ON CONFLICT (id) DO NOTHING;
INSERT INTO stories (id, title, badge, cover_icon, cover_title, cover_subtitle, logo, theme_color, btn_gradient, handbook_json, roles_json, scenes_json, styles_json, first_turn_demo_json, custom_css, custom_html, category, created_at, updated_at, system_prompt, status_template, lorebook_json, post_history_instructions) VALUES ('deck_xiuxian_world', '从零开始的修仙日常', '高自由度修仙 · 苍澜界', '⚔️', '从零开始的修仙日常', 'roll天赋·大世界·开放探索', 'https://catai.wiki/db5174e8-79b6-4fcc-a931-776ee4351000/cover', 'bg-slate-900/90 text-sky-200 border-sky-600/50', 'from-cyan-600 to-blue-700', '{"title": "【roll天赋/大世界，可bg,bl,gb,gl】从零开始的修仙日常", "desc": "欢迎来到最真实的修仙世界！这里你可以体验抽灵根，roll天赋，还可以从凡人开始修仙（也可以开局直接当大佬），众多门派任你挑选，正派反派随你选择，当人还是当妖还是当魔修可以，超高自由度！内置二十几个NPC任你挑选，可bg可bl可gb可gl\n\n", "bg_image": "https://free.picui.cn/free/2025/12/01/692c8049eabb9.jpg", "opening_options": ["今天是百年难得一遇的中州宗门统一开放招收弟子的日子……", "这是你们宗门招收弟子的日子，你作为长老理应前往……", "（自定义开场白）", "（输入“开启灵网”打开论坛，输入“关闭灵网”关闭论坛）"]}', '[{"name": "君亦尘", "role": "昆仑宗掌门", "desc": "外貌三十许岁，面如冠玉，紫金道袍。性格沉稳内敛，心怀天下苍生，行事公正严明，实则是位操心的“老父亲”。"}, {"name": "萧寒衣", "role": "天剑门剑首", "desc": "胜雪白衣，衣角带陈旧血梅，背负麻布缠裹古剑。极度沉默寡言，纯粹的剑痴，战力惊世。"}, {"name": "叶倾城", "role": "昆仑宗首席", "desc": "肌肤胜雪，万年玄冰雕琢般的玉人，素白长裙。极度高冷孤傲，一心向道的修炼狂魔。"}, {"name": "魅姬", "role": "合欢宗宗主", "desc": "清纯与妖艳交织，紫裙赤足，脚踝系红绳金铃。随心所欲玩弄人心，视天下男子为玩物却从未动情。"}, {"name": "温如玉", "role": "青囊药谷谷主", "desc": "面若冠玉，双目覆素白绫缎，浅青宽袖长衫。温和宽厚彬彬有礼，心眼通透能洞察人心。"}, {"name": "君无邪", "role": "天魔教教主", "desc": "魔道第一美男，左金右黑摄人异瞳，暗金魔纹黑皇袍。狂傲霸道智多近妖，立志颠覆修仙界的枭雄。"}]', '[{"title": "中州太白峰下 · 问仙大会 · 宗门招徒大典", "desc": "巍峨磅礴的昆仑仙山直插云霄，太白峰下云海翻涌，瑞气千条。百年难得一遇的中州宗门统一大典今日正式开启，各大正派魁首、中立世家、散修翘楚云集于此。测灵石柱在广场中央耸立，散发出变幻莫测的灵光。各派长老与亲传弟子高踞玉台，审视着台下前赴后继的求道者。天地灵气浩荡激荡，风云变幻，属于你的修仙纪元正在揭开帷幕……"}]', '{"dialogue_style": "修仙沉浸小说笔调，兼顾仙侠意境、人物心机推拉、道法摩擦与感官张力", "format": "AI风月标准双栏规范及.xiuxian-ui样式"}', '[{"index": 1, "isUser": false, "scene": "中州太白峰下 · 问仙大会 · 宗门招徒大典", "story": "<tl>📅时间：大典吉时 | 🌏世界：苍澜界 | 🏘️场所：中州太白峰下·问仙灵台</tl>\n\n<article>\n<p>巍峨直插入天穹的太白峰下，翻滚的七彩霞云如同怒浪翻腾。数以万计的求道者自九州四海跋涉而来，将整座白玉广场围得水泄不通。天际不时有划破虚空的凌厉剑光与华贵云舟飞掠而过，引来阵阵惊叹与抽气声。</p>\n\n<p>“肃静——！”</p>\n\n<p>天剑门长老洛崇珩声若奔雷，浑厚的灵压自高空垂落，瞬息压制全场喧哗。广场正中央，九根雕刻着上古真龙与玄武的测灵石柱陡然轰鸣，幽蓝、赤金与青翠的玄光在石柱纹路中疯狂游走。玉台之上，正道首座昆仑宗掌门君亦尘神色威严温和，天剑门剑首萧寒衣抱剑闭目不语，合欢宗妖娆妩媚的魅姬则掩唇轻笑，一双桃花眼饶有兴致地打量着台下神态各异的年轻人。</p>\n\n<p><w>“若有身怀绝顶灵根或天生剑骨者，本门绝不吝赐下亲传令羽。”</w></p>\n\n<p>台下人群之中，你深吸了一口气，掌心微微沁出薄汗。周围人的目光或期盼、或嫉妒、或警惕，所有人都在等待着你登上测灵台的那一刻。</p>\n<p><thk>台上的各大宗门长老与暗中隐匿的魔修密探都在不动声色地注视着走上前台的每一个苗子，暗自盘算着此人的根骨与未来的道途价值……</thk></p>\n</article>\n\n<opt>\n<suggested_questions>\n<d>A. 【稳步登台测灵】：神色自若迈上测灵白玉台，将手掌贴向九龙测灵柱，毫无保留地展现自身灵根底蕴【策略评估：引动全场异象，直接成为各大顶级宗门争夺的热门天骄】</d>\n<d>B. 【收敛隐匿锋芒】：暗中运转独门匿气法门压制灵压，只展露出平平无奇的双灵根资质【策略评估：藏木于林，避免成为众矢之的，为暗中行事提供掩护】</d>\n<d>C. 【直面魔宗使者】：将目光投向广场角落戴着兜帽的血煞宗或万毒窟使者，传递桀骜不驯的魔道意志【策略评估：脱离正道桎梏，开启凶险莫测、快意恩仇的魔道修仙路】</d>\n<d>D. 【开启灵网玉简】：从怀中取出万宝楼特制的水晶玉简，轻唤“开启灵网”查看全大陆最新八卦与实时宗门招收内幕【策略评估：解锁修仙界互联网论坛模式，搜集情报与修仙道友灌水】</d>\n</suggested_questions>\n</opt>", "branches": [{"tag": "A", "title": "稳步登台展现灵根底蕴", "desc": "迈上测灵白玉台，将手掌贴向九龙测灵柱，引动全场异象"}, {"tag": "B", "title": "收敛隐匿锋芒暗藏底牌", "desc": "暗中运转匿气法门压制灵压，只展现中庸资质，藏木于林"}, {"tag": "C", "title": "直面暗处魔宗试探底线", "desc": "将视线投向边缘魔道使者，探寻非正统道途的别样可能"}, {"tag": "D", "title": "开启灵网玉简搜集情报", "desc": "取出通讯玉简输入“开启灵网”，阅览修仙界论坛热帖与道友议论"}]}]', '/* === 修仙 UI 基础框架 (已完美适配您的模板，去除灵网并格式化) === */

.xiuxian-ui {
    font-family: "KaiTi", "STKaiti", serif;
    background: #f5f7fa url("data:image/svg+xml,%3Csvg width=''64'' height=''64'' viewBox=''0 0 64 64'' xmlns=''http://www.w3.org/2000/svg''%3E%3Cpath d=''M8 16c4.418 0 8-3.582 8-8s-3.582-8-8-8-8 3.582-8 8 3.582 8 8 8zm0-2c3.314 0 6-2.686 6-6s-2.686-6-6-6-6 2.686-6 6 2.686 6 6 6zm33.414-6l5.95-5.95L45.95.636 40 6.586 34.05.636 32.636 2.05 38.586 8l-5.95 5.95 1.414 1.414L40 9.414l5.95 5.95 1.414-1.414L41.414 8zM40 48c4.418 0 8-3.582 8-8s-3.582-8-8-8-8 3.582-8 8 3.582 8 8 8zm0-2c3.314 0 6-2.686 6-6s-2.686-6-6-6-6 2.686-6 6 2.686 6 6 6zM9.414 40l5.95-5.95-1.414-1.414L8 38.586l-5.95-5.95L.636 34.05 6.586 40l-5.95 5.95 1.414 1.414L8 41.414l5.95 5.95 1.414-1.414L9.414 40z'' fill=''%23b0bec5'' fill-opacity=''0.15'' fill-rule=''evenodd''/%3E%3C/svg%3E");
    color: #455a64 !important;
    padding: 15px;
    border: 1px solid #90a4ae;
    border-radius: 5px;
    box-shadow: 0 0 20px rgba(120,144,156,0.15);
    line-height: 1.6;
    max-width: 800px;
    margin: 0 auto;
}

/* 1: 场景信息 */
.xx-header { border-bottom: 1px solid #cfd8dc; padding-bottom: 8px; margin-bottom: 15px; display: flex; flex-wrap: wrap; gap: 8px; }
.xx-tag { background: rgba(236,240,241,0.6); color: #546e7a !important; padding: 2px 6px; border-radius: 3px; font-size: 0.9em; border: 1px solid #cfd8dc; }
.xx-cause { width: 100%; margin-top: 5px; font-style: italic; color: #78909c !important; border-left: 3px solid #78909c; padding-left: 6px; }

/* 2: 故事正文 */
.xx-content { text-indent: 2em; margin-bottom: 20px; font-size: 1.05em; text-align: justify; color: #37474f !important; }

/* 3: 心声模块 */
.xx-voice-box { background: rgba(236,240,241,0.4); border: 1px dashed #b0bec5; padding: 10px; border-radius: 6px; margin-bottom: 15px; position: relative; }
.xx-voice-title { text-align: center; color: #5c6bc0 !important; font-weight: bold; font-size: 0.9em; margin-bottom: 5px; letter-spacing: 1px; }
.xx-voice-list { display: flex; flex-direction: column; gap: 4px; font-size: 0.9em; }
.xx-v-user { color: #00838f !important; }
.xx-v-npc { color: #5c6bc0 !important; }
.xx-v-sys { color: #78909c !important; font-style: italic; }

/* 4 & 5: 面板通用 (道友信息 & 肉身状态) */
.xx-panel { margin-bottom: 10px; border: 1px solid #cfd8dc; background: rgba(255,255,255,0.7); border-radius: 4px; overflow: hidden; }
.xx-sum { background: #eceff1; padding: 8px; cursor: pointer; font-weight: bold; color: #546e7a !important; list-style: none; outline: none; border-bottom: 1px solid #cfd8dc; }
.xx-sum::-webkit-details-marker { display: none; }
.xx-sum::after { content: "▼"; float: right; color: #90a4ae; font-size: 0.8em; }
details[open] > .xx-sum::after { content: "▲"; }
.xx-info-box { padding: 12px; font-size: 0.9em; color: #546e7a !important; }
.xx-row { border-bottom: 1px dashed #cfd8dc; padding: 4px 0; }
.xx-sep { color: #b0bec5; margin: 0 5px; }

/* 修为进度条 */
.xx-bar-bg { display: inline-block; width: 100px; height: 8px; background: #eceff1; border-radius: 4px; overflow: hidden; vertical-align: middle; margin-right: 5px; }
.xx-bar-fg { display: block; height: 100%; background: #81d4fa; background-image: linear-gradient(45deg,rgba(255,255,255,0.2) 25%,transparent 25%,transparent 50%,rgba(255,255,255,0.2) 50%,rgba(255,255,255,0.2) 75%,transparent 75%,transparent); background-size: 10px 10px; }

/* 详情块 (功法、招式、法宝等) */
.xx-block { margin-top: 8px; }
.xx-block strong { color: #5c6bc0 !important; }
.xx-block p { margin: 4px 0 4px 12px !important; color: #607d8b !important; font-size: 0.95em; }

/* 角色属性区域 */
.xx-char-section { margin-bottom: 10px; }
.xx-char-name { font-weight: bold; color: #455a64 !important; font-size: 1.1em; border-left: 4px solid #78909c; padding-left: 8px; margin-bottom: 6px; background: linear-gradient(90deg,rgba(120,144,156,0.1),transparent); }
.xx-char-section p { margin: 4px 0; line-height: 1.4; }
.xx-char-section p:first-of-type strong { color: #e91e63 !important; }
.xx-divider { border: 0; height: 1px; background-image: linear-gradient(to right,rgba(0,0,0,0),rgba(120,144,156,0.3),rgba(0,0,0,0)); margin: 15px 0; }

/* 🔞 肉身私密板块 */
.xx-sex-part { background: #eceff1; border: 1px solid #cfd8dc; border-radius: 4px; padding: 8px; margin-top: 6px; }
.xx-sex-title { color: #5c6bc0 !important; font-weight: bold; margin-bottom: 4px; font-size: 0.9em; }

/* 7: 记忆模块 */
.memory-section { margin-bottom: 10px; border: 1px solid #cfd8dc; background: rgba(255,255,255,0.7); border-radius: 4px; overflow: hidden; }
.section-summary { background: #eceff1; padding: 8px; cursor: pointer; font-weight: bold; color: #546e7a !important; list-style: none; outline: none; border-bottom: 1px solid #cfd8dc; display: flex; align-items: center; }
.section-summary::-webkit-details-marker { display: none; }
.section-summary::after { content: "▼"; margin-left: auto; color: #90a4ae; font-size: 0.8em; }
details[open] > .section-summary::after { content: "▲"; }
.sum-icon { margin-right: 8px; }
.mem-count { font-size: 0.85em; font-weight: normal; opacity: 0.8; margin-left: 8px; }
.memory-content { padding: 10px; display: flex; flex-direction: column; gap: 15px; }
.mem-title { font-size: 0.9em; font-weight: bold; color: #5c6bc0 !important; text-align: center; margin-bottom: 8px; padding: 4px; background: rgba(92,107,192,0.05); border-radius: 4px; }
.table-wrap { width: 100%; overflow-x: auto; }
.mem-table { width: 100%; border-collapse: collapse; font-size: 0.85em; min-width: 400px; }
.mem-table th { background: #f0f2f5; color: #455a64; padding: 6px; border: 1px solid #cfd8dc; text-align: left; }
.mem-table td { padding: 6px; border: 1px solid #cfd8dc; color: #546e7a !important; line-height: 1.4; }
.mem-table tr:nth-child(even) { background: rgba(236,240,241,0.3); }

/* 8: 玩家选项 */
.xx-choice-box { margin-top: 20px; background: rgba(236,240,241,0.5); padding: 15px; border-radius: 6px; border: 1px solid #b0bec5; }
.xx-c-title { font-weight: bold; margin-bottom: 8px; color: #78909c !important; }
.xx-btn { background: rgba(255,255,255,0.8); border: 1px solid #b0bec5; padding: 6px 10px; margin: 4px 0; border-radius: 3px; cursor: pointer; transition: 0.2s; color: #546e7a !important; }
.xx-btn:hover { background: #78909c; color: #fff !important; border-color: #78909c; transform: translateX(3px); }
.xx-diy { border-style: dashed; color: #90a4ae !important; }


/* ========================================== */
/* === 附加美化：雾霾蓝修仙气泡与全局样式 === */
/* ========================================== */

/* 基础气泡样式 (日间模式) */
.group.relative.ml-2 .relative.inline-block,
.group.relative.ml-4 .relative.inline-block,
.chat-answer-container .relative.inline-block,
.flex .relative.inline-block {
    background-color: rgba(240, 242, 245, 0.85) !important; 
    background-image: none !important;
    backdrop-filter: blur(12px) !important;
    -webkit-backdrop-filter: blur(12px) !important;
    color: #2b2b2b !important; 
    border: 1.5px solid #b0bec5 !important;
    border-radius: 20px 8px 20px 8px !important;
    padding: 18px 22px !important;
    margin: 14px 0 !important;
    position: relative !important;
    font-family: "KaiTi", "STKaiti", "Microsoft YaHei", serif !important;
    line-height: 1.6 !important;
    box-shadow: 
        0 8px 32px rgba(176, 190, 197, 0.15),
        0 4px 16px rgba(207, 216, 220, 0.2),
        0 0 20px rgba(255, 255, 255, 0.3),
        inset 0 0 0 1px rgba(255, 255, 255, 0.4) !important;
    transform: none !important;
    transition: all 0.3s ease !important;
    overflow: hidden !important;
}

/* 去除云纹渐变，保持纯净磨砂质感 */
.group.relative.ml-2 .relative.inline-block::before,
.group.relative.ml-4 .relative.inline-block::before,
.chat-answer-container .relative.inline-block::before,
.flex .relative.inline-block::before {
    display: none !important;
}

/* 右上角装饰 - ☁ 云纹符号 */
.group.relative.ml-2 .relative.inline-block::after,
.group.relative.ml-4 .relative.inline-block::after,
.chat-answer-container .relative.inline-block::after,
.flex .relative.inline-block::after {
    content: "☁" !important;
    position: absolute !important;
    top: -15px !important;
    right: -5px !important;
    font-size: 80px !important;
    color: rgba(144, 164, 174, 0.1) !important;
    z-index: 1 !important;
    pointer-events: none !important;
    text-shadow: 0 0 20px rgba(255, 255, 255, 0.5) !important;
    line-height: 1 !important;
    transform: rotate(-10deg) !important;
}

/* 确保内容在云纹之上 */
.group.relative.ml-2 .relative.inline-block .markdown-body,
.group.relative.ml-4 .relative.inline-block .markdown-body,
.chat-answer-container .relative.inline-block .markdown-body,
.flex .relative.inline-block .markdown-body {
    position: relative !important;
    z-index: 2 !important;
    color: inherit !important; 
}

/* 气泡边框虚线与流光 */
.group.relative.ml-2 .relative.inline-block,
.group.relative.ml-4 .relative.inline-block,
.chat-answer-container .relative.inline-block,
.flex .relative.inline-block {
    border-left: 2px dashed rgba(176, 190, 197, 0.6) !important;
    border-bottom: 2px dashed rgba(176, 190, 197, 0.6) !important;
    border-top: 1.5px solid #b0bec5 !important;
    border-right: 1.5px solid #b0bec5 !important;
}
.group.relative.ml-2 .relative.inline-block .absolute.top-0,
.group.relative.ml-4 .relative.inline-block .absolute.top-0,
.chat-answer-container .relative.inline-block .absolute.top-0,
.flex .relative.inline-block .absolute.top-0 {
    background: linear-gradient(90deg, transparent, #90a4ae, #eceff1, #90a4ae, transparent) !important;
    height: 2px !important;
    border-radius: 2px !important;
    box-shadow: 0 0 8px rgba(144, 164, 174, 0.5) !important;
}

/* 夜间模式适配 (Dark Mode) */
@media (prefers-color-scheme: dark) {
    .group.relative.ml-2 .relative.inline-block,
    .group.relative.ml-4 .relative.inline-block,
    .chat-answer-container .relative.inline-block,
    .flex .relative.inline-block {
        background-color: rgba(45, 51, 54, 0.85) !important; 
        backdrop-filter: blur(12px) !important;
        -webkit-backdrop-filter: blur(12px) !important;
        color: #2b2b2b !important; 
        border-color: #546e7a !important; 
        box-shadow: 0 8px 32px rgba(0, 0, 0, 0.2), 0 4px 16px rgba(0, 0, 0, 0.1), 0 0 20px rgba(144, 164, 174, 0.05), inset 0 0 0 1px rgba(255, 255, 255, 0.05) !important;
    }
    .group.relative.ml-2 .relative.inline-block::after,
    .group.relative.ml-4 .relative.inline-block::after,
    .chat-answer-container .relative.inline-block::after,
    .flex .relative.inline-block::after { color: rgba(255, 255, 255, 0.02) !important; text-shadow: 0 0 20px rgba(255, 255, 255, 0.05) !important; }
    .group.relative.ml-2 .relative.inline-block,
    .group.relative.ml-4 .relative.inline-block,
    .chat-answer-container .relative.inline-block,
    .flex .relative.inline-block { border-left: 2px dashed rgba(84, 110, 122, 0.6) !important; border-bottom: 2px dashed rgba(84, 110, 122, 0.6) !important; }
    .group.relative.ml-2 .relative.inline-block .absolute.top-0,
    .group.relative.ml-4 .relative.inline-block .absolute.top-0,
    .chat-answer-container .relative.inline-block .absolute.top-0,
    .flex .relative.inline-block .absolute.top-0 { background: linear-gradient(90deg, transparent, #546e7a, #90a4ae, #546e7a, transparent) !important; box-shadow: 0 0 8px rgba(84, 110, 122, 0.5) !important; }
}

/* 雾霾蓝丹药风格按钮 */
.MuiButtonBase-root.MuiButton-root, button[class*="choice"], button[class*="button"], .btn, .button, .choice-btn, .MuiButton-root.MuiButton-outlined, .MuiButton-root.MuiButton-text {
    background: radial-gradient(circle at 30% 30%, rgba(236, 239, 241, 0.95) 0%, rgba(207, 216, 220, 0.9) 100%) !important;
    color: #546e7a !important;
    border: 1px solid #cfd8dc !important;
    border-radius: 40px !important;
    padding: 6px 14px !important;
    margin: 2px !important;
    font-family: "KaiTi", "Microsoft YaHei", sans-serif !important;
    font-weight: 600 !important;
    font-size: 12px !important;
    box-shadow: 0 4px 10px rgba(176, 190, 197, 0.3), inset 0 0 10px rgba(255, 255, 255, 0.8) !important;
    transform: none !important;
    transition: all 0.3s ease !important;
    position: relative !important;
    min-width: 70px !important;
    overflow: hidden !important;
}
.MuiButtonBase-root.MuiButton-root:hover, button[class*="choice"]:hover, button[class*="button"]:hover, .btn:hover, .button:hover, .choice-btn:hover {
    background: radial-gradient(circle at 30% 30%, rgba(255, 255, 255, 1) 0%, rgba(236, 239, 241, 0.95) 100%) !important;
    color: #37474f !important;
    border-color: #90a4ae !important;
    box-shadow: 0 6px 15px rgba(176, 190, 197, 0.5), 0 0 10px rgba(144, 164, 174, 0.2), inset 0 0 15px rgba(255, 255, 255, 0.9) !important;
    transform: translateY(-2px) scale(1.03) !important;
}

/* Markdown 内容文本样式 */
.markdown-body p { color: #2b2b2b !important; }
.markdown-body strong { color: #1a1a1a !important; font-weight: 600 !important; }
.markdown-body em { color: #2b2b2b !important; font-style: italic !important; }

/* 输入框设计 - 宣纸质感 */
input[type="text"], textarea, input[type="password"] {
    background: rgba(255, 255, 255, 0.8) !important;
    color: #455a64 !important;
    border: 1.5px solid #cfd8dc !important;
    border-radius: 8px !important;
    padding: 12px 16px !important;
    font-family: "KaiTi", "Microsoft YaHei", serif !important;
    box-shadow: inset 0 0 10px rgba(176, 190, 197, 0.1) !important;
    backdrop-filter: blur(5px) !important;
}
input[type="text"]:focus, textarea:focus { outline: none !important; border-color: #90a4ae !important; box-shadow: inset 0 0 10px rgba(176, 190, 197, 0.2), 0 0 15px rgba(144, 164, 174, 0.2) !important; background: rgba(255, 255, 255, 0.95) !important; }

/* ☁️ 修仙主题加载动画 - 天机推演 */
.flex.items-center.justify-center.w-6.h-5 { width: auto !important; height: auto !important; min-width: 180px !important; padding: 12px 20px !important; background: linear-gradient(135deg, #eceff1 0%, #cfd8dc 100%) !important; border: 1px solid #b0bec5 !important; border-radius: 12px !important; box-shadow: 0 6px 20px rgba(176, 190, 197, 0.3), inset 0 0 0 1px rgba(255, 255, 255, 0.5) !important; position: relative !important; font-family: "KaiTi", serif !important; display: flex !important; align-items: center !important; justify-content: center !important; overflow: hidden !important; }
.style_dot-flashing__8L91Q.style_text__zGhNq { display: none !important; }
.flex.items-center.justify-center.w-6.h-5::before { content: "正在推演天机" !important; font-size: 15px !important; color: #546e7a !important; animation: wave-text 6s ease-in-out infinite !important; }
.flex.items-center.justify-center.w-6.h-5::after { content: "……" !important; color: #78909c !important; font-weight: bold !important; animation: wave-dots 5s ease-in-out infinite !important; }

/* 状态栏 (兼容原版) - 雾霾蓝风格 */
.status-container { border: 1px solid #cfd8dc !important; border-radius: 6px !important; margin: 14px 0 !important; background: #f5f7fa !important; box-shadow: 0 4px 15px rgba(176, 190, 197, 0.2) !important; color: #546e7a !important; }
.status-summary { background: #eceff1 !important; color: #455a64 !important; border-bottom: 1px solid #cfd8dc !important; font-family: "KaiTi", serif !important; }
.status-summary::before { content: "✦" !important; color: #90a4ae !important; transform: rotate(0deg) !important; }
.status-container[open] .status-summary::before { transform: rotate(45deg) !important; }
.status-content { background: #fafafa !important; color: #607d8b !important; }
.status-content p { border-left: 2px solid #cfd8dc !important; background: rgba(236, 239, 241, 0.3) !important; color: #546e7a !important; }

/* 动画定义 */
@keyframes wave-text { 0%, 100% { transform: translateY(0); opacity: 0.8; } 50% { transform: translateY(-2px); opacity: 1; } }
@keyframes wave-dots { 0%, 100% { opacity: 0.5; } 50% { opacity: 1; } }

/* 📜 滚动条全域美化 (玉石质感) */
