<script>
(function(){
var app=document.getElementById(''cvs-app'');
if(!app){return;}
var hd=app.querySelector(''#cvs-top'');
function smoothScrollToTop(){
if(hd&&hd.scrollIntoView){
try{hd.scrollIntoView({behavior:''smooth'',block:''start''});}catch(e){hd.scrollIntoView(true);}
}
try{window.scrollTo({top:0,behavior:''smooth''});}catch(e){window.scrollTo(0,0);}
}
var navBtns=app.querySelectorAll(''[data-target]'');
Array.prototype.forEach.call(navBtns,function(b){
b.addEventListener(''click'',function(){
var sel=b.getAttribute(''data-target'');
if(sel===''#cvs-top''||sel===''#cvs-app''){smoothScrollToTop();return;}
var t=app.querySelector(sel);
if(t&&t.scrollIntoView){
try{t.scrollIntoView({behavior:''smooth'',block:''start''});}catch(e){t.scrollIntoView(true);}
}
});
});
var scCards=app.querySelectorAll(''.sc-card'');
var customBox=app.querySelector(''#custom-scenario-box'');
var currentScenario='''';
Array.prototype.forEach.call(scCards,function(c){
c.addEventListener(''click'',function(){
Array.prototype.forEach.call(scCards,function(x){x.classList.remove(''active'');});
c.classList.add(''active'');
currentScenario=c.getAttribute(''data-day'');
if(currentScenario===''custom''){customBox.style.display=''block'';}
else{customBox.style.display=''none'';}
});
});
function v(id){var el=app.querySelector(''#''+id);return el?el.value.trim():'''';}
function show(val){return val===''''?''（未填写）'':val;}
var scenarioMap={mon:''周一：今天是李佳怡值班，你意外走进这家便利店，准备买些东西带回家……'',tue:''周二：今天是沈璃值班，你意外走进这家便利店，准备买些东西带回家……'',wed:''周三：今天是王馨悦值班，你意外走进这家便利店，准备买些东西带回家……'',sun:''周日：今天是白小悦值班，你意外走进这家便利店，准备买些东西带回家……''};
function buildScenario(){
if(currentScenario===''custom''){return show(v(''custom-scenario''));}
if(currentScenario&&scenarioMap[currentScenario]){return scenarioMap[currentScenario];}
return ''（未选择开场情景）'';
}
function buildText(){
var lines=[];
lines.push(''【玩家信息】'');
lines.push(''姓名：''+show(v(''p-name'')));
lines.push(''年龄：''+show(v(''p-age'')));
lines.push(''性别：''+show(v(''p-gender'')));
lines.push(''身份：''+show(v(''p-identity'')));
lines.push(''外貌：''+show(v(''p-appearance'')));
lines.push(''经济状况：''+show(v(''p-economy'')));
lines.push(''其他设定：''+show(v(''p-other'')));
lines.push('''');
lines.push(''【开场情景】'');
lines.push(buildScenario());
return lines.join(''\n'');
}
var outputArea=app.querySelector(''#output-area'');
var btnConfirm=app.querySelector(''#btn-confirm'');
var btnCopy=app.querySelector(''#btn-copy'');
var btnClear=app.querySelector(''#btn-clear'');
btnConfirm.addEventListener(''click'',function(){
outputArea.value=buildText();
outputArea.classList.add(''filled'');
});
function feedbackBtn(btn,txt){
if(!btn){return;}
if(!btn.getAttribute(''data-orig'')){btn.setAttribute(''data-orig'',btn.textContent);}
btn.textContent=txt;
btn.classList.add(''done'');
clearTimeout(btn._t);
btn._t=setTimeout(function(){btn.textContent=btn.getAttribute(''data-orig'');btn.classList.remove(''done'');},1500);
}
function manualSelect(){
if(outputArea&&outputArea.select){
