outputArea.select();
try{outputArea.setSelectionRange(0,outputArea.value.length);}catch(e){}
}
feedbackBtn(btnCopy,''请手动复制'');
}
function legacyCopy(text){
var ok=false;
var ta=document.createElement(''textarea'');
ta.value=text;
ta.setAttribute(''readonly'','''');
ta.style.position=''fixed'';
ta.style.top=''0'';
ta.style.left=''0'';
ta.style.width=''2px'';
ta.style.height=''2px'';
ta.style.padding=''0'';
ta.style.border=''none'';
ta.style.outline=''none'';
ta.style.boxShadow=''none'';
ta.style.background=''transparent'';
ta.style.color=''transparent'';
ta.style.opacity=''0.01'';
ta.style.zIndex=''2147483647'';
document.body.appendChild(ta);
try{
ta.focus();
ta.select();
try{ta.setSelectionRange(0,text.length);}catch(e){}
ok=document.execCommand(''copy'');
}catch(e){ok=false;}
document.body.removeChild(ta);
return ok;
}
function doCopy(text){
var handled=false;
function done(){if(handled)return;handled=true;feedbackBtn(btnCopy,''已复制 ✓'');}
function fail(){if(handled)return;handled=true;manualSelect();}
if(navigator.clipboard&&navigator.clipboard.writeText){
navigator.clipboard.writeText(text).then(done).catch(function(){
if(legacyCopy(text)){done();}else{fail();}
});
return;
}
if(legacyCopy(text)){done();}else{fail();}
}
btnCopy.addEventListener(''click'',function(){
var text=outputArea.value||'''';
if(text===''''){
outputArea.value=buildText();
outputArea.classList.add(''filled'');
text=outputArea.value;
}
doCopy(text);
});
btnClear.addEventListener(''click'',function(){
[''p-name'',''p-age'',''p-gender'',''p-identity'',''p-appearance'',''p-economy'',''p-other'',''custom-scenario''].forEach(function(id){
var el=app.querySelector(''#''+id);
if(el){el.value='''';}
});
Array.prototype.forEach.call(scCards,function(x){x.classList.remove(''active'');});
customBox.style.display=''none'';
currentScenario='''';
outputArea.value='''';
outputArea.classList.remove(''filled'');
});
