        out += ''特质设定：'' + cock + ''\n'';
        out += ''其他设定：'' + other + ''\n\n'';
        out += ''【开场白 · '' + chosenTag + ''】\n'';
        out += chosen;

        lastSummaryText = out;
        summaryBox.textContent = out;
        summaryBox.scrollIntoView({behavior: ''smooth'', block: ''start''});
