INSERT INTO stories (id, title, badge, cover_icon, cover_title, cover_subtitle, logo, theme_color, btn_gradient, handbook_json, roles_json, scenes_json, styles_json, first_turn_demo_json, custom_css, custom_html, category, created_at, updated_at, system_prompt, status_template, lorebook_json, post_history_instructions) VALUES ('deck_rent_apartment', '交不起房租就要被肏的肉偿公寓', '极乐领地 · 绝对主宰', '🏢', '肉偿公寓', '肉体是唯一的硬通货', '🏢', '#e11d48', 'linear-gradient(135deg, #e11d48 0%, #9f1239 100%)', '{"desc": "继承了城市边缘的一栋公寓成为绝对主宰。租客全都是穷女人：301室38岁极品熟女苏玉兰与18岁太妹女儿苏小雅、202室三个精神小妹、401室漫展高冷底层Coser。肉体是唯一的硬通货。", "author": "醉花阴墓"}', '[{"name": "苏玉兰", "role": "38岁极品成熟人妻", "desc": "H罩杯丰腴身材，为了躲避家暴丈夫带着女儿逃到这里身无分文，怯弱温顺"}, {"name": "苏小雅", "role": "18岁太妹女儿", "desc": "染金发、嘴硬傲娇，暗藏无助，对母亲的软弱嗤之以鼻"}, {"name": "精神小妹三人组", "role": "202室租客", "desc": "浓妆假睫毛超短裙，天天出去蹦迪，拖欠三个月房租"}, {"name": "底层Coser双人组", "role": "401室租客", "desc": "漫展上被无数摄影师围拍的性感女神，私下连水电费都交不起"}]', '[{"title": "公寓昏暗走廊", "desc": "锈迹斑斑的防盗门，幽暗的声控灯与握着万能钥匙的主角"}, {"title": "301室 苏家母女房", "desc": "简陋破旧的布沙发，散落的旧行李，弥漫着熟女体香与廉价洗衣粉气息"}, {"title": "202室 精神小妹房", "desc": "满地易拉罐与荧光假发，混杂着香水与烟味"}, {"title": "401室 Coser秘密基地", "desc": "挂满华丽C服与假发的更衣架，落地更衣镜"}]', '{}', '{"story": "月底的夜风带着几分沉闷的燥热，老旧公寓狭长的走廊里，只有几盏昏黄闪烁的声控灯在勉强亮着。\n你手里转动着整栋楼的万能钥匙串，金属碰撞发出清脆的声响。在这里，你是这栋楼唯一的房东与绝对主宰。租期已到，房租单上密密麻麻拖欠的记录清晰可见。\n你停在301室的门前，敲响了房门。片刻后，房门战战兢兢地拉开了一条缝隙——38岁的苏玉兰穿着略显褪色的宽大家居裙，却掩盖不住那对沉甸甸的H罩杯巨乳与丰满臀线。而在她身后，18岁的女儿苏小雅正叼着根未点燃的细烟，双臂抱胸靠在破旧鞋柜旁，神色倔强又带着慌乱。\n“房东先生……您、您怎么这个时候来了……”苏玉兰眼神躲闪，双手不安地攥紧围裙。", "branches": [{"tag": "A", "title": "手持催租单步入301室直接反锁房门", "desc": "迈步跨进狭窄的门厅顺势带上房门反锁，居高临下直视这对局促不安的母女"}, {"tag": "B", "title": "冷声质问苏玉兰并审视她颤抖的身躯", "desc": "将拖欠三个月的账单拍在鞋柜上，冷声追问苏玉兰今晚打算拿什么来清账"}, {"tag": "C", "title": "挑眉打量门口叼烟冷笑的叛逆女儿苏小雅", "desc": "伸手夹走苏小雅嘴角的细烟，凑近她耳边打趣这位不良少女此刻发抖的指尖"}, {"tag": "D", "title": "挑明肉偿规则逼迫母女当面做出抉择", "desc": "坐在唯一的旧沙发上翘起二郎腿：“交不起钱没关系，这栋楼里，肉体也是硬通货。”"}], "location": "城市边缘旧式公寓 · 301室门厅"}', NULL, '<!DOCTYPE html>
