openingItems.forEach(function(item){
item.addEventListener(''click'',function(){
openingItems.forEach(function(i){i.classList.remove(''selected'');});
item.classList.add(''selected'');
selectedOpening = item.getAttribute(''data-text'') || '''';
var co = root.querySelector(''#customOpening'');
if(co) co.value = '''';
});
});
var btnGen = root.querySelector(''#btnGenerate'');
btnGen.addEventListener(''click'',function(){
