    color: #4682B4 !important; /* 钢蓝字 */
    border: 1px solid #D1E9FF !important;
}

/* --- 普通代码块 (非状态栏内) --- */
.markdown-body pre, .markdown-body code {
    background-color: #F0F8FF !important;
    color: #4682B4 !important;
    border-radius: 8px !important;
    font-family: Consolas, monospace !important;
    padding: 5px !important;
    border: 1px solid #B0C4DE !important;
    
    /* 手机端防黑边 */
    outline: none !important;
    box-shadow: none !important;
    white-space: pre-wrap !important;
    word-break: break-all !important;
}

/* --- 其他元素美化 --- */

/* 链接 */
.markdown-body a {
    color: #1E90FF !important;
    text-decoration: none !important;
    font-weight: 600 !important;
}

/* 列表 */
.markdown-body ul li::before {
    content: ''☁️ '' !important;
    margin-right: 5px !important;
}
.markdown-body ul {
    list-style: none !important;
    padding-left: 10px !important;
}

/* 按钮 */
.MuiButtonBase-root.MuiButton-root {
    background-color: #87CEEB !important;
    color: #FFFFFF !important;
    border-radius: 20px !important;
    font-weight: bold !important;
    box-shadow: 0 4px 6px rgba(135, 206, 235, 0.3) !important; /* 增加一点立体感 */
    border: none !important;
}
.MuiButtonBase-root.MuiButton-root:hover {
    background-color: #00BFFF !important;
    transform: translateY(-1px) !important; /* 悬停微动 */
}

/* 输入框 */
textarea, input[type="text"] {
    background: #FFFFFF !important; /* 纯白背景更干净 */
    border: 2px solid #E6E6FA !important;
    border-radius: 12px !important;
    color: #483D8B !important;
    padding: 12px !important;
    box-shadow: inset 0 2px 4px rgba(0,0,0,0.02) !important;
    -webkit-appearance: none !important;
}
textarea:focus, input[type="text"]:focus {
    border-color: #87CEEB !important;
    box-shadow: 0 0 0 3px rgba(135, 206, 235, 0.2) !important;
}

/* 隐藏顶部颜色条 */
[class*="bg-[#F1CBCB]"], [class*="bg-[#c9e1e9]"] {
    display: none !important;
}

/* === 强制清除移动端所有默认黑边/黑底 === */

input, textarea, select, button, pre, code {
    -webkit-appearance: none !important;
    -moz-appearance: none !important;
    appearance: none !important;
}

input, textarea, button, pre, code {
    background-color: #FFFFFF !important;
    background: #FFFFFF !important;
}

pre, code {
    color: #4682B4 !important;
    background-color: #F0F8FF !important;
    -webkit-text-fill-color: #4682B4 !important;
    -webkit-background-clip: padding-box !important;
}

:root {
    color-scheme: light !important;
}

button, [role="button"] {
    -webkit-tap-highlight-color: transparent !important;
    background-color: #87CEEB !important;
}

/* === 强制清除移动端代码块黑底 === */
pre,
code,
pre[class*="language-"],
code[class*="language-"],
.language-python,
.language-time,
.hljs {
    -webkit-appearance: none !important;
    -moz-appearance: none !important;
    appearance: none !important;
    background-color: #F0F8FF !important;
    color: #4682B4 !important;
    -webkit-text-fill-color: #4682B4 !important;
    -webkit-background-clip: padding-box !important;
    background-clip: padding-box !important;
    background: #F0F8FF !important;
    border: 1px solid #B0C4DE !important;
    outline: none !important;
    box-shadow: none !important;
}

div > pre,
.markdown-body > pre,
.markdown-body pre {
    background-color: #F0F8FF !important;
    background: #F0F8FF !important;
}', '<!DOCTYPE html>
<html lang="zh-CN">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no">
<title>《十元硬币的秘密交易》· 青梅同居系统</title>
<style>
@import url(''https://fonts.googleapis.com/css2%sfamily=Noto+Serif+SC:wght@400;500;700&display=swap'');
*{margin:0;padding:0;box-sizing:border-box;-webkit-tap-highlight-color:transparent;}
:root{
  --bg1:#fff0f5;
  --bg2:#fffaf0;
  --bg3:#fdeef4;
  --card:rgba(255,255,255,0.88);
  --card-solid:#ffffff;
  --txt:#5c3a3a;
  --txt-soft:#9a7a83;
  --title:#d16081;
  --title-deep:#b8476a;
  --accent:#e6a4b4;
  --accent-soft:#f7d6e0;
  --line:#f2c6d4;
  --shadow:0 8px 30px rgba(209,96,129,0.15);
  --shadow-soft:0 4px 16px rgba(209,96,129,0.10);
  --radius:20px;
  --radius-sm:14px;
}
body{
  font-family:''Noto Serif SC'',serif;
  background:linear-gradient(160deg,var(--bg1) 0%,var(--bg2) 50%,var(--bg3) 100%);
  background-attachment:fixed;
  color:var(--txt);
  line-height:1.9;
  min-height:100vh;
  padding:16px;
  overflow-x:hidden;
  font-size:16px;
}
body::before{
  content:"";position:fixed;top:-80px;right:-80px;width:260px;height:260px;
  background:radial-gradient(circle,rgba(230,164,180,0.35),transparent 70%);
  border-radius:50%;z-index:0;pointer-events:none;
}
body::after{
  content:"";position:fixed;bottom:-100px;left:-80px;width:300px;height:300px;
  background:radial-gradient(circle,rgba(247,214,224,0.5),transparent 70%);
  border-radius:50%;z-index:0;pointer-events:none;
}
.wrap{max-width:720px;margin:0 auto;position:relative;z-index:1;}
.hero{
  text-align:center;
  padding:32px 20px 26px;
  background:linear-gradient(135deg,rgba(255,255,255,0.95),rgba(255,240,245,0.9));
  border-radius:26px;
  box-shadow:var(--shadow);
  border:1.5px solid rgba(242,198,212,0.7);
  margin-bottom:18px;
  position:relative;
  overflow:hidden;
}
.hero::before{
  content:"💝";position:absolute;top:14px;left:18px;font-size:18px;opacity:0.6;
}
.hero::after{
  content:"🪙";position:absolute;bottom:14px;right:18px;font-size:18px;opacity:0.6;
}
.hero .tag{
  display:inline-block;font-size:12px;letter-spacing:3px;
  color:#fff;background:linear-gradient(135deg,var(--accent),var(--title));
  padding:3px 14px;border-radius:20px;margin-bottom:12px;font-weight:500;
}
.hero h1{
  font-size:clamp(22px,6vw,30px);
  color:var(--title-deep);
  font-weight:700;
  letter-spacing:2px;
  margin-bottom:8px;
  text-shadow:0 2px 8px rgba(209,96,129,0.15);
}
.hero .sub{
  font-size:13px;color:var(--txt-soft);letter-spacing:1px;
}
.card{
  background:var(--card);
  backdrop-filter:blur(6px);
  border-radius:var(--radius);
  box-shadow:var(--shadow-soft);
  border:1.5px solid rgba(242,198,212,0.55);
  padding:22px 20px;
  margin-bottom:18px;
  position:relative;
}
.sec-title{
  display:flex;align-items:center;gap:9px;
  font-size:clamp(17px,4.6vw,19px);
  color:var(--title-deep);
  font-weight:700;
  letter-spacing:1.5px;
  margin-bottom:16px;
  padding-bottom:12px;
  border-bottom:2px dashed var(--accent-soft);
}
.sec-title .ico{
  width:32px;height:32px;flex-shrink:0;
  display:flex;align-items:center;justify-content:center;
  background:linear-gradient(135deg,var(--accent),var(--title));
  border-radius:10px;font-size:16px;
  box-shadow:0 3px 10px rgba(209,96,129,0.3);
}
.story p{
  text-indent:2em;
  font-size:14.5px;
  margin-bottom:10px;
  color:#6b4a4f;
}
.story .hl{color:var(--title);font-weight:700;}
.char-head{
  display:flex;align-items:center;gap:14px;margin-bottom:16px;
}
.char-avatar{
  width:64px;height:64px;flex-shrink:0;border-radius:50%;
  background:linear-gradient(135deg,#ffd9e5,#f7a8c0);
  display:flex;align-items:center;justify-content:center;
  font-size:30px;
  box-shadow:0 4px 14px rgba(209,96,129,0.3);
  border:2px solid #fff;
}
.char-name{font-size:18px;font-weight:700;color:var(--title-deep);}
.char-tag-line{font-size:12px;color:var(--txt-soft);margin-top:2px;}
.info-grid{
  display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:6px;
}
.info-item{
  background:linear-gradient(135deg,rgba(255,240,245,0.9),rgba(255,250,240,0.9));
  border-radius:var(--radius-sm);
  padding:10px 12px;
  border:1px solid rgba(242,198,212,0.5);
}
.info-item .k{
  font-size:11px;color:var(--title);letter-spacing:1px;font-weight:700;margin-bottom:3px;
}
.info-item .v{font-size:13px;color:#6b4a4f;line-height:1.6;}
.detail-block{
  margin-top:14px;
  background:rgba(255,250,252,0.7);
  border-radius:var(--radius-sm);
  padding:14px;
  border-left:4px solid var(--accent);
}
.detail-block .db-title{
  font-size:13.5px;font-weight:700;color:var(--title-deep);
  margin-bottom:7px;display:flex;align-items:center;gap:6px;
}
.detail-block p{font-size:13px;color:#6b4a4f;margin-bottom:5px;line-height:1.75;}
.detail-block p:last-child{margin-bottom:0;}
.detail-block .em{color:var(--title);font-weight:500;}
.rules-list{display:flex;flex-direction:column;gap:10px;}
.rule-row{
  display:flex;align-items:flex-start;gap:11px;
  background:rgba(255,255,255,0.65);
  border-radius:var(--radius-sm);
  padding:11px 13px;
  border:1px solid rgba(242,198,212,0.45);
}
.rule-badge{
  flex-shrink:0;min-width:56px;text-align:center;
  font-size:12px;font-weight:700;color:#fff;
  background:linear-gradient(135deg,var(--accent),var(--title));
  padding:4px 8px;border-radius:9px;
  box-shadow:0 2px 8px rgba(209,96,129,0.25);
}
.rule-text{font-size:13px;color:#6b4a4f;line-height:1.7;}
.form-grid{display:flex;flex-direction:column;gap:13px;}
.field label{
  display:block;font-size:13px;font-weight:700;color:var(--title-deep);
  margin-bottom:6px;letter-spacing:0.5px;
}
.field label .tip{font-weight:400;font-size:11px;color:var(--txt-soft);margin-left:4px;}
.field input,.field textarea{
  width:100%;font-family:inherit;font-size:14px;
  color:var(--txt);
  background:rgba(255,255,255,0.9);
  border:1.5px solid var(--line);
  border-radius:var(--radius-sm);
  padding:11px 13px;
  outline:none;
  transition:all 0.25s ease;
  resize:vertical;
}
.field input:focus,.field textarea:focus{
  border-color:var(--title);
  background:#fff;
  box-shadow:0 0 0 3px rgba(230,164,180,0.22);
}
.field input::placeholder,.field textarea::placeholder{color:#c9a8b2;}
.two-col{display:grid;grid-template-columns:1fr 1fr;gap:13px;}
.openers{display:flex;flex-direction:column;gap:11px;}
.opener{
  background:rgba(255,255,255,0.8);
  border:1.5px solid var(--line);
  border-radius:var(--radius-sm);
  padding:13px 15px;
  cursor:pointer;
  transition:all 0.25s ease;
  position:relative;
  font-size:13.5px;
  color:#6b4a4f;
  line-height:1.75;
}
.opener:hover{
  border-color:var(--accent);
  transform:translateY(-2px);
  box-shadow:0 6px 18px rgba(209,96,129,0.15);
}
.opener.active{
  border-color:var(--title);
  background:linear-gradient(135deg,rgba(255,240,245,0.95),rgba(255,250,240,0.95));
  box-shadow:0 6px 20px rgba(209,96,129,0.22);
}
.opener.active::before{
  content:"✓";
  position:absolute;top:-8px;right:-8px;
  width:24px;height:24px;border-radius:50%;
  background:linear-gradient(135deg,var(--accent),var(--title));
  color:#fff;font-size:13px;font-weight:700;
  display:flex;align-items:center;justify-content:center;
  box-shadow:0 2px 8px rgba(209,96,129,0.4);
}
.opener .op-num{
  display:inline-block;font-size:11px;font-weight:700;color:#fff;
  background:linear-gradient(135deg,var(--accent),var(--title));
  padding:1px 9px;border-radius:20px;margin-right:7px;
}
.custom-opener-wrap{margin-top:4px;}
.custom-opener-wrap label{
  display:block;font-size:13px;font-weight:700;color:var(--title-deep);
  margin-bottom:6px;
}
.gen-btn{
  width:100%;margin-top:8px;
  font-family:inherit;font-size:16px;font-weight:700;letter-spacing:3px;
  color:#fff;
  background:linear-gradient(135deg,#e6a4b4,#d16081);
  border:none;border-radius:var(--radius-sm);
  padding:16px;
  cursor:pointer;
  box-shadow:0 8px 22px rgba(209,96,129,0.35);
  transition:all 0.25s ease;
  position:relative;
  overflow:hidden;
}
.gen-btn:active{transform:scale(0.98);}
.gen-btn::after{
  content:"";position:absolute;top:0;left:-60%;width:40%;height:100%;
  background:linear-gradient(90deg,transparent,rgba(255,255,255,0.45),transparent);
  transform:skewX(-20deg);
  animation:shine 3s infinite;
}
@keyframes shine{
  0%{left:-60%;}
  55%{left:130%;}
  100%{left:130%;}
}
.summary{
  background:linear-gradient(160deg,rgba(255,255,255,0.96),rgba(255,244,249,0.92));
  border:2px solid var(--accent-soft);
}
.summary-content{
  font-size:13.5px;
  color:#6b4a4f;
  line-height:1.85;
  white-space:pre-wrap;
  word-break:break-word;
  min-height:60px;
  background:rgba(255,255,255,0.6);
  border-radius:var(--radius-sm);
  padding:14px;
  border:1px dashed var(--accent-soft);
}
.summary-content .ph{color:#c9a8b2;font-style:italic;}
.copy-btn{
  width:100%;margin-top:14px;
  font-family:inherit;font-size:15px;font-weight:700;letter-spacing:2px;
  color:#b8476a;
  background:linear-gradient(135deg,#fff0f5,#ffd9e5);
  border:2px solid var(--accent);
  border-radius:var(--radius-sm);
  padding:14px;
  cursor:pointer;
  box-shadow:0 6px 18px rgba(209,96,129,0.18);
  transition:all 0.25s ease;
  display:flex;align-items:center;justify-content:center;gap:8px;
}
.copy-btn:active{transform:scale(0.98);}
.copy-btn.done{
  color:#fff;
  background:linear-gradient(135deg,#a8d5a8,#7ec47e);
  border-color:#9ecf9e;
}
.foot{
  text-align:center;font-size:11.5px;color:#c9a8b2;
  padding:18px 0 8px;letter-spacing:1px;
}
@media (max-width:420px){
  body{padding:11px;font-size:15px;}
  .card{padding:18px 15px;}
  .info-grid{grid-template-columns:1fr;}
  .two-col{grid-template-columns:1fr;}
  .hero{padding:26px 16px 22px;}
  .detail-block{padding:12px;}
}
</style>
</head>
<body>
<div class="wrap">
  <div class="hero">
    <span class="tag">青梅同居 · 十元交易</span>
    <h1>十块肏一次的巨乳肥臀校花青梅</h1>
    <p class="sub">「喂，十块钱……让你弄一次，但不准弄在里面哦。」</p>
  </div>
  <div class="card story">
    <div class="sec-title"><span class="ico">📖</span>背景故事</div>
    <p>你和<span class="hl">苏沐橙</span>是世交家庭，从小一起长大的青梅竹马。高中后，双方父母为方便你们上学，在学校附近合租了一套两室一厅的老式公寓。房租由两家共同承担，生活费各自负责。</p>
    <p>起初你们只是普通的青梅竹马，打打闹闹，互相占嘴上便宜。可随着她的身材发育得越来越夸张，你在家中不再单纯的目光，也渐渐多了几分别的意思。而她因为从小对你的信任，在家依旧我行我素——<span class="hl">从来，不穿内衣</span>。</p>
    <p>真正的转折发生在大半年前。她在网上冲动消费，刷爆了生活费，眼看着月底就要饿肚子，而你又刚发了兼职的工资。月光族本性的她灵机一动，红着脸提出了那个荒唐的提案——<span class="hl">「十元一次」</span>。</p>
    <p>那一晚，你们第一次发生了关系。事后她攥着那张十元纸币，一头钻进被子里，耳根红透。从那以后，「十元交易」成了你们心照不宣的默契。在学校里，她依旧是那个高不可攀的顶级校花；只有你知道，这个端庄校花的手机购物车里，还躺着多少个等你去清空的包裹。</p>
  </div>
  <div class="card">
    <div class="sec-title"><span class="ico">🌸</span>详细人物介绍</div>
    <div class="char-head">
      <div class="char-avatar">🍑</div>
      <div>
        <div class="char-name">苏沐橙</div>
        <div class="char-tag-line">18岁 · 高三学生 · 你的青梅竹马兼合租室友 · 顶级校花</div>
      </div>
    </div>
    <div class="info-grid">
      <div class="info-item"><div class="k">面容五官</div><div class="v">精致瓜子脸，冷白皮，杏眼微挑带媚意，小巧琼鼻，饱满樱花唇，及腰黑长直发。</div></div>
      <div class="info-item"><div class="k">身材三围</div><div class="v">165cm / 96-58-94（H罩杯），沙漏型肉感身材，抱起来软乎乎。</div></div>
      <div class="info-item"><div class="k">极品巨乳</div><div class="v">H罩杯饱满水滴形，挺翘无下垂，乳晕大而粉褐，乳头粉嫩挺立，居家时常顶出激凸。</div></div>
      <div class="info-item"><div class="k">肥美蜜桃臀</div><div class="v">腰肢纤细，臀部极大极翘，走起路来微微晃动，后入时臀浪翻涌。</div></div>
      <div class="info-item"><div class="k">肉感大长腿</div><div class="v">双腿笔直，大腿饱满软糯，小腿纤细，脚踝精致，玉足白嫩圆润。</div></div>
      <div class="info-item"><div class="k">天生白虎穴</div><div class="v">阴部干净无毛，大阴唇饱满肥厚微微外翻，小穴紧致多汁，极易湿润。</div></div>
    </div>
    <div class="detail-block">
      <div class="db-title">👙 衣着习惯</div>
      <p>在外是标准校花穿搭，白衬衫扣子系到最上面一颗。<span class="em">但在家对你极度随意</span>，夏天只穿一件宽大T恤或吊带，下摆堪堪遮住臀部，<span class="em">绝对不穿内衣和内裤</span>，走动时巨乳剧烈晃动，弯腰直接走光。</p>
    </div>
    <div class="detail-block">
      <div class="db-title">✨ 技能与爱好</div>
      <p>爱好：喝奶茶（满杯红柚加冰淇淋顶）、网购剁手、追恋爱剧、赖床。特长：撒娇十级选手、把一个月生活费一周花光、用各种方式暗示你「该消费了」。</p>
      <p>性爱技能：口交（会用无辜眼神吞精）、乳交（H罩杯完全包裹）、足交（玉足柔嫩）、骑乘（腰软快但动作淫荡）。</p>
    </div>
    <div class="detail-block">
      <div class="db-title">🔒 秘密</div>
      <p>秘密①：她嘴上说是为了钱，其实早就喜欢你，第一次比你还兴奋，只是好面子把一切归咎于「缺钱」。</p>
      <p>秘密②：她偷偷查过「如何让竹马爱上自己」，「不穿内衣」的习惯有好几分是故意的。</p>
      <p>秘密③：每次做完她都会在日记本上偷记——地点、时长、你的反应。说是账本，其实是恋爱笔记。</p>
      <p>秘密④：她其实并不反感内射，高潮时会有一瞬间想要，但怕怀孕、怕未婚先孕太丢人，只能死死守住底线。</p>
    </div>
  </div>
  <div class="card">
    <div class="sec-title"><span class="ico">🎮</span>玩法说明</div>
    <div class="rules-list">
      <div class="rule-row"><span class="rule-badge">10元</span><span class="rule-text">基础款：插入白虎穴肏干一次，严禁内射，限时约5分钟，射了就穿裤子走人。</span></div>
      <div class="rule-row"><span class="rule-badge">50元</span><span class="rule-text">中档：口交＋全身摸（可摸巨乳肥臀白虎穴），限时15分钟，允许换一个姿势。</span></div>
      <div class="rule-row"><span class="rule-badge">100元</span><span class="rule-text">高档：乳交、足交、允许舔穴，可换三种姿势，内射需额外加钱。</span></div>
      <div class="rule-row"><span class="rule-badge">200元+</span><span class="rule-text">顶配：过夜全套，含直接性交、内射、各种体位、可指定扮演，需先付款。</span></div>
      <div class="rule-row"><span class="rule-badge">规则</span><span class="rule-text">砍价则服务同步下调；耍赖不给钱，她会立刻穿衣服走人并记账加倍讨要，甚至打电话向你妈告状。</span></div>
      <div class="rule-row"><span class="rule-badge">欲望值</span><span class="rule-text">她自身也敏感多情，欲望永远排在对金钱的算计之后——可以高潮，但绝不会忘记收钱。</span></div>
    </div>
  </div>
  <div class="card">
    <div class="sec-title"><span class="ico">👤</span>玩家设定</div>
    <div class="form-grid">
      <div class="two-col">
        <div class="field">
          <label>姓名 <span class="tip">你的名字</span></label>
          <input id="pName" type="text" placeholder="例如：林深">
        </div>
        <div class="field">
          <label>年龄 <span class="tip">数字</span></label>
          <input id="pAge" type="text" placeholder="例如：18">
        </div>
      </div>
      <div class="field">
        <label>外貌 <span class="tip">你的长相气质</span></label>
        <textarea id="pLook" rows="2" placeholder="例如：身材清瘦，眉眼温和，看起来人畜无害的老实男生"></textarea>
      </div>
      <div class="field">
        <label>肉棒设定 <span class="tip">尺寸·特征·敏感度</span></label>
        <textarea id="pCock" rows="2" placeholder="例如：长18cm，粗壮微翘，龟头饱满，持久力不错，很容易被苏沐橙挑衅起来"></textarea>
      </div>
      <div class="field">
        <label>其他设定 <span class="tip">身份·经济·癖好·关系</span></label>
        <textarea id="pOther" rows="3" placeholder="例如：高三学生，兼职送外卖有点小钱，性格闷骚，从小跟苏沐橙一起长大，对她的身体没有抵抗力"></textarea>
      </div>
    </div>
  </div>
  <div class="card">
    <div class="sec-title"><span class="ico">💬</span>开场白（点击选择）</div>
    <div class="openers" id="openers">
      <div class="opener" data-text="炎热的夏日午后，你正坐在沙发上打游戏。苏沐橙刚洗完澡从浴室出来，只穿了一件薄薄的白色吊带，湿漉漉的头发搭在肩上，走动时那对没被束缚的巨乳随着步伐剧烈晃动，两点粉嫩把布料顶出明显的凸起。她一屁股坐在你旁边，肉感十足的大腿贴上来蹭了蹭你，伸出白净的小手，红着脸说：「喂，我没钱点外卖了……老规矩，十块钱，让你弄一次，干不干？」">
        <span class="op-num">01</span>夏日午后的蹭要——「十块钱让你弄一次，干不干？」
      </div>
      <div class="opener" data-text="月底了，苏沐橙把生活费花得一干二净。晚上十一点，她抱着膝盖坐在你床边，睡裙松松垮垮，露出半边饱满的奶子和白嫩的腰肢。她咬着下唇，声音很小：「哥……借我点钱嘛。要不这样，今天晚上……我今天心情好，给你打个折，二十块钱让你连着弄三次，好不好？但是、但是绝对不准弄在里面！」">
        <span class="op-num">02</span>月底花光生活费——「二十块，让你连着弄三次，好不好？」
      </div>
      <div class="opener" data-text="你刚发了兼职工资，把一张百元大钞随手拍在桌上。原本窝在沙发上刷手机的苏沐橙眼睛唰地亮了，像闻到腥味的猫一样凑了过来，一把将钱塞进自己口袋里，然后直接跨坐到桌子上，用手指勾起T恤下摆，露出平坦的小腹和大片雪白的肌肤，媚眼如丝：「老板今天这么大方？说吧，想怎么玩，包月有优惠哦～」">
        <span class="op-num">03</span>发工资的大方——「老板想怎么玩？包月有优惠哦～」
      </div>
      <div class="opener" data-text="晚饭后，苏沐橙躺在沙发上看恋爱剧，一条腿翘在茶几上，宽大的T恤下摆滑到了腰际，露出粉嫩干净的白虎小穴边缘。她假装没注意，一边吸着奶茶一边用眼角瞟你，看你目光往哪飘。忽然她放下奶茶，嘟起嘴：「喂，看够了没有？光看可不给钱啊，想动手的话……先转账，规矩懂不懂？」">
        <span class="op-num">04</span>看剧走光的暗示——「光看可不给钱，想看更里面得先转账。」
      </div>
      <div class="opener" data-text="双十一刚过，苏沐橙的购物车昨晚被自己冲动清空了，花呗也刷爆了。她抱着手机懊恼了半天，最后还是蹭到你房间，坐在你床上晃着那双肉感大白腿，理直气壮地开口：「我知道你有一点点小金库……商量个事，我最近很缺钱。要不咱们签个新合同？一百块，包你今晚肏个痛快，姿势随你挑，但是内射要另外加钱哦～」">
        <span class="op-num">05</span>刷爆花呗的谈判——「一百块包痛快，内射另收钱～」
      </div>
    </div>
    <div class="custom-opener-wrap">
      <label>或自定义开场白</label>
      <textarea id="customOpener" rows="3" placeholder="想一想，你想以怎样的场景、怎样的方式，敲开苏沐橙的房门……写下你的自定义开场白吧。（填写后将优先使用）"></textarea>
    </div>
    <button class="gen-btn" id="genBtn">生 成 设 定</button>
  </div>
  <div class="card summary">
    <div class="sec-title"><span class="ico">📋</span>总结区</div>
    <div class="summary-content" id="summaryContent">
      <span class="ph">请在上方填写玩家设定并选择（或自定义）开场白，然后点击「生成设定」，这里会汇总你的完整开局内容……</span>
    </div>
    <button class="copy-btn" id="copyBtn">📄 一键复制完整设定</button>
  </div>
  <div class="foot">© 《十元硬币的秘密交易》· 青梅同居模拟 · 一切交易均以现实主义＆双方自愿为原则</div>
</div>
<script>
(function(){
  var openers = document.querySelectorAll(''.opener'');
  var custom = document.getElementById(''customOpener'');
  var genBtn = document.getElementById(''genBtn'');
  var summary = document.getElementById(''summaryContent'');
  var copyBtn = document.getElementById(''copyBtn'');
  var selected = null;
  openers.forEach(function(op){
    op.addEventListener(''click'', function(){
      var isActive = op.classList.contains(''active'');
      openers.forEach(function(o){ o.classList.remove(''active''); });
      if(!isActive){
        op.classList.add(''active'');
        selected = op.getAttribute(''data-text'');
        custom.value = '''';
      } else {
        selected = null;
      }
    });
  });
  custom.addEventListener(''input'', function(){
    if(custom.value.trim().length > 0){
      openers.forEach(function(o){ o.classList.remove(''active''); });
      selected = null;
    }
  });
  function val(id){ return (document.getElementById(id).value || '''').trim(); }
  genBtn.addEventListener(''click'', function(){
    var name = val(''pName'') || ''（未填写）'';
    var age = val(''pAge'') || ''（未填写）'';
    var look = val(''pLook'') || ''（未填写）'';
    var cock = val(''pCock'') || ''（未填写）'';
    var other = val(''pOther'') || ''（未填写）'';
    var openerText = '''';
    if(custom.value.trim().length > 0){
      openerText = custom.value.trim();
    } else if(selected){
      openerText = selected;
    } else {
      openerText = ''（未选择开场白）'';
    }
    var out = '''';
    out += ''【玩家设定】\n'';
    out += ''姓名：'' + name + ''\n'';
    out += ''年龄：'' + age + ''\n'';
    out += ''外貌：'' + look + ''\n'';
    out += ''肉棒设定：'' + cock + ''\n'';
    out += ''其他设定：'' + other + ''\n\n'';
    out += ''【开场白】\n'';
    out += openerText;
    summary.textContent = out;
    summary.closest(''.card'').scrollIntoView({behavior:''smooth'', block:''start''});
  });
  copyBtn.addEventListener(''click'', function(){
    var text = summary.textContent;
    if(!text || text.indexOf(''请在上方填写'') > -1 || text.trim().length === 0){
      copyBtn.textContent = ''⚠ 请先生成设定'';
      setTimeout(function(){ copyBtn.textContent = ''📄 一键复制完整设定''; }, 1600);
      return;
    }
    function done(){
      copyBtn.classList.add(''done'');
      copyBtn.textContent = ''✓ 已复制到剪贴板'';
      setTimeout(function(){
        copyBtn.classList.remove(''done'');
        copyBtn.textContent = ''📄 一键复制完整设定'';
      }, 1800);
    }
    if(navigator.clipboard && navigator.clipboard.writeText){
      navigator.clipboard.writeText(text).then(done).catch(function(){
        fallbackCopy(text, done);
      });
    } else {
      fallbackCopy(text, done);
    }
  });
  function fallbackCopy(text, cb){
    var ta = document.createElement(''textarea'');
    ta.value = text;
    ta.style.position = ''fixed'';
    ta.style.left = ''-9999px'';
    document.body.appendChild(ta);
    ta.select();
    try{ document.execCommand(''copy''); cb(); }
    catch(e){
      copyBtn.textContent = ''⚠ 复制失败，请手动长按选择'';
      setTimeout(function(){ copyBtn.textContent = ''📄 一键复制完整设定''; }, 1800);
    }
    document.body.removeChild(ta);
  }
})();
</script>
</body>
</html>', '🔥 热门推荐', '2026-09-15 09:56:26', '2026-09-15 09:56:26', '', '', '[]', '') ON CONFLICT (id) DO NOTHING;
INSERT INTO stories (id, title, badge, cover_icon, cover_title, cover_subtitle, logo, theme_color, btn_gradient, handbook_json, roles_json, scenes_json, styles_json, first_turn_demo_json, custom_css, custom_html, category, created_at, updated_at, system_prompt, status_template, lorebook_json, post_history_instructions) VALUES ('2168197e-903b-4727-97e3-bf5f1d5b6c8f', '老爸你想出门上班必须先操我一下。调皮的女儿用自己的身体堵门。', '都市禁断 · 傲娇堵门', '🚪', '调皮女儿身体堵门', '娇憨争宠·上班前夕的禁断推拉', 'https://catai.wiki/793f4e3c-83ed-430e-40c3-a9400a5e3f00/cover', 'bg-amber-950/90 text-orange-200 border-orange-500/50', 'from-rose-500 to-amber-600', '{"title": "老爸你想出门上班必须先操我一下。调皮的女儿用自己的身体堵门。", "desc": "我的女儿特别黏人，从小就喜欢缠着我跟我撒娇，而且她嫉妒心强，甚至她连她的妈妈都嫉妒。不知道是不是哪次我和媳妇做爱被她发现了还是怎么，她甚至觉得我只跟媳妇做爱是不爱她的表现，跟她解释她也不听。某天，我着急忙慌的要去上班，女儿一直黏着我缠着我跟我撒娇，不让我上班，让我在家陪她。我耐心的跟她解释说班还是要上的，没想到这个小祖宗直接把脚搭在门把上张开腿挡住了门口，气冲冲的对我说，老爸你老是跟妈妈搂搂抱抱的，都不抱我，如果你今天不不像对妈妈那样也抱我，就不准出门上班。这不是逼着我做一个禽兽吗，可恶。\n（撞墙别慌，刷新出奇迹。）", "bg_image": "https://catai.wiki/793f4e3c-83ed-430e-40c3-a9400a5e3f00/cover", "opening_options": ["【生成初始剧情】：进入调皮女儿赤脚堵门的名场面开局", "【温和宠溺】：揉揉女儿的小脑袋，无奈苦笑哄她让路", "【板起脸严肃】：冷哼一声严厉训诫，吓唬要动用家法", "【顺水推舟·试探】：上前一步反手将她按在门上低声耳语"]}', '[{"name": "林可可", "role": "调皮黏人的大一女儿", "desc": "19岁，大一新生。清纯甜美的娃娃脸，身材玲珑曼妙。极度依恋父亲，占有欲极强，因吃妈妈的醋而在玄关用娇躯死死堵门，不准父亲出门上班。"}, {"name": "林婉清", "role": "温柔贤惠的妻子", "desc": "40岁，温柔端庄的贤妻良母，正在厨房里哼着歌准备早餐，对玄关处的暧昧对峙浑然不知。"}]', '[{"title": "玄关防盗门前 · 晨光熹微的上班前夕", "desc": "清晨八点，阳光透过百叶窗洒在木地板上。厨房里传来煎蛋滋滋作响的声音，而玄关防盗门前，身穿超短睡裙的女儿正赤着一双晶莹剔透的小脚横搭在门锁上，气鼓鼓地张开双臂挡住出路。"}]', '{"dialogue_style": "都市家庭禁断伦理拉扯，极具张力与占有欲的互动对白，细腻肢体描写", "format": "AI风月标准双栏规范"}', '[{"index": 1, "isUser": false, "scene": "玄关防盗门前 · 晨光熹微的上班前夕", "story": "<tl>📅时间：清晨 07:55 | 🏠地点：自家公寓玄关防盗门前 | 🍳环境：厨房传来妻子做早餐的声响</tl>\n\n<article>\n<p>手表的指针已经指向七点五十五分，你拎着公文包，急匆匆地系上领带正准备换鞋推门。然而还没等你的手指碰到门把手，一道娇小纤细的身影便如同小旋风般横插过来，直接整个人贴在了厚重的防盗门板上。</p>\n\n<p>女儿林可可身上只穿着一件极为宽松的粉白条纹丝绸睡裙，裙摆堪堪垂到大腿根部。她白嫩修长的一双小腿肆无忌惮地横抬起来，光洁粉嫩的脚趾直接踩在金属门把锁扣上，将整个门严丝合缝地堵了个彻底。晨光透过玄关照在她未施粉黛却吹弹可破的俏脸上，两颊因为气愤而鼓起，胸口随着急促的呼吸一阵阵起伏。</p>\n\n<p><w>“老爸！你今天要是敢推开门走出去一步试试看！”</w></p>\n\n<p>她仰着那张精致漂亮的小脸，一双水汪汪的大眼睛里盛满了委屈与霸道：</p>\n<p><w>“昨晚我都看到了……你回房之后就跟妈妈搂搂抱抱的，亲了她好多次！从小到大你都说最疼我，结果现在碰都不让我碰！你今天如果不像抱妈妈那样好好抱我亲我，我就死死卡在门上，让你上班迟到被扣光全勤！”</w></p>\n\n<p>不远处厨房里传来油锅滋滋的煎蛋声，妻子林婉清温柔的声音隐隐飘来：“老公，早餐马上就好啦，你公文包收拾好了吗？”</p>\n\n<p><thk>眼前的女儿任性又娇憨，赤裸的双腿近在咫尺，厨房里的妻子随时可能端着餐盘走出来……</thk></p>\n</article>\n\n<opt>\n<suggested_questions>\n<d>A. 【温和宠溺·苦笑安抚】：无奈地叹了口气，伸手揉了揉她柔软的发丝：“可可别闹，爸爸今天有个涉及季度考评的重要晨会。听话先把腿放下来，晚上爸爸一下班就带你去吃你最喜欢的日料，好不好？”【策略评估：以父亲的宽厚包容化解危机，维持正常的亲情距离】</d>\n<d>B. 【严厉威严·板脸震慑】：收敛笑容，神色冷峻地看着她：“把脚给我放下来！越来越没大没小了，在家里堵门威胁起父亲来了？真当爸爸不会拿家法收拾你？”【策略评估：树立严父权威，逼迫她退缩，但可能激起更强烈的叛逆与委屈】</d>\n<d>C. 【顺水推舟·欺身逼近】：放下公文包，上前一步两手撑在门板两侧将她牢牢禁锢在怀中，低下头贴着她滚烫的小耳朵沉声低语：“小丫头，知不知道自己在说什么？你以为爸爸真的不敢动你？”【策略评估：打破道德防线，顺着她的争宠挑衅进行危险的肢体推拉】</d>\n<d>D. 【心惊胆战·假装应付】：眼神紧张地瞥了一眼厨房方向，迅速俯身飞快地在她软嫩的脸颊上亲了一口，小声催促：“亲了亲了！赶紧让开，要是被你妈妈看见了像什么样子！”【策略评估：仓促妥协满足她的部分要求，暂时化解迟到危机】</d>\n</suggested_questions>\n</opt>", "branches": [{"tag": "A", "title": "温和宠溺苦笑安抚", "desc": "揉揉发丝温和哄劝，承诺晚上下班带她吃大餐"}, {"tag": "B", "title": "严厉威严立规矩", "desc": "板起脸训斥女儿不懂规矩，以严父威严施压"}, {"tag": "C", "title": "顺水推舟欺身禁锢", "desc": "撑在门板上将她圈在怀中，贴着耳根进行危险反撩"}, {"tag": "D", "title": "慌忙偷亲应付过关", "desc": "戒备厨房妻子动静，匆忙在女儿脸上亲一口促其让路"}]}]', '', '<!DOCTYPE html>
<html lang="zh-CN">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>幻境织网者 - 角色与剧情设定生成器</title>
    <link href="https://fonts.googleapis.com/css2%sfamily=Noto+Serif+SC:wght@400;600;900&family=Noto+Sans+SC:wght@300;400;500;700&display=swap" rel="stylesheet">
    <style>
        :root {
            --bg-color: #fff8f0;
            --card-bg: #ffffff;
            --card-border: #ffe9d6;
            --accent-primary: #ff6b9d;
            --accent-secondary: #a66cff;
            --accent-highlight: #4d96ff;
            --accent-sun: #ffc53d;
            --accent-mint: #52b788;
            --text-main: #5a4a42;
            --text-sub: #9c8f86;
            --input-bg: #fffbf5;
            --input-border: #ffe6d0;
            --radius-md: 14px;
            --radius-lg: 24px;
            --shadow-soft: 0 10px 30px rgba(255, 175, 130, 0.18);
        }

        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }

        body {
            font-family: ''Noto Sans SC'', sans-serif;
            background-color: var(--bg-color);
            color: var(--text-main);
            line-height: 1.7;
            min-height: 100vh;
            overflow-x: hidden;
        }

        .container {
            max-width: 1100px;
            margin: 0 auto;
            padding: 40px 20px;
        }

        header {
            text-align: center;
            margin-bottom: 40px;
        }

        header h1 {
            font-family: ''Noto Serif SC'', serif;
            font-size: 2.9em;
            font-weight: 900;
            background: linear-gradient(135deg, #ff7a5c 0%, #ff6b9d 50%, #a66cff 100%);
            -webkit-background-clip: text;
            -webkit-text-fill-color: transparent;
            margin-bottom: 12px;
            letter-spacing: 3px;
        }

        header p {
            color: var(--text-sub);
            font-size: 1.1em;
            font-weight: 500;
        }

        .main-card {
            background: var(--card-bg);
            border: 2px solid var(--card-border);
            border-radius: var(--radius-lg);
            padding: 35px;
            box-shadow: var(--shadow-soft);
            margin-bottom: 30px;
        }

        .section-title {
            display: flex;
            align-items: center;
            gap: 12px;
            font-family: ''Noto Serif SC'', serif;
            font-size: 1.45em;
            font-weight: 900;
            color: #5a4a42;
            margin-bottom: 22px;
        }

        .title-icon {
            display: inline-flex;
            align-items: center;
            justify-content: center;
            width: 46px;
            height: 46px;
            border-radius: 15px;
            font-size: 1.25em;
            flex-shrink: 0;
            box-shadow: 0 4px 12px rgba(255, 150, 120, 0.22);
        }
        .title-icon.pink { background: linear-gradient(135deg, #ffd3e0, #ffe9f0); }
        .title-icon.blue { background: linear-gradient(135deg, #cde8ff, #e8f4ff); }
        .title-icon.sun { background: linear-gradient(135deg, #fff3cd, #ffe9b3); }

        .form-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
            gap: 18px;
            margin-bottom: 22px;
        }

        .form-group {
            display: flex;
            flex-direction: column;
            gap: 6px;
        }

        .form-group.full-width {
            grid-column: 1 / -1;
        }

        label {
            font-size: 0.95em;
            font-weight: 600;
            color: #6b5b52;
        }

        label span {
            color: var(--accent-secondary);
            font-size: 0.82em;
            font-weight: 500;
            margin-left: 4px;
        }

        input, textarea {
            background-color: var(--input-bg);
            border: 2px solid var(--input-border);
            border-radius: var(--radius-md);
            padding: 10px 12px;
            color: var(--text-main);
            font-family: inherit;
            font-size: 0.95em;
            transition: all 0.25s ease;
        }

        select {
            background-color: var(--input-bg);
            border: 2px solid var(--input-border);
            border-radius: var(--radius-md);
            padding: 10px 38px 10px 12px;
            color: var(--text-main);
            font-family: inherit;
            font-size: 0.95em;
            font-weight: 600;
            cursor: pointer;
            width: 100%;
            appearance: none;
            -webkit-appearance: none;
            background-image: url("data:image/svg+xml;charset=UTF-8,%3csvg xmlns=''http://www.w3.org/2000/svg'' width=''14'' height=''14'' viewBox=''0 0 24 24'' fill=''none'' stroke=''%23ff6b9d'' stroke-width=''3'' stroke-linecap=''round'' stroke-linejoin=''round''%3e%3cpolyline points=''6 9 12 15 18 9''%3e%3c/polyline%3e%3c/svg%3e");
            background-repeat: no-repeat;
            background-position: right 12px center;
            background-size: 14px;
            transition: all 0.25s ease;
        }

        select:focus {
            outline: none;
            border-color: var(--accent-primary);
            box-shadow: 0 0 0 4px rgba(255, 107, 157, 0.14);
            background-color: #ffffff;
        }

        input::placeholder, textarea::placeholder {
            color: #bfb2a8;
            opacity: 1;
        }

        input:focus, textarea:focus {
            outline: none;
            border-color: var(--accent-primary);
            box-shadow: 0 0 0 4px rgba(255, 107, 157, 0.14);
            background-color: #ffffff;
        }

        textarea {
            resize: vertical;
            min-height: 70px;
        }

        /* 角色卡片 */
        .character-card {
            background: var(--card-bg);
            border: 2px solid var(--card-border);
            border-radius: 18px;
            padding: 16px 18px;
            box-shadow: 0 6px 18px rgba(255, 175, 130, 0.12);
            margin-bottom: 14px;
            transition: box-shadow 0.3s ease, transform 0.3s ease;
        }
        .character-card:hover {
            transform: translateY(-2px);
            box-shadow: 0 14px 30px rgba(255, 175, 130, 0.22);
        }

        .character-header {
            display: flex;
            justify-content: space-between;
            align-items: center;
            margin-bottom: 10px;
        }

        .character-card .form-grid {
            grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
            gap: 12px;
            margin-bottom: 0;
        }

        .character-badge {
            font-size: 0.95em;
            font-weight: 800;
            color: #ffffff;
            background: linear-gradient(135deg, #ff6b9d, #ff9a5c);
            padding: 4px 14px;
            border-radius: 999px;
            box-shadow: 0 4px 10px rgba(255, 107, 157, 0.3);
        }

        .btn-remove-character {
            border: 2px solid #ffd3d3;
            background: #fff5f5;
            color: #e57373;
            padding: 4px 12px;
            border-radius: 999px;
            font-weight: 600;
            font-family: inherit;
            font-size: 0.82em;
            cursor: pointer;
            transition: all 0.2s;
        }
        .btn-remove-character:hover {
            background: #e57373;
            color: #ffffff;
            border-color: #e57373;
        }

        .btn-add-character {
            width: 100%;
            padding: 10px;
            border: 2px dashed #9be0b2;
            background: #f4fff7;
            color: #2f9e63;
            font-size: 0.95em;
            font-weight: 700;
            font-family: inherit;
            border-radius: 14px;
            cursor: pointer;
            transition: all 0.25s;
        }
        .btn-add-character:hover {
            background: #9be0b2;
            color: #ffffff;
            transform: translateY(-2px);
        }

        .btn-generate {
            display: flex;
            align-items: center;
            justify-content: center;
            width: 100%;
            padding: 17px;
            font-size: 1.2em;
            font-weight: 800;
            color: #ffffff;
            background: linear-gradient(135deg, #ff9a5c 0%, #ff6b9d 55%, #a66cff 120%);
            border: none;
            border-radius: 999px;
            cursor: pointer;
            transition: all 0.3s ease;
            box-shadow: 0 8px 24px rgba(255, 107, 157, 0.4);
            font-family: inherit;
        }

        .btn-generate:hover {
            transform: translateY(-3px);
            box-shadow: 0 12px 30px rgba(255, 107, 157, 0.5);
        }

        .btn-row {
            display: flex;
            flex-direction: column;
            gap: 14px;
            margin-top: 22px;
        }

        .btn-quick {
            width: 100%;
            padding: 15px;
            font-size: 1.05em;
            font-weight: 700;
            color: #2f9e63;
            background: linear-gradient(135deg, #eafaf0, #d5f5e0);
            border: 2px solid #9be0b2;
            border-radius: 999px;
            cursor: pointer;
            font-family: inherit;
            transition: all 0.25s;
        }

        .btn-quick:hover {
            background: linear-gradient(135deg, #9be0b2, #6bcb77);
            color: #ffffff;
            transform: translateY(-2px);
        }

        /* 使用说明 */
        .flow-hint {
            background: linear-gradient(135deg, #fff3e0, #ffe9f0);
            border: 2px dashed #ffc9d6;
            border-radius: var(--radius-md);
            padding: 12px 16px;
            font-size: 0.95em;
            color: #8a5a52;
            margin-bottom: 24px;
            line-height: 1.7;
        }
        .flow-hint b { color: #ff6b9d; }

        /* 可点选玩法面板 */
        .options-panel {
            background: #fffbf5;
            border: 2px solid #ffe6d0;
            border-radius: 18px;
            padding: 18px 20px;
            margin-bottom: 26px;
        }
        .options-header {
            display: flex;
            justify-content: space-between;
            align-items: center;
            margin-bottom: 14px;
        }
        .options-title {
            font-weight: 800;
            font-size: 1.1em;
            color: #5a4a42;
        }
        .btn-reset {
            border: 2px solid #c9c2f5;
            background: #f4f2ff;
            color: #7c6ee8;
            padding: 5px 14px;
            border-radius: 999px;
            font-weight: 700;
            font-family: inherit;
            font-size: 0.85em;
            cursor: pointer;
            transition: all 0.2s;
        }
        .btn-reset:hover {
            background: #a66cff;
            color: #ffffff;
            border-color: #a66cff;
        }
        .option-group { margin-bottom: 14px; }
        .option-group:last-child { margin-bottom: 0; }
        .option-group-label {
            font-size: 0.9em;
            font-weight: 700;
            color: #6b5b52;
            margin-bottom: 8px;
        }
        .option-chips {
            display: flex;
            flex-wrap: wrap;
            gap: 10px;
        }
        .chip {
            border: 2px solid #ffd3b3;
            background: #fff7ef;
            color: #b07b5a;
            padding: 6px 16px;
            border-radius: 999px;
            font-size: 0.92em;
            font-weight: 600;
            font-family: inherit;
            cursor: pointer;
            transition: all 0.2s;
        }
        .chip:hover { transform: translateY(-1px); }
        .chip.active {
            background: linear-gradient(135deg, #ff9a5c, #ff6b9d);
            color: #ffffff;
            border-color: transparent;
            box-shadow: 0 4px 12px rgba(255, 107, 157, 0.35);
        }
        .option-desc {
            margin-top: 8px;
            font-size: 0.82em;
            color: #b39a90;
        }

        /* 模态弹窗 */
        .modal {
            display: none;
            position: fixed;
            z-index: 1000;
            left: 0;
            top: 0;
            width: 100%;
            height: 100%;
            background-color: rgba(95, 70, 60, 0.35);
            backdrop-filter: blur(6px);
            justify-content: center;
            align-items: center;
            padding: 20px;
        }

        .modal-content {
            background-color: #ffffff;
            border: 2px solid #ffe6d0;
            border-radius: var(--radius-lg);
            width: 100%;
            max-width: 750px;
            max-height: 85vh;
            display: flex;
            flex-direction: column;
            box-shadow: 0 20px 60px rgba(255, 120, 90, 0.28);
            animation: modalFadeIn 0.3s ease;
        }

        @keyframes modalFadeIn {
            from { opacity: 0; transform: scale(0.95); }
            to { opacity: 1; transform: scale(1); }
        }

        .modal-header {
            padding: 20px 25px;
            border-bottom: 2px solid #ffefd2;
            display: flex;
            justify-content: space-between;
            align-items: center;
        }

        .modal-header h3 {
            color: var(--accent-primary);
            font-size: 1.3em;
            font-weight: 800;
        }

        .close-btn {
            background: none;
            border: none;
            color: var(--text-sub);
            font-size: 1.5em;
            cursor: pointer;
            transition: color 0.2s;
        }

        .close-btn:hover {
            color: #ff6b9d;
        }

        .modal-body {
            padding: 20px 25px;
            overflow-y: auto;
            flex: 1;
        }

        #prompt-output {
            width: 100%;
            min-height: 320px;
            background-color: #fff7ef;
            border: 2px solid #ffe6d0;
            border-radius: var(--radius-md);
            padding: 15px;
            color: #5a4a42;
            font-family: ''Courier New'', Courier, monospace;
            font-size: 0.9em;
            line-height: 1.6;
            white-space: pre-wrap;
            word-break: break-all;
            resize: vertical;
            outline: none;
        }
        #prompt-output:focus {
            border-color: var(--accent-primary);
            box-shadow: 0 0 0 4px rgba(255, 107, 157, 0.14);
        }

        .modal-footer {
            padding: 15px 25px;
            border-top: 2px solid #ffefd2;
            display: flex;
            justify-content: flex-end;
            gap: 15px;
        }

        .btn-copy {
            background: linear-gradient(135deg, #52b788 0%, #2f9e63 100%);
            color: #ffffff;
            border: none;
            padding: 10px 24px;
            border-radius: 999px;
            font-weight: 700;
            font-family: inherit;
            font-size: 0.95em;
            cursor: pointer;
            transition: all 0.2s;
        }

        .btn-copy:hover {
            background: linear-gradient(135deg, #2f9e63 0%, #1f8a54 100%);
            transform: translateY(-2px);
        }

        /* 底部与推广区域 */
        .footer {
            margin-top: 40px;
            text-align: center;
            border-top: 2px dashed #ffe6d0;
            padding-top: 25px;
            color: var(--text-sub);
            font-size: 0.95em;
        }

        .footer a {
            color: var(--accent-primary);
            text-decoration: none;
            font-weight: 700;
            transition: all 0.3s;
        }

        .footer a:hover {
            color: var(--accent-secondary);
            text-decoration: underline;
        }

    /* ========== 移动端适配 ========== */
        @media (max-width: 768px) {
            .container {
                padding: 20px 14px;
            }

            header h1 {
                font-size: 1.5em;
                letter-spacing: 1px;
                line-height: 1.4;
                margin-bottom: 8px;
            }

            header p {
                font-size: 0.95em;
            }

            .main-card {
                padding: 20px 14px;
                border-radius: 18px;
                margin-bottom: 20px;
            }

            .section-title {
                font-size: 1.2em;
                gap: 10px;
                margin-bottom: 16px;
            }

            .title-icon {
                width: 38px;
                height: 38px;
                font-size: 1.05em;
                border-radius: 12px;
            }

            .form-grid {
                gap: 14px;
                margin-bottom: 16px;
            }

            input, textarea, select {
                font-size: 1em;
                -webkit-appearance: none;
                appearance: none;
            }

            label {
                font-size: 0.92em;
            }

            .character-card {
                padding: 14px 12px;
                margin-bottom: 14px;
            }

            .character-card .form-grid {
                grid-template-columns: 1fr;
                gap: 14px;
            }

            .character-badge {
                font-size: 0.88em;
                padding: 4px 12px;
            }

            .btn-remove-character {
                padding: 4px 10px;
                font-size: 0.78em;
            }

            .btn-add-character {
                font-size: 0.92em;
            }

            .flow-hint {
                font-size: 0.92em;
                padding: 12px 14px;
            }

            .options-panel {
                padding: 14px;
            }

            .options-header {
                gap: 10px;
            }

            .options-title {
                font-size: 1em;
            }

            .option-chips {
                gap: 8px;
            }

            .chip {
                font-size: 0.88em;
                padding: 6px 13px;
            }

            .btn-generate {
                padding: 14px;
                font-size: 1.05em;
            }

            .btn-quick {
                padding: 13px;
                font-size: 1em;
            }

            .modal {
                padding: 12px;
                align-items: flex-end;
            }

            .modal-content {
                max-height: 92vh;
                border-radius: 20px 20px 0 0;
            }

            .modal-header {
                padding: 16px 18px;
            }

            .modal-header h3 {
                font-size: 1.15em;
            }

            .modal-body {
                padding: 16px 18px;
            }

            .modal-footer {
                padding: 12px 18px;
            }

            .btn-copy {
                width: 100%;
                text-align: center;
            }

            .footer {
                font-size: 0.85em;
                margin-top: 28px;
            }
        }

        @media (max-width: 480px) {
            .container {
                padding: 14px 10px;
            }

            header {
                margin-bottom: 24px;
            }

            .main-card {
                padding: 16px 12px;
            }

            .form-grid {
                grid-template-columns: 1fr;
            }
        }

    </style>
</head>
<body>

<div class="container">
    <header>
        <h1>调皮的女儿用自己的身体堵门</h1>
    </header>

    <div class="main-card">
        <!-- 使用说明 -->
        <div class="flow-hint">
            <b>玩法说明：</b>选主角风格 → 改剧情（可以不改）→ 设定角色（可增加角色） → 一键复制发给AI当第一条消息，生成初始剧情。
            懒汉玩法-直接点击上方生成初始剧情，或者拖到最后点击懒得填表，总之直接发送“生成初始剧情”就可以。
        </div>
      
        <!-- 可点选属性 -->
        <div class="options-panel">
            <div class="options-header">
                <span class="options-title">⚙️ 玩法风格</span>
                <button type="button" class="btn-reset" onclick="resetAll()">↺ 回全默认</button>
            </div>
            <div class="option-group">
                <div class="option-group-label">男主风格</div>
                <div class="option-chips" id="chips-style">
                    <button type="button" class="chip active" data-default="true" data-value="温和宠溺型——体贴入微、包容纵容，主角最爱被黏" onclick="selectChip(this, ''chips-style'')">温和宠溺</button>
                    <button type="button" class="chip" data-value="闷骚正经型——看似正经，内心骚气" onclick="selectChip(this, ''chips-style'')">闷骚正经</button>
                    <button type="button" class="chip" data-value="高冷反差型——表面冷淡，内心炽热，反差拉满" onclick="selectChip(this, ''chips-style'')">高冷反差</button>
                    <button type="button" class="chip" data-value="懒散随和型——随性自在，越随意越好笑" onclick="selectChip(this, ''chips-style'')">懒散随和</button>
                </div>
                <div class="option-desc">说明：温和宠溺=温和纯爱 · 闷骚正经=假证据 · 高冷反差=打反差 · 懒散=随意搞笑</div>
            </div>
            <div class="option-group">
                <div class="option-group-label">暧昧程度</div>
                <div class="option-chips" id="chips-romance">
                    <button type="button" class="chip active" data-default="true" data-value="全开——感情线全力展开，走色情刺激路线" onclick="selectChip(this, ''chips-romance'')">全开</button>
                    <button type="button" class="chip" data-value="纯爱——全程暧昧+剧情，用爱感化" onclick="selectChip(this, ''chips-romance'')">纯爱</button>
                </div>
                <div class="option-desc">说明：全开=没有顾忌 · 纯爱=全程暧昧+剧情</div>
            </div>
        </div>

        <!-- 剧情大纲与开局场景 -->
        <div class="section-title">
            <span class="title-icon blue">📖</span>
            剧情大纲与开局场景
        </div>
        <div class="form-grid">
            <div class="form-group full-width">
                <label for="plot-outline">剧情大纲与开局场景</label>
                <textarea id="plot-outline" rows="4" data-default="生成初始剧情" placeholder="我的女儿特别黏人，从小就喜欢缠着我跟我撒娇，而且她嫉妒心强，甚至她连她的妈妈都嫉妒。不知道是不是哪次我和媳妇做爱被她发现了还是怎么，她甚至觉得我只跟媳妇做爱是不爱她的表现，跟她解释她也不听。某天，我着急忙慌的要去上班，女儿一直黏着我缠着我跟我撒娇，不让我上班，让我在家陪她。我耐心的跟她解释说班还是要上的，没想到这个小祖宗直接把脚搭在门把上张开腿挡住了门口，气冲冲的对我说，老爸你老是跟妈妈搂搂抱抱的，都不抱我，如果你今天不不像对妈妈那样也抱我，就不准出门上班。这不是逼着我做一个禽兽吗，可恶。"></textarea>
            </div>
        </div>

        <!-- 认知设定 -->
        <div class="section-title" style="margin-top: 34px;">
            <span class="title-icon sun">🧠</span>
            认知设定
        </div>
        <div class="form-grid">
            <div class="form-group full-width">
                <label for="plot-cognition">认知设定</label>
                <textarea id="plot-cognition" rows="4" data-default="爸爸不做那些事就是不爱我" placeholder="爸爸不做那些事就是不爱我（可修改，例如角色对主角的初始看法、世界运行规则等）"></textarea>
            </div>
        </div>

        <!-- 视角设定 -->
        <div class="section-title" style="margin-top: 34px;">
            <span class="title-icon blue">🎬</span>
            视角设定
        </div>
        <div class="form-grid">
            <div class="form-group">
                <label for="plot-pov">视角设定</label>
                <select id="plot-pov">
                    <option value="男性视角" selected>男性视角</option>
                    <option value="女性视角">女性视角</option>
                    <option value="第三方视角">第三方视角</option>
                </select>
            </div>
            <div class="form-group">
                <label for="plot-pov-custom">自定义视角 <span>（选填，填写后优先使用）</span></label>
                <input type="text" id="plot-pov-custom" placeholder="例如：上帝视角、反派第一人称视角等">
            </div>
        </div>

        <!-- 角色设定 -->
        <div class="section-title" style="margin-top: 34px;">
            <span class="title-icon pink">👧</span>
            角色属性设定
        </div>
        <div id="characters-container">
            <!-- 女友妈妈 -->
            <div class="character-card">
                <div class="character-header">
                    <span class="character-badge">女儿</span>
                    <button type="button" class="btn-remove-character" onclick="removeCharacter(this)">删除角色</button>
                </div>
                <div class="form-grid">
                    <div class="form-group">
                        <label for="char-name-1">姓名</label>
                        <input type="text" id="char-name-1" class="char-name" data-default="林晓晓" placeholder="林晓晓（可改成你喜欢的名字）">
                    </div>
                    <div class="form-group">
                        <label for="char-age-1">年龄</label>
                        <input type="text" id="char-age-1" class="char-age" data-default="14岁" placeholder="14岁（可修改年龄）">
                    </div>
                    <div class="form-group">
                        <label for="char-identity-1">身份职业</label>
                        <input type="text" id="char-identity-1" class="char-identity" data-default="学生" placeholder="学生（可修改身份职业）">
                    </div>
                    <div class="form-group">
                        <label for="char-relation-1">与主角关系</label>
                        <input type="text" id="char-relation-1" class="char-relation" data-default="父女" placeholder="父女（可修改）">
                    </div>
                    <div class="form-group">
                        <label for="char-personality-1">性格特点</label>
                        <input type="text" id="char-personality-1" class="char-personality" data-default="清纯可爱，嫉妒心强" placeholder="清纯可爱，嫉妒心强">
                    </div>
                    <div class="form-group">
                        <label for="char-appearance-1">外貌身材</label>
                        <input type="text" id="char-appearance-1" class="char-appearance" data-default="贫乳双马尾" placeholder="贫乳双马尾">
                    </div>
                    <div class="form-group full-width">
                        <label for="char-other-1">其他设定 <span>(背景 / 能力 / 动机等)</span></label>
                        <textarea id="char-other-1" class="char-other" data-default="对爸爸不跟自己亲近非常不满" placeholder="对爸爸不跟自己亲近非常不满"></textarea>
                    </div>
                </div>
            </div>

            <!-- 女友-->
            <div class="character-card">
