    .tech-toast-content {
      background: linear-gradient(135deg, #252932 0%, #1a1d23 100%);
      border: 1px solid rgba(255, 255, 255, 0.08);
      border-radius: 12px;
      padding: 16px 24px;
      box-shadow: 0 8px 32px rgba(0, 0, 0, 0.5);
      pointer-events: auto;
    }
    
    .tech-info-block {
      background: rgba(0, 0, 0, 0.3);
      border: 1px solid rgba(255, 255, 255, 0.08);
      border-radius: 12px;
      padding: 16px;
      margin-bottom: 16px;
    }
    
    .tech-info-block-title {
      font-size: 12px;
      font-weight: 600;
      color: #ffffff;
      margin-bottom: 12px;
      text-transform: uppercase;
      letter-spacing: 2px;
    }
    
    .tech-preview-item {
      background: rgba(0, 0, 0, 0.3);
      border: 1px solid rgba(255, 255, 255, 0.08);
      border-radius: 8px;
      padding: 12px 16px;
      margin-bottom: 8px;
    }
    
    .tech-preview-label {
      color: #ffffff;
      font-size: 13px;
      font-weight: 600;
    }
    
    .tech-preview-value {
      color: #c4c4c4;
      font-size: 14px;
      margin-top: 4px;
    }
    
    details {
      border-radius: 12px;
      overflow: hidden;
      background: transparent;
      border: none;
      margin-bottom: 12px;
      transition: all 0.3s ease;
    }
    
    summary {
      display: flex;
      align-items: center;
      padding: 16px 24px;
      font-weight: 600;
      color: #e0e0e0;
      background: rgba(26, 29, 35, 0.8);
      cursor: pointer;
      list-style: none;
      text-transform: uppercase;
      letter-spacing: 1px;
      transition: all 0.3s ease;
      position: relative;
      font-size: 14px;
      border-radius: 12px;
      border: 1px solid rgba(255, 255, 255, 0.08);
      backdrop-filter: blur(10px);
    }
    
    summary:hover {
      background: rgba(40, 44, 52, 0.9);
      color: #fff;
      border-color: rgba(255, 255, 255, 0.2);
    }
    
    summary::before {
      content: ''▸'';
      margin-right: 12px;
      color: #ffffff;
      font-size: 12px;
      transition: transform 0.3s ease;
    }
    
    details[open] > summary::before {
      transform: rotate(90deg);
      color: #ffffff;
    }
    
    details[open] > summary {
      background: rgba(0, 0, 0, 0.4);
      border-bottom: 1px solid rgba(255, 255, 255, 0.2);
      border-radius: 12px 12px 0 0;
    }
    
    details > *:not(summary) {
      background: linear-gradient(135deg, #252932 0%, #1a1d23 100%);
      margin-top: 0;
      padding: 20px 24px;
      color: #c4c4c4;
      line-height: 1.7;
