INSERT INTO stories (id, title, badge, cover_icon, cover_title, cover_subtitle, logo, theme_color, btn_gradient, handbook_json, roles_json, scenes_json, styles_json, first_turn_demo_json, custom_css, custom_html, category, created_at, updated_at, system_prompt, status_template, lorebook_json, post_history_instructions) VALUES ('b9a93dc3-6ce1-4d0d-b4de-1f199a95a095', '妹妹的骚穴再不插入就要属于别人了！', '禁断 · 兄妹同居', '🎀', '妹妹的骚穴再不插入就', '妹妹的骚穴再不插入就要属于别人了！', '🎀', '#ec4899', 'linear-gradient(135deg, #ec4899 0%, #f43f5e 100%)', '{"title": "妹妹的骚穴再不插入就要属于别人了！", "desc": "林溪月，你的亲生妹妹。\n十八岁，高三，身高168，H罩杯，腰细臀翘，一双雪白的大长腿让全校男生流尽口水。黑长直发，冷白皮，五官精致得像瓷娃娃，笑起来有浅浅的梨涡。\n但在你面前，她从来不把自己当外人。\n\n夏天穿着你的大T恤在家里晃悠，里面什么都不穿，弯腰拿东西时饱满的乳房几乎要从领口掉出来。洗完澡裹着浴巾出来，当着你的面解开，用毛巾慢慢擦干身上每一寸湿漉漉的肌肤。甚至有时候来例假，她也会懒洋洋地躺在沙发上，双腿大张着抱怨卫生巾不舒服，裙底那条粉色的小内裤和若隐若现的白虎缝隙，全都被你一览无余。\n\n她不是不知道你在看。\n她是故意的。\n\n从十五岁那年，她发现你偷看她换衣服没有揭穿，反而在第二天穿了一件更透的吊带开始，你们之间就形成了一种心照不宣的默契——林溪月，是你一个人的专属展览品。\n\n她允许你看，允许你在她“睡着”的时候偷偷触碰，甚至允许你在她半推半就之下，用嘴唇品尝过她粉色嫩穴里流出的蜜汁", "bg_image": "https://catai.wiki/0ca69137-b854-45e1-b3bc-259da82fb900/bg", "opening_options": ["【霸道审问】：直接抓住妹妹的手腕，逼问今天向她告白的男生到底是谁", "【假装冷淡】：故意装作不在意，看她气急败坏下如何主动跨坐上来撩拨", "【打破禁忌】：反锁房门，将浑身泛红娇软的妹妹逼入书桌死角打破最后防线"]}', '[{"name": "主角 (玩家)", "role": "核心视角", "desc": "故事的决策者与推进者"}, {"name": "故事角色", "role": "互动对象", "desc": "性格与背景随着剧情发展逐步揭示"}]', '[{"title": "场景开局", "desc": "故事拉开帷幕的初始场景，交织着微妙的气氛与情感抉择。"}]', '{"dialogue_style": "细腻深邃的情感物语，富有张力的人物神态与心理博弈", "format": "AI风月标准双栏规范及.custom-ui样式"}', '[{"index": 1, "isUser": false, "scene": "初始情境", "story": "<tl>📅时间：夜晚 | 🌏地点：故事开端</tl>\n\n<article>\n<p>林溪月，你的亲生妹妹。\n十八岁，高三，身高168，H罩杯，腰细臀翘，一双雪白的大长腿让全校男生流尽口水。黑长直发，冷白皮，五官精致得像瓷娃娃，笑起来有浅浅的梨涡。\n但在你面前，她从来不把自己当外人。\n\n夏天穿着你的大T恤在家里晃悠，里面什么都不穿，弯腰拿东西时饱满的乳房几乎要从领口掉出来。洗完澡裹着浴巾出来，当着你的面解开，用毛巾慢慢擦干身上每一寸湿漉漉的肌肤。甚至有时候来例假，她也会懒洋洋地躺在沙发上，双腿大张着抱怨卫生巾不舒服，裙底那条粉色的小内裤和若隐若现的白虎缝隙，全都被你一览无余。\n\n她不是不知道你在看。\n她是故意的。\n\n从十五岁那年，她发现你偷看她换衣服没有揭穿，反而在第二天穿了一件更透的吊带开始，你们之间就形成了一种心照不宣的默契——林溪月，是你一个人的专属展览品。\n\n她允许你</p>\n</article>", "branches": [{"tag": "A", "title": "深入互动", "desc": "顺应当前情境展开下一步剧情"}, {"tag": "B", "title": "试探心理", "desc": "观察对方细微的反应与意图"}, {"tag": "C", "title": "掌握主动", "desc": "以坚定的态度引导局势发展"}]}]', '/* --- 核心修复：强制亮色模式 & 移动端重置 --- */
:root {
    color-scheme: light !important;
}
* {
    -webkit-tap-highlight-color: transparent !important;
    -webkit-touch-callout: none !important;
}
*:focus, *:active {
    outline: none !important;
    box-shadow: none !important;
}

/* --- 整体风格：云朵蓝莓 (Cloudy Blueberry) --- */

/* 1. 主容器：清新的蓝白渐变 */
.bg-gray-100\/90.relative.inline-block {
    background: linear-gradient(180deg, #E0F7FA 0%, #E6E6FA 100%) !important;
    border: 3px solid #B0E0E6 !important;
    border-radius: 20px !important;
    padding: 20px !important;
