  font-size:14px;
  color:var(--pink);
  letter-spacing:6px;
  opacity:.8;
}

/* 通用卡片 */
.card{
  background:var(--card);
  border:1px solid var(--line);
  border-radius:var(--radius);
  box-shadow:var(--shadow-soft);
  padding:20px 18px;
  margin-bottom:18px;
  backdrop-filter:blur(6px);
  position:relative;
  overflow:hidden;
}
.card-title{
  display:flex;
  align-items:center;
