<animate attributeName="stroke-dashoffset" from="280" to="0" dur="2s" fill="freeze" />
</circle>
<path d="M30 50 L45 65 L70 35" fill="none" stroke="#e91e63" stroke-width="5" stroke-linecap="round" stroke-linejoin="round">
<animate attributeName="stroke-dashoffset" from="100" to="0" dur="1s" begin="1.5s" fill="freeze" />
