ter;justify-content:flex-start;padding:60px 20px;overflow-y:auto;opacity:0;transition:opacity 0.4s ease;}#rule-modal::before{content:'''';position:fixed;top:0;left:0;width:100%;height:100%;pointer-events:none;box-shadow:inset 0 0 100px rgba(138,3,3,0.15);z-index:-1;}.rule-modal-content{width:100%;max-width:800px;background:#050202;border:1px solid #8a0303;padding:40px;box-shadow:0 0 40px rgba(138,3,3,0.4);position:relative;animation:slideDown 0.4s ease forwards;}@keyframes slideDown{from{transform:translateY(-30px);opacity:0;}to{transform:translateY(0);opacity:1;}}.chapter-list{width:100%;display:flex;flex-direction:column;gap:15px;}.chapter-item{background:rgba(15,5,5,0.8);border:1px solid #4a0101;border-radius:3px;overflow:hidden;}.chapter-title{width:100%;background:linear-gradient(90deg, rgba(138,3,3,0.2) 0%, rgba(0,0,0,0) 100%);border:none;padding:15px 20px;text-align:left;font-family:var(--font-title);font-size:1.4rem;color:#ff1a1a;font-weight:bold;transition:all 0.3s ease;display:flex;justify-content:space-between;align-items:center;}.chapter-title:hover{background:linear-gradient(90deg, rgba(138,3,3,0.4) 0%, rgba(20,0,0,0.8) 100%);padding-left:25px;}.chapter-title::after{content:''+'';font-size:1.8rem;color:#8a0303;transition:transform 0.3s;}.chapter-item.active .chapter-title::after{content:''-'';transform:rotate(180deg);color:#ff1a1a;}.chapter-nodes{display:none;padding:15px 20px;border-top:1px dashed #4a0101;background:rgba(5,0,0,0.6);}.chapter-item.active .chapter-nodes{display:block;animation:fadeIn 0.4s ease;}.node-item{padding:10px 0;border-bottom:1px solid rgba(138,3,3,0.15);color:#b0b0b0;font-size:1.05rem;line-height:1.5;position:relative;padding-left:15px;}.node-item::before{content:'''';position:absolute;left:0;top:18px;width:6px;height:6px;background:#8a0303;border-radius:50%;}.node-item:last-child{border-bottom:none;}.roster-container{display:flex;flex-wrap:wrap;gap:20px;justify-content:center;padding:20px 0;}.roster-group{width:100%;margin-bottom:30px;}.roster-group-title{color:#a00505;font-family:var(--font-title);font-size:1.5rem;border-bottom:1px dashed #4a0101;margin-bottom:15px;padding-bottom:5px;}.roster-item{background:none;border:none;color:#8a0303;font-family:var(--font-title);font-size:1.8rem;font-weight:bold;text-shadow:1px 1px 3px #000;transition:all 0.3s;padding:5px 15px;position:relative;display:inline-block;}.roster-item:hover{color:#ff1a1a;text-shadow:0 0 10px rgba(255,0,0,0.8);transform:scale(1.1) !important;z-index:2;}.roster-item::after{content:'''';position:absolute;bottom:0;left:0;width:100%;height:2px;background:#ff1a1a;transform:scaleX(0);transition:transform 0.3s;}.roster-item:hover::after{transform:scaleX(1);}.form-group{margin-bottom:20px;}.form-label{display:block;font-family:var(--font-title);font-size:1.2rem;color:#a00505;margin-bottom:8px;font-weight:bold;}.form-input, .form-select, .form-textarea{width:100%;background:rgba(0,0,0,0.5);border:1px solid #4a0101;font-family:var(--font-body);font-size:1rem;color:#fff;padding:12px;transition:all 0.3s ease;outline:none;border-radius:2px;}.form-input:focus, .form-select:focus, .form-textarea:focus{border-color:#ff1a1a;background:rgba(138,3,3,0.1);box-shadow:inset 0 0 10px rgba(138,3,3,0.3);}.form-textarea{resize:vertical;min-height:80px;}option{background:#050505;color:#ccc;}.flex-row{display:flex;gap:15px;}.flex-half{flex:1;}.preview-box{margin-top:30px;padding:20px;background-color:rgba(0,0,0,0.8);border:1px dashed #4a0101;border-radius:2px;font-family:''Courier New'',Courier,monospace;font-size:1rem;line-height:1.6;color:#aaa;white-space:pre-wrap;word-wrap:break-word;box-shadow:inset 0 0 15px #000;}.btn-submit{display:block;width:100%;background:linear-gradient(to bottom, #4a0101, #1a0000);color:#ff1a1a;text-align:center;padding:15px;font-family:var(--font-title);font-size:1.5rem;font-weight:bold;border:1px solid #8a0303;border-radius:3px;margin-top:30px;box-shadow:0 0 15px rgba(138,3,3,0.4);transition:all 0.3s ease;letter-spacing:2px;}.btn-submit:hover{background:linear-gradient(to bottom, #8a0303, #4a0101);color:#fff;box-shadow:0 0 25px rgba(255,0,0,0.6);animation:heartbeat 1s infinite;}@keyframes heartbeat{0%,100%{transform:scale(1.02);}50%{transform:scale(1.04);}}#copy-modal{position:fixed;top:0;left:0;width:100%;height:100vh;background-color:rgba(0,0,0,0.9);display:none;justify-content:center;align-items:center;z-index:20000;opacity:0;transition:opacity 0.3s ease;}.modal-content{background-color:#0a0505;padding:40px;border-radius:3px;text-align:center;box-shadow:0 0 40px #8a0303;border:1px solid #ff1a1a;max-width:400px;width:90%;}.modal-title{font-family:var(--font-title);font-size:1.8rem;color:#ff1a1a;margin-bottom:15px;font-weight:bold;}.modal-text{font-size:1.1rem;margin-bottom:25px;color:#ccc;}.btn-close{background-color:#1a0000;color:#ff1a1a;border:1px solid #8a0303;padding:10px 30px;font-size:1.1rem;border-radius:2px;transition:all 0.3s;font-weight:bold;}.btn-close:hover{background-color:#4a0101;box-shadow:0 0 10px #ff0000;}footer{position:fixed;bottom:0;width:100%;text-align:center;padding:10px;opacity:0.01;pointer-events:none;z-index:-1;}footer a{color:#fff;text-decoration:none;font-size:12px;}@media (max-width:768px){.menu-item:nth-child(1){top:20%;left:5%;font-size:2rem;}.menu-item:nth-child(2){top:40%;left:55%;font-size:1.8rem;}.menu-item:nth-child(3){top:60%;left:10%;font-size:2.2rem;}.menu-item:nth-child(4){top:80%;left:45%;font-size:2.5rem;}.panel{width:95%;padding:35px 20px 20px 20px;height:90vh;}.panel-title{font-size:1.8rem;}.flex-row{flex-direction:column;gap:0;}#rule-modal{padding:40px 10px;}.rule-modal-content{padding:30px 15px;}}</style></head><body><audio id="bgm" loop preload="auto"><source src="https://music.163.com/song/media/outer/url%sid=1374978394.mp3" type="audio/mpeg"></audio><button id="music-toggle" class="clickable" title="开启/关闭音效"><svg id="icon-play" width="30" height="30" viewBox="0 0 24 24" fill="none" stroke="#ff1a1a" stroke-width="2" style="display:block;"><polygon points="11 5 6 9 2 9 2 15 6 15 11 19 11 5"></polygon><path d="M19.07 4.93a10 10 0 0 1 0 14.14M15.54 8.46a5 5 0 0 1 0 7.07"></path></svg><svg id="icon-mute" width="30" height="30" viewBox="0 0 24 24" fill="none" stroke="#666" stroke-width="2" style="display:none;"><polygon points="11 5 6 9 2 9 2 15 6 15 11 19 11 5"></polygon><line x1="23" y1="9" x2="17" y2="15"></line><line x1="17" y1="9" x2="23" y2="15"></line></svg></button><div id="new-intro" class="clickable"><div class="intro-text">我叫杨间，当你看见这句话的时候我已经死了.....</div></div><div id="main-scene"><div id="main-menu"><button class="menu-item clickable" data-target="panel-world">【天地冥律】</button><button class="menu-item clickable" data-target="panel-events">【血字案卷】</button><button class="menu-item clickable" data-target="panel-chars">【遗像留影】</button><button class="menu-item clickable" data-target="panel-create">【入局引路】</button></div><div id="panel-world" class="panel"><button class="panel-close clickable">×</button><h2 class="panel-title">天地冥律</h2><p class="lore-text" style="text-align:center;margin-bottom:25px;color:#ff1a1a;">【绝密警告】点击查阅灵异档案，知晓越多，死得越快。</p><div class="rule-item" data-rule="1">【铁律一】厉鬼本源与规律</div><div class="rule-item" data-rule="2">【铁律二】暗夜割据与势力</div><div class="rule-item" data-rule="3">【铁律三】诡物图鉴与代价</div><div class="rule-item" data-rule="4">【铁律四】驾驭、死机与异类</div></div><div id="rule-modal"><div class="rule-modal-content"><button id="close-rule-modal" class="panel-close clickable">×</button><h2 id="rule-modal-title" class="panel-title"></h2><div id="rule-modal-body"></div></div></div><div id="panel-events" class="panel"><button class="panel-close clickable">×</button><h2 class="panel-title">血字案卷</h2><p class="lore-text" style="text-align:center;margin-bottom:20px;">【绝密档案：时代终结者的足迹，点击篇章展开节点】</p><div class="chapter-list" id="chapter-accordion"></div></div><div id="panel-chars" class="panel"><button class="panel-close clickable">×</button><h2 class="panel-title">遗像留影</h2><p class="lore-text">这里曾经记录着许多名字，像是一份等待死神勾划的清单。点击血字查看生平绝密。</p><div class="roster-group"><div class="roster-group-title">【核心主角团】</div><div class="roster-container" id="roster-main"></div></div><div class="roster-group"><div class="roster-group-title">【总部顶尖队长】</div><div class="roster-container" id="roster-captains"></div></div></div><div id="panel-create" class="panel"><button class="panel-close clickable">×</button><h2 class="panel-title">入局引路 (签订死契)</h2><div class="flex-row"><div class="flex-half form-group"><label class="form-label">名字/代号：</label><input type="text" id="cfg-name" class="form-input" placeholder="输入姓名或代号..." autocomplete="off"></div><div class="flex-half form-group"><label class="form-label">性别：</label><select id="cfg-gender" class="form-select"><option value="男">男</option><option value="女">女</option><option value="未知">未知/不可名状</option></select></div></div><div class="flex-row"><div class="flex-half form-group"><label class="form-label">社会身份：</label><input type="text" id="cfg-identity" class="form-input" placeholder="如：学生/公司职员/无业游民/安保..."></div><div class="flex-half form-group"><label class="form-label">性格特征：</label><input type="text" id="cfg-personality" class="form-input" placeholder="如：冷酷无情/疯狂/谨慎胆小/圣母..."></div></div><div class="flex-row"><div class="flex-half form-group"><label class="form-label">所属势力：</label><select id="cfg-faction" class="form-select"><option value="亚洲区总部">亚洲区总部</option><option value="朋友圈">朋友圈</option><option value="灵异论坛">灵异论坛</option><option value="国王组织">国王组织</option><option value="鬼邮局/太平古镇">鬼邮局/太平古镇</option><option value="民间散人">民间散人</option><option value="custom">【自定义势力】</option></select><input type="text" id="cfg-faction-custom" class="form-input" placeholder="输入自定义势力..." style="display:none; margin-top:10px;"></div><div class="flex-half form-group"><label class="form-label">介入篇章：</label><select id="cfg-time-chapter" class="form-select"></select></div></div><div class="form-group"><label class="form-label">介入节点：</label><select id="cfg-time-node" class="form-select"></select></div><div class="form-group"><label class="form-label">生命形态：</label><select id="cfg-lifeform" class="form-select"><option value="普通人">普通人 (在灵异事件中绝望求生)</option><option value="驭鬼者" selected>驭鬼者/异类 (与鬼共舞，饮鸩止渴)</option></select></div><div id="ghost-config-area"><div class="form-group"><label class="form-label">驾驭的灵异拼图 (能力与杀人规律)：</label><textarea id="cfg-ghost" class="form-textarea" placeholder="详细描述你体内厉鬼的能力。例如：鬼眼（红光覆盖范围内皆为鬼域）、无头鬼影（拼接肢解躯体）..."></textarea></div><div class="flex-row"><div class="flex-half form-group"><label class="form-label">即死条件 (触发规律)：</label><input type="text" id="cfg-death" class="form-input" placeholder="例如：听到特定频率的敲门声必死..."></div><div class="flex-half form-group"><label class="form-label">复苏代价 (使用能力的后果)：</label><input type="text" id="cfg-cost" class="form-input" placeholder="例如：每次使用鬼域，身体就会加速腐烂..."></div></div><div class="form-group"><label class="form-label">角色实力境界：</label><select id="cfg-power" class="form-select"><option value="驾驭单鬼期 (濒临复苏)">驾驭单鬼期 (濒临复苏，随时暴毙)</option><option value="双鬼平衡期 (短暂安全)">双鬼平衡期 (短暂安全，掌控一定自保力)</option><option value="半异类 (免疫常规致死)">半异类 (免疫常规致死，开始舍弃人类结构)</option><option value="队长级 (掌控深层鬼域)">队长级 (掌控深层鬼域，足以镇压S级事件)</option><option value="民国老怪级 (灵异源头)">民国老怪级 (灵异源头，近乎无解的存在)</option></select></div></div><div class="form-group"><label class="form-label">背景故事与执念：</label><textarea id="cfg-bg" class="form-textarea" placeholder="简述你的过去，以及在这绝望世界中支撑你活下去的唯一理由..."></textarea></div><div class="form-group"><label class="form-label">绝密档案预览：</label><div id="preview-box" class="preview-box"></div></div><button type="button" id="btn-submit" class="btn-submit clickable">【生成死契档案并复制】</button></div></div><div id="copy-modal"><div class="modal-content"><h3 class="modal-title">契约已成</h3><p class="modal-text">你的绝密档案已成功复制。<br>无论你是原著角色还是自定义人物，祝你在这地狱中...活得久一点。</p><button class="btn-close clickable" id="btn-close-modal">关闭</button></div></div><footer><a href="https://aitrader.wiki/zh/explore/installed/813e225e-2a1a-45bd-b441-f4741dff5418" target="_blank">本页面采用AI风月-创作大师生成</a></footer><script>const bgm=document.getElementById(''bgm'');const musicToggle=document.getElementById(''music-toggle'');const iconPlay=document.getElementById(''icon-play'');const iconMute=document.getElementById(''icon-mute'');let isMusicPlaying=false;function toggleMusic(){if(isMusicPlaying){bgm.pause();iconPlay.style.display=''none'';iconMute.style.display=''block'';}else{bgm.play().catch(e=>console.log(e));iconPlay.style.display=''block'';iconMute.style.display=''none'';}isMusicPlaying=!isMusicPlaying;}musicToggle.addEventListener(''click'',toggleMusic);const newIntro=document.getElementById(''new-intro'');const mainMenu=document.getElementById(''main-menu'');const menuItems=document.querySelectorAll(''.menu-item'');const panels=document.querySelectorAll(''.panel'');const panelCloses=document.querySelectorAll(''.panel-close'');let introDone=false;newIntro.addEventListener(''click'',()=>{if(introDone)return;introDone=true;newIntro.style.opacity=''0'';bgm.play().then(()=>{isMusicPlaying=true;iconPlay.style.display=''block'';iconMute.style.display=''none'';}).catch(e=>console.log("Audio autoplay blocked"));musicToggle.style.display=''block'';setTimeout(()=>{newIntro.style.display=''none'';},1500);});function hideAllPanels(){panels.forEach(p=>{p.style.display=''none'';p.style.opacity=''0'';});}menuItems.forEach(item=>{item.addEventListener(''click'',()=>{const targetId=item.getAttribute(''data-target'');mainMenu.style.opacity=''0'';setTimeout(()=>{mainMenu.style.display=''none'';hideAllPanels();const targetPanel=document.getElementById(targetId);targetPanel.style.display=''block'';setTimeout(()=>{targetPanel.style.opacity=''1'';},50);},500);});});panelCloses.forEach(btn=>{if(btn.id===''close-rule-modal'')return;btn.addEventListener(''click'',()=>{hideAllPanels();mainMenu.style.display=''block'';setTimeout(()=>{mainMenu.style.opacity=''1'';},50);});});const ruleData={1:{title:''【铁律一】厉鬼本源与规律'',content:''<p class="lore-text">1. <span class="blood-highlight">鬼无法被杀死。</span>这是这个世界最让人绝望的基石。任何物理手段、热武器、核弹都对真正的灵异无效。即使将其打碎、焚烧，它也会在灵异的深处再次复原。</p><p class="lore-text">2. <span class="blood-highlight">能对付鬼的只有鬼。</span>人类只有驾驭了厉鬼力量（成为驭鬼者），利用体内的灵异去对抗外在的灵异，才能挣扎求生。这本质上是用毒药解毒。</p><p class="lore-text">3. <span class="blood-highlight">洞察鬼的规律。</span>每一只鬼都有其绝对的杀人规律（如：听到敲门声、回头、被看到脸）。只要不触发规律，普通人也能与S级厉鬼擦肩而过；一旦触发规律，无视距离、无视防御，必死无疑。</p><p class="lore-text">4. <span class="blood-highlight">鬼域与重启。</span>高等级的厉鬼拥有“鬼域”，这是一种扭曲现实的灵异空间。而在鬼域的深层（如第七层以上），甚至可以触及时间的禁忌，实现“重启”，将自身或周围的一切倒退回几十分钟前的状态。</p>''},2:{title:''【铁律二】暗夜割据与势力'',content:''<p class="lore-text">在这个被绝望笼罩的世界中，灵异事件频发，驭鬼者们抱团取暖，形成了主宰生死的各大势力：</p><p class="lore-text">- <span class="blood-highlight">【亚洲区总部】</span>：官方最高组织，掌握最多资源。以“十二队长”为核心战力，致力于关押厉鬼、维持秩序。队长级人物拥有独立处置S级事件的特权与实力。</p><p class="lore-text">- <span class="blood-highlight">【朋友圈】</span>：以利益为核心的顶尖驭鬼者财阀，行事霸道，底蕴深厚。曾试图通过资本与灵异结合掌控总部，后被杨间单枪匹马血洗覆灭。</p><p class="lore-text">- <span class="blood-highlight">【灵异论坛】</span>：民间最大的驭鬼者交流与互助平台，由亚洲第一驭鬼者叶真所创。叶真以中二病著称，但实力极其恐怖，拥有替死灵异。</p><p class="lore-text">- <span class="blood-highlight">【国王组织】</span>：海外顶尖势力，由多位代号为"国王"的恐怖驭鬼者组成。企图用“诺亚方舟计划”将幽灵船引向亚洲，颠覆现有格局，引发了惨烈的世界大战。</p><p class="lore-text">- <span class="blood-highlight">【鬼邮局/太平古镇】</span>：遗留自民国时期的恐怖灵异之地。民国七老为了镇压灵异留下的后手，既是可怕的诅咒，也是上一代的传承。邮局管理者掌控着无数信使的生死。</p>''},3:{title:''【铁律三】诡物图鉴与代价'',content:''<p class="lore-text">灵异物品是保命的底牌，但使用它们往往伴随着比死亡更可怕的代价：</p><p class="lore-text">- <span class="blood-highlight">【人皮纸】</span>：知晓过去未来，能给出驾驭厉鬼的完美方案。但它拥有极高智慧，给出的方案里永远藏着置人于死地、企图让自己脱困的致命陷阱。</p><p class="lore-text">- <span class="blood-highlight">【鬼橱】</span>：等价交换的极致。向它提出要求，它必定帮你实现，但你必须在规定时间内完成它下达的恐怖任务，否则将面临无解的抹杀。</p><p class="lore-text">- <span class="blood-highlight">【棺材钉】</span>：无视任何规律的终极压制物。只要钉入厉鬼体内，瞬间形成绝对压制，连S级源头也能使其死机。杨间凭此一击封神关押饿死鬼。</p><p class="lore-text">- <span class="blood-highlight">【鬼柴刀】</span>：只要留下脚印，就能无视空间距离隔空肢解厉鬼。代价是绝对的等价反噬：使用者也会承受同等部位的肢解，没有极强恢复力的驭鬼者用之必死。</p><p class="lore-text">- <span class="blood-highlight">【红色鬼烛】</span>：点燃后，只要烛火不灭，处于火光范围内的人绝对安全。燃烧速度取决于遭受的灵异攻击强度，面对S级厉鬼可能瞬间燃尽。</p><p class="lore-text">- <span class="blood-highlight">【白色鬼烛】</span>：点燃会散发黑色阴霾，必定吸引周围厉鬼到来。极其危险，通常用于绝境中主动引鬼制造混乱。</p><p class="lore-text">- <span class="blood-highlight">【八音盒】</span>：打开播放诡异音乐，音乐响起时听者被施加不死诅咒，肉身被毁也能活。代价：音乐停止时，听者将遭受无解的厉鬼袭击。</p><p class="lore-text">- <span class="blood-highlight">【替死娃娃】</span>：极其稀有，写上名字后，可代替使用者承受一次必死的灵异袭击。是驭鬼者梦寐以求的保命神物。</p>''},4:{title:''【铁律四】驾驭、死机与异类'',content:''<p class="lore-text">成为驭鬼者，就是在饮鸩止渴。力量的尽头是彻底的深渊：</p><p class="lore-text">- <span class="blood-highlight">【厉鬼复苏】</span>：每一次使用灵异力量，都会刺激体内的厉鬼，加速其苏醒。当鬼完全复苏，驭鬼者就会暴毙，体内的鬼将脱离束缚，化作新的、更恐怖的灵异事件。</p><p class="lore-text">- <span class="blood-highlight">【拼图与制衡】</span>：延缓复苏的唯一常规方法。驾驭两只或多只杀人规律互补、相互克制的厉鬼，在体内形成脆弱的平衡。但平衡一旦打破，死得更快。</p><p class="lore-text">- <span class="blood-highlight">【厉鬼死机】</span>：极少数情况下的奇迹。通过极端的灵异冲突（如在特定灵异之地自杀重启），让体内的鬼陷入深度沉睡。驭鬼者可以毫无代价地使用力量，但随着时间推移，死机依然有解除的风险。</p><p class="lore-text">- <span class="blood-highlight">【彻底异类】</span>：驭鬼者的最高境界。彻底舍弃人类的生理结构，用灵异力量重塑身躯，甚至将自己的意识转化为某种灵异现象。异类不再惧怕厉鬼复苏，拥有近乎无限的寿命，但也会逐渐丧失人性，变得冷漠如真正的厉鬼。</p>''}};const ruleItems=document.querySelectorAll(''.rule-item'');const ruleModal=document.getElementById(''rule-modal'');const ruleModalTitle=document.getElementById(''rule-modal-title'');const ruleModalBody=document.getElementById(''rule-modal-body'');const closeRuleModal=document.getElementById(''close-rule-modal'');function openModal(title,content){ruleModalTitle.innerText=title;ruleModalBody.innerHTML=content;ruleModal.style.display=''flex'';setTimeout(()=>{ruleModal.style.opacity=''1'';},50);}ruleItems.forEach(item=>{item.addEventListener(''click'',()=>{const ruleId=item.getAttribute(''data-rule'');openModal(ruleData[ruleId].title,ruleData[ruleId].content);});});closeRuleModal.addEventListener(''click'',()=>{ruleModal.style.opacity=''0'';setTimeout(()=>{ruleModal.style.display=''none'';},400);});const chapters=[{title:"第一篇章：大昌市篇",nodes:["节点1：2018年6月14日-15日·大昌市第七高中敲门鬼事件","节点2：2018年6月15日·逃出生天与驭鬼者之路","节点3：2018年6月15-16日·认鬼做父与商场诡影","节点4：2018年6月17日·无头鬼影与商场逃生","节点5：2018年6月17日-20日·厉鬼收容与黑吃黑"]},{title:"第二篇章：黄岗村篇",nodes:["节点1：2018年6月20日-23日·俱乐部冲突与黄岗村惊魂","节点2：2018年6月24日-26日·打破平衡与恶鬼交易","节点3：2018年6月26日·驾驭双鬼与黄岗村终局","节点4：2018年7月1日-2日·鬼婴重现与镜中鬼","节点5：2018年7月2日-3日·鬼血复苏与俱乐部之战","节点6：2018年7月3日·诅咒反杀与观江交易","节点7：2018年7月3日·敲门鬼域与鬼绳复苏","节点8：2018年7月3日-7日·古宅鬼镜与杀机暗涌","节点9：2018年7月7日-8日·绝杀与反击"]},{title:"第三篇章：饿死鬼篇",nodes:["节点1：2018年7月8日-9日·饿死鬼事件爆发","节点2：7月9日-13日·第七街与饿死鬼","节点3：7月13日-18日·绝境与赌命","节点4：7月18日-25日·向死而生与时间重置","节点5：7月25日-31日·饿死鬼终局与余波"]},{title:"第四篇章：灵异公交车篇",nodes:["节点1：8月1日-2日·鬼脸遗患与灵异公交","节点2：8月2日-8月8日·鬼车死局与X级档案","节点3：8月9日-10日·鬼橱交易与中山迷局"]},{title:"第五篇章：凯撒大酒店篇",nodes:["节点1：8月11日·凯撒大酒店与笑脸迷局","节点2：8月12日·鬼雾迷局与无解柴刀","节点3：8月12-13日·记忆篡改与禁忌重生","节点5：8月13-18日·大昌市的部署与大京市之行"]},{title:"第六篇章：总部鬼差篇",nodes:["节点1：8月18日·航班惊魂与大京市初阵","节点2：8月18-19日·大京市暗流与记忆篡改","节点3：8月20日·大京市培训与鬼差出棺","节点4：8月20-21日·绝境博弈与鬼差重启","节点5：8月21-22日·五层鬼域与总部风波","节点6：8月22-23日·总部立威与民国隐秘","节点7：8月23日·敲门鬼之谜与S级失控","节点8：8月23-24日·总部救援与雷霆清算","节点9：8月24-25日·鬼画初现与惊魂救援","节点10：8月25日·绝杀与八音盒诅咒","节点11：8月25日·血洗朋友圈与六层鬼域","节点12：8月25-26日·诡异柴刀与诅咒博弈"]},{title:"第七篇章：鬼梦篇",nodes:["节点1：8月26日·画中求生与鬼橱交易","节点2：8月27-28日·灵位陷阱与意识复苏","节点3：8月28-30日·队伍集结与跨国交易","节点4：8月31日-9月1日·神户除灵与敲门鬼关押","节点5：9月1日-3日·死亡预知与归乡探秘","节点5：9月3日-13日·鬼梦终结与总部惊变"]},{title:"第八篇章：鬼湖篇",nodes:["节点1：9月14日-16日·鬼邮局与福寿园之谜","节点2：9月16日-18日·大川市的无影阴霾","节点3：9月18-19日·大川市的全面失控与301室之谜","节点4：9月20-22日·异类觉醒与大东古宅","节点5：9月23-26日·邮局四楼与公交前夕","节点6：9月26日-10月1日·灵异公交与古宅七日","节点7：10月1日-10月6日·头七回魂与邮局五楼","节点8：10月7日-10月8日·地狱公寓与神兵天降","节点9：10月8日-10月11日·许愿鬼与鬼湖集结","节点10：10月11日-10月15日·鬼湖封锁与恶犬认主"]},{title:"第九篇章：鬼画篇",nodes:["节点1：10月16日-10月19日·大澳市风波与凯撒迷局","节点2：10月19日-10月25日·凯撒迷局与大京风云","节点3：10月25日-10月26日·大京风云与桃花源计划","节点4：10月26日-10月28日·桃花源碎与白水迷局","节点5：10月28-30日·虚幻崩塌与重启之局","节点6：10月30日-10月31日·灵灵异游戏与民国恩怨"]},{title:"第十篇章：世界大战篇",nodes:["节点1：2024年11月1日-11月3日·幽灵船余波与队长反击","节点2：2024年11月4日-11月5日·大洲市决战与幽灵船落幕","节点3：2024年11月6日-11月15日·鬼血沉寂与阴阳路计划","节点4：2024年11月-2084年11月·六十年的等待与新旧交替","节点5：2084年11月3日-11月5日·神明显化与灵异终结"]}];const chapterAccordion=document.getElementById(''chapter-accordion'');chapters.forEach((chap,idx)=>{const item=document.createElement(''div'');item.className=''chapter-item'';const btn=document.createElement(''button'');btn.className=''chapter-title clickable'';btn.innerText=chap.title;const nodesDiv=document.createElement(''div'');nodesDiv.className=''chapter-nodes'';chap.nodes.forEach(node=>{const n=document.createElement(''div'');n.className=''node-item'';n.innerText=node;nodesDiv.appendChild(n);});btn.addEventListener(''click'',()=>{item.classList.toggle(''active'');});item.appendChild(btn);item.appendChild(nodesDiv);chapterAccordion.appendChild(item);});const rosterData={main:[{name:''杨间'',desc:''代号【鬼眼】。亚洲区执法队长，终结时代的看门人。从七中敲门鬼事件绝境求生，一路踏着厉鬼与驭鬼者的尸骨登顶。体内驾驭了鬼眼（九层鬼域、范围重启）、无头鬼影（拼接肢解躯体）、鬼手（绝对压制）、鬼梦恶犬（意识拉入梦境）、骗人鬼（欺骗现实）、鬼火（焚烧灵异）。持有武器：鬼柴刀、红缨枪（镶嵌棺材钉）。他窃取鬼湖灵异重塑身躯化身彻底异类。最终为了终结灵异时代，他疯狂肢解融合万千恐怖源头成就终极神明形态，创造绝对封闭世界，化身看门人，将世间所有厉鬼拉入深渊永恒镇压。''},{name:''张伟'',desc:''阿伟。杨间的死党，运气逆天的普通人，自带极强的“搞笑抗性”。在无数次S级、A级灵异事件中奇迹生还，甚至敢在极其危险的灵异之地淡定地打电动游戏。被书迷戏称为“夜之帝王”。虽然他没有驾驭任何厉鬼，但他那近乎荒诞的乐观和生存能力，是杨间在逐渐丧失人性的过程中，为数不多能维系其情感锚点的存在。''},{name:''王珊珊'',desc:''鬼童饲养员。杨间的狂热追随者与绝对心腹。在七中敲门鬼事件后被灵异侵蚀，被杨间用鬼眼印记强行救下，变成了一种半人半鬼的异类存在。她失去了大部分人类的情感，变得极度冷漠，但对杨间有着绝对的忠诚。她负责饲养和控制极其恐怖的“鬼童”，是杨间大后方最坚实的护盾。''},{name:''李阳'',desc:''代号【堵门鬼】。杨间小队的核心成员。原本是被卷入鬼邮局事件的绝望信使，被杨间救下后成为其最忠诚的下属。驾驭了“鬼开门”与“鬼堵门”的灵异拼图，为人稳重、极其冷静，在处理鬼邮局、鬼湖等各大S级事件中发挥了不可替代的巨大作用，最终成长为独当一面的顶尖驭鬼者。''},{name:''童倩'',desc:''代号【鬼脸】。极少数在残酷的灵异世界中依然保留着真善美与强烈正义感的驭鬼者。拥有两张诡异的笑脸与哭脸，能够通过笑声和哭声进行大范围的灵异袭击。在中山市事件中险些丧命，被杨间救下并招募进小队。虽然她的理念与冷酷的杨间经常冲突，但她代表了人类在绝境中不屈的道德底线。''}],captains:[{name:''李军'',desc:''代号【鬼火】。亚洲总部绝对忠诚的卫士，王小明教授最信任的人。浑身燃烧着惨绿色的鬼火，行事作风刚正不阿，永远冲在处理灵异事件的第一线。即便在S级鬼画事件中为了断后而战死，他也凭借着守护人类的强烈执念，被王小明改造成异类重新复活，化身灰烬中的不屈英魂，继续为总部燃尽最后一丝光热。''},{name:''卫景'',desc:''代号【鬼差】。李军的搭档，由王小明主导的禁忌实验中诞生的怪物。他融合了S级厉鬼“鬼差”的部分灵异，拥有无解的“压制其他厉鬼”的可怕能力（落单必死规律）。他失去了作为人类的绝大部分特征，变得比鬼还要像鬼，是总部最恐怖的战略级威慑力量，如同黑暗中无情的行刑者。''},{name:''柳三'',desc:''代号【纸人】。保命能力天下第一的队长。没有人知道他的本体究竟在哪里，也没有人见过他的真面目。他通过漫山遍野、诡异至极的黄纸人来行动和收集情报。每一个纸人看似脆弱，实则蕴含着恐怖的灵异。在无数次团灭级别的危机中，他总能依靠纸人替死全身而退，是情报获取与消耗战的大师。''},{name:''曹洋'',desc:''总部十二队长之一，行事极其低调但实力深不可测。驾驭了极其罕见的灵异力量。在S级鬼湖事件中，他是少数能在鬼湖深处存活并带出关键情报的人。在与国王组织的幽灵船战役中，他展现出了惊人的压制力，是一个平时不显山露水，但在绝境中绝对可靠的顶尖战力。''},{name:''李乐平'',desc:''代号【遗忘鬼】。大川市负责人。他驾驭的厉鬼极其特殊，连他自己都会遗忘自己的身份和存在。任何看到他、记住他的人，都会遭受遗忘鬼的无解袭击，记忆被强行抹除。他是一个没有过去、没有名字的幽灵，为了不波及他人，他孤身一人镇压着大川市的灵异，是孤独而悲壮的守望者。''}]};function renderRoster(containerId,data){const container=document.getElementById(containerId);data.forEach(char=>{const btn=document.createElement(''button'');btn.className=''roster-item clickable'';btn.innerText=char.name;btn.style.transform=`rotate(${Math.random()*10-5}deg) translateY(${Math.random()*10-5}px)`;btn.addEventListener(''click'',()=>openModal(`【绝密档案：${char.name}】`,`<p class="lore-text blood-highlight" style="font-size:1.3rem;">身份确认完毕。正在调取绝密卷宗...</p><p class="lore-text">${char.desc}</p>`));container.appendChild(btn);});}renderRoster(''roster-main'',rosterData.main);renderRoster(''roster-captains'',rosterData.captains);const cfgName=document.getElementById(''cfg-name'');const cfgGender=document.getElementById(''cfg-gender'');const cfgIdentity=document.getElementById(''cfg-identity'');const cfgPersonality=document.getElementById(''cfg-personality'');const cfgFaction=document.getElementById(''cfg-faction'');const cfgFactionCustom=document.getElementById(''cfg-faction-custom'');const cfgTimeChapter=document.getElementById(''cfg-time-chapter'');const cfgTimeNode=document.getElementById(''cfg-time-node'');const cfgLifeform=document.getElementById(''cfg-lifeform'');const cfgGhost=document.getElementById(''cfg-ghost'');const cfgDeath=document.getElementById(''cfg-death'');const cfgCost=document.getElementById(''cfg-cost'');const cfgPower=document.getElementById(''cfg-power'');const cfgBg=document.getElementById(''cfg-bg'');const ghostConfigArea=document.getElementById(''ghost-config-area'');const previewBox=document.getElementById(''preview-box'');chapters.forEach(chap=>{const opt=document.createElement(''option'');opt.value=chap.title;opt.innerText=chap.title;cfgTimeChapter.appendChild(opt);});function updateNodes(){const selected=cfgTimeChapter.value;const chap=chapters.find(c=>c.title===selected);cfgTimeNode.innerHTML='''';if(chap&&chap.nodes){chap.nodes.forEach(node=>{const opt=document.createElement(''option'');opt.value=node;opt.innerText=node;cfgTimeNode.appendChild(opt);});}updatePreview();}cfgTimeChapter.addEventListener(''change'',updateNodes);cfgLifeform.addEventListener(''change'',(e)=>{if(e.target.value===''普通人''){ghostConfigArea.style.display=''none'';}else{ghostConfigArea.style.display=''block'';}updatePreview();});cfgFaction.addEventListener(''change'',(e)=>{if(e.target.value===''custom''){cfgFactionCustom.style.display=''block'';}else{cfgFactionCustom.style.display=''none'';}updatePreview();});const inputs=[cfgName,cfgGender,cfgIdentity,cfgPersonality,cfgFaction,cfgFactionCustom,cfgTimeNode,cfgLifeform,cfgGhost,cfgDeath,cfgCost,cfgPower,cfgBg];inputs.forEach(input=>input.addEventListener(''input'',updatePreview));function updatePreview(){const name=cfgName.value.trim()||''[未命名]'';const gender=cfgGender.value;const identity=cfgIdentity.value.trim()||''[未知社会身份]'';const personality=cfgPersonality.value.trim()||''[性格未鉴定]'';const faction=cfgFaction.value===''custom''%s(cfgFactionCustom.value.trim()||''[未知势力]''):cfgFaction.value;const timeChapter=cfgTimeChapter.value;const timeNode=cfgTimeNode.value;const lifeform=cfgLifeform.value;const bg=cfgBg.value.trim()||''暂无记录...'';let ghostText='''';if(lifeform!==''普通人''){const ghost=cfgGhost.value.trim()||''[尚未记录灵异拼图]'';const death=cfgDeath.value.trim()||''[尚未探明即死规律]'';const cost=cfgCost.value.trim()||''[尚未记录复苏代价]'';const power=cfgPower.value;ghostText=`\n【灵异拼图与境界】\n实力评级：${power}\n驾驭厉鬼：${ghost}\n即死条件(规律)：${death}\n复苏代价(反噬)：${cost}\n-------------------------`;}const text=`=========================\n【神秘复苏 - 绝密档案】\n=========================\n代号/姓名：${name}\n性别：${gender}\n社会身份：${identity}\n性格评估：${personality}\n生命形态：${lifeform}\n所属势力：${faction}\n介入篇章：${timeChapter}\n介入节点：${timeNode}\n-------------------------${ghostText}\n【背景故事与执念】\n${bg}\n=========================`;previewBox.innerText=text;}updateNodes();const btnSubmit=document.getElementById(''btn-submit'');const copyModal=document.getElementById(''copy-modal'');const btnCloseModal=document.getElementById(''btn-close-modal'');btnSubmit.addEventListener(''click'',()=>{const textToCopy=previewBox.innerText;const textarea=document.createElement(''textarea'');textarea.value=textToCopy;textarea.style.position=''fixed'';textarea.style.opacity=''0'';document.body.appendChild(textarea);textarea.select();try{document.execCommand(''copy'');copyModal.style.display=''flex'';setTimeout(()=>{copyModal.style.opacity=''1'';},10);}catch(err){alert(''复制失败，请手动选择预览框内容复制。'');}finally{document.body.removeChild(textarea);}});btnCloseModal.addEventListener(''click'',()=>{copyModal.style.opacity=''0'';setTimeout(()=>{copyModal.style.display=''none'';},300);});</script></body></html>', '玄幻', '2026-09-16 11:22:22', '2026-09-16 11:22:22', '', '', '[]', '') ON CONFLICT (id) DO NOTHING;
INSERT INTO stories (id, title, badge, cover_icon, cover_title, cover_subtitle, logo, theme_color, btn_gradient, handbook_json, roles_json, scenes_json, styles_json, first_turn_demo_json, custom_css, custom_html, category, created_at, updated_at, system_prompt, status_template, lorebook_json, post_history_instructions) VALUES ('b64f6c60-f3b0-438b-91ef-51362dbb4ce4', '爸爸我下面好痒帮我磨一磨吧。可爱女儿竟然用我晨勃的鸡巴止痒', '晨勃禁断 · 娇憨反差', '🛌', '晨勃止痒女儿', '天真娇憨女儿陈小涵 · 晨勃磨蹭', '🛌', '#fd79a8', 'linear-gradient(135deg, #fd79a8 0%, #e84393 100%)', '{"desc": "女儿胆小怕黑平时常赖在主卧大床睡。某个清晨妻子起床洗漱，主角还在赖床，下身晨勃高高挺立。迷糊间感觉下身有柔软温热磨蹭，睁眼一看，16岁的可爱女儿正笨拙地撅着屁股用下面磨蹭鸡巴止痒...天真娇憨下的禁忌心跳。", "author": "AI风月精选"}', '[{"name": "陈小涵", "role": "16岁可爱女儿 (高一在读 / 158cm / A罩杯)", "desc": "扎着双马尾，皮肤白嫩娇软，性格纯真俏皮、天真大胆。对异性的身体构造充满好奇，由于胆小怕黑经常溜进父母被窝。大早晨趁母亲在厨房洗漱，隔着薄薄的草莓纯棉内裤主动骑坐在父亲晨勃的硬肉棒上前后磨蹭止痒。"}]', '[{"title": "主卧大床 · 清晨被窝内", "desc": "掀开棉被一角，草莓内裤在硬挺肉棒上笨拙起伏磨蹭的温热禁忌"}, {"title": "客厅洗手间门前 · 惊险推拉", "desc": "母亲厨房走动的脚步声近在咫尺，被按在墙角屏住呼吸的私密触碰"}, {"title": "女儿卧室书桌 · 课后辅导", "desc": "百褶裙摆下大腿内侧的黏腻水渍与悄悄探入裙底的大手"}]', '{}', '{"location": "主卧大床 · 清晨初醒被窝内", "story": "清晨的阳光透过百叶窗缝隙，在地毯上洒下温暖的金色光斑。门外隐约传来妻子洗漱与厨房烧水的声音。\n你还在被窝里迷迷糊糊地赖床，男性晨间正常的生理冲动让你胯下一柱擎天，将轻薄的棉被高高顶起。半梦半醒间，下身却传来一阵极其微妙而异样的温热触感——像是有什么柔软轻盈的小东西，正笨拙而缓慢地在敏感的部位前后磨蹭。\n你猛然睁开眼，被子不知何时已被掀开了一角。16岁的独生女儿陈小涵正穿着一条粉色草莓纯棉小睡裤，撅着娇小圆润的屁股，隔着薄薄的棉布将双腿间娇嫩的花径死死压在你晨勃硬挺的肉棒上微微扭动。\n撞见你骤然清醒的目光，小丫头不仅没有害怕逃开，那张未褪尽婴儿肥的清秀小脸上反而泛起一抹天真的绯红，两根细嫩的手指扯了扯睡裤边缘，声音带着软糯的晨起鼻音：“爸爸……你醒啦？你别动嘛……我下面刚才突然好痒好难受……刚好看到你这里竖起来一根热热的大硬棒子，想着拿来磨一磨止痒……好舒服哦，爸爸你继续睡，我自己动就好了……”", "branches": [{"tag": "A", "title": "倒吸一口凉气，假装严厉斥责但身体却僵硬不敢乱动", "desc": "口头拿出做父亲的威严假正经申斥，身体却被她柔软的小屁股磨得阵阵发麻【假正经责难: 口头申斥打破伦理，暗中享受温热摩擦】"}, {"tag": "B", "title": "伸手按住她纤细的腰肢，温柔地将肉棒隔着裤子向她更深处顶了顶", "desc": "顺水推舟宠溺回应她的止痒请求，挺起腰肢让晨勃前端狠狠顶住她娇嫩的花核【宠溺纵容: 顺应天真止痒，逐步打破父女身体防线】"}, {"tag": "C", "title": "提醒门外妈妈还在厨房，压低嗓音将手探入她粉色睡裤边缘", "desc": "借着母亲随时可能进来的刺激紧张感，将指尖悄悄滑入她温热微潮的裤腰内部【紧张刺激: 厨房水声与被窝偷情，触碰娇嫩湿润边缘】"}, {"tag": "D", "title": "翻身将她抱进怀里，用大手揉按她平坦小腹与敏感大腿内侧", "desc": "以帮她彻底消除奇痒为名，大手滑向她平坦光滑的小腹与细嫩大腿根部【贴身温存: 假借检查止痒名义，全面探索少女敏感点】"}]}', '', '<!DOCTYPE html>
<html lang="zh-CN">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>幻境织网者 - 角色与剧情设定生成器</title>
    <link href="https://fonts.googleapis.com/css2%sfamily=Noto+Serif+SC:wght@400;600;900&family=Noto+Sans+SC:wght@300;400;500;700&display=swap" rel="stylesheet">
    <style>
        :root {
            --bg-color: #fff8f0;
            --card-bg: #ffffff;
            --card-border: #ffe9d6;
            --accent-primary: #ff6b9d;
            --accent-secondary: #a66cff;
            --accent-highlight: #4d96ff;
            --accent-sun: #ffc53d;
            --accent-mint: #52b788;
            --text-main: #5a4a42;
            --text-sub: #9c8f86;
            --input-bg: #fffbf5;
            --input-border: #ffe6d0;
            --radius-md: 14px;
            --radius-lg: 24px;
            --shadow-soft: 0 10px 30px rgba(255, 175, 130, 0.18);
        }

        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }

        body {
            font-family: ''Noto Sans SC'', sans-serif;
            background-color: var(--bg-color);
            color: var(--text-main);
            line-height: 1.7;
            min-height: 100vh;
            overflow-x: hidden;
        }

        .container {
            max-width: 1100px;
            margin: 0 auto;
            padding: 40px 20px;
        }

        header {
            text-align: center;
            margin-bottom: 40px;
        }

        header h1 {
            font-family: ''Noto Serif SC'', serif;
            font-size: 2.9em;
            font-weight: 900;
            background: linear-gradient(135deg, #ff7a5c 0%, #ff6b9d 50%, #a66cff 100%);
            -webkit-background-clip: text;
            -webkit-text-fill-color: transparent;
            margin-bottom: 12px;
            letter-spacing: 3px;
        }

        header p {
            color: var(--text-sub);
            font-size: 1.1em;
            font-weight: 500;
        }

        .main-card {
            background: var(--card-bg);
            border: 2px solid var(--card-border);
            border-radius: var(--radius-lg);
            padding: 35px;
            box-shadow: var(--shadow-soft);
            margin-bottom: 30px;
        }

        .section-title {
            display: flex;
            align-items: center;
            gap: 12px;
            font-family: ''Noto Serif SC'', serif;
            font-size: 1.45em;
            font-weight: 900;
            color: #5a4a42;
            margin-bottom: 22px;
        }

        .title-icon {
            display: inline-flex;
            align-items: center;
            justify-content: center;
            width: 46px;
            height: 46px;
            border-radius: 15px;
            font-size: 1.25em;
            flex-shrink: 0;
            box-shadow: 0 4px 12px rgba(255, 150, 120, 0.22);
        }
        .title-icon.pink { background: linear-gradient(135deg, #ffd3e0, #ffe9f0); }
        .title-icon.blue { background: linear-gradient(135deg, #cde8ff, #e8f4ff); }
        .title-icon.sun { background: linear-gradient(135deg, #fff3cd, #ffe9b3); }

        .form-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
            gap: 18px;
            margin-bottom: 22px;
        }

        .form-group {
            display: flex;
            flex-direction: column;
            gap: 6px;
        }

        .form-group.full-width {
            grid-column: 1 / -1;
        }

        label {
            font-size: 0.95em;
            font-weight: 600;
            color: #6b5b52;
        }

        label span {
            color: var(--accent-secondary);
            font-size: 0.82em;
            font-weight: 500;
            margin-left: 4px;
        }

        input, textarea {
            background-color: var(--input-bg);
            border: 2px solid var(--input-border);
            border-radius: var(--radius-md);
            padding: 10px 12px;
            color: var(--text-main);
            font-family: inherit;
            font-size: 0.95em;
            transition: all 0.25s ease;
        }

        input::placeholder, textarea::placeholder {
            color: #bfb2a8;
            opacity: 1;
        }

        input:focus, textarea:focus {
            outline: none;
            border-color: var(--accent-primary);
            box-shadow: 0 0 0 4px rgba(255, 107, 157, 0.14);
            background-color: #ffffff;
        }

        textarea {
            resize: vertical;
            min-height: 70px;
        }

        /* 角色卡片 */
        .character-card {
            background: var(--card-bg);
            border: 2px solid var(--card-border);
            border-radius: 18px;
            padding: 16px 18px;
            box-shadow: 0 6px 18px rgba(255, 175, 130, 0.12);
            margin-bottom: 14px;
            transition: box-shadow 0.3s ease, transform 0.3s ease;
        }
        .character-card:hover {
            transform: translateY(-2px);
            box-shadow: 0 14px 30px rgba(255, 175, 130, 0.22);
        }

        .character-header {
            display: flex;
            justify-content: space-between;
            align-items: center;
            margin-bottom: 10px;
        }

        .character-card .form-grid {
            grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
            gap: 12px;
            margin-bottom: 0;
        }

        .character-badge {
            font-size: 0.95em;
            font-weight: 800;
            color: #ffffff;
            background: linear-gradient(135deg, #ff6b9d, #ff9a5c);
            padding: 4px 14px;
            border-radius: 999px;
            box-shadow: 0 4px 10px rgba(255, 107, 157, 0.3);
        }

        .btn-remove-character {
            border: 2px solid #ffd3d3;
            background: #fff5f5;
            color: #e57373;
            padding: 4px 12px;
            border-radius: 999px;
            font-weight: 600;
            font-family: inherit;
            font-size: 0.82em;
            cursor: pointer;
            transition: all 0.2s;
        }
        .btn-remove-character:hover {
            background: #e57373;
            color: #ffffff;
            border-color: #e57373;
        }

        .btn-add-character {
            width: 100%;
            padding: 10px;
            border: 2px dashed #9be0b2;
            background: #f4fff7;
            color: #2f9e63;
            font-size: 0.95em;
            font-weight: 700;
            font-family: inherit;
            border-radius: 14px;
            cursor: pointer;
            transition: all 0.25s;
        }
        .btn-add-character:hover {
            background: #9be0b2;
            color: #ffffff;
            transform: translateY(-2px);
        }

        .btn-generate {
            display: flex;
            align-items: center;
            justify-content: center;
            width: 100%;
            padding: 17px;
            font-size: 1.2em;
            font-weight: 800;
            color: #ffffff;
            background: linear-gradient(135deg, #ff9a5c 0%, #ff6b9d 55%, #a66cff 120%);
            border: none;
            border-radius: 999px;
            cursor: pointer;
            transition: all 0.3s ease;
            box-shadow: 0 8px 24px rgba(255, 107, 157, 0.4);
            font-family: inherit;
        }

        .btn-generate:hover {
            transform: translateY(-3px);
            box-shadow: 0 12px 30px rgba(255, 107, 157, 0.5);
        }

        .btn-row {
            display: flex;
            flex-direction: column;
            gap: 14px;
            margin-top: 22px;
        }

        .btn-quick {
            width: 100%;
            padding: 15px;
            font-size: 1.05em;
            font-weight: 700;
            color: #2f9e63;
            background: linear-gradient(135deg, #eafaf0, #d5f5e0);
            border: 2px solid #9be0b2;
            border-radius: 999px;
            cursor: pointer;
            font-family: inherit;
            transition: all 0.25s;
        }

        .btn-quick:hover {
            background: linear-gradient(135deg, #9be0b2, #6bcb77);
            color: #ffffff;
            transform: translateY(-2px);
        }

        /* 使用说明 */
        .flow-hint {
            background: linear-gradient(135deg, #fff3e0, #ffe9f0);
            border: 2px dashed #ffc9d6;
            border-radius: var(--radius-md);
            padding: 12px 16px;
            font-size: 0.95em;
            color: #8a5a52;
            margin-bottom: 24px;
            line-height: 1.7;
        }
        .flow-hint b { color: #ff6b9d; }

        /* 可点选玩法面板 */
        .options-panel {
            background: #fffbf5;
            border: 2px solid #ffe6d0;
            border-radius: 18px;
            padding: 18px 20px;
            margin-bottom: 26px;
        }
        .options-header {
            display: flex;
            justify-content: space-between;
            align-items: center;
            margin-bottom: 14px;
        }
        .options-title {
            font-weight: 800;
            font-size: 1.1em;
            color: #5a4a42;
        }
        .btn-reset {
            border: 2px solid #c9c2f5;
            background: #f4f2ff;
            color: #7c6ee8;
            padding: 5px 14px;
            border-radius: 999px;
            font-weight: 700;
            font-family: inherit;
            font-size: 0.85em;
            cursor: pointer;
            transition: all 0.2s;
        }
        .btn-reset:hover {
            background: #a66cff;
            color: #ffffff;
            border-color: #a66cff;
        }
        .option-group { margin-bottom: 14px; }
        .option-group:last-child { margin-bottom: 0; }
        .option-group-label {
            font-size: 0.9em;
            font-weight: 700;
            color: #6b5b52;
            margin-bottom: 8px;
        }
        .option-chips {
            display: flex;
            flex-wrap: wrap;
            gap: 10px;
        }
        .chip {
            border: 2px solid #ffd3b3;
            background: #fff7ef;
            color: #b07b5a;
            padding: 6px 16px;
            border-radius: 999px;
            font-size: 0.92em;
            font-weight: 600;
            font-family: inherit;
            cursor: pointer;
            transition: all 0.2s;
        }
        .chip:hover { transform: translateY(-1px); }
        .chip.active {
            background: linear-gradient(135deg, #ff9a5c, #ff6b9d);
            color: #ffffff;
            border-color: transparent;
            box-shadow: 0 4px 12px rgba(255, 107, 157, 0.35);
        }
        .option-desc {
            margin-top: 8px;
            font-size: 0.82em;
            color: #b39a90;
        }

        /* 模态弹窗 */
        .modal {
            display: none;
            position: fixed;
            z-index: 1000;
            left: 0;
            top: 0;
            width: 100%;
            height: 100%;
            background-color: rgba(95, 70, 60, 0.35);
            backdrop-filter: blur(6px);
            justify-content: center;
            align-items: center;
            padding: 20px;
        }

        .modal-content {
            background-color: #ffffff;
            border: 2px solid #ffe6d0;
            border-radius: var(--radius-lg);
            width: 100%;
            max-width: 750px;
            max-height: 85vh;
            display: flex;
            flex-direction: column;
            box-shadow: 0 20px 60px rgba(255, 120, 90, 0.28);
            animation: modalFadeIn 0.3s ease;
        }

        @keyframes modalFadeIn {
            from { opacity: 0; transform: scale(0.95); }
            to { opacity: 1; transform: scale(1); }
        }

        .modal-header {
            padding: 20px 25px;
            border-bottom: 2px solid #ffefd2;
            display: flex;
            justify-content: space-between;
            align-items: center;
        }

        .modal-header h3 {
            color: var(--accent-primary);
            font-size: 1.3em;
            font-weight: 800;
        }

        .close-btn {
            background: none;
            border: none;
            color: var(--text-sub);
            font-size: 1.5em;
            cursor: pointer;
            transition: color 0.2s;
        }

        .close-btn:hover {
            color: #ff6b9d;
        }

        .modal-body {
            padding: 20px 25px;
            overflow-y: auto;
            flex: 1;
        }

        #prompt-output {
            width: 100%;
            min-height: 320px;
            background-color: #fff7ef;
            border: 2px solid #ffe6d0;
            border-radius: var(--radius-md);
            padding: 15px;
            color: #5a4a42;
            font-family: ''Courier New'', Courier, monospace;
            font-size: 0.9em;
            line-height: 1.6;
            white-space: pre-wrap;
            word-break: break-all;
            resize: vertical;
            outline: none;
        }
        #prompt-output:focus {
            border-color: var(--accent-primary);
            box-shadow: 0 0 0 4px rgba(255, 107, 157, 0.14);
        }

        .modal-footer {
            padding: 15px 25px;
            border-top: 2px solid #ffefd2;
            display: flex;
            justify-content: flex-end;
            gap: 15px;
        }

        .btn-copy {
            background: linear-gradient(135deg, #52b788 0%, #2f9e63 100%);
            color: #ffffff;
            border: none;
            padding: 10px 24px;
            border-radius: 999px;
            font-weight: 700;
            font-family: inherit;
            font-size: 0.95em;
            cursor: pointer;
            transition: all 0.2s;
        }

        .btn-copy:hover {
            background: linear-gradient(135deg, #2f9e63 0%, #1f8a54 100%);
            transform: translateY(-2px);
        }

        /* 底部与推广区域 */
        .footer {
            margin-top: 40px;
            text-align: center;
            border-top: 2px dashed #ffe6d0;
            padding-top: 25px;
            color: var(--text-sub);
            font-size: 0.95em;
        }

        .footer a {
            color: var(--accent-primary);
            text-decoration: none;
            font-weight: 700;
            transition: all 0.3s;
        }

        .footer a:hover {
            color: var(--accent-secondary);
            text-decoration: underline;
        }

    /* ========== 移动端适配 ========== */
        @media (max-width: 768px) {
            .container {
                padding: 20px 14px;
            }

            header h1 {
                font-size: 1.5em;
                letter-spacing: 1px;
                line-height: 1.4;
                margin-bottom: 8px;
            }

            header p {
                font-size: 0.95em;
            }

            .main-card {
                padding: 20px 14px;
                border-radius: 18px;
                margin-bottom: 20px;
            }

            .section-title {
                font-size: 1.2em;
                gap: 10px;
                margin-bottom: 16px;
            }

            .title-icon {
                width: 38px;
                height: 38px;
                font-size: 1.05em;
                border-radius: 12px;
            }

            .form-grid {
                gap: 14px;
                margin-bottom: 16px;
            }

            input, textarea {
                font-size: 1em;
                -webkit-appearance: none;
                appearance: none;
            }

            label {
                font-size: 0.92em;
            }

            .character-card {
                padding: 14px 12px;
                margin-bottom: 14px;
            }

            .character-card .form-grid {
                grid-template-columns: 1fr;
                gap: 14px;
            }

            .character-badge {
                font-size: 0.88em;
                padding: 4px 12px;
            }

            .btn-remove-character {
                padding: 4px 10px;
                font-size: 0.78em;
            }

            .btn-add-character {
                font-size: 0.92em;
            }

            .flow-hint {
                font-size: 0.92em;
                padding: 12px 14px;
            }

            .options-panel {
                padding: 14px;
            }

            .options-header {
                gap: 10px;
            }

            .options-title {
                font-size: 1em;
            }

            .option-chips {
                gap: 8px;
            }

            .chip {
                font-size: 0.88em;
                padding: 6px 13px;
            }

            .btn-generate {
                padding: 14px;
                font-size: 1.05em;
            }

            .btn-quick {
                padding: 13px;
                font-size: 1em;
            }

            .modal {
                padding: 12px;
                align-items: flex-end;
            }

            .modal-content {
                max-height: 92vh;
                border-radius: 20px 20px 0 0;
            }

            .modal-header {
                padding: 16px 18px;
            }

            .modal-header h3 {
                font-size: 1.15em;
            }

            .modal-body {
                padding: 16px 18px;
            }

            .modal-footer {
                padding: 12px 18px;
            }

            .btn-copy {
                width: 100%;
                text-align: center;
            }

