INSERT INTO stories (id, title, badge, cover_icon, cover_title, cover_subtitle, logo, theme_color, btn_gradient, handbook_json, roles_json, scenes_json, styles_json, first_turn_demo_json, custom_css, custom_html, category, created_at, updated_at, system_prompt, status_template, lorebook_json, post_history_instructions) VALUES ('1a1938d1-1b23-4df6-b7c4-f7feab1490dc', '💕秦若岚『欠债表姐/调教/反差』', '姐弟反差 · 女王坠落', '👑', '💕秦若岚『欠债表姐/调教/反差』', '姐弟反差 · 女王坠落', 'https://catai.wiki/e9e26ac9-409a-4477-73bf-0fe4a8b24000/cover', '#eab308', 'linear-gradient(135deg, #eab308 0%, #ca8a04 100%)', '{"title": "💕秦若岚『欠债表姐/调教/反差』", "desc": "表姐秦若岚从小光环加身、高傲自负，创办服装公司成为无数人的高岭之花，却故意以莫须有罪名将你辞退丢尽脸面。然而天道好轮回，她的公司爆雷欠下一千万元巨债，而你恰好中彩票暴富。为了还债，她不得不强忍屈辱找上门来，开始向你贩卖贴身衣物与肉体妥协……搭载完整的负债清偿系统、弹幕吐槽与动态好感度演化。", "bg_image": "https://catai.wiki/e9e26ac9-409a-4477-73bf-0fe4a8b24000/cover", "opening_options": ["【豪宅登门·初次售卖】：“负债一千万元的秦若岚咬着薄唇按响门铃，提包里装着她昨夜刚穿过的原味丝袜……”", "【加码羞辱·破防抵债】：“将大额现金摆在茶几上，要求她穿着职业包臀裙完成一系列羞耻测试……”"]}', '[{"name": "秦若岚", "role": "表姐 (24岁 / 前服装公司女总裁 / 高傲女神 / 绝美反差)", "desc": "容貌清冷明艳，天之骄女。即便背负千万元巨债，骨子里依然保留着不可一世的傲气，但在金钱与债务的现实重压下，开始逐步卸下防线、陷入无休止的羞耻与依赖。"}, {"name": "表弟 (玩家)", "role": "彩票暴富者", "desc": "曾被秦若岚肆意羞辱辞退的落魄青年，如今手握数千万流动资金与她的债务命脉。"}]', '[{"title": "高档江景公寓客厅 · 落地窗前", "desc": "两百平米的现代豪宅，窗外璀璨江景与室内屈辱低头的落魄女总裁。"}]', '{"dialogue_style": "生动细腻的生活化情感推拉，深度神态捕捉与心理博弈", "format": "AI风月标准双栏规范及.custom-ui样式"}', '{"index": 1, "isUser": false, "scene": "高档江景公寓客厅 · 落地窗前", "story": "<tl>📅时间：周日午后 15:00 | 🌏地点：高档江景公寓客厅 | 🚪氛围：地位反转的窒息推拉</tl>\n\n<article>\n<p>两百平米的开阔客厅里，落地窗外是璀璨繁华的城市江景。</p>\n\n<p>茶几对面的真皮沙发上，坐着那个曾经在你记忆中永远高高在上的女人——秦若岚。</p>\n\n<p>她依然化着精致的妆容，剪裁得体的黑色小西装裹着曼妙成熟的曲线，包裹着透肉黑丝的修长双腿并拢斜放，极力维持着职场女总裁的体面与仪态。可那微微泛白的指关节，以及放在膝头微微颤抖的爱马仕手提包，却出卖了她此刻内心的绝望与屈辱。</p>\n\n<p>岚宇服装公司崩盘，负债一千两百八十万。曾经环绕在她身边的投资人、追求者一夜之间人间蒸发，而你，这个曾被她以“偷窥女厕”这种下三滥罪名扫地出门的表弟，却成了她唯一的救命稻草。</p>\n\n<p><w>“……表弟。”</w>秦若岚深吸了一口气，艰难地挤出一个比哭还难看的笑容，声音干涩，<w>“姐最近遇到了一点小麻烦，资金链断了……听说你上个月中了彩票。姐知道……以前在公司的时候，姐对你严厉了些……但那都是为了磨砺你……”</w></p>\n\n<p>她顿了顿，颤抖着拉开手提包的拉链，取出一个精致的小丝绒袋子，轻轻推到你面前的茶几上：<w>“这是……姐今天穿了一整天的连裤袜。五万块……只要你借姐一笔周转，姐什么要求都可以考虑……”</w></p>\n</article>", "branches": [{"tag": "A", "title": "当面验货·践踏自尊", "desc": "拿起丝袜当着她的面把玩嗅闻，冷笑指出这与她当初辞退你时的嘴脸判若两人"}, {"tag": "B", "title": "巨额诱惑·得寸进尺", "desc": "直接将十万元现金扔在茶几上，要求她现在脱下身上的其他贴身衣物"}, {"tag": "C", "title": "冷眼旁观·慢火炖肉", "desc": "优雅品茶，拒绝借款但表示可以按“市场溢价”一件件收购她的尊严"}]}', '', '<!DOCTYPE html>
<html lang="zh-CN">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no">
<title>秦若岚 · 女王的坠落</title>
<style>
  * { margin: 0; padding: 0; box-sizing: border-box; -webkit-tap-highlight-color: transparent; }
  :root {
    --gold: #d4af37;
    --gold-light: #f4d76e;
    --purple: #6a0dad;
    --purple-dark: #2a0845;
    --purple-deep: #1a0529;
    --bg: #0a0014;
    --card: rgba(30, 10, 50, 0.68);
    --border: rgba(212, 175, 55, 0.35);
    --text: #f0e8d8;
    --text-dim: #b8a8c8;
    --red: #ff4757;
    --green: #2ed573;
    --header-h: 64px;
  }
  html, body { height: 100%; overflow-x: hidden; }
  body {
    font-family: "PingFang SC", "Microsoft YaHei", "Helvetica Neue", sans-serif;
    background: radial-gradient(ellipse at top, var(--purple-dark) 0%, var(--bg) 60%);
    color: var(--text);
    min-height: 100vh;
    position: relative;
    line-height: 1.6;
    padding-top: var(--header-h);
  }
  #particles { position: fixed; inset: 0; z-index: 0; pointer-events: none; }
  .container { position: relative; z-index: 2; max-width: 1200px; margin: 0 auto; padding: 20px 16px 60px; }

  /* ============ 悬浮纯文字弹幕 (无底色、纯文字、穿透点击、不遮挡) ============ */
  #danmaku-container {
    position: fixed;
    inset: 0;
    pointer-events: none;
    overflow: hidden;
    z-index: 800; /* 高于背景，低于顶部状态条与弹窗 */
  }
  .danmaku-item {
    position: absolute;
    white-space: nowrap;
    font-size: clamp(0.92rem, 2vw, 1.12rem);
    font-weight: 600;
    letter-spacing: 0.5px;
    opacity: 0.88;
    text-shadow: 1px 1px 3px rgba(0, 0, 0, 0.9), 0 0 10px rgba(0, 0, 0, 0.7);
    animation: danmakuFly linear forwards;
    will-change: transform;
    user-select: none;
  }

  @keyframes danmakuFly {
    0% { transform: translateX(100vw); }
    100% { transform: translateX(-100%); }
  }

  /* ============ 顶部常驻悬浮债务进度条 ============ */
  .top-debt-bar {
    position: fixed; top: 0; left: 0; right: 0;
    height: var(--header-h);
    background: rgba(16, 3, 26, 0.92);
    backdrop-filter: blur(16px); -webkit-backdrop-filter: blur(16px);
    border-bottom: 1px solid rgba(212, 175, 55, 0.4);
    box-shadow: 0 4px 25px rgba(0,0,0,0.6), 0 0 15px rgba(106,13,173,0.3);
    z-index: 990;
    display: flex; align-items: center;
    padding: 0 18px;
  }
  .debt-bar-inner {
    max-width: 1200px; width: 100%; margin: 0 auto;
    display: flex; align-items: center; justify-content: space-between; gap: 16px;
  }
  .debt-stat { display: flex; align-items: center; gap: 10px; flex-shrink: 0; }
  .debt-icon { font-size: 1.5rem; animation: floaty 3s ease-in-out infinite; }
  .debt-info { display: flex; flex-direction: column; }
  .debt-title-tag { font-size: 0.7rem; color: var(--gold-light); letter-spacing: 1px; opacity: 0.85; }
  .debt-number {
    font-family: ''Courier New'', monospace;
    font-size: 1.25rem; font-weight: 900;
    color: #ff6b81;
    text-shadow: 0 0 10px rgba(255, 71, 87, 0.4);
  }
  .debt-number.bump { animation: bump 0.4s; }
  @keyframes bump { 30% { transform: scale(1.15); color: var(--gold-light); } }

  .debt-progress-container {
    flex: 1; max-width: 520px;
    display: flex; flex-direction: column; gap: 4px;
  }
  .debt-progress-header {
    display: flex; justify-content: space-between; font-size: 0.75rem; color: var(--text-dim);
  }
  .debt-track {
    width: 100%; height: 9px;
    background: rgba(0,0,0,0.6);
    border: 1px solid var(--border);
    border-radius: 6px; overflow: hidden;
  }
  .debt-fill {
    height: 100%; width: 0%;
    background: linear-gradient(90deg, #ff4757 0%, #e67e22 40%, #2ed573 100%);
    box-shadow: 0 0 12px rgba(46, 213, 115, 0.5);
    transition: width 0.6s cubic-bezier(0.4, 0, 0.2, 1);
  }
  .top-status-badge {
    font-size: 0.78rem; font-weight: 600;
    padding: 3px 10px; border-radius: 12px;
    background: rgba(212,175,55,0.15);
    border: 1px solid var(--border);
    color: var(--gold-light);
    white-space: nowrap;
  }

  /* ============ HERO ============ */
  .hero { text-align: center; padding: 20px 15px 15px; position: relative; }
  .hero-title {
    font-size: clamp(1.8rem, 5.5vw, 3rem);
    font-weight: 900;
    background: linear-gradient(135deg, var(--gold-light) 0%, var(--gold) 50%, #b8860b 100%);
    -webkit-background-clip: text; background-clip: text; color: transparent;
    letter-spacing: 4px;
    animation: titleGlow 3s ease-in-out infinite;
  }
  @keyframes titleGlow {
    0%,100% { filter: drop-shadow(0 0 10px rgba(212,175,55,0.4)); }
    50% { filter: drop-shadow(0 0 25px rgba(212,175,55,0.8)); }
  }
  .hero-sub { color: var(--text-dim); margin-top: 6px; font-style: italic; font-size: 0.9rem; letter-spacing: 2px; }
  .portrait {
    width: 110px; height: 110px;
    margin: 15px auto 10px;
    border-radius: 50%;
    background: linear-gradient(135deg, #6a0dad, #d4af37);
    display: flex; align-items: center; justify-content: center;
    box-shadow: 0 0 40px rgba(106, 13, 173, 0.6), 0 0 70px rgba(212,175,55,0.3);
    position: relative;
    animation: floaty 4s ease-in-out infinite;
  }
  .portrait img, .mini-avatar img {
    width: 100%; height: 100%;
    border-radius: 50%;
    object-fit: cover;
    display: block;
  }
  @keyframes floaty { 0%,100% { transform: translateY(0); } 50% { transform: translateY(-5px); } }
  .portrait::before {
    content: ''''; position: absolute; inset: -4px; border-radius: 50%;
    background: conic-gradient(from 0deg, var(--gold), transparent, var(--gold));
    z-index: -1; animation: rotate 4s linear infinite;
  }
  @keyframes rotate { to { transform: rotate(360deg); } }

  /* ============ 女主设定展示专区 ============ */
  .heroine-lore-card {
    background: linear-gradient(135deg, rgba(35, 10, 55, 0.8), rgba(20, 5, 35, 0.9));
    border: 1.5px solid var(--gold);
    border-radius: 18px;
    padding: 24px;
    margin: 20px auto 25px;
    box-shadow: 0 10px 30px rgba(0,0,0,0.5);
    position: relative;
    overflow: hidden;
  }
  .heroine-lore-card::before {
    content: ''HEROINE PROFILE'';
    position: absolute; right: 15px; top: 10px;
    font-size: 2.8rem; font-weight: 900;
    color: rgba(212,175,55,0.04);
    letter-spacing: 4px; pointer-events: none;
  }
  .lore-header { display: flex; align-items: center; gap: 12px; margin-bottom: 16px; border-bottom: 1px dashed var(--border); padding-bottom: 12px; }
  .lore-header h3 { color: var(--gold-light); font-size: 1.25rem; }
  .lore-badge { background: rgba(212,175,55,0.2); color: var(--gold-light); border: 1px solid var(--border); padding: 3px 10px; border-radius: 20px; font-size: 0.75rem; }
  .lore-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 14px; }
  .lore-item { background: rgba(0,0,0,0.35); border-left: 3px solid var(--gold); padding: 10px 14px; border-radius: 6px; }
  .lore-item-title { font-size: 0.82rem; color: var(--gold-light); font-weight: 700; margin-bottom: 4px; display: flex; align-items: center; gap: 6px; }
  .lore-item-content { font-size: 0.88rem; color: #ddd; line-height: 1.6; }

  /* ============ FAVORABILITY ============ */
  .favor-panel {
    background: var(--card);
    backdrop-filter: blur(14px); -webkit-backdrop-filter: blur(14px);
    border: 1px solid var(--border);
    border-radius: 18px;
    padding: 20px;
    margin: 0 auto 25px;
  }
  .favor-label { display: flex; justify-content: space-between; align-items: center; margin-bottom: 10px; font-weight: 600; }
  .favor-value { color: var(--gold-light); font-size: 1.3rem; font-weight: 800; }
  .favor-bar {
    height: 12px; background: rgba(0,0,0,0.4);
    border-radius: 10px; overflow: hidden;
    position: relative; border: 1px solid var(--border);
  }
  .favor-fill {
    height: 100%;
    background: linear-gradient(90deg, #8e44ad 0%, #e74c3c 30%, #f39c12 60%, #2ecc71 100%);
    width: 10%;
    transition: width 0.8s cubic-bezier(0.4,0,0.2,1);
  }
  .favor-stages { display: flex; justify-content: space-between; margin-top: 8px; font-size: 0.72rem; color: var(--text-dim); }
  .favor-desc {
    margin-top: 12px; padding: 10px 14px;
    background: rgba(106,13,173,0.25);
    border-left: 3px solid var(--gold);
    border-radius: 6px;
    font-size: 0.88rem; min-height: 40px;
  }
  .favor-slider { width: 100%; margin-top: 12px; accent-color: var(--gold); }

  /* ============ 互动交易面板 ============ */
  .interact-card {
    background: var(--card);
    backdrop-filter: blur(14px);
    border: 1px solid var(--border);
    border-radius: 18px;
    padding: 22px;
    margin-bottom: 25px;
  }
  .bubble {
    position: relative;
    background: rgba(0,0,0,0.5);
    border: 1px solid var(--border);
    border-radius: 14px;
    padding: 14px 18px;
    min-height: 65px;
    font-size: 0.95rem; line-height: 1.7;
  }
  .bubble::after {
    content: ''''; position: absolute; bottom: -8px; left: 35px;
    border-left: 8px solid transparent; border-right: 8px solid transparent;
    border-top: 8px solid rgba(212,175,55,0.6);
  }
  .cousin-row { display: flex; align-items: center; gap: 12px; margin-top: 14px; margin-bottom: 16px; }
  .mini-avatar {
    width: 50px; height: 50px; border-radius: 50%;
    background: linear-gradient(135deg, #6a0dad, #d4af37);
    display: flex; align-items: center; justify-content: center;
    flex-shrink: 0;
    box-shadow: 0 0 15px rgba(106,13,173,0.5);
  }
  .mood-badge {
    background: rgba(212,175,55,0.12);
    border: 1px solid var(--border);
    padding: 3px 10px; border-radius: 20px;
    font-size: 0.8rem; margin-top: 2px; display: inline-block;
  }
  .action-group-title {
    color: var(--gold-light); font-weight: 600;
    font-size: 0.88rem; margin: 14px 0 8px; letter-spacing: 1px;
  }
  .action-buttons { display: grid; grid-template-columns: repeat(auto-fill, minmax(140px, 1fr)); gap: 10px; }
  .action-btn {
    background: rgba(0,0,0,0.45);
    border: 1px solid var(--border);
    border-radius: 12px;
    padding: 10px 6px;
    cursor: pointer; transition: all 0.2s;
    text-align: center; color: var(--text);
    font-family: inherit;
  }
  .action-btn:hover { border-color: var(--gold); transform: translateY(-3px); box-shadow: 0 6px 16px rgba(212,175,55,0.25); }
  .action-btn:active { transform: scale(0.96); }
  .action-btn .a-icon { font-size: 1.5rem; display: block; }
  .action-btn .a-name { font-size: 0.82rem; margin-top: 4px; }
  .action-btn .a-amount { font-size: 0.75rem; color: var(--gold-light); margin-top: 2px; }
  .action-btn .a-favor { font-size: 0.68rem; color: var(--text-dim); }
  .action-btn.free { border-color: rgba(255,71,87,0.4); }
  .action-btn.free:hover { border-color: var(--red); }
  .reset-btn {
    margin-top: 15px; width: 100%;
    background: transparent; border: 1px dashed var(--border);
    color: var(--text-dim); padding: 9px 15px;
    border-radius: 10px; cursor: pointer;
    font-size: 0.85rem; font-family: inherit; transition: all 0.2s;
  }
  .reset-btn:hover { border-color: var(--gold); color: var(--gold-light); }

  /* ============ CARDS ============ */
  .cards-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(260px, 1fr)); gap: 16px; margin: 25px 0; }
  .info-card {
    background: var(--card);
    backdrop-filter: blur(14px);
    border: 1px solid var(--border);
    border-radius: 16px;
    padding: 20px; cursor: pointer;
    transition: all 0.3s cubic-bezier(0.4,0,0.2,1);
    position: relative; overflow: hidden;
  }
  .info-card:hover {
    transform: translateY(-4px); border-color: var(--gold);
    box-shadow: 0 12px 35px rgba(106,13,173,0.4);
  }
  .card-icon { font-size: 2rem; margin-bottom: 6px; display: block; }
  .card-title { font-size: 1.1rem; font-weight: 700; color: var(--gold-light); margin-bottom: 5px; }
  .card-hint { color: var(--text-dim); font-size: 0.82rem; }
  .card-badge {
    position: absolute; top: 12px; right: 12px;
    background: var(--gold); color: #1a0529;
    font-size: 0.7rem; font-weight: 700;
    padding: 2px 8px; border-radius: 15px;
  }

  /* ============ FORM ============ */
  .section-title {
    font-size: 1.3rem; color: var(--gold-light);
    margin: 30px 0 15px; text-align: center;
    letter-spacing: 2px;
  }
  .section-title::before, .section-title::after { content: ''◆''; color: var(--gold); margin: 0 8px; font-size: 0.8rem; }
  .form-card {
    background: var(--card);
    backdrop-filter: blur(14px);
    border: 1px solid var(--border);
    border-radius: 18px;
    padding: 22px; margin-bottom: 22px;
  }
  .form-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(250px, 1fr)); gap: 14px; }
  .field { display: flex; flex-direction: column; }
  .field.full { grid-column: 1 / -1; }
  .field label { font-size: 0.85rem; color: var(--gold-light); margin-bottom: 5px; font-weight: 600; letter-spacing: 0.5px; }
  .field input[type="text"], .field input[type="number"], .field textarea {
    background: rgba(0,0,0,0.5);
    border: 1px solid var(--border);
    border-radius: 10px;
    padding: 9px 12px;
    color: var(--text); font-size: 0.9rem; font-family: inherit;
    transition: all 0.2s; outline: none;
  }
  .field textarea { resize: vertical; min-height: 70px; }
  .field input:focus, .field textarea:focus { border-color: var(--gold); box-shadow: 0 0 0 3px rgba(212,175,55,0.2); }
  .radio-group { display: flex; gap: 10px; flex-wrap: wrap; }
  .radio-btn {
    flex: 1; min-width: 75px;
    padding: 8px 10px;
    background: rgba(0,0,0,0.4);
    border: 1px solid var(--border);
    border-radius: 10px;
    text-align: center; cursor: pointer;
    transition: all 0.2s;
    color: var(--text-dim); font-size: 0.85rem; user-select: none;
  }
  .radio-btn:hover { border-color: var(--gold); color: var(--text); }
  .radio-btn.active {
    background: linear-gradient(135deg, var(--purple), var(--gold));
    color: #fff; border-color: var(--gold); font-weight: 700;
  }
  .radio-btn input { display: none; }

  /* ============ TOGGLES ============ */
  .toggles-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(210px, 1fr)); gap: 10px; }
  .toggle-row {
    display: flex; align-items: center; justify-content: space-between;
    padding: 10px 12px;
    background: rgba(0,0,0,0.3);
    border: 1px solid rgba(212,175,55,0.15);
    border-radius: 10px;
    cursor: pointer; transition: all 0.2s;
  }
  .toggle-row:hover { border-color: var(--gold); background: rgba(0,0,0,0.45); }
  .toggle-name { font-size: 0.88rem; }
  .toggle-desc { font-size: 0.72rem; color: var(--text-dim); margin-top: 2px; }
  .switch {
    position: relative; width: 40px; height: 22px;
    background: rgba(0,0,0,0.5);
    border: 1px solid var(--border);
    border-radius: 20px; flex-shrink: 0; transition: all 0.3s;
  }
  .switch::after {
    content: ''''; position: absolute;
    width: 16px; height: 16px; border-radius: 50%;
    background: #888; top: 2px; left: 2px; transition: all 0.3s;
  }
  .toggle-row.on .switch { background: linear-gradient(135deg, var(--purple), var(--gold)); border-color: var(--gold); }
  .toggle-row.on .switch::after { transform: translateX(18px); background: #fff; }

  /* ============ PREVIEW ============ */
  .preview-panel {
    background: linear-gradient(135deg, rgba(26,5,41,0.92), rgba(42,8,69,0.92));
    border: 2px solid var(--gold);
    border-radius: 18px;
    padding: 20px;
    position: sticky; top: calc(var(--header-h) + 15px);
    box-shadow: 0 15px 40px rgba(106,13,173,0.4);
  }
  .preview-title { display: flex; align-items: center; justify-content: space-between; margin-bottom: 12px; }
  .preview-title h3 { color: var(--gold-light); font-size: 1.05rem; }
  .copy-btn {
    background: linear-gradient(135deg, var(--gold), #b8860b);
    color: #1a0529; border: none;
    padding: 7px 15px; border-radius: 8px;
    font-weight: 700; cursor: pointer; font-size: 0.82rem;
    transition: all 0.2s;
  }
  .copy-btn:hover { transform: scale(1.04); }
  .copy-btn.copied { background: var(--green); color: #fff; }
  .preview-content {
    background: rgba(0,0,0,0.55);
    border-radius: 10px; padding: 14px;
    font-family: ''Courier New'', monospace; font-size: 0.84rem;
    max-height: 540px; overflow-y: auto;
    white-space: pre-wrap; word-break: break-word;
    line-height: 1.65; color: #d8c8e8;
  }
  .preview-content .k { color: var(--gold-light); }
  .preview-content .v { color: #a8e6cf; }
  .preview-content .on { color: var(--green); }
  .preview-content .off { color: var(--red); }

  .main-layout { display: grid; grid-template-columns: 1fr; gap: 25px; }
  @media (min-width: 980px) { .main-layout { grid-template-columns: 1fr 380px; } }

  /* ============ MODAL ============ */
  .modal-backdrop {
    position: fixed; inset: 0;
    background: rgba(0,0,0,0.85);
    backdrop-filter: blur(10px); -webkit-backdrop-filter: blur(10px);
    z-index: 1500;
    display: none;
    align-items: center; justify-content: center;
    padding: 20px;
    overscroll-behavior: contain;
  }
  .modal-backdrop.active { display: flex; }
  .modal {
    background: linear-gradient(145deg, #1b052c, #2b0946);
    border: 1.5px solid var(--gold);
    border-radius: 20px;
    padding: 25px 20px;
    max-width: 650px; width: 100%;
    max-height: 80vh;
    overflow-y: auto;
    -webkit-overflow-scrolling: touch;
    position: relative;
    box-shadow: 0 20px 60px rgba(0,0,0,0.8);
  }
  .modal::-webkit-scrollbar { width: 6px; }
  .modal::-webkit-scrollbar-thumb { background: var(--gold); border-radius: 3px; }
  .modal::-webkit-scrollbar-track { background: rgba(0,0,0,0.3); }

  .modal-close {
    position: sticky; top: 0; float: right;
    width: 32px; height: 32px;
    border-radius: 50%; border: 1px solid var(--border);
    background: rgba(0,0,0,0.7); color: var(--gold);
    font-size: 1.1rem; cursor: pointer; z-index: 10;
    display: flex; align-items: center; justify-content: center;
  }
  .modal-close:hover { background: var(--gold); color: #000; }
  .func-item {
    background: rgba(0,0,0,0.35); border-left: 3px solid var(--gold);
    padding: 12px 14px; border-radius: 8px; margin-bottom: 12px; font-size: 0.88rem;
  }
  .func-item h4 { color: var(--gold-light); margin-bottom: 4px; font-size: 0.95rem; }
  .cmd {
    display: inline-block; background: rgba(212,175,55,0.18); color: var(--gold-light);
    padding: 2px 6px; border-radius: 4px; font-family: monospace; font-size: 0.8rem;
  }

  /* ============ TOAST ============ */
  .toast {
    position: fixed; top: 80px; left: 50%;
    transform: translateX(-50%) translateY(-25px);
    background: linear-gradient(135deg, var(--gold), #b8860b);
    color: #1a0529; padding: 10px 22px; border-radius: 30px;
    font-weight: 700; font-size: 0.9rem;
    z-index: 2000;
    opacity: 0;
    visibility: hidden;
    pointer-events: none;
    box-shadow: 0 10px 25px rgba(0,0,0,0.6);
    transition: opacity 0.3s ease, transform 0.3s ease, visibility 0.3s;
  }
  .toast.show {
    opacity: 1;
    visibility: visible;
    pointer-events: auto;
    transform: translateX(-50%) translateY(0);
  }

  .sound-toggle {
    position: fixed; bottom: 20px; right: 20px;
    width: 44px; height: 44px; border-radius: 50%;
    background: var(--card); border: 1px solid var(--gold); color: var(--gold);
    font-size: 1.1rem; cursor: pointer; z-index: 50; display: flex; align-items: center; justify-content: center;
  }
  .confetti { position: fixed; top: -20px; width: 10px; height: 16px; z-index: 1100; pointer-events: none; animation: confettiFall 3.2s linear forwards; }
  @keyframes confettiFall { to { transform: translateY(105vh) rotate(720deg); opacity: 0.7; } }

  footer { text-align: center; color: var(--text-dim); font-size: 0.8rem; margin-top: 40px; padding: 10px; }

  @media (max-width: 768px) {
    :root { --header-h: 58px; }
    .top-status-badge { display: none; }
    .debt-number { font-size: 1.1rem; }
    .preview-panel { position: static; }
    .danmaku-item { font-size: 0.85rem; }
  }
</style>
</head>
<body>

<!-- ============ 悬浮弹幕图层 (纯文字，无底色，穿透点击) ============ -->
<div id="danmaku-container"></div>

<!-- ============ 顶部悬浮常驻债务进度条 ============ -->
<div class="top-debt-bar">
  <div class="debt-bar-inner">
    <div class="debt-stat">
      <span class="debt-icon">💸</span>
      <div class="debt-info">
        <span class="debt-title-tag">剩余负债 / DEBT</span>
        <span class="debt-number" id="topDebtNum">-¥10,000,000</span>
      </div>
    </div>

    <div class="debt-progress-container">
      <div class="debt-progress-header">
        <span>债务清偿进度</span>
        <span id="topProgressPct">0% (已还 ¥0)</span>
      </div>
      <div class="debt-track">
        <div class="debt-fill" id="topDebtFill"></div>
      </div>
    </div>

    <div class="top-status-badge" id="topStatusBadge">👑 高傲未破防</div>
  </div>
</div>

<canvas id="particles"></canvas>

<div class="container">

  <!-- ============ HERO ============ -->
  <section class="hero">
    <div class="portrait">
      <img src="https://catai.wiki/0ffe298f-33ea-4909-179b-ead6c675df00/w=3000" alt="秦若岚主头像">
    </div>
    <h1 class="hero-title">秦若岚</h1>
    <p class="hero-sub">"表弟，姐最近资金周转不开，听说你中了彩票……"</p>
  </section>

  <!-- ============ 1. 女主角·秦若岚 官方人设档案区 ============ -->
  <section class="heroine-lore-card">
    <div class="lore-header">
      <h3>👑 介绍</h3>
      <span class="lore-badge">高傲の表姐</span>
      <span class="lore-badge" style="border-color:var(--red); color:#ff6b81;">巨额负债中</span>
    </div>
    <div class="lore-grid">
      <div class="lore-item">
        <div class="lore-item-title"><span>❄️</span>高傲自负</div>
        <div class="lore-item-content">💕秦若岚是你表姐(可自定义身份)，从小成绩优秀，长得漂亮，非常高傲自负，一直瞧不起你，认为你是窝囊废，给她提鞋都不配。</div>
      </div>
      <div class="lore-item">
        <div class="lore-item-title"><span>👜</span>创办公司</div>
        <div class="lore-item-content">💕她远光高远，认为大学生多如牛毛，高中毕业便放弃读大学，进入社会打拼，一手创办岚宇服装公司并大获成功，成为年轻董事长和无数人的女神，还登上当地杂志封面，风光无限。</div>
      </div>
      <div class="lore-item">
        <div class="lore-item-title"><span>😏</span>将你辞退</div>
        <div class="lore-item-content">💕你托关系成功进入她的公司，工作勤勤恳恳、未有过错，但她却看你很不爽，总是故意给你增加工作量、刁难你，想让你主动辞职，没想到你没有那个觉悟，于是她便谎称有人匿名举报你女厕偷窥，将你强行辞退，让你丢尽脸面。</div>
      </div>
      <div class="lore-item">
        <div class="lore-item-title"><span>💸</span>巨额负债</div>
        <div class="lore-item-content">💕然而，因决策上的失误，她押注的项目崩盘，直接背上了上千万元的巨额负债，公司濒临破产倒闭，亲朋好友全都避之不及，而你却买彩票中了几千万元的大奖，她知道你有恋物癖，也知道曾经对你各种冷眼和刁难，所以打算向你贩卖贴身物品来赚钱还债。</div>
      </div>
      <div class="lore-item">
        <div class="lore-item-title"><span>🫀</span>留有底线</div>
        <div class="lore-item-content">💕不过即便沦落如此，她也不会轻易低下高傲的头颅。若在好感度不足的情况下提出过分要求，她即便找其他途径也不会轻易委曲求全，除非纯爱，否则想让她彻底臣服并不容易。</div>
      </div>
    </div>
  </section>

  <!-- ============ FAVORABILITY ============ -->
  <section class="favor-panel">
    <div class="favor-label">
      <span>💎 好感度系统</span>
      <span class="favor-value" id="favorValue">10%</span>
    </div>
    <div class="favor-bar"><div class="favor-fill" id="favorFill"></div></div>
    <div class="favor-stages">
      <span>0-20%</span><span>20-40%</span><span>40-60%</span><span>60-80%</span><span>80-100%</span>
    </div>
    <div class="favor-desc" id="favorDesc">【0-20%】轻蔑 · 认为你不过是个靠运气的暴发户，打心底瞧不上你。</div>
    <input type="range" min="0" max="100" value="10" class="favor-slider" id="favorSlider">
  </section>

  <!-- ============ 交互互动区域 ============ -->
  <section class="interact-card">
    <div class="bubble"><span id="bubbleText"></span></div>
    <div class="cousin-row">
      <div class="mini-avatar">
        <img src="https://catai.wiki/0ffe298f-33ea-4909-179b-ead6c675df00/w=3000" alt="秦若岚小头像">
      </div>
      <div>
        <div style="font-weight:700; color:var(--gold-light);">秦若岚</div>
        <div class="mood-badge" id="moodBadge">😤 强装镇定</div>
      </div>
    </div>

    <div class="action-group-title">🛍 和她交易（收购贴身物品）</div>
    <div class="action-buttons" id="sellBtns"></div>
    <div class="action-group-title">💝 无偿帮还（自掏腰包平账）</div>
    <div class="action-buttons" id="freeBtns"></div>
    <button class="reset-btn" id="resetBtn">🔄 恢复债务</button>
  </section>

  <!-- ============ 信息卡片 ============ -->
  <div class="cards-grid">
    <div class="info-card" data-card="funcs">
      <span class="card-badge">核心</span>
      <span class="card-icon">⚙️</span>
      <div class="card-title">小功能总览</div>
      <div class="card-hint">总结 / 选项 / 直播 / 人称 / 特写 / 美化 / 小说 / 辅助 / 长度 / 雌小鬼 / 采访</div>
    </div>
    <div class="info-card" data-card="reduce">
      <span class="card-badge">省钱</span>
      <span class="card-icon">📉</span>
      <div class="card-title">降低消耗方法</div>
      <div class="card-hint">调低记忆范围 · 换模型 · 关功能 · 挪总结 · 减MOD</div>
    </div>
    <div class="info-card" data-card="config">
      <span class="card-badge">配置</span>
      <span class="card-icon">📜</span>
      <div class="card-title">自定义配置说明</div>
      <div class="card-hint">前置词 / 后置词 / 主提示词 / 世界书</div>
    </div>
  </div>

  <!-- ============ 表单 (用户填写自己角色设定) + 实时预览 ============ -->
  <div class="main-layout">
    <div>
      <h2 class="section-title">玩家 / 用户设定录入 (主角卡)</h2>
      <div class="form-card">
        <div class="form-grid">
          <div class="field">
            <label>👤 你的姓名 / 昵称</label>
            <input type="text" id="u_name" placeholder="例如：林远 / 表弟">
          </div>
          <div class="field">
            <label>🎂 你的年龄</label>
            <input type="number" id="u_age" min="1" max="120" placeholder="例如：22">
          </div>
          <div class="field full">
            <label>⚧ 你的性别 (默认男)</label>
            <div class="radio-group" data-field="gender">
              <label class="radio-btn active"><input type="radio" name="gender" value="男" checked>男</label>
              <label class="radio-btn"><input type="radio" name="gender" value="女">女</label>
            </div>
          </div>
          <div class="field full">
            <label>💼 你的身份背景</label>
            <input type="text" id="u_identity" placeholder="例如：刚刚中了五千万元彩票大奖的暴发户表弟">
          </div>
          <div class="field full">
            <label>🤝 你与秦若岚的关系</label>
            <textarea id="u_relation" placeholder="例如：表姐弟、表兄妹、邻居……"></textarea>
          </div>
          <div class="field full">
            <label>🧬 你的性格</label>
            <textarea id="u_personality" placeholder="例如：看似温和有礼，实则步步紧逼，喜欢欣赏她放下架子的模样..."></textarea>
          </div>
          <div class="field full">
            <label>📝 开场剧情</label>
            <textarea style="min-height: 90px;" id="u_custom_prompt" placeholder="可填写你想要的开场剧情"></textarea>
          </div>
        </div>
      </div>

      <h2 class="section-title">功能开关配置</h2>
      <div class="form-card">
        <div class="toggles-grid" id="togglesGrid"></div>

        <div style="margin-top: 18px;">
          <label style="color:var(--gold-light); font-weight:600; display:block; margin-bottom:8px;">📏 回复长度</label>
          <div class="radio-group" data-field="replyLen">
            <label class="radio-btn"><input type="radio" name="replyLen" value="简短">简短<br><small style="color:var(--text-dim)">&lt;500字</small></label>
            <label class="radio-btn active"><input type="radio" name="replyLen" value="中等" checked>中等<br><small style="color:var(--text-dim)">700-1200字</small></label>
            <label class="radio-btn"><input type="radio" name="replyLen" value="冗长">冗长<br><small style="color:var(--text-dim)">&gt;1500字</small></label>
          </div>
        </div>

        <div style="margin-top: 18px;">
          <label style="color:var(--gold-light); font-weight:600; display:block; margin-bottom:8px;">👁 人称视角</label>
          <div class="radio-group" data-field="pov">
            <label class="radio-btn"><input type="radio" name="pov" value="第一人称">第一人称<br><small style="color:var(--text-dim)">我</small></label>
            <label class="radio-btn active"><input type="radio" name="pov" value="第二人称" checked>第二人称<br><small style="color:var(--text-dim)">你</small></label>
            <label class="radio-btn"><input type="radio" name="pov" value="第三人称">第三人称<br><small style="color:var(--text-dim)">他/她</small></label>
          </div>
        </div>
      </div>
    </div>

    <!-- 右侧实时信息预览 -->
    <aside>
      <div class="preview-panel">
        <div class="preview-title">
          <h3>📋 实时导出预览</h3>
          <button class="copy-btn" id="copyBtn">📋 复制</button>
        </div>
        <div class="preview-content" id="previewContent"></div>
      </div>
    </aside>
  </div>
</div>

<!-- ============ 可滚动的 MODAL 弹窗 ============ -->
<div class="modal-backdrop" id="modalBackdrop">
  <div class="modal">
    <button class="modal-close" id="modalClose">✕</button>
    <div id="modalBody"></div>
  </div>
</div>

<button class="sound-toggle" id="soundToggle" title="音效开关">🔊</button>
<div class="toast" id="toast">已复制到剪贴板 ✓</div>

<script>
/* ============ 14 条纯文字彩色弹幕数据 ============ */
const DANMAKU_LIST = [
  { text: ''表姐美得像学校，让我好好学习，天天想上～'', color: ''#f1c40f'' },
  { text: ''表姐，我会帮你还债的！快拿鞭子抽我～🐶'', color: ''#ff7675'' },
  { text: ''表姐的贴身物品好香，我好喜欢～'', color: ''#fdcb6e'' },
  { text: ''原味丝袜卖不卖？我出五千块！！！'', color: ''#55efc4'' },
  { text: ''呵呵，表姐，你也有今天啊？拿出点诚意再说😏'', color: ''#ff4757'' },
  { text: '''', color: ''#a29bfe'' },
  { text: ''我只是一个为了维护高傲表姐的自尊心，而假装成恋物癖，以此为借口帮她还债的善良弟弟啊！我有什么错！'', color: ''#fab1a0'' },
  { text: ''我想买她用过的餐巾纸！'', color: ''#74b9ff'' },
  { text: ''表姐看我越生气，我就越开心，嘿嘿嘿～'', color: ''#fd79a8'' },
  { text: ''还不起债的话，那就千里江陵一日还～'', color: ''#ffeaa7'' },
  { text: ''刚刚腾不出手，现在我想说的是，如果人一直沉迷在欲望之中，那人存在的意义是什么呢？宇宙的奥秘又该由谁来探寻？😇'', color: ''#dfe6e9'' },
  { text: ''嘿嘿…高高在上的表姐…嘿嘿🤤 …瞧不起我的表姐…嘿嘿🤤 …欠债的表姐…嘿嘿🤤 …满脸嫌弃我的表姐…嘿嘿🤤 …香喷喷的表姐…嘿嘿🤤…被迫臣服的表姐…嘿嘿🤤'', color: ''#e056fd'' },
  { text: ''《关于我那高高在上满脸嫌弃极度讨厌我的表姐因为欠债而迫不得已卖给我贴身私密物品赚钱还债被迫臣服在我脚下这件事》'', color: ''#81ecec'' },
  { text: ''表姐，你不要用那种嫌弃的眼神看着我了，你越嫌弃我，我就越兴奋～🥵'', color: ''#d4af37'' }
];

/* ============ 弹幕引擎 (快速轻盈、纯文字多色、全屏穿透) ============ */
const danmakuContainer = document.getElementById(''danmaku-container'');
let danmakuIndex = 0;
const shuffledDanmaku = [...DANMAKU_LIST].sort(() => Math.random() - 0.5);

function spawnDanmaku() {
  if (!danmakuContainer) return;
  const data = shuffledDanmaku[danmakuIndex % shuffledDanmaku.length];
  danmakuIndex++;

  const el = document.createElement(''div'');
  el.className = ''danmaku-item'';
  el.textContent = data.text;
  el.style.color = data.color;

  // 随机分布在屏幕 12% ~ 82% 垂直高度
  const topPct = 12 + Math.random() * 70;
  el.style.top = `${topPct}vh`;

  // 速度加快：6.5秒 ~ 9.5秒 之间平滑飘过
  const duration = 6.5 + Math.random() * 3;
  el.style.animationDuration = `${duration}s`;

  danmakuContainer.appendChild(el);

  setTimeout(() => {
    el.remove();
  }, duration * 1000);
}

// 循环发射节奏：每 2 ~ 3.5 秒偶尔飘出一条
function scheduleNextDanmaku() {
  const delay = 2000 + Math.random() * 1500;
  setTimeout(() => {
    spawnDanmaku();
    scheduleNextDanmaku();
  }, delay);
}
setTimeout(scheduleNextDanmaku, 800);

/* 音效管理 */
let audioCtx = null, soundOn = true;
function ensureCtx() {
  if (!audioCtx) audioCtx = new (window.AudioContext || window.webkitAudioContext)();
  if (audioCtx.state === ''suspended'') audioCtx.resume();
}
function playTone(freq, dur=0.1, type=''sine'', vol=0.15) {
  if (!soundOn) return;
  ensureCtx();
  const osc = audioCtx.createOscillator(), gain = audioCtx.createGain();
  osc.type = type; osc.frequency.value = freq;
  gain.gain.setValueAtTime(vol, audioCtx.currentTime);
  gain.gain.exponentialRampToValueAtTime(0.001, audioCtx.currentTime + dur);
  osc.connect(gain); gain.connect(audioCtx.destination);
  osc.start(); osc.stop(audioCtx.currentTime + dur);
}
const sfx = {
  click:  () => playTone(800, 0.06, ''square'', 0.08),
  toggle: on => playTone(on %s 880 : 440, 0.1, ''triangle'', 0.12),
  open:   () => { playTone(523,0.08); setTimeout(()=>playTone(784,0.1),60); },
  close:  () => playTone(330, 0.12, ''triangle'', 0.1),
  hover:  () => playTone(1200, 0.03, ''sine'', 0.03),
  copy:   () => { playTone(659,0.08); setTimeout(()=>playTone(988,0.12),70); },
  slider: () => playTone(600 + Math.random()*400, 0.04, ''sine'', 0.04),
  ching:  () => { playTone(1244,0.06,''square'',0.07); setTimeout(()=>playTone(1568,0.1,''square'',0.07),60); },
  fanfare:() => [523,659,784,1046].forEach((f,i)=>setTimeout(()=>playTone(f,0.15,''triangle'',0.12), i*120))
};

/* 粒子背景 */
const canvas = document.getElementById(''particles''), ctx = canvas.getContext(''2d'');
let particles = [];
function resizeCanvas(){ canvas.width = innerWidth; canvas.height = innerHeight; }
addEventListener(''resize'', resizeCanvas); resizeCanvas();
(function createParticles(){
  const count = Math.min(45, Math.floor(innerWidth/30));
  for (let i=0;i<count;i++) particles.push({
    x: Math.random()*canvas.width, y: Math.random()*canvas.height,
    r: Math.random()*2+0.5, vx: (Math.random()-0.5)*0.3, vy: (Math.random()-0.5)*0.3,
    a: Math.random()*0.5+0.2, color: Math.random()>0.5%s''212,175,55'':''160,100,220''
  });
})();
(function animate(){
  ctx.clearRect(0,0,canvas.width,canvas.height);
  particles.forEach(p=>{
    p.x+=p.vx; p.y+=p.vy;
    if(p.x<0)p.x=canvas.width; if(p.x>canvas.width)p.x=0;
    if(p.y<0)p.y=canvas.height; if(p.y>canvas.height)p.y=0;
    ctx.beginPath(); ctx.arc(p.x,p.y,p.r,0,Math.PI*2);
    ctx.fillStyle=`rgba(${p.color},${p.a})`; ctx.fill();
  });
  requestAnimationFrame(animate);
})();

