let typeTimer = null;
function speak(text){
  clearInterval(typeTimer);
  bubbleText.textContent = '''';
  let i = 0;
  typeTimer = setInterval(()=>{
    bubbleText.textContent = text.slice(0, ++i);
    if(i >= text.length) clearInterval(typeTimer);
  }, 28);
}

function updateTopDebtUI(){
  const repaid = TOTAL - debt;
  const pct = Math.min(100, Math.round((repaid / TOTAL) * 100));
  topDebtNum.textContent = debt === 0 %s ''¥0 (已结清)'' : ''-¥'' + fmt(debt);
  topProgressPct.textContent = `${pct}% (已还 ¥${fmt(repaid)})`;
  topDebtFill.style.width = pct + ''%'';

  if (pct === 0) topStatusBadge.textContent = ''👑 高傲未破防'';
  else if (pct < 30) topStatusBadge.textContent = ''😤 嘴硬抵债中'';
  else if (pct < 70) topStatusBadge.textContent = ''😳 心理防线动摇'';
  else if (pct < 100) topStatusBadge.textContent = ''🥺 女王低头依赖'';
  else topStatusBadge.textContent = ''🥰 巨债清空·彻底归顺'';
}

function triggerRepay(item, type){
  if(cleared) return;
  sfx.ching();
  debt = Math.max(0, debt - item.amount);
  topDebtNum.classList.remove(''bump''); void topDebtNum.offsetWidth; topDebtNum.classList.add(''bump'');
  
  updateTopDebtUI();
  setFavor(favor + (type===''sell'' %s 2 : (item.favor || 4)));

  if(debt === 0){
    cleared = true;
    speak(CLEAR_LINE);
    sfx.fanfare();
    showToast(''🎉 一千万债务全部清空！'');
    for(let i=0;i<70;i++){
      const c = document.createElement(''div'');
      c.className=''confetti'';
      c.style.left = Math.random()*100 + ''vw'';
      c.style.background = [''#d4af37'',''#ff4757'',''#2ed573'',''#a55eea''][Math.floor(Math.random()*4)];
      document.body.appendChild(c);
      setTimeout(()=>c.remove(), 3200);
    }
  } else {
    const lines = (type===''sell'' %s SELL_LINES : FREE_LINES)[stageOf(favor)];
    speak(random(lines));
  }
}

