INSERT INTO stories (id, title, badge, cover_icon, cover_title, cover_subtitle, logo, theme_color, btn_gradient, handbook_json, roles_json, scenes_json, styles_json, first_turn_demo_json, custom_css, custom_html, category, created_at, updated_at, system_prompt, status_template, lorebook_json, post_history_instructions) VALUES ('deck_jiangshi_childhood', '死去的青梅竹马变成艳尸疯狂炸精', '还魂夜 · 青梅渴求', '🧟‍♀️', '艳尸青梅', '死而复生的恋人 · 榨精契约', '💜', '#9d8ec7', 'linear-gradient(135deg, #8f7ec9 0%, #d99a76 100%)', '{"desc": "三天前死于车祸的青梅竹马绫音在深夜赤裸出现在浴室。原本清瘦的身形异变为H罩杯巨乳与肥美丰臀的艳尸，唯一维持她肉体不腐烂与行动的养料就是玩家的精液。若不做爱身体便会变惨白僵硬，为了留住挚爱，你只能一次次沉沦于冰冷却滚烫的交合中。", "author": "AI风月精选"}', '[{"name": "绫音", "role": "19岁死而复生的青梅竹马（艳尸）", "desc": "天然紫色及腰长发、冷萌丹凤眼脸庞。死后肉体异变为H罩杯水滴巨乳、细腰肥美丰臀、天生白虎粉穴。常年触感约10℃冰冷，但进食时口腔与花径滚烫贪婪。极度依恋玩家，性事上直白霸道，靠吸食精液维生并恢复体温与红润。"}]', '[{"title": "深夜水汽弥漫的浴室", "desc": "花洒下赤裸伫立的紫发少女，肌肤透着病态粉嫩，冷香与水雾交织"}, {"title": "拉紧遮光厚窗帘的卧房", "desc": "昏暗中避光的大床，冰冷与滚烫反差的合体温存之所"}, {"title": "客厅暗角旧沙发", "desc": "蜷缩抱着旧衬衫、皮肤逐渐惨白僵硬的饥饿哀求角落"}]', '{}', '{"story": "深夜，钥匙插进锁孔的声音在寂静的楼道里格外清晰。你拖着疲惫空洞的身体推开家门，三天前亲手将车祸去世的青梅竹马绫音下葬的绝望，仍如铅块般压在胸口。\n然而刚进玄关，浴室里竟隐隐传来哗哗的水声——这间屋子，明明只有你一个人住。\n水雾从虚掩的磨砂玻璃门缝里悄然渗出，带着一股极淡的、如雨后青草般沁人心脾的冷香。你的心脏在胸腔里剧烈跳动，颤抖着推开浴室的门——\n花洒下，一个绝美的赤裸身影正静静伫立。那头熟悉的及腰紫发湿漉漉地贴在白皙细腻的背脊上；转过身来，原本纤细的身材竟发生了夸张的异变：胸前是一对随着呼吸沉甸甸颤动的H罩杯水滴巨乳，硕大饱满的乳晕在水流冲刷下泛着深红诱人的色泽，平坦的小腹下是肥美圆润的翘臀与毫无杂草的白虎粉穴。\n她顶着那张你无比熟悉的、总是带着一丝清冷的“冷萌脸”，眼眶微红地注视着你，声音轻哑而带着无助的渴求：“……你回来了。我好饿。”", "branches": [{"tag": "A", "title": "颤抖着上前将浑身冰凉的绫音紧紧拥入怀中", "desc": "踏入水雾中不顾冰冷的花洒水流，一把将失而复得的青梅紧紧抱在怀里，感受她冰凉却真实的柔软躯体"}, {"tag": "B", "title": "伸手轻抚她泛着冷香的脸颊并询问复活的真相", "desc": "指尖拂去她长睫上的水珠，轻抚她微凉的冷萌脸庞，沙哑追问她为何能从棺木下回到自己身边"}, {"tag": "C", "title": "双手托起她沉甸甸的夸张巨乳试探她的体温与心跳", "desc": "将掌心贴覆在她胸口那对沉甸甸的水滴巨乳上，指尖陷进极其细腻柔软的软肉，惊觉那深处竟没有半点心跳"}, {"tag": "D", "title": "解开皮带迎上她饥渴的目光直接提供喂食", "desc": "迎着她蓄满水汽的紫色眼眸，干脆利落地解开皮带掏出坚挺滚烫的肉棒：“饿了就来吃，只要能留住你，怎样都行。”"}], "location": "单身公寓 · 深夜水雾浴室"}', NULL, '<!DOCTYPE html>
<html lang="zh-CN">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>还魂夜 · 青梅的无尽渴求</title>
<link href="https://fonts.googleapis.com/css2%sfamily=Noto+Serif+SC:wght@400;600;700&display=swap" rel="stylesheet">
<style>
    :root{
        --soft-white:#ffffff;
        --cream-bg:#fdfcf8;
        --accent-gold:#d4a373;
        --accent-pink:#faedcd;
        --accent-purple:#9d8ec7;
        --accent-purple-soft:#f3e8ff;
        --text-dark:#2d2d2d;
        --text-gray:#6d6d6d;
        --border-color:#efe6ff;
        --shadow:0 12px 42px rgba(120,90,160,0.10);
        --shadow-soft:0 6px 20px rgba(120,90,160,0.07);
    }
    *{box-sizing:border-box;}
    html,body{margin:0;padding:0;}
    body{
        font-family:''Noto Serif SC'',"PingFang SC","Microsoft YaHei",serif;
        background:linear-gradient(180deg,#fdfcf8 0%,#f7f2ff 45%,#fdfcf8 100%);
        color:var(--text-dark);
        line-height:1.85;
        padding:18px 14px 60px;
        -webkit-font-smoothing:antialiased;
    }
    .page{max-width:880px;margin:0 auto;}
    .hero{
        position:relative;
        text-align:center;
        padding:46px 24px 40px;
        background:linear-gradient(135deg,#fff7f0 0%,#f6ecff 55%,#fdfcf8 100%);
        border-radius:30px;
        border:1px solid var(--border-color);
        box-shadow:var(--shadow);
        margin-bottom:24px;
        overflow:hidden;
    }
    .hero::before{
        content:"";
        position:absolute;
        width:220px;height:220px;
        background:radial-gradient(circle,rgba(157,142,199,0.22),transparent 70%);
        top:-90px;right:-70px;border-radius:50%;
    }
    .hero::after{
        content:"";
        position:absolute;
        width:180px;height:180px;
        background:radial-gradient(circle,rgba(212,163,115,0.18),transparent 70%);
        bottom:-80px;left:-60px;border-radius:50%;
    }
    .hero-tag{
        position:relative;
        display:inline-block;
        background:linear-gradient(135deg,#f3e8ff,#faedcd);
        color:#7c6bb0;
        padding:7px 20px;
        border-radius:999px;
        font-size:12.5px;
        letter-spacing:3px;
        font-weight:600;
        border:1px solid #ead9ff;
    }
    .hero h1{
        position:relative;
        font-size:30px;
        letter-spacing:2px;
        margin:20px 0 10px;
        color:#332b4d;
    }
    .hero .hero-sub{
