.f { height: 100%; border-radius: 0; background: linear-gradient(90deg, #a53232, #8b2626); box-shadow: none; }
.l div, .txt div, .lo div { padding: 8px 0; border-bottom: 1px dashed rgba(139,38,38,0.15); }
