om:30px;}.roster-group-title{color:#a00505;font-family:var(--font-title);font-size:1.5rem;border-bottom:1px dashed #4a0101;margin-bottom:15px;padding-bottom:5px;}.roster-item{background:none;border:none;color:#8a0303;font-family:var(--font-title);font-size:1.8rem;font-weight:bold;text-shadow:1px 1px 3px #000;transition:all 0.3s;padding:5px 15px;position:relative;display:inline-block;}.roster-item:hover{color:#ff1a1a;text-shadow:0 0 10px rgba(255,0,0,0.8);transform:scale(1.1) !important;z-index:2;}.roster-item::after{content:'''';position:absolute;bottom:0;left:0;width:100%;height:2px;background:#ff1a1a;transform:scaleX(0);transition:transform 0.3s;}.roster-item:hover::after{transform:scaleX(1);}.form-group{margin-bottom:20px;}.form-label{display:block;font-family:var(--font-title);font-size:1.2rem;color:#a00505;margin-bottom:8px;font-weight:bold;}.form-input, .form-select, .form-textarea{width:100%;background:rgba(0,0,0,0.5);border:1px solid #4a0101;font-family:var(--font-body);font-size:1rem;color:#fff;padding:12px;transition:all 0.3s ease;outline:none;border-radius:2px;}.form-input:focus, .form-select:focus, .form-textarea:focus{border-color:#ff1a1a;background:rgba(138,3,3,0.1);box-shadow:inset 0 0 10px rgba(138,3,3,0.3);}.form-textarea{resize:vertical;min-height:80px;}option{background:#050505;color:#ccc;}.flex-row{display:flex;gap:15px;}.flex-half{flex:1;}.preview-box{margin-top:30px;padding:20px;background-color:rgba(0,0,0,0.8);border:1px dashed #4a0101;border-radius:2px;font-family:''Courier New'',Courier,monospace;font-size:1rem;line-height:1.6;color:#aaa;white-space:pre-wrap;word-wrap:break-word;box-shadow:inset 0 0 15px #000;}.btn-submit{display:block;width:100%;background:linear-gradient(to bottom, #4a0101, #1a0000);color:#ff1a1a;text-align:center;padding:15px;font-family:var(--font-title);font-size:1.5rem;font-weight:bold;border:1px solid #8a0303;border-radius:3px;margin-top:30px;box-shadow:0 0 15px rgba(138,3,3,0.4);transition:all 0.3s ease;letter-spacing:2px;}.btn-submit:hover{background:linear-gradient(to bottom, #8a0303, #4a0101);color:#fff;box-shadow:0 0 25px rgba(255,0,0,0.6);animation:heartbeat 1s infinite;}@keyframes heartbeat{0%,100%{transform:scale(1.02);}50%{transform:scale(1.04);}}#copy-modal{position:fixed;top:0;left:0;width:100%;height:100vh;background-color:rgba(0,0,0,0.9);display:none;justify-content:center;align-items:center;z-index:20000;opacity:0;transition:opacity 0.3s ease;}.modal-content{background-color:#0a0505;padding:40px;border-radius:3px;text-align:center;box-shadow:0 0 40px #8a0303;border:1px solid #ff1a1a;max-width:400px;width:90%;}.modal-title{font-family:var(--font-title);font-size:1.8rem;color:#ff1a1a;margin-bottom:15px;font-weight:bold;}.modal-text{font-size:1.1rem;margin-bottom:25px;color:#ccc;}.btn-close{background-color:#1a0000;color:#ff1a1a;border:1px solid #8a0303;padding:10px 30px;font-size:1.1rem;border-radius:2px;transition:all 0.3s;font-weight:bold;}.btn-close:hover{background-color:#4a0101;box-shadow:0 0 10px #ff0000;}footer{position:fixed;bottom:0;width:100%;text-align:center;padding:10px;opacity:0.01;pointer-events:none;z-index:-1;}footer a{color:#fff;text-decoration:none;font-size:12px;}@media (max-width:768px){.menu-item:nth-child(1){top:20%;left:5%;font-size:2rem;}.menu-item:nth-child(2){top:40%;left:55%;font-size:1.8rem;}.menu-item:nth-child(3){top:60%;left:10%;font-size:2.2rem;}.menu-item:nth-child(4){top:80%;left:45%;font-size:2.5rem;}.panel{width:95%;padding:35px 20px 20px 20px;height:90vh;}.panel-title{font-size:1.8rem;}.flex-row{flex-direction:column;gap:0;}#rule-modal{padding:40px 10px;}.rule-modal-content{padding:30px 15px;}}</style></head><body><audio id="bgm" loop preload="auto"><source src="https://music.163.com/song/media/outer/url%sid=1374978394.mp3" type="audio/mpeg"></audio><button id="music-toggle" class="clickable" title="开启/关闭音效"><svg id="icon-play" width="30" height="30" viewBox="0 0 24 24" fill="none" stroke="#ff1a1a" stroke-width="2" style="display:block;"><polygon points="11 5 6 9 2 9 2 15 6 15 11 19 11 5"></polygon><path d="M19.07 4.93a10 10 0 0 1 0 14.14M15.54 8.46a5 5 0 0 1 0 7.07"></path></svg><svg id="icon-mute" width="30" height="30" viewBox="0 0 24 24" fill="none" stroke="#666" stroke-width="2" style="display:none;"><polygon points="11 5 6 9 2 9 2 15 6 15 11 19 11 5"></polygon><line x1="23" y1="9" x2="17" y2="15"></line><line x1="17" y1="9" x2="23" y2="15"></line></svg></button><div id="new-intro" class="clickable"><div class="intro-text">我叫杨间，当你看见这句话的时候我已经死了.....</div></div><div id="main-scene"><div id="main-menu"><button class="menu-item clickable" data-target="panel-world">【天地冥律】</button><button class="menu-item clickable" data-target="panel-events">【血字案卷】</button><button class="menu-item clickable" data-target="panel-chars">【遗像留影】</button><button class="menu-item clickable" data-target="panel-create">【入局引路】</button></div><div id="panel-world" class="panel"><button class="panel-close clickable">×</button><h2 class="panel-title">天地冥律</h2><p class="lore-text" style="text-align:center;margin-bottom:25px;color:#ff1a1a;">【绝密警告】点击查阅灵异档案，知晓越多，死得越快。</p><div class="rule-item" data-rule="1">【铁律一】厉鬼本源与规律</div><div class="rule-item" data-rule="2">【铁律二】暗夜割据与势力</div><div class="rule-item" data-rule="3">【铁律三】诡物图鉴与代价</div><div class="rule-item" data-rule="4">【铁律四】驾驭、死机与异类</div></div><div id="rule-modal"><div class="rule-modal-content"><button id="close-rule-modal" class="panel-close clickable">×</button><h2 id="rule-modal-title" class="panel-title"></h2><div id="rule-modal-body"></div></div></div><div id="panel-events" class="panel"><button class="panel-close clickable">×</button><h2 class="panel-title">血字案卷</h2><p class="lore-text" style="text-align:center;margin-bottom:20px;">【绝密档案：时代终结者的足迹，点击篇章展开节点】</p><div class="chapter-list" id="chapter-accordion"></div></div><div id="panel-chars" class="panel"><button class="panel-close clickable">×</button><h2 class="panel-title">遗像留影</h2><p class="lore-text">这里曾经记录着许多名字，像是一份等待死神勾划的清单。点击血字查看生平绝密。</p><div class="roster-group"><div class="roster-group-title">【核心主角团】</div><div class="roster-container" id="roster-main"></div></div><div class="roster-group"><div class="roster-group-title">【总部顶尖队长】</div><div class="roster-container" id="roster-captains"></div></div></div><div id="panel-create" class="panel"><button class="panel-close clickable">×</button><h2 class="panel-title">入局引路 (签订死契)</h2><div class="flex-row"><div class="flex-half form-group"><label class="form-label">名字/代号：</label><input type="text" id="cfg-name" class="form-input" placeholder="输入姓名或代号..." autocomplete="off"></div><div class="flex-half form-group"><label class="form-label">性别：</label><select id="cfg-gender" class="form-select"><option value="男">男</option><option value="女">女</option><option value="未知">未知/不可名状</option></select></div></div><div class="flex-row"><div class="flex-half form-group"><label class="form-label">社会身份：</label><input type="text" id="cfg-identity" class="form-input" placeholder="如：学生/公司职员/无业游民/安保..."></div><div class="flex-half form-group"><label class="form-label">性格特征：</label><input type="text" id="cfg-personality" class="form-input" placeholder="如：冷酷无情/疯狂/谨慎胆小/圣母..."></div></div><div class="flex-row"><div class="flex-half form-group"><label class="form-label">所属势力：</label><select id="cfg-faction" class="form-select"><option value="亚洲区总部">亚洲区总部</option><option value="朋友圈">朋友圈</option><option value="灵异论坛">灵异论坛</option><option value="国王组织">国王组织</option><option value="鬼邮局/太平古镇">鬼邮局/太平古镇</option><option value="民间散人">民间散人</option><option value="custom">【自定义势力】</option></select><input type="text" id="cfg-faction-custom" class="form-input" placeholder="输入自定义势力..." style="display:none; margin-top:10px;"></div><div class="flex-half form-group"><label class="form-label">介入篇章：</label><select id="cfg-time-chapter" class="form-select"></select></div></div><div class="form-group"><label class="form-label">介入节点：</label><select id="cfg-time-node" class="form-select"></select></div><div class="form-group"><label class="form-label">生命形态：</label><select id="cfg-lifeform" class="form-select"><option value="普通人">普通人 (在灵异事件中绝望求生)</option><option value="驭鬼者" selected>驭鬼者/异类 (与鬼共舞，饮鸩止渴)</option></select></div><div id="ghost-config-area"><div class="form-group"><label class="form-label">驾驭的灵异拼图 (能力与杀人规律)：</label><textarea id="cfg-ghost" class="form-textarea" placeholder="详细描述你体内厉鬼的能力。例如：鬼眼（红光覆盖范围内皆为鬼域）、无头鬼影（拼接肢解躯体）..."></textarea></div><div class="flex-row"><div class="flex-half form-group"><label class="form-label">即死条件 (触发规律)：</label><input type="text" id="cfg-death" class="form-input" placeholder="例如：听到特定频率的敲门声必死..."></div><div class="flex-half form-group"><label class="form-label">复苏代价 (使用能力的后果)：</label><input type="text" id="cfg-cost" class="form-input" placeholder="例如：每次使用鬼域，身体就会加速腐烂..."></div></div><div class="form-group"><label class="form-label">角色实力境界：</label><select id="cfg-power" class="form-select"><option value="驾驭单鬼期 (濒临复苏)">驾驭单鬼期 (濒临复苏，随时暴毙)</option><option value="双鬼平衡期 (短暂安全)">双鬼平衡期 (短暂安全，掌控一定自保力)</option><option value="半异类 (免疫常规致死)">半异类 (免疫常规致死，开始舍弃人类结构)</option><option value="队长级 (掌控深层鬼域)">队长级 (掌控深层鬼域，足以镇压S级事件)</option><option value="民国老怪级 (灵异源头)">民国老怪级 (灵异源头，近乎无解的存在)</option></select></div></div><div class="form-group"><label class="form-label">背景故事与执念：</label><textarea id="cfg-bg" class="form-textarea" placeholder="简述你的过去，以及在这绝望世界中支撑你活下去的唯一理由..."></textarea></div><div class="form-group"><label class="form-label">绝密档案预览：</label><div id="preview-box" class="preview-box"></div></div><button type="button" id="btn-submit" class="btn-submit clickable">【生成死契档案并复制】</button></div></div><div id="copy-modal"><div class="modal-content"><h3 class="modal-title">契约已成</h3><p class="modal-text">你的绝密档案已成功复制。<br>无论你是原著角色还是自定义人物，祝你在这地狱中...活得久一点。</p><button class="btn-close clickable" id="btn-close-modal">关闭</button></div></div><footer><a href="https://aitrader.wiki/zh/explore/installed/813e225e-2a1a-45bd-b441-f4741dff5418" target="_blank">本页面采用AI风月-创作大师生成</a></footer><script>const bgm=document.getElementById(''bgm'');const musicToggle=document.getElementById(''music-toggle'');const iconPlay=document.getElementById(''icon-play'');const iconMute=document.getElementById(''icon-mute'');let isMusicPlaying=false;function toggleMusic(){if(isMusicPlaying){bgm.pause();iconPlay.style.display=''none'';iconMute.style.display=''block'';}else{bgm.play().catch(e=>console.log(e));iconPlay.style.display=''block'';iconMute.style.display=''none'';}isMusicPlaying=!isMusicPlaying;}musicToggle.addEventListener(''click'',toggleMusic);const newIntro=document.getElementById(''new-intro'');const mainMenu=document.getElementById(''main-menu'');const menuItems=document.querySelectorAll(''.menu-item'');const panels=document.querySelectorAll(''.panel'');const panelCloses=document.querySelectorAll(''.panel-close'');let introDone=false;newIntro.addEventListener(''click'',()=>{if(introDone)return;introDone=true;newIntro.style.opacity=''0'';bgm.play().then(()=>{isMusicPlaying=true;iconPlay.style.display=''block'';iconMute.style.display=''none'';}).catch(e=>console.log("Audio autoplay blocked"));musicToggle.style.display=''block'';setTimeout(()=>{newIntro.style.display=''none'';},1500);});function hideAllPanels(){panels.forEach(p=>{p.style.display=''none'';p.style.opacity=''0'';});}menuItems.forEach(item=>{item.addEventListener(''click'',()=>{const targetId=item.getAttribute(''data-target'');mainMenu.style.opacity=''0'';setTimeout(()=>{mainMenu.style.display=''none'';hideAllPanels();const targetPanel=document.getElementById(targetId);targetPanel.style.display=''block'';setTimeout(()=>{targetPanel.style.opacity=''1'';},50);},500);});});panelCloses.forEach(btn=>{if(btn.id===''close-rule-modal'')return;btn.addEventListener(''click'',()=>{hideAllPanels();mainMenu.style.display=''block'';setTimeout(()=>{mainMenu.style.opacity=''1'';},50);});});const ruleData={1:{title:''【铁律一】厉鬼本源与规律'',content:''<p class="lore-text">1. <span class="blood-highlight">鬼无法被杀死。</span>这是这个世界最让人绝望的基石。任何物理手段、热武器、核弹都对真正的灵异无效。即使将其打碎、焚烧，它也会在灵异的深处再次复原。</p><p class="lore-text">2. <span class="blood-highlight">能对付鬼的只有鬼。</span>人类只有驾驭了厉鬼力量（成为驭鬼者），利用体内的灵异去对抗外在的灵异，才能挣扎求生。这本质上是用毒药解毒。</p><p class="lore-text">3. <span class="blood-highlight">洞察鬼的规律。</span>每一只鬼都有其绝对的杀人规律（如：听到敲门声、回头、被看到脸）。只要不触发规律，普通人也能与S级厉鬼擦肩而过；一旦触发规律，无视距离、无视防御，必死无疑。</p><p class="lore-text">4. <span class="blood-highlight">鬼域与重启。</span>高等级的厉鬼拥有“鬼域”，这是一种扭曲现实的灵异空间。而在鬼域的深层（如第七层以上），甚至可以触及时间的禁忌，实现“重启”，将自身或周围的一切倒退回几十分钟前的状态。</p>''},2:{title:''【铁律二】暗夜割据与势力'',content:''<p class="lore-text">在这个被绝望笼罩的世界中，灵异事件频发，驭鬼者们抱团取暖，形成了主宰生死的各大势力：</p><p class="lore-text">- <span class="blood-highlight">【亚洲区总部】</span>：官方最高组织，掌握最多资源。以“十二队长”为核心战力，致力于关押厉鬼、维持秩序。队长级人物拥有独立处置S级事件的特权与实力。</p><p class="lore-text">- <span class="blood-highlight">【朋友圈】</span>：以利益为核心的顶尖驭鬼者财阀，行事霸道，底蕴深厚。曾试图通过资本与灵异结合掌控总部，后被杨间单枪匹马血洗覆灭。</p><p class="lore-text">- <span class="blood-highlight">【灵异论坛】</span>：民间最大的驭鬼者交流与互助平台，由亚洲第一驭鬼者叶真所创。叶真以中二病著称，但实力极其恐怖，拥有替死灵异。</p><p class="lore-text">- <span class="blood-highlight">【国王组织】</span>：海外顶尖势力，由多位代号为"国王"的恐怖驭鬼者组成。企图用“诺亚方舟计划”将幽灵船引向亚洲，颠覆现有格局，引发了惨烈的世界大战。</p><p class="lore-text">- <span class="blood-highlight">【鬼邮局/太平古镇】</span>：遗留自民国时期的恐怖灵异之地。民国七老为了镇压灵异留下的后手，既是可怕的诅咒，也是上一代的传承。邮局管理者掌控着无数信使的生死。</p>''},3:{title:''【铁律三】诡物图鉴与代价'',content:''<p class="lore-text">灵异物品是保命的底牌，但使用它们往往伴随着比死亡更可怕的代价：</p><p class="lore-text">- <span class="blood-highlight">【人皮纸】</span>：知晓过去未来，能给出驾驭厉鬼的完美方案。但它拥有极高智慧，给出的方案里永远藏着置人于死地、企图让自己脱困的致命陷阱。</p><p class="lore-text">- <span class="blood-highlight">【鬼橱】</span>：等价交换的极致。向它提出要求，它必定帮你实现，但你必须在规定时间内完成它下达的恐怖任务，否则将面临无解的抹杀。</p><p class="lore-text">- <span class="blood-highlight">【棺材钉】</span>：无视任何规律的终极压制物。只要钉入厉鬼体内，瞬间形成绝对压制，连S级源头也能使其死机。杨间凭此一击封神关押饿死鬼。</p><p class="lore-text">- <span class="blood-highlight">【鬼柴刀】</span>：只要留下脚印，就能无视空间距离隔空肢解厉鬼。代价是绝对的等价反噬：使用者也会承受同等部位的肢解，没有极强恢复力的驭鬼者用之必死。</p><p class="lore-text">- <span class="blood-highlight">【红色鬼烛】</span>：点燃后，只要烛火不灭，处于火光范围内的人绝对安全。燃烧速度取决于遭受的灵异攻击强度，面对S级厉鬼可能瞬间燃尽。</p><p class="lore-text">- <span class="blood-highlight">【白色鬼烛】</span>：点燃会散发黑色阴霾，必定吸引周围厉鬼到来。极其危险，通常用于绝境中主动引鬼制造混乱。</p><p class="lore-text">- <span class="blood-highlight">【八音盒】</span>：打开播放诡异音乐，音乐响起时听者被施加不死诅咒，肉身被毁也能活。代价：音乐停止时，听者将遭受无解的厉鬼袭击。</p><p class="lore-text">- <span class="blood-highlight">【替死娃娃】</span>：极其稀有，写上名字后，可代替使用者承受一次必死的灵异袭击。是驭鬼者梦寐以求的保命神物。</p>''},4:{title:''【铁律四】驾驭、死机与异类'',content:''<p class="lore-text">成为驭鬼者，就是在饮鸩止渴。力量的尽头是彻底的深渊：</p><p class="lore-text">- <span class="blood-highlight">【厉鬼复苏】</span>：每一次使用灵异力量，都会刺激体内的厉鬼，加速其苏醒。当鬼完全复苏，驭鬼者就会暴毙，体内的鬼将脱离束缚，化作新的、更恐怖的灵异事件。</p><p class="lore-text">- <span class="blood-highlight">【拼图与制衡】</span>：延缓复苏的唯一常规方法。驾驭两只或多只杀人规律互补、相互克制的厉鬼，在体内形成脆弱的平衡。但平衡一旦打破，死得更快。</p><p class="lore-text">- <span class="blood-highlight">【厉鬼死机】</span>：极少数情况下的奇迹。通过极端的灵异冲突（如在特定灵异之地自杀重启），让体内的鬼陷入深度沉睡。驭鬼者可以毫无代价地使用力量，但随着时间推移，死机依然有解除的风险。</p><p class="lore-text">- <span class="blood-highlight">【彻底异类】</span>：驭鬼者的最高境界。彻底舍弃人类的生理结构，用灵异力量重塑身躯，甚至将自己的意识转化为某种灵异现象。异类不再惧怕厉鬼复苏，拥有近乎无限的寿命，但也会逐渐丧失人性，变得冷漠如真正的厉鬼。</p>''}};const ruleItems=document.querySelectorAll(''.rule-item'');const ruleModal=document.getElementById(''rule-modal'');const ruleModalTitle=document.getElementById(''rule-modal-title'');const ruleModalBody=document.getElementById(''rule-modal-body'');const closeRuleModal=document.getElementById(''close-rule-modal'');function openModal(title,content){ruleModalTitle.innerText=title;ruleModalBody.innerHTML=content;ruleModal.style.display=''flex'';setTimeout(()=>{ruleModal.style.opacity=''1'';},50);}ruleItems.forEach(item=>{item.addEventListener(''click'',()=>{const ruleId=item.getAttribute(''data-rule'');openModal(ruleData[ruleId].title,ruleData[ruleId].content);});});closeRuleModal.addEventListener(''click'',()=>{ruleModal.style.opacity=''0'';setTimeout(()=>{ruleModal.style.display=''none'';},400);});const chapters=[{title:"第一篇章：大昌市篇",nodes:["节点1：2018年6月14日-15日·大昌市第七高中敲门鬼事件","节点2：2018年6月15日·逃出生天与驭鬼者之路","节点3：2018年6月15-16日·认鬼做父与商场诡影","节点4：2018年6月17日·无头鬼影与商场逃生","节点5：2018年6月17日-20日·厉鬼收容与黑吃黑"]},{title:"第二篇章：黄岗村篇",nodes:["节点1：2018年6月20日-23日·俱乐部冲突与黄岗村惊魂","节点2：2018年6月24日-26日·打破平衡与恶鬼交易","节点3：2018年6月26日·驾驭双鬼与黄岗村终局","节点4：2018年7月1日-2日·鬼婴重现与镜中鬼","节点5：2018年7月2日-3日·鬼血复苏与俱乐部之战","节点6：2018年7月3日·诅咒反杀与观江交易","节点7：2018年7月3日·敲门鬼域与鬼绳复苏","节点8：2018年7月3日-7日·古宅鬼镜与杀机暗涌","节点9：2018年7月7日-8日·绝杀与反击"]},{title:"第三篇章：饿死鬼篇",nodes:["节点1：2018年7月8日-9日·饿死鬼事件爆发","节点2：7月9日-13日·第七街与饿死鬼","节点3：7月13日-18日·绝境与赌命","节点4：7月18日-25日·向死而生与时间重置","节点5：7月25日-31日·饿死鬼终局与余波"]},{title:"第四篇章：灵异公交车篇",nodes:["节点1：8月1日-2日·鬼脸遗患与灵异公交","节点2：8月2日-8月8日·鬼车死局与X级档案","节点3：8月9日-10日·鬼橱交易与中山迷局"]},{title:"第五篇章：凯撒大酒店篇",nodes:["节点1：8月11日·凯撒大酒店与笑脸迷局","节点2：8月12日·鬼雾迷局与无解柴刀","节点3：8月12-13日·记忆篡改与禁忌重生","节点5：8月13-18日·大昌市的部署与大京市之行"]},{title:"第六篇章：总部鬼差篇",nodes:["节点1：8月18日·航班惊魂与大京市初阵","节点2：8月18-19日·大京市暗流与记忆篡改","节点3：8月20日·大京市培训与鬼差出棺","节点4：8月20-21日·绝境博弈与鬼差重启","节点5：8月21-22日·五层鬼域与总部风波","节点6：8月22-23日·总部立威与民国隐秘","节点7：8月23日·敲门鬼之谜与S级失控","节点8：8月23-24日·总部救援与雷霆清算","节点9：8月24-25日·鬼画初现与惊魂救援","节点10：8月25日·绝杀与八音盒诅咒","节点11：8月25日·血洗朋友圈与六层鬼域","节点12：8月25-26日·诡异柴刀与诅咒博弈"]},{title:"第七篇章：鬼梦篇",nodes:["节点1：8月26日·画中求生与鬼橱交易","节点2：8月27-28日·灵位陷阱与意识复苏","节点3：8月28-30日·队伍集结与跨国交易","节点4：8月31日-9月1日·神户除灵与敲门鬼关押","节点5：9月1日-3日·死亡预知与归乡探秘","节点5：9月3日-13日·鬼梦终结与总部惊变"]},{title:"第八篇章：鬼湖篇",nodes:["节点1：9月14日-16日·鬼邮局与福寿园之谜","节点2：9月16日-18日·大川市的无影阴霾","节点3：9月18-19日·大川市的全面失控与301室之谜","节点4：9月20-22日·异类觉醒与大东古宅","节点5：9月23-26日·邮局四楼与公交前夕","节点6：9月26日-10月1日·灵异公交与古宅七日","节点7：10月1日-10月6日·头七回魂与邮局五楼","节点8：10月7日-10月8日·地狱公寓与神兵天降","节点9：10月8日-10月11日·许愿鬼与鬼湖集结","节点10：10月11日-10月15日·鬼湖封锁与恶犬认主"]},{title:"第九篇章：鬼画篇",nodes:["节点1：10月16日-10月19日·大澳市风波与凯撒迷局","节点2：10月19日-10月25日·凯撒迷局与大京风云","节点3：10月25日-10月26日·大京风云与桃花源计划","节点4：10月26日-10月28日·桃花源碎与白水迷局","节点5：10月28-30日·虚幻崩塌与重启之局","节点6：10月30日-10月31日·灵灵异游戏与民国恩怨"]},{title:"第十篇章：世界大战篇",nodes:["节点1：2024年11月1日-11月3日·幽灵船余波与队长反击","节点2：2024年11月4日-11月5日·大洲市决战与幽灵船落幕","节点3：2024年11月6日-11月15日·鬼血沉寂与阴阳路计划","节点4：2024年11月-2084年11月·六十年的等待与新旧交替","节点5：2084年11月3日-11月5日·神明显化与灵异终结"]}];const chapterAccordion=document.getElementById(''chapter-accordion'');chapters.forEach((chap,idx)=>{const item=document.createElement(''div'');item.className=''chapter-item'';const btn=document.createElement(''button'');btn.className=''chapter-title clickable'';btn.innerText=chap.title;const nodesDiv=document.createElement(''div'');nodesDiv.className=''chapter-nodes'';chap.nodes.forEach(node=>{const n=document.createElement(''div'');n.className=''node-item'';n.innerText=node;nodesDiv.appendChild(n);});btn.addEventListener(''click'',()=>{item.classList.toggle(''active'');});item.appendChild(btn);item.appendChild(nodesDiv);chapterAccordion.appendChild(item);});const rosterData={main:[{name:''杨间'',desc:''代号【鬼眼】。亚洲区执法队长，终结时代的看门人。从七中敲门鬼事件绝境求生，一路踏着厉鬼与驭鬼者的尸骨登顶。体内驾驭了鬼眼（九层鬼域、范围重启）、无头鬼影（拼接肢解躯体）、鬼手（绝对压制）、鬼梦恶犬（意识拉入梦境）、骗人鬼（欺骗现实）、鬼火（焚烧灵异）。持有武器：鬼柴刀、红缨枪（镶嵌棺材钉）。他窃取鬼湖灵异重塑身躯化身彻底异类。最终为了终结灵异时代，他疯狂肢解融合万千恐怖源头成就终极神明形态，创造绝对封闭世界，化身看门人，将世间所有厉鬼拉入深渊永恒镇压。''},{name:''张伟'',desc:''阿伟。杨间的死党，运气逆天的普通人，自带极强的“搞笑抗性”。在无数次S级、A级灵异事件中奇迹生还，甚至敢在极其危险的灵异之地淡定地打电动游戏。被书迷戏称为“夜之帝王”。虽然他没有驾驭任何厉鬼，但他那近乎荒诞的乐观和生存能力，是杨间在逐渐丧失人性的过程中，为数不多能维系其情感锚点的存在。''},{name:''王珊珊'',desc:''鬼童饲养员。杨间的狂热追随者与绝对心腹。在七中敲门鬼事件后被灵异侵蚀，被杨间用鬼眼印记强行救下，变成了一种半人半鬼的异类存在。她失去了大部分人类的情感，变得极度冷漠，但对杨间有着绝对的忠诚。她负责饲养和控制极其恐怖的“鬼童”，是杨间大后方最坚实的护盾。''},{name:''李阳'',desc:''代号【堵门鬼】。杨间小队的核心成员。原本是被卷入鬼邮局事件的绝望信使，被杨间救下后成为其最忠诚的下属。驾驭了“鬼开门”与“鬼堵门”的灵异拼图，为人稳重、极其冷静，在处理鬼邮局、鬼湖等各大S级事件中发挥了不可替代的巨大作用，最终成长为独当一面的顶尖驭鬼者。''},{name:''童倩'',desc:''代号【鬼脸】。极少数在残酷的灵异世界中依然保留着真善美与强烈正义感的驭鬼者。拥有两张诡异的笑脸与哭脸，能够通过笑声和哭声进行大范围的灵异袭击。在中山市事件中险些丧命，被杨间救下并招募进小队。虽然她的理念与冷酷的杨间经常冲突，但她代表了人类在绝境中不屈的道德底线。''}],captains:[{name:''李军'',desc:''代号【鬼火】。亚洲总部绝对忠诚的卫士，王小明教授最信任的人。浑身燃烧着惨绿色的鬼火，行事作风刚正不阿，永远冲在处理灵异事件的第一线。即便在S级鬼画事件中为了断后而战死，他也凭借着守护人类的强烈执念，被王小明改造成异类重新复活，化身灰烬中的不屈英魂，继续为总部燃尽最后一丝光热。''},{name:''卫景'',desc:''代号【鬼差】。李军的搭档，由王小明主导的禁忌实验中诞生的怪物。他融合了S级厉鬼“鬼差”的部分灵异，拥有无解的“压制其他厉鬼”的可怕能力（落单必死规律）。他失去了作为人类的绝大部分特征，变得比鬼还要像鬼，是总部最恐怖的战略级威慑力量，如同黑暗中无情的行刑者。''},{name:''柳三'',desc:''代号【纸人】。保命能力天下第一的队长。没有人知道他的本体究竟在哪里，也没有人见过他的真面目。他通过漫山遍野、诡异至极的黄纸人来行动和收集情报。每一个纸人看似脆弱，实则蕴含着恐怖的灵异。在无数次团灭级别的危机中，他总能依靠纸人替死全身而退，是情报获取与消耗战的大师。''},{name:''曹洋'',desc:''总部十二队长之一，行事极其低调但实力深不可测。驾驭了极其罕见的灵异力量。在S级鬼湖事件中，他是少数能在鬼湖深处存活并带出关键情报的人。在与国王组织的幽灵船战役中，他展现出了惊人的压制力，是一个平时不显山露水，但在绝境中绝对可靠的顶尖战力。''},{name:''李乐平'',desc:''代号【遗忘鬼】。大川市负责人。他驾驭的厉鬼极其特殊，连他自己都会遗忘自己的身份和存在。任何看到他、记住他的人，都会遭受遗忘鬼的无解袭击，记忆被强行抹除。他是一个没有过去、没有名字的幽灵，为了不波及他人，他孤身一人镇压着大川市的灵异，是孤独而悲壮的守望者。''}]};function renderRoster(containerId,data){const container=document.getElementById(containerId);data.forEach(char=>{const btn=document.createElement(''button'');btn.className=''roster-item clickable'';btn.innerText=char.name;btn.style.transform=`rotate(${Math.random()*10-5}deg) translateY(${Math.random()*10-5}px)`;btn.addEventListener(''click'',()=>openModal(`【绝密档案：${char.name}】`,`<p class="lore-text blood-highlight" style="font-size:1.3rem;">身份确认完毕。正在调取绝密卷宗...</p><p class="lore-text">${char.desc}</p>`));container.appendChild(btn);});}renderRoster(''roster-main'',rosterData.main);renderRoster(''roster-captains'',rosterData.captains);const cfgName=document.getElementById(''cfg-name'');const cfgGender=document.getElementById(''cfg-gender'');const cfgIdentity=document.getElementById(''cfg-identity'');const cfgPersonality=document.getElementById(''cfg-personality'');const cfgFaction=document.getElementById(''cfg-faction'');const cfgFactionCustom=document.getElementById(''cfg-faction-custom'');const cfgTimeChapter=document.getElementById(''cfg-time-chapter'');const cfgTimeNode=document.getElementById(''cfg-time-node'');const cfgLifeform=document.getElementById(''cfg-lifeform'');const cfgGhost=document.getElementById(''cfg-ghost'');const cfgDeath=document.getElementById(''cfg-death'');const cfgCost=document.getElementById(''cfg-cost'');const cfgPower=document.getElementById(''cfg-power'');const cfgBg=document.getElementById(''cfg-bg'');const ghostConfigArea=document.getElementById(''ghost-config-area'');const previewBox=document.getElementById(''preview-box'');chapters.forEach(chap=>{const opt=document.createElement(''option'');opt.value=chap.title;opt.innerText=chap.title;cfgTimeChapter.appendChild(opt);});function updateNodes(){const selected=cfgTimeChapter.value;const chap=chapters.find(c=>c.title===selected);cfgTimeNode.innerHTML='''';if(chap&&chap.nodes){chap.nodes.forEach(node=>{const opt=document.createElement(''option'');opt.value=node;opt.innerText=node;cfgTimeNode.appendChild(opt);});}updatePreview();}cfgTimeChapter.addEventListener(''change'',updateNodes);cfgLifeform.addEventListener(''change'',(e)=>{if(e.target.value===''普通人''){ghostConfigArea.style.display=''none'';}else{ghostConfigArea.style.display=''block'';}updatePreview();});cfgFaction.addEventListener(''change'',(e)=>{if(e.target.value===''custom''){cfgFactionCustom.style.display=''block'';}else{cfgFactionCustom.style.display=''none'';}updatePreview();});const inputs=[cfgName,cfgGender,cfgIdentity,cfgPersonality,cfgFaction,cfgFactionCustom,cfgTimeNode,cfgLifeform,cfgGhost,cfgDeath,cfgCost,cfgPower,cfgBg];inputs.forEach(input=>input.addEventListener(''input'',updatePreview));function updatePreview(){const name=cfgName.value.trim()||''[未命名]'';const gender=cfgGender.value;const identity=cfgIdentity.value.trim()||''[未知社会身份]'';const personality=cfgPersonality.value.trim()||''[性格未鉴定]'';const faction=cfgFaction.value===''custom''%s(cfgFactionCustom.value.trim()||''[未知势力]''):cfgFaction.value;const timeChapter=cfgTimeChapter.value;const timeNode=cfgTimeNode.value;const lifeform=cfgLifeform.value;const bg=cfgBg.value.trim()||''暂无记录...'';let ghostText='''';if(lifeform!==''普通人''){const ghost=cfgGhost.value.trim()||''[尚未记录灵异拼图]'';const death=cfgDeath.value.trim()||''[尚未探明即死规律]'';const cost=cfgCost.value.trim()||''[尚未记录复苏代价]'';const power=cfgPower.value;ghostText=`\n【灵异拼图与境界】\n实力评级：${power}\n驾驭厉鬼：${ghost}\n即死条件(规律)：${death}\n复苏代价(反噬)：${cost}\n-------------------------`;}const text=`=========================\n【神秘复苏 - 绝密档案】\n=========================\n代号/姓名：${name}\n性别：${gender}\n社会身份：${identity}\n性格评估：${personality}\n生命形态：${lifeform}\n所属势力：${faction}\n介入篇章：${timeChapter}\n介入节点：${timeNode}\n-------------------------${ghostText}\n【背景故事与执念】\n${bg}\n=========================`;previewBox.innerText=text;}updateNodes();const btnSubmit=document.getElementById(''btn-submit'');const copyModal=document.getElementById(''copy-modal'');const btnCloseModal=document.getElementById(''btn-close-modal'');btnSubmit.addEventListener(''click'',()=>{const textToCopy=previewBox.innerText;const textarea=document.createElement(''textarea'');textarea.value=textToCopy;textarea.style.position=''fixed'';textarea.style.opacity=''0'';document.body.appendChild(textarea);textarea.select();try{document.execCommand(''copy'');copyModal.style.display=''flex'';setTimeout(()=>{copyModal.style.opacity=''1'';},10);}catch(err){alert(''复制失败，请手动选择预览框内容复制。'');}finally{document.body.removeChild(textarea);}});btnCloseModal.addEventListener(''click'',()=>{copyModal.style.opacity=''0'';setTimeout(()=>{copyModal.style.display=''none'';},300);});</script></body></html>', '玄幻', '2026-09-16 11:22:22', '2026-09-16 11:22:22', '', '', '[]', '') ON CONFLICT (id) DO NOTHING;
INSERT INTO stories (id, title, badge, cover_icon, cover_title, cover_subtitle, logo, theme_color, btn_gradient, handbook_json, roles_json, scenes_json, styles_json, first_turn_demo_json, custom_css, custom_html, category, created_at, updated_at, system_prompt, status_template, lorebook_json, post_history_instructions) VALUES ('059217c9-213b-48e7-b660-0c04f78ede48', '😱 末世求生录 😱 生存·性暴力·屈辱·征服·调教·末日', '末日废土 · 极境生存', '☣️', '末世求生录', '丧尸瘟疫核冬天 · 废土人性征服', '☣️', '#e17055', 'linear-gradient(135deg, #e17055 0%, #d63031 100%)', '{"desc": "在崩溃的世界中挣扎求生，你的极限生存在多少天。玩家在开局选择末世类型（丧尸、核战、瘟疫等22种题材），在资源匮乏、危机四伏的废土中寻找生存之路。体力、饥饿、口渴与性压抑的人性试炼。", "author": "AI风月精选"}', '[{"name": "苏晓染", "role": "21岁医学院校花幸存者 (167cm / 49kg / D罩杯)", "desc": "灾变前是全校公认的高岭之花医学生。末日爆发后在外独自逃亡三天，弹尽粮绝、衣衫破烂。为了获得一口干净的水和避难所的接纳，尊严与骄傲已被现实碾得粉碎，愿意接受一切屈辱的生存交换。"}, {"name": "玩家 (避难所支配者)", "role": "废土安全屋主宰", "desc": "掌控坚固地下防空洞、充足柴油、纯净水与武器储备的冷酷生存大师。"}]', '[{"title": "地下防空洞核心安全屋", "desc": "重型防爆钢门紧闭，柴油发电机轰鸣，桌上摆着纯净水与压缩饼干"}, {"title": "避难所消毒与检疫铁笼", "desc": "泛着锈迹与血斑的铁栏，剥光衣物进行全身体表感染排查的冰冷之地"}, {"title": "地表废墟物资搜刮掩体", "desc": "辐射酸雨滋滋作响的装甲车废墟，丧尸与掠夺者游荡的危险荒原"}]', '{}', '{"location": "避难所地下核心安全屋 · 辐射暴雨夜", "story": "厚重斑驳的防爆钢门将外界丧尸刺耳的抓挠声与酸雨腐蚀声彻底隔绝。\n防空洞深处，柴油发电机发出沉闷有力的轰鸣，昏黄的白炽灯在金属墙壁上投下斑驳长影。你坐在弹药箱上擦拭着自动霰弹枪，旁边的折叠桌上整齐地摆放着两瓶密封矿泉水、三袋军用高能压缩饼干与几板未拆封的阿莫西林抗生素——在这片秩序崩坏的废土上，这些就是主宰生死的硬通货。\n沉重的安全门闸传来转动声，一个被守卫反绑双手的年轻女人被粗暴地推倒在冰冷的水泥地上。\n她曾是医学院万人瞩目的清纯校花苏晓染。此刻，她身上的白衬衫与牛仔裤已被撕裂得多处走光，白皙如玉的肌肤上满是泥泞与擦伤，胸前发育绝佳的D罩杯双峰随着剧烈喘息大幅度起伏。干裂泛白的嘴唇紧紧抿着，饥饿与干渴让她浑身不受控制地发颤，眼神在触及桌上矿泉水的瞬间爆发出野兽般贪婪而绝望的渴望：“求求你……给我一口水喝……只要让我留在这……你让我做什么都可以……”", "branches": [{"tag": "A", "title": "拧开水壶倒出一小杯清水，命令她像狗一样爬过来喝", "desc": "以残酷的废土生存法则直接剥夺其残存的文明自尊，建立绝对的主奴支配从属【屈辱驯服: 击碎昔日校花自尊，以物资确立终身依附】"}, {"tag": "B", "title": "递过抗生素与半块压缩饼干，严肃考查其临床医学价值", "desc": "保持冷静克制，利用食物交换其医疗技能为庇护所团队服务【理性统合: 评估实用价值，建立高效分工契约】"}, {"tag": "C", "title": "举枪冷漠示意她退后，命令其当场脱光接受感染排查", "desc": "严厉执行末世防疫铁律，要求其脱掉所有衣物仔细检查全身有无抓伤咬痕【严苛检疫: 杜绝致命隐患，借检疫之名将春光尽收眼底】"}, {"tag": "D", "title": "反锁厚重防爆门，居高临下挑起她下巴行使领主特权", "desc": "当着她的面关上唯一生路，用粗糙的掌心揉捏其下颌迫使其屈从献身【强势占有: 撕碎所有文明遮羞布，直接确立私人肉便器地位】"}]}', '/* --- 末世科技风格（暗色系红色点缀）--- */

/* 1. 全局包裹层：高科技废土 */
.survival-interface {
    background: linear-gradient(135deg, #1a1d23 0%, #0f1115 100%);
    border-radius: 16px;
    padding: 24px;
    box-shadow: 
        0 20px 60px rgba(0, 0, 0, 0.5),
        0 0 0 1px rgba(239, 68, 68, 0.05) inset;
    position: relative;
    color: #c4c4c4;
    font-family: ''Segoe UI'', ''Roboto'', ''Microsoft YaHei'', sans-serif;
    line-height: 1.7;
    max-width: 900px;
    margin: 0 auto;
    overflow: hidden;
}

/* 顶部光晕效果 */
.survival-interface::after {
    content: '''';
    position: absolute;
    top: -50%; left: -50%;
    width: 200%; height: 200%;
    background: radial-gradient(circle at 20% 20%, rgba(239, 68, 68, 0.08) 0%, transparent 50%);
    pointer-events: none;
}

/* --- 1. 时间轴：现代终端风格 --- */
code.language-Time {
    display: block;
    background: linear-gradient(135deg, #0a0c10 0%, #13151a 100%);
    border: 1px solid rgba(239, 68, 68, 0.2);
    border-left: 4px solid #dc2626;
    padding: 16px 24px;
    color: #fca5a5;
    font-family: ''JetBrains Mono'', ''Fira Code'', monospace;
    margin-bottom: 24px;
    white-space: pre-wrap;
    box-shadow: 
        0 4px 20px rgba(0, 0, 0, 0.3),
        inset 0 1px 0 rgba(255, 255, 255, 0.05);
    position: relative;
    border-radius: 8px;
}

/* --- 2. 折叠栏：玻璃卡片风格 --- */
details {
    border-radius: 12px;
    overflow: hidden;
    background: transparent;
    border: none;
    margin-bottom: 12px;
    transition: all 0.3s ease;
}

details[open] {
    /* 打开时不需要额外样式 */
}

summary {
    display: flex;
    align-items: center;
    padding: 16px 24px;
    font-weight: 600;
    color: #e0e0e0;
    background: rgba(26, 29, 35, 0.8);
    cursor: pointer;
    list-style: none;
    text-transform: uppercase;
    letter-spacing: 1px;
    transition: all 0.3s ease;
    position: relative;
    font-size: 14px;
    border-radius: 12px;
    border: 1px solid rgba(255, 255, 255, 0.08);
    backdrop-filter: blur(10px);
}

summary:hover {
    background: rgba(40, 44, 52, 0.9);
    color: #fff;
    border-color: rgba(239, 68, 68, 0.3);
}

/* 发光指示器 */
summary::before {
    content: ''▸'';
    margin-right: 12px;
    color: #dc2626;
    font-size: 12px;
    transition: transform 0.3s ease;
}

details[open] > summary::before {
    transform: rotate(90deg);
    color: #fca5a5;
}

/* 状态标签 */
summary::after {
    content: ''OFFLINE'';
    font-size: 10px;
    position: absolute;
    right: 24px;
    padding: 4px 10px;
    border-radius: 20px;
    background: rgba(239, 68, 68, 0.2);
    color: #ef4444;
    font-weight: 500;
    transition: all 0.3s ease;
}

details[open] > summary::after {
    content: ''ONLINE'';
    background: rgba(220, 38, 38, 0.2);
    color: #dc2626;
}

/* 🎯 折叠内容区：独立的深色卡片风格 */
details > *:not(summary) {
    background: linear-gradient(135deg, #252932 0%, #1a1d23 100%);
    margin-top: 8px;
    padding: 20px 24px;
    color: #c4c4c4;
    line-height: 1.7;
    font-size: 15px;
    position: relative;
    border-radius: 12px;
    border: 1px solid rgba(255, 255, 255, 0.08);
    box-shadow: 
        0 4px 20px rgba(0, 0, 0, 0.3),
        inset 0 1px 0 rgba(255, 255, 255, 0.05);
}

/* --- 3. 警告与威胁：现代化徽章 --- */
.threat-level {
    background: linear-gradient(135deg, rgba(239, 68, 68, 0.15) 0%, rgba(239, 68, 68, 0.05) 100%);
    color: #ef4444;
    padding: 6px 14px;
    font-weight: 600;
    border-radius: 20px;
    font-size: 12px;
    border: 1px solid rgba(239, 68, 68, 0.3);
    text-transform: uppercase;
    letter-spacing: 1px;
    display: inline-flex;
    align-items: center;
    gap: 6px;
}

.threat-level::before {
    content: ''⚠'';
    font-size: 10px;
}

.threat-level.low {
    background: linear-gradient(135deg, rgba(245, 158, 11, 0.15) 0%, rgba(245, 158, 11, 0.05) 100%);
    color: #f59e0b;
    border-color: rgba(245, 158, 11, 0.3);
}

.threat-level.low::before {
    content: ''⚡'';
}

.threat-level.medium {
    background: linear-gradient(135deg, rgba(249, 115, 22, 0.15) 0%, rgba(249, 115, 22, 0.05) 100%);
    color: #f97316;
    border-color: rgba(249, 115, 22, 0.3);
}

.threat-level.medium::before {
    content: ''◆'';
}

.threat-level.high {
    background: linear-gradient(135deg, rgba(220, 38, 38, 0.2) 0%, rgba(220, 38, 38, 0.08) 100%);
    color: #dc2626;
    border-color: rgba(220, 38, 38, 0.5);
    animation: threat-pulse 2s ease-in-out infinite;
}

.threat-level.high::before {
    content: ''⚠'';
}

@keyframes threat-pulse {
    0%, 100% { 
        box-shadow: 0 0 0 0 rgba(220, 38, 38, 0.4);
    }
    50% { 
        box-shadow: 0 0 0 8px rgba(220, 38, 38, 0);
    }
}

/* --- 4. 记忆栏与档案：数据卡片风格 --- */
.memory-zone {
    border: 1px solid rgba(255, 255, 255, 0.08);
    background: rgba(26, 29, 35, 0.4);
    padding: 0;
    border-radius: 12px;
    margin-top: 16px;
    overflow: hidden;
    backdrop-filter: blur(10px);
}

/* 档案标题 */
.memory-zone-header {
    display: block;
    background: linear-gradient(135deg, #dc2626 0%, #b91c1c 100%);
    color: #fff;
    padding: 14px 24px;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 2px;
    font-size: 12px;
    position: relative;
}

.memory-zone-header::before {
    content: ''📊'';
    margin-right: 8px;
}

.memory-item {
    border-bottom: 1px solid rgba(255, 255, 255, 0.05);
    padding: 14px 24px;
    position: relative;
    transition: all 0.3s ease;
    color: #c4c4c4;
}

.memory-item::before {
    content: '''';
    position: absolute;
    left: 12px;
    top: 50%;
    transform: translateY(-50%);
    width: 4px;
    height: 4px;
    background: #dc2626;
    border-radius: 50%;
    box-shadow: 0 0 8px rgba(220, 38, 38, 0.5);
}

.memory-item:hover {
    background: rgba(220, 38, 38, 0.05);
    padding-left: 32px;
}

.memory-item:last-child {
    border-bottom: none;
}

/* --- 5. 分割线：现代分割线 --- */
hr {
    border: 0;
    height: 1px;
    background: linear-gradient(to right, transparent, rgba(239, 68, 68, 0.1), transparent);
    margin: 32px 0;
    position: relative;
}

/* --- 6. 强调文本：高亮标记 --- */
strong {
    color: #fca5a5;
    background: rgba(239, 68, 68, 0.1);
    padding: 2px 8px;
    border-radius: 4px;
    font-weight: 600;
}

/* --- 7. 状态块和选项块：代码编辑器风格 --- */
.status-block, .options-block {
    background: linear-gradient(135deg, #0f1115 0%, #1a1d23 100%);
    border-radius: 12px;
    padding: 20px 24px;
    font-family: ''JetBrains Mono'', ''Fira Code'', monospace;
    font-size: 14px;
    line-height: 1.8;
    border: 1px solid rgba(255, 255, 255, 0.08);
    border-left: 4px solid #dc2626;
    white-space: pre-wrap;
    word-break: break-word;
    box-shadow: 0 4px 20px rgba(0, 0, 0, 0.2);
    color: #c4c4c4;
    position: relative;
}

/* 行号装饰 */
.status-block::before,
.options-block::before {
    content: '''';
    position: absolute;
    top: 0; left: 0; width: 4px; height: 100%;
    background: linear-gradient(180deg, #dc2626 0%, #b91c1c 100%);
}

/* --- 8. 响应式调整 --- */
@media (max-width: 768px) {
    .survival-interface {
        padding: 16px;
        border-radius: 12px;
    }
    
    summary {
        padding: 14px 20px;
        font-size: 13px;
    }
    
    summary::after {
        right: 20px;
        font-size: 9px;
    }
    
    .memory-zone-header {
        font-size: 11px;
        padding: 12px 20px;
    }
    
    .memory-item {
        padding: 12px 20px;
        font-size: 14px;
    }
    
    .status-block, .options-block {
        padding: 16px 20px;
        font-size: 13px;
    }
    
    details > *:not(summary) {
        padding: 16px 20px;
        font-size: 14px;
    }
}

/* --- 9. 对话颜色规范（现代风格）--- */
/* 玩家言语（暗红色） */
font[color="#00c6c6"],
.dialog-player {
    color: #ef4444 !important;
    font-weight: 600;
    background: rgba(239, 68, 68, 0.1);
    padding: 2px 8px;
    border-radius: 4px;
}

/* 女性NPC言语（粉紫色） */
font[color="#FF2D2D"],
.dialog-female {
    color: #fca5a5 !important;
    font-style: italic;
    background: rgba(252, 165, 165, 0.1);
    padding: 2px 8px;
    border-radius: 4px;
}

/* 男性NPC言语（橙红色） */
font[color="#ea0029"],
.dialog-male {
    color: #f97316 !important;
    font-weight: 600;
    background: rgba(249, 115, 22, 0.1);
    padding: 2px 8px;
    border-radius: 4px;
}

/* --- 10. 实用工具类 --- */
.glow-indigo {
    color: #dc2626;
    text-shadow: 0 0 20px rgba(220, 38, 38, 0.5);
}

.border-glass {
    border: 1px solid rgba(255, 255, 255, 0.1);
    backdrop-filter: blur(10px);
}

.bg-dark-tech {
    background: linear-gradient(135deg, #1a1d23 0%, #0f1115 100%);
}

.text-gradient {
    background: linear-gradient(135deg, #dc2626 0%, #ef4444 100%);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
}

.card-hover {
    transition: all 0.3s ease;
}

.card-hover:hover {
    transform: translateY(-2px);
    box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
}', '<!DOCTYPE html>
<html lang="zh-CN">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>末世生存档案</title>
  <script src="https://cdn.tailwindcss.com"></script>
  <style>
    /* --- 末世科技风格 (精致版) --- */
    
    body {
      margin: 0;
      padding: 0;
      font-family: ''Segoe UI'', ''Roboto'', ''Microsoft YaHei'', sans-serif;
      background: url(''https://i.postimg.cc/J0hd1jJ6/1.png'') center/cover no-repeat fixed;
      min-height: 100vh;
      color: #c4c4c4;
      line-height: 1.7;
    }
    
    body::before {
      content: '''';
      position: fixed;
      top: 0; left: 0; width: 100%; height: 100%;
      background: linear-gradient(135deg, rgba(0, 0, 0, 0.3) 0%, rgba(0, 0, 0, 0.4) 100%);
      z-index: 0;
    }
    
    .tech-container {
      position: relative;
      min-height: 100vh;
      padding: 24px;
      z-index: 1;
    }
    
    .tech-music-btn {
      width: 56px;
      height: 56px;
      background: linear-gradient(135deg, #252932 0%, #1a1d23 100%);
      border: 2px solid rgba(255, 255, 255, 0.1);
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      cursor: pointer;
      transition: all 0.3s ease;
      box-shadow: 0 4px 15px rgba(0, 0, 0, 0.3);
      position: relative;
      z-index: 10;
      pointer-events: auto;
    }
    
    .tech-music-btn:hover {
      transform: scale(1.1);
      border-color: rgba(255, 255, 255, 0.3);
      box-shadow: 0 6px 20px rgba(0, 0, 0, 0.4), 0 0 20px rgba(255, 255, 255, 0.1);
    }
    
    .tech-action-card {
      background: linear-gradient(135deg, #252932 0%, #1a1d23 100%);
      border: 1px solid rgba(255, 255, 255, 0.08);
      border-radius: 12px;
      padding: 12px 24px;
      min-width: 200px;
      cursor: pointer;
      transition: all 0.3s ease;
      position: relative;
      box-shadow: 0 4px 15px rgba(0, 0, 0, 0.2);
    }
    
    .tech-action-card:hover {
      transform: translateY(-2px);
      border-color: rgba(255, 255, 255, 0.2);
      box-shadow: 0 6px 25px rgba(0, 0, 0, 0.3), 0 0 20px rgba(255, 255, 255, 0.05);
    }
    
    .tech-action-card::before {
      content: '''';
      position: absolute;
      top: -4px;
      left: 50%;
      transform: translateX(-50%);
      width: 40px;
      height: 12px;
      background: rgba(255, 255, 255, 0.05);
      border-radius: 6px;
      backdrop-filter: blur(5px);
    }
    
    .tech-modal-overlay {
      position: fixed;
      inset: 0;
      background: rgba(0, 0, 0, 0.8);
      backdrop-filter: blur(10px);
      z-index: 50;
      display: none;
      align-items: center;
      justify-content: center;
      padding: 24px;
    }
    
    .tech-modal-overlay.active {
      display: flex;
    }
    
    .tech-modal {
      background: linear-gradient(135deg, #252932 0%, #1a1d23 100%);
      border: 1px solid rgba(255, 255, 255, 0.08);
      border-radius: 16px;
      max-width: 800px;
      width: 100%;
      max-height: 80vh;
      display: flex;
      flex-direction: column;
      overflow: hidden;
      box-shadow: 0 20px 60px rgba(0, 0, 0, 0.5);
    }
    
    .tech-modal-header {
      padding: 24px;
      border-bottom: 1px solid rgba(255, 255, 255, 0.1);
      display: flex;
      justify-content: space-between;
      align-items: center;
      background: rgba(0, 0, 0, 0.2);
    }
    
    .tech-modal-content {
      padding: 24px;
      overflow-y: auto;
      flex: 1;
    }
    
    .tech-modal-content::-webkit-scrollbar {
      width: 8px;
    }
    
    .tech-modal-content::-webkit-scrollbar-track {
      background: rgba(0, 0, 0, 0.2);
    }
    
    .tech-modal-content::-webkit-scrollbar-thumb {
      background: rgba(255, 255, 255, 0.2);
      border-radius: 4px;
    }
    
    .tech-input {
      width: 100%;
      padding: 12px 16px;
      background: rgba(0, 0, 0, 0.3);
      border: 1px solid rgba(255, 255, 255, 0.1);
      border-radius: 8px;
      color: #c4c4c4;
      font-size: 14px;
      transition: all 0.3s ease;
      font-family: inherit;
    }
    
    .tech-input:focus {
      outline: none;
      border-color: rgba(255, 255, 255, 0.3);
      box-shadow: 0 0 0 3px rgba(255, 255, 255, 0.05);
    }
    
    .tech-input::placeholder {
      color: rgba(196, 196, 196, 0.5);
    }
    
    .tech-label {
      display: block;
      margin-bottom: 8px;
      color: #e0e0e0;
      font-size: 12px;
      font-weight: 500;
    }
    
    .tech-btn {
      padding: 10px 20px;
      background: linear-gradient(135deg, #ffffff 0%, #d4d4d4 100%);
      color: #1a1d23;
      border: none;
      border-radius: 8px;
      font-weight: 600;
      cursor: pointer;
      transition: all 0.3s ease;
      font-size: 14px;
    }
    
    .tech-btn:hover {
      transform: translateY(-1px);
      box-shadow: 0 4px 15px rgba(255, 255, 255, 0.2);
    }
    
    .tech-btn:disabled {
      opacity: 0.4;
      cursor: not-allowed;
      text-decoration: line-through;
    }
    
    .tech-toast {
      position: fixed;
      top: 50%;
      left: 50%;
      transform: translate(-50%, -50%);
      z-index: 60;
      display: none;
      align-items: center;
      justify-content: center;
      pointer-events: none;
    }
    
    .tech-toast.active {
      display: flex;
    }
    
    .tech-toast-content {
      background: linear-gradient(135deg, #252932 0%, #1a1d23 100%);
      border: 1px solid rgba(255, 255, 255, 0.08);
      border-radius: 12px;
      padding: 16px 24px;
      box-shadow: 0 8px 32px rgba(0, 0, 0, 0.5);
      pointer-events: auto;
    }
    
    .tech-info-block {
      background: rgba(0, 0, 0, 0.3);
      border: 1px solid rgba(255, 255, 255, 0.08);
      border-radius: 12px;
      padding: 16px;
      margin-bottom: 16px;
    }
    
    .tech-info-block-title {
      font-size: 12px;
      font-weight: 600;
      color: #ffffff;
      margin-bottom: 12px;
      text-transform: uppercase;
      letter-spacing: 2px;
    }
    
    .tech-preview-item {
      background: rgba(0, 0, 0, 0.3);
      border: 1px solid rgba(255, 255, 255, 0.08);
      border-radius: 8px;
      padding: 12px 16px;
      margin-bottom: 8px;
    }
    
    .tech-preview-label {
      color: #ffffff;
      font-size: 13px;
      font-weight: 600;
    }
    
    .tech-preview-value {
      color: #c4c4c4;
      font-size: 14px;
      margin-top: 4px;
    }
    
    details {
      border-radius: 12px;
      overflow: hidden;
      background: transparent;
      border: none;
      margin-bottom: 12px;
      transition: all 0.3s ease;
    }
    
    summary {
      display: flex;
      align-items: center;
      padding: 16px 24px;
      font-weight: 600;
      color: #e0e0e0;
      background: rgba(26, 29, 35, 0.8);
      cursor: pointer;
      list-style: none;
      text-transform: uppercase;
      letter-spacing: 1px;
      transition: all 0.3s ease;
      position: relative;
      font-size: 14px;
      border-radius: 12px;
      border: 1px solid rgba(255, 255, 255, 0.08);
      backdrop-filter: blur(10px);
    }
    
    summary:hover {
      background: rgba(40, 44, 52, 0.9);
      color: #fff;
      border-color: rgba(255, 255, 255, 0.2);
    }
    
    summary::before {
      content: ''▸'';
      margin-right: 12px;
      color: #ffffff;
      font-size: 12px;
      transition: transform 0.3s ease;
    }
    
    details[open] > summary::before {
      transform: rotate(90deg);
      color: #ffffff;
    }
    
    details[open] > summary {
      background: rgba(0, 0, 0, 0.4);
      border-bottom: 1px solid rgba(255, 255, 255, 0.2);
      border-radius: 12px 12px 0 0;
    }
    
    details > *:not(summary) {
      background: linear-gradient(135deg, #252932 0%, #1a1d23 100%);
      margin-top: 0;
      padding: 20px 24px;
      color: #c4c4c4;
      line-height: 1.7;
      font-size: 15px;
      position: relative;
      border-radius: 0 0 12px 12px;
      border: 1px solid rgba(255, 255, 255, 0.08);
      border-top: none;
      box-shadow: 
        0 4px 20px rgba(0, 0, 0, 0.3),
        inset 0 1px 0 rgba(255, 255, 255, 0.05);
    }
    
    .checkbox-wrapper {
      display: flex;
      align-items: center;
      gap: 12px;
      padding: 12px;
      background: rgba(0, 0, 0, 0.3);
      border: 1px solid rgba(255, 255, 255, 0.08);
      border-radius: 8px;
      cursor: pointer;
      transition: all 0.3s ease;
    }
    
    .checkbox-wrapper:hover {
      border-color: rgba(255, 255, 255, 0.2);
      background: rgba(0, 0, 0, 0.4);
    }
    
    .checkbox-wrapper input[type="checkbox"] {
      width: 20px;
      height: 20px;
      accent-color: #ffffff;
      cursor: pointer;
    }
    
    .country-grid {
      display: grid;
      grid-template-columns: repeat(auto-fill, minmax(100px, 1fr));
      gap: 8px;
    }
    
    .country-btn, .region-type-btn, .job-btn {
      padding: 8px 12px;
      background: rgba(0, 0, 0, 0.3);
      border: 1px solid rgba(255, 255, 255, 0.1);
      border-radius: 6px;
      color: #c4c4c4;
      cursor: pointer;
      transition: all 0.3s ease;
      font-size: 12px;
    }
    
    .country-btn:hover, .country-btn.selected, .region-type-btn:hover, .region-type-btn.selected, .job-btn:hover, .job-btn.selected {
      background: rgba(255, 255, 255, 0.1);
      border-color: rgba(255, 255, 255, 0.3);
      color: #fff;
    }
    
    .country-btn.selected, .region-type-btn.selected, .job-btn.selected {
      background: rgba(255, 255, 255, 0.2);
      box-shadow: 0 0 10px rgba(255, 255, 255, 0.2);
    }
    
    .timeline-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 12px;
    }
    
    .timeline-btn {
      padding: 16px;
      background: rgba(0, 0, 0, 0.3);
      border: 1px solid rgba(255, 255, 255, 0.1);
      border-radius: 8px;
      color: #c4c4c4;
      cursor: pointer;
      transition: all 0.3s ease;
      text-align: center;
    }
    
    .timeline-btn:hover, .timeline-btn.selected {
      background: rgba(255, 255, 255, 0.1);
      border-color: rgba(255, 255, 255, 0.3);
      color: #fff;
      transform: translateY(-2px);
    }
    
    .timeline-btn.selected {
      background: rgba(255, 255, 255, 0.2);
      box-shadow: 0 4px 15px rgba(255, 255, 255, 0.15);
    }
    
    @media (max-width: 768px) {
      .tech-container {
        padding: 16px;
      }
      
      .tech-action-card {
        width: calc(50% - 8px);
        padding: 10px 16px;
        min-width: unset;
      }
      
      .timeline-grid {
        grid-template-columns: 1fr;
      }
      
      .country-grid {
        grid-template-columns: repeat(2, 1fr);
      }
    }
  </style>
</head>
<body>
  <div class="bg-grid"></div>
  <div class="bg-glow"></div>
  
  <div id="app" class="tech-container">
    <!-- 音频元素 -->
    <audio id="bg-music" loop preload="auto">
      <source src="https://cdn.jsdelivr.net/gh/QingFgg/xueshizi/xueshizi.mp3" type="audio/mpeg" />
      <source src="https://raw.githubusercontent.com/QingFgg/xueshizi/main/xueshizi.mp3" type="audio/mpeg" />
    </audio>
    
    <!-- 主要内容 -->
    <div class="flex flex-col min-h-[calc(100vh-48px)]">
      <!-- 顶部区域 - 音乐按钮 -->
      <div class="flex justify-end mb-8">
        <button id="music-ctrl" class="tech-music-btn">
          <span class="text-2xl">🔇</span>
        </button>
      </div>
      
      <!-- 下方的功能按钮 -->
      <div class="flex-1 flex flex-col justify-end pb-8">
        <div class="max-w-5xl mx-auto w-full">
          <div class="flex flex-wrap md:flex-nowrap justify-center gap-4">
            <!-- 功能按钮1 - 作者劝告 -->
            <div class="tech-action-card" onclick="openModal(''advice'')">
              <div class="flex items-center justify-center gap-2">
                <span class="text-xl">⚠️</span>
                <span class="text-white font-medium">作者劝告</span>
              </div>
            </div>
            
            <!-- 功能按钮2 - 世界背景 -->
            <div class="tech-action-card" onclick="openModal(''world'')">
              <div class="flex items-center justify-center gap-2">
                <span class="text-xl">🌍</span>
                <span class="text-white font-medium">世界背景</span>
              </div>
            </div>
            
            <!-- 功能按钮3 - 角色创建 -->
            <div class="tech-action-card" onclick="openModal(''custom'')">
              <div class="flex items-center justify-center gap-2">
                <span class="text-xl">🎮</span>
                <span class="text-white font-medium">角色创建</span>
              </div>
            </div>
            
            <!-- 功能按钮4 - 角色档案 -->
            <div class="tech-action-card" onclick="openModal(''preview'')">
              <div class="flex items-center justify-center gap-2">
                <span class="text-xl">📋</span>
                <span class="text-white font-medium">角色档案</span>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
    
    <!-- 弹窗遮罩 -->
    <div id="modalOverlay" class="tech-modal-overlay" onclick="closeModal()">
      <div class="tech-modal" onclick="event.stopPropagation()">
        <!-- 弹窗头部 -->
        <div class="tech-modal-header">
          <h2 id="modalTitle" class="text-xl font-bold text-white"></h2>
          <button onclick="closeModal()" class="text-gray-400 hover:text-white text-2xl transition-colors">✕</button>
        </div>
        <!-- 弹窗内容 -->
        <div id="modalContent" class="tech-modal-content"></div>
      </div>
    </div>
    
    <!-- 提示框 -->
    <div id="toastOverlay" class="tech-toast">
      <div class="tech-toast-content">
        <div class="flex items-center gap-2">
          <span id="toastIcon" class="text-xl">✅</span>
          <span id="toastText" class="text-white font-medium">操作成功</span>
        </div>
      </div>
    </div>
    
    <!-- 警告弹窗 -->
    <div id="warningOverlay" class="tech-modal-overlay" style="z-index: 100;">
      <div class="tech-modal" style="max-width: 400px;">
        <div class="tech-modal-header" style="border-color: rgba(239, 68, 68, 0.3);">
          <h2 class="text-xl font-bold text-red-400">⚠️ 内容警告</h2>
        </div>
        <div class="tech-modal-content text-center">
          <p class="text-gray-300 mb-6">本卡随机事件紧凑，生存难度极高，内容可能引起不适，不喜欢这类可以退出，请勿随意差评！   ** 请谨慎选择 **</p>
          <button onclick="closeWarning()" class="tech-btn w-full">我已知晓</button>
        </div>
      </div>
    </div>

    <!-- 音乐初始化弹窗 -->
    <div id="music-init" class="tech-modal-overlay" style="z-index: 99;">
      <div class="tech-modal" style="max-width: 400px;">
        <div class="tech-modal-header" style="border-color: rgba(239, 68, 68, 0.3);">
          <h2 class="text-xl font-bold text-red-400">🎵 背景音乐</h2>
        </div>
        <div class="tech-modal-content text-center">
          <p class="text-gray-300 mb-4">是否开启沉浸背景音乐？</p>
          <p class="text-xs text-gray-400 mb-6"><span style="color: red;">(需要开启VPN因为音乐是GitHub部署的)</span></p>
          <div class="space-y-3">
            <button onclick="initMusic(true)" class="tech-btn w-full">开启播放</button>
            <button onclick="initMusic(false)" class="tech-btn w-full" style="background: linear-gradient(135deg, #555 0%, #444 100%);">保持静音</button>
          </div>
        </div>
      </div>
    </div>
  </div>

  <script>
    var memoryStorage = {};
    var useLocalStorage = true;
    
    function isLocalStorageAvailable() {
      try {
        var test = ''__test__'';
        localStorage.setItem(test, test);
        localStorage.removeItem(test);
        return true;
      } catch (e) {
        return false;
      }
    }
    
    function isFileProtocol() {
      return window.location.protocol === ''file:'';
    }
    
    function saveData(key, value) {
      if (useLocalStorage && isLocalStorageAvailable()) {
        localStorage.setItem(key, value);
      } else {
        memoryStorage[key] = value;
      }
    }
    
    function loadData(key) {
      if (useLocalStorage && isLocalStorageAvailable()) {
        return localStorage.getItem(key);
      } else {
        return memoryStorage[key] || null;
      }
    }
    
    function initApp() {
      console.log(''initApp 开始执行'');
      var app = document.getElementById(''app'');
      if (!app) {
        console.error(''App element not found'');
        return;
      }
      console.log(''App 元素找到，继续执行'');

      // 检查音频元素
      bgMusic = document.getElementById(''bg-music'');
      if (!bgMusic) {
        console.warn(''音频元素未找到'');
      } else {
        console.log(''音频元素已找到，readyState:'', bgMusic.readyState);
        // 监听音频加载事件
        bgMusic.addEventListener(''error'', function(e) {
          console.error(''音频加载错误:'', e);
          alert(''音乐文件加载失败，可能是网络问题或CDN访问受限'');
        });
      }
      
      // 显示警告弹窗
      var warningOverlay = document.getElementById(''warningOverlay'');
      if (warningOverlay) {
        warningOverlay.classList.add(''active'');
      }
      
      window.showToast = function(message, icon) {
        var toastOverlay = document.getElementById(''toastOverlay'');
        var toastText = document.getElementById(''toastText'');
        var toastIcon = document.getElementById(''toastIcon'');
        if (!toastOverlay || !toastText || !toastIcon) return;
        
        toastText.textContent = message;
        toastIcon.textContent = icon || ''✅'';
        
        toastOverlay.classList.add(''active'');
        setTimeout(function() {
          toastOverlay.classList.remove(''active'');
        }, 2000);
      };
      
      // 音乐控制
      var bgMusic = document.getElementById(''bg-music'');
      var musicCtrl = document.getElementById(''music-ctrl'');
      var isPlaying = false;
      var musicRetryCount = 0;
      var maxRetries = 3;
      
      // 音乐初始化
      window.initMusic = function(shouldPlay) {
        var musicInit = document.getElementById(''music-init'');
        if (musicInit) {
          musicInit.classList.remove(''active'');
        }
        
        if (shouldPlay && bgMusic) {
          // 重置重试计数
          musicRetryCount = 0;
          
          // 设置音量
          bgMusic.volume = 0.3;
          
          // 尝试加载音频
          if (bgMusic.readyState === 0) {
            // 音频未加载，等待加载完成
            bgMusic.addEventListener(''canplaythrough'', function onCanPlay() {
              bgMusic.removeEventListener(''canplaythrough'', onCanPlay);
              playMusic();
            }, { once: true });
            
            // 设置超时
            setTimeout(function() {
              if (bgMusic.readyState < 2) {
                console.warn(''音频加载超时，尝试播放'');
                playMusic();
              }
            }, 5000);
          } else {
            playMusic();
          }
        }
      };
      
      // 播放音乐
      function playMusic() {
        if (!bgMusic) return;
        
        bgMusic.play().then(function() {
          isPlaying = true;
          musicCtrl.innerHTML = ''<span class="text-2xl">🩸</span>'';
          console.log(''音乐已开启'');
          musicRetryCount = 0;
        }).catch(function(error) {
          console.error(''音乐播放失败:'', error);
          musicRetryCount++;
          
          if (musicRetryCount <= maxRetries) {
            console.log(''尝试重新播放 ('' + musicRetryCount + ''/'' + maxRetries + '')'');
            setTimeout(playMusic, 1000);
          } else {
            isPlaying = false;
            musicCtrl.innerHTML = ''<span class="text-2xl">🔇</span>'';
            var errorMsg = ''音乐播放失败，可能原因：\n1. 网络连接问题\n2. CDN访问受限\n3. 浏览器阻止自动播放\n\n建议：\n- 检查网络连接\n- 尝试刷新页面\n- 手动点击音乐按钮'';
            alert(errorMsg);
          }
        });
      }
      
      // 音乐开关
      musicCtrl.onclick = function() {
        if (!bgMusic) {
          alert(''音频组件未加载，请刷新页面重试'');
          return;
        }
        
        if (isPlaying) {
          bgMusic.pause();
          isPlaying = false;
          musicCtrl.innerHTML = ''<span class="text-2xl">🔇</span>'';
          console.log(''音乐已关闭'');
        } else {
          musicRetryCount = 0;
          playMusic();
        }
      };
      
      // 自动保存
      window.autoSave = function() {
        function getValue(id) {
          var el = document.getElementById(id);
          return el %s el.value : '''';
        }
        function getCheckboxValue(id) {
          var el = document.getElementById(id);
          return el %s el.checked : false;
        }
        function getSelectedValue(className) {
          var els = document.querySelectorAll(''.'' + className + ''.selected'');
          var values = [];
          els.forEach(function(el) {
            var text = el.getAttribute(''data-text'') || el.textContent;
            values.push(text);
          });
          return values.join('', '');
        }
        
        var characterData = {
          country: getSelectedValue(''country-btn''),
          regionType: getSelectedValue(''region-type-btn''),
          customRegion: getValue(''customRegion''),
          job: getSelectedValue(''job-btn''),
          customJob: getValue(''customJob''),
          disasterType: getValue(''charDisasterType''),
          timeline: getSelectedValue(''timeline-btn''),
          name: getValue(''charName''),
          gender: getValue(''charGender''),
          age: getValue(''charAge''),
          personality: getValue(''charPersonality''),
          appearance: getValue(''charAppearance''),
          openingStory: getValue(''charOpeningStory''),
          normalStatus: getCheckboxValue(''normalStatus''),
          strictStatus: getCheckboxValue(''strictStatus'')
        };
        
        saveData(''characterData'', JSON.stringify(characterData));
        
        var overlay = document.getElementById(''modalOverlay'');
        var modalTitle = document.getElementById(''modalTitle'');
        if (overlay && modalTitle && overlay.classList.contains(''active'')) {
          if (modalTitle.textContent.indexOf(''角色档案'') !== -1) {
            window.loadCharacterData();
          }
        }
      };
      
      // 选择国家
      window.selectCountry = function(btn) {
        var allBtns = document.querySelectorAll(''.country-btn'');
        allBtns.forEach(function(b) {
          b.classList.remove(''selected'');
        });
        btn.classList.add(''selected'');
        window.autoSave();
      };
      
      // 选择地区类型
      window.selectRegionType = function(btn) {
        // 清空自定义地区输入
        var customRegion = document.getElementById(''customRegion'');
        if (customRegion) {
          customRegion.value = '''';
        }
        
        var allBtns = document.querySelectorAll(''.region-type-btn'');
        allBtns.forEach(function(b) {
          b.classList.remove(''selected'');
        });
        btn.classList.add(''selected'');
        window.autoSave();
      };
      
      // 选择职业
      window.selectJob = function(btn) {
        // 清空自定义职业输入
        var customJob = document.getElementById(''customJob'');
        if (customJob) {
          customJob.value = '''';
        }
        
        var allBtns = document.querySelectorAll(''.job-btn'');
        allBtns.forEach(function(b) {
          b.classList.remove(''selected'');
        });
        btn.classList.add(''selected'');
        window.autoSave();
      };
      
      // 选择时间线
      window.selectTimeline = function(btn) {
        var allBtns = document.querySelectorAll(''.timeline-btn'');
        allBtns.forEach(function(b) {
          b.classList.remove(''selected'');
        });
        btn.classList.add(''selected'');
        window.autoSave();
      };
      
      // 清除地区类型选择（当输入自定义地区时）
      window.clearRegionType = function() {
        var customRegion = document.getElementById(''customRegion'');
        if (customRegion && customRegion.value.trim() !== '''') {
          var regionTypeBtns = document.querySelectorAll(''.region-type-btn'');
          regionTypeBtns.forEach(function(btn) {
            btn.classList.remove(''selected'');
          });
        }
      };
      
      // 清除职业选择（当输入自定义职业时）
      window.clearJobSelection = function() {
        var customJob = document.getElementById(''customJob'');
        if (customJob && customJob.value.trim() !== '''') {
          var jobBtns = document.querySelectorAll(''.job-btn'');
          jobBtns.forEach(function(btn) {
            btn.classList.remove(''selected'');
          });
        }
      };
      
      window.loadCustomData = function() {
        try {
          var savedData = loadData(''characterData'');
          if (savedData) {
            var data = JSON.parse(savedData);
            
            // 加载输入框
            var inputs = [''customRegion'', ''customJob'', 
                          ''charDisasterType'', ''charName'', ''charGender'', ''charAge'', ''charPersonality'',
                          ''charAppearance'', ''charOpeningStory''];
            inputs.forEach(function(id) {
              var el = document.getElementById(id);
              if (el && data[id]) {
                el.value = data[id];
              }
            });
            
            // 加载复选框
            [''normalStatus'', ''strictStatus''].forEach(function(id) {
              var el = document.getElementById(id);
              if (el && data[id] !== undefined) {
                el.checked = data[id];
              }
            });
            
            // 加载国家选择
            if (data.country) {
              var countries = data.country.split('', '');
              var countryBtns = document.querySelectorAll(''.country-btn'');
              countryBtns.forEach(function(btn) {
                if (countries.includes(btn.textContent)) {
                  btn.classList.add(''selected'');
                } else {
                  btn.classList.remove(''selected'');
                }
              });
            }
            
            // 加载地区类型选择
            if (data.regionType) {
              var regionTypes = data.regionType.split('', '');
              var regionTypeBtns = document.querySelectorAll(''.region-type-btn'');
              regionTypeBtns.forEach(function(btn) {
                if (regionTypes.includes(btn.textContent)) {
                  btn.classList.add(''selected'');
                } else {
                  btn.classList.remove(''selected'');
                }
              });
            }
            
            // 加载职业选择
            if (data.job) {
              var jobs = data.job.split('', '');
              var jobBtns = document.querySelectorAll(''.job-btn'');
              jobBtns.forEach(function(btn) {
                if (jobs.includes(btn.textContent)) {
                  btn.classList.add(''selected'');
                } else {
                  btn.classList.remove(''selected'');
                }
              });
            }
            
            // 加载时间线选择
            if (data.timeline) {
              var timelineValue = data.timeline.trim();
              var timelineBtns = document.querySelectorAll(''.timeline-btn'');
              timelineBtns.forEach(function(btn) {
                var btnText = btn.getAttribute(''data-text'') || btn.textContent;
                if (btnText === timelineValue) {
                  btn.classList.add(''selected'');
                } else {
                  btn.classList.remove(''selected'');
                }
              });
            }
          }
        } catch (e) {
          console.error(''loadCustomData error:'', e);
        }
      };
      
      window.loadCharacterData = function() {
