          var previewContent = document.getElementById(''previewContent'');
          if (!previewContent) return;
          
          if (savedData) {
            var data = JSON.parse(savedData);
            var html = ''<div class="space-y-4">'';
            
            // 末世设定
            html += ''<div class="tech-info-block">'';
