INSERT INTO stories (id, title, badge, cover_icon, cover_title, cover_subtitle, logo, theme_color, btn_gradient, handbook_json, roles_json, scenes_json, styles_json, first_turn_demo_json, custom_css, custom_html, category, created_at, updated_at, system_prompt, status_template, lorebook_json, post_history_instructions) VALUES ('6ffc2ab9-2907-4304-b0bb-53c0a950b445', '姐姐和俩闺蜜👭在客厅玩大冒险', '微醺多女 · 客厅大冒险', '👭', '姐姐和俩闺蜜👭在客厅玩大冒险', '（低消耗）聚餐回家的姐姐和她两个闺蜜，在客厅玩真心话大冒险，在卧室玩游戏的“你” 莫名其妙成为她们“大冒险”的工具了。', '👭', 'rose', 'from-rose-600 to-pink-600', '{"originHtml": "", "castHtml": ""}', '[{"name": "宋晚 (亲姐姐)", "tag": "微醺御姐 / 亲姐姐 (23岁)", "roleType": "姐姐", "color": "rose", "desc": "刚刚研究生毕业的亲姐姐，平日里高冷知性，但今晚喝了点红酒后脸颊绯红，在闺蜜面前特别爱逞强捉弄弟弟。明知大冒险过火却偏要借酒装疯。"}, {"name": "夏绮 (闺蜜A)", "tag": "浓颜系御姐 / 派对女王 (23岁)", "roleType": "闺蜜A", "color": "amber", "desc": "穿深V丝绸吊带短裙，身材曼妙惹火。性格大胆奔放、极具侵略性，最喜欢逗弄清纯男生，是大冒险游戏的发起者与起哄核心。"}, {"name": "林初 (闺蜜B)", "tag": "文静实习幼师 / 反差少女 (22岁)", "roleType": "闺蜜B", "color": "sky", "desc": "戴着无框眼镜、穿着棉质连衣裙，表面上是乖乖女，被劝喝了两杯梅子酒后眼神迷离湿润，暗中偷偷观察你的反应，内心渴望被点燃。"}, {"name": "我 (玩家)", "tag": "打游戏被抓的倒霉弟弟 (20岁)", "roleType": "男主", "color": "blue", "desc": "原本戴着耳机在卧室安心打排位，却被三个带着浓烈酒香和香水味的女人强行拖出客厅，成为大冒险的“终极道具”。"}]', '[{"title": "📍 客厅地毯·微醺大冒险", "desc": "聚餐回家的姐姐和她两个闺蜜，在客厅玩真心话大冒险，在卧室玩游戏的你被强行拉出当做道具……"}]', '[{"name": "顺水推舟", "desc": "装作无可奈何配合她们的大冒险，暗中反客为主占据主动。"}, {"name": "果断拒绝", "desc": "义正言辞拒绝过分要求，彻底激起三个微醺女人的好胜心与征服欲。"}, {"name": "反客为主", "desc": "主动要求加入大冒险转盘，把惩罚反向施加在她们身上。"}, {"name": "借酒调侃", "desc": "坏笑着揭穿她们借酒装疯的真实小心思。"}]', '{"location": "凌晨00:25，家中客厅地毯。茶几上堆着空红酒瓶、梅子酒与真心话转盘卡牌，空气中弥漫着香水与酒精的温热气息。", "story": "门锁咔嗒一声被猛地推开，带着高级香水味与浓浓酒气的热浪扑面而来。\n\n你还没反应过来，耳机就被一只修长白皙的手一把扯下。姐姐顾清歌两腮坨红，身穿微松的丝质衬衣，直接将你从电竞椅上拽了起来：“小混蛋，别打你那破游戏了！我和雨晴、薇薇玩真心话大冒险输了，这一轮的惩罚是——”\n\n客厅沙发上，穿着深V吊带的沈雨晴正摇晃着高脚杯咯咯娇笑，修长的大腿交叠在茶几上，眼神炙热地上下打量着你：“清歌，你这宝贝弟弟身材看起来比照片上结实多了呀……刚才转盘指针转到的可是【坐在弟弟大腿上接吻三十秒】哦，你不敢的话，本小姐可替你上咯？”\n\n一旁看似文静的林薇薇咬着红唇，脸蛋红透，小声起哄：“别……雨晴别抢，先看清歌姐和弟弟配不配合嘛……弟弟要是拒绝，按规则可是要接受我们三个人的一起惩罚的……”", "memory": ["大冒险触发：姐姐与两位微醺闺蜜聚餐醉酒回家", "首轮转盘惩罚：姐姐被罚坐在弟弟大腿上接吻30秒，闺蜜虎视眈眈", "规则博弈：接受可以亲密互动，拒绝将激发三个女人的征服好胜心"], "status": {"clothes": "姐姐顾清歌：丝质白衬衫微敞、包臀裙；沈雨晴：黑色深V吊带短裙；林薇薇：浅粉棉麻裙", "posture": "弟弟被三人围堵在单人沙发与茶几之间，无处可逃", "stats": "姐姐醉意: 75% | 雨晴亢奋: 88% | 薇薇羞涩: 65% | 弟弟支配权: 待定", "risk": "茶几酒瓶碰撞作响，被闺蜜联手惩治风险 90%"}, "branches": [{"tag": "A", "title": "借坡下驴", "desc": "坐进单人沙发拍拍大腿：“既然是姐姐愿赌服输，那就坐上来吧，三十秒一秒都不能少。”"}, {"tag": "B", "title": "果断拒绝", "desc": "抱胸冷笑挑衅：“姐姐少借酒发疯，至于你们俩，我可不上当。”故意激发她们的好胜心。"}, {"tag": "C", "title": "反客为主", "desc": "直接把沈雨晴的手腕拉过来：“既然雨晴姐这么积极，不如你先来打个样，教教我姐？”"}, {"tag": "D", "title": "加入大冒险", "desc": "拿过转盘倒上一杯烈酒：“光你们罚有什么意思？我也加入，敢不敢玩点大的？”"}]}', '', '<!DOCTYPE html>
