.btn{background-color:var(--color-primary);color:var(--color-text);border:none;padding:var(--space-md) var(--space-lg);border-radius:var(--radius-md);font-size:1rem;font-weight:700;cursor:pointer;transition:all var(--transition-base) var(--ease-out);display:inline-flex;align-items:center;justify-content:center;gap:var(--space-sm);width:100%;text-transform:uppercase;letter-spacing:1px;box-shadow:var(--shadow-sm);}
