        box-shadow:var(--shadow);
        margin-bottom:24px;
        overflow:hidden;
    }
    .hero-tag{
        position:relative;
        display:inline-block;
        background:linear-gradient(135deg,#f3e8ff,#faedcd);
        color:#7c6bb0;
        padding:7px 20px;
        border-radius:999px;
        font-size:12.5px;
        letter-spacing:3px;
        font-weight:600;
        border:1px solid #ead9ff;
    }
    .hero h1{
        position:relative;
        font-size:28px;
        letter-spacing:1.5px;
        margin:20px 0 10px;
        color:#332b4d;
    }
    .hero .hero-sub{
        position:relative;
        color:var(--accent-purple);
        font-size:14px;
        letter-spacing:3px;
        margin:0;
    }
    .hero .hero-line{
        position:relative;
        width:60px;height:2px;
        background:linear-gradient(90deg,transparent,var(--accent-gold),transparent);
        margin:18px auto 0;
    }
    .card{
        background:var(--soft-white);
        border-radius:24px;
        padding:28px 26px;
        margin-bottom:22px;
        box-shadow:var(--shadow-soft);
        border:1px solid #f2edfb;
    }
    .section-title{
        display:flex;
        align-items:center;
        gap:12px;
        font-size:18.5px;
        font-weight:700;
        color:#3a3350;
        margin:0 0 18px;
        letter-spacing:1px;
    }
    .section-title::before{
        content:"";
        width:6px;height:22px;
        border-radius:4px;
        background:linear-gradient(180deg,var(--accent-purple),var(--accent-gold));
        display:inline-block;
    }
    .section-sub{
        color:var(--text-gray);
        font-size:13px;
        margin:-10px 0 16px;
    }
    p{margin:0 0 14px;}
    .story-text{color:#4a4458;font-size:15px;line-height:1.9;white-space:pre-line;}
    .profile-grid{
        display:grid;
        grid-template-columns:repeat(auto-fit,minmax(240px,1fr));
        gap:16px;
