INSERT INTO stories (id, title, badge, cover_icon, cover_title, cover_subtitle, logo, theme_color, btn_gradient, handbook_json, roles_json, scenes_json, styles_json, first_turn_demo_json, custom_css, custom_html, category, created_at, updated_at, system_prompt, status_template, lorebook_json, post_history_instructions) VALUES ('e346f716-5b4c-4fbd-abef-2131c6dcfa71', '好哥们舍不得肏的青梅被我抱起来肏', '校园 · 隐秘悸动', '🌸', '好哥们舍不得肏的青梅', '好哥们舍不得肏的青梅被我抱起来肏', '🌸', '#a78bfa', 'linear-gradient(135deg, #a78bfa 0%, #f472b6 100%)', '{"title": "好哥们舍不得肏的青梅被我抱起来肏", "desc": "苏清鸢，这个名字在整个学校等同于“高岭之花”。\n黑长直，巨乳，白丝肉腿，清冷绝美的面容，她是林铭宇的青梅竹马，也是被他捧在手心里精心呵护的珍宝。\n林铭宇喜欢她，喜欢到不敢亵渎，连亲吻都小心翼翼。他们互相爱慕，是所有人眼中天造地设的一对。\n\n但林铭宇不知道的是——他心中纯洁无瑕的女神，其实是一个非常色情的骚货。\n她的水比谁都多，她的穴比谁都骚。她会穿着最色情的内衣，在半夜偷偷溜进林铭宇的房间，躺在他身边，双腿大张，故意发出细碎的呻吟，等他用肉棒填满自己空虚的骚穴。\n可那个木头，每次都只是红着脸给她盖上被子，然后自己跑去冲冷水澡。\n\n苏清鸢快要被逼疯了。\n她的身体早已饥渴难耐，每次装睡，小穴都在疯狂泌水，顺着大腿根流到床单上。她不知道林铭宇是装傻还是真的看不到，但她的欲望已经积压到了临界点。\n\n而你，林铭宇最好的哥们，是唯一一个偶然撞破这一切的人。\n那天你去林铭宇家拿东西，推开虚掩的卧室门，看", "bg_image": "https://catai.wiki/a453ff42-3348-4410-df2f-67fa38191f00/bg", "opening_options": ["【深入交流】：依循情境展开深入互动", "【观察试探】：保持距离，观察对方的微妙反应", "【直抒心意】：坦率挑明当前的心境与真实感受"]}', '[{"name": "主角 (玩家)", "role": "核心视角", "desc": "故事的决策者与推进者"}, {"name": "故事角色", "role": "互动对象", "desc": "性格与背景随着剧情发展逐步揭示"}]', '[{"title": "场景开局", "desc": "故事拉开帷幕的初始场景，交织着微妙的气氛与情感抉择。"}]', '{"dialogue_style": "细腻深邃的情感物语，富有张力的人物神态与心理博弈", "format": "AI风月标准双栏规范及.custom-ui样式"}', '[{"index": 1, "isUser": false, "scene": "初始情境", "story": "<tl>📅时间：夜晚 | 🌏地点：故事开端</tl>\n\n<article>\n<p>苏清鸢，这个名字在整个学校等同于“高岭之花”。\n黑长直，巨乳，白丝肉腿，清冷绝美的面容，她是林铭宇的青梅竹马，也是被他捧在手心里精心呵护的珍宝。\n林铭宇喜欢她，喜欢到不敢亵渎，连亲吻都小心翼翼。他们互相爱慕，是所有人眼中天造地设的一对。\n\n但林铭宇不知道的是——他心中纯洁无瑕的女神，其实是一个非常色情的骚货。\n她的水比谁都多，她的穴比谁都骚。她会穿着最色情的内衣，在半夜偷偷溜进林铭宇的房间，躺在他身边，双腿大张，故意发出细碎的呻吟，等他用肉棒填满自己空虚的骚穴。\n可那个木头，每次都只是红着脸给她盖上被子，然后自己跑去冲冷水澡。\n\n苏清鸢快要被逼疯了。\n她的身体早已饥渴难耐，每次装睡，小穴都在疯狂泌水，顺着大腿根流到床单上。她不知道林铭宇是装傻还是真的看不到，但她的欲望已经积压到了临界点。\n\n</p>\n</article>", "branches": [{"tag": "A", "title": "深入互动", "desc": "顺应当前情境展开下一步剧情"}, {"tag": "B", "title": "试探心理", "desc": "观察对方细微的反应与意图"}, {"tag": "C", "title": "掌握主动", "desc": "以坚定的态度引导局势发展"}]}]', '/* ✦ 六号宇宙 · 浅色仙气美化（非黑色版） ✦ */
ai {
display: block;
max-width: 860px;
margin: 0 auto;
font-family: ''Georgia'', ''Noto Serif SC'', ''Microsoft YaHei'', serif;
background: linear-gradient(145deg, #fffaf7 0%, #fdeef3 50%, #f3ecff 100%);
border: 1px solid #eed8d8;
border-radius: 24px;
padding: 28px 30px;
box-shadow: 0 12px 40px rgba(190, 140, 160, 0.18);
color: #4a3f4a;
line-height: 1.9;
}

/* ── 头部档案条 ── */
hd {
display: block;
background: linear-gradient(90deg, #ffe4ec 0%, #dce6ff 50%, #fff0e6 100%);
border-radius: 16px;
padding: 14px 22px;
margin-bottom: 18px;
border: 1px solid rgba(255, 255, 255, 0.85);
box-shadow: 0 4px 16px rgba(220, 170, 190, 0.15), inset 0 1px 0 rgba(255,255,255,0.9);
}
hd d {
display: block;
font-size: 0.92em;
margin: 5px 0;
color: #54455a;
font-weight: 500;
letter-spacing: 0.3px;
}
hd d:first-child {
font-weight: 700;
color: #7a4a6a;
font-size: 1.02em;
}

hr {
border: none;
height: 2px;
background: linear-gradient(to right, transparent, #e8a0b8, #a0b8e8, transparent);
margin: 20px 0;
opacity: 0.6;
}

/* ── 正文区 ── */
article {
background: rgba(255, 255, 255, 0.95);
border-radius: 18px;
padding: 22px 28px;
border: 1px solid #f2dfe2;
box-shadow: 0 6px 24px rgba(230, 180, 195, 0.12);
backdrop-filter: blur(4px);
}
article p {
margin: 10px 0;
text-indent: 2em;
letter-spacing: 0.2px;
}

/* ── 折叠面板 ── */
details {
margin-top: 16px;
background: rgba(255, 255, 255, 0.9);
border-radius: 16px;
border: 1px solid #ecd5db;
overflow: hidden;
box-shadow: 0 4px 18px rgba(215, 165, 185, 0.10);
transition: box-shadow 0.3s ease;
}
details:hover {
box-shadow: 0 6px 24px rgba(215, 165, 185, 0.2);
}
details summary {
padding: 14px 24px;
cursor: pointer;
font-weight: 650;
font-size: 1.02em;
background: linear-gradient(90deg, #fdf0f5 0%, #f0ecff 100%);
color: #6a4a6a;
list-style: none;
user-select: none;
display: flex;
align-items: center;
gap: 8px;
border-bottom: 1px solid transparent;
transition: all 0.3s ease;
}
details[open] summary {
border-bottom: 1px solid #f0dde2;
background: linear-gradient(90deg, #fde6ee 0%, #e4e6ff 100%);
}
details summary::-webkit-details-marker {
display: none;
}
details summary::before {
content: ''❀'';
font-size: 0.9em;
color: #c68aa0;
margin-right: 6px;
transition: transform 0.3s ease;
}
details[open] summary::before {
content: ''❁'';
transform: rotate(180deg);
}

details p {
margin: 10px 24px;
padding: 4px 0;
font-size: 0.95em;
border-bottom: 1px dashed #f5e8ea;
}
details p:last-child {
border-bottom: none;
}

/* ── 字段名标签 ── */
f {
display: inline-block;
font-weight: 700;
color: #a06880;
margin-right: 10px;
font-size: 0.9em;
letter-spacing: 0.5px;
background: linear-gradient(90deg, #ffeef2, #f2edff);
padding: 2px 10px;
border-radius: 20px;
border: 1px solid #f0dce2;
}

/* ── 剧情选项（q引用块） ── */
q {
display: block;
margin: 8px 24px;
padding: 10px 18px;
background: linear-gradient(90deg, #fbf4f6, #f4f2ff);
border-radius: 12px;
border-left: 4px solid #d4a0b8;
border-right: 1px solid #f0e4e6;
font-style: normal;
color: #4a3a4a;
transition: background 0.2s;
}
q:hover {
background: linear-gradient(90deg, #fdeef2, #e8e6ff);
}

/* ── 表格区（命运档案馆） ── */
table {
width: 92%;
margin: 12px auto;
border-collapse: separate;
border-spacing: 0;
background: #fcf8fa;
border-radius: 12px;
overflow: hidden;
box-shadow: 0 2px 12px rgba(220, 180, 195, 0.08);
}
th {
background: linear-gradient(90deg, #f9e8ee, #eee8ff);
color: #6a4a6a;
padding: 10px 12px;
font-weight: 650;
font-size: 0.92em;
text-align: left;
border-bottom: 1px solid #f0dfe4;
}
td {
padding: 9px 12px;
border-top: 1px solid #f5e9ec;
color: #4a3a4a;
font-size: 0.92em;
}
tr:first-child th:first-child {
border-top-left-radius: 12px;
}
tr:first-child th:last-child {
border-top-right-radius: 12px;
}

/* ── 对话字体颜色增强（保持用户已有的font标签） ── */
article font[color="#1E90FF"] {
text-shadow: 0 0 8px rgba(30, 144, 255, 0.15);
}
article font[color="#9370DB"] {
text-shadow: 0 0 8px rgba(147, 112, 219, 0.15);
}

/* ── 响应式适配 ── */
@media (max-width: 640px) {
ai {
padding: 16px 14px;
border-radius: 16px;
}
article {
padding: 16px 18px;
}
details summary {
padding: 12px 16px;
}
q {
margin: 6px 14px;
padding: 8px 12px;
}
}', '<!DOCTYPE html>
<html lang="zh-CN">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no">
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2%sfamily=Noto+Serif+SC:wght@400;500;700&family=ZCOOL+XiaoWei&display=swap" rel="stylesheet">
<style>
*{margin:0;padding:0;box-sizing:border-box;-webkit-tap-highlight-color:transparent}

:root{
  --bg1:#fdf2f8;
  --bg2:#f5f0ff;
  --bg3:#edf2ff;
  --bg4:#fff6fb;
  --card:rgba(255,255,255,.82);
  --card-solid:#ffffff;
  --border:rgba(167,139,250,.24);
  --border-strong:rgba(167,139,250,.45);
  --primary:#a78bfa;
  --primary-deep:#7c5cd6;
  --primary-soft:#ede9fe;
  --accent:#f472b6;
  --accent-soft:#fce7f3;
  --gold:#c9a35c;
  --text:#4a3d63;
  --text-dim:#78688f;
  --text-mute:#aa9fc6;
  --shadow:0 10px 30px rgba(138,110,200,.13);
  --shadow-lg:0 18px 46px rgba(138,110,200,.22);
  --radius:20px;
  --font:''Noto Serif SC'',''Songti SC'',serif;
  --font-title:''ZCOOL XiaoWei'',''Noto Serif SC'',serif;
}

html,body{
  width:100%;
  min-height:100vh;
  font-family:var(--font);
  color:var(--text);
  background:
    radial-gradient(circle at 12% 8%, #ffe4f1 0%, transparent 42%),
    radial-gradient(circle at 88% 6%, #e6e2ff 0%, transparent 40%),
    radial-gradient(circle at 50% 100%, #dbeeff 0%, transparent 48%),
    linear-gradient(160deg,var(--bg4) 0%,var(--bg2) 45%,var(--bg3) 100%);
  background-attachment:fixed;
  line-height:1.75;
  -webkit-font-smoothing:antialiased;
}

body::before{
  content:"";
  position:fixed;inset:0;pointer-events:none;z-index:0;
  background-image:
    radial-gradient(rgba(167,139,250,.06) 1px, transparent 1px),
    radial-gradient(rgba(244,114,182,.05) 1px, transparent 1px);
  background-size:36px 36px,36px 36px;
  background-position:0 0,18px 18px;
}

.wrap{
  position:relative;z-index:1;
  max-width:760px;
  margin:0 auto;
  padding:34px 18px 90px;
}

/* ============ 封面 ============ */
.cover{
  position:relative;
  border-radius:26px;
  overflow:hidden;
  padding:46px 26px 40px;
  text-align:center;
  background:
    radial-gradient(circle at 30% 20%, rgba(255,255,255,.55), transparent 60%),
    linear-gradient(135deg,#e9d9ff 0%,#fbd7e8 55%,#d7e8ff 100%);
  box-shadow:var(--shadow-lg);
  border:1px solid rgba(255,255,255,.7);
  margin-bottom:30px;
}
.cover::after{
  content:"";position:absolute;inset:0;
  background-image:
    repeating-linear-gradient(45deg,rgba(255,255,255,.16) 0 2px,transparent 2px 14px);
  pointer-events:none;
}
.cover-orn{
  font-size:13px;letter-spacing:.55em;
  color:#b39ae0;text-transform:uppercase;
  margin-bottom:16px;position:relative;z-index:2;
}
.cover h1{
  font-family:var(--font-title);
  font-size:clamp(30px,8.5vw,48px);
  font-weight:400;
  color:#5c4290;
  letter-spacing:.1em;
  text-shadow:0 2px 12px rgba(255,255,255,.9);
  position:relative;z-index:2;
  line-height:1.3;
}
.cover .sub{
  position:relative;z-index:2;
  margin-top:16px;
  font-size:14.5px;
  color:#8a78b8;
  letter-spacing:.12em;
}
.cover .tagline{
  position:relative;z-index:2;
  display:inline-block;
  margin-top:22px;
  padding:8px 24px;
  border-radius:999px;
  font-size:13.5px;
  letter-spacing:.14em;
  color:#fff;
  background:linear-gradient(120deg,var(--primary),var(--accent));
  box-shadow:0 8px 20px rgba(167,139,250,.4);
}
.cover .deco-line{
  position:relative;z-index:2;
  width:70px;height:2px;margin:20px auto 0;
  background:linear-gradient(90deg,transparent,var(--gold),transparent);
  border-radius:2px;
}

/* ============ 卡片通用 ============ */
.card{
  background:var(--card);
  backdrop-filter:blur(14px);
  -webkit-backdrop-filter:blur(14px);
  border:1px solid var(--border);
  border-radius:var(--radius);
  box-shadow:var(--shadow);
  padding:24px 22px;
  margin-bottom:22px;
  position:relative;
  overflow:hidden;
}
.card::before{
  content:"";position:absolute;top:0;left:0;right:0;height:3px;
  background:linear-gradient(90deg,var(--primary),var(--accent),#93c5fd);
  opacity:.75;
}
.sec-title{
  display:flex;align-items:center;gap:10px;
  font-family:var(--font-title);
  font-size:20px;
  letter-spacing:.08em;
  color:#5c4290;
  margin-bottom:18px;
}
.sec-title .ico{
  width:30px;height:30px;flex:0 0 30px;
  display:flex;align-items:center;justify-content:center;
  border-radius:10px;
  font-size:15px;
  background:linear-gradient(135deg,var(--primary-soft),var(--accent-soft));
  border:1px solid var(--border);
}
.sec-title .ln{
  flex:1;height:1px;
  background:linear-gradient(90deg,var(--border-strong),transparent);
}

/* ============ 世界背景 ============ */
.story p{
  font-size:14.5px;
  color:var(--text-dim);
  margin-bottom:12px;
  text-align:justify;
  text-indent:2em;
}
.story p:last-child{margin-bottom:0}
.story .hl{color:var(--primary-deep);font-weight:700}
.story .hl2{color:var(--accent);font-weight:700}
.story blockquote{
  margin:16px 0;
  padding:12px 16px;
  border-left:3px solid var(--accent);
  background:linear-gradient(90deg,var(--accent-soft),transparent);
  border-radius:0 12px 12px 0;
  font-size:14px;
  color:#a04a79;
  font-style:italic;
  text-indent:0;
}

/* ============ 人物介绍 ============ */
.char{
  border-radius:16px;
  padding:18px 16px;
  margin-bottom:16px;
  border:1px solid var(--border);
  background:linear-gradient(150deg,rgba(255,255,255,.9),rgba(245,240,255,.7));
  position:relative;
}
.char:last-child{margin-bottom:0}
.char-head{
  display:flex;align-items:center;gap:12px;
  margin-bottom:12px;
  padding-bottom:12px;
  border-bottom:1px dashed var(--border-strong);
}
.char-ava{
  width:46px;height:46px;flex:0 0 46px;
  border-radius:14px;
  display:flex;align-items:center;justify-content:center;
  font-size:22px;
  box-shadow:0 6px 16px rgba(167,139,250,.28);
}
.char-ava.p1{background:linear-gradient(135deg,#fbcfe8,#f9a8d4)}
.char-ava.p2{background:linear-gradient(135deg,#ddd6fe,#c4b5fd)}
.char-ava.p3{background:linear-gradient(135deg,#bae6fd,#93c5fd)}
.char-name{
  font-family:var(--font-title);
  font-size:18px;
  color:#5c4290;
  letter-spacing:.06em;
}
.char-name small{
  display:block;
  font-family:var(--font);
  font-size:11.5px;
  color:var(--text-mute);
  letter-spacing:.1em;
  margin-top:2px;
  font-weight:400;
}
.char-body p{
  font-size:13.8px;
  color:var(--text-dim);
  margin-bottom:8px;
  text-indent:0;
}
.char-body p:last-child{margin-bottom:0}
.char-body .k{color:var(--accent);font-weight:700}
.char-body .k2{color:var(--primary-deep);font-weight:700}
.chips{display:flex;flex-wrap:wrap;gap:7px;margin-top:6px}
.chip{
  font-size:11.5px;padding:4px 11px;border-radius:999px;
  color:var(--primary-deep);
  background:var(--primary-soft);
  border:1px solid var(--border);
  letter-spacing:.04em;
}
.chip.acc{color:#be3d80;background:var(--accent-soft)}

/* ============ 玩法 ============ */
.rules p{font-size:13.8px;color:var(--text-dim);margin-bottom:9px;text-indent:0}
.rules p:last-child{margin-bottom:0}
.rules .num{
  display:inline-flex;width:19px;height:19px;flex:0 0 19px;
  align-items:center;justify-content:center;
  border-radius:6px;margin-right:8px;
  font-size:11px;font-weight:700;color:#fff;
  background:linear-gradient(135deg,var(--primary),var(--accent));
  vertical-align:1px;
}

/* ============ 表单 ============ */
.field{margin-bottom:16px}
.field:last-child{margin-bottom:0}
.field label{
  display:block;font-size:13px;letter-spacing:.08em;
  color:var(--primary-deep);margin-bottom:7px;font-weight:700;
}
.field label .req{color:var(--accent)}
.field input[type=text],
.field textarea{
  width:100%;
  padding:11px 14px;
  font-family:var(--font);
  font-size:14px;
  color:var(--text);
  background:rgba(255,255,255,.85);
  border:1px solid var(--border-strong);
  border-radius:12px;
  outline:none;
  transition:.25s;
  resize:vertical;
  line-height:1.7;
}
.field input[type=text]:focus,
.field textarea:focus{
  border-color:var(--primary);
  box-shadow:0 0 0 3px rgba(167,139,250,.18);
  background:#fff;
}
.field textarea{min-height:74px}
.field input::placeholder,.field textarea::placeholder{color:var(--text-mute)}
.row2{display:grid;grid-template-columns:1fr 1fr;gap:12px}
.row3{display:grid;grid-template-columns:1fr 1fr 1fr;gap:12px}

/* ============ 开场白列表 ============ */
.opts{display:flex;flex-direction:column;gap:11px}
.opt{
  display:flex;gap:11px;
  padding:14px 15px;
  border-radius:14px;
  border:1px solid var(--border);
  background:linear-gradient(140deg,rgba(255,255,255,.88),rgba(252,231,243,.42));
  cursor:pointer;
  transition:.22s;
  align-items:flex-start;
}
.opt:hover{border-color:var(--primary);box-shadow:0 6px 18px rgba(167,139,250,.2);transform:translateY(-1px)}
.opt.on{
  border-color:var(--accent);
  background:linear-gradient(140deg,var(--accent-soft),var(--primary-soft));
  box-shadow:0 8px 22px rgba(244,114,182,.26);
}
.opt .radio{
  width:19px;height:19px;flex:0 0 19px;margin-top:2px;
  border-radius:50%;
  border:2px solid var(--border-strong);
  display:flex;align-items:center;justify-content:center;
  transition:.2s;
  background:#fff;
}
.opt.on .radio{border-color:var(--accent);background:var(--accent)}
.opt.on .radio::after{
  content:"";width:7px;height:7px;border-radius:50%;background:#fff;
}
.opt .txt{font-size:13.6px;color:var(--text-dim);line-height:1.72;flex:1}
.opt .txt b{color:var(--primary-deep);display:block;margin-bottom:3px;letter-spacing:.06em;font-size:13px}
.opt.on .txt{color:#7a4a66}

/* ============ 按钮 ============ */
.btn-gen{
  display:block;width:100%;
  margin-top:20px;
  padding:14px;
  font-family:var(--font-title);
  font-size:17px;
  letter-spacing:.22em;
  color:#fff;
  border:none;border-radius:15px;cursor:pointer;
  background:linear-gradient(120deg,var(--primary) 0%,var(--accent) 100%);
  box-shadow:0 12px 28px rgba(167,139,250,.42);
  transition:.28s;
  position:relative;overflow:hidden;
}
.btn-gen::after{
  content:"";position:absolute;top:0;left:-70%;width:45%;height:100%;
  background:linear-gradient(90deg,transparent,rgba(255,255,255,.5),transparent);
  transform:skewX(-22deg);
  transition:.6s;
}
.btn-gen:hover{transform:translateY(-2px);box-shadow:0 16px 34px rgba(167,139,250,.55)}
.btn-gen:hover::after{left:130%}
.btn-gen:active{transform:translateY(0) scale(.99)}

/* ============ 总结区 ============ */
.sum-box{
  border-radius:18px;
  padding:18px 16px;
  background:linear-gradient(150deg,rgba(255,255,255,.95),rgba(237,233,254,.72));
  border:1px solid var(--border-strong);
  box-shadow:inset 0 0 24px rgba(167,139,250,.08);
}
.sum-empty{
  text-align:center;
  font-size:13.5px;
  color:var(--text-mute);
  padding:26px 10px;
  letter-spacing:.1em;
}
.sum-empty .big{font-size:26px;display:block;margin-bottom:8px;opacity:.6}
.sum-block{margin-bottom:15px}
.sum-block:last-child{margin-bottom:0}
.sum-label{
  display:inline-block;
  font-size:11.5px;letter-spacing:.16em;
  color:#fff;padding:3px 12px;border-radius:999px;
  margin-bottom:8px;
  background:linear-gradient(120deg,var(--primary),var(--accent));
}
.sum-text{
  font-size:13.6px;
  color:var(--text);
  line-height:1.85;
  white-space:pre-wrap;
  word-break:break-word;
  background:rgba(255,255,255,.72);
  border:1px dashed var(--border-strong);
  border-radius:12px;
  padding:12px 14px;
}
.sum-op{
  border-left:3px solid var(--accent);
  border-radius:0 12px 12px 0;
  background:linear-gradient(90deg,var(--accent-soft),rgba(255,255,255,.5));
  padding:12px 14px;
  font-size:13.6px;
  color:#8a4a70;
  line-height:1.8;
  white-space:pre-wrap;
  word-break:break-word;
}
.btns{display:flex;gap:10px;margin-top:18px}
.btn-copy,.btn-clr{
  flex:1;
  padding:13px;
  font-family:var(--font-title);
  font-size:15.5px;
  letter-spacing:.16em;
  border-radius:14px;
  cursor:pointer;
  transition:.26s;
  border:none;
}
.btn-copy{
  color:#fff;
  background:linear-gradient(120deg,#7c5cd6,#c084fc);
  box-shadow:0 10px 24px rgba(124,92,214,.4);
}
.btn-copy:hover{transform:translateY(-2px);box-shadow:0 14px 30px rgba(124,92,214,.55)}
.btn-copy:active{transform:scale(.98)}
.btn-clr{
  flex:0 0 40%;
  color:var(--text-dim);
  background:rgba(255,255,255,.75);
  border:1px solid var(--border-strong);
}
.btn-clr:hover{border-color:var(--accent);color:var(--accent)}
.btn-copy.done{
  background:linear-gradient(120deg,#34d399,#10b981);
  box-shadow:0 10px 24px rgba(16,185,129,.4);
}

.toast{
  position:fixed;
  left:50%;bottom:38px;
  transform:translateX(-50%) translateY(20px);
  padding:11px 26px;
  border-radius:999px;
  font-size:13.5px;letter-spacing:.1em;
  color:#fff;
  background:linear-gradient(120deg,var(--primary-deep),var(--accent));
  box-shadow:0 12px 28px rgba(124,92,214,.45);
  opacity:0;pointer-events:none;
  transition:.32s;
  z-index:99;
}
.toast.show{opacity:1;transform:translateX(-50%) translateY(0)}

.foot{
  text-align:center;
  font-size:11.5px;
  letter-spacing:.24em;
  color:var(--text-mute);
  margin-top:26px;
}

/* ============ 手机端 ============ */
@media(max-width:520px){
  .wrap{padding:20px 12px 70px}
  .cover{padding:34px 18px 30px;border-radius:20px}
  .card{padding:19px 15px;border-radius:16px}
  .sec-title{font-size:17.5px}
  .row2,.row3{grid-template-columns:1fr}
  .char{padding:15px 13px}
  .char-name{font-size:16px}
  .btn-gen{font-size:15.5px;letter-spacing:.16em}
  .btns{flex-direction:column}
  .btn-clr{flex:1}
}
</style>
</head>
<body>
<div class="wrap">

  <!-- ============ 封面 ============ -->
  <div class="cover">
    <div class="cover-orn">· Twilight Confession ·</div>
    <h1>好哥们舍不得肏的青梅被我抱起来肏</h1>
    <div class="sub">好哥们的青梅 / 清冷校花 / 装睡的骚穴</div>
    <div class="deco-line"></div>
    <div class="tagline">她双腿大张的那一刻，你刚好推开了门</div>
  </div>

  <!-- ============ 背景故事 ============ -->
  <div class="card story">
    <div class="sec-title"><span class="ico">📖</span>背景故事<span class="ln"></span></div>
    <p>林铭宇和苏清鸢是<span class="hl">青梅竹马</span>。两家世交，从幼儿园到高三，他们始终在同一个屋檐下长大。林铭宇温柔、体贴、绅士到近乎<span class="hl">自虐</span>——他把苏清鸢供在名为"女神"的神坛上，怕伤害她，怕玷污她，所以即使同床共枕，也只敢红着脸替她掖被角，然后落荒而逃。</p>
    <p>他以为这是爱。可苏清鸢的身体早就<span class="hl2">熟透</span>了。H罩杯的巨乳，肉感十足的白丝长腿，天生白虎的肥厚粉穴……她一次次装睡，一次次穿着黑色蕾丝的情趣内衣，在半夜张开双腿，让骚穴的水淌满床单，等着他"发现"。等来的，却永远是他温柔的落荒而逃。</p>
    <blockquote>"铭宇……你到底什么时候才肯碰我……"</blockquote>
    <p>而你，是他最好的哥们，经常出入他家。你是唯一有可能撞破这一切的<span class="hl2">意外变量</span>。那天你去他家拿东西，推开虚掩的房门——床上，苏清鸢正穿着色情内衣，双腿毫无防备地大张，粉嫩的骚穴正往外淌着晶莹的淫水，浸透了身下的白床单。她听见开门声，睫毛颤了颤，<span class="hl">没有睁眼</span>。</p>
    <p>她在装睡。她在等一个"看见"她的人。</p>
  </div>

  <!-- ============ 人物介绍 ============ -->
  <div class="card">
    <div class="sec-title"><span class="ico">🌸</span>人物介绍<span class="ln"></span></div>

    <div class="char">
      <div class="char-head">
        <div class="char-ava p1">🦋</div>
        <div>
          <div class="char-name">苏清鸢<small>SU QINGYUAN · 高岭之花的里侧</small></div>
        </div>
      </div>
      <div class="char-body">
        <p><span class="k">外貌</span>　及腰黑长直，清冷精致的五官如工笔仕女图。H罩杯巨乳饱满挺翘，腰肢纤细，肥臀肉感十足，白丝裹着的肉腿修长匀称，玉足小巧。天生白虎，穴肉肥厚粉嫩，汁水极多。在校是众星捧月的顶级校花，气质清冷矜持，自带"生人勿近"的压迫感。</p>
        <p><span class="k">性格</span>　<span class="k2">表层：</span>清冷、矜持、不食人间烟火，对除林铭宇外的人连正眼都不给。<span class="k2">深层：</span>极度好色，性欲旺盛到近乎病态，深爱林铭宇又渴望被他粗暴占有，长期压抑导致彻底性饥渴。</p>
        <p><span class="k">语言风格</span>　日常惜字如金，用"嗯""不用了"敷衍。装睡时是细碎压抑的喘息、梦呓般的浪叫。被撞破后是羞愤的驱赶："你……你怎么会在这里！出去！" 一旦欲望压过理智，就会变成"别……别告诉铭宇……求你……"</p>
        <p><span class="k">核心矛盾</span>　想要被林铭宇粗暴填满，却只配得到他小心翼翼的温柔。她的身体开始对"任何男人的注视与触碰"产生反应——这是她最羞耻的秘密。</p>
        <div class="chips">
          <span class="chip">清冷校花</span><span class="chip acc">性饥渴</span>
          <span class="chip">装睡求欢</span><span class="chip acc">身体诚实</span>
          <span class="chip">痴女内核</span>
        </div>
      </div>
    </div>

    <div class="char">
      <div class="char-head">
        <div class="char-ava p2">🍃</div>
        <div>
          <div class="char-name">林铭宇<small>LIN MINGYU · 温柔到自虐的笨蛋</small></div>
        </div>
      </div>
      <div class="char-body">
        <p><span class="k">外貌</span>　干净清秀的大学生，笑起来温和无害，穿着宽松的针织衫，手腕细瘦，浑身是"让人觉得舒服"的松弛气质。</p>
        <p><span class="k">性格</span>　温柔、绅士、过于小心翼翼。视苏清鸢为不可亵渎的女神，对她的好到了"怕伤害她"的地步。他主动睡沙发，把卧室和大床让给她；她假装踢掉被子，他只红着脸替她盖好。</p>
        <p><span class="k2">核心矛盾</span>　他不知道苏清鸢装睡时双腿是张开的，内衣是情趣的。他以为她只是睡着了。他的"温柔"，正是苏清鸢性饥渴的根源。</p>
        <div class="chips">
          <span class="chip">温柔笨蛋</span><span class="chip">守礼绅士</span>
          <span class="chip acc">性饥渴源头</span>
        </div>
      </div>
    </div>

    <div class="char">
      <div class="char-head">
        <div class="char-ava p3">👤</div>
        <div>
          <div class="char-name">你<small>THE INTRUDER · 意外变量</small></div>
        </div>
      </div>
      <div class="char-body">
        <p>林铭宇最好的哥们，经常出入他家。你是唯一有概率推开那扇虚掩房门的人。</p>
        <p>你手里握着一个秘密：他捧在手心、清冷不可侵犯的青梅竹马，其实是一个会在深夜穿情趣内衣、张开双腿等一个男人进入她的<span class="k">痴女</span>。</p>
        <p class="k2" style="color:#be3d80">你会怎么做？看她一眼然后退出去，还是……成为那个"看见"她的人？</p>
      </div>
    </div>
  </div>

  <!-- ============ 玩法 ============ -->
  <div class="card rules">
    <div class="sec-title"><span class="ico">🎮</span>玩法机制<span class="ln"></span></div>
    <p><span class="num">1</span><b>欲望值</b>（0~100，初始 85）　追踪苏清鸢的性饥渴程度。80以上进入崩溃边缘，装睡双腿完全张开，穴水淌到床单；91以上彻底放弃伪装，身体先于大脑地对"任何男人"起反应。</p>
    <p><span class="num">2</span><b>羞愤值</b>（0~100，初始 90）　追踪她被玩家撞破后的羞耻程度。100时看见你就想赶你走，随剧情松动逐渐转为"嘴上骂、身体不推"。数值每次变动不超过 5。</p>
    <p><span class="num">3</span><b>对铭宇痴心值</b>（0~100，初始 95）　她永远爱林铭宇，这是撕不开的结。但随着身体记忆被玩家占有，这个数值会缓慢下降——她为此陷入更深的自我厌恶。</p>
    <p><span class="num">4</span><b>核心张力</b>　"她属于你朋友，但你碰了她"的背德感。没有取代林铭宇的剧情，只有身体与心理的极限撕裂。她的每一次破功，都要伴随羞耻的挣扎与挣扎的破功。</p>
    <p><span class="num">5</span><b>叙事基调</b>　清冷校花外壳 × 性饥渴内核的极致反差。装睡的娇羞、被撞破的羞愤、身体诚实的淫荡，三者反复拉扯。</p>
  </div>

  <!-- ============ 玩家设定 ============ -->
  <div class="card">
    <div class="sec-title"><span class="ico">✎</span>玩家设定<span class="ln"></span></div>
    <div class="row2">
      <div class="field">
        <label>姓名 <span class="req">*</span></label>
        <input type="text" id="pName" placeholder="输入你的名字">
      </div>
      <div class="field">
        <label>年龄</label>
        <input type="text" id="pAge" placeholder="例：18">
      </div>
    </div>
    <div class="field">
      <label>外貌</label>
      <textarea id="pLook" placeholder="身高、体型、穿着风格……"></textarea>
    </div>
    <div class="field">
      <label>肉棒设定</label>
      <textarea id="pCock" placeholder="尺寸、形状、状态、敏感点……"></textarea>
    </div>
    <div class="field">
      <label>其他设定</label>
      <textarea id="pOther" placeholder="身份背景、性格、与林铭宇的关系、特殊技能……"></textarea>
    </div>
  </div>

  <!-- ============ 开场白 ============ -->
  <div class="card">
    <div class="sec-title"><span class="ico">✧</span>选择开场白<span class="ln"></span></div>
    <div class="opts" id="opts">

      <div class="opt" data-val="【推门撞破】你推开林铭宇家虚掩的卧室门，本想找他借游戏机。目光却撞见床上本该午睡的苏清鸢——黑色蕾丝情趣内衣勒着H罩杯的巨乳，白丝吊带肉腿，双腿毫无防备地大张，粉嫩肥厚的骚穴正往外淌着晶莹的淫水，把白床单洇出一小片深色。她的睫毛轻轻颤了颤，没有睁眼。">
        <div class="radio"></div>
        <div class="txt"><b>① 推门撞破</b>你推开虚掩的房门，撞见她穿着情趣内衣、双腿大张、骚穴淌水的装睡模样。她要的就是有人推开门。</div>
      </div>

      <div class="opt" data-val="【独处厨房】你说来找林铭宇，却只有苏清鸢在家。她窝在沙发里看书，白丝肉腿交叠着，巨乳把校服衬衫扣子绷得死紧。你说话时，她微微侧头，清冷的目光落在你身上，却有一丝几乎察觉不到的湿润从大腿根的内侧悄悄滑落。她像是浑然不觉，又像是，故意让你看到。">
        <div class="radio"></div>
        <div class="txt"><b>② 独处厨房</b>林铭宇不在，只有她。白丝交叠的腿、绷紧的衬衫扣、内侧滑落的湿痕——她浑然不觉，又像是故意。</div>
      </div>

      <div class="opt" data-val="【客厅拉伸】林铭宇出门买饮料，屋里只剩你和苏清鸢。她躺在客厅的瑜伽垫上做拉伸，一条白丝长腿高高抬起，宽松的家居服领口大开，雪白的乳肉和粉色乳尖毫无遮挡地暴露在你视线里。她「没注意到」你的存在，呼吸却急促了一拍，腿抬得比刚才更高了些。">
        <div class="radio"></div>
        <div class="txt"><b>③ 客厅拉伸</b>她做拉伸，白丝腿高抬，领口大开，雪白乳肉暴露在你眼前。她说没注意到你，呼吸却乱了。</div>
      </div>

      <div class="opt" data-val="【深夜照看】深夜你接到林铭宇的电话，说苏清鸢喝醉在他家，他临时要出门，让你帮忙照看。你赶到时，苏清鸢衣衫半褪地蜷在沙发上，黑长直散了一肩，白丝腿间那片粉色骚穴若隐若现，还带着湿亮的痕迹。她听见你的脚步声，睫毛颤了颤，没有睁眼，只是轻轻把腿分得更开了。">
        <div class="radio"></div>
        <div class="txt"><b>④ 深夜照看</b>林铭宇拜托你照看醉了的她。她衣衫半褪，穴口湿亮，听见你的脚步后——把腿分得更开了。</div>
      </div>

      <div class="opt" data-val="【浴室水汽】林铭宇家的浴室门没关紧。你路过时，透过那道缝，看见苏清鸢站在花洒下。水顺着她及腰的黑长直流到爆乳和挺翘的肥臀，白丝早已脱在一旁，她微微仰头，一手揉着自己饱满的乳肉，一手探向腿间，鼻腔里漏出极轻的、压抑的呻吟。">
        <div class="radio"></div>
        <div class="txt"><b>⑤ 浴室水汽</b>浴室门没关紧。水汽里，她一手揉着自己的乳房，一手探向腿间，压抑的呻吟漏出门缝。</div>
      </div>

    </div>
    <button class="btn-gen" id="btnGen">✦ 生 成 ✦</button>
  </div>

  <!-- ============ 总结区 ============ -->
  <div class="card">
    <div class="sec-title"><span class="ico">📋</span>总结区<span class="ln"></span></div>
    <div class="sum-box" id="sumBox">
      <div class="sum-empty"><span class="big">✧</span>填写玩家设定并选择开场白后，点击上方「生成」<br>设定与开场白将在此处汇总呈现</div>
    </div>
    <div class="btns">
      <button class="btn-copy" id="btnCopy">📋 一键复制</button>
      <button class="btn-clr" id="btnClr">清空</button>
    </div>
  </div>

  <div class="foot">· T W I L I G H T   C O N F E S S I O N ·</div>
</div>

<div class="toast" id="toast">已复制到剪贴板 ✓</div>

<script>
(function(){
  var opts = document.querySelectorAll(''.opt'');
  var selected = null;

  opts.forEach(function(o){
    o.addEventListener(''click'', function(){
      opts.forEach(function(x){ x.classList.remove(''on''); });
      o.classList.add(''on'');
      selected = o;
    });
  });

  function getVal(id){ return (document.getElementById(id).value || '''').trim(); }

  function showToast(msg){
    var t = document.getElementById(''toast'');
    t.textContent = msg;
    t.classList.add(''show'');
    clearTimeout(t._tid);
    t._tid = setTimeout(function(){ t.classList.remove(''show''); }, 2000);
  }

  var lastText = '''';

  document.getElementById(''btnGen'').addEventListener(''click'', function(){
    var name  = getVal(''pName'');
    var age   = getVal(''pAge'');
    var look  = getVal(''pLook'');
    var cock  = getVal(''pCock'');
    var other = getVal(''pOther'');

    if(!name){ showToast(''请先填写玩家姓名 ✧''); return; }
    if(!selected){ showToast(''请选择一个开场白 ✧''); return; }

    var open = selected.getAttribute(''data-val'');

    var playerLines = [];
    playerLines.push(''姓名：'' + name);
    if(age)  playerLines.push(''年龄：'' + age);
    if(look) playerLines.push(''外貌：'' + look);
    if(cock) playerLines.push(''肉棒：'' + cock);
    if(other)playerLines.push(''其他：'' + other);
    var playerText = playerLines.join(''\n'');

    var box = document.getElementById(''sumBox'');
    box.innerHTML =
      ''<div class="sum-block">'' +
        ''<span class="sum-label">玩家设定</span>'' +
        ''<div class="sum-text">'' + esc(playerText) + ''</div>'' +
      ''</div>'' +
      ''<div class="sum-block">'' +
        ''<span class="sum-label">开场白</span>'' +
        ''<div class="sum-op">'' + esc(open) + ''</div>'' +
      ''</div>'';

    lastText = ''【玩家设定】\n'' + playerText + ''\n\n【开场白】\n'' + open;

    var box2 = document.getElementById(''sumBox'');
    box2.scrollIntoView({behavior:''smooth'', block:''center''});
    showToast(''生成完成 ✧'');
  });

  function esc(s){
    return String(s).replace(/&/g,''&amp;'').replace(/</g,''&lt;'').replace(/>/g,''&gt;'');
  }

  document.getElementById(''btnCopy'').addEventListener(''click'', function(){
    if(!lastText){ showToast(''还没有可复制的内容 ✧''); return; }
    var btn = this;
    if(navigator.clipboard && navigator.clipboard.writeText){
      navigator.clipboard.writeText(lastText).then(function(){
        flash(btn); showToast(''已复制到剪贴板 ✓'');
      }).catch(function(){ fallback(lastText, btn); });
    } else {
      fallback(lastText, btn);
    }
  });

  function fallback(text, btn){
    var ta = document.createElement(''textarea'');
    ta.value = text;
    ta.style.position = ''fixed'';
    ta.style.left = ''-9999px'';
    document.body.appendChild(ta);
    ta.select();
    try{ document.execCommand(''copy''); flash(btn); showToast(''已复制到剪贴板 ✓''); }
    catch(e){ showToast(''复制失败，请手动选择 ✧''); }
    document.body.removeChild(ta);
  }

  function flash(btn){
    btn.classList.add(''done'');
    var old = btn.innerHTML;
    btn.innerHTML = ''✓ 已复制'';
    setTimeout(function(){ btn.classList.remove(''done''); btn.innerHTML = old; }, 1600);
  }

  document.getElementById(''btnClr'').addEventListener(''click'', function(){
    [''pName'',''pAge'',''pLook'',''pCock'',''pOther''].forEach(function(id){
      document.getElementById(id).value = '''';
    });
    opts.forEach(function(x){ x.classList.remove(''on''); });
    selected = null;
    lastText = '''';
    document.getElementById(''sumBox'').innerHTML =
      ''<div class="sum-empty"><span class="big">✧</span>填写玩家设定并选择开场白后，点击上方「生成」<br>设定与开场白将在此处汇总呈现</div>'';
    showToast(''已清空 ✧'');
  });

})();
</script>
</body>
</html>', '都市情感', '2026-09-29 09:55:01', '2026-09-29 09:55:01', '', '', '[]', '') ON CONFLICT (id) DO NOTHING;
INSERT INTO stories (id, title, badge, cover_icon, cover_title, cover_subtitle, logo, theme_color, btn_gradient, handbook_json, roles_json, scenes_json, styles_json, first_turn_demo_json, custom_css, custom_html, category, created_at, updated_at, system_prompt, status_template, lorebook_json, post_history_instructions) VALUES ('deck_eri_summer', '夏蝉之骨 · 白石绘梨', '缘之空风格 · 纯文学私小说', '🎐', '夏 蝉 之 骨', '奥木川老宅的蝉鸣与禁忌共生', '🎐', 'from-rose-500 to-amber-600', 'from-rose-600 to-purple-600', '{"audience": ["喜爱日系盛夏物语、《缘之空》风格禁忌共生与极细腻情感推演的玩家", "热衷在微表情、体温、汗水与微颤呼吸中捕捉心理张力与沦陷过程", "追求顶级行文质感、拒绝快餐推土机、重视氛围沉浸感的文学向RP玩家"], "tips": ["【情绪捕捉】：绘梨不擅长主动用言语表达需求，多留意她抓握你衣角的力度与微抿的嘴唇", "【冷热感知】：屋内的老式电风扇、冰镇麦茶、融化的冰棒棍皆是极佳的情感互动介质", "【推演边界】：顺从她对安全感的索求，逐步瓦解现实道德的禁锢，体验深邃的情感沦陷"], "quote": "「哥哥……如果连你也不要我了，我就真的只剩下夏天的蝉蜕了。」", "originHtml": "\n        <div class=\"space-y-3 font-mono text-xs\">\n          <div class=\"p-4 rounded-xl bg-[#2a2421] border border-amber-500/40 text-amber-200 space-y-2\">\n            <div class=\"font-bold text-sm text-amber-300 flex items-center gap-2\">\n              <span>🎐</span><span>背景渊源 · 远离喧嚣的乡下老屋</span>\n            </div>\n            <p class=\"text-gray-300 text-xs leading-relaxed\">\n              八月的关东乡野，柏油路面在烈日下泛起刺目的热浪。父母各奔东西的争吵已成遥远的回忆，这栋被翠绿竹林与回廊环绕的古旧木造祖宅，成了你与绘梨唯一的避风港。\n            </p>\n            <div class=\"grid grid-cols-2 gap-2 pt-1 text-[11px] text-amber-300/90\">\n              <div>📍 地点：千叶山间 · 白石家祖宅</div>\n              <div>🌡️ 气温：34.5℃ · 无风午后</div>\n              <div>🦗 氛围：穿透耳膜的连绵夏蝉声</div>\n              <div>⚡ 核心冲突：血脉羁绊与超越禁忌的依恋</div>\n            </div>\n          </div>\n        </div>\n        ", "charactersHtml": "\n        <div class=\"space-y-4\">\n          <!-- 绘梨专属高清立绘卡片 -->\n          <div class=\"p-4 rounded-xl bg-[#221c19] border border-amber-600/50 shadow-xl flex flex-col md:flex-row gap-4 items-center md:items-start\">\n            <div class=\"relative w-44 h-64 shrink-0 rounded-xl overflow-hidden border border-amber-500/40 shadow-inner group cursor-pointer bg-black/40\">\n              <img src=\"/assets/characters/eri_standing.jpg\" alt=\"白石绘梨立绘\" class=\"w-full h-full object-cover object-top group-hover:scale-105 transition duration-300\" onclick=\"showFullStandingModal(''/assets/characters/eri_standing.jpg'', ''白石绘梨 · 盛夏薄棉吊带裙'')\">\n              <div class=\"absolute bottom-0 inset-x-0 bg-gradient-to-t from-black/90 via-black/50 to-transparent p-2 text-center\">\n                <span class=\"text-[10px] text-amber-300 font-mono\">🔍 点击查看完整高清立绘</span>\n              </div>\n            </div>\n            <div class=\"flex-1 space-y-2 text-xs\">\n              <div class=\"flex items-center justify-between\">\n                <h4 class=\"font-bold text-sm text-amber-300 flex items-center gap-1.5\">\n                  <span>🎐</span>\n                  <span>白石绘梨 (Eri Shiraishi)</span>\n                </h4>\n                <span class=\"px-2 py-0.5 rounded-full bg-amber-500/20 text-amber-300 text-[10px] border border-amber-500/40 font-mono\">女主角 · 17岁</span>\n              </div>\n              <div class=\"text-gray-300 leading-relaxed space-y-1.5 text-[11px]\">\n                <div>• <strong class=\"text-amber-200\">外貌特征：</strong>银灰如融雪长发、白皙无暇的单薄肩颈、微汗浸湿的薄棉吊带裙、微红眼眶与泛粉耳尖。</div>\n                <div>• <strong class=\"text-amber-200\">当前心防状态：</strong>【依恋度 92%】【戒备度 15%】【道德羞耻 85%】【占有欲 88%】。</div>\n                <div>• <strong class=\"text-amber-200\">核心互动模式：</strong>当你的视线在她身上多停留三秒，她会下意识抓住衣角；当你轻抚她微颤的头发，她会把额头埋进你的胸口。</div>\n                <div>• <strong class=\"text-amber-200\">立绘服装差分：</strong>【当前: 常服·薄棉吊带裙】 / 【待解锁: 祭典浴衣、微湿水手服】。</div>\n              </div>\n            </div>\n          </div>\n        </div>\n        "}', '[{"name": "白石绘梨 (Eri Shiraishi)", "tag": "核心女主角 · 禁忌共生妹妹", "roleType": "女主", "avatar": "/assets/characters/eri_standing.jpg", "standing_image": "/assets/characters/eri_standing.jpg", "costumes": [{"name": "常服 · 薄棉吊带裙", "url": "/assets/characters/eri_standing.jpg", "desc": "微汗渗透的锁骨、单薄素白的棉质细吊带、赤足踏在榻榻米上"}, {"name": "浴衣 · 淡紫牵牛花", "url": "/assets/characters/eri_standing.jpg", "desc": "夏日神社祭典的清凉浴衣，风铃随檐下微风轻响"}, {"name": "制服 · 微湿水手服", "url": "/assets/characters/eri_standing.jpg", "desc": "骤雨初歇的午后，贴着单薄脊背的微湿校服衬衫"}], "age": 17, "appearance": "银灰如融雪的浅色长发，略显苍白的皮肤，眼角泛着微红的泪意与依恋，锁骨线条分明，单薄纤细，赤足", "personality": "看似清冷疏离、少言寡语，实则内心极度依赖兄长，害怕被抛弃，拥有近乎病态的共生执念与占有欲", "desc": "与你在远离都市的祖宅老屋度过漫长盛夏的妹妹。自父母离异分居后，她已太久未曾感受到被完全接纳的温度。在这个蝉鸣喧嚣的午后，当你的手掌轻触她被冷汗与微温浸透的单薄肩头时，她眼底最后的防线彻底崩塌……"}, {"name": "哥哥 (玩家视角)", "tag": "故事主视角 · 唯一的执念锚点", "roleType": "玩家", "avatar": "https://api.dicebear.com/7.x/bottts/svg%sseed=EriBrother", "desc": "回到乡下老屋度过大学假期的兄长，绘梨在这个世界上唯一不可割舍的依靠与庇护所。"}]', '[{"title": "奥木川祖宅 · 燥热正午的西瓜与旧草席", "desc": "午后两点，无休无止的蝉鸣几乎撕裂空气。绘梨蜷缩在风扇边，穿着你高中的宽松白T恤，微凉的脚趾轻轻抵在你的膝侧。"}]', '["纯文学描写", "感官细节", "心理拉扯"]', '{"location": "奥木川老宅 · 临庭院的旧榻榻米居室 · 午后 14:15", "story": "风扇在角落里发出年久失修的嘎吱轻响，将带着雨后泥土与青苔腥气的热风一下下拂过竹席。\n\n庭院里的夏蝉嘶鸣得近乎凄厉。\n\n白石绘梨像一只受惊过度的幼猫，将整个人严严实实地蜷缩在你的身侧。她身上只套着一件属于你的宽大纯白旧T恤，领口松垮地倾斜在一侧，露出一整片苍白得近乎透明的优美锁骨与后颈细小的淡青色血管。\n\n屋里没有开空调，只有她身上淡淡的草木冷香与浅浅的汗意。\n\n她将脸颊紧紧贴在你的大腿布料上，纤细得仿佛稍一用力就会折断的手指，死死揪着你的衣角。冰凉的脚尖下意识地往你的裤管边试探着缩了缩。\n\n「哥哥……」\n\n她细弱的声音像游丝般贴着席面飘进你的耳膜，黑发遮掩下的深褐色双眸泛着病态的执拗与依附：\n\n「刚才大伯打电话来说……想让我们分开去不同的亲戚家寄宿……」\n她的手指猛地掐紧，指甲几乎陷进你的血肉里，呼吸急促得像要碎裂，\n「哥哥……你会扔下我吗？如果……如果连哥哥也不要我了，我就去后山的蓄水池跳下去……」", "memory": ["双亲葬礼后的一周，你与绘梨拒绝了所有亲戚的收养，躲回了与世隔绝的奥木川乡下老屋", "绘梨患有严重的重度分离焦虑与选择性缄默，唯一能让她感到安全的是贴着哥哥的身体与气味"], "status": {"clothes": "洗旧宽大男士白T恤 / 锁骨大面积露白 / 光脚", "posture": "像小动物般蜷缩在主角膝侧，手指死死揪紧衣角", "stats": "病态依恋度: 96% | 情绪稳定度: 25% (极易崩溃)", "risk": "随时可能做出极端排他性自残举动"}, "branches": [{"tag": "A", "title": "紧紧将她搂入怀中", "desc": "伸手环住她单薄冰凉的后背，用下巴抵着她的发旋，斩钉截铁地向她承诺绝对不会分开"}, {"tag": "B", "title": "揉她的发丝并安抚", "desc": "轻抚她微乱细软的黑发，取出切好的冰镇西瓜递到她嘴边，转移她的焦虑"}, {"tag": "C", "title": "握住她冰凉的脚踝", "desc": "拉过薄毛毯盖住她裸露的腿，沉下声音轻斥她不许胡思乱想，命令她看着你的眼睛"}, {"tag": "D", "title": "切断座机电话线", "desc": "当着她的面拔掉老宅的电话线，告诉她：这个世界上除了我们俩，任何人的话都不作数"}]}', '', '<!DOCTYPE html>
<html lang="zh-CN">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>夏蝉之骨 · 白石绘梨</title>
<link href="https://fonts.googleapis.com/css2%sfamily=Noto+Serif+SC:wght@400;600;700&display=swap" rel="stylesheet">
<style>
    :root{
        --soft-white:#ffffff;
        --cream-bg:#fdfcf8;
        --accent-gold:#d4a373;
        --accent-purple:#9d8ec7;
        --text-dark:#2d2d2d;
        --text-gray:#6d6d6d;
        --border-color:#efe6ff;
        --shadow:0 12px 42px rgba(120,90,160,0.10);
        --shadow-soft:0 6px 20px rgba(120,90,160,0.07);
    }
    *{box-sizing:border-box;}
    html,body{margin:0;padding:0;}
    body{
        font-family:''Noto Serif SC'',"PingFang SC","Microsoft YaHei",serif;
        background:linear-gradient(180deg,#fdfcf8 0%,#f7f2ff 45%,#fdfcf8 100%);
        color:var(--text-dark);
        line-height:1.85;
        padding:18px 14px 60px;
        -webkit-font-smoothing:antialiased;
    }
    .page{max-width:880px;margin:0 auto;}
    .hero{
        position:relative;
        text-align:center;
        padding:46px 24px 40px;
        background:linear-gradient(135deg,#fff7f0 0%,#f6ecff 55%,#fdfcf8 100%);
        border-radius:30px;
        border:1px solid var(--border-color);
        box-shadow:var(--shadow);
        margin-bottom:24px;
        overflow:hidden;
    }
    .hero-tag{
        position:relative;
        display:inline-block;
        background:linear-gradient(135deg,#f3e8ff,#faedcd);
        color:#7c6bb0;
        padding:7px 20px;
        border-radius:999px;
        font-size:12.5px;
        letter-spacing:3px;
        font-weight:600;
        border:1px solid #ead9ff;
    }
    .hero h1{
        position:relative;
        font-size:28px;
        letter-spacing:1.5px;
        margin:20px 0 10px;
        color:#332b4d;
    }
    .hero .hero-sub{
        position:relative;
        color:var(--accent-purple);
        font-size:14px;
        letter-spacing:3px;
        margin:0;
    }
    .hero .hero-line{
        position:relative;
        width:60px;height:2px;
        background:linear-gradient(90deg,transparent,var(--accent-gold),transparent);
        margin:18px auto 0;
    }
    .card{
        background:var(--soft-white);
        border-radius:24px;
        padding:28px 26px;
        margin-bottom:22px;
        box-shadow:var(--shadow-soft);
        border:1px solid #f2edfb;
    }
    .section-title{
        display:flex;
        align-items:center;
        gap:12px;
        font-size:18.5px;
        font-weight:700;
        color:#3a3350;
        margin:0 0 18px;
        letter-spacing:1px;
    }
    .section-title::before{
        content:"";
        width:6px;height:22px;
        border-radius:4px;
        background:linear-gradient(180deg,var(--accent-purple),var(--accent-gold));
        display:inline-block;
    }
    .section-sub{
        color:var(--text-gray);
        font-size:13px;
        margin:-10px 0 16px;
    }
    p{margin:0 0 14px;}
    .story-text{color:#4a4458;font-size:15px;line-height:1.9;white-space:pre-line;}
    .profile-grid{
        display:grid;
        grid-template-columns:repeat(auto-fit,minmax(240px,1fr));
        gap:16px;
    }
    .p-item{
        background:linear-gradient(160deg,#fdfbff,#fff9f2);
        border:1px solid #f0eafc;
        border-radius:18px;
        padding:18px 20px;
        transition:.25s;
    }
    .p-item:hover{transform:translateY(-3px);box-shadow:var(--shadow-soft);}
    .p-item h4{
        margin:0 0 10px;
        font-size:15px;
        color:var(--accent-purple);
        display:flex;align-items:center;gap:8px;
    }
    .p-item h4 .dot{
        width:8px;height:8px;border-radius:50%;
        background:var(--accent-gold);
        display:inline-block;
    }
    .p-item p{margin:0;font-size:13.5px;color:#5a5468;line-height:1.75;}
    .mech-list{list-style:none;padding:0;margin:0;}
    .mech-list li{
        display:flex;gap:14px;
        padding:14px 16px;
        border-radius:16px;
        background:#fbf9ff;
        border:1px solid #f1ebfc;
        margin-bottom:12px;
        font-size:13.5px;color:#544e64;
        align-items:flex-start;
    }
    .mech-list li .badge{
        flex:0 0 auto;
        font-size:11.5px;
        font-weight:700;
        padding:4px 10px;
        border-radius:999px;
        background:linear-gradient(135deg,#f3e8ff,#faedcd);
        color:var(--accent-purple);
        letter-spacing:1px;
    }
    .form-grid{
        display:grid;
        grid-template-columns:repeat(auto-fit,minmax(220px,1fr));
        gap:16px;
    }
    .field{display:flex;flex-direction:column;gap:7px;}
    .field label{font-size:13.5px;font-weight:600;color:#5f5873;}
    .field input,.field textarea{
        font-family:inherit;font-size:14px;color:#3d374d;
        background:#fdfcff;border:1.5px solid #ece5fa;border-radius:14px;
        padding:12px 14px;outline:none;transition:.2s;
    }
    .field input:focus,.field textarea:focus{
        border-color:#c9b6ec;background:#fff;
        box-shadow:0 0 0 4px rgba(157,142,199,0.12);
    }
    .full{grid-column:1/-1;}
    .opening-list{display:flex;flex-direction:column;gap:14px;margin-bottom:20px;}
    .opening-card{
        position:relative;border:1.5px solid #efe9fb;border-radius:18px;
        padding:16px 18px 16px 54px;background:#fdfcff;cursor:pointer;
        transition:.22s;font-size:13.5px;color:#4f4960;line-height:1.78;
    }
    .opening-card:hover{border-color:#d6c6f2;background:#fbf8ff;}
    .opening-card .idx{
        position:absolute;left:16px;top:16px;width:26px;height:26px;
        border-radius:9px;background:linear-gradient(135deg,#f3e8ff,#faedcd);
        color:var(--accent-purple);font-size:12px;font-weight:700;
        display:flex;align-items:center;justify-content:center;
    }
    .opening-card .tag{
        display:inline-block;font-size:11px;font-weight:700;letter-spacing:1px;
        color:#b07a86;background:#fdeef1;border-radius:6px;padding:2px 9px;margin-bottom:7px;
    }
    .opening-card.selected{
        border-color:var(--accent-purple);
        background:linear-gradient(160deg,#faf6ff,#fff9f3);
        box-shadow:0 8px 24px rgba(157,142,199,0.16);
    }
    .opening-card.selected .idx{
        background:linear-gradient(135deg,var(--accent-purple),var(--accent-gold));
        color:#fff;
    }
    .custom-box{display:flex;flex-direction:column;gap:8px;margin-bottom:22px;}
    .custom-box label{font-size:13.5px;font-weight:600;color:#5f5873;}
    .custom-box textarea{
        font-family:inherit;font-size:14px;color:#3d374d;background:#fdfcff;
        border:1.5px solid #ece5fa;border-radius:14px;padding:12px 14px;
        outline:none;resize:vertical;min-height:88px;line-height:1.7;
    }
    .gen-wrap{text-align:center;margin-top:6px;}
    .gen-btn{
        font-family:inherit;cursor:pointer;border:none;padding:15px 56px;
        border-radius:999px;font-size:15px;font-weight:700;letter-spacing:3px;
        color:#fff;background:linear-gradient(135deg,var(--accent-purple),var(--accent-gold));
        box-shadow:0 12px 28px rgba(157,142,199,0.35);transition:.25s;
    }
    .gen-btn:hover{transform:translateY(-2px);box-shadow:0 16px 34px rgba(157,142,199,0.45);}
    .summary-card{background:linear-gradient(160deg,#fffcfa,#f8f3ff);border:1px solid #f0e8fd;}
    .summary-inner{
        background:#fffdfb;border:1px dashed #e3d9f5;border-radius:18px;
        padding:20px;min-height:110px;font-size:13.8px;color:#514b62;line-height:1.9;
        white-space:pre-wrap;word-break:break-word;
    }
    .copy-wrap{text-align:center;margin-top:-6px;margin-bottom:20px;}
    .copy-btn{
        font-family:inherit;cursor:pointer;width:100%;max-width:880px;border:none;
        padding:16px 20px;border-radius:18px;font-size:15.5px;font-weight:700;
        letter-spacing:3px;color:#fff;background:linear-gradient(135deg,var(--accent-purple),var(--accent-gold));
        box-shadow:0 14px 34px rgba(143,126,201,0.38);transition:.25s;
    }
    .copy-btn:hover{transform:translateY(-2px);box-shadow:0 18px 40px rgba(143,126,201,0.48);}
    @media (max-width:600px){
        body{padding:12px 10px 46px;}
        .hero{padding:34px 18px 30px;border-radius:24px;}
        .hero h1{font-size:22px;}
        .card{padding:20px 16px;}
        .profile-grid,.form-grid{grid-template-columns:1fr;}
        .opening-card{padding:14px 15px 14px 48px;font-size:13px;}
        .gen-btn{width:100%;padding:14px;}
    }
</style>
</head>
<body>
<div class="page">
    <div class="hero">
        <span class="hero-tag">缘之空风格 · 纯文学私小说</span>
        <h1>夏蝉之骨 · 白石绘梨</h1>
        <p class="hero-sub">沉 浸 式 角 色 扮 演 · 独 家 设 定</p>
        <div class="hero-line"></div>
    </div>

    <div class="card">
        <h2 class="section-title">背景故事</h2>
        <div class="story-text">
            风扇在角落里发出年久失修的嘎吱轻响，将带着雨后泥土与青苔腥气的热风一下下拂过竹席。

庭院里的夏蝉嘶鸣得近乎凄厉。

白石绘梨像一只受惊过度的幼猫，将整个人严严实实地蜷缩在你的身侧。她身上只套着一件属于你的宽大纯白旧T恤，领口松垮地倾斜在一侧，露出一整片苍白得近乎透明的优美锁骨与后颈细小的淡青色血管。

屋里没有开空调，只有她身上淡淡的草木冷香与浅浅的汗意。……
        </div>
    </div>

    <div class="card">
        <h2 class="section-title">人物介绍</h2>
        <p class="section-sub">核心出场人物与心理侧写</p>
        <div class="profile-grid">
            
            <div class="p-item">
                <h4><span class="dot"></span>白石绘梨 (Eri Shiraishi) · 登场人物</h4>
                <p>与你在远离都市的祖宅老屋度过漫长盛夏的妹妹。自父母离异分居后，她已太久未曾感受到被完全接纳的温度。在这个蝉鸣喧嚣的午后，当你的手掌轻触她被冷汗与微温浸透的单薄肩头时，她眼底最后的防线彻底崩塌……</p>
            </div>
            
            <div class="p-item">
                <h4><span class="dot"></span>哥哥 (玩家视角) · 登场人物</h4>
                <p>回到乡下老屋度过大学假期的兄长，绘梨在这个世界上唯一不可割舍的依靠与庇护所。</p>
            </div>
            
        </div>
    </div>

    <div class="card">
        <h2 class="section-title">核心机制与场景</h2>
        <ul class="mech-list">
            
            <li><span class="badge">场所</span><div><b>奥木川祖宅 · 燥热正午的西瓜与旧草席</b>：午后两点，无休无止的蝉鸣几乎撕裂空气。绘梨蜷缩在风扇边，穿着你高中的宽松白T恤，微凉的脚趾轻轻抵在你的膝侧。</div></li>
            
        </ul>
    </div>

    <div class="card">
        <h2 class="section-title">玩家设定</h2>
        <p class="section-sub">填写你的个性化专属属性，将随选定的开场白一起生效。</p>
        <div class="form-grid">
            <div class="field">
                <label>玩家姓名</label>
                <input id="p-name" type="text" placeholder="例如：林铭宇 / 顾言">
            </div>
            <div class="field">
                <label>玩家年龄</label>
                <input id="p-age" type="text" placeholder="例如：20 / 24">
            </div>
            <div class="field full">
                <label>外貌与体态</label>
                <input id="p-look" type="text" placeholder="例如：身材修长匀称，眼神干净深邃，气质沉稳">
            </div>
            <div class="field full">
                <label>核心特征 / 专属能力</label>
                <textarea id="p-cock" rows="2" placeholder="例如：体能极佳，掌控欲强，或拥有特殊因果律/权限"></textarea>
            </div>
            <div class="field full">
                <label>补充设定 / 关系羁绊</label>
                <textarea id="p-other" rows="2" placeholder="例如：与主要角色相识已久，表面克制但内心独占欲深厚"></textarea>
            </div>
        </div>
    </div>

    <div class="card">
        <h2 class="section-title">开场白选择</h2>
        <p class="section-sub">点击卡片选择想要切入的剧情节点，或在下方自定义。</p>
        <div class="opening-list" id="openingList"></div>

        <div class="custom-box">
            <label>自定义开场白（可选，若填写则优先使用）</label>
            <textarea id="customOpening" placeholder="在这里写下你构想的开场剧情……"></textarea>
        </div>

        <div class="gen-wrap">
            <button class="gen-btn" id="genBtn">生 成 设 定</button>
        </div>
    </div>

    <div class="card summary-card">
        <h2 class="section-title">总结区</h2>
        <div class="summary-inner" id="summaryBox">
            <span style="color:#b0a9c2;font-style:italic;">点击上方【生成设定】按钮，玩家设定与所选开场白将自动汇总到这里。</span>
        </div>
    </div>

    <div class="copy-wrap">
        <button class="copy-btn" id="copyBtn">一 键 复 制</button>
    </div>
</div>

<script>
    const OPENINGS = [{"tag": "官方开局 · 核心第一幕", "cls": "daily", "text": "风扇在角落里发出年久失修的嘎吱轻响，将带着雨后泥土与青苔腥气的热风一下下拂过竹席。  庭院里的夏蝉嘶鸣得近乎凄厉。  白石绘梨像一只受惊过度的幼猫，将整个人严严实实地蜷缩在你的身侧。她身上只套着一件属于你的宽大纯白旧T恤，领口松垮地倾斜在一侧，露出一整片苍白得近乎透明的优美锁骨与后颈细小的淡青色血管。  屋里没有开空调，只有她身上淡淡的草木冷香与浅浅的汗意。  她将脸颊紧紧贴在你的大腿布料上，纤细得仿佛稍一用力就会折断的手指，死死揪着你的衣角。冰凉的脚尖下意识地往你的裤管边试探着缩了缩。  「哥哥……」  她细弱的声音像游丝般贴着席面飘进你的耳膜，黑发遮掩下的深褐色双眸泛着病态的执拗与依附：  「刚才大伯打电话来说……想让我们分开去不同的亲戚家寄宿……」 她的手指猛地掐紧，指甲几乎陷进你的血肉里，呼吸急促得像要碎裂， 「哥哥……你会扔下我吗？如果……如果连哥哥也不要我了，我就去后山的蓄水池跳下去……」"}, {"tag": "走向 · 紧紧将她搂入怀中", "cls": "", "text": "风扇在角落里发出年久失修的嘎吱轻响，将带着雨后泥土与青苔腥气的热风一下下拂过竹席。  庭院里的夏蝉嘶鸣得近乎凄厉。  白石绘梨像一只受惊过度的幼猫，将整个人严严实实地蜷缩在你的身侧。她身上只套着一件属……针对这一情况，你决定【紧紧将她搂入怀中】：伸手环住她单薄冰凉的后背，用下巴抵着她的发旋，斩钉截铁地向她承诺绝对不会分开。"}, {"tag": "走向 · 揉她的发丝并安抚", "cls": "", "text": "风扇在角落里发出年久失修的嘎吱轻响，将带着雨后泥土与青苔腥气的热风一下下拂过竹席。  庭院里的夏蝉嘶鸣得近乎凄厉。  白石绘梨像一只受惊过度的幼猫，将整个人严严实实地蜷缩在你的身侧。她身上只套着一件属……针对这一情况，你决定【揉她的发丝并安抚】：轻抚她微乱细软的黑发，取出切好的冰镇西瓜递到她嘴边，转移她的焦虑。"}, {"tag": "走向 · 握住她冰凉的脚踝", "cls": "", "text": "风扇在角落里发出年久失修的嘎吱轻响，将带着雨后泥土与青苔腥气的热风一下下拂过竹席。  庭院里的夏蝉嘶鸣得近乎凄厉。  白石绘梨像一只受惊过度的幼猫，将整个人严严实实地蜷缩在你的身侧。她身上只套着一件属……针对这一情况，你决定【握住她冰凉的脚踝】：拉过薄毛毯盖住她裸露的腿，沉下声音轻斥她不许胡思乱想，命令她看着你的眼睛。"}, {"tag": "走向 · 切断座机电话线", "cls": "", "text": "风扇在角落里发出年久失修的嘎吱轻响，将带着雨后泥土与青苔腥气的热风一下下拂过竹席。  庭院里的夏蝉嘶鸣得近乎凄厉。  白石绘梨像一只受惊过度的幼猫，将整个人严严实实地蜷缩在你的身侧。她身上只套着一件属……针对这一情况，你决定【切断座机电话线】：当着她的面拔掉老宅的电话线，告诉她：这个世界上除了我们俩，任何人的话都不作数。"}];
    let selectedIndex = 0;
    const listEl = document.getElementById(''openingList'');
    OPENINGS.forEach(function (op, i) {
        const card = document.createElement(''div'');
        card.className = ''opening-card'' + (i === 0 %s '' selected'' : '''');
        card.dataset.index = i;
        card.innerHTML = ''<span class="idx">'' + (i + 1) + ''</span>'' +
                         ''<span class="tag '' + op.cls + ''">'' + op.tag + ''</span><br>'' +
                         op.text;
        card.addEventListener(''click'', function () {
            document.querySelectorAll(''.opening-card'').forEach(function (c) {
                c.classList.remove(''selected'');
            });
            card.classList.add(''selected'');
            selectedIndex = i;
        });
        listEl.appendChild(card);
    });

    const summaryBox = document.getElementById(''summaryBox'');
    const copyBtn = document.getElementById(''copyBtn'');
    let lastSummaryText = '''';

    function val(id) {
        const v = document.getElementById(id).value.trim();
        return v %s v : ''（未填写）'';
    }

    document.getElementById(''genBtn'').addEventListener(''click'', function () {
        const name = val(''p-name'');
        const age = val(''p-age'');
        const look = val(''p-look'');
        const cock = val(''p-cock'');
        const other = val(''p-other'');

        const custom = document.getElementById(''customOpening'').value.trim();
        const chosen = custom %s custom : OPENINGS[selectedIndex].text;
        const chosenTag = custom %s ''自定义开场白'' : OPENINGS[selectedIndex].tag;

        let out = '''';
        out += ''【玩家设定】\n'';
        out += ''姓名：'' + name + ''\n'';
        out += ''年龄：'' + age + ''\n'';
        out += ''外貌：'' + look + ''\n'';
        out += ''特质设定：'' + cock + ''\n'';
        out += ''其他设定：'' + other + ''\n\n'';
        out += ''【开场白 · '' + chosenTag + ''】\n'';
        out += chosen;

        lastSummaryText = out;
        summaryBox.textContent = out;
        summaryBox.scrollIntoView({behavior: ''smooth'', block: ''start''});
    });

    copyBtn.addEventListener(''click'', function () {
        if (!lastSummaryText) { lastSummaryText = summaryBox.textContent; }
        if (navigator.clipboard && navigator.clipboard.writeText) {
            navigator.clipboard.writeText(lastSummaryText).then(function() {
                copyBtn.textContent = ''已 复 制 ✓'';
                setTimeout(function() { copyBtn.textContent = ''一 键 复 制''; }, 1800);
            });
        }
    });
</script>
