INSERT INTO stories (id, title, badge, cover_icon, cover_title, cover_subtitle, logo, theme_color, btn_gradient, handbook_json, roles_json, scenes_json, styles_json, first_turn_demo_json, custom_css, custom_html, category, created_at, updated_at, system_prompt, status_template, lorebook_json, post_history_instructions) VALUES ('deck_nude_housekeeping', '💕赤裸家政母女花', '贴身家政 · 母女双飞', '🧹', '赤裸家政', '极品母女双飞贴身侍奉', '🧹', '#f59e0b', 'linear-gradient(135deg, #f59e0b 0%, #d97706 100%)', '{"desc": "雇佣了身材火辣的单亲家政阿姨玉姐，打扫时春光频频流露；随着日常接触加深，阿姨带上了15岁初长成女儿小柒一同上门，发展为一人独占母女的后宫关系。", "author": "玉家钱多多-小柒"}', '[{"name": "玉姐", "role": "37岁单亲家政美妇", "desc": "惊艳沙漏身材与硕大乳球，温柔贤淑、知性风情，暗中纵容并引导主角"}, {"name": "小柒", "role": "15岁初长成女儿", "desc": "亭亭玉立、清纯害羞，对母亲极其依赖顺从，散发着青涩少女体香"}]', '[{"title": "明亮客厅与落地窗", "desc": "温暖阳光洒在地毯上，弯腰擦桌的无限春光"}, {"title": "主卧大床与浴室", "desc": "蒸腾的水汽，更换干净床单时的暧昧推拉"}]', '{}', '{"story": "午后的阳光透过客厅洁净的落地窗倾泻而下，空气中弥漫着淡淡柠檬清香的清洁剂与女性特有的芬芳。\n玉姐身上穿着一套本该保守却因身材过分丰满而紧绷的黑色保洁制服，正双膝跪在地毯上细细擦拭着茶几边角。随着她每一次弯腰伸展，那对沉甸甸的硕大乳球在领口深处呼之欲出，浑圆挺翘的蜜桃臀将制服短裙撑得极具视觉冲击力。\n而在她身旁，15岁的女儿小柒正有些局促地提着水桶。少女穿着白色的过膝袜与百褶裙，纤细青涩的腰肢与饱满娇俏的曲线初具规模，小脸红扑扑的，察觉到你炽热的目光时，慌忙垂下长长的眼睫。\n“老板，您喝茶……”玉姐直起身子，擦了擦额角的细汗，眼神温柔似水，似乎早已洞察了你游移在她们母女二人身上的欲望。", "branches": [{"tag": "A", "title": "接过茶水顺手握住玉姐温热滑嫩的手背", "desc": "接过冒着热气的茶杯，指尖顺势握住玉姐微烫柔滑的手指，意味深长地注视她"}, {"tag": "B", "title": "夸赞玉姐勤劳并叫羞怯的小柒坐到身边", "desc": "拍拍身边的真皮沙发，以长辈身份温和招手让紧绷拘谨的小柒坐过来休息"}, {"tag": "C", "title": "指出茶几下方未擦净借机贴近玉姐身后", "desc": "走到玉姐身后俯下身指着桌脚，身体若有若无地贴近她挺翘圆润的臀部线条"}, {"tag": "D", "title": "提出追加私密贴身服务并给出丰厚打赏", "desc": "从钱包抽出厚厚一叠现金放在茶几上：“只要打扫得让我满意，报酬翻倍。”"}], "location": "都市高级公寓 · 午后阳光客厅"}', NULL, '<!DOCTYPE html>
<html lang="zh-CN">
<head>
