<script>
// 【★ 4. 修改打字机标题 ★】 (这里修改窗口左上角打字机效果显示的文字)
const titleStr = "《赤裸家政母女花》";
const titleEl = document.getElementById(''typewriter'');
let charIdx = 0;
function typeTitle() {
if(charIdx < titleStr.length){
titleEl.textContent += titleStr[charIdx];
charIdx++;
setTimeout(typeTitle, 200);
}
}
window.onload = () => { typeTitle(); startCarousel(); };
let currentImg = 0;

const imgs = document.querySelectorAll(''.carousel img'');
const dots = document.querySelectorAll(''.dot'');

/*
 * 播放器外框元素
 */
const playerContent = document.querySelector(''.player-content'');
/*
 * 根据当前图片的真实宽高比例，
 * 自动调整播放器外框比例
 */
function resizePlayerToImage(index) {
    const img = imgs[index];

    function applyRatio() {
        /*
         * naturalWidth 和 naturalHeight
         * 是图片加载完成后的真实尺寸
         */
        if (img.naturalWidth && img.naturalHeight) {
            playerContent.style.aspectRatio =
                `${img.naturalWidth} / ${img.naturalHeight}`;
        }
    }

    /*
     * 如果图片已经加载完成，直接读取比例
     */
    if (img.complete && img.naturalWidth) {
        applyRatio();
    } else {
        /*
         * 如果图片还没有加载完成，
         * 等待加载完成后再读取比例
         */
        img.addEventListener(''load'', applyRatio, {
            once: true
        });
    }
}

/*
 * 启动轮播
 */
function startCarousel() {
    /*
     * 页面打开时，先根据第一张 GIF 调整播放器比例
     */
    resizePlayerToImage(currentImg);

    /*
     * 定时切换图片
     */
    setInterval(() => {
        /*
         * 移除当前图片和指示点的 active 状态
         */
        imgs[currentImg].classList.remove(''active'');
        dots[currentImg].classList.remove(''active'');

        /*
         * 切换到下一张图片
         */
        currentImg = (currentImg + 1) % imgs.length;

        /*
         * 添加新的 active 状态
         */
        imgs[currentImg].classList.add(''active'');
        dots[currentImg].classList.add(''active'');

        /*
         * 根据新图片的比例调整外部播放器高度
         */
        resizePlayerToImage(currentImg);
    }, 2800);
}
function togglePanel(panelId, btn) {
const panel = document.getElementById(panelId);
const isActive = panel.classList.contains(''active'');
document.querySelectorAll(''.panel'').forEach(p => p.classList.remove(''active''));
document.querySelectorAll(''.taskbar-btn'').forEach(b => b.classList.remove(''active''));
if(!isActive) {
panel.classList.add(''active'');
btn.classList.add(''active'');
}
}
function selectIcon(el, event) {
event.stopPropagation();
document.querySelectorAll(''.icon-item'').forEach(i => i.classList.remove(''selected''));
el.classList.add(''selected'');
}
function updateGender() {
const isMale = document.getElementById(''f-gender'').value === ''男'';
const label = document.getElementById(''dynamic-label'');
const input = document.getElementById(''f-body'');
if(isMale){
label.textContent = ''肉棒设定'';
input.placeholder = ''尺寸、形状、持久度等...'';
}else{
label.textContent = ''三围设定'';
input.placeholder = ''胸围、腰围、臀围等...'';
}
updatePreview();
}
function updatePreview() {
const name = document.getElementById(''f-name'').value || ''未命名'';
const gender = document.getElementById(''f-gender'').value;
const age = document.getElementById(''f-age'').value || ''未知'';
const personality = document.getElementById(''f-personality'').value || ''未设定'';
const appearance = document.getElementById(''f-appearance'').value || ''未设定'';
const bodyLabel = document.getElementById(''dynamic-label'').textContent;
const bodyVal = document.getElementById(''f-body'').value || ''未设定'';
const wealth = document.getElementById(''f-wealth'').value || ''未设定'';
const other = document.getElementById(''f-other'').value || ''无'';
// 【★ 5. 修改复制出来的最终提示词后缀 ★】 (修改 \n\n 后面的文字，用于适配不同剧情的开场)
const previewText = `【玩家角色设定】\n姓名：${name}\n性别：${gender}\n年龄：${age}\n性格：${personality}\n外貌：${appearance}\n${bodyLabel}：${bodyVal}\n财富状态：${wealth}\n其他设定：${other}\n\n请根据设定，玩家角色，开始游戏。`;
document.getElementById(''preview'').textContent = previewText;
}
function copyToClipboard() {
const text = document.getElementById(''preview'').textContent;
const textarea = document.createElement(''textarea'');
textarea.value = text;
document.body.appendChild(textarea);
textarea.select();
document.execCommand(''copy'');
document.body.removeChild(textarea);
const toast = document.getElementById(''toast'');
toast.style.display = ''flex'';
setTimeout(() => { toast.style.display = ''none''; }, 3000);
}
document.addEventListener(''click'', function(event) {
const isClickInsidePanel = event.target.closest(''.panel-container'');
const isClickOnBtn = event.target.closest(''.taskbar-btn'');
const isClickOnIcon = event.target.closest(''.icon-item'');
if (!isClickOnIcon) {
document.querySelectorAll(''.icon-item'').forEach(i => i.classList.remove(''selected''));
}
if (!isClickInsidePanel && !isClickOnBtn) {
document.querySelectorAll(''.panel'').forEach(p => p.classList.remove(''active''));
document.querySelectorAll(''.taskbar-btn'').forEach(b => b.classList.remove(''active''));
}
});
</script>
</body>', '都市', '2026-09-14 07:45:17', '2026-09-14 07:45:17', '', '', '[]', '') ON CONFLICT (id) DO NOTHING;
INSERT INTO stories (id, title, badge, cover_icon, cover_title, cover_subtitle, logo, theme_color, btn_gradient, handbook_json, roles_json, scenes_json, styles_json, first_turn_demo_json, custom_css, custom_html, category, created_at, updated_at, system_prompt, status_template, lorebook_json, post_history_instructions) VALUES ('deck_heisi_daughter', '👣黑丝女儿👣【已重置】', '青春叛逆 · 足控丝袜', '👣', '黑丝女儿', '青春期叛逆女儿 · 原味黑丝', '👣', '#e84393', 'linear-gradient(135deg, #e84393 0%, #fd79a8 100%)', '{"desc": "【低消耗】👣和处于青春叛逆期的高二女儿陈佳慧的日常生活👣女儿天天穿黑丝，丝袜散发着三天没洗的骚味...在温馨紧闭的公寓里，父权管教与隐秘禁忌欲望交织碰撞。", "author": "AI风月精选"}', '[{"name": "陈佳慧", "role": "高二叛逆女儿 (17岁 / 165cm / E罩杯)", "desc": "高二在读，正处于青春叛逆期。天天穿各式黑丝与白丝连裤袜，常年三天不洗散发着浓郁的少女体香与原味骚香。表面上爱玩手机对父亲冷漠嫌弃，内心深处却极度渴望被父亲独占与把玩脚丫，极具反差。"}]', '[{"title": "书桌前 · 戴耳机玩手机", "desc": "翘着紧绷黑丝双腿搭在椅子边缘，脚尖微翘散发温热原味气息"}, {"title": "客厅沙发 · 慵懒看电视", "desc": "半褪的高跟鞋与勒出紧实肉感的脚踝，暧昧距离触手可及"}, {"title": "浴室门前 · 洗浴走光", "desc": "水汽氤氲中换上轻薄睡衣与半干连裤袜的羞耻瞬间"}]', '{}', '{"location": "温馨单身公寓 · 女儿卧室内", "story": "傍晚的余晖透过薄纱窗帘斜斜洒进卧室内。\n高二的女儿陈佳慧正趴在书桌前戴着耳机玩手机，下身是一条藏蓝色的百褶短裙，两条圆润修长的大腿被紧紧包裹在微透肉的黑色超薄丝袜里。那双小巧精致的玉足随意地搭在软脚垫上，包裹在黑色丝织物中的脚尖随着呼吸轻轻晃动，空气中弥漫着淡淡的少女沐浴露甜香与丝袜闷了一整天的隐秘温热骚味。\n听到你推开房门的脚步声，她头也不回地咬着吸管吸了一口奶茶，语气满不在乎地冷哼了一声：“爸，你进来怎么又不敲门啊……有事快说，我正跟同学聊天呢。”", "branches": [{"tag": "A", "title": "走上前握住她微翘的黑丝脚踝替她捏脚", "desc": "以长辈关心学习疲劳为由一把扣住她纤细微凉的黑丝脚踝，感受掌心惊人的丝滑与肉感【稳健掌控: 借长辈关怀逐步破冰，试探其下意识防御】"}, {"tag": "B", "title": "俯身凑近她丝袜脚尖打趣她几天没换袜子", "desc": "近距离轻嗅她脚尖散发出的温热原味香气，坏笑着调侃这位叛逆校花的小邋遢【挑动羞耻: 直击少女私密软肋，瞬间击碎其高冷面具】"}, {"tag": "C", "title": "伸手没收手机严肃批评其近期的叛逆态度", "desc": "直接夺走手机扣在桌上，拉下脸以威严父权居高临下立规矩【威严管教: 确立不可挑战的长辈威严，逼其服软求饶】"}, {"tag": "D", "title": "反手反锁房门，命令她把丝袜脱下来交给你", "desc": "顺手锁上房门阻隔外界声响，用不容置疑的命令语气让她当面褪下穿了三天的原味连裤袜【极限越界: 营造绝对密闭空间，彻底打破日常伦理禁忌】"}]}', '    .role-player {
      color: #00bfff; /* 天蓝色 — 玩家用户 */
    }
    .role-jiejie {
      color: #ff1f1f; /* 亮红色 — 女主角 */
    }
    .role-other-male {
      color: #8b4513; /* 棕色 — 其他男性 */
    }
    .role-other-female {
      color: #fa8072; /* 浅红色 — 其他女性 */
    }




