INSERT INTO stories (id, title, badge, cover_icon, cover_title, cover_subtitle, logo, theme_color, btn_gradient, handbook_json, roles_json, scenes_json, styles_json, first_turn_demo_json, custom_css, custom_html, category, created_at, updated_at, system_prompt, status_template, lorebook_json, post_history_instructions) VALUES ('deck_nude_girls_school', '🌸全裸女校，只有你是特招', '全裸铁律 · 唯我特招', '🌸', '🌸全裸女校，只有你是特招', '全裸铁律 · 唯我特招', 'https://catai.wiki/4d39b21c-82c1-4986-8feb-1f5a25806e00/cover', 'bg-pink-950/90 text-pink-300 border-pink-600/60', 'from-rose-600 to-purple-600', '{"title": "🌸全裸女校，只有你是特招", "desc": "【超低耗】【全校全裸】【唯一男生】全封闭圣伊甸贵族女子学园，三千名名门千金一丝不挂。因报名系统故障，你作为特招生成为了建校百年唯一的男学生。入校即脱衣——面对全校全裸的绝对铁律，全校只有公共女浴室与女更衣室，面对少女们毫不避讳的目光与生理课老师的热烈研究，你该如何生存与征服？", "bg_image": "https://catai.wiki/6ef5e821-d7db-4a16-808a-a90d95975900/bg"}', '[{"name": "主人公", "desc": "【超低耗】【全校全裸】【唯一男生】全封闭圣伊甸贵族女子学园，三千名名门千金一丝不挂。因报名系统故障，你作为特招生成为了建校百年唯一的男学生。入校即脱衣——面对全校全裸的绝对铁律，全校只有公共女浴室与女更衣室，面对少女们毫不避讳的目光与生理课老师的热烈研究，你该如何生存与征服？", "role_type": "protagonist"}]', '[{"title": "圣伊甸贵族女子学园 · 入学校门强制更衣室 · 上午", "desc": "【超低耗】【全校全裸】【唯一男生】全封闭圣伊甸贵族女子学园，三千名名门千金一丝不挂。因报名系统故障，你作为特招生成为了建校百年唯一的男学生。入校即脱衣——面对全校全裸的绝对铁律，全校只有公共女浴室与女更衣室，面对少女们毫不避讳的目光与生理课老师的热烈研究，你该如何生存与征服？"}]', '{"dialogue_style": "沉浸式感官细节描写，兼顾心理摩擦、禁断张力与高潮爆发", "format": "AI风月标准双栏规范"}', '[{"index": 1, "isUser": false, "scene": "圣伊甸贵族女子学园 · 入学校门强制更衣室 · 上午", "story": "“新生同学，欢迎来到圣伊甸。在这里，身体是唯一的诚实礼仪。”校门旁的更衣室门推开，成熟丰满、一丝不挂的女校长塞西莉亚优雅地端着茶杯注视着你。在她的注视下，你脱下了身上的最后一件衣物。当踏入恒温26℃的林荫校园，走廊与草坪上成百上千名赤身裸体的贵族少女们齐刷刷转过头来，目光聚焦在全校唯一一具男性肉体上，窃窃私语与好奇惊呼此起彼伏……", "branches": [{"tag": "A", "title": "顺应当前情境小心周旋应对", "desc": "保持镇定，仔细观察周遭人物的微表情与防备程度，稳步建立信任关系"}, {"tag": "B", "title": "出人意料反客为主试探底线", "desc": "抓住对方好奇或破防的瞬间，采取大胆主动的行动颠覆攻守局势"}, {"tag": "C", "title": "制造独处私密借口深入交流", "desc": "将关键人物引向更隐秘的角落或私密房间，拉开二人深度交互帷幕"}, {"tag": "D", "title": "直接挑明自身特殊需求与条件", "desc": "打破常规客套，直言不讳地提出极具侵略性与掌控欲的契约规则"}]}]', '/* ========== 全局 ========== */
body,
p,
span,
div,
details,
summary,
td,
th,
li,
blockquote {
    font-size: 16px !important;
    font-family: ''Microsoft YaHei'', ''PingFang SC'', sans-serif !important;
}

/* ===== 对话颜色 ===== */
.player-talk {
    color: #1a73e8 !important;
    font-weight: 500;
}
.npc-talk {
    color: #d63384 !important;
    font-weight: 500;
}

/* ===== 容器基准 ===== */
.w {
    display: block;
    font-family: system-ui, -apple-system, sans-serif;
    font-size: 14px;
    color: #4a2c40;
    line-height: 1.5;
    background: linear-gradient(135deg, #fff0f5 0%, #fef5f9 100%);
    padding: 8px;
    border-radius: 12px;
    box-shadow: 0 4px 15px rgba(255, 126, 179, 0.1);
}

/* ===== 状态面板 (a) ===== */
.w .a {
    display: block;
    background: rgba(255, 255, 255, 0.72);
    border: 1px solid rgba(255, 126, 179, 0.3);
    border-radius: 8px;
    margin-bottom: 8px;
    overflow: hidden;
    box-shadow: 0 2px 6px rgba(0, 0, 0, 0.02);
    transition: box-shadow 0.3s ease, border-color 0.3s ease;
}
.w .a[open] {
    box-shadow: 0 6px 16px rgba(255, 117, 140, 0.12);
    border-color: rgba(255, 126, 179, 0.55);
}

/* ===== 师生图鉴 (b) ===== */
.w .b {
    display: block;
    background: rgba(255, 255, 255, 0.72);
    border: 1px solid rgba(255, 126, 179, 0.3);
    border-radius: 8px;
    margin-bottom: 8px;
    overflow: hidden;
    box-shadow: 0 2px 6px rgba(0, 0, 0, 0.02);
}

/* ===== 记忆区 (star-memory) ===== */
.w .star-memory {
    display: block;
    background: rgba(255, 255, 255, 0.72);
    border: 1px solid rgba(255, 126, 179, 0.3);
    border-radius: 8px;
    margin-bottom: 8px;
    overflow: hidden;
    box-shadow: 0 2px 6px rgba(0, 0, 0, 0.02);
    transition: box-shadow 0.3s ease, border-color 0.3s ease;
}
.w .star-memory[open] {
    box-shadow: 0 6px 16px rgba(255, 117, 140, 0.12);
    border-color: rgba(255, 126, 179, 0.55);
}

/* ===== 隐藏原生三角 ===== */
.w .a summary::-webkit-details-marker,
.w .b summary::-webkit-details-marker,
.w .star-memory summary::-webkit-details-marker,
.w .m summary::-webkit-details-marker {
    display: none;
}
.w .a summary,
.w .b summary,
.w .star-memory summary,
.w .m summary {
    list-style: none;
}

/* ===== 标题通用 ===== */
.w .a summary,
.w .b summary,
.w .star-memory summary {
    cursor: pointer;
    padding: 10px 12px;
    font-weight: 600;
    user-select: none;
    display: flex;
    justify-content: space-between;
    align-items: center;
    transition: background 0.25s ease;
    background: linear-gradient(90deg, rgba(255, 126, 179, 0.13) 0%, rgba(255, 255, 255, 0) 100%);
    color: #d81b60;
    font-size: 15px;
    border-bottom: 1px solid transparent;
}
.w .a[open]>summary,
.w .b[open]>summary,
.w .star-memory[open]>summary {
    border-bottom: 1px solid rgba(255, 126, 179, 0.2);
}

/* ===== 箭头动画 ===== */
.w .a summary::after,
.w .b summary::after,
.w .star-memory summary::after {
    content: "▼";
    font-size: 11px;
    color: #ff758c;
    opacity: 0.7;
    transition: transform 0.3s ease;
    margin-left: 8px;
}
.w .a[open]>summary::after,
.w .b[open]>summary::after,
.w .star-memory[open]>summary::after {
    transform: rotate(180deg);
}

/* ===== Hover ===== */
.w .a summary:hover,
.w .b summary:hover,
.w .star-memory summary:hover {
    background: rgba(255, 126, 179, 0.18);
}

/* ===== 展开动画 ===== */
.w .a[open]>*:not(summary),
.w .b[open]>*:not(summary),
.w .star-memory[open]>*:not(summary) {
    animation: panel-fade-in 0.35s cubic-bezier(0.4, 0, 0.2, 1);
}
@keyframes panel-fade-in {
    0% {
        opacity: 0;
        transform: translateY(-4px);
    }
    100% {
        opacity: 1;
        transform: translateY(0);
    }
}

/* ===== 状态条目容器 ===== */
.w .r {
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    margin: 5px 10px;
    background: rgba(255, 255, 255, 0.85);
    border-radius: 6px;
    padding: 4px 0;
    border: 1px solid rgba(255, 126, 179, 0.12);
    transition: background 0.2s ease;
}
.w .r:hover {
    background: rgba(255, 255, 255, 0.96);
}

/* ===== 粉色标签 ===== */
.w .k {
