}
.w .mi {
    padding: 6px 10px;
    margin: 4px 6px 8px 6px;
    background: rgba(255, 255, 255, 0.5);
    border-radius: 4px;
    font-size: 13px;
    color: #553a4b;
    line-height: 1.6;
}

/* ===== 记忆区内层 details ===== */
.w .star-memory details {
    background: rgba(255, 245, 248, 0.5);
    border-radius: 6px;
