    vertical-align: top;
    border-bottom: 1px solid rgba(255, 126, 179, 0.10);
    word-wrap: break-word;
    overflow-wrap: break-word;
    line-height: 1.5;
}
.w .star-memory table th {
    background: rgba(255, 126, 179, 0.08);
    font-weight: 600;
    font-size: 12px;
    color: #b34a6a;
    letter-spacing: 0.3px;
    border-bottom: 2px solid rgba(255, 126, 179, 0.20);
}
/* ===== 列宽分配：编号窄，时间窄，场景窄，内容宽 ===== */
.w .star-memory table th:nth-child(1),
.w .star-memory table td:nth-child(1) {
