</div>
</div>
</div>
<!-- 开场白 -->
<div class="section-box">
<div class="section-title">🎬 自定义开场白</div>
<textarea id="custom_intro" class="form-input" rows="3" placeholder="请输入自定义开场白（可选）..."></textarea>
</div>
<!-- 预览 -->
<div class="section-box">
<div class="section-title">📋 信息预览</div>
<div class="preview-box" id="finalPreview">等待生成内容...</div>
<button class="copy-btn" id="copyBtn" onclick="copyConfig()">📑 复制完整系统设定</button>
</div>
</div>
</div>
</div>
<!-- 自定义NPC弹窗 -->
<div class="modal" id="npcModal">
<div class="modal-content">
<h3 style="color:var(--primary); margin-bottom:15px;">添加新NPC</h3>
<div class="form-group"><label>姓名</label><input type="text" id="new_name" class="form-input"></div>
<div class="form-group"><label>年龄</label><input type="text" id="new_age" class="form-input"></div>
<div class="form-group"><label>性格</label><input type="text" id="new_personality" class="form-input"></div>
<div class="form-group"><label>身份</label><input type="text" id="new_identity" class="form-input"></div>
<div class="form-group"><label>背景</label><textarea id="new_bg" class="form-input"></textarea></div>
<button class="action-btn" onclick="addNewNpc()">➕ 确认添加</button>
<button class="action-btn" style="background:#444; margin-top:10px;" onclick="closeModal()">取消</button>
</div>
</div>
<div class="toast" id="toast">已成功复制到剪贴板</div>
<footer><a href="https://aitrader.wiki/zh/explore/installed/813e225e-2a1a-45bd-b441-f4741dff5418" target="_blank">本页面采用AI风月-创作大师生成</a></footer>
<script>
function switchTab(tabId) {
    document.querySelectorAll(''.content-area'').forEach(el => el.classList.remove(''active''));
    document.querySelectorAll(''.tab-btn'').forEach(el => el.classList.remove(''active''));
    document.getElementById(tabId).classList.add(''active'');
    event.currentTarget.classList.add(''active'');
    window.scrollTo(0,0);
}
function toggleKink(el) { el.classList.toggle(''active''); updatePreview(); }
function selectNpc(el) { el.classList.toggle(''selected''); updatePreview(); }
function showNpcModal() { document.getElementById(''npcModal'').style.display = ''flex''; }
function closeModal() { document.getElementById(''npcModal'').style.display = ''none''; }
function addNewNpc() {
    const name = document.getElementById(''new_name'').value;
    const age = document.getElementById(''new_age'').value;
    const pers = document.getElementById(''new_personality'').value;
    const iden = document.getElementById(''new_identity'').value;
    const bg = document.getElementById(''new_bg'').value;
    if(!name) return;
    const div = document.createElement(''div'');
    div.className = ''npc-list-item selected'';
    div.onclick = function() { this.classList.toggle(''selected''); updatePreview(); };
    div.innerHTML = `<h5>👤 ${name}</h5><p>${age} | ${pers} | ${iden}</p><div style="display:none">${bg}</div>`;
    document.getElementById(''npcList'').appendChild(div);
    closeModal();
    updatePreview();
}
function updatePreview() {
    const pName = document.getElementById(''p_name'').value || ''龙傲天'';
    const pGender = document.getElementById(''p_gender'').value || ''男'';
    const pPers = document.getElementById(''p_personality'').value || ''温柔体贴'';
    const pIden = document.getElementById(''p_identity'').value || ''高中生'';
    const pOther = document.getElementById(''p_other'').value || ''无'';
    const kinks = Array.from(document.querySelectorAll(''.kink-item.active'')).map(el => el.innerText).join('', '') || ''无'';
    let npcInfo = '''';
    document.querySelectorAll(''.npc-list-item.selected'').forEach(el => {
        const h5 = el.querySelector(''h5'').innerText;
        const p = el.querySelector(''p'').innerText;
        const bg = el.querySelector(''div'').innerText;
        npcInfo += `【NPC：${h5}】\n详情：${p}\n背景：${bg}\n\n`;
    });
    const intro = document.getElementById(''custom_intro'').value || ''默认开场'';
    const fullText = `【玩家信息】\n姓名：${pName}\n性别：${pGender}\n性格：${pPers}\n身份：${pIden}\n核心性癖：${kinks}\n其他：${pOther}\n\n【NPC信息】\n${npcInfo}【剧情开场】\n${intro}\n\n(请按照Aphrodite👦管理员模拟系统规则开始游戏)`;
    document.getElementById(''finalPreview'').innerText = fullText;
}
function quickCopy(name, traits) {
    const admin = document.getElementById(''shop_admin_name'').value || ''新任管理员'';
    const iden = document.getElementById(''shop_admin_identity'').value || ''管理员'';
    const text = `【管理员查房确认】\n\n👤 管理员设定：\n姓名：${admin}\n身份：${iden}\n\n📦 目标住户：\n姓名：${name}\n核心属性：${traits}\n\n(【👦】请按照月桂庄公寓规则开始剧情)`;
    const el = document.createElement(''textarea'');
    el.value = text;
    document.body.appendChild(el);
    el.select();
    document.execCommand(''copy'');
    document.body.removeChild(el);
    showToast();
}
function copyConfig() {
    updatePreview();
    const text = document.getElementById(''finalPreview'').innerText;
    const el = document.createElement(''textarea'');
    el.value = text;
    document.body.appendChild(el);
    el.select();
    document.execCommand(''copy'');
    document.body.removeChild(el);
    showToast();
}
function showToast() {
    const t = document.getElementById(''toast'');
    t.style.display = ''block'';
    setTimeout(() => t.style.display = ''none'', 2000);
}
document.querySelectorAll(''input, textarea'').forEach(el => el.addEventListener(''input'', updatePreview));
updatePreview();
</script>
</body>
</html>', '都市', '2026-09-15 15:03:14', '2026-09-15 15:03:14', '', '', '[]', '') ON CONFLICT (id) DO NOTHING;
INSERT INTO stories (id, title, badge, cover_icon, cover_title, cover_subtitle, logo, theme_color, btn_gradient, handbook_json, roles_json, scenes_json, styles_json, first_turn_demo_json, custom_css, custom_html, category, created_at, updated_at, system_prompt, status_template, lorebook_json, post_history_instructions) VALUES ('60575ef0-3b20-4843-a0a8-5b3e60de9cc7', '绿帽好哥们的极品骚妈淫姐求肏内射', '都市 · 熟女人妻', '👠', '绿帽好哥们的极品骚妈淫姐求肏内射', '都市 · 熟女人妻', '👠', '#f43f5e', 'linear-gradient(135deg, #f43f5e 0%, #fb7185 100%)', '{"title": "绿帽好哥们的极品骚妈淫姐求肏内射", "desc": "绿帽好哥们的极品骚妈淫姐求肏内射", "bg_image": "https://catai.wiki/387eae64-7f67-462e-08de-c1d7a974d500/cover", "opening_options": ["【透明吊带·开门迎客】：“林铭宇用钥匙刚打开门，陈梦瑶穿着几近透明的黑色蕾丝吊带裙迎了出来，I罩杯豪乳微晃：‘是小宇的朋友吧？快进来……’”", "【宽松衬衫·长腿俯视】：“你刚在沙发坐下，顶级模特姐姐陈雨欣穿着宽大男士衬衫下楼，露出修长玉腿与深邃乳沟，居高临下玩味打量你……”", "【饭后蜜桃·沙发贴身】：“饭后林铭宇躲进屋，陈梦瑶端着水果坐到你身边，熟透的蜜桃臀贴着你，叉起苹果递到你嘴边：‘小宇不懂事，还是你懂事……’”", "【深夜走廊·对镜涂乳】：“深夜去洗手间，陈雨欣房门虚掩，正穿着丁字裤对着镜子给饱满双乳涂润肤乳，镜中视线与你交汇却并未遮掩……”", "【凌晨求援·好哥们崩溃】：“凌晨一点林铭宇敲响你家门崩溃祈求：‘兄弟……我妈和我姐又……我没办法了，求你今晚去我家收了她们吧！’”"]}', '[{"name": "陈梦瑶", "role": "哥们母亲 (38岁 / I罩杯豪乳 / 熟女人妻)", "desc": "林铭宇的母亲。丈夫早逝，身材丰腴诱人，常年深居闺阁欲望无处宣泄，外表温柔贤惠，内心充满渴望被征服的极度饥渴。"}, {"name": "陈雨欣", "role": "哥们姐姐 (24岁 / E罩杯 / 顶级超模 / 高冷白虎)", "desc": "T台上最耀眼的顶级名模，一双笔直大长腿与天生白虎名器。面对外人高冷凌厉，私下却穿着诱人睡衣发起极具侵略性的主动攻势。"}, {"name": "林铭宇", "role": "好哥们 (崩溃求援)", "desc": "你的大学同窗好友。因无法承受母亲与姐姐越来越过火的诱惑而彻底崩溃，痛哭跪求你接纳这两个女人。"}, {"name": "主角 (玩家)", "role": "新任男主人", "desc": "被好哥们托付的救世主，成为这个香艳不设防豪宅真正的主宰。"}]', '[{"title": "林家豪宅 · 香气弥漫的玄关与客厅", "desc": "豪华私密复式公寓，门扉虚掩，空气中弥漫着高级熟女体香与沐浴乳芳香。"}, {"title": "二楼走廊 · 虚掩的陈雨欣闺房", "desc": "暖黄色微光斜照的镜前，超模姐姐正对着穿衣镜涂抹润肤乳。"}]', '{"dialogue_style": "沉浸式细腻小说叙事，富有张力的肉体与情感博弈", "format": "AI风月标准双栏规范及.custom-ui样式"}', '{"index": 1, "isUser": false, "scene": "林家豪宅 · 香气弥漫的玄关与客厅", "story": "<tl>📅时间：周末黄昏 18:30 | 🌏地点：林铭宇家中客厅 | 🍷氛围：香艳诱惑</tl>\n\n<article>\n<p>林铭宇掏出钥匙的手都在微微颤抖。防盗门锁咔嗒一声轻响，门才推开一条缝，一股浓郁的熟女体香混杂着高级兰花沐浴露的气息便扑面而来。</p>\n\n<p>玄关深处的木质地板上，一对踩着毛绒拖鞋的雪白玉足款款迈出。陈梦瑶穿着一件薄如蝉翼的黑色蕾丝吊带睡裙迎了出来——那对足以让任何年轻女孩自惭形秽的I罩杯硕大豪乳随着步伐剧烈晃荡，深色的乳晕与挺立的乳头在轻纱下若隐若现。</p>\n\n<p><w>“哎呀，是小宇的朋友来了呀？”</w>陈梦瑶眼波流转，成熟美艳的脸庞泛着动人的水润光泽。她温柔地笑着迎上前，丰满绵软的胸脯几乎直接蹭到了你的手臂，<w>“快进来坐，外边风大。阿姨刚刚洗完澡，家里没外人，别拘束呀……”</w></p>\n\n<p>林铭宇面无血色地低下头，死死咬着牙，用几乎只有你能听见的声音发颤道：<w>“兄弟……救我……”</w></p>\n</article>", "branches": [{"tag": "A", "title": "强势主动", "desc": "把握主导权，将局势引向最深层的欲望试探"}, {"tag": "B", "title": "细致观察", "desc": "审视对方微小的呼吸与神态变化，步步为营"}, {"tag": "C", "title": "言语挑逗", "desc": "用暧昧低沉的耳语彻底击溃对方的心防防线"}]}', '', '<!DOCTYPE html>
<html lang="zh-CN">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no">
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2%sfamily=Noto+Serif+SC:wght@400;500;700&family=ZCOOL+XiaoWei&display=swap" rel="stylesheet">
<style>
*{margin:0;padding:0;box-sizing:border-box;-webkit-tap-highlight-color:transparent}

:root{
  --bg1:#fdf2f8;
  --bg2:#f5f0ff;
  --bg3:#edf2ff;
  --bg4:#fff6fb;
  --card:rgba(255,255,255,.85);
  --card-solid:#ffffff;
  --border:rgba(167,139,250,.24);
  --border-strong:rgba(167,139,250,.45);
  --primary:#a78bfa;
  --primary-deep:#7c5cd6;
  --primary-soft:#ede9fe;
  --accent:#f472b6;
  --accent-soft:#fce7f3;
  --gold:#c9a35c;
  --text:#4a3d63;
  --text-dim:#78688f;
  --text-mute:#aa9fc6;
  --shadow:0 10px 30px rgba(138,110,200,.13);
  --shadow-lg:0 18px 46px rgba(138,110,200,.22);
  --radius:20px;
  --font:''Noto Serif SC'',''Songti SC'',serif;
  --font-title:''ZCOOL XiaoWei'',''Noto Serif SC'',serif;
}

body{
  font-family:var(--font);
  background:linear-gradient(135deg,var(--bg1),var(--bg2),var(--bg3),var(--bg4));
  background-size:400% 400%;
  animation:bgFlow 18s ease-in-out infinite;
  color:var(--text);
  min-height:100vh;
  padding:20px 16px 60px;
  line-height:1.8;
}

@keyframes bgFlow{
  0%,100%{background-position:0% 50%}
  50%{background-position:100% 50%}
}

@keyframes fadeUp{
  from{opacity:0;transform:translateY(18px)}
  to{opacity:1;transform:translateY(0)}
}

@keyframes fadeIn{
  from{opacity:0}
  to{opacity:1}
}

.container{
  max-width:1000px;
  margin:0 auto;
}

/* ===== 顶部标题 ===== */
.hero{
  text-align:center;
  padding:30px 10px 25px;
  position:relative;
}

.hero-title{
  font-family:var(--font-title);
  font-size:clamp(2rem, 6vw, 3rem);
  font-weight:700;
  background:linear-gradient(135deg,#a78bfa 0%,#f472b6 50%,#7c5cd6 100%);
  -webkit-background-clip:text;
  -webkit-text-fill-color:transparent;
  letter-spacing:4px;
  text-shadow:0 0 40px rgba(167,139,250,.15);
}

.hero-sub{
  margin-top:10px;
  font-size:clamp(.8rem, 2.8vw, .95rem);
  color:var(--text-dim);
  letter-spacing:2px;
  opacity:.85;
  font-style:italic;
}

.hero-divider{
  width:80px;
  height:3px;
  margin:18px auto 0;
  border-radius:4px;
  background:linear-gradient(90deg,transparent,var(--primary),#f472b6,transparent);
  position:relative;
}

.hero-divider::after{
  content:"✦";
  position:absolute;
  top:50%;
  left:50%;
  transform:translate(-50%,-50%);
  background:var(--card-solid);
  color:var(--gold);
  font-size:14px;
  padding:0 10px;
  border-radius:4px;
}

/* ===== 卡片通用 ===== */
.card{
  background:var(--card);
  backdrop-filter:blur(14px);
  -webkit-backdrop-filter:blur(14px);
  border:1px solid var(--border);
  border-radius:var(--radius);
  padding:24px;
  box-shadow:var(--shadow);
  margin-bottom:18px;
  animation:fadeUp .7s cubic-bezier(.22,1,.36,1) both;
}

.card-title{
  display:flex;
  align-items:center;
  justify-content:space-between;
  margin-bottom:16px;
  padding-bottom:12px;
  border-bottom:1px dashed var(--border);
  font-family:var(--font-title);
  font-size:1.15rem;
  letter-spacing:1px;
  color:var(--primary-deep);
  cursor:default;
}

.card-title::before{
  content:"◆";
  margin-right:10px;
  color:var(--accent);
  font-size:.8em;
  transform:translateY(-2px);
}

.card-title .fold-btn{
  font-size:.75rem;
  color:var(--text-mute);
  font-family:var(--font);
  letter-spacing:1px;
  cursor:pointer;
  background:var(--primary-soft);
  border:1px solid var(--border);
  border-radius:20px;
  padding:3px 14px;
  transition:all .3s;
}

.card-title .fold-btn:hover{
  background:var(--primary);
  color:#fff;
  border-color:var(--primary);
}

/* ===== 折叠区 ===== */
.collapse-area{
  width:100%;
  border:0;
  background:transparent;
  overflow:hidden;
  transition:max-height .5s cubic-bezier(.4,0,.2,1);
  max-height:20000px;
}

.collapse-area.closed{
  max-height:0 !important;
}

/* ===== 玩家设定 ===== */
.player-wrap{
  position:relative;
}

.player-grid{
  display:grid;
  grid-template-columns:repeat(auto-fit,minmax(240px,1fr));
  gap:14px;
}

.player-item{
  background:rgba(255,255,255,.55);
  border:1px solid var(--border);
  border-radius:14px;
  padding:14px 16px;
  transition:all .3s ease;
  position:relative;
  overflow:hidden;
}

.player-item:focus-within{
  background:var(--card-solid);
  border-color:var(--primary);
  box-shadow:0 0 0 3px rgba(167,139,250,.12);
}

.player-item.full{
  grid-column:1/-1;
}

.player-item .label{
  font-size:.8rem;
  color:var(--text-mute);
  letter-spacing:1px;
  margin-bottom:6px;
  font-weight:500;
}

.player-item input,.player-item textarea{
  width:100%;
  border:none;
  outline:none;
  background:transparent;
  font-family:var(--font);
  font-size:.95rem;
  color:var(--text);
  resize:vertical;
  padding:4px 0;
  line-height:1.6;
  min-height:24px;
}

.player-item textarea{
  min-height:60px;
}

.player-item input::placeholder,.player-item textarea::placeholder{
  color:var(--text-mute);
  font-style:italic;
}

/* ===== 额外设定 ===== */
.extra-toggle{
  display:flex;
  align-items:center;
  justify-content:center;
  gap:8px;
  width:100%;
  padding:10px 0;
  background:transparent;
  border:1px dashed var(--border-strong);
  border-radius:12px;
  font-size:.85rem;
  color:var(--text-dim);
  cursor:pointer;
  transition:all .3s;
  margin-top:12px;
  font-family:var(--font);
  letter-spacing:1px;
}

.extra-toggle:hover{
  background:var(--primary-soft);
  color:var(--primary-deep);
}

.extra-area{
  margin-top:14px;
  border-top:1px dashed var(--border);
  padding-top:14px;
}

/* ===== 开场白列表 ===== */
.starter-wrap{
  position:relative;
}

.starter-note{
  font-size:.83rem;
  color:var(--text-mute);
  text-align:right;
  margin-bottom:12px;
  font-style:italic;
  letter-spacing:.5px;
}

.starter-list{
  display:flex;
  flex-direction:column;
  gap:10px;
}

.starter-item{
  background:rgba(255,255,255,.5);
  border:1px solid var(--border);
  border-radius:14px;
  padding:12px 16px;
  font-size:.92rem;
  color:var(--text);
  line-height:1.75;
  cursor:pointer;
  transition:all .25s ease;
  position:relative;
  padding-left:44px;
  letter-spacing:.3px;
  word-break:break-word;
}

.starter-item::before{
  content:"○";
  position:absolute;
  left:16px;
  top:50%;
  transform:translateY(-50%);
  font-size:1rem;
  color:var(--text-mute);
  transition:all .3s;
}

.starter-item:hover{
  border-color:var(--primary);
  background:var(--primary-soft);
  transform:translateX(4px);
  box-shadow:0 4px 12px rgba(167,139,250,.12);
}

.starter-item:hover::before{
  content:"●";
  color:var(--primary-deep);
}

.starter-item.selected{
  background:linear-gradient(135deg,var(--primary-soft),var(--accent-soft));
  border-color:var(--primary);
  box-shadow:0 4px 14px rgba(167,139,250,.2);
}

.starter-item.selected::before{
  content:"●";
  color:var(--accent);
}

.starter-custom{
  margin-top:14px;
  padding:12px 16px;
}

/* ===== 生成按钮 ===== */
.generate-area{
  text-align:center;
  margin:26px 0 20px;
  position:relative;
  z-index:2;
}

.generate-btn{
  display:inline-flex;
  align-items:center;
  justify-content:center;
  gap:12px;
  padding:16px 50px;
  font-family:var(--font-title);
  font-size:1.25rem;
  letter-spacing:4px;
  color:#fff;
  background:linear-gradient(135deg,#a78bfa 0%,#7c5cd6 50%,#f472b6 100%);
  border:none;
  border-radius:50px;
  cursor:pointer;
  box-shadow:0 10px 30px rgba(124,92,214,.45),0 4px 12px rgba(244,114,182,.25);
  transition:all .3s ease;
  position:relative;
  overflow:hidden;
}

.generate-btn::before{
  content:"";
  position:absolute;
  top:0;
  left:-100%;
  width:100%;
  height:100%;
  background:linear-gradient(90deg,transparent,rgba(255,255,255,.25),transparent);
  transition:left .5s ease;
}

.generate-btn:hover::before{
  left:100%;
}

.generate-btn:hover{
  transform:translateY(-3px) scale(1.02);
  box-shadow:0 14px 36px rgba(124,92,214,.55),0 6px 18px rgba(244,114,182,.35);
}

.generate-btn:active{
  transform:translateY(0) scale(.98);
  box-shadow:0 6px 18px rgba(124,92,214,.4);
}

.generate-btn .star{
  font-size:1.1rem;
  animation:twinkle 1.5s ease-in-out infinite;
}

@keyframes twinkle{
  0%,100%{opacity:1;transform:scale(1)}
  50%{opacity:.6;transform:scale(.9)}
}

/* ===== 总结区 ===== */
.summary-area{
  margin-top:8px;
  position:relative;
}

.summary-title{
  text-align:center;
  font-family:var(--font-title);
  font-size:1.3rem;
  letter-spacing:3px;
  color:var(--primary-deep);
  margin-bottom:16px;
  display:flex;
  align-items:center;
  justify-content:center;
  gap:16px;
}

.summary-title::before,.summary-title::after{
  content:"";
  flex:1;
  max-width:80px;
  height:2px;
  background:linear-gradient(90deg,transparent,var(--primary));
  border-radius:4px;
}

.summary-title::after{
  background:linear-gradient(90deg,var(--primary),transparent);
}

.summary-card{
  background:linear-gradient(145deg,rgba(255,255,255,.9),rgba(250,244,255,.85));
  border:1px solid var(--border-strong);
  border-radius:var(--radius);
  padding:22px;
  box-shadow:var(--shadow-lg);
  position:relative;
  animation:fadeUp .7s .3s cubic-bezier(.22,1,.36,1) both;
}

.summary-content{
  font-size:.95rem;
  line-height:2;
  white-space:pre-wrap;
  word-break:break-word;
  color:var(--text);
  text-align:left;
  padding:0 4px;
}

.summary-content .divider{
  text-align:center;
  color:var(--accent);
  letter-spacing:4px;
  margin:8px 0;
  font-size:.9rem;
  opacity:.75;
}

.copy-area{
  text-align:center;
  margin-top:18px;
  padding-top:16px;
  border-top:1px dashed var(--border);
}

.copy-btn{
  display:inline-flex;
  align-items:center;
  justify-content:center;
  gap:8px;
  padding:11px 40px;
  font-size:.92rem;
  letter-spacing:2px;
  color:var(--primary-deep);
  background:var(--primary-soft);
  border:1.5px solid var(--primary);
  border-radius:30px;
  cursor:pointer;
  transition:all .3s ease;
  font-family:var(--font);
  font-weight:500;
}

.copy-btn:hover{
  background:var(--primary);
  color:#fff;
  box-shadow:0 6px 18px rgba(167,139,250,.35);
  transform:translateY(-2px);
}

.copy-btn:active{
  transform:translateY(0) scale(.98);
}

.copy-btn.copied{
  background:linear-gradient(135deg,#34d399,#10b981);
  border-color:#34d399;
  color:#fff;
}

.copy-btn svg{
  width:15px;
  height:15px;
  transition:all .3s;
}

/* ===== 背景故事 ===== */
.story-body{
  font-size:.95rem;
  line-height:2.2;
  color:var(--text);
  white-space:pre-wrap;
  word-break:break-word;
}

.story-body .section-head{
  font-family:var(--font-title);
  font-size:1.05rem;
  color:var(--primary-deep);
  margin:20px 0 10px;
  display:flex;
  align-items:center;
  gap:10px;
  font-weight:700;
}

.story-body .section-head:first-child{
  margin-top:4px;
}

.story-body .section-head::before{
  content:"❖";
  color:var(--accent);
  font-size:.9em;
}

.story-body .highlight{
  background:linear-gradient(transparent 60%,rgba(252,231,243,.6) 60%);
  padding:0 2px;
  border-radius:2px;
}

.story-body .quote{
  border-left:3px solid var(--primary);
  padding-left:14px;
  margin:10px 0;
  color:var(--text-dim);
  font-style:italic;
  background:rgba(237,233,254,.25);
  border-radius:0 8px 8px 0;
}

/* ===== 人物介绍 ===== */
.character-block{
  margin-bottom:18px;
  background:rgba(255,255,255,.4);
  border-radius:16px;
  overflow:hidden;
  border:1px solid var(--border);
}

.character-block:last-child{
  margin-bottom:0;
}

.char-header{
  display:flex;
  align-items:center;
  gap:12px;
  padding:16px 18px;
  background:linear-gradient(135deg,rgba(237,233,254,.6),rgba(252,231,243,.4));
  cursor:pointer;
  transition:all .3s;
  position:relative;
}

.char-header:hover{
  background:linear-gradient(135deg,rgba(237,233,254,.9),rgba(252,231,243,.6));
}

.char-avatar{
  width:52px;
  height:52px;
  border-radius:50%;
  border:2px solid var(--primary);
  display:flex;
  align-items:center;
  justify-content:center;
  font-family:var(--font-title);
  font-size:1.5rem;
  color:var(--primary-deep);
  background:rgba(255,255,255,.8);
  box-shadow:0 4px 12px rgba(167,139,250,.25);
  flex-shrink:0;
}

.char-name{
  flex:1;
  font-family:var(--font-title);
  font-size:1.1rem;
  letter-spacing:2px;
  color:var(--primary-deep);
}

.char-role-tag{
  font-size:.75rem;
  color:var(--accent);
  background:var(--accent-soft);
  padding:2px 12px;
  border-radius:20px;
  border:1px solid rgba(244,114,182,.25);
  letter-spacing:1px;
  white-space:nowrap;
}

.char-arrow{
  color:var(--text-mute);
  font-size:.9rem;
  transition:all .4s;
  transform:rotate(90deg);
}

.char-block.closed .char-arrow{
  transform:rotate(0deg);
}

.char-body{
  max-height:0;
  overflow:hidden;
  transition:max-height .5s cubic-bezier(.4,0,.2,1);
}

.char-block:not(.closed) .char-body{
  max-height:20000px;
}

.char-detail{
  padding:18px;
  font-size:.92rem;
  line-height:2;
  border-top:1px solid var(--border);
}

.char-detail .attr-label{
  display:inline-block;
  min-width:70px;
  color:var(--text-mute);
  font-size:.83rem;
  letter-spacing:1px;
  font-weight:500;
}

.char-detail .attr-content{
  margin:2px 0 8px;
  padding-left:70px;
}

.char-detail .attr-content .highlight{
  background:linear-gradient(transparent 60%,rgba(252,231,243,.6) 60%);
}

/* ===== 玩法区 ===== */
.mech-grid{
  display:grid;
  grid-template-columns:repeat(auto-fit,minmax(280px,1fr));
  gap:14px;
}

.mech-item{
  background:rgba(255,255,255,.5);
  border:1px solid var(--border);
  border-radius:14px;
  padding:16px;
  text-align:center;
  transition:all .3s;
}

.mech-item:hover{
  border-color:var(--primary);
  background:var(--primary-soft);
  transform:translateY(-3px);
}

.mech-icon{
  font-size:2rem;
  margin-bottom:8px;
  display:block;
}

.mech-name{
  font-weight:700;
  font-size:.95rem;
  color:var(--text);
  margin-bottom:6px;
  letter-spacing:1px;
}

.mech-desc{
  font-size:.83rem;
  color:var(--text-dim);
  line-height:1.8;
}

/* ===== 响应式 ===== */
@media (max-width:600px){
  :root{
    --radius:16px;
  }
  body{
    padding:12px 12px 50px;
  }
  .card{
    padding:18px;
  }
  .player-item{
    padding:12px 14px;
  }
  .player-grid{
    grid-template-columns:1fr;
    gap:10px;
  }
  .starter-item{
    font-size:.88rem;
    padding:10px 14px 10px 40px;
  }
  .generate-btn{
    width:100%;
    max-width:320px;
    padding:14px 24px;
    font-size:1.05rem;
  }
  .summary-card{
    padding:16px;
  }
  .char-detail .attr-content{
    padding-left:60px;
  }
  .char-role-tag{
    font-size:.68rem;
    padding:1px 8px;
  }
  .char-header{
    flex-wrap:wrap;
  }
}

/* ===== 滚动条 ===== */
::-webkit-scrollbar{
  width:5px;
  height:5px;
}
::-webkit-scrollbar-track{
  background:transparent;
}
::-webkit-scrollbar-thumb{
  background:var(--primary);
  border-radius:10px;
  opacity:.5;
}
::-webkit-scrollbar-thumb:hover{
  background:var(--primary-deep);
}

/* ===== 空状态 ===== */
.empty-state{
  text-align:center;
  padding:30px;
  color:var(--text-mute);
  font-size:.9rem;
  letter-spacing:1px;
}

.empty-state::before{
  content:"(๑•́ ₃ •̀๑)";
  display:block;
  font-size:1.4rem;
  margin-bottom:10px;
  animation:float 2s ease-in-out infinite;
}

@keyframes float{
  0%,100%{transform:translateY(0)}
  50%{transform:translateY(-6px)}
}
</style>
</head>
<body>

<div class="container">

  <!-- ========== 标题 ========== -->
  <div class="hero">
    <div class="hero-title">骚妈淫姐</div>
    <div class="hero-sub">— 母姐丼 · 肉欲燃烧的禁忌之家 —</div>
    <div class="hero-divider"></div>
  </div>

  <!-- ========== 背景故事 ========== -->
  <div class="card" id="card-story">
    <div class="card-title">
      <span>背景故事</span>
      <span class="fold-btn" data-target="story-body">收起</span>
    </div>
    <div class="collapse-area" id="story-collapse">
      <div class="story-body" id="story-body">
      ❖ 我好兄弟林铭宇，跪在了我面前。</br>
      他的眼眶红得发黑，像是几夜没睡，声音抖得几乎连不成句子：「哥们……我求你……我真的受不了了……她们……你帮帮我……求你了……」</br></br>
      他说的「她们」，是他亲妈陈梦瑶，和他亲姐陈雨欣。</br></br>
      陈梦瑶——38岁，守寡多年。岁月几乎没有在她脸上留下痕迹，反而赐予了她一份少女绝无的熟魅风情。那对I罩杯的硕大豪乳沉甸甸地坠着，哪怕穿着最宽松的衣服，也压不住那两团饱满的重量。浓密阴毛下的骚穴是深粉色，丰沛的汁水似乎从未干涸。她每晚都幻想着亲生儿子的大鸡巴，在自慰中泄身到崩溃。</br></br>
      陈雨欣——24岁，顶级模特。天生尤物，白虎名器。那双逆天的大长腿和E罩杯的饱满乳房，足以登上任何时尚杂志封面。可谁又能想到，T台上高冷的女王，回到家后却对着弟弟的房间门缝自慰。她比母亲更大胆、更主动、更贪婪。</br></br>
      这个家，没有锁门的概念，没有穿衣的规矩。两个女人用尽手段诱惑着林铭宇，却只换来他一次比一次更深的恐惧。</br></br>
      兄弟崩溃了。他不敢触碰亲妈，更不敢碰亲姐。</br>
      他红着眼睛，紧紧握住我的手：「她们是我的亲人……我没办法……但你不一样……哥，你帮她们……帮我……给她们……好不好？」</br></br>
      这个家，正在等待一个男人。</br>
      而敲响门的我，就是那个男人。
      </div>
    </div>
  </div>

  <!-- ========== 人物介绍 ========== -->
  <div class="card" id="card-chars">
    <div class="card-title">
      <span>详细人物介绍</span>
      <span class="fold-btn" data-target="chars-body">收起</span>
    </div>
    <div class="collapse-area" id="chars-collapse">
      <div id="chars-body">

      <!-- 人物：陈梦瑶 -->
      <div class="character-block char-block" id="block-mom">
        <div class="char-header" onclick="toggleChar(''block-mom'')">
          <div class="char-avatar">梦</div>
          <div class="char-name">陈梦瑶</div>
          <div class="char-role-tag">哥哥的母亲</div>
          <div class="char-arrow">▼</div>
        </div>
        <div class="char-body">
          <div class="char-detail">
            <div>
              <span class="attr-label">年龄</span>
              <div class="attr-content">38岁 · 冻龄寡妇</div>
            </div>
            <div>
              <span class="attr-label">外貌</span>
              <div class="attr-content">及腰乌黑直发，皮肤白嫩得几乎透明。I罩杯豪乳微微下垂却极度饱满硕大，深色乳晕，奶牛般的乳尖。腰肢纤细却配上一对丰腴肥硕的磨盘大臀，大腿圆润。</div>
            </div>
            <div>
              <span class="attr-label">下体</span>
              <div class="attr-content">阴阜饱满肥美，<span class="highlight">阴毛浓密呈倒三角</span>，一直蔓延到会阴。大阴唇肥厚，骚穴因常年自慰呈深粉色，汁水极为丰沛。</div>
            </div>
            <div>
              <span class="attr-label">性格</span>
              <div class="attr-content">表面温柔和善，标准好太太。内在是极度饥渴的熟女，对年轻的强壮男性几乎毫无抵抗力。对待禁忌关系，她有种自欺欺人的「懂事」，既疯狂又克制，既温柔又危险。</div>
            </div>
            <div>
              <span class="attr-label">语言风格</span>
              <div class="attr-content">柔软、黏腻，带着母性的长音和刻意的慵懒。「小宇的朋友……长得可真精神。来来来，快进来……把这里当自己家就好。」</div>
            </div>
          </div>
        </div>
      </div>

      <!-- 人物：陈雨欣 -->
      <div class="character-block char-block" id="block-sis">
        <div class="char-header" onclick="toggleChar(''block-sis'')">
          <div class="char-avatar">欣</div>
          <div class="char-name">陈雨欣</div>
          <div class="char-role-tag">哥哥的姐姐</div>
          <div class="char-arrow">▼</div>
        </div>
        <div class="char-body">
          <div class="char-detail">
            <div>
              <span class="attr-label">年龄</span>
              <div class="attr-content">24岁 · 顶级模特</div>
            </div>
            <div>
              <span class="attr-label">外貌</span>
              <div class="attr-content">175cm，E罩杯饱满乳房，粉色乳晕。腰肢盈盈一握，臀线极高且圆翘。一双逆天长腿，脚下臻品玉足。全身体毛极为稀疏，私处是<span class="highlight">天生的白虎</span>，光滑粉嫩，阴唇紧闭如处子。</div>
            </div>
            <div>
              <span class="attr-label">下体</span>
              <div class="attr-content">天生无毛的白虎名器，阴阜嫩白，大阴唇粉嫩小巧，往里夹裹着一线绯红色的肉缝。骚穴内里却极其多汁紧致，几乎痉挛般吸嘬着一切插入其中的异物。</div>
            </div>
            <div>
              <span class="attr-label">性格</span>
              <div class="attr-content">外表高冷自我，T台上是骄傲的女王。在家里却是个性欲极其旺盛的骚货，比母亲更大胆直接。她对自己天然的身体优势极度自信，喜欢争夺、占有、挑衅。</div>
            </div>
            <div>
              <span class="attr-label">语言风格</span>
              <div class="attr-content">直接、大胆、带刺。「你就是我弟的哥们？长得还行，起码比他有种。」「看什么看？想看就看，别偷偷摸摸的。」</div>
            </div>
          </div>
        </div>
      </div>

      </div>
    </div>
  </div>

  <!-- ========== 玩法 ========== -->
  <div class="card" id="card-mech">
    <div class="card-title">
      <span>玩法介绍</span>
      <span class="fold-btn" data-target="mech-body">收起</span>
    </div>
    <div class="collapse-area" id="mech-collapse">
      <div id="mech-body">
        <div class="mech-grid">
          <div class="mech-item">
            <span class="mech-icon">💗</span>
            <div class="mech-name">攻略系统</div>
            <div class="mech-desc">通过与两位成熟美人互动提升「攻略值」。数值高低影响她们对你的态度——从最初的试探挑逗，到主动脱衣、主动求欢，再到最后的共侍一夫。整个过程细腻而真实。</div>
          </div>
          <div class="mech-item">
            <span class="mech-icon">⚡</span>
            <div class="mech-name">竞争机制</div>
            <div class="mech-desc">母亲和姐姐是双线目标。她们之间既有母女的情谊，更有激烈的「雌竞」意识。你更偏向谁，谁就会获得更多主动权，另一个人则可能会主动做出更大胆的求欢行为来引你回头。</div>
          </div>
          <div class="mech-item">
            <span class="mech-icon">🔥</span>
            <div class="mech-name">背德体验</div>
            <div class="mech-desc">整个故事充满乱伦禁忌、背德感与罪恶快感。林铭宇是连接一切的纽带，你必须面对他对你信任和祈求。当他亲眼看着母亲和姐姐在你身下婉转承欢时，那份扭曲的情感足以让灵魂燃烧。</div>
          </div>
          <div class="mech-item">
            <span class="mech-icon">🖤</span>
            <div class="mech-name">自由选择</div>
            <div class="mech-desc">你可以选择温柔地调教这对极品母女，也可以粗暴地征服她们。选择权完全在你手中。或许这也将影响这个畸形家庭的最终结局，由你来书写。</div>
          </div>
          <div class="mech-item">
            <span class="mech-icon">🎬</span>
            <div class="mech-name">具象演出</div>
            <div class="mech-desc">对话描写细腻写实，充满感官刺激与心理刻画。每一帧画面、每一声喘息、每一滴淫液，都让你身临其境，仿佛你正站在陈梦瑶和陈雨欣两人敞开的房门之前。</div>
          </div>
          <div class="mech-item">
            <span class="mech-icon">✨</span>
            <div class="mech-name">不设限体验</div>
            <div class="mech-desc">没有多余的限制，玩家的意志决定故事的走向。你的身份设定自由填写，可以全情代入这个荒淫的家中。</div>
          </div>
        </div>
      </div>
    </div>
  </div>

  <!-- ========== 玩家设定 ========== -->
  <div class="card player-wrap" id="card-player">
    <div class="card-title">
      <span>玩家设定</span>
      <span class="fold-btn" data-target="player-body">收起</span>
    </div>
    <div class="collapse-area" id="player-collapse">
      <div id="player-body">
        <div class="player-grid">
          <div class="player-item">
            <div class="label">玩家姓名</div>
            <input type="text" id="p-name" placeholder="请输入你的名字...">
          </div>
          <div class="player-item">
            <div class="label">年龄</div>
            <input type="number" id="p-age" placeholder="例如 25">
          </div>
          <div class="player-item">
            <div class="label">外貌特征</div>
            <input type="text" id="p-look" placeholder="身高 / 体格 / 气质...">
          </div>
          <div class="player-item">
            <div class="label">肉棒设定</div>
            <input type="text" id="p-dick" placeholder="长度 / 粗细 / 形状...">
          </div>
          <div class="player-item full">
            <div class="label">额外设定（可选）</div>
            <textarea id="p-extra" placeholder="补充你的角色背景 / 特殊设定 / 癖好...（留空则视为无额外设定）"></textarea>
          </div>
        </div>
      </div>
    </div>
  </div>

  <!-- ========== 开场白 ========== -->
  <div class="card starter-wrap" id="card-starter">
    <div class="card-title">
      <span>开场白选择</span>
      <span class="fold-btn" data-target="starter-body">收起</span>
    </div>
    <div class="collapse-area" id="starter-collapse">
      <div id="starter-body">
        <div class="starter-note">✦ 点击选择开场白，或自定义填写你自己的开场白 ✦</div>
        <div class="starter-list" id="starter-list">

          <div class="starter-item" data-text="林铭宇用钥匙刚打开门，一股浓郁的熟女体香混杂着淡淡的沐浴露味道扑面而来。陈梦瑶穿着一件几近透明的黑色蕾丝吊带裙迎了出来，I罩杯的豪乳随着她的步伐剧烈晃荡，深色的乳晕和凸起的乳头在薄纱下清晰可见。她温柔地笑着：「是小宇的朋友吧？快进来，别在门口站着，把这儿当自己家。」" onclick="selectStarter(this)">林铭宇用钥匙刚打开门，一股浓郁的熟女体香混杂着淡淡的沐浴露味道扑面而来。陈梦瑶穿着一件几近透明的黑色蕾丝吊带裙迎了出来，I罩杯的豪乳随着她的步伐剧烈晃荡，深色的乳晕和凸起的乳头在薄纱下清晰可见。她温柔地笑着：「是小宇的朋友吧？快进来，别在门口站着，把这儿当自己家。」</div>

          <div class="starter-item" data-text="你刚在沙发上坐下，陈雨欣从二楼走了下来。她穿着一件白色宽松男士衬衫，衬衫下摆堪堪遮住大腿根部，一双修长笔直的白腿完全暴露。衬衫扣子只系了中间两颗，E罩杯的饱满乳房和深邃乳沟一览无余。她走到你面前，居高临下地打量你，嘴角勾起一抹玩味的笑：「你就是铭宇说的那个家伙？身体不错嘛。」" onclick="selectStarter(this)">你刚在沙发上坐下，陈雨欣从二楼走了下来。她穿着一件白色宽松男士衬衫，衬衫下摆堪堪遮住大腿根部，一双修长笔直的白腿完全暴露。衬衫扣子只系了中间两颗，E罩杯的饱满乳房和深邃乳沟一览无余。她走到你面前，居高临下地打量你，嘴角勾起一抹玩味的笑：「你就是铭宇说的那个家伙？身体不错嘛。」</div>

          <div class="starter-item" data-text="晚饭后，林铭宇借口说有事匆匆溜回了房间，客厅里只剩下你和陈梦瑶。她端着一盘水果坐到你身边，大腿几乎贴着你的大腿，熟透的蜜桃臀毫不避讳地压在沙发垫上。她叉起一块苹果递到你嘴边，眼神含水：「来，吃块水果。小宇那孩子不懂事，整天窝在屋里。还是你懂事，肯陪阿姨说说话……」" onclick="selectStarter(this)">晚饭后，林铭宇借口说有事匆匆溜回了房间，客厅里只剩下你和陈梦瑶。她端着一盘水果坐到你身边，大腿几乎贴着你的大腿，熟透的蜜桃臀毫不避讳地压在沙发垫上。她叉起一块苹果递到你嘴边，眼神含水：「来，吃块水果。小宇那孩子不懂事，整天窝在屋里。还是你懂事，肯陪阿姨说说话……」</div>

          <div class="starter-item" data-text="深夜，你起床去洗手间。走廊尽头，陈雨欣的房门虚掩着，暖黄色的灯光从门缝里泻出。你无意间一瞥，看到她正对着穿衣镜，身上只穿着丁字裤，双手托着自己饱满的乳房在仔细涂抹身体乳，光滑无毛的粉嫩私处正对着镜面。她似乎从镜子里看到了你，动作顿了一下，却没有遮挡，反而缓缓转过身，似笑非笑地看着门口。" onclick="selectStarter(this)">深夜，你起床去洗手间。走廊尽头，陈雨欣的房门虚掩着，暖黄色的灯光从门缝里泻出。你无意间一瞥，看到她正对着穿衣镜，身上只穿着丁字裤，双手托着自己饱满的乳房在仔细涂抹身体乳，光滑无毛的粉嫩私处正对着镜面。她似乎从镜子里看到了你，动作顿了一下，却没有遮挡，反而缓缓转过身，似笑非笑地看着门口。</div>

          <div class="starter-item" data-text="凌晨一点，门铃突然响起。你打开门，林铭宇站在门外。他眼神闪烁，脸上带着毫不掩饰的崩溃：「兄弟……我妈和我姐……她们又……我实在是没办法了……你今晚……就去我家吧……」他话没说完，身后传来陈梦瑶妖媚的声音：「小宇……是谁来啦？」" onclick="selectStarter(this)">凌晨一点，门铃突然响起。你打开门，林铭宇站在门外。他眼神闪烁，脸上带着毫不掩饰的崩溃：「兄弟……我妈和我姐……她们又……我实在是没办法了……你今晚……就去我家吧……」他话没说完，身后传来陈梦瑶妖媚的声音：「小宇……是谁来啦？」</div>

        </div>

        <div class="player-item starter-custom" style="grid-column:1/-1;">
          <div class="label">自定义开场白</div>
          <textarea id="starter-custom-input" placeholder="输入你自己的开场白...（选填，留空则无）"></textarea>
        </div>
      </div>
    </div>
  </div>

  <!-- ========== 生成按钮 ========== -->
  <div class="generate-area">
    <button class="generate-btn" id="generate-btn" onclick="generateSummary()">
      <span class="star">✦</span>
      生成角色卡
      <span class="star">✦</span>
    </button>
  </div>

  <!-- ========== 总结区 ========== -->
  <div class="summary-area" id="summary-area">
    <div class="summary-title">角色卡片</div>
    <div class="summary-card">
      <div class="summary-content" id="summary-content">
        <div class="empty-state">点击上方「生成角色卡」按钮，<br>生成你的专属角色卡。</div>
      </div>
      <div class="copy-area">
        <button class="copy-btn" id="copy-btn" onclick="copySummary()" style="opacity:0;pointer-events:none;pointer-events:auto;opacity:1;">
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="9" y="9" width="13" height="13" rx="2"/><path d="M5 15H4a2 2 0 01-2-2V4a2 2 0 012-2h9a2 2 0 012 2v1"/></svg>
          一键复制
        </button>
      </div>
    </div>
  </div>

</div>

<script>
/* ===== 折叠功能 ===== */
document.querySelectorAll(''.fold-btn'').forEach(btn=>{
  btn.addEventListener(''click'',function(){
    const target=this.getAttribute(''data-target'');
    const card=this.closest(''.card'');
    const collapse=card.querySelector(''.collapse-area'');
    collapse.classList.toggle(''closed'');
    this.textContent=collapse.classList.contains(''closed'')%s''展开'':''收起'';
  });
});

/* ===== 字符折叠 ===== */
function toggleChar(id){
  const el=document.getElementById(id);
  el.classList.toggle(''closed'');
}

/* ===== 开场白选择 ===== */
let selectedStarter='''';
function selectStarter(el){
  document.querySelectorAll(''.starter-item'').forEach(item=>item.classList.remove(''selected''));
  el.classList.add(''selected'');
  selectedStarter=el.getAttribute(''data-text'');
}

/* ===== 生成总结 ===== */
function generateSummary(){

  // 收集玩家设定
  const name=document.getElementById(''p-name'').value.trim()||''未命名'';
  const age=document.getElementById(''p-age'').value.trim()||''未知'';
  const look=document.getElementById(''p-look'').value.trim()||''普通身材，体格匀称'';
  const dick=document.getElementById(''p-dick'').value.trim()||''18cm/6cm，粗壮坚硬，微微上翘'';
  const extra=document.getElementById(''p-extra'').value.trim();

  // 收集开场白
  const customStarter=document.getElementById(''starter-custom-input'').value.trim();
  const finalStarter=customStarter||selectedStarter||''黄昏时分，你按响了林铭宇家的门铃。门被打开，一股幽香的暖风带着女人和欲望的气息，扑面而来。'';

  let playerText='''';
  playerText+=`【玩家设定】\n`;
  playerText+=`姓名：${name}\n`;
  playerText+=`年龄：${age}\n`;
  playerText+=`外貌：${look}\n`;
  playerText+=`肉棒：${dick}\n`;
  if(extra){
    playerText+=`额外设定：${extra}\n`;
  }

  const dividerText=`\n✦ ✦ ✦ ✦ ✦ ✦\n`;

  let starterText=`【开场白】\n${finalStarter}\n`;

  const summaryText=playerText+dividerText+starterText;

  // 输出到总结区
  const content=document.getElementById(''summary-content'');
  content.innerHTML='''';
  const textNode=document.createElement(''div'');
  textNode.style.whiteSpace=''pre-wrap'';
  textNode.style.wordBreak=''break-word'';
  textNode.textContent=summaryText;
  content.appendChild(textNode);

  // 显示复制按钮
  const copyBtn=document.getElementById(''copy-btn'');
  copyBtn.style.opacity=''1'';
  copyBtn.style.pointerEvents=''auto'';
  copyBtn.classList.remove(''copied'');
  copyBtn.innerHTML=''<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="9" y="9" width="13" height="13" rx="2"/><path d="M5 15H4a2 2 0 01-2-2V4a2 2 0 012-2h9a2 2 0 012 2v1"/></svg> 一键复制'';

  // 滚动到总结区
  setTimeout(()=>{
    document.getElementById(''summary-area'').scrollIntoView({behavior:''smooth'',block:''center''});
  },100);
}

/* ===== 复制功能 ===== */
function copySummary(){
  const content=document.getElementById(''summary-content'');
  const text=content.innerText.replace(/\n{3,}/g,''\n\n'').trim();

  const copyBtn=document.getElementById(''copy-btn'');

  if(navigator.clipboard && navigator.clipboard.writeText){
    navigator.clipboard.writeText(text).then(()=>{
      copyBtn.classList.add(''copied'');
      copyBtn.innerHTML=''<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><path d="M20 6L9 17l-5-5"/></svg> 已复制'';
      setTimeout(()=>{
        copyBtn.classList.remove(''copied'');
        copyBtn.innerHTML=''<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="9" y="9" width="13" height="13" rx="2"/><path d="M5 15H4a2 2 0 01-2-2V4a2 2 0 012-2h9a2 2 0 012 2v1"/></svg> 一键复制'';
      },2000);
    }).catch(()=>{
      fallbackCopy(text);
    });
  }else{
    fallbackCopy(text);
  }
}

function fallbackCopy(text){
  const content=document.getElementById(''summary-content'');
  const range=document.createRange();
  range.selectNodeContents(content);
  const selection=window.getSelection();
  selection.removeAllRanges();
  selection.addRange(range);

  try{
    document.execCommand(''copy'');
    const copyBtn=document.getElementById(''copy-btn'');
    copyBtn.classList.add(''copied'');
    copyBtn.innerHTML=''<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><path d="M20 6L9 17l-5-5"/></svg> 已复制'';
    setTimeout(()=>{
      copyBtn.classList.remove(''copied'');
      copyBtn.innerHTML=''<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="9" y="9" width="13" height="13" rx="2"/><path d="M5 15H4a2 2 0 01-2-2V4a2 2 0 012-2h9a2 2 0 012 2v1"/></svg> 一键复制'';
    },2000);
  }catch(err){
    alert(''复制失败，请手动复制文本。'');
  }
  selection.removeAllRanges();
}
</script>

</body>
</html>', '都市情感', '2026-10-05 10:12:59', '2026-10-05 10:15:00', '', '', '[]', '') ON CONFLICT (id) DO NOTHING;
INSERT INTO stories (id, title, badge, cover_icon, cover_title, cover_subtitle, logo, theme_color, btn_gradient, handbook_json, roles_json, scenes_json, styles_json, first_turn_demo_json, custom_css, custom_html, category, created_at, updated_at, system_prompt, status_template, lorebook_json, post_history_instructions) VALUES ('78546857-37c0-4608-a376-9d7efc653cdf', '爹妈将管教不了的妹妹交给了你', '家庭 · 叛逆管教', '👧', '爹妈将管教不了的妹妹交给了你', '家庭 · 叛逆管教', '👧', '#ff1493', 'linear-gradient(135deg, #ff1493 0%, #c71585 100%)', '{"title": "爹妈将管教不了的妹妹交给了你", "desc": "你的家庭是一个重组家庭。近期，你的继妹夏茉迎来了极其严重的青春期叛逆，染发抽烟甚至对父母满嘴恶言。极度失望的父母断绝了她的生活费并打包送上了高铁塞到你家，给你下了死命令：不管用什么手段，替我们狠狠管教她！", "bg_image": "https://catai.wiki/2d0465c2-18a6-48c4-3d07-c565e7c2a100/cover", "opening_options": ["【玄关对峙·立下规矩】：“夏茉嚼着口香糖，戴着耳机将行李箱往你脚边一踢，伸手找你要钱点外卖。你面色冷淡地打掉她的手……”", "【没收手机·断网制裁】：“进门第一件事，你要求她交出手机并拔掉WiFi电源，她瞬间像被踩了尾巴的小猫一样尖叫起来……”", "【冷眼旁观·任性碰壁】：“你没有多说什么，自顾自做饭吃晚餐，看她能在又饿又没钱的情况下硬撑到几点……”"]}', '[{"name": "夏茉", "role": "继妹 (16岁 / 地雷系穿搭 / 叛逆嘴臭 / 初恋脸)", "desc": "重组家庭的继妹。表面嚣张跋扈、满嘴网络抽象梗，把你当成免费佣人和老登；内心极度敏感脆弱、渴望被在意，防备心极强。"}, {"name": "哥哥 (玩家)", "role": "管教者与监护人", "desc": "独自居住的大学毕业生/青年，受父母之托对夏茉进行生活上的管教与心理上的引导。"}]', '[{"title": "单身公寓门厅 · 杂乱的玄关前", "desc": "狭窄但整洁的公寓门口，弥漫着少女身上淡淡的电子烟香气。"}]', '{"dialogue_style": "张力十足的生活化情感博弈，生动的神态捕捉与心理推拉", "format": "AI风月标准双栏规范及.custom-ui样式"}', '{"index": 1, "isUser": false, "scene": "单身公寓门厅 · 杂乱的玄关前", "story": "<tl>📅时间：周五傍晚 18:00 | 🌏地点：单身公寓门厅 | 🚪氛围：针锋相对</tl>\n\n<article>\n<p>砰的一声，门铃响得急促而暴躁。</p>\n\n<p>你拉开防盗门，一股混杂着劣质草莓味电子烟与少女微弱香水的气味迎面扑来。站在门外台阶上的，正是那个让全家头疼欲裂的继妹——夏茉。</p>\n\n<p>她头戴一副硕大的粉黑配色降噪耳机，身上套着一件快要盖过百褶裙的宽大破洞T恤，细瘦白皙的长腿上踩着厚底松糕鞋。她嘴里正漫不经心地嚼着口香糖，鼻腔里哼出一声冷气，抬起脚把那个沉重的行李箱直接踢到了你的鞋柜边上。</p>\n\n<p><w>“看什么看啊虾头男？”</w>夏茉摘下一侧耳机挂在脖子上，抱着双臂斜眼上下打量着你，语气刻薄又带着挑衅，<w>“别以为那两个老登把你搬出来本小姐就会怕你。赶紧爆点金币给我点个外卖，本小姐坐了一下午高铁快饿死了，别逼我急眼啊！”</w></p>\n</article>", "branches": [{"tag": "A", "title": "立下规矩", "desc": "严厉制止她的无礼行为，勒令收起香烟与耳机"}, {"tag": "B", "title": "经济制裁", "desc": "明确告知这里由你做主，交出手机才给饭吃"}, {"tag": "C", "title": "冷漠无视", "desc": "无视她的叫嚣，关上房门看她能嘴硬多久"}]}', '', '<html lang="zh-CN">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no">
<title>继妹管教计划</title>
<style>
:root {--primary-pink:#ff1493;--dark-pink:#c71585;--bg-black:#0f0f14;--card-bg:#1a1a24;--text-main:#e0e0e0;--text-muted:#888899;--border-color:#333344;}
* {box-sizing:border-box;margin:0;padding:0;-webkit-tap-highlight-color:transparent;}
body {font-family:''Microsoft YaHei'', sans-serif;background-color:var(--bg-black);color:var(--text-main);line-height:1.6;font-size:15px;background-image:linear-gradient(45deg, rgba(255,20,147,0.03) 25%, transparent 25%, transparent 75%, rgba(255,20,147,0.03) 75%, rgba(255,20,147,0.03)), linear-gradient(45deg, rgba(255,20,147,0.03) 25%, transparent 25%, transparent 75%, rgba(255,20,147,0.03) 75%, rgba(255,20,147,0.03));background-size:40px 40px;background-position:0 0, 20px 20px;}
.container {max-width:700px;margin:0 auto;padding:15px;min-height:100vh;}
.header {text-align:center;padding:30px 0 20px;border-bottom:2px dashed var(--primary-pink);margin-bottom:25px;}
.title {font-size:2.2em;color:var(--primary-pink);font-weight:900;text-shadow:2px 2px 5px rgba(255,20,147,0.4);letter-spacing:3px;margin-bottom:10px;text-transform:uppercase;}
.subtitle {font-size:1em;color:var(--text-muted);font-style:italic;}
.card {background:var(--card-bg);border:1px solid var(--border-color);border-left:4px solid var(--primary-pink);border-radius:8px;padding:20px;margin-bottom:20px;box-shadow:0 4px 15px rgba(0,0,0,0.5);position:relative;overflow:hidden;}
.card::before {content:''🖤'';position:absolute;top:10px;right:15px;font-size:1.5em;opacity:0.2;}
.card-title {color:var(--primary-pink);font-size:1.3em;margin-bottom:15px;display:flex;align-items:center;font-weight:bold;}
.card-title::before {content:'''';display:inline-block;width:8px;height:8px;background:var(--primary-pink);border-radius:50%;margin-right:10px;}
.tags-container {display:flex;flex-wrap:wrap;gap:8px;margin-bottom:15px;}
.tag {background:rgba(255,20,147,0.1);color:var(--primary-pink);border:1px solid rgba(255,20,147,0.3);padding:4px 10px;border-radius:15px;font-size:0.85em;}
.desc-text {margin-bottom:10px;color:#ccc;}
.highlight {color:var(--primary-pink);font-weight:bold;}
.warning-box {background:rgba(255,0,0,0.1);border:1px solid #ff4444;border-left:4px solid #ff4444;padding:15px;border-radius:6px;margin-top:15px;}
.warning-title {color:#ff4444;font-weight:bold;margin-bottom:8px;display:flex;align-items:center;}
.warning-title::before {content:''⚠️'';margin-right:5px;}
.warning-text {font-size:0.9em;color:#ffaaaa;margin-bottom:5px;}
details {background:#111118;border:1px solid var(--border-color);border-radius:6px;margin-top:15px;overflow:hidden;}
summary {padding:12px 15px;font-weight:bold;color:var(--primary-pink);cursor:pointer;user-select:none;display:flex;align-items:center;background:rgba(255,20,147,0.05);}
summary::before {content:''▶'';display:inline-block;margin-right:10px;font-size:0.8em;transition:transform 0.2s;}
details[open] summary::before {transform:rotate(90deg);}
.details-content {padding:15px;font-size:0.95em;border-top:1px solid var(--border-color);color:#ffb3c1;}
.form-group {margin-bottom:20px;}
.form-label {display:block;font-weight:bold;color:var(--text-main);margin-bottom:8px;font-size:1em;}
.form-hint {font-size:0.8em;color:var(--text-muted);font-weight:normal;margin-left:5px;}
input[type="text"], textarea {width:100%;padding:12px;border:1px solid var(--border-color);background:#111118;color:var(--text-main);font-family:inherit;font-size:0.95em;border-radius:4px;transition:all 0.3s;}
input[type="text"]:focus, textarea:focus {outline:none;border-color:var(--primary-pink);box-shadow:0 0 8px rgba(255,20,147,0.3);}
textarea {height:80px;resize:vertical;}
.btn-submit {display:block;width:100%;padding:15px;background:transparent;color:var(--primary-pink);font-size:1.2em;font-weight:bold;border:2px solid var(--primary-pink);border-radius:6px;cursor:pointer;margin-top:30px;transition:all 0.3s;text-transform:uppercase;letter-spacing:2px;}
.btn-submit:hover {background:var(--primary-pink);color:#fff;box-shadow:0 0 15px rgba(255,20,147,0.5);}
#result-box {display:none;margin-top:25px;animation:fadeIn 0.5s;}
@keyframes fadeIn {from{opacity:0;transform:translateY(10px);} to{opacity:1;transform:translateY(0);}}
#output-text {width:100%;height:220px;background:#0a0a0d;color:#ffb3c1;border:1px dashed var(--primary-pink);padding:15px;font-family:monospace;font-size:0.95em;white-space:pre-wrap;resize:none;border-radius:6px;}
.footer {text-align:center;margin-top:40px;padding:20px 0;font-size:0.85em;color:var(--text-muted);border-top:1px solid var(--border-color);}
</style>
</head>
<body>
<div class="container">
<div class="header">
<h1 class="title">继妹管教计划</h1>
<div class="subtitle">"别逼我急眼啊，老登！" —— 绝对服从的调教之路</div>
</div>
<div class="card">
<div class="card-title">👧 目标档案：夏茉 (你的继妹)</div>
<div class="tags-container">
<span class="tag">地雷系亚逼</span>
<span class="tag">嚣张嘴臭</span>
<span class="tag">初恋脸</span>
<span class="tag">158cm/42kg</span>
<span class="tag">B罩杯微乳</span>
<span class="tag">降噪耳机</span>
<span class="tag">绝对处女</span>
</div>
<p class="desc-text">表面嚣张跋扈，把你当“爆金币的老登”和“免费佣人”。日常大码T恤配热裤/百褶裙、破洞网袜、厚底鞋，戴Choker。私下喜欢穿带骷髅或蕾丝元素的黑色内衣装成熟。</p>
<details>
<summary>💬 听听她怎么说</summary>
<div class="details-content">
「看什么看啊虾头男？尊嘟假嘟，你不会真以为老登把你当盘菜了吧？赶紧爆点金币给本小姐点个外卖，别逼我急眼啊，急了急了急了！」
</div>
</details>
</div>
<div class="card">
<div class="card-title">⚙️ 核心玩法与排雷指南</div>
