.fy-fall{display:flex;align-items:center;gap:10px;box-sizing:border-box;width:100%;margin:12px 0 10px;padding:10px 14px;border:1px solid rgba(184,31,74,.30);border-radius:15px;background:linear-gradient(145deg,rgba(255,255,255,.97),rgba(255,245,248,.94));box-shadow:0 10px 28px rgba(93,70,82,.10),inset 0 1px rgba(255,255,255,.9);color:#463d43;font-family:"PingFang SC","Microsoft YaHei",system-ui,sans-serif}
