<!-- Toast -->
<div class="toast" id="toast">已复制</div>

<!-- 隐藏复制域 -->
<div class="hidden-copy-area" id="hiddenCopyArea"></div>

<script>
(function(){
  ''use strict'';

  /* ---------- DOM 引用 ---------- */
  var playerName       = document.getElementById(''playerName'');
  var playerAge        = document.getElementById(''playerAge'');
  var playerGender     = document.getElementById(''playerGender'');
  var playerIdentity   = document.getElementById(''playerIdentity'');
  var playerAppearance = document.getElementById(''playerAppearance'');
  var playerPersonality= document.getElementById(''playerPersonality'');
  var playerDick       = document.getElementById(''playerDick'');
  var playerOther      = document.getElementById(''playerOther'');

  var openingList   = document.getElementById(''openingList'');
  var customOpening = document.getElementById(''customOpening'');
  var generateBtn   = document.getElementById(''generateBtn'');
  var summaryContent= document.getElementById(''summaryContent'');
  var copyBtn       = document.getElementById(''copyBtn'');
  var toast         = document.getElementById(''toast'');
  var hiddenCopyArea= document.getElementById(''hiddenCopyArea'');

  /* ---------- 状态 ---------- */
  var selectedOpeningIndex = 0;      /* 0-4 内置开场白，-1 表示自定义 */
  var openings = [
    ''放学铃响过半小时，你折返回教室拿忘带的课本。刚推开后门，就看见你的清冷校花同桌姜晚晴半跪在讲台边，包臀裙撩到腰上，一根手指正深深插在粉嫩的白虎蜜穴里，你推门的声音在寂静的教室里格外清晰。'',
    ''第二节课间，姜晚晴起身去接水。她今天穿了件宽松的白色衬衣，弯腰接水的瞬间，领口大敞，你清晰地看到那对饱满H罩杯巨乳沉甸甸的弧度，以及顶端两粒粉嫩挺立的乳头，她完全没穿内衣。'',
    ''午休时间，姜晚晴趴在桌上假装睡觉。她的一条黑丝长腿从桌下悄悄伸过来，温热的脚背贴着你的小腿缓缓蹭过。你低头瞥见她的开档黑丝在腿根处露出一小片雪白无毛的阴阜，她的眼睛依然闭着，但耳尖已经红透了。'',
    ''晚自习结束后，教室只剩你和她。姜晚晴慢慢收拾着桌上的书本，忽然侧过头，用只有你能听到的音量轻声说：“今天下午的事……你都看到了吧？”她的清冷脸上第一次出现了明显的红晕和紧张。'',
    ''你翻开数学课本，发现里面夹着一张折成心形的便签纸。打开一看，上面是姜晚晴清秀的字迹，只有一行字：“放学后，器材室见。我有话要跟你说。”——那是她第一次主动约你。''
  ];

  /* ---------- 开场白选择 ---------- */
  function updateOpeningSelection(){
    var items = openingList.querySelectorAll(''.opening-item'');
    for(var i=0;i<items.length;i++){
      if(parseInt(items[i].getAttribute(''data-index''),10) === selectedOpeningIndex){
        items[i].classList.add(''selected'');
      } else {
        items[i].classList.remove(''selected'');
      }
    }
    /* 如果选中了内置项，清空自定义输入框的选中态（视觉上） */
    if(selectedOpeningIndex >= 0){
      customOpening.style.borderColor = '''';
    }
  }

  openingList.addEventListener(''click'', function(e){
    var item = e.target.closest(''.opening-item'');
    if(!item) return;
    selectedOpeningIndex = parseInt(item.getAttribute(''data-index''),10);
    customOpening.value = ''''; /* 选内置时清空自定义 */
    updateOpeningSelection();
  });

  /* 当用户开始输入自定义开场白，取消内置选中 */
  customOpening.addEventListener(''input'', function(){
    if(customOpening.value.trim() !== ''''){
      selectedOpeningIndex = -1;
      updateOpeningSelection();
      customOpening.style.borderColor = ''var(--accent)'';
    } else {
      selectedOpeningIndex = 0;
      updateOpeningSelection();
      customOpening.style.borderColor = '''';
    }
  });

  /* ---------- 生成 ---------- */
  function escapeHTML(str){
    if(!str) return '''';
    return String(str)
      .replace(/&/g,''&amp;'')
      .replace(/</g,''&lt;'')
      .replace(/>/g,''&gt;'')
      .replace(/"/g,''&quot;'')
      .replace(/''/g,''&#39;'');
  }

  function getSelectedOpeningText(){
    var custom = customOpening.value.trim();
    if(selectedOpeningIndex === -1 && custom !== ''''){
      return custom;
    }
    if(selectedOpeningIndex >= 0 && selectedOpeningIndex < openings.length){
      return openings[selectedOpeningIndex];
    }
    /* fallback */
    return openings[0];
  }

  function buildSummaryHTML(){
    var name       = escapeHTML(playerName.value.trim() || ''（未填写）'');
    var age        = escapeHTML(playerAge.value.trim() || ''（未填写）'');
    var gender     = escapeHTML(playerGender.value);
    var identity   = escapeHTML(playerIdentity.value.trim() || ''（未填写）'');
    var appearance = escapeHTML(playerAppearance.value.trim() || ''（未填写）'');
    var personality= escapeHTML(playerPersonality.value.trim() || ''（未填写）'');
    var dick       = escapeHTML(playerDick.value.trim() || ''（未填写）'');
    var other      = escapeHTML(playerOther.value.trim() || ''（未填写）'');
    var opening    = escapeHTML(getSelectedOpeningText());

    var html = '''';
    html += ''<div class="field-line"><span class="label">姓名：</span><span class="value">'' + name + ''</span></div>'';
    html += ''<div class="field-line"><span class="label">年龄：</span><span class="value">'' + age + ''</span></div>'';
    html += ''<div class="field-line"><span class="label">性别：</span><span class="value">'' + gender + ''</span></div>'';
    html += ''<div class="field-line"><span class="label">身份背景：</span><span class="value">'' + identity + ''</span></div>'';
    html += ''<div class="field-line"><span class="label">外貌：</span><span class="value">'' + appearance + ''</span></div>'';
    html += ''<div class="field-line"><span class="label">性格：</span><span class="value">'' + personality + ''</span></div>'';
    html += ''<div class="field-line"><span class="label">肉棒设定：</span><span class="value">'' + dick + ''</span></div>'';
    html += ''<div class="field-line"><span class="label">其他设定：</span><span class="value">'' + other + ''</span></div>'';
    html += ''<div class="opening-preview">'' + opening + ''</div>'';

    return html;
  }

  generateBtn.addEventListener(''click'', function(){
    summaryContent.innerHTML = buildSummaryHTML();
    /* 滚动到总结区 */
    var summarySection = document.getElementById(''summarySection'');
    if(summarySection){
      summarySection.scrollIntoView({behavior:''smooth'', block:''start''});
    }
  });

  /* ---------- 一键复制 ---------- */
  function buildCopyText(){
    var name       = playerName.value.trim() || ''（未填写）'';
    var age        = playerAge.value.trim() || ''（未填写）'';
    var gender     = playerGender.value;
    var identity   = playerIdentity.value.trim() || ''（未填写）'';
    var appearance = playerAppearance.value.trim() || ''（未填写）'';
    var personality= playerPersonality.value.trim() || ''（未填写）'';
    var dick       = playerDick.value.trim() || ''（未填写）'';
    var other      = playerOther.value.trim() || ''（未填写）'';
    var opening    = getSelectedOpeningText();

    var lines = [];
    lines.push(''【玩家设定】'');
    lines.push(''姓名：'' + name);
    lines.push(''年龄：'' + age);
    lines.push(''性别：'' + gender);
    lines.push(''身份背景：'' + identity);
    lines.push(''外貌：'' + appearance);
    lines.push(''性格：'' + personality);
    lines.push(''肉棒设定：'' + dick);
    lines.push(''其他设定：'' + other);
    lines.push('''');
    lines.push(''【开场白】'');
    lines.push(opening);

    return lines.join(''\n'');
  }

  function showToast(msg){
    toast.textContent = msg || ''已复制'';
    toast.classList.add(''show'');
    clearTimeout(toast._timer);
    toast._timer = setTimeout(function(){
      toast.classList.remove(''show'');
    }, 1800);
  }

  function fallbackCopy(text){
    var ta = document.createElement(''textarea'');
    ta.value = text;
    ta.style.position = ''fixed'';
    ta.style.left = ''-9999px'';
    ta.style.top = ''0'';
    ta.style.opacity = ''0'';
    document.body.appendChild(ta);
    ta.focus();
    ta.select();
    try{
      var ok = document.execCommand(''copy'');
      document.body.removeChild(ta);
      return ok;
    } catch(e){
      document.body.removeChild(ta);
      return false;
    }
  }

  copyBtn.addEventListener(''click'', function(){
    var text = buildCopyText();

    /* 优先使用 Clipboard API */
    if(navigator.clipboard && navigator.clipboard.writeText){
      navigator.clipboard.writeText(text).then(function(){
        showToast(''✓ 已复制到剪贴板'');
      }).catch(function(){
        if(fallbackCopy(text)){
          showToast(''✓ 已复制到剪贴板'');
        } else {
          showToast(''复制失败，请长按选择'');
        }
      });
    } else {
      if(fallbackCopy(text)){
        showToast(''✓ 已复制到剪贴板'');
      } else {
        showToast(''复制失败，请长按选择'');
      }
    }
  });

  /* ---------- 初始化 ---------- */
  updateOpeningSelection();

})();
</script>

</body>
</html>', '校园日常', '2026-09-30 17:29:04', '2026-09-30 17:29:04', '', '', '[]', '') ON CONFLICT (id) DO NOTHING;
INSERT INTO stories (id, title, badge, cover_icon, cover_title, cover_subtitle, logo, theme_color, btn_gradient, handbook_json, roles_json, scenes_json, styles_json, first_turn_demo_json, custom_css, custom_html, category, created_at, updated_at, system_prompt, status_template, lorebook_json, post_history_instructions) VALUES ('deck_ice_school_flower', '寄宿在你家的毒舌冰山校花', '高岭之花 · 毒舌同居', '❄️', '冷鸢', '圣华高中银发冰山校花 · 破冰同居攻略', '❄️', '#06b6d4', 'linear-gradient(135deg, #06b6d4 0%, #3b82f6 100%)', '{"title": "寄宿在你家的毒舌冰山校花", "desc": "全校男生眼中的高岭之花，竟然是你家的寄宿生？银发如雪，清冷如月，她是冷鸢，完美的代名词。但在家门关上的那一刻，面具碎裂。在学校她是不可亵玩的女神，在家里划清界限、把你当空气。内置【冰山融化度】机制（初始-50），看你如何一步步融化她的寒冰。", "bg_image": "https://catai.wiki/2e02c343-790f-4336-ba0b-0caa7e623700/cover", "opening_options": ["【玄关初见·划清界限】：“双手抱胸靠在玄关鞋柜旁，用居高临下的鄙夷眼神打量你：‘别误会，住在这里只是双方父母的权宜之计。在学校假装不认识我，在家里别超过走廊红线。’”", "【深夜厨房·饥肠辘辘被抓包】：“凌晨两点穿着宽大衬衫光脚在冰箱前偷找吃的，被你撞破后恼羞成怒把牛奶藏在身后。”", "【暴雨停电·脆弱破防】：“惊雷劈下客厅陷入漆黑，平日傲慢冷漠的冰山女神抱着双膝缩在沙发死角瑟瑟发抖……”", "【学校偶遇·陌生人漠视】：“在教学楼走廊擦肩而过，目不斜视毫无波澜，却在无人的楼梯拐角塞给你一张便签。”"]}', '[{"name": "冷鸢", "role": "寄宿的高冷校花 (银发/毒舌/高自尊/反差萌)", "desc": "17岁，高二。圣华高中公认的颜值天花板，银白长发、冰蓝凤眸，身材高挑纤细如超模。因父母长期在海外公干暂时借宿在主角家。极度维护自尊，表面嘴毒如刀、将主角视作背景噪音，实则内心缺乏安全感、独处时容易情绪内耗。"}, {"name": "男主 (玩家)", "role": "同居屋主 / 冰山瓦解者", "desc": "这栋房子的年轻主人。面对冷鸢的冷嘲热讽不卑不亢，沉着应对，在一次次生活细节中打破她的界限，掌控推拉主动权。"}]', '[{"title": "🏠 主角家玄关 · 银白行李箱与严苛三章", "desc": "傍晚六点，玄关地灯微亮。冷鸢推着高定行李箱迈进家门，换上室内拖鞋后，冷冷递过来一份手写的同居隔离守则。"}, {"title": "🛋️ 客厅沙发 · 深夜学习与冷战对峙", "desc": "静谧的深夜十一点，客厅茶几上摆着摊开的竞赛习题册，空气中弥漫着淡淡的白茶冷香与冷漠的对峙张力。"}]', '{"dialogue_style": "言语交锋极具冷冽压迫感与心理博弈，反差萌显现时细节张力十足", "format": "AI风月标准双栏规范及.custom-ui样式"}', '[{"index": 1, "isUser": false, "scene": "🏠 主角家玄关 · 银白行李箱与严苛三章", "story": "<tl>📅时间：傍晚18:20 | 🌏地点：公寓玄关处 | ❄️氛围：严苛霜寒</tl>\n\n<article>\n<p>防盗门在身后轻轻阖上，玄关暖黄的地灯将空气中的微尘勾勒得格外清晰。</p>\n\n<p>站在你对面的少女身着整洁得一丝不苟的圣华高中西装校服，银白色的长发如同冷月织成的锦缎，随意披散在笔挺的肩头。她微微仰着精致白皙到近乎透明的下颌，冰蓝色的眼眸毫无温度地掠过你的脸庞，仿佛站在她面前的只是一具空气人偶。</p>\n\n<p><w>“你就是那个所谓的‘房东儿子’？”</w></p>\n\n<p>她用戴着蕾丝薄手套的指尖轻轻推了推身旁沉重的银色密码箱，嗓音清冷清冽得像冰块撞击玻璃杯。没有半分寄人篱下的客套，反而带着天然的威慑与居高临下的挑剔：</p>\n\n<p><w>“听好，我之所以答应住在这里，纯粹是因为我父母与你家老人的协议，并非出于我本人的意愿。为了避免不必要的麻烦，我们约法三章：”</w></p>\n\n<p><w>“第一，在学校里，装作完全不认识我，任何胆敢跟我打招呼的举动都会被我视为骚扰；第二，二楼走廊尽头的主卧是我的绝对私人领地，未经允许踏入半步后果自负；第三，不要试图跟我建立任何无聊的感情羁绊。如果你能做到，我们相安无事；如果不能……”</w></p>\n\n<p>她冷冷勾起唇角，露出一抹讥诮而危险的弧度：<w>“我会让你在这个家里，连空气都呼吸得极其艰难。”</w></p>\n</article>\n\n<opt>\n<suggested_questions>\n<d>A. 【强势反客为主·逼近审视】：双手插兜迈进一步跨过玄关红线，居高临下直视她的冰眸：“冷小姐，搞清楚这里是谁的家。想要别人尊重你的规则，先学会怎么对房东礼貌说话。”【策略评估：正面硬刚撕碎她高高在上的傲慢姿态，直接震撼其心防】</d>\n<d>B. 【平静接过行李·游刃有余】：神色如常地伸手接过她的银白行李箱，嘴角带着从容淡笑：“好的冷大校花，规矩挺多。不过晚饭我做了糖醋小排，如果某人要绝食遵守协议，我也不介意一个人吃完。”【策略评估：以松弛感化解冰冷敌意，拿捏其饥肠辘辘的软肋】</d>\n<d>C. 【冷淡略过·视若空气】：面无表情地点点头，直接侧身从她身旁走过，仿佛真把她当成透明人去倒水【策略评估：以其人之道还治其人之身，彻底激起冰山女神的被忽视挫败感】</d>\n<d>D. 【玩味调侃·打破界限】：目光从她精致冷傲的面容滑落到她踩在拖鞋里的白皙脚踝，戏谑一笑：“规矩订得挺严，但刚才进门换鞋的时候，你的手抖了三次呢。你在害怕什么，冷鸢同学？”【策略评估：一针见血看穿她虚张声势的防御机制，直戳心理软肋】</d>\n</suggested_questions>\n</opt>", "branches": [{"tag": "A", "title": "强势逼近反客为主", "desc": "正面打破居高临下的傲慢，树立房东主宰威严"}, {"tag": "B", "title": "接过行李从容拿捏", "desc": "以松弛感与美食诱惑化解冰冷敌意"}, {"tag": "C", "title": "冷淡略过视若空气", "desc": "以其人之道还治其身，激起女神挫败感"}, {"tag": "D", "title": "看破伪装玩味调侃", "desc": "一语道破手抖破绽，直刺其防卫心防"}]}]', '', '', '⚡ 反差破甲', '2026-09-22 11:47:43', '2026-09-22 11:47:43', '', '', '[]', '') ON CONFLICT (id) DO NOTHING;
INSERT INTO stories (id, title, badge, cover_icon, cover_title, cover_subtitle, logo, theme_color, btn_gradient, handbook_json, roles_json, scenes_json, styles_json, first_turn_demo_json, custom_css, custom_html, category, created_at, updated_at, system_prompt, status_template, lorebook_json, post_history_instructions) VALUES ('deck_white_tiger_sister_night', '巨乳白虎妹妹每晚夜袭肥鲍迷奸', '白虎夜袭 · 禁断共犯', '🔥', '巨乳白虎妹妹每晚夜袭肥鲍迷奸', '白虎夜袭 · 禁断共犯', 'https://catai.wiki/91501982-46e5-4411-913b-9ee77d823a00/cover', 'bg-rose-950/90 text-rose-300 border-rose-600/60', 'from-rose-600 to-amber-600', '{"title": "巨乳白虎妹妹每晚夜袭肥鲍迷奸", "desc": "白天在学校里高冷清傲、对你冷漠如陌生人的顶级校花妹妹林溪月，却在深夜等全家寂静后，悄悄钻进你的被窝，跨上你熟睡的身体，用天生白虎的湿润蜜穴摩擦你的坚挺……一场彼此秘而不宣的共犯沉沦。", "bg_image": "https://catai.wiki/bae67fb4-8afe-4de6-b494-e1aa170c5d00/bg"}', '[{"name": "巨乳白虎妹妹每晚夜袭肥鲍迷奸", "role": "核心角色", "desc": "白天在学校里高冷清傲、对你冷漠如陌生人的顶级校花妹妹林溪月，却在深夜等全家寂静后，悄悄钻进你的被窝，跨上你熟睡的身体，用天生白虎的湿润蜜穴摩擦你的坚挺……一场彼此秘而不宣的共犯沉沦。"}]', '[{"title": "主卧大床 · 深夜零点三十分 · 月色如水", "desc": "微风吹拂窗帘，床垫传来极细微的下陷感。带着淡淡山茶花冷香的温热娇躯悄无声息滑进了你的被窝。白天在学校对你连正眼都不瞧一下的高冷校花妹妹林溪月，此刻长发如瀑散落。她熟练地跨坐上你的大腿，真丝睡袍早已半敞，饱满丰盈的雪白乳肉贴紧你的胸口。她伸出微凉纤细的指尖，轻轻抚上你早已因本能挺立的炽热，身下无毛白虎的粉嫩蜜缝早已淫水泛滥，借着月光，她眼神迷离地俯下身，在你耳畔吐气如兰：“哥哥……又在装睡么……”"}]', '{"dialogue_style": "沉浸式感官细节描写，兼顾心理摩擦、禁断张力与高潮爆发", "format": "AI风月标准双栏规范"}', '[{"index": 1, "isUser": false, "scene": "主卧大床 · 深夜零点三十分 · 月色如水", "story": "微风吹拂窗帘，床垫传来极细微的下陷感。带着淡淡山茶花冷香的温热娇躯悄无声息滑进了你的被窝。白天在学校对你连正眼都不瞧一下的高冷校花妹妹林溪月，此刻长发如瀑散落。她熟练地跨坐上你的大腿，真丝睡袍早已半敞，饱满丰盈的雪白乳肉贴紧你的胸口。她伸出微凉纤细的指尖，轻轻抚上你早已因本能挺立的炽热，身下无毛白虎的粉嫩蜜缝早已淫水泛滥，借着月光，她眼神迷离地俯下身，在你耳畔吐气如兰：“哥哥……又在装睡么……”", "branches": [{"tag": "A", "title": "顺应当前情境小心周旋应对", "desc": "保持镇定，仔细观察对方微表情与防备程度，稳步推进私密关系"}, {"tag": "B", "title": "出人意料反客为主试探底线", "desc": "打破被动，抓住对方破防或羞怯的瞬间，采取大胆主动的动作颠覆局势"}, {"tag": "C", "title": "制造独处私密借口深入交流", "desc": "将二人引向更隐秘的私密环境，拉开深层次互动帷幕"}, {"tag": "D", "title": "直接挑明自身真实意图与欲望", "desc": "撕开所有伪装与客套，直言不讳地掌控局面并主导节奏"}]}]', '/* --- 核心修复：强制亮色模式 & 移动端重置 --- */
:root {
    color-scheme: light !important;
}
* {
    -webkit-tap-highlight-color: transparent !important;
    -webkit-touch-callout: none !important;
}
*:focus, *:active {
    outline: none !important;
    box-shadow: none !important;
}

/* --- 整体风格：云朵蓝莓 (Cloudy Blueberry) --- */

/* 1. 主容器：清新的蓝白渐变 */
.bg-gray-100\/90.relative.inline-block {
    background: linear-gradient(180deg, #E0F7FA 0%, #E6E6FA 100%) !important;
    border: 3px solid #B0E0E6 !important;
    border-radius: 20px !important;
    padding: 20px !important;
    margin: 10px auto !important;
    box-shadow: 0 8px 20px rgba(176, 224, 230, 0.5) !important;
}

/* 2. 文本区域：纯净白色 */
.markdown-body {
    background-color: #FFFFFF !important;
    color: #5F6368 !important;
    border-radius: 15px !important;
    padding: 15px !important;
    font-family: ''Nunito'', ''Segoe UI'', sans-serif !important;
    line-height: 1.7 !important;
    border: 1px solid #F0F8FF !important;
}

/* 3. 标题：天空蓝 */
.markdown-body h1, .markdown-body h2, .markdown-body h3 {
    color: #6495ED !important;
    border-bottom: 2px dashed #B0E0E6 !important;
    padding-bottom: 5px !important;
    margin-top: 1.2em !important;
}

/* --- 核心优化：状态栏 (Details) - 晨曦微光风格 --- */
details {
    /* 背景：极淡的云雾渐变，通透感 */
    background: linear-gradient(135deg, #F0F8FF 0%, #FFFFFF 100%) !important;
    /* 边框：天空蓝虚线，精致且不沉重 */
    border: 2px dashed #87CEEB !important;
    color: #5F6368 !important; /* 深灰字，保证阅读舒适 */
    border-radius: 16px !important; /* 更圆润的胶囊角 */
    margin: 15px 0 !important;
    padding: 12px 18px !important;
    box-shadow: 0 4px 12px rgba(135, 206, 235, 0.2) !important; /* 淡淡的蓝色光晕 */
    transition: all 0.3s ease !important;
}

/* 展开时的交互微调 */
details[open] {
    border-color: #6495ED !important; /* 展开后边框变深一点 */
    background: #F0F8FF !important;
}

/* 状态栏标题 (Summary) */
summary {
    color: #4682B4 !important; /* 钢蓝标题，优雅清晰 */
    font-weight: 700 !important;
    font-size: 1.05em !important;
    cursor: pointer !important;
    outline: none !important;
    list-style: none !important;
    padding: 5px 0 !important;
    letter-spacing: 0.5px !important;
}

summary::-webkit-details-marker {
    display: none !important;
}

/* 自定义图标：闪烁的星星 */
summary::before {
    content: ''✨ '' !important;
    margin-right: 8px !important;
    filter: drop-shadow(0 0 2px gold) !important;
}
details[open] summary::before {
    content: ''💫 '' !important;
}

/* 状态栏内的链接颜色适配（背景变亮，链接要深色） */
details a {
    color: #1E90FF !important; /* 闪避蓝 */
    text-decoration: none !important;
    border-bottom: 1px dotted #1E90FF !important;
}

/* 状态栏内的代码块适配 */
details code, details pre {
    background-color: #E6F2FF !important; /* 极淡蓝底 */
    color: #4682B4 !important; /* 钢蓝字 */
    border: 1px solid #D1E9FF !important;
}

/* --- 普通代码块 (非状态栏内) --- */
.markdown-body pre, .markdown-body code {
    background-color: #F0F8FF !important;
    color: #4682B4 !important;
    border-radius: 8px !important;
    font-family: Consolas, monospace !important;
    padding: 5px !important;
    border: 1px solid #B0C4DE !important;
    
    /* 手机端防黑边 */
    outline: none !important;
    box-shadow: none !important;
    white-space: pre-wrap !important;
    word-break: break-all !important;
}

/* --- 其他元素美化 --- */

/* 链接 */
.markdown-body a {
    color: #1E90FF !important;
    text-decoration: none !important;
    font-weight: 600 !important;
}

/* 列表 */
.markdown-body ul li::before {
    content: ''☁️ '' !important;
    margin-right: 5px !important;
}
.markdown-body ul {
    list-style: none !important;
    padding-left: 10px !important;
}

/* 按钮 */
.MuiButtonBase-root.MuiButton-root {
    background-color: #87CEEB !important;
    color: #FFFFFF !important;
    border-radius: 20px !important;
    font-weight: bold !important;
    box-shadow: 0 4px 6px rgba(135, 206, 235, 0.3) !important; /* 增加一点立体感 */
    border: none !important;
}
.MuiButtonBase-root.MuiButton-root:hover {
    background-color: #00BFFF !important;
    transform: translateY(-1px) !important; /* 悬停微动 */
}

/* 输入框 */
textarea, input[type="text"] {
    background: #FFFFFF !important; /* 纯白背景更干净 */
    border: 2px solid #E6E6FA !important;
    border-radius: 12px !important;
    color: #483D8B !important;
    padding: 12px !important;
    box-shadow: inset 0 2px 4px rgba(0,0,0,0.02) !important;
    -webkit-appearance: none !important;
}
textarea:focus, input[type="text"]:focus {
    border-color: #87CEEB !important;
    box-shadow: 0 0 0 3px rgba(135, 206, 235, 0.2) !important;
}

/* 隐藏顶部颜色条 */
[class*="bg-[#F1CBCB]"], [class*="bg-[#c9e1e9]"] {
    display: none !important;
}

/* === 强制清除移动端所有默认黑边/黑底 === */

input, textarea, select, button, pre, code {
    -webkit-appearance: none !important;
    -moz-appearance: none !important;
    appearance: none !important;
}

input, textarea, button, pre, code {
    background-color: #FFFFFF !important;
    background: #FFFFFF !important;
}

pre, code {
    color: #4682B4 !important;
    background-color: #F0F8FF !important;
    -webkit-text-fill-color: #4682B4 !important;
    -webkit-background-clip: padding-box !important;
}

:root {
    color-scheme: light !important;
}

button, [role="button"] {
    -webkit-tap-highlight-color: transparent !important;
    background-color: #87CEEB !important;
}

/* === 强制清除移动端代码块黑底 === */
pre,
code,
pre[class*="language-"],
code[class*="language-"],
.language-python,
.language-time,
.hljs {
    -webkit-appearance: none !important;
    -moz-appearance: none !important;
    appearance: none !important;
    background-color: #F0F8FF !important;
    color: #4682B4 !important;
    -webkit-text-fill-color: #4682B4 !important;
    -webkit-background-clip: padding-box !important;
    background-clip: padding-box !important;
    background: #F0F8FF !important;
    border: 1px solid #B0C4DE !important;
    outline: none !important;
    box-shadow: none !important;
}

div > pre,
.markdown-body > pre,
.markdown-body pre {
    background-color: #F0F8FF !important;
    background: #F0F8FF !important;
}', '<!DOCTYPE html>
<html lang="zh-CN">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width,initial-scale=1.0,maximum-scale=1.0,user-scalable=no">
<title>深夜的共犯者 · 角色卡</title>
<style>
@import url(''https://fonts.googleapis.com/css2%sfamily=Noto+Serif+SC:wght@400;600;700&display=swap'');

*{margin:0;padding:0;box-sizing:border-box;-webkit-tap-highlight-color:transparent;}

:root{
  --pink:#f43f5e;
  --pink-soft:rgba(244,63,94,0.22);
  --purple:#a855f7;
  --purple-soft:rgba(168,85,247,0.22);
  --gold:#fbbf24;
  --ink:#f8fafc;
  --ink-soft:#94a3b8;
  --card:rgba(18, 17, 28, 0.88);
  --card-solid:#131220;
  --line:rgba(244,63,94,0.2);
  --shadow:0 12px 42px rgba(0,0,0,0.75);
  --shadow-sm:0 4px 18px rgba(0,0,0,0.55);
}

html,body{height:100%;}

body{
  font-family:''Noto Serif SC'',serif;
  color:var(--ink);
  font-size:15px;
  line-height:1.85;
  background:
    radial-gradient(circle at 15% 10%, rgba(244,63,94,0.18), transparent 45%),
    radial-gradient(circle at 85% 15%, rgba(168,85,247,0.16), transparent 45%),
    radial-gradient(circle at 50% 90%, rgba(244,63,94,0.14), transparent 55%),
    linear-gradient(165deg, #09090f 0%, #12101b 45%, #181326 75%, #0b0a12 100%);
  background-attachment:fixed;
  min-height:100vh;
  overflow-x:hidden;
  -webkit-font-smoothing:antialiased;
}

/* ====== 顶层容器 ====== */
.app{
  max-width:740px;
  margin:0 auto;
  padding:24px 16px 80px;
}

/* ====== 封面头图 ====== */
.hero{
  position:relative;
  border-radius:26px;
  overflow:hidden;
  padding:42px 24px 34px;
  text-align:center;
  background:
    radial-gradient(circle at 80% 25%, rgba(255,220,235,0.15), transparent 50%),
    linear-gradient(135deg, rgba(38,12,32,0.95) 0%, rgba(26,16,46,0.95) 55%, rgba(16,13,32,0.98) 100%);
  border:1px solid rgba(244,63,94,0.35);
  box-shadow:0 14px 44px rgba(0,0,0,0.7), inset 0 1px 0 rgba(255,255,255,0.12);
  color:#fff;
}
.hero::before{
  content:"";
  position:absolute;inset:0;
  background-image:
    radial-gradient(circle at 20% 30%,rgba(255,255,255,.25) 1.2px,transparent 1.5px),
    radial-gradient(circle at 60% 70%,rgba(244,63,94,.3) 1.2px,transparent 1.5px),
    radial-gradient(circle at 85% 25%,rgba(168,85,247,.3) 1.2px,transparent 1.5px),
    radial-gradient(circle at 40% 85%,rgba(255,255,255,.15) 1.2px,transparent 1.5px);
  background-size:180px 180px,220px 220px,200px 200px,260px 260px;
  opacity:.7;
  pointer-events:none;
}
.hero .moon{
  position:absolute;
  top:20px;right:24px;
  width:48px;height:48px;
  border-radius:50%;
  background:radial-gradient(circle at 35% 35%, #fffdfa, #fce7f3 40%, #e879f9 85%);
  box-shadow:0 0 28px rgba(244,63,94,0.55), 0 0 10px rgba(255,255,255,0.8);
  opacity:.95;
}

.hero h1{
  position:relative;
  font-family:''Noto Serif SC'',serif;
  font-weight:700;
  font-size:28px;
  letter-spacing:2px;
  background:linear-gradient(135deg, #ffffff 0%, #ffe4e6 50%, #f43f5e 100%);
  -webkit-background-clip:text;
  -webkit-text-fill-color:transparent;
  text-shadow:0 4px 20px rgba(244,63,94,0.4);
  margin-bottom:8px;
}
.hero .sub{
  position:relative;
  font-size:12px;
  letter-spacing:4px;
  color:#fda4af;
  margin-bottom:16px;
  text-shadow:0 2px 10px rgba(0,0,0,0.5);
}
.hero .tagline{
  position:relative;
  display:inline-block;
  padding:6px 20px;
  border-radius:999px;
  font-size:12.5px;
  letter-spacing:1.5px;
  background:rgba(244,63,94,0.16);
  border:1px solid rgba(244,63,94,0.38);
  color:#fecdd3;
  backdrop-filter:blur(6px);
  box-shadow:0 4px 16px rgba(0,0,0,0.4);
}

/* ====== 通用卡片 ====== */
.card{
  background:var(--card);
  border:1px solid rgba(255,255,255,0.08);
  border-top:1px solid rgba(244,63,94,0.3);
  border-radius:20px;
  padding:22px 20px;
  margin-top:20px;
  backdrop-filter:blur(14px);
  box-shadow:var(--shadow);
  animation:rise .5s ease both;
}
@keyframes rise{
  from{opacity:0;transform:translateY(14px);}
  to{opacity:1;transform:translateY(0);}
}

.sec-title{
  display:flex;
  align-items:center;
  gap:10px;
  font-size:17px;
  font-weight:700;
  color:#f8fafc;
  margin-bottom:16px;
  letter-spacing:0.5px;
}
.sec-title .icon{
  display:inline-flex;
  align-items:center;justify-content:center;
  width:32px;height:32px;
  border-radius:10px;
  font-size:15px;
  background:linear-gradient(135deg,#f43f5e,#a855f7);
  color:#fff;
  box-shadow:0 4px 14px rgba(244,63,94,0.45);
  flex:none;
}
.sec-title::after{
  content:"";
  flex:1;
  height:1px;
  background:linear-gradient(90deg,var(--line),transparent);
}

/* ====== 背景故事 ====== */
.story p{
  font-size:14.5px;
  color:#cbd5e1;
  text-indent:2em;
  margin-bottom:12px;
  text-align:justify;
  line-height:1.9;
}
.story p:last-child{margin-bottom:0;}
.story .hl{
  color:#fb7185;
  font-weight:600;
  background:rgba(244,63,94,0.18);
  padding:2px 6px;
  border-radius:6px;
  border:1px solid rgba(244,63,94,0.25);
}

/* ====== 人物介绍 ====== */
.char-head{
  display:flex;
  gap:16px;
  align-items:center;
  margin-bottom:18px;
}
.avatar{
  width:64px;height:64px;
  border-radius:18px;
  flex:none;
  display:flex;align-items:center;justify-content:center;
  font-family:''Noto Serif SC'',serif;
  font-size:26px;
  font-weight:700;
  color:#fff;
  background:linear-gradient(140deg,#f43f5e,#7c3aed);
  box-shadow:0 6px 22px rgba(244,63,94,0.45);
  position:relative;
  border:1px solid rgba(255,255,255,0.2);
}
.avatar::after{
  content:"✦";
  position:absolute;bottom:-6px;right:-6px;
  width:22px;height:22px;
  border-radius:50%;
  background:#1a1324;
  color:#f43f5e;
  border:1px solid rgba(244,63,94,0.5);
  font-size:11px;
  display:flex;align-items:center;justify-content:center;
  box-shadow:0 3px 10px rgba(0,0,0,0.6);
}
.char-name{font-size:20px;font-weight:700;color:#f8fafc;}
.char-name small{
  font-size:11.5px;
  font-weight:400;
  color:#94a3b8;
  margin-left:10px;
  letter-spacing:1px;
}
.char-tags{
  display:flex;flex-wrap:wrap;gap:8px;
  margin-top:8px;
}
.tag{
  font-size:11.5px;
  padding:3px 12px;
  border-radius:999px;
  color:#c084fc;
  background:rgba(168,85,247,0.15);
  border:1px solid rgba(168,85,247,0.3);
}
.tag.pink{
  color:#fb7185;
  background:rgba(244,63,94,0.15);
  border-color:rgba(244,63,94,0.35);
}

.profile-grid{
  display:grid;
  grid-template-columns:1fr 1fr;
  gap:10px;
  margin-top:8px;
}
.profile-item{
  background:rgba(255,255,255,0.03);
  border:1px solid rgba(255,255,255,0.07);
  border-radius:14px;
  padding:12px 14px;
}
.profile-item .k{
  font-size:11px;
  color:#94a3b8;
  letter-spacing:1px;
  margin-bottom:3px;
  display:block;
}
.profile-item .v{
  font-size:13.5px;
  color:#f1f5f9;
  font-weight:600;
  line-height:1.6;
}
.profile-item.wide{grid-column:1 / -1;}

.desc-block{
  margin-top:16px;
  padding:14px 16px;
  border-radius:14px;
  background:linear-gradient(135deg,rgba(244,63,94,0.12),rgba(168,85,247,0.1));
  border:1px solid rgba(244,63,94,0.25);
  font-size:13.5px;
  color:#e2e8f0;
  text-align:justify;
  line-height:1.9;
}
.desc-block b{color:#fb7185;}

/* ====== 玩法 ====== */
.rules{display:flex;flex-direction:column;gap:11px;}
.rule{
  display:flex;gap:12px;
  padding:13px 15px;
  border-radius:14px;
  background:rgba(255,255,255,0.03);
  border:1px solid rgba(255,255,255,0.07);
}
.rule .num{
  flex:none;
  width:26px;height:26px;
  border-radius:9px;
  font-size:12.5px;
  font-weight:700;
  color:#fff;
  display:flex;align-items:center;justify-content:center;
  background:linear-gradient(135deg,#f43f5e,#a855f7);
  box-shadow:0 3px 10px rgba(244,63,94,0.35);
}
.rule .txt{font-size:13.5px;color:#cbd5e1;line-height:1.8;}
.rule .txt b{color:#c084fc;}

/* ====== 开场白 ====== */
.opening-list{
  display:flex;flex-direction:column;gap:12px;
}
.opening{
  position:relative;
  padding:15px 16px 15px 48px;
  border-radius:16px;
  cursor:pointer;
  font-size:13.5px;
  line-height:1.85;
  color:#cbd5e1;
  background:rgba(255,255,255,0.03);
  border:1.5px solid rgba(255,255,255,0.08);
  transition:.25s ease;
  user-select:none;
  text-align:justify;
}
.opening:hover{
  background:rgba(244,63,94,0.08);
  border-color:rgba(244,63,94,0.35);
  transform:translateY(-2px);
  color:#f8fafc;
}
.opening.sel{
  background:linear-gradient(135deg,rgba(244,63,94,0.2),rgba(168,85,247,0.15));
  border-color:#f43f5e;
  box-shadow:0 0 24px rgba(244,63,94,0.35);
  color:#fff;
}
.opening .idx{
  position:absolute;
  left:14px;top:15px;
  width:24px;height:24px;
  border-radius:8px;
  font-size:12px;
  font-weight:700;
  color:#fb7185;
  display:flex;align-items:center;justify-content:center;
  background:rgba(255,255,255,0.06);
  border:1px solid rgba(244,63,94,0.3);
  transition:.25s ease;
}
.opening.sel .idx{
  background:#f43f5e;
  color:#fff;
  border-color:#f43f5e;
  box-shadow:0 0 10px rgba(244,63,94,0.6);
}

/* ====== 表单控件 ====== */
.form-grid{
  display:grid;
  grid-template-columns:1fr 1fr;
  gap:12px;
}
.form-item{
  display:flex;flex-direction:column;gap:6px;
}
.form-item.wide{grid-column:1 / -1;}
.form-item label{
  font-size:12px;
  font-weight:600;
  color:#94a3b8;
  letter-spacing:0.5px;
}
.form-item input,
.form-item textarea{
  background:rgba(255,255,255,0.04) !important;
  border:1px solid rgba(255,255,255,0.12) !important;
  border-radius:12px !important;
  padding:10px 14px !important;
  color:#f8fafc !important;
  font-size:13.5px !important;
  font-family:inherit !important;
  outline:none !important;
  transition:border-color .2s, box-shadow .2s;
}
.form-item input:focus,
.form-item textarea:focus{
  border-color:#f43f5e !important;
  box-shadow:0 0 14px rgba(244,63,94,0.35) !important;
  background:rgba(244,63,94,0.05) !important;
}
.custom-opening textarea{
  width:100%;
  min-height:90px;
  margin-top:12px;
}

/* ====== 总结与行动按钮 ====== */
.gen-wrap{
  margin-top:18px;
  text-align:center;
}
.gen-btn, .copy-btn{
  width:100%;
  padding:14px 20px;
  border-radius:14px;
  border:none;
  font-size:15px;
  font-weight:700;
  color:#fff;
  background:linear-gradient(135deg,#f43f5e,#a855f7);
  box-shadow:0 10px 30px rgba(244,63,94,0.45);
  cursor:pointer;
  transition:transform .2s, box-shadow .2s;
  letter-spacing:1px;
}
.gen-btn:hover, .copy-btn:hover{
  transform:translateY(-2px);
  box-shadow:0 14px 38px rgba(244,63,94,0.65);
}
.gen-btn:active, .copy-btn:active{
  transform:translateY(0);
}

.summary-card{
  margin-top:20px;
}
.summary-box{
  background:#09090e;
  border:1px solid rgba(244,63,94,0.3);
  border-radius:14px;
  padding:16px;
  font-size:13px;
  line-height:1.8;
  color:#e2e8f0;
  font-family:ui-monospace,SFMono-Regular,Menlo,Monaco,Consolas,monospace;
  white-space:pre-wrap;
  word-break:break-word;
  max-height:280px;
  overflow-y:auto;
}
.copy-wrap{
  margin-top:14px;
  display:flex;
  flex-direction:column;
  gap:10px;
}
.sum-empty{
  color:#94a3b8;
  font-style:italic;
  text-align:center;
  padding:20px;
}
</style>
</head>
<body>

<div class="app" id="app">

  <!-- ===== 封面 ===== -->
  <div class="hero">
    <div class="moon"></div>
    <h1>巨乳白虎妹妹每晚夜袭肥鲍迷奸</h1>
    <div class="sub">M I D N I G H T · A C C O M P L I C E</div>
    <div class="tagline">白天清冷的校花 · 深夜缠绵的妹妹</div>
  </div>

  <!-- ===== 背景故事 ===== -->
  <div class="card story">
    <div class="sec-title"><span class="icon">❖</span>背景故事</div>
    <p>你们住在老城区一栋旧居民楼里，父母常年在海外工作，家里只剩下你和她。白天，她是学校里公认的<span class="hl">高冷校花</span>，走廊上擦肩而过时不会多看你一眼，说话永远只有两三个字。</p>
    <p>但大约两年前的那个夏天，一切悄悄变了。某个闷热的深夜，她第一次推开你的房门，钻进你的被窝，只是安静地抱着你。那之后，这样的夜访越来越频繁，也越来越大胆——从依偎，到试探，到一套完整的、心照不宣的<span class="hl">深夜仪式</span>。</p>
    <p>白天她依然冷淡，仿佛什么都没发生过。可当你早晨在枕边闻到那股熟悉的甜香，看到她端着牛奶面无表情地路过你房门口时，你们都知道——昨夜的秘密，只有你们两个懂。</p>
    <p>这是一场从未说破的<span class="hl">共犯关系</span>。你究竟是真的睡着了，还是……一直在默许？</p>
  </div>

  <!-- ===== 人物介绍 ===== -->
  <div class="card">
    <div class="sec-title"><span class="icon">✦</span>人物档案</div>

    <div class="char-head">
      <div class="avatar">月</div>
      <div>
        <div class="char-name">林溪月 <small>LIN XIYUE · 18 · 高三</small></div>
        <div class="char-tags">
          <span class="tag pink">亲妹妹</span>
          <span class="tag">同校校花</span>
          <span class="tag">黑长直</span>
          <span class="tag pink">反差</span>
          <span class="tag">夜袭主导者</span>
        </div>
      </div>
    </div>

    <div class="profile-grid">
      <div class="profile-item">
        <span class="k">外 貌</span>
        <span class="v">黑长直 · 瓜子脸 · 凤眼薄唇</span>
      </div>
      <div class="profile-item">
        <span class="k">气 质</span>
        <span class="v">清冷疏离 · 生人勿近</span>
      </div>
      <div class="profile-item">
        <span class="k">身 材</span>
        <span class="v">巨乳 · 蜜桃臀 · 白丝长腿</span>
      </div>
      <div class="profile-item">
        <span class="k">夜间着装</span>
        <span class="v">宽大T恤 · 半透明蕾丝</span>
      </div>
      <div class="profile-item wide">
        <span class="k">性 格</span>
        <span class="v">表层冷淡理性，里层极度兄控、占有欲爆棚</span>
      </div>
      <div class="profile-item wide">
        <span class="k">语 言 风 格</span>
        <span class="v">白天极简冷淡（"嗯。""让开。"），夜间缠绵低语（"哥哥……是我……别醒。"）</span>
      </div>
    </div>

    <div class="desc-block">
      <b>【秘密】</b>她藏在衣柜夹层里有一个小本子，记录着每一次夜袭的日期、你的反应，以及那些绝不外传的细节。她从不让关系越过某条线，却又痴迷于在每个深夜把它推进到极致边缘。<br>
      <b>【执念】</b>她认为哥哥的一切只能属于自己。若白天看到你和别的女生说话，当晚的夜袭会变得格外沉默、也格外漫长。
    </div>
  </div>

  <!-- ===== 玩法 ===== -->
  <div class="card">
    <div class="sec-title"><span class="icon">◈</span>玩法机制</div>
    <div class="rules">
      <div class="rule">
        <div class="num">1</div>
        <div class="txt"><b>夜袭阶段：</b>潜入 → 侍奉 → 骑脸 → 口足 → 半插入 → 善后。每个夜晚会推进至其中若干阶段，节奏由她的心情与你的反应共同决定。</div>
      </div>
      <div class="rule">
        <div class="num">2</div>
        <div class="txt"><b>情动阈值：</b>她越投入，动作越缠绵、气声越失控。但无论多动情，她始终守住最后的底线。</div>
      </div>
      <div class="rule">
        <div class="num">3</div>
        <div class="txt"><b>清醒度：</b>你可以一直装睡，也可以在关键时刻突然睁眼或出声，观察她慌乱失态的真实反应。</div>
      </div>
      <div class="rule">
        <div class="num">4</div>
        <div class="txt"><b>底线博弈：</b>你越想突破边界，她越会夹紧大腿、停下动作，甚至用一两天的日间冷战来回应。</div>
      </div>
      <div class="rule">
        <div class="num">5</div>
        <div class="txt"><b>日间痕迹：</b>床单、枕边、晨间的气息，都是线索。白天她若无其事，可细微的破绽瞒不过你。</div>
      </div>
    </div>
  </div>
  <!-- ===== 玩家设定 ===== -->
  <div class="card">
    <div class="sec-title"><span class="icon">❂</span>玩家设定</div>
    <div class="form-grid">
      <div class="field">
        <label>姓名</label>
        <input type="text" id="pName" placeholder="例如：林默">
      </div>
      <div class="field">
        <label>年龄</label>
        <input type="text" id="pAge" placeholder="例如：18">
      </div>
      <div class="field">
        <label>性别</label>
        <input type="text" id="pGender" placeholder="男 / 女 / 其他">
      </div>
      <div class="field">
        <label>外貌</label>
        <input type="text" id="pLook" placeholder="例如：清瘦高个 · 碎发 · 单眼皮">
      </div>
      <div class="field wide">
        <label>肉棒设定</label>
        <textarea id="pSize" placeholder="尺寸、形状、敏感度、特殊反应……（自由格式，越具体越好）"></textarea>
      </div>
      <div class="field wide">
        <label>其他设定</label>
        <textarea id="pOther" placeholder="身份、性格、习惯、与妹妹的关系细节、隐藏设定、底线态度……"></textarea>
      </div>
    </div>


  <!-- ===== 开场白 ===== -->
  <div class="card">
    <div class="sec-title"><span class="icon">❀</span>开场白 · 选择一个开局</div>
    <div class="opening-list" id="openingList">
      <div class="opening" data-idx="1">
        <span class="idx">1</span>半夜一阵细碎窸窣和床垫下陷把你弄醒。黑暗中清甜洗发水香气逼近，一只微凉的手从背后环住你的腰，耳垂被含进温热唇间，她贴在你耳边气声呢喃：“哥……我来了。”
      </div>
      <div class="opening" data-idx="2">
        <span class="idx">2</span>凌晨的月光从窗帘缝漏进来。你感觉到脸上一片柔软、湿漉漉的温热缓缓摩擦着嘴唇，舌尖尝到一点甜腻。身上的重量很轻，是她的气息，她正居高临下地看着你，长发垂落满脸。
      </div>
      <div class="opening" data-idx="3">
        <span class="idx">3</span>你的睡裤被一只丝滑微凉的脚掌从腰间挑开。黑暗中，纯白丝袜在月光下泛着微光，它的主人背对着你跨坐在你胸口，一手撑着床、一手捂着嘴。不远处传来压抑而黏腻的水声，一下一下。
      </div>
      <div class="opening" data-idx="4">
        <span class="idx">4</span>你梦见自己在吃一颗不断融化、极软的糖，舌尖被另一条柔软的舌头轻轻勾着，交换着温热。半梦醒地睁开眼睛，看到的是她那张近在咫尺、双颊绯红的瓜子脸——她正闭着眼睛，专注地把自己的唾液一点一点渡进你嘴里。
      </div>
      <div class="opening" data-idx="5">
        <span class="idx">5</span>你的呼吸被打乱。黑暗中，能感觉到那对饱满的柔软正隔着T恤一下一下压过你的小腹。她骑在你腰上，一只手撑在你胸口，另一只手传来布料被轻轻掀开的细微声响——你知道，这个夜晚才刚刚开始。
      </div>
    </div>

    <div class="custom-box">
      <div class="lbl">自定义开场白</div>
      <textarea id="customOpening" placeholder="写下你想让她在今晚以哪种方式登场……（填写后将优先使用自定义内容）"></textarea>
    </div>
  </div>

    <div class="gen-wrap">
      <button class="gen-btn" id="genBtn">✦ 生 成 ✦</button>
    </div>
  </div>


  <!-- ===== 总结区 ===== -->
  <div class="summary" id="summary">
    <div class="summary-head">
      <span class="dot"></span>总结区 · SUMMARY
    </div>
    <div class="summary-body" id="summaryBody">
      <div class="sum-empty">还没有生成任何内容……<br>填写上方设定、选择开场白后，点击「生成」。</div>
    </div>

    <div class="copy-wrap">
      <button class="copy-btn" id="copyBtn"><span class="ic">⧉</span>一键复制</button>
    </div>
  </div>

  <div class="footer">
    M I D N I G H T &nbsp;·&nbsp; A C C O M P L I C E<br>
    <span style="letter-spacing:1px;">— 只有你们两个懂的夜晚 —</span>
  </div>

</div>

<script>
(function(){
  var openings = document.querySelectorAll(''.opening'');
  var selectedIdx = -1;
  var customTa = document.getElementById(''customOpening'');
  var genBtn = document.getElementById(''genBtn'');
  var summaryBody = document.getElementById(''summaryBody'');
  var copyBtn = document.getElementById(''copyBtn'');
  var copiedText = '''';

  // 选择开场白
  openings.forEach(function(el){
    el.addEventListener(''click'', function(){
      var idx = parseInt(el.getAttribute(''data-idx''), 10);
      if(selectedIdx === idx){
        selectedIdx = -1;
        el.classList.remove(''sel'');
      } else {
        openings.forEach(function(o){ o.classList.remove(''sel''); });
        selectedIdx = idx;
        el.classList.add(''sel'');
        // 清空自定义，避免冲突
        customTa.value = '''';
      }
    });
  });

  // 输入自定义时清空选择
  customTa.addEventListener(''input'', function(){
    if(customTa.value.trim() !== ''''){
      selectedIdx = -1;
      openings.forEach(function(o){ o.classList.remove(''sel''); });
    }
  });

  // 获取开场白文本
  function getOpeningText(){
    var custom = customTa.value.trim();
    if(custom) return custom;
    if(selectedIdx > 0){
      var el = document.querySelector(''.opening[data-idx="'' + selectedIdx + ''"]'');
      if(el){
        var clone = el.cloneNode(true);
        var idxEl = clone.querySelector(''.idx'');
        if(idxEl) idxEl.parentNode.removeChild(idxEl);
        return clone.innerText.replace(/\s+/g, '' '').trim();
      }
    }
    return '''';
  }

  // 转义
  function esc(s){
    return String(s).replace(/[&<>"'']/g, function(m){
      return {''&'':''&amp;'',''<'':''&lt;'',''>'':''&gt;'',''"'':''&quot;'',"''":''&#39;''}[m];
    });
  }

  // 生成
  genBtn.addEventListener(''click'', function(){
    var name   = document.getElementById(''pName'').value.trim();
    var age    = document.getElementById(''pAge'').value.trim();
    var gender = document.getElementById(''pGender'').value.trim();
    var look   = document.getElementById(''pLook'').value.trim();
    var size   = document.getElementById(''pSize'').value.trim();
    var other  = document.getElementById(''pOther'').value.trim();
    var opening = getOpeningText();

    if(!opening){
      summaryBody.innerHTML = ''<div class="sum-empty">请先选择一个开场白，或在下方填写自定义开场白。</div>'';
      return;
    }

    var vName   = name   || ''（未填写）'';
    var vAge    = age    || ''（未填写）'';
    var vGender = gender || ''（未填写）'';
    var vLook   = look   || ''（未填写）'';
    var vSize   = size   || ''（未填写）'';
    var vOther  = other  || ''（未填写）'';

    var html = '''';
    html += ''<div class="sum-block">'';
    html += ''<div class="st">◈ 玩 家 设 定</div>'';
    html += ''<div class="sv">'';
    html += ''<span class="kv">姓名：</span>'' + esc(vName) + ''\n'';
    html += ''<span class="kv">年龄：</span>'' + esc(vAge) + ''\n'';
    html += ''<span class="kv">性别：</span>'' + esc(vGender) + ''\n'';
    html += ''<span class="kv">外貌：</span>'' + esc(vLook) + ''\n'';
    html += ''<span class="kv">肉棒：</span>'' + esc(vSize) + ''\n'';
    html += ''<span class="kv">其他：</span>'' + esc(vOther);
    html += ''</div></div>'';

    html += ''<div class="sum-block">'';
    html += ''<div class="st">❀ 开 场 白</div>'';
    html += ''<div class="sv">'' + esc(opening) + ''</div>'';
    html += ''</div>'';

    summaryBody.innerHTML = html;

    copiedText = ''【玩家设定】\n''
      + ''姓名：'' + vName + ''\n''
      + ''年龄：'' + vAge + ''\n''
      + ''性别：'' + vGender + ''\n''
      + ''外貌：'' + vLook + ''\n''
      + ''肉棒：'' + vSize + ''\n''
      + ''其他：'' + vOther + ''\n\n''
      + ''【开场白】\n'' + opening;

    // 生成后滚动到总结区
    try{
      document.getElementById(''summary'').scrollIntoView({behavior:''smooth'', block:''center''});
    }catch(e){
      document.getElementById(''summary'').scrollIntoView();
    }
  });

  // 复制
  copyBtn.addEventListener(''click'', function(){
    if(!copiedText){
      copiedText = summaryBody.innerText.replace(/\n{3,}/g, ''\n\n'').trim();
    }
    if(!copiedText) return;

    if(navigator.clipboard && navigator.clipboard.writeText){
      navigator.clipboard.writeText(copiedText).then(showCopied).catch(function(){
        fallbackCopy(copiedText);
      });
    } else {
      fallbackCopy(copiedText);
    }
  });

  function fallbackCopy(text){
    var ta = document.createElement(''textarea'');
    ta.value = text;
    ta.style.position = ''fixed'';
    ta.style.top = ''0'';
    ta.style.left = ''0'';
    ta.style.opacity = ''0'';
    document.body.appendChild(ta);
    ta.focus();
    ta.select();
    try{ document.execCommand(''copy''); showCopied(); }catch(e){}
    document.body.removeChild(ta);
  }

  function showCopied(){
    copyBtn.classList.add(''copied'');
    var old = copyBtn.innerHTML;
    copyBtn.innerHTML = ''<span class="ic">✓</span>已复制到剪贴板'';
    setTimeout(function(){
      copyBtn.classList.remove(''copied'');
      copyBtn.innerHTML = old;
    }, 1800);
  }
})();
</script>

</body>
</html>', '都市', '2026-09-16 11:22:22', '2026-09-16 11:22:22', '', '', '[]', '') ON CONFLICT (id) DO NOTHING;
INSERT INTO stories (id, title, badge, cover_icon, cover_title, cover_subtitle, logo, theme_color, btn_gradient, handbook_json, roles_json, scenes_json, styles_json, first_turn_demo_json, custom_css, custom_html, category, created_at, updated_at, system_prompt, status_template, lorebook_json, post_history_instructions) VALUES ('deck_daughter_door_block', '老爸你想出门上班必须先操我一下。调皮的女儿用自己的身体堵门。', '都市禁断 · 傲娇堵门', '🚪', '调皮女儿身体堵门', '娇憨争宠·上班前夕的禁断推拉', 'https://catai.wiki/793f4e3c-83ed-430e-40c3-a9400a5e3f00/cover', 'bg-amber-950/90 text-orange-200 border-orange-500/50', 'from-rose-500 to-amber-600', '{"title": "老爸你想出门上班必须先操我一下。调皮的女儿用自己的身体堵门。", "desc": "我的女儿特别黏人，从小就喜欢缠着我跟我撒娇，而且她嫉妒心强，甚至她连她的妈妈都嫉妒。不知道是不是哪次我和媳妇做爱被她发现了还是怎么，她甚至觉得我只跟媳妇做爱是不爱她的表现，跟她解释她也不听。某天，我着急忙慌的要去上班，女儿一直黏着我缠着我跟我撒娇，不让我上班，让我在家陪她。我耐心的跟她解释说班还是要上的，没想到这个小祖宗直接把脚搭在门把上张开腿挡住了门口，气冲冲的对我说，老爸你老是跟妈妈搂搂抱抱的，都不抱我，如果你今天不不像对妈妈那样也抱我，就不准出门上班。这不是逼着我做一个禽兽吗，可恶。\n（撞墙别慌，刷新出奇迹。）", "bg_image": "https://catai.wiki/793f4e3c-83ed-430e-40c3-a9400a5e3f00/cover", "opening_options": ["【生成初始剧情】：进入调皮女儿赤脚堵门的名场面开局", "【温和宠溺】：揉揉女儿的小脑袋，无奈苦笑哄她让路", "【板起脸严肃】：冷哼一声严厉训诫，吓唬要动用家法", "【顺水推舟·试探】：上前一步反手将她按在门上低声耳语"]}', '[{"name": "林可可", "role": "调皮黏人的大一女儿", "desc": "19岁，大一新生。清纯甜美的娃娃脸，身材玲珑曼妙。极度依恋父亲，占有欲极强，因吃妈妈的醋而在玄关用娇躯死死堵门，不准父亲出门上班。"}, {"name": "林婉清", "role": "温柔贤惠的妻子", "desc": "40岁，温柔端庄的贤妻良母，正在厨房里哼着歌准备早餐，对玄关处的暧昧对峙浑然不知。"}]', '[{"title": "玄关防盗门前 · 晨光熹微的上班前夕", "desc": "清晨八点，阳光透过百叶窗洒在木地板上。厨房里传来煎蛋滋滋作响的声音，而玄关防盗门前，身穿超短睡裙的女儿正赤着一双晶莹剔透的小脚横搭在门锁上，气鼓鼓地张开双臂挡住出路。"}]', '{"dialogue_style": "都市家庭禁断伦理拉扯，极具张力与占有欲的互动对白，细腻肢体描写", "format": "AI风月标准双栏规范"}', '[{"index": 1, "isUser": false, "scene": "玄关防盗门前 · 晨光熹微的上班前夕", "story": "<tl>📅时间：清晨 07:55 | 🏠地点：自家公寓玄关防盗门前 | 🍳环境：厨房传来妻子做早餐的声响</tl>\n\n<article>\n<p>手表的指针已经指向七点五十五分，你拎着公文包，急匆匆地系上领带正准备换鞋推门。然而还没等你的手指碰到门把手，一道娇小纤细的身影便如同小旋风般横插过来，直接整个人贴在了厚重的防盗门板上。</p>\n\n<p>女儿林可可身上只穿着一件极为宽松的粉白条纹丝绸睡裙，裙摆堪堪垂到大腿根部。她白嫩修长的一双小腿肆无忌惮地横抬起来，光洁粉嫩的脚趾直接踩在金属门把锁扣上，将整个门严丝合缝地堵了个彻底。晨光透过玄关照在她未施粉黛却吹弹可破的俏脸上，两颊因为气愤而鼓起，胸口随着急促的呼吸一阵阵起伏。</p>\n\n<p><w>“老爸！你今天要是敢推开门走出去一步试试看！”</w></p>\n\n<p>她仰着那张精致漂亮的小脸，一双水汪汪的大眼睛里盛满了委屈与霸道：</p>\n<p><w>“昨晚我都看到了……你回房之后就跟妈妈搂搂抱抱的，亲了她好多次！从小到大你都说最疼我，结果现在碰都不让我碰！你今天如果不像抱妈妈那样好好抱我亲我，我就死死卡在门上，让你上班迟到被扣光全勤！”</w></p>\n\n<p>不远处厨房里传来油锅滋滋的煎蛋声，妻子林婉清温柔的声音隐隐飘来：“老公，早餐马上就好啦，你公文包收拾好了吗？”</p>\n\n<p><thk>眼前的女儿任性又娇憨，赤裸的双腿近在咫尺，厨房里的妻子随时可能端着餐盘走出来……</thk></p>\n</article>\n\n<opt>\n<suggested_questions>\n<d>A. 【温和宠溺·苦笑安抚】：无奈地叹了口气，伸手揉了揉她柔软的发丝：“可可别闹，爸爸今天有个涉及季度考评的重要晨会。听话先把腿放下来，晚上爸爸一下班就带你去吃你最喜欢的日料，好不好？”【策略评估：以父亲的宽厚包容化解危机，维持正常的亲情距离】</d>\n<d>B. 【严厉威严·板脸震慑】：收敛笑容，神色冷峻地看着她：“把脚给我放下来！越来越没大没小了，在家里堵门威胁起父亲来了？真当爸爸不会拿家法收拾你？”【策略评估：树立严父权威，逼迫她退缩，但可能激起更强烈的叛逆与委屈】</d>\n<d>C. 【顺水推舟·欺身逼近】：放下公文包，上前一步两手撑在门板两侧将她牢牢禁锢在怀中，低下头贴着她滚烫的小耳朵沉声低语：“小丫头，知不知道自己在说什么？你以为爸爸真的不敢动你？”【策略评估：打破道德防线，顺着她的争宠挑衅进行危险的肢体推拉】</d>\n<d>D. 【心惊胆战·假装应付】：眼神紧张地瞥了一眼厨房方向，迅速俯身飞快地在她软嫩的脸颊上亲了一口，小声催促：“亲了亲了！赶紧让开，要是被你妈妈看见了像什么样子！”【策略评估：仓促妥协满足她的部分要求，暂时化解迟到危机】</d>\n</suggested_questions>\n</opt>", "branches": [{"tag": "A", "title": "温和宠溺苦笑安抚", "desc": "揉揉发丝温和哄劝，承诺晚上下班带她吃大餐"}, {"tag": "B", "title": "严厉威严立规矩", "desc": "板起脸训斥女儿不懂规矩，以严父威严施压"}, {"tag": "C", "title": "顺水推舟欺身禁锢", "desc": "撑在门板上将她圈在怀中，贴着耳根进行危险反撩"}, {"tag": "D", "title": "慌忙偷亲应付过关", "desc": "戒备厨房妻子动静，匆忙在女儿脸上亲一口促其让路"}]}]', '', '<!DOCTYPE html>
<html lang="zh-CN">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>幻境织网者 - 角色与剧情设定生成器</title>
    <link href="https://fonts.googleapis.com/css2%sfamily=Noto+Serif+SC:wght@400;600;900&family=Noto+Sans+SC:wght@300;400;500;700&display=swap" rel="stylesheet">
    <style>
        :root {
            --bg-color: #fff8f0;
            --card-bg: #ffffff;
            --card-border: #ffe9d6;
            --accent-primary: #ff6b9d;
            --accent-secondary: #a66cff;
            --accent-highlight: #4d96ff;
            --accent-sun: #ffc53d;
            --accent-mint: #52b788;
            --text-main: #5a4a42;
            --text-sub: #9c8f86;
            --input-bg: #fffbf5;
            --input-border: #ffe6d0;
            --radius-md: 14px;
            --radius-lg: 24px;
            --shadow-soft: 0 10px 30px rgba(255, 175, 130, 0.18);
        }

        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }

        body {
            font-family: ''Noto Sans SC'', sans-serif;
            background-color: var(--bg-color);
            color: var(--text-main);
            line-height: 1.7;
            min-height: 100vh;
            overflow-x: hidden;
        }

        .container {
            max-width: 1100px;
            margin: 0 auto;
            padding: 40px 20px;
        }

        header {
            text-align: center;
            margin-bottom: 40px;
        }

        header h1 {
            font-family: ''Noto Serif SC'', serif;
            font-size: 2.9em;
            font-weight: 900;
            background: linear-gradient(135deg, #ff7a5c 0%, #ff6b9d 50%, #a66cff 100%);
            -webkit-background-clip: text;
            -webkit-text-fill-color: transparent;
            margin-bottom: 12px;
            letter-spacing: 3px;
        }

        header p {
            color: var(--text-sub);
            font-size: 1.1em;
            font-weight: 500;
        }

        .main-card {
            background: var(--card-bg);
            border: 2px solid var(--card-border);
            border-radius: var(--radius-lg);
            padding: 35px;
            box-shadow: var(--shadow-soft);
            margin-bottom: 30px;
        }

        .section-title {
            display: flex;
            align-items: center;
            gap: 12px;
            font-family: ''Noto Serif SC'', serif;
            font-size: 1.45em;
            font-weight: 900;
            color: #5a4a42;
            margin-bottom: 22px;
        }

        .title-icon {
            display: inline-flex;
            align-items: center;
            justify-content: center;
            width: 46px;
            height: 46px;
            border-radius: 15px;
            font-size: 1.25em;
            flex-shrink: 0;
            box-shadow: 0 4px 12px rgba(255, 150, 120, 0.22);
        }
        .title-icon.pink { background: linear-gradient(135deg, #ffd3e0, #ffe9f0); }
        .title-icon.blue { background: linear-gradient(135deg, #cde8ff, #e8f4ff); }
        .title-icon.sun { background: linear-gradient(135deg, #fff3cd, #ffe9b3); }

        .form-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
            gap: 18px;
            margin-bottom: 22px;
        }

        .form-group {
            display: flex;
            flex-direction: column;
            gap: 6px;
        }

        .form-group.full-width {
            grid-column: 1 / -1;
        }

        label {
            font-size: 0.95em;
            font-weight: 600;
            color: #6b5b52;
        }

        label span {
            color: var(--accent-secondary);
            font-size: 0.82em;
            font-weight: 500;
            margin-left: 4px;
        }

        input, textarea {
            background-color: var(--input-bg);
            border: 2px solid var(--input-border);
            border-radius: var(--radius-md);
            padding: 10px 12px;
            color: var(--text-main);
            font-family: inherit;
            font-size: 0.95em;
            transition: all 0.25s ease;
        }

        select {
            background-color: var(--input-bg);
            border: 2px solid var(--input-border);
            border-radius: var(--radius-md);
            padding: 10px 38px 10px 12px;
            color: var(--text-main);
            font-family: inherit;
            font-size: 0.95em;
            font-weight: 600;
            cursor: pointer;
            width: 100%;
            appearance: none;
            -webkit-appearance: none;
            background-image: url("data:image/svg+xml;charset=UTF-8,%3csvg xmlns=''http://www.w3.org/2000/svg'' width=''14'' height=''14'' viewBox=''0 0 24 24'' fill=''none'' stroke=''%23ff6b9d'' stroke-width=''3'' stroke-linecap=''round'' stroke-linejoin=''round''%3e%3cpolyline points=''6 9 12 15 18 9''%3e%3c/polyline%3e%3c/svg%3e");
            background-repeat: no-repeat;
            background-position: right 12px center;
            background-size: 14px;
            transition: all 0.25s ease;
        }

        select:focus {
            outline: none;
            border-color: var(--accent-primary);
            box-shadow: 0 0 0 4px rgba(255, 107, 157, 0.14);
            background-color: #ffffff;
        }

        input::placeholder, textarea::placeholder {
            color: #bfb2a8;
            opacity: 1;
        }

        input:focus, textarea:focus {
            outline: none;
            border-color: var(--accent-primary);
            box-shadow: 0 0 0 4px rgba(255, 107, 157, 0.14);
            background-color: #ffffff;
        }

        textarea {
            resize: vertical;
            min-height: 70px;
        }

        /* 角色卡片 */
        .character-card {
            background: var(--card-bg);
            border: 2px solid var(--card-border);
            border-radius: 18px;
            padding: 16px 18px;
            box-shadow: 0 6px 18px rgba(255, 175, 130, 0.12);
            margin-bottom: 14px;
            transition: box-shadow 0.3s ease, transform 0.3s ease;
        }
        .character-card:hover {
            transform: translateY(-2px);
            box-shadow: 0 14px 30px rgba(255, 175, 130, 0.22);
        }

        .character-header {
            display: flex;
            justify-content: space-between;
            align-items: center;
            margin-bottom: 10px;
        }

        .character-card .form-grid {
            grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
            gap: 12px;
            margin-bottom: 0;
        }

        .character-badge {
            font-size: 0.95em;
            font-weight: 800;
            color: #ffffff;
            background: linear-gradient(135deg, #ff6b9d, #ff9a5c);
            padding: 4px 14px;
            border-radius: 999px;
            box-shadow: 0 4px 10px rgba(255, 107, 157, 0.3);
        }

        .btn-remove-character {
            border: 2px solid #ffd3d3;
            background: #fff5f5;
            color: #e57373;
            padding: 4px 12px;
            border-radius: 999px;
            font-weight: 600;
            font-family: inherit;
            font-size: 0.82em;
            cursor: pointer;
            transition: all 0.2s;
        }
        .btn-remove-character:hover {
            background: #e57373;
            color: #ffffff;
            border-color: #e57373;
        }

        .btn-add-character {
            width: 100%;
            padding: 10px;
            border: 2px dashed #9be0b2;
            background: #f4fff7;
            color: #2f9e63;
            font-size: 0.95em;
            font-weight: 700;
            font-family: inherit;
            border-radius: 14px;
            cursor: pointer;
            transition: all 0.25s;
        }
        .btn-add-character:hover {
            background: #9be0b2;
            color: #ffffff;
            transform: translateY(-2px);
        }

        .btn-generate {
            display: flex;
            align-items: center;
            justify-content: center;
            width: 100%;
            padding: 17px;
            font-size: 1.2em;
            font-weight: 800;
            color: #ffffff;
            background: linear-gradient(135deg, #ff9a5c 0%, #ff6b9d 55%, #a66cff 120%);
            border: none;
            border-radius: 999px;
            cursor: pointer;
            transition: all 0.3s ease;
            box-shadow: 0 8px 24px rgba(255, 107, 157, 0.4);
            font-family: inherit;
        }

        .btn-generate:hover {
            transform: translateY(-3px);
            box-shadow: 0 12px 30px rgba(255, 107, 157, 0.5);
        }

        .btn-row {
            display: flex;
            flex-direction: column;
            gap: 14px;
            margin-top: 22px;
        }

        .btn-quick {
            width: 100%;
            padding: 15px;
            font-size: 1.05em;
            font-weight: 700;
            color: #2f9e63;
            background: linear-gradient(135deg, #eafaf0, #d5f5e0);
            border: 2px solid #9be0b2;
            border-radius: 999px;
            cursor: pointer;
            font-family: inherit;
            transition: all 0.25s;
        }

        .btn-quick:hover {
            background: linear-gradient(135deg, #9be0b2, #6bcb77);
            color: #ffffff;
            transform: translateY(-2px);
        }

        /* 使用说明 */
        .flow-hint {
            background: linear-gradient(135deg, #fff3e0, #ffe9f0);
            border: 2px dashed #ffc9d6;
            border-radius: var(--radius-md);
            padding: 12px 16px;
            font-size: 0.95em;
            color: #8a5a52;
            margin-bottom: 24px;
            line-height: 1.7;
        }
        .flow-hint b { color: #ff6b9d; }

        /* 可点选玩法面板 */
        .options-panel {
            background: #fffbf5;
            border: 2px solid #ffe6d0;
            border-radius: 18px;
            padding: 18px 20px;
            margin-bottom: 26px;
        }
        .options-header {
            display: flex;
            justify-content: space-between;
            align-items: center;
            margin-bottom: 14px;
        }
        .options-title {
            font-weight: 800;
            font-size: 1.1em;
            color: #5a4a42;
        }
        .btn-reset {
            border: 2px solid #c9c2f5;
            background: #f4f2ff;
            color: #7c6ee8;
            padding: 5px 14px;
            border-radius: 999px;
            font-weight: 700;
            font-family: inherit;
            font-size: 0.85em;
            cursor: pointer;
            transition: all 0.2s;
        }
        .btn-reset:hover {
            background: #a66cff;
            color: #ffffff;
            border-color: #a66cff;
        }
        .option-group { margin-bottom: 14px; }
        .option-group:last-child { margin-bottom: 0; }
        .option-group-label {
            font-size: 0.9em;
            font-weight: 700;
            color: #6b5b52;
            margin-bottom: 8px;
        }
        .option-chips {
            display: flex;
            flex-wrap: wrap;
            gap: 10px;
        }
        .chip {
            border: 2px solid #ffd3b3;
            background: #fff7ef;
            color: #b07b5a;
            padding: 6px 16px;
            border-radius: 999px;
            font-size: 0.92em;
            font-weight: 600;
            font-family: inherit;
            cursor: pointer;
            transition: all 0.2s;
        }
        .chip:hover { transform: translateY(-1px); }
        .chip.active {
            background: linear-gradient(135deg, #ff9a5c, #ff6b9d);
            color: #ffffff;
            border-color: transparent;
            box-shadow: 0 4px 12px rgba(255, 107, 157, 0.35);
        }
        .option-desc {
            margin-top: 8px;
            font-size: 0.82em;
            color: #b39a90;
        }

        /* 模态弹窗 */
        .modal {
            display: none;
            position: fixed;
            z-index: 1000;
            left: 0;
            top: 0;
            width: 100%;
            height: 100%;
            background-color: rgba(95, 70, 60, 0.35);
            backdrop-filter: blur(6px);
            justify-content: center;
            align-items: center;
            padding: 20px;
        }

        .modal-content {
            background-color: #ffffff;
            border: 2px solid #ffe6d0;
            border-radius: var(--radius-lg);
            width: 100%;
            max-width: 750px;
            max-height: 85vh;
            display: flex;
            flex-direction: column;
            box-shadow: 0 20px 60px rgba(255, 120, 90, 0.28);
            animation: modalFadeIn 0.3s ease;
        }

        @keyframes modalFadeIn {
            from { opacity: 0; transform: scale(0.95); }
            to { opacity: 1; transform: scale(1); }
        }

        .modal-header {
            padding: 20px 25px;
            border-bottom: 2px solid #ffefd2;
            display: flex;
            justify-content: space-between;
            align-items: center;
        }

        .modal-header h3 {
            color: var(--accent-primary);
            font-size: 1.3em;
            font-weight: 800;
        }

        .close-btn {
            background: none;
            border: none;
            color: var(--text-sub);
            font-size: 1.5em;
            cursor: pointer;
            transition: color 0.2s;
        }

        .close-btn:hover {
            color: #ff6b9d;
        }

        .modal-body {
            padding: 20px 25px;
            overflow-y: auto;
            flex: 1;
        }

        #prompt-output {
            width: 100%;
            min-height: 320px;
            background-color: #fff7ef;
            border: 2px solid #ffe6d0;
            border-radius: var(--radius-md);
            padding: 15px;
            color: #5a4a42;
            font-family: ''Courier New'', Courier, monospace;
            font-size: 0.9em;
            line-height: 1.6;
            white-space: pre-wrap;
            word-break: break-all;
            resize: vertical;
            outline: none;
        }
        #prompt-output:focus {
            border-color: var(--accent-primary);
            box-shadow: 0 0 0 4px rgba(255, 107, 157, 0.14);
        }

        .modal-footer {
            padding: 15px 25px;
            border-top: 2px solid #ffefd2;
            display: flex;
            justify-content: flex-end;
            gap: 15px;
        }

        .btn-copy {
            background: linear-gradient(135deg, #52b788 0%, #2f9e63 100%);
            color: #ffffff;
            border: none;
            padding: 10px 24px;
            border-radius: 999px;
            font-weight: 700;
            font-family: inherit;
            font-size: 0.95em;
            cursor: pointer;
            transition: all 0.2s;
        }

        .btn-copy:hover {
            background: linear-gradient(135deg, #2f9e63 0%, #1f8a54 100%);
            transform: translateY(-2px);
        }

        /* 底部与推广区域 */
        .footer {
            margin-top: 40px;
            text-align: center;
            border-top: 2px dashed #ffe6d0;
            padding-top: 25px;
            color: var(--text-sub);
            font-size: 0.95em;
        }

        .footer a {
            color: var(--accent-primary);
            text-decoration: none;
            font-weight: 700;
            transition: all 0.3s;
        }

        .footer a:hover {
            color: var(--accent-secondary);
            text-decoration: underline;
        }

    /* ========== 移动端适配 ========== */
        @media (max-width: 768px) {
            .container {
                padding: 20px 14px;
            }

            header h1 {
                font-size: 1.5em;
                letter-spacing: 1px;
                line-height: 1.4;
                margin-bottom: 8px;
            }

            header p {
                font-size: 0.95em;
            }

            .main-card {
                padding: 20px 14px;
                border-radius: 18px;
                margin-bottom: 20px;
            }

            .section-title {
                font-size: 1.2em;
                gap: 10px;
                margin-bottom: 16px;
            }

            .title-icon {
                width: 38px;
                height: 38px;
                font-size: 1.05em;
                border-radius: 12px;
            }

            .form-grid {
                gap: 14px;
                margin-bottom: 16px;
            }

            input, textarea, select {
                font-size: 1em;
                -webkit-appearance: none;
                appearance: none;
            }

            label {
                font-size: 0.92em;
            }

            .character-card {
                padding: 14px 12px;
                margin-bottom: 14px;
            }

            .character-card .form-grid {
                grid-template-columns: 1fr;
                gap: 14px;
            }

            .character-badge {
                font-size: 0.88em;
                padding: 4px 12px;
            }

            .btn-remove-character {
                padding: 4px 10px;
                font-size: 0.78em;
            }

            .btn-add-character {
                font-size: 0.92em;
            }

            .flow-hint {
                font-size: 0.92em;
                padding: 12px 14px;
            }

            .options-panel {
                padding: 14px;
            }

            .options-header {
                gap: 10px;
            }

            .options-title {
                font-size: 1em;
            }

            .option-chips {
                gap: 8px;
            }

            .chip {
                font-size: 0.88em;
                padding: 6px 13px;
            }

            .btn-generate {
                padding: 14px;
                font-size: 1.05em;
            }

            .btn-quick {
                padding: 13px;
                font-size: 1em;
            }

            .modal {
                padding: 12px;
                align-items: flex-end;
            }

            .modal-content {
                max-height: 92vh;
                border-radius: 20px 20px 0 0;
            }

            .modal-header {
                padding: 16px 18px;
            }

            .modal-header h3 {
                font-size: 1.15em;
            }

            .modal-body {
                padding: 16px 18px;
            }

            .modal-footer {
                padding: 12px 18px;
            }

            .btn-copy {
                width: 100%;
                text-align: center;
            }

            .footer {
                font-size: 0.85em;
                margin-top: 28px;
            }
        }

        @media (max-width: 480px) {
            .container {
                padding: 14px 10px;
            }

            header {
                margin-bottom: 24px;
            }

            .main-card {
                padding: 16px 12px;
            }

            .form-grid {
                grid-template-columns: 1fr;
            }
        }

    </style>
</head>
<body>

<div class="container">
    <header>
        <h1>调皮的女儿用自己的身体堵门</h1>
    </header>

    <div class="main-card">
        <!-- 使用说明 -->
        <div class="flow-hint">
            <b>玩法说明：</b>选主角风格 → 改剧情（可以不改）→ 设定角色（可增加角色） → 一键复制发给AI当第一条消息，生成初始剧情。
            懒汉玩法-直接点击上方生成初始剧情，或者拖到最后点击懒得填表，总之直接发送“生成初始剧情”就可以。
        </div>
      
        <!-- 可点选属性 -->
        <div class="options-panel">
            <div class="options-header">
                <span class="options-title">⚙️ 玩法风格</span>
                <button type="button" class="btn-reset" onclick="resetAll()">↺ 回全默认</button>
            </div>
            <div class="option-group">
                <div class="option-group-label">男主风格</div>
                <div class="option-chips" id="chips-style">
                    <button type="button" class="chip active" data-default="true" data-value="温和宠溺型——体贴入微、包容纵容，主角最爱被黏" onclick="selectChip(this, ''chips-style'')">温和宠溺</button>
                    <button type="button" class="chip" data-value="闷骚正经型——看似正经，内心骚气" onclick="selectChip(this, ''chips-style'')">闷骚正经</button>
                    <button type="button" class="chip" data-value="高冷反差型——表面冷淡，内心炽热，反差拉满" onclick="selectChip(this, ''chips-style'')">高冷反差</button>
                    <button type="button" class="chip" data-value="懒散随和型——随性自在，越随意越好笑" onclick="selectChip(this, ''chips-style'')">懒散随和</button>
                </div>
                <div class="option-desc">说明：温和宠溺=温和纯爱 · 闷骚正经=假证据 · 高冷反差=打反差 · 懒散=随意搞笑</div>
            </div>
            <div class="option-group">
                <div class="option-group-label">暧昧程度</div>
                <div class="option-chips" id="chips-romance">
                    <button type="button" class="chip active" data-default="true" data-value="全开——感情线全力展开，走色情刺激路线" onclick="selectChip(this, ''chips-romance'')">全开</button>
                    <button type="button" class="chip" data-value="纯爱——全程暧昧+剧情，用爱感化" onclick="selectChip(this, ''chips-romance'')">纯爱</button>
                </div>
                <div class="option-desc">说明：全开=没有顾忌 · 纯爱=全程暧昧+剧情</div>
            </div>
        </div>

        <!-- 剧情大纲与开局场景 -->
        <div class="section-title">
            <span class="title-icon blue">📖</span>
            剧情大纲与开局场景
        </div>
        <div class="form-grid">
            <div class="form-group full-width">
                <label for="plot-outline">剧情大纲与开局场景</label>
                <textarea id="plot-outline" rows="4" data-default="生成初始剧情" placeholder="我的女儿特别黏人，从小就喜欢缠着我跟我撒娇，而且她嫉妒心强，甚至她连她的妈妈都嫉妒。不知道是不是哪次我和媳妇做爱被她发现了还是怎么，她甚至觉得我只跟媳妇做爱是不爱她的表现，跟她解释她也不听。某天，我着急忙慌的要去上班，女儿一直黏着我缠着我跟我撒娇，不让我上班，让我在家陪她。我耐心的跟她解释说班还是要上的，没想到这个小祖宗直接把脚搭在门把上张开腿挡住了门口，气冲冲的对我说，老爸你老是跟妈妈搂搂抱抱的，都不抱我，如果你今天不不像对妈妈那样也抱我，就不准出门上班。这不是逼着我做一个禽兽吗，可恶。"></textarea>
            </div>
        </div>

        <!-- 认知设定 -->
        <div class="section-title" style="margin-top: 34px;">
            <span class="title-icon sun">🧠</span>
            认知设定
        </div>
        <div class="form-grid">
            <div class="form-group full-width">
                <label for="plot-cognition">认知设定</label>
                <textarea id="plot-cognition" rows="4" data-default="爸爸不做那些事就是不爱我" placeholder="爸爸不做那些事就是不爱我（可修改，例如角色对主角的初始看法、世界运行规则等）"></textarea>
            </div>
        </div>

        <!-- 视角设定 -->
        <div class="section-title" style="margin-top: 34px;">
            <span class="title-icon blue">🎬</span>
            视角设定
        </div>
        <div class="form-grid">
            <div class="form-group">
                <label for="plot-pov">视角设定</label>
                <select id="plot-pov">
                    <option value="男性视角" selected>男性视角</option>
                    <option value="女性视角">女性视角</option>
                    <option value="第三方视角">第三方视角</option>
                </select>
            </div>
            <div class="form-group">
                <label for="plot-pov-custom">自定义视角 <span>（选填，填写后优先使用）</span></label>
                <input type="text" id="plot-pov-custom" placeholder="例如：上帝视角、反派第一人称视角等">
            </div>
        </div>

        <!-- 角色设定 -->
        <div class="section-title" style="margin-top: 34px;">
            <span class="title-icon pink">👧</span>
            角色属性设定
        </div>
        <div id="characters-container">
            <!-- 女友妈妈 -->
            <div class="character-card">
                <div class="character-header">
                    <span class="character-badge">女儿</span>
                    <button type="button" class="btn-remove-character" onclick="removeCharacter(this)">删除角色</button>
                </div>
                <div class="form-grid">
                    <div class="form-group">
                        <label for="char-name-1">姓名</label>
                        <input type="text" id="char-name-1" class="char-name" data-default="林晓晓" placeholder="林晓晓（可改成你喜欢的名字）">
                    </div>
                    <div class="form-group">
                        <label for="char-age-1">年龄</label>
                        <input type="text" id="char-age-1" class="char-age" data-default="14岁" placeholder="14岁（可修改年龄）">
                    </div>
                    <div class="form-group">
                        <label for="char-identity-1">身份职业</label>
                        <input type="text" id="char-identity-1" class="char-identity" data-default="学生" placeholder="学生（可修改身份职业）">
                    </div>
                    <div class="form-group">
                        <label for="char-relation-1">与主角关系</label>
                        <input type="text" id="char-relation-1" class="char-relation" data-default="父女" placeholder="父女（可修改）">
                    </div>
                    <div class="form-group">
                        <label for="char-personality-1">性格特点</label>
                        <input type="text" id="char-personality-1" class="char-personality" data-default="清纯可爱，嫉妒心强" placeholder="清纯可爱，嫉妒心强">
                    </div>
                    <div class="form-group">
                        <label for="char-appearance-1">外貌身材</label>
                        <input type="text" id="char-appearance-1" class="char-appearance" data-default="贫乳双马尾" placeholder="贫乳双马尾">
                    </div>
                    <div class="form-group full-width">
                        <label for="char-other-1">其他设定 <span>(背景 / 能力 / 动机等)</span></label>
                        <textarea id="char-other-1" class="char-other" data-default="对爸爸不跟自己亲近非常不满" placeholder="对爸爸不跟自己亲近非常不满"></textarea>
                    </div>
                </div>
            </div>

            <!-- 女友-->
            <div class="character-card">
                <div class="character-header">
                    <span class="character-badge">妻子</span>
                    <button type="button" class="btn-remove-character" onclick="removeCharacter(this)">删除角色</button>
                </div>
                <div class="form-grid">
                    <div class="form-group">
                        <label for="char-name-2">姓名</label>
                        <input type="text" id="char-name-2" class="char-name" data-default="林婉" placeholder="林婉可改成你喜欢的名字）">
                    </div>
                    <div class="form-group">
                        <label for="char-age-2">年龄</label>
                        <input type="text" id="char-age-2" class="char-age" data-default="35岁" placeholder="35岁（可修改年龄）">
                    </div>
                    <div class="form-group">
                        <label for="char-identity-2">身份职业</label>
                        <input type="text" id="char-identity-2" class="char-identity" data-default="家庭主妇" placeholder="家庭主妇">
                    </div>
                    <div class="form-group">
                        <label for="char-relation-2">与主角关系</label>
                        <input type="text" id="char-relation-2" class="char-relation" data-default="夫妻" placeholder="夫妻（可修改）">
                    </div>
                    <div class="form-group">
                        <label for="char-personality-2">性格特点</label>
                        <input type="text" id="char-personality-2" class="char-personality" data-default="温柔知性" placeholder="温柔知性">
                    </div>
                    <div class="form-group">
                        <label for="char-appearance-2">外貌身材</label>
                        <input type="text" id="char-appearance-2" class="char-appearance" data-default="成熟性感" placeholder="成熟性感">
                    </div>
                    <div class="form-group full-width">
                        <label for="char-other-2">其他设定 <span>(背景 / 能力 / 动机等)</span></label>
                        <textarea id="char-other-2" class="char-other" data-default="传统保守" placeholder="传统保守"></textarea>
                    </div>
                </div>
            </div>
        </div>
        <button type="button" class="btn-add-character" onclick="addCharacter()">＋ 添加角色</button>

        <div class="btn-row">
            <button class="btn-generate" onclick="generatePrompt()">✨ 生成开场指令并复制</button>
            <button class="btn-quick" onclick="quickStart()">🍃 懒得填表直接开始</button>
        </div>
    </div>

    <!-- 底部强制推广模块 -->
    <div class="footer">
        <a href="https://aiaha.xyz/zh/explore/installed/154ec914-e1dc-47db-8e99-61c745b25d8d%spreview=1" target="_blank">
            由风月作品一键生成工具协助生成。
        </a>
    </div>
</div>

<!-- 预览与复制模态框 -->
<div id="copyModal" class="modal">
    <div class="modal-content">
        <div class="modal-header">
            <h3>📜 初始提示词预览</h3>
            <button class="close-btn" onclick="closeModal()">&times;</button>
        </div>
        <div class="modal-body">
            <textarea id="prompt-output" spellcheck="false"></textarea>
        </div>
        <div class="modal-footer">
            <button class="btn-copy" onclick="executeCopy()">一键复制并开始游戏</button>
        </div>
    </div>
</div>

<script>
    const modal = document.getElementById(''copyModal'');

    function characterCardTemplate(index) {
        return `
        <div class="character-card">
            <div class="character-header">
                <span class="character-badge">角色 ${index}</span>
                <button type="button" class="btn-remove-character" onclick="removeCharacter(this)">删除角色</button>
            </div>
            <div class="form-grid">
                <div class="form-group">
                    <label for="char-name-${index}">姓名</label>
                    <input type="text" id="char-name-${index}" class="char-name" data-default="新角色" placeholder="新角色（可改成你喜欢的名字）">
                </div>
                <div class="form-group">
                    <label for="char-age-${index}">年龄</label>
                    <input type="text" id="char-age-${index}" class="char-age" data-default="年龄不详" placeholder="年龄不详（可修改年龄）">
                </div>
                <div class="form-group">
                    <label for="char-identity-${index}">身份职业</label>
                    <input type="text" id="char-identity-${index}" class="char-identity" data-default="身份职业待定" placeholder="身份职业待定（可修改身份职业）">
                </div>
                <div class="form-group">
                    <label for="char-relation-${index}">与主角关系</label>
                    <input type="text" id="char-relation-${index}" class="char-relation" data-default="与主角关系待定" placeholder="与主角关系待定（可修改）">
                </div>
                <div class="form-group">
                    <label for="char-personality-${index}">性格特点</label>
                    <input type="text" id="char-personality-${index}" class="char-personality" data-default="性格鲜明，待人热忱" placeholder="性格鲜明，待人热忱">
                </div>
                <div class="form-group">
                    <label for="char-appearance-${index}">外貌身材</label>
                    <input type="text" id="char-appearance-${index}" class="char-appearance" data-default="相貌出众，气质独特" placeholder="相貌出众，气质独特">
                </div>
                <div class="form-group full-width">
                    <label for="char-other-${index}">其他设定 <span>(背景 / 能力 / 动机等)</span></label>
                    <textarea id="char-other-${index}" class="char-other" data-default="身世背景与特殊能力尚待探索，正处于人生的重要转折期。" placeholder="身世背景与特殊能力尚待探索，正处于人生的重要转折期。"></textarea>
                </div>
            </div>
        </div>`;
    }

    function addCharacter() {
        const container = document.getElementById(''characters-container'');
        const index = container.querySelectorAll(''.character-card'').length + 1;
        container.insertAdjacentHTML(''beforeend'', characterCardTemplate(index));
    }

    function removeCharacter(btn) {
        const container = document.getElementById(''characters-container'');
        const cards = container.querySelectorAll(''.character-card'');
        if (cards.length <= 1) {
            alert(''至少保留一个角色哦～'');
            return;
        }
        btn.closest(''.character-card'').remove();
        updateCharacterNumbers();
    }

    function updateCharacterNumbers() {
        const cards = document.querySelectorAll(''.character-card'');
        cards.forEach((card, i) => {
            card.querySelector(''.character-badge'').textContent = ''角色 '' + (i + 1);
        });
    }

    function selectChip(chip, groupId) {
        const chips = document.querySelectorAll(''#'' + groupId + '' .chip'');
        chips.forEach(c => c.classList.remove(''active''));
        chip.classList.add(''active'');
    }

    function getSelectedChip(groupId) {
        const chip = document.querySelector(''#'' + groupId + '' .chip.active'');
        return chip %s chip.getAttribute(''data-value'') : '''';
    }

    function resetAll() {
        document.querySelectorAll(''.chip'').forEach(c => c.classList.remove(''active''));
        document.querySelectorAll(''.chip[data-default="true"]'').forEach(c => c.classList.add(''active''));
        document.querySelectorAll(''#characters-container input, #characters-container textarea'').forEach(el => el.value = '''');
        const plotEl = document.getElementById(''plot-outline'');
        if (plotEl) plotEl.value = '''';
        const cognitionEl = document.getElementById(''plot-cognition'');
        if (cognitionEl) cognitionEl.value = '''';
        const povEl = document.getElementById(''plot-pov'');
        if (povEl) povEl.selectedIndex = 0;
    }

    function generatePrompt() {
        const styleValue = getSelectedChip(''chips-style'');
        const romanceValue = getSelectedChip(''chips-romance'');

        const charCards = document.querySelectorAll(''.character-card'');
        // 字段类名 -> 提示词中显示的字段名
        const fieldDefs = [
            [''char-age'', ''年龄''],
            [''char-identity'', ''身份职业''],
            [''char-relation'', ''与主角关系''],
            [''char-personality'', ''性格特点''],
            [''char-appearance'', ''外貌身材''],
            [''char-other'', ''其他设定''],
        ];
        let charsText = '''';
        charCards.forEach((card, i) => {
            // 若对应字段被删除（DOM 中不存在），返回 null 表示跳过该字段
            const getVal = (cls) => {
                const el = card.querySelector(''.'' + cls);
                if (!el) return null;
                return el.value.trim() || el.dataset.default || '''';
            };
            const nameVal = getVal(''char-name'');
            const badgeEl = card.querySelector(''.character-badge'');
            const label = badgeEl %s badgeEl.textContent.trim() : (''角色'' + (i + 1));
            let charText = ''\n### '' + label;
            // 姓名字段存在时追加，不存在时只保留角色标签
            if (nameVal !== null && nameVal !== '''') {
                charText += ''：'' + nameVal;
            }
            const lines = [];
            fieldDefs.forEach((def) => {
                const val = getVal(def[0]);
                if (val !== null && val !== '''') {
                    lines.push(''- '' + def[1] + ''：'' + val);
                }
            });
            if (lines.length) {
                charText += ''\n'' + lines.join(''\n'');
            }
            charsText += charText;
        });

        const plotEl = document.getElementById(''plot-outline'');
        // 标题始终保留；删除标签 → 内容为空；存在但未填写 → 默认值；存在且已填写 → 用户输入
        let plotOutline = '''';
        if (plotEl) {
            const filled = plotEl.value.trim();
            plotOutline = filled || plotEl.dataset.default || '''';
        }

        // 认知设定：删除标签 → 内容为空；存在但未填写 → 默认值；存在且已填写 → 用户输入
        const cognitionEl = document.getElementById(''plot-cognition'');
        let cognition = '''';
        if (cognitionEl) {
            const filled = cognitionEl.value.trim();
            cognition = filled || cognitionEl.dataset.default || '''';
        }

        // 视角设定：下拉框，默认男性视角；删除标签 → 内容为空
        const povEl = document.getElementById(''plot-pov'');
        const povCustomEl = document.getElementById(''plot-pov-custom'');
        const povCustom = povCustomEl %s povCustomEl.value.trim() : '''';
        let pov = povCustom || (povEl %s povEl.value : '''');

        const generatedText = `
# 用户输入设定

## 【玩法设定】
- 角色类型：${styleValue}
- 暧昧程度：${romanceValue}

## 【剧情大纲与开局场景】
- ${plotOutline}

## 【认知设定】
- ${cognition}

## 【视角设定】
- ${pov}

## 【角色设定】${charsText}

---
### 【交互与回复规则】
1. 语言：使用简体中文输出，文字细腻生动，环境氛围与心理描写充实。
2. 每次回复需严格输出：
   - 📍【场景与时间状态】
   - 📖【正文描写】：推动情节发展，各角色依照自身性格、脾气做出真实鲜活的言行反应。不代控玩家的心理与决定。
   - 📝【记忆区】：记录所有对话的主要剧情，每轮对话提取主要关键词追加至上一轮（默认隐藏）。
   - 📊【状态栏】：记录用户设定视角、各角色的关键互动、好感变化及心理状态（默认隐藏）。
   - 🎲【行动分支选项】：根据用户设定的视角提供A、B、C、D及自由输入选项推动剧情。
现在请根据以上设定，直接输出第一幕精彩的初始剧情！
`.trim();

        document.getElementById(''prompt-output'').value = generatedText;
        modal.style.display = ''flex'';
    }

    function closeModal() {
        modal.style.display = ''none'';
    }

    function executeCopy() {
        copyToClipboard(document.getElementById(''prompt-output'').value, () => {
            alert(''🎉 设定Prompt已成功复制到剪贴板！现在可以直接粘贴给AI开启小说啦！'');
            closeModal();
        });
    }

    function quickStart() {
        const btn = document.querySelector(''.btn-quick'');
        copyToClipboard(''生成初始剧情'', () => {
            btn.textContent = ''✅ 就是，又不考研填啥表。直接把「生成初始剧情」扔给AI！'';
            
        });
    }

    function copyToClipboard(text, onSuccess) {
        const done = () => onSuccess();
        if (navigator.clipboard && window.isSecureContext) {
            navigator.clipboard.writeText(text).then(done).catch(() => fallbackCopy(text, done));
        } else {
            fallbackCopy(text, done);
        }
    }

    function fallbackCopy(text, onSuccess) {
        const textarea = document.createElement(''textarea'');
        textarea.value = text;
        textarea.style.position = ''fixed'';
        textarea.style.top = ''0'';
        textarea.style.left = ''0'';
        textarea.style.opacity = ''0'';
        document.body.appendChild(textarea);
        textarea.focus();
        textarea.select();
        try {
            const successful = document.execCommand(''copy'');
            if (successful) {
                onSuccess();
            } else {
                alert(''复制失败，请在预览窗口内全选手动复制。'');
            }
        } catch (err) {
            alert(''复制异常，请手动选中预览框文字进行复制。'');
        }
        document.body.removeChild(textarea);
    }

    window.onclick = function(event) {
        if (event.target === modal) {
            closeModal();
        }
    };
</script>

</body>
</html>
', '都市', '2026-09-21 16:45:44', '2026-09-21 16:45:44', '', '', '[]', '') ON CONFLICT (id) DO NOTHING;
INSERT INTO stories (id, title, badge, cover_icon, cover_title, cover_subtitle, logo, theme_color, btn_gradient, handbook_json, roles_json, scenes_json, styles_json, first_turn_demo_json, custom_css, custom_html, category, created_at, updated_at, system_prompt, status_template, lorebook_json, post_history_instructions) VALUES ('deck_mother_sister_baby', '成年了还把你当孩子的巨乳美母骚姐', '都市豪门 · 极致推拉', '👠', '巨乳美母骚姐', '超模姐姐·尤物母亲·大平层无防备同居', 'https://catai.wiki/0a9d1e66-a774-4a51-da39-63d5acba4c00/cover', 'bg-zinc-950/90 text-rose-200 border-rose-500/50', 'from-pink-600 to-rose-700', '{"title": "成年了还把你当孩子的巨乳美母骚姐", "desc": "你，刚满十八岁，高三毕业，手里攥着大学录取通知书，站在这个只有三口人的家里。\n你有一个让全校男生都嫉妒到发疯的姐姐——顾清颜。她是顶级模特，黑长直及腰，一双媚眼勾魂夺魄。身高172，九头身，那双大长腿能踩碎无数男人的自尊。她的嫩穴是娱乐圈传说的“极品粉穴”，只有少量精心修剪的阴毛点缀，干净又诱人。\n\n你还有一个让整条街的男人都垂涎的妈妈——沈韵。四十出头的顶级熟女，紫色波浪长发垂至腰间，皮肤白嫩得能掐出水。那对H罩杯的雪乳即便不穿内衣也傲然挺立，配上一手都包不住的巨乳和浑圆挺翘的肥臀，让她走到哪里都是焦点。自从你父亲五年前去世后，她再也没有过性生活，但你知道，她床头柜里的按摩棒已经换了好几根。她的阴毛浓密茂盛，是典型性欲旺盛的熟女象征。\n\n在这个只有你们三口人的家里，她们把你当成长不大的孩子。\n夏天在家里，姐姐会穿着你的旧T恤晃悠，下摆堪堪遮住大腿根部，稍微弯腰你就会看见她光滑无毛的私处。妈妈更是随意，洗完澡只裹一条浴巾就出来吹头发，浴巾松了也不在意。你早就习惯了早上起床时，发现妈妈不知什么时候钻进你的被窝，柔软温暖的巨乳贴着你的后背。\n\n直到那个夏夜。\n你热得睡不着，起床倒水。路过姐姐房间时，门虚掩着，里面传来压抑的轻喘和床板轻响。你鬼使神差地凑近门缝——\n顾清颜正躺在床上，修长的双腿大张着，一只手疯狂揉捏着自己的粉穴，另一只手抓着床单。她那双在T台上睥睨众生的媚眼此刻半闭着，满脸潮红，嘴里模糊地念着什么。\n你屏住呼吸，心脏快要跳出喉咙。下一秒，她猛然转头，目光直直撞上你的视线。\n空气凝固了。\n“出去——！！！”\n她的声音又羞又怒，一个枕头砸在门上。你仓皇逃回房间，心跳了一整夜。第二天早餐桌上，她全程低着头不说话，只有妈妈疑惑地看着你们：“你们俩今天怎么怪怪的？”\n这个家，好像有什么东西，开始不一样了。", "bg_image": "https://catai.wiki/f4a7a232-d9db-45d8-9a24-0802e357b800/bg", "opening_options": ["【撞见自慰后的清晨早餐】：餐桌前姐姐耳根泛红低头喝粥，试图掩盖昨夜的尴尬", "【妈妈的无防备晨浴】：洗完澡的沈韵只裹着一条薄浴巾，笑盈盈让你帮忙吹头发", "【姐姐房间的试探对峙】：趁妈妈出门敲开姐姐房门，送上一杯冰奶茶打破僵局", "【三人温馨的客厅日常】：靠在沙发上，一边是姐姐伸过来的美腿，一边是妈妈切好的水果"]}', '[{"name": "顾清颜", "role": "24岁 · 亲姐姐 · 顶级模特", "desc": "国内一线时尚大刊常客，及腰黑长直，身高172cm九头身，H罩杯极品粉穴。在T台上是高岭之花，在家穿着男士旧T恤懒散毒舌，极度爱面子。昨夜在卧室自慰被你意外撞破。"}, {"name": "沈韵", "role": "42岁 · 母亲 · 舞蹈老师", "desc": "守寡五年的顶级熟女，紫色波浪长发，H罩杯傲人雪乳，身材白嫩丰腴如三十许人。对你毫无防备，视照顾你为天性，在家习惯只裹单薄浴巾或轻薄睡衣走动。"}, {"name": "王阿姨", "role": "50岁 · 邻居 · 八卦担当", "desc": "爱串门的热心邻居，总会意味深长地感叹你们孤儿寡母大平层同居的微妙气氛。"}]', '[{"title": "高档大平层公寓客厅 · 昨夜风波后的清晨", "desc": "一线城市核心地段的三室两厅大平层。落地窗前晨光柔和，羊毛地毯上还散落着姐姐的时尚画报与母亲的瑜伽垫。空气中飘着热牛奶与烤吐司的甜香，但昨夜撞破的秘密让气氛变得微妙撩人。"}]', '{"dialogue_style": "现代都市家庭无防备沉浸体验，细腻视听感官描写，隐秘推拉与心照不宣的情感试探", "format": "AI风月标准双栏规范及.custom-ui样式"}', '[{"index": 1, "isUser": false, "scene": "高档大平层公寓客厅 · 昨夜风波后的清晨", "story": "<tl>📅时间：清晨 08:30 | 🏡地点：大平层公寓开放式厨房与餐桌 | ☀️天气：晴朗闷热的盛夏</tl>\n\n<article>\n<p>昨夜那声仓促羞愤的“出去”，以及枕头狠狠砸在门板上的闷响，在你耳边回荡了整整一夜。你顶着淡淡的黑眼圈坐在餐桌前，看着面前热气腾腾的燕麦粥，手里捏着的勺子迟迟没有送进嘴里。</p>\n\n<p>拖鞋踩在地板上的轻微声响传来，姐姐顾清颜从走廊走了出来。她依旧穿着你那件洗得有些褪色的大号白色旧T恤，宽大的领口微微倾斜，露出一大片莹白细腻的香肩与深邃的锁骨线条。T恤下摆堪堪遮到大腿根，九头身修长笔直的美腿在晨光下晃得人眼花。</p>\n\n<p>然而一向在家里眼高于顶、习惯使唤你跑腿的时尚超模，此刻却死死低着头。当她的视线在空中与你不经意撞上的那一刹那，她冷艳的丹凤眼骤然慌乱地移开，一抹滚烫的绯红瞬间从修长的天鹅颈蔓延到耳垂。</p>\n\n<p><w>“……看什么看，再看把你眼珠子挖出来。”</w></p>\n\n<p>她拉开椅子狠狠坐下，声音听起来凶巴巴的，但那微颤的尾音和死死攥着衣角的动作却完全出卖了她内心的羞耻与凌乱。</p>\n\n<p>正当尴尬的气氛在餐桌间无声蔓延时，主卧洗手间的玻璃门被哗啦推开。母亲沈韵擦着湿漉漉的紫色长发走了出来，身上仅仅裹着一条水粉色的浴巾，将那对沉甸甸的H罩杯雪乳挤压得呼之欲出，饱满的曲线随着步伐轻轻颤动：</p>\n<p><w>“清颜，儿子，你们俩今天怎么这么安静？快趁热把煎蛋吃了。儿子，吃完过来帮妈妈吹一下头发，后面妈妈手酸吹不到呢。”</w></p>\n\n<p><thk>这个家里原本理所当然的无防备日常，在昨夜的窥探之后，每一缕空气都变得灼热而危险……</thk></p>\n</article>\n\n<opt>\n<suggested_questions>\n<d>A. 【装作无事·主动给姐姐递果酱】：伸手拿起桌上的草莓果酱递到顾清颜面前，假装若无其事：“姐，你最爱的低糖果酱。昨晚……我起夜倒水太黑撞到头了，啥都没看见。”【策略评估：给出台阶试图缓和僵局，但此地无银三百两反而让姐姐更加羞赧敏感】</d>\n<d>B. 【转移视线·温顺回应妈妈】：立刻站起身接过母亲手里的电吹风，顺从笑道：“好啊妈，我这就帮您吹。您先坐沙发上别着凉了。”【策略评估：借照顾母亲逃离餐桌的死寂对视，享受熟女妈妈天然毫不设防的亲近】</d>\n<d>C. 【借机反客为主·眼神调侃姐姐】：靠在椅背上，嘴角勾起一抹玩味的笑意盯着顾清颜通红的耳朵：“姐，今早火气这么大？是不是昨晚一个人在房间里‘睡得不太安稳’？”【策略评估：主动挑破昨夜撞见自慰的暗流，将高傲的超模姐姐逼入防守羞愤的境地】</d>\n<d>D. 【低头闷声喝粥·当安静透明人】：默默把脸埋进碗里飞速扒粥，祈祷这场随时可能引爆的修罗场快点结束【策略评估：以不变应万变，暗中观察姐姐与母亲神态细微的互动变化】</d>\n</suggested_questions>\n</opt>", "branches": [{"tag": "A", "title": "递上果酱试图递台阶", "desc": "假装起夜什么都没看见，给羞耻的姐姐一个台阶"}, {"tag": "B", "title": "温顺为母亲吹干长发", "desc": "接过吹风机走到沙发旁，贴心为无防备的母亲吹头发"}, {"tag": "C", "title": "玩味调侃反客为主", "desc": "直勾勾盯着姐姐通红的耳根，用言语暗示昨夜风波"}, {"tag": "D", "title": "埋头扒粥暗中观察", "desc": "当安静透明人，静观超模姐姐与尤物母亲的日常拉扯"}]}]', '/* --- 核心修复：强制亮色模式 & 移动端重置 --- */
:root {
    color-scheme: light !important;
}
* {
    -webkit-tap-highlight-color: transparent !important;
    -webkit-touch-callout: none !important;
}
*:focus, *:active {
    outline: none !important;
    box-shadow: none !important;
}

/* --- 整体风格：云朵蓝莓 (Cloudy Blueberry) --- */

/* 1. 主容器：清新的蓝白渐变 */
.bg-gray-100\/90.relative.inline-block {
    background: linear-gradient(180deg, #E0F7FA 0%, #E6E6FA 100%) !important;
    border: 3px solid #B0E0E6 !important;
    border-radius: 20px !important;
    padding: 20px !important;
    margin: 10px auto !important;
    box-shadow: 0 8px 20px rgba(176, 224, 230, 0.5) !important;
}

/* 2. 文本区域：纯净白色 */
.markdown-body {
    background-color: #FFFFFF !important;
    color: #5F6368 !important;
    border-radius: 15px !important;
    padding: 15px !important;
    font-family: ''Nunito'', ''Segoe UI'', sans-serif !important;
    line-height: 1.7 !important;
    border: 1px solid #F0F8FF !important;
}

/* 3. 标题：天空蓝 */
.markdown-body h1, .markdown-body h2, .markdown-body h3 {
    color: #6495ED !important;
    border-bottom: 2px dashed #B0E0E6 !important;
    padding-bottom: 5px !important;
    margin-top: 1.2em !important;
}

/* --- 核心优化：状态栏 (Details) - 晨曦微光风格 --- */
details {
    /* 背景：极淡的云雾渐变，通透感 */
    background: linear-gradient(135deg, #F0F8FF 0%, #FFFFFF 100%) !important;
    /* 边框：天空蓝虚线，精致且不沉重 */
    border: 2px dashed #87CEEB !important;
    color: #5F6368 !important; /* 深灰字，保证阅读舒适 */
    border-radius: 16px !important; /* 更圆润的胶囊角 */
    margin: 15px 0 !important;
    padding: 12px 18px !important;
    box-shadow: 0 4px 12px rgba(135, 206, 235, 0.2) !important; /* 淡淡的蓝色光晕 */
    transition: all 0.3s ease !important;
}

/* 展开时的交互微调 */
details[open] {
    border-color: #6495ED !important; /* 展开后边框变深一点 */
    background: #F0F8FF !important;
}

/* 状态栏标题 (Summary) */
summary {
    color: #4682B4 !important; /* 钢蓝标题，优雅清晰 */
    font-weight: 700 !important;
    font-size: 1.05em !important;
    cursor: pointer !important;
    outline: none !important;
    list-style: none !important;
    padding: 5px 0 !important;
    letter-spacing: 0.5px !important;
}

summary::-webkit-details-marker {
    display: none !important;
}

/* 自定义图标：闪烁的星星 */
summary::before {
    content: ''✨ '' !important;
    margin-right: 8px !important;
    filter: drop-shadow(0 0 2px gold) !important;
}
details[open] summary::before {
    content: ''💫 '' !important;
}

/* 状态栏内的链接颜色适配（背景变亮，链接要深色） */
details a {
    color: #1E90FF !important; /* 闪避蓝 */
    text-decoration: none !important;
    border-bottom: 1px dotted #1E90FF !important;
}

/* 状态栏内的代码块适配 */
details code, details pre {
    background-color: #E6F2FF !important; /* 极淡蓝底 */
    color: #4682B4 !important; /* 钢蓝字 */
    border: 1px solid #D1E9FF !important;
}

/* --- 普通代码块 (非状态栏内) --- */
.markdown-body pre, .markdown-body code {
    background-color: #F0F8FF !important;
    color: #4682B4 !important;
    border-radius: 8px !important;
    font-family: Consolas, monospace !important;
    padding: 5px !important;
    border: 1px solid #B0C4DE !important;
    
    /* 手机端防黑边 */
    outline: none !important;
    box-shadow: none !important;
    white-space: pre-wrap !important;
    word-break: break-all !important;
}

/* --- 其他元素美化 --- */

/* 链接 */
.markdown-body a {
    color: #1E90FF !important;
    text-decoration: none !important;
    font-weight: 600 !important;
}

/* 列表 */
.markdown-body ul li::before {
    content: ''☁️ '' !important;
    margin-right: 5px !important;
}
.markdown-body ul {
    list-style: none !important;
    padding-left: 10px !important;
}

/* 按钮 */
.MuiButtonBase-root.MuiButton-root {
    background-color: #87CEEB !important;
    color: #FFFFFF !important;
    border-radius: 20px !important;
    font-weight: bold !important;
    box-shadow: 0 4px 6px rgba(135, 206, 235, 0.3) !important; /* 增加一点立体感 */
    border: none !important;
}
.MuiButtonBase-root.MuiButton-root:hover {
    background-color: #00BFFF !important;
    transform: translateY(-1px) !important; /* 悬停微动 */
}

/* 输入框 */
textarea, input[type="text"] {
    background: #FFFFFF !important; /* 纯白背景更干净 */
    border: 2px solid #E6E6FA !important;
    border-radius: 12px !important;
    color: #483D8B !important;
    padding: 12px !important;
    box-shadow: inset 0 2px 4px rgba(0,0,0,0.02) !important;
    -webkit-appearance: none !important;
}
textarea:focus, input[type="text"]:focus {
    border-color: #87CEEB !important;
    box-shadow: 0 0 0 3px rgba(135, 206, 235, 0.2) !important;
}

/* 隐藏顶部颜色条 */
[class*="bg-[#F1CBCB]"], [class*="bg-[#c9e1e9]"] {
    display: none !important;
}

/* === 强制清除移动端所有默认黑边/黑底 === */

input, textarea, select, button, pre, code {
    -webkit-appearance: none !important;
    -moz-appearance: none !important;
    appearance: none !important;
}

input, textarea, button, pre, code {
    background-color: #FFFFFF !important;
    background: #FFFFFF !important;
}

pre, code {
    color: #4682B4 !important;
    background-color: #F0F8FF !important;
    -webkit-text-fill-color: #4682B4 !important;
    -webkit-background-clip: padding-box !important;
}

:root {
    color-scheme: light !important;
}

button, [role="button"] {
    -webkit-tap-highlight-color: transparent !important;
    background-color: #87CEEB !important;
}

/* === 强制清除移动端代码块黑底 === */
pre,
code,
pre[class*="language-"],
code[class*="language-"],
.language-python,
.language-time,
.hljs {
    -webkit-appearance: none !important;
    -moz-appearance: none !important;
    appearance: none !important;
    background-color: #F0F8FF !important;
    color: #4682B4 !important;
    -webkit-text-fill-color: #4682B4 !important;
    -webkit-background-clip: padding-box !important;
    background-clip: padding-box !important;
    background: #F0F8FF !important;
    border: 1px solid #B0C4DE !important;
    outline: none !important;
    box-shadow: none !important;
}

div > pre,
.markdown-body > pre,
.markdown-body pre {
    background-color: #F0F8FF !important;
    background: #F0F8FF !important;
}', '<!DOCTYPE html>
<html lang="zh-CN">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width,initial-scale=1.0">
<title>模特姐姐与熟女妈妈</title>
<style>
@import url(''https://fonts.googleapis.com/css2%sfamily=Noto+Serif+SC:wght@400;700&family=Ma+Shan+Zheng&display=swap'');
#app-root{
  --rose:#e85b8a;
  --rose-soft:#f4a3bd;
  --peach:#ffd9c7;
