}
#app-root *{box-sizing:border-box;-webkit-tap-highlight-color:transparent;}
#app-root .wrap{max-width:52em;margin:0 auto;padding:1.1em .9em 5em;}
#app-root .hero{
  position:relative;
  text-align:center;
  padding:1.8em .8em 1.4em;
