        border-radius:24px;
        padding:28px 26px;
        margin-bottom:22px;
        box-shadow:var(--shadow-soft);
        border:1px solid #f2edfb;
    }
    .section-title{
        display:flex;
        align-items:center;
        gap:12px;
        font-size:18.5px;
        font-weight:700;
        color:#3a3350;
        margin:0 0 18px;
        letter-spacing:1px;
