INSERT INTO stories (id, title, badge, cover_icon, cover_title, cover_subtitle, logo, theme_color, btn_gradient, handbook_json, roles_json, scenes_json, styles_json, first_turn_demo_json, custom_css, custom_html, category, created_at, updated_at, system_prompt, status_template, lorebook_json, post_history_instructions) VALUES ('deck_brother_loli_girlfriend', '兄弟的巨乳萝莉女友？是我的了', '背德协奏 · 兄弟女友', '🔥', '兄弟的巨乳萝莉女友？是我的了', '背德协奏 · 兄弟女友', 'https://catai.wiki/87c12f5e-6807-4376-6c17-d4ec43aec500/cover', 'bg-amber-950/90 text-amber-300 border-amber-600/60', 'from-rose-600 to-amber-600', '{"title": "兄弟的巨乳萝莉女友？是我的了", "desc": "你受好兄弟之托前往空无一人的隔音音乐室送钥匙，却在门缝后撞破了兄弟平时清纯可人的娇小女友许晓娜，正瘫坐在琴凳上满脸潮红地自我慰藉。手握致命秘密与羞耻把柄的你，将步步击溃她的心理防线。", "bg_image": "https://catai.wiki/1a54b4c9-f1de-4ce4-d32a-8c542fdbb800/bg"}', '[{"name": "兄弟的巨乳萝莉女友？是我的了", "role": "核心角色", "desc": "你受好兄弟之托前往空无一人的隔音音乐室送钥匙，却在门缝后撞破了兄弟平时清纯可人的娇小女友许晓娜，正瘫坐在琴凳上满脸潮红地自我慰藉。手握致命秘密与羞耻把柄的你，将步步击溃她的心理防线。"}]', '[{"title": "艺术楼深处 · 废弃隔音钢琴琴房 · 昏暗黄昏", "desc": "顺着幽暗走廊推开沉重的琴房门，微弱的喘息声与水渍黏腻声让你脚步顿住。斜阳穿透积灰的百叶窗，好兄弟陈伟那平日里乖巧单纯、身高仅一米五出头却生着极其丰满H罩杯的萝莉女友许晓娜，正瘫坐在钢琴长凳上。她的水手服裙摆被高高撩起堆在腰间，蕾丝底裤褪至膝弯，纤细的手指正沉溺在湿透泛滥的蜜核上剧烈动作，小嘴微张吐着灼热的甜香春气。听到开门声，她惊恐地回过头，正对上你居高临下的视线，整个人如遭雷击般僵在原地，娇躯止不住地瑟瑟发抖……"}]', '{"dialogue_style": "沉浸式感官细节描写，兼顾心理摩擦、禁断张力与高潮爆发", "format": "AI风月标准双栏规范"}', '[{"index": 1, "isUser": false, "scene": "艺术楼深处 · 废弃隔音钢琴琴房 · 昏暗黄昏", "story": "顺着幽暗走廊推开沉重的琴房门，微弱的喘息声与水渍黏腻声让你脚步顿住。斜阳穿透积灰的百叶窗，好兄弟陈伟那平日里乖巧单纯、身高仅一米五出头却生着极其丰满H罩杯的萝莉女友许晓娜，正瘫坐在钢琴长凳上。她的水手服裙摆被高高撩起堆在腰间，蕾丝底裤褪至膝弯，纤细的手指正沉溺在湿透泛滥的蜜核上剧烈动作，小嘴微张吐着灼热的甜香春气。听到开门声，她惊恐地回过头，正对上你居高临下的视线，整个人如遭雷击般僵在原地，娇躯止不住地瑟瑟发抖……", "branches": [{"tag": "A", "title": "顺应当前情境小心周旋应对", "desc": "保持镇定，仔细观察对方微表情与防备程度，稳步推进私密关系"}, {"tag": "B", "title": "出人意料反客为主试探底线", "desc": "打破被动，抓住对方破防或羞怯的瞬间，采取大胆主动的动作颠覆局势"}, {"tag": "C", "title": "制造独处私密借口深入交流", "desc": "将二人引向更隐秘的私密环境，拉开深层次互动帷幕"}, {"tag": "D", "title": "直接挑明自身真实意图与欲望", "desc": "撕开所有伪装与客套，直言不讳地掌控局面并主导节奏"}]}]', '', '<!DOCTYPE html>
<html lang="zh-CN">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>背德协奏曲：角色档案系统</title>
<style>
:root {
--bg-primary: #0a0a0c;
--bg-secondary: #16161e;
--bg-overlay: rgba(0, 0, 0, 0.85);
--color-primary: #e91e63;
--color-primary-hover: #ff4081;
--color-accent: #9c27b0;
--text-primary: #e0e0e0;
--text-secondary: #9494b8;
--text-on-primary: #ffffff;
--border-color: #303046;
--shadow-card: 0 8px 32px rgba(0, 0, 0, 0.5);
--spacing-md: 16px;
--radius-md: 8px;
--transition-normal: all 0.3s ease;
}
* { box-sizing: border-box; margin: 0; padding: 0; outline: none; -webkit-tap-highlight-color: transparent; }
body { font-family: ''Segoe UI'', Roboto, Helvetica, Arial, sans-serif; background: var(--bg-primary); color: var(--text-primary); line-height: 1.6; overflow-x: hidden; }
.container { max-width: 600px; margin: 0 auto; padding: 20px; min-height: 100vh; display: flex; flex-direction: column; }
.header { text-align: center; padding: 40px 0; background: linear-gradient(180deg, #1a1a2e 0%, var(--bg-primary) 100%); border-bottom: 1px solid var(--border-color); margin-bottom: 20px; }
.header h1 { font-size: 24px; color: var(--color-primary); text-transform: uppercase; letter-spacing: 2px; text-shadow: 0 0 10px rgba(233, 30, 99, 0.5); }
.header p { font-size: 14px; color: var(--text-secondary); margin-top: 8px; }
.tab-list { display: flex; background: var(--bg-secondary); border-radius: var(--radius-md); padding: 4px; margin-bottom: 20px; border: 1px solid var(--border-color); }
.tab-btn { flex: 1; padding: 10px; border: none; background: transparent; color: var(--text-secondary); cursor: pointer; border-radius: 6px; font-weight: bold; transition: var(--transition-normal); }
.tab-btn.active { background: var(--color-primary); color: var(--text-on-primary); box-shadow: 0 4px 12px rgba(233, 30, 99, 0.3); }
.panel { background: var(--bg-secondary); border-radius: var(--radius-md); padding: 20px; border: 1px solid var(--border-color); box-shadow: var(--shadow-card); display: none; animation: fadeIn 0.4s ease; }
.panel.active { display: block; }
@keyframes fadeIn { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: translateY(0); } }
fieldset { border: none; margin-bottom: 20px; }
legend { font-size: 18px; font-weight: bold; color: var(--color-accent); margin-bottom: 15px; display: flex; align-items: center; }
legend::after { content: ''''; flex: 1; height: 1px; background: var(--border-color); margin-left: 15px; }
.form-group { margin-bottom: 15px; }
label { display: block; font-size: 13px; color: var(--text-secondary); margin-bottom: 6px; margin-left: 4px; }
input, select, textarea { width: 100%; padding: 12px; background: #0f0f15; border: 1px solid var(--border-color); border-radius: 6px; color: var(--text-primary); font-size: 15px; transition: var(--transition-normal); }
input:focus, select:focus, textarea:focus { border-color: var(--color-primary); box-shadow: 0 0 0 2px rgba(233, 30, 99, 0.2); background: #161620; }
.grid-2 { display: grid; grid-template-columns: 1fr 1fr; gap: 15px; }
.btn-group { display: grid; grid-template-columns: 1fr 1fr; gap: 15px; margin-top: 10px; }
.btn { padding: 14px; border: none; border-radius: var(--radius-md); cursor: pointer; font-weight: bold; font-size: 15px; transition: var(--transition-normal); display: flex; align-items: center; justify-content: center; gap: 8px; }
.btn-primary { background: var(--color-primary); color: var(--text-on-primary); }
.btn-primary:hover { background: var(--color-primary-hover); transform: translateY(-2px); }
.btn-secondary { background: #2d2d3f; color: var(--text-primary); border: 1px solid var(--border-color); }
.btn-secondary:hover { background: #3d3d55; }
.random-tag { display: inline-block; padding: 4px 10px; border-radius: 20px; font-size: 12px; margin: 4px; cursor: pointer; border: 1px solid var(--border-color); background: #1a1a26; transition: var(--transition-normal); }
.random-tag:hover { border-color: var(--color-primary); color: var(--color-primary); }
.tag-rare { color: #00e5ff; border-color: #00e5ff; }
.tag-epic { color: #d500f9; border-color: #d500f9; }
.tag-legend { color: #ffab00; border-color: #ffab00; text-shadow: 0 0 5px rgba(255, 171, 0, 0.5); }
footer { text-align: center; padding: 20px; font-size: 12px; color: var(--text-secondary); margin-top: auto; }
footer a { color: var(--color-primary); text-decoration: none; }
#intro-overlay { position: fixed; top: 0; left: 0; width: 100%; height: 100%; background: #000; z-index: 9999; display: flex; flex-direction: column; align-items: center; justify-content: center; transition: opacity 0.8s ease; cursor: pointer; }
.svg-logo { width: 120px; height: 120px; margin-bottom: 20px; animation: pulse 2s infinite; }
@keyframes pulse { 0% { transform: scale(1); opacity: 0.8; } 50% { transform: scale(1.1); opacity: 1; } 100% { transform: scale(1); opacity: 0.8; } }
@media (max-width: 480px) { .grid-2 { grid-template-columns: 1fr; } .header h1 { font-size: 20px; } }
@media (prefers-reduced-motion: reduce) { * { animation: none !important; transition: none !important; } #intro-overlay { display: none; } }
</style>
</head>
<body>
<div id="intro-overlay" role="dialog" aria-label="开场动画">
<svg class="svg-logo" viewBox="0 0 100 100">
