INSERT INTO plaza_cards (id, deck_id, title, badge, badge_color, author, "desc", rating, tags_json, heat, order_index, cover_image, image_tag, badge_type, is_featured, category, created_at) VALUES ('deck_eri_summer', NULL, '夏蝉之骨 · 白石绘梨', '缘之空风格 · 纯文学私小说', 'bg-amber-500/20 text-amber-300 border border-amber-500/40', '深町秋生 · 纯文学组', '午后两点，无休无止的蝉鸣几乎撕裂空气。绘梨蜷缩在风扇边，穿着你高中的宽松白T恤，微凉的脚趾轻轻抵在你的膝侧。', '9.9', '["缘之空风味", "病态共生", "纯爱私小说", "纤细病娇", "夏日老宅"]', '3820.5 亿', 12, '/assets/characters/eri_standing.jpg', '日系缘之空·夏日孤宅', 'exclusive', 1, '都市', '2026-09-13 09:16:35') ON CONFLICT (title) DO NOTHING;
