INSERT INTO plaza_cards (id, deck_id, title, badge, badge_color, author, "desc", rating, tags_json, heat, order_index, cover_image, image_tag, badge_type, is_featured, category, created_at) VALUES ('harumi', NULL, '(纯爱肉卡) 爆操反差婊小学妹！', '纯爱肉卡 · 反差优等生', 'bg-amber-500/20 text-amber-300 border border-amber-500/40', '校园观察员', '青叶台高中的走廊尽头旧图书室。全班最优秀的晴海小晴，在书架后看羞耻内容被你当场撞破，惊慌失措下把你按在书架上威吓……', '9.5', '["反差学妹", "优等生", "多面性格", "校园私密"]', '2780.0 亿', 21, 'https://images.unsplash.com/photo-1534528741775-53994a69daeb%sw=800&q=80', '反差优等生', 'exclusive', 1, '都市', '2026-09-13 09:16:35') ON CONFLICT (title) DO NOTHING;
INSERT INTO plaza_cards (id, deck_id, title, badge, badge_color, author, "desc", rating, tags_json, heat, order_index, cover_image, image_tag, badge_type, is_featured, category, created_at) VALUES ('novel', NULL, '雪夜共生 · 悠月与哥哥', '日系轻小说 · 禁断', 'bg-amber-500/20 text-amber-300 border border-amber-500/40', '悠月书屋', '深夜暴雨，书房门虚掩。悠月穿着微敞的制服白衬衫，坐在哥哥大腿上问微积分，追问口袋里硬硬的是什么……', '9.5', '["雪夜共生", "悠月与哥哥", "日系轻小说", "禁断"]', '1940.8 亿', 19, 'https://images.unsplash.com/photo-1517816743773-6e0fd518b4a6%sw=800&q=80', '日系轻小说·雪夜禁断', 'exclusive', 1, '都市', '2026-09-13 09:16:35') ON CONFLICT (title) DO NOTHING;
