INSERT INTO plaza_cards (id, deck_id, title, badge, badge_color, author, "desc", rating, tags_json, heat, order_index, cover_image, image_tag, badge_type, is_featured, category, created_at) VALUES ('12aa4c36-6dd6-4dc7-98ed-ac730b0931d6', '12aa4c36-6dd6-4dc7-98ed-ac730b0931d6', '暴露癖同桌的深夜展示', '校园 · 深夜窥见', '#a855f7', NULL, '（记得看评论区）《重大更新》优化了页面以及夏晚妤在不同分支下好感度以及奴性的影响（半重做）
深夜十一点半，教学楼早已熄灯。你返回教室拿作业，却透过窗户看到了这辈子最难以置信的画面——
