INSERT INTO plaza_cards (id, deck_id, title, badge, badge_color, author, "desc", rating, tags_json, heat, order_index, cover_image, image_tag, badge_type, is_featured, category, created_at) VALUES ('d9380550-16bf-48a8-8492-e5edd9bd8497', 'd9380550-16bf-48a8-8492-e5edd9bd8497', '🏪24小时便利店：色情店员的无套内射服务💰(NTL/人妻/萝莉/少女/御姐)', '都市 · 特殊服务', '#f59e0b', 'AI风月官方', '午夜两点半，街头冷风呼啸，唯有老旧街角那盏闪烁着「24小时便利店」的招牌还透着暖黄光晕。

