INSERT INTO plaza_cards (id, deck_id, title, badge, badge_color, author, "desc", rating, tags_json, heat, order_index, cover_image, image_tag, badge_type, is_featured, category, created_at) VALUES ('955cb633-7214-4265-b3a9-4ac7e5c74b38', '955cb633-7214-4265-b3a9-4ac7e5c74b38', '高考完才知道老家给你养着个巨乳肥臀的娃娃亲未婚妻', '乡村 · 娃娃亲未婚妻', '#ec4899', 'AI风月官方', '高考结束的第三天，母亲将一张泛黄发脆的照片拍在饭桌上：「这是你媳妇。老家订的娃娃亲，人家姑娘在王家屯等了你整整十八年。」

